const SYSTEM_ID = 'sr2e';

/**
 * Adapter between the pure rules engine and Foundry's dice: every wave the engine
 * asks for is a real Foundry Roll, collected so the chat message can show them all
 * (and Dice So Nice animates them).
 */
function foundryRoller(sink: any[]): DiceRoller {
  return async (count: number) => {
    const roll = await new Roll(`${count}d6`).evaluate();
    // Dice So Nice (v0.41.0): the SR2e colour set, Rule of Six re-rolls (later waves) in gold.
    if (dsnColoursOn()) {
      const colorset = dsnColorsetFor(sink.length);
      for (const term of roll.dice ?? []) term.options = { ...(term.options ?? {}), colorset, appearance: { ...(term.options?.appearance ?? {}), colorset } };
    }
    sink.push(roll);
    return roll.dice[0].results.map((r: any) => r.result as number);
  };
}

/** v0.50.0: text for chat HTML (labels carry item and actor names). v0.81.0: the shared `escHtml` (rules/html.ts). */
const escText = escHtml;

/**
 * v0.81.0: text for element content only (a card title): `escHtml`, with the quotes left as they are (they can't
 * end an element's content, and "Shaman's" reads better in the card's source). Never use it inside an attribute.
 */
function escContent(t: unknown): string {
  return escHtml(t).replace(/&#39;/g, "'").replace(/&quot;/g, '"');
}

/**
 * v0.81.0 (security): whether a user (a card's author, from the server-set `message.author`) is a GM or owns `doc`.
 * The methods that apply a change from a card take that author and check it here (defense in depth: the chat
 * handlers check it too). rules/trust.ts `userOwns`, for a real User only (never an object from data that merely
 * says isGM).
 */
function userOwns(user: any, doc: any): boolean {
  return realUser(user) && trustUserOwns(user, doc);
}

/** A real User of this world (when the world's user list can tell), not an object from data. */
function realUser(user: any): boolean {
  if (!user) return false;
  const users: any = (game as any)?.users;
  return typeof users?.get !== 'function' || users.get(user.id) === user;
}

/**
 * v0.81.1 (SEC1-1, design 1): the card author a GM-side re-resolution acts for. Set only by `SR2Actor.runAsAuthor`
 * while it runs a player's card again on the GM's client (Change target number, Karma re-roll, Buy success, Avoid
 * disaster, Use again, Send ritual, Offer to grimoire). While set, the resolvers decide "write directly or post an
 * Apply (GM) card" by what that author owns, not by the GM's own rights. Null otherwise.
 */
let actingAuthor: any = null;

/**
 * v0.81.1: whether this resolution may write `doc` directly: the acting author owns it, or (no acting author) this
 * client's user does. Write-or-card routing only; pure UI checks keep `isOwner`.
 */
function canWriteNow(doc: any): boolean {
  if (!doc) return false;
  return actingAuthor ? userOwns(actingAuthor, doc) : Boolean(doc.isOwner);
}

/** v0.81.1: whether this resolution runs with GM authority (the acting author's, else this client's user's). */
function isGmNow(): boolean {
  return actingAuthor ? realGm(actingAuthor) : Boolean((game as any)?.user?.isGM);
}

/** v0.81.1: `doc.isOwner === false` for the acting author (an object with no `isOwner` counts as writable, as before). */
function notWritableNow(doc: any): boolean {
  if (!doc) return false;
  return actingAuthor ? !userOwns(actingAuthor, doc) : doc.isOwner === false;
}

/** v0.81.1: whether this resolution may create an actor (a GM, or a user with ACTOR_CREATE). */
function canCreateActorNow(): boolean {
  const u: any = actingAuthor ?? (game as any)?.user;
  if (actingAuthor ? realGm(u) : Boolean(u?.isGM)) return true;
  try { return Boolean(u?.can?.('ACTOR_CREATE')); } catch { return false; }
}

/**
 * v0.81.1 (SEC1-1/SEC1-5): while acting as a player, a write this client starts on a document that player doesn't
 * own is refused, as Foundry refuses it on the player's own client; a chat card it posts carries the player as
 * author. Pure: the hook bodies registerActingAuthorHooks installs. `op` is 'create' (with `parent`), 'update' or
 * 'delete'. Returns false to cancel the operation.
 */
export function actingMayWrite(doc: any, op: 'create' | 'update' | 'delete', documentName: string, userId: string): boolean {
  if (!actingAuthor || userId !== (game as any)?.user?.id) return true;
  if (realGm(actingAuthor)) return true;
  if (op === 'create') {
    if (documentName === 'ChatMessage') return true;
    const parent = doc?.parent ?? null;
    if (parent) return userOwns(actingAuthor, parent);
    if (documentName === 'Actor' || documentName === 'Item') {
      try { return Boolean(actingAuthor.can?.(`${documentName.toUpperCase()}_CREATE`)); } catch { return false; }
    }
    return false;
  }
  return userOwns(actingAuthor, doc);
}

/** v0.81.1: a chat card created while acting as a player is authored by that player (never by the GM's client). */
export function actingAuthorFor(data: any, userId: string): string | null {
  if (!actingAuthor || userId !== (game as any)?.user?.id || realGm(actingAuthor)) return null;
  const cur = data?.author?.id ?? data?.author ?? data?.user?.id ?? data?.user ?? null;
  return !cur || cur === (game as any)?.user?.id ? String(actingAuthor.id) : null;
}

/**
 * v0.81.1 round 2 (FIX2-BRIEF A4): a write the acting-author guard cancels is never silent: the GM is told which
 * document and why. Returns false (the hook's "cancel").
 */
export function actingRefused(doc: any, documentName: string): false {
  const who = escText(String(actingAuthor?.name ?? tx('SR2E.Card.Actor.aPlayer')));
  const what = escText(String(doc?.name ?? documentName));
  ui.notifications?.warn?.(tx('SR2E.Notify.Actor.notChangedIsnTSAnd', { what, who }));
  return false;
}

/** The document kinds whose writes the acting-author guard covers. */
const ACTING_GUARDED = ['Actor', 'Item', 'ActiveEffect', 'Token', 'Scene', 'Combat', 'Combatant', 'ChatMessage', 'Region', 'Wall', 'Tile', 'Drawing', 'MeasuredTemplate', 'AmbientLight', 'AmbientSound', 'Note', 'JournalEntry', 'JournalEntryPage', 'Macro', 'RollTable', 'Folder', 'Playlist', 'Cards', 'User', 'Setting'];

/**
 * v0.81.1 (SEC1-1, design 1): the backstop for `runAsAuthor`. A resolver that writes another document without a
 * `canWriteNow` check (it relies on Foundry refusing it for a player) is refused here too while a GM re-runs a
 * player's card. Concurrency: the acting author is module-wide while the re-run awaits, so a GM write started at
 * that moment from another handler is checked against the player too (refused, never widened).
 */
export function registerActingAuthorHooks(): void {
  for (const name of ACTING_GUARDED) {
    Hooks.on(`preCreate${name}`, (doc: any, data: any, o: any, userId: string) => {
      if (name === 'ChatMessage') {
        const a = actingAuthorFor(data, userId);
        if (a) { try { doc.updateSource?.({ author: a }); } catch { /* older core */ } }
        return true;
      }
      return o?.sr2eRelay || actingMayWrite(doc, 'create', name, userId) ? undefined : actingRefused(doc?.parent ?? doc, name);
    });
    // Round 3 (V2 #14): a write a relay handler marks `sr2eRelay` (run inline in a re-run, after judging the request as
    // the player) is the relay's own and goes through.
    Hooks.on(`preUpdate${name}`, (doc: any, _c: any, o: any, userId: string) => (o?.sr2eRelay || actingMayWrite(doc, 'update', name, userId) ? undefined : actingRefused(doc, name)));
    Hooks.on(`preDelete${name}`, (doc: any, o: any, userId: string) => (o?.sr2eRelay || actingMayWrite(doc, 'delete', name, userId) ? undefined : actingRefused(doc, name)));
  }
}

/** A real User who is a GM. */
function realGm(user: any): boolean {
  return realUser(user) && Boolean(user.isGM);
}

/** v0.81.0 (SEC1-1): an Actor document (a uuid from a card can name a User, a Macro, a Scene...). */
function isActorDoc(a: any): boolean {
  return a instanceof SR2Actor || a?.documentName === 'Actor';
}

/**
 * Round 2 (V-DOC 10, FIX2-BRIEF H6): the highest background count a scene or region holds (regions.ts clamps it to
 * 20; the Apply (GM) cleanse card's bound is the same), so a cleansing never lowers it by more.
 */
const MAX_BACKGROUND_COUNT = 20;

/** The most hourly radiation tests one exposure rolls at once (the rest are noted on a card). */
const RADIATION_TESTS_PER_CALL = 24;

/** v0.81.0: the most dice one test may roll (a forged snapshot can't ask for 100,000). */
const MAX_TEST_DICE = 200;

/**
 * A test card's body. `label` is plain text (names, typed text): it is escaped here, once (v0.81.0), so callers
 * pass it raw and never pre-escape it.
 */
function describeResult(label: string, r: SuccessTestResult): string {
  const mods = escText(r.modifiers.map((m) => `${m.label} ${m.value >= 0 ? '+' : ''}${m.value}`).join(', '));
  const dice = r.dice
    .map((d) => `<span class="sr2e-die ${d.success ? 'hit' : 'miss'}">${escText(d.faces.join('+'))}${d.faces.length > 1 ? `=${d.total}` : ''}</span>`)
    .join(' ');
  const outcome = r.botch
    ? `<strong class="sr2e-botch">${tx('SR2E.Card.Actor.disasterEveryDieIsA1')}</strong>`
    : `<strong>${tCount(r.successes, 'SR2E.Card.Actor.successes')}</strong>`;
  // v0.35.0: the dice fold away (click to open); the TN's breakdown shows on hover.
  const breakdown = tx('SR2E.Card.Actor.base', { baseTargetNumber: r.baseTargetNumber, part: mods ? `; ${mods}` : '', part2: r.targetNumberClamped ? tx('SR2E.Card.Actor.tnMinimum2') : '' });
  // v0.67.0: the big success count under the title (the look's chat cards).
  const count = r.botch
    ? `<div class="sr2e-count sr2e-count-botch"><b>✕</b><span>${tx('SR2E.Card.Actor.disaster')}</span></div>`
    : `<div class="sr2e-count"><b>${r.successes}</b><span>${tCount(r.successes, 'SR2E.Card.Actor.successes2')}</span></div>`;
  return `<div class="sr2e-roll">
    <h3>${escContent(label)}</h3>
    ${count}
    <details class="sr2e-fold"><summary title="${tx('SR2E.Card.Actor.tn', { breakdown })}">${tx('SR2E.Card.Actor.diceVsTn', { totalDice: r.totalDice })} <strong>${r.targetNumber}</strong><span class="sr2e-sum-out"> · ${outcome}</span></summary>
    ${mods || r.targetNumberClamped ? `<p class="sr2e-breakdown"><em>${breakdown}</em></p>` : ''}
    <p class="sr2e-dice">${dice || `<em>${tx('SR2E.Card.Actor.noDice')}</em>`}</p></details>
  </div>`;
}

/**
 * The outcome banner at the top of a test card (v0.35.0): Hit, Miss, Counterattack, Disaster,
 * Resisted, Takes X, or the plain success count.
 */
function outcomeBanner(snap: { kind: string; botch: boolean; disasterAvoided?: boolean; successes: number }, html: string): string {
  const b = (cls: string, text: string) => `<div class="sr2e-banner sr2e-banner-${cls}">${text}</div>`;
  if (snap.botch && !snap.disasterAvoided) return b('disaster', tx('SR2E.Card.Actor.disaster2'));
  // v0.89.5: the outcome words are found by their ids (outcomeWord, takenMark), never by their text: the html is the
  // card being built now, in this client's language.
  const has = (id: OutcomeId) => html.includes(`data-sr2e-outcome="${id}"`);
  if (has('counter')) return b('counter', tx('SR2E.Card.Actor.counterattack'));
  // v0.74.0: coloured for whoever rolled: on a defense card a hit is bad for the defender, a miss good ('dodged').
  if (has('hit')) return b('hit', tx('SR2E.Card.Actor.hit'));
  if (has('missed')) return b(snap.kind === 'attack' ? 'miss' : 'dodged', tx('SR2E.Card.Actor.miss'));
  if (snap.kind === 'soak') {
    const m = /data-sr2e-taken="([LMSD])" data-sr2e-track="(physical|stun|matrix|vehicle)"/.exec(html);
    if (m) return b('taken', tKey(TAKEN_BANNER[m[2] as TakenTrack], { level: m[1] }));
    if (has('fullyResisted') || has('noDrain') || has('resisted') || has('cleanMiss')) return b('ok', tx('SR2E.Card.Actor.resisted'));
  }
  if (snap.kind === 'attack') return snap.successes > 0 ? b('neutral', tCount(snap.successes, 'SR2E.Card.Actor.successes')) : b('miss', tx('SR2E.Card.Actor.miss'));
  return snap.successes > 0 ? b('ok', tx('SR2E.Card.Actor.success', { successes: snap.successes })) : b('miss', tx('SR2E.Card.Actor.failed'));
}

/**
 * Foundry's roll mode (public, GM only, blind, self) on a card (v0.36.0). Cards someone else must
 * answer (Defend, Resist, a blast to detonate) stay public, or the other player would never see them.
 */
export function withRollMode(data: any): any {
  const content = String(data?.content ?? '');
  // v0.81.0 (D1-9): also the buttons another player presses (the attacker's whip check on a defender's card, the
  // patient's rejection test on the surgeon's, a rammer's own damage, a rigger's shock, catching fire, an element's effect).
  if (/data-sr2e-action="(defend|resist|resistSpell|resistToxin|blastScatter|createSpirit|morale|whipCheck|rejectionTest|ramSelf|riggerShock|catchFire|elementEffect)"/.test(content) || data?.whisper?.length) return data;
  const CM: any = ChatMessage;
  // v0.60.0: the user's own default for this kind of test (client setting rollPrivacy), else Foundry's chat mode.
  const kind = String(data?.flags?.[SYSTEM_ID]?.test?.kind ?? data?.flags?.[SYSTEM_ID]?.privacyKind ?? '');
  let prefs: Record<string, string> = {};
  try { prefs = (game.settings.get(SYSTEM_ID, 'rollPrivacy') ?? {}) as Record<string, string>; } catch { /* not registered */ }
  // Foundry v14: core.messageMode (public, gm, blind, self, ic) and ChatMessage.applyMode.
  if (typeof CM.applyMode === 'function') {
    let mode = 'public';
    try { mode = String(game.settings.get('core', 'messageMode') ?? 'public'); } catch { /* no setting */ }
    mode = privacyFor(kind, prefs, mode);
    if (mode === 'public' || mode === 'ic') return data;
    const d = { ...data };
    return CM.applyMode(d, mode) ?? d;
  }
  let mode = 'publicroll';
  try { mode = String(game.settings.get('core', 'rollMode') ?? 'publicroll'); } catch { /* no setting */ }
  const own = privacyFor(kind, prefs, '');
  if (own) mode = legacyRollMode(own);
  if (mode === 'publicroll' || typeof CM.applyRollMode !== 'function') return data;
  return CM.applyRollMode({ ...data }, mode) ?? data;
}

export type PoolKind = 'combat' | 'spell' | 'hacking' | 'control' | 'task';

export interface TestOptions {
  label?: string;
  /** v0.92.0 (RULES.MAGIC_V920.poolLayers): the Spell Pool's narrow layers this action falls inside. */
  spellUse?: SorceryUse;
  targetNumber?: number;
  /** Dice to add from a dice pool (capped at what is left). */
  poolDice?: number;
  /** Which pool `poolDice` comes from. Defaults to the Combat Pool. */
  pool?: PoolKind;
  /** v0.80.0 (RULES.URR_V80.coreKarmaDice): extra dice bought from the Karma Pool (ignored in the book). */
  karmaDice?: number;
  modifiers?: TargetNumberModifier[];
  /** A magical test (Sorcery, Conjuring): centering can cancel wound and sustaining penalties. */
  magical?: boolean;
  /** Affected by the scene's background count (magical tests always are). */
  background?: boolean;
  /** Not this actor's own effort (a frame's test): no wound or sustaining penalties. */
  noPenalties?: boolean;
  /** An act on the astral plane (cleansing, v0.45.0): no astral perception penalty, no background count. */
  astralAct?: boolean;
  /** v0.50.0: a Matrix test: the meat body's Blinded and astral perception don't count (RULES.TN_AUTO.matrix). */
  matrix?: boolean;
  /** v0.50.0: a driving, gunnery or sensor test: a jumped-in rigger's body statuses don't count (RULES.TN_AUTO.rigging). */
  vehicle?: boolean;
  /** v0.50.0: sight is already in the modifiers (perception): no separate Blinded. */
  sightHandled?: boolean;
  /** v0.50.0: labels of modifiers the player or GM switched off in the dialog's preview (found-by-itself ones). */
  exclude?: string[];
}

/** State carried on an attack chat card so the defender can respond. */
export interface AttackState {
  /** v0.80.0 (URR_V80.vehDamage): how a hit on a vehicle came about (weapon base Power, a spell, an impact). */
  vehHit?: Veh80Hit;
  /** v0.80.0: the defender is on full defense (the Revamp's clean-miss flow allows a melee clean miss only then). */
  fullDefense80?: boolean;
  /** v0.78.0: the Power a barrier takes from this attack (before burst or full-auto fire; RULES.BOOK_V78.barriers). */
  barrierPower?: number;
  /** v0.72.0 (O3): a spirit's or dual-natured critter's attack (immunity doesn't stop it outright). */
  awakenedAttacker?: boolean;
  attackerUuid: string;
  targetUuid: string;
  weaponName: string;
  melee: boolean;
  damageType: DamageType;
  power: number;
  level: DamageLevel;
  attackSuccesses: number;
  /** Final TN the attacker rolled against; the defender's dodge uses the same TN. */
  targetNumber: number;
  /** An astral attack: dodged with astral Quickness, soaked with astral Body, no armor. */
  astral?: boolean;
  /** v0.56.0: an adept's distance strike: not opposed (dodged like a ranged attack). */
  distance?: boolean;
  /** Cybercombat: no dodge; the target resists straight away (persona Bod, IC rating). */
  matrix?: boolean;
  /** Black IC: damages the decker's own Physical/Stun track. */
  black?: boolean;
  /** An elemental manipulation spell: soaked with part of the target's armor. */
  elemental?: boolean;
  /** No dodge step: the target resists straight away. */
  noDodge?: boolean;
  /** A magical weapon: immunity to normal weapons does not count. */
  ignoreImmunity?: boolean;
  /** Melee: the attacker's weapon reach (opposed melee compares it with the defender's). */
  reach?: number;
  /** Ammunition and called shots: how much armor counts, which kind, or none at all. */
  armorMultiplier?: number;
  armorKind?: 'ballistic' | 'impact';
  ignoreArmor?: boolean;
  /** v0.79.0 (RULES.DOCS_V79.rangedFlechette 'armor', SRII p. 93): flechette rounds; the soak decides the extra level and the armor. */
  flechette?: boolean;
  /** Blast weapons: the damage is set per target; successes do not stage it. */
  fixedDamage?: boolean;
  /** Barriers shot through: their rating adds to the target's armor. */
  extraArmor?: number;
  /** An anti-vehicle weapon: full damage against vehicles. */
  antiVehicle?: boolean;
  /** v0.73.0 (O25): a ram: the rammer's share, offered after the defense. */
  ram?: { vehicleUuid: string; power: number; level: DamageLevel | null; bodyPerSuccess?: number };
  /** A flamethrower (v0.37.0): a hit can set the target on fire. */
  flame?: boolean;
  /** An elemental manipulation's secondary effect and the spell's Force (v0.39.0). */
  elementEffect?: ElementEffect;
  spellForce?: number;
  /** What the weapon is made of (silver, wood...), for critter vulnerabilities and allergies (v0.39.0). */
  material?: string;
  /** v0.43.0: a called shot at this limb location (cyberlimb armor, cyberware damage). */
  calledLocation?: string;
  /** v0.48.0: a bite that passes on a disease (a critter's Infection power). */
  infection?: InfectionState;
  /** v0.55.0: a toxin the weapon delivers on a hit; the target didn't know it was coming (no dodge, no pool); suppressive fire. */
  toxinHit?: ToxinHit; unaware?: boolean; suppressive?: boolean;
  /** An IC's action (v0.27.0): what it does on a hit. */
  ic?: IcAction;
  /** v0.57.0: a called shot at part of a vehicle; an occupant shot through it (and the vehicle's armor that counts). */
  vehiclePart?: string; vehicleWeaponId?: string; occupantUuid?: string; occupantArmor?: number;
  /** v0.61.0: a weapon that can hit its wielder (monowhip); who holds superior position in this melee. */
  selfHit?: boolean; superior?: 'attacker' | 'defender';
  /** v0.78.0: the self-hit weapon's skill, for the wielder's check after a defended miss (COMBAT_V61.monowhip 'defended'). */
  selfHitSkill?: string;
}

/** v0.55.0: a toxin a weapon delivers on a hit (a dart, capsule round, poisoned blade). */
export type ToxinHit = { name: string; vector: string; power: number; level: DamageLevel; damageType: DamageType; kind?: string; from: string; needsWound: boolean;
  speed?: string; effect?: string; incubationHours?: number; intervalHours?: number; recoveries?: number; contagious?: string };
/** v0.48.0: the disease a bite passes on (RULES.CRITTERS.infection). */
export type InfectionState = ReturnType<typeof infectionFrom> & { from: string };

/** An IC acting on a persona: what it does when it hits (RULES.MATRIX.icAttackTn). */
export interface IcAction {
  behavior: IcBehavior;
  icUuid: string;
  icName: string;
  rating: number;
  /** Crippler and ripper: the persona program. */
  attribute?: string;
  /** Tar baby and tar pit: the utility (program item id on the target). */
  programId?: string;
  programName?: string;
  traceMode?: string;
  hostUuid?: string;
  /** Psychotropic IC (v0.40.0): what it does to the decker's mind. */
  payload?: string;
}

/** Options for driving tests, rams and chase positioning. */
export interface DriveOptions {
  vehicle?: any; terrain?: string; situational?: string[]; offroad?: boolean; poolDice?: number; modifiers?: TargetNumberModifier[];
  crashTest?: boolean; label?: string; useSpecialization?: boolean; relatedSkillId?: string | null;
  /** v0.48.0: false leaves the scene's weather out (a covered place). */
  weather?: boolean;
  /** v0.50.0: labels of found-by-themselves modifiers switched off in the dialog. */
  exclude?: string[];
  /** v0.50.0: no warnings (a dialog's preview). */
  quiet?: boolean;
  /** v0.57.0: a push to this speed (beyond the Combat Turn's Acceleration). */
  push?: number;
  /** v0.92.3: the kind of vehicle test (rigger 2's tables differ; default by crashTest / push, else a Driving Test). */
  kind?: DriveKind;
}

/** Options for SR2Actor.attackWith / planAttack / previewAttack. */
export interface AttackOptions {
  targetUuid?: string | null; range?: RangeBand; modifiers?: TargetNumberModifier[]; poolDice?: number;
  /** Ranged only. Falls back to the weapon's first mode if not one it has. */
  mode?: FiringMode; fullAutoRounds?: number; earlierRoundsThisPhase?: number;
  /** Ids from RULES.SITUATIONAL_MODIFIERS, and a RULES.VISIBILITY id (or an explicit visibility modifier). */
  situational?: string[]; visibility?: string;
  /**
   * v0.50.0: what the attacker sees, as the Attack dialog worked it out (light or blind fire, smoke, the
   * target's concealment). Left out, it is read from the tokens by itself (with partial cover and prone),
   * and either way Blinded, blind fire and weather don't double up (RULES.TN_AUTO.attack).
   */
  sight?: { light?: TargetNumberModifier | null; blindFire?: TargetNumberModifier | null; smoke?: TargetNumberModifier | null; concealment?: TargetNumberModifier | null };
  /** v0.50.0: labels of found-by-themselves modifiers switched off in the dialog. */
  exclude?: string[];
  /** Roll the skill's specialization; or, without the skill, default to this related skill item. */
  useSpecialization?: boolean; relatedSkillId?: string | null;
  /** v0.38.0: roll the skill's concentration. */
  useConcentration?: boolean;
  /** Distance measured on the canvas, in metres, shown on the card; `outOfRange` notes an override. */
  measuredMetres?: number; outOfRange?: boolean;
  /** v0.61.0: melee: who holds superior position (COMBAT_V61.superiorPosition, off by default). */
  superior?: '' | 'attacker' | 'defender';
  /** v0.56.0: an unarmed strike past arm's length by an adept's distance strike. */
  distanceStrike?: boolean;
  /** Called shot effect (adds the called-shot TN unless 'none'). */
  calledShot?: CalledShotEffect;
  /** v0.57.0: a called shot at part of a target vehicle (RULES.VEHICLES_V57.calledShots), the occupant aimed at, the weapon mount aimed at. */
  vehiclePart?: string; occupantUuid?: string | null; vehicleWeaponId?: string | null;
  /** Ammunition id (RULES.COMBAT.ammo); defaults to the weapon's loaded type. */
  ammoType?: string;
  /** Full auto spread over several targets: rounds fired at this one, and how many other targets. */
  rounds?: number; spreadExtraTargets?: number;
  /** Rounds wasted walking fire to this target: they use ammo and add recoil, but no damage. */
  wastedRounds?: number;
  /** Several targets with their own Power (shotgun spread, blasts). Replaces targetUuid. */
  hits?: Array<{ targetUuid: string; power?: number; powerDelta?: number; level?: DamageLevel }>;
  /** Blast weapons: where it lands (pixels, elevation in scene units), for scatter. */
  blastPoint?: { x: number; y: number; elevation: number } | null;
  /** Extra note for the card title (e.g. a shotgun's spread). */
  note?: string;
  /** Melee: the target's longest reach (the attacker's reach advantage lowers their TN). */
  targetReach?: number;
  /** Melee: subdue (Stun damage). */
  subdue?: boolean;
  /** v0.80.0 (URR_V80.cbtChargePower): a charging melee attack's extra Power. */
  chargePower80?: number;
  /** v0.55.0: the target doesn't know it is coming (no dodge, no Combat Pool); suppressive fire (base damage, cover saves). */
  unaware?: boolean; suppressive?: boolean;
  /** Rating of barriers shot through (adds to the target's armor). */
  barrierArmor?: number;
  /** A vehicle-mounted weapon: the vehicle and who fires it (driver, gunner aboard, autopilot). */
  mounted?: { vehicleUuid: string; role: FirerRole } | null;
  /** v0.29.0: strike or throw with this cyberlimb (its own Strength), and use vision magnification. */
  limbId?: string | null;
  magnify?: boolean;
  /** v0.43.0: a called shot at this limb location; a bounced grenade throw. */
  calledLocation?: string;
  bounce?: boolean;
  /** v0.72.0 (O7): indirect fire: how the spotter passes the target, and their Perception successes (less scatter). */
  indirect?: { link: SpotterLink; spotterSuccesses?: number; spotterUuid?: string | null } | null;
  /** v0.46.0: fire a fixed mount outside its firing arc anyway. */
  ignoreArc?: boolean;
  /** v0.49.0: fire a turret beyond its limit or traverse anyway. */
  ignoreTurret?: boolean;
}

/** The defender's own weapon in opposed melee, for a counterattack. */
export interface CounterWeapon {
  weaponName: string;
  power: number;
  level: DamageLevel;
  damageType: DamageType;
  reach: number;
  ignoreImmunity?: boolean;
  /** v0.48.0: a defending critter's bite carries its infection too. */
  infection?: InfectionState;
  /** v0.71.0 (R10): the defending weapon's extras (stun or own armor kind, silver or wood, a poisoned blade). */
  extras?: Partial<AttackState>;
}

/** A blast weapon's attack, kept so a miss can scatter it. */
export interface BlastContext {
  attackerUuid: string;
  weaponName: string;
  power: number;
  level: DamageLevel;
  damageType: DamageType;
  perMetre: number;
  point: { x: number; y: number; elevation: number };
  /** v0.55.0: a gas grenade's toxin: everyone caught resists it. */
  toxin?: ToxinHit;
  dodge: boolean;
  /** Range band (scatter dice), attack successes (less scatter), grenade kind. */
  range?: string;
  successes?: number;
  kind?: string;
  /** v0.37.0: a shaped charge, and anti-vehicle (both hit barriers harder). */
  shaped?: boolean;
  antiVehicle?: boolean;
  /** v0.43.0: the grenade's fuse, smart guidance with a smartlink, and a bounced throw. */
  fuse?: string;
  smart?: boolean;
  bounce?: boolean;
  /** v0.72.0 (O7): fired indirect: the spotter's successes take scatter off. */
  indirect?: { spotterSuccesses: number };
  /** v0.61.0: fired inside the launcher's minimum arming range: it doesn't go off. */
  dud?: boolean;
  /** v0.79.0 (RULES.DOCS_V79.rangedScatter 'byType', SRII Grenade Range Table): standard / aerodynamic / launcher; null = by range. */
  scatterType?: ScatterType | null;
}

/** What a summoning takes (SR2Actor.conjure). */
export interface ConjureOptions {
  force: number; spiritKind?: SpiritKind; spiritType?: string; templateUuid?: string | null;
  poolDice?: number; drainPoolDice?: number;
  /** Elementals: their element (guessed from the type if empty). Nature spirits: their domain. */
  element?: string; domain?: string;
  /** Elementals: pay for conjuring materials from nuyen (the Summon dialog ticks it by default). */
  useMaterials?: boolean;
  /** v0.50.0: found-by-themselves modifiers switched off in the dialog. */
  exclude?: string[];
  /** v0.61.0: an insect spirit's host body (the user's target if not given). */
  hostUuid?: string | null;
}

/** A charge armed with a timer on a scene (v0.43.0). */
export interface ArmedCharge {
  id: string;
  actorUuid: string;
  name: string;
  power: number;
  perMetre: number;
  shaped: boolean;
  point: { x: number; y: number; elevation: number };
  at: { round: number; worldTime: number };
  seconds: number;
  place: string;
  /** Its card: once that card's Detonate has been used, the timer does nothing. */
  messageId: string;
  /** v0.47.0: the setter's successes, which make it harder to disarm (RULES.GEAR.disarm). */
  setterSuccesses?: number;
}

/** Whether an attack is resolved as an opposed melee test. */
export function opposedMelee(a: { melee?: boolean; astral?: boolean; matrix?: boolean; distance?: boolean } | undefined): boolean {
  return Boolean(a?.melee && !a.astral && !a.matrix && !a.distance && RULES.COMBAT.melee.opposed);
}

/** The damage-state extras an attack carries through to the target's resistance. */
function armorExtras(a: Partial<AttackState>): Partial<DamageState> {
  return {
    ...(a.armorMultiplier !== undefined && a.armorMultiplier !== 1 ? { armorMultiplier: a.armorMultiplier } : {}),
    ...(a.flechette ? { flechette: true } : {}),
    ...(a.armorKind ? { armorKind: a.armorKind } : {}),
    ...(a.ignoreArmor ? { ignoreArmor: true } : {}),
    ...(a.ignoreImmunity ? { ignoreImmunity: true } : {}),
    ...(a.awakenedAttacker ? { awakenedAttacker: true } : {}),
    ...(a.extraArmor ? { extraArmor: a.extraArmor } : {}),
    ...(a.antiVehicle ? { antiVehicle: true } : {}),
    // v0.80.0 (URR_V80.vehDamage): how a hit on a vehicle came about (weapon base Power, a spell, an impact).
    ...(a.vehHit ? { vehHit: a.vehHit } : {}),
    ...(a.material ? { material: a.material } : {}),
    ...(a.calledLocation ? { calledLocation: a.calledLocation } : {}),
    ...(a.infection ? { infection: a.infection } : {}),
    ...(a.toxinHit ? { toxinHit: a.toxinHit } : {}),
    ...(a.flame || damageImmunity({ fire: true }, { element: String(a.elementEffect ?? '') }).immune ? { fire: true } : {}),
    // v0.57.0: a called shot at part of a vehicle; an occupant shot through it takes the damage instead.
    ...(a.vehiclePart && a.vehiclePart !== 'occupant' ? { vehiclePart: a.vehiclePart, ...(a.vehicleWeaponId ? { vehicleWeaponId: a.vehicleWeaponId } : {}) } : {}),
    ...(a.vehiclePart === 'occupant' && a.occupantUuid ? { targetUuid: a.occupantUuid, antiVehicle: undefined, extraArmor: (a.extraArmor ?? 0) + (a.occupantArmor ?? 0), occupantShot: true } : {}),
  };
}

/** The secondary-effect button on an elemental spell's hit card, and its flag (v0.39.0). */
function elementEffectExtras(a: Partial<AttackState>, targetUuid: string): { html: string; flags: Record<string, unknown> } {
  const k = a.elementEffect;
  if (!k || k === 'none') return { html: '', flags: {} };
  return {
    html: ` <button type="button" data-sr2e-action="elementEffect" title="${tx('SR2E.Card.Actor.theElementSSecondaryEffect')}">${escText(ELEMENT_EFFECT_LABELS[k])}</button>`,
    flags: { elementEffect: { targetUuid, kind: k, force: a.spellForce ?? a.power ?? 0 } },
  };
}

/** State carried on a "you were hit" card so the target can resist. */
export interface DamageState {
  targetUuid: string;
  /** v0.80.0 (URR_V80.vehDamage): how a hit on a vehicle came about (weapon base Power, a spell, an impact). */
  vehHit?: Veh80Hit;
  melee: boolean;
  /** v0.61.0: fire damage (a flamethrower, a fire elemental spell): fire immunity stops it. */
  fire?: boolean;
  astral?: boolean;
  matrix?: boolean;
  black?: boolean;
  elemental?: boolean;
  ignoreImmunity?: boolean;
  /** v0.72.0 (O3): the attacker is a spirit or a dual-natured critter: its blow isn't stopped outright by immunity. */
  awakenedAttacker?: boolean;
  armorMultiplier?: number;
  armorKind?: 'ballistic' | 'impact';
  ignoreArmor?: boolean;
  extraArmor?: number;
  /** v0.79.0 (RULES.DOCS_V79.rangedFlechette): flechette rounds (see AttackState). */
  flechette?: boolean;
  /** Against vehicles: an anti-vehicle weapon (full damage), or a crash (no weapon reduction). */
  antiVehicle?: boolean;
  crash?: boolean;
  /** v0.73.0 (O25): the rammer's own share of a ram (its passengers take theirs). */
  ramSelf?: boolean;
  /** The weapon's material, for critter vulnerabilities (v0.39.0). */
  material?: string;
  /** v0.43.0: a called shot at this limb location. */
  calledLocation?: string;
  /** v0.48.0: a bite that passes on a disease. */
  infection?: InfectionState;
  /** v0.55.0: a toxin delivered by the hit. */
  toxinHit?: ToxinHit;
  /** Matrix damage from IC: blaster and sparky crashes damage the deck. */
  ic?: IcAction;
  /** v0.80.0 (URR_V80.cbtDefense 'cleanMiss'): the attacker's successes and the net, staged at the resistance test. */
  cleanMiss80?: { hits: number; net: number; noClean?: boolean };
  /** v0.57.0: a called shot at part of a vehicle (applied when the vehicle takes the damage). */
  vehiclePart?: string; vehicleWeaponId?: string;
  /** v0.92.3 (Rigger 2 p. 53): the attacker's successes against a vehicle, for a complete miss at its resistance test. */
  attackHits?: number;
  /** v0.92.3 (Rigger 2 p. 53): someone shot inside a vehicle (no Combat Pool; a jacked-in rigger +3 TN). */
  occupantShot?: boolean;
  damageType: DamageType;
  power: number;
  level: DamageLevel;
}

/** State carried on a spell card so the target can resist. */
export interface SpellState {
  casterUuid: string;
  targetUuid: string;
  spellName: string;
  force: number;
  resistAttribute: AttributeKey;
  /** 'power' for critter/spirit powers (wording only). */
  noun?: 'spell' | 'power';
  /** A power with no damage: net successes are reported, the monitor is untouched. */
  effectOnly?: boolean;
  /** Pool the target may add when resisting (spells: Spell Pool). */
  resistPool?: 'spell' | 'combat' | 'none';
  level: DamageLevel;
  damageType: DamageType;
  casterSuccesses: number;
  /** Cast through a ward or mana barrier: its rating adds resistance dice. */
  barrierDice?: number;
  barrierName?: string;
  /** An Essence drain power (v0.39.0). */
  essenceDrain?: boolean;
  /** A sustained power changing the target's attributes (v0.45.0); v0.56.0: any EffectBundle change. */
  powerEffect?: FxSpec;
  /** A spell bounced back by reflecting: it can't be reflected again (v0.45.0). */
  reflected?: boolean;
  /** v0.80.0 (RULES.URR_V80.magRitualResistTn): the TN to resist, when not the Force (a ritual led by a higher Sorcery). */
  resistTn?: number;
}

/** Context for a test that marks the condition monitor (damage soak, drain, spell resistance). */
export interface SoakContext {
  /** 'stage': successes stage `level` down. 'spell': successes cancel the caster's and the rest stage it up. */
  mode: 'stage' | 'spell';
  noun: 'damage' | 'drain';
  level: DamageLevel;
  type: DamageType;
  body: number;
  casterSuccesses?: number;
  spellName?: string;
  /** spell mode: a power with no damage, so nothing is marked on the monitor. */
  effectOnly?: boolean;
  /** Monitor before this test applied anything, and after (so a re-roll can correct it safely). */
  before: Monitor;
  after?: Monitor;
  /** Matrix damage: marks the Matrix condition monitor instead (before and after, in boxes). */
  track?: 'matrix' | 'vehicle';
  matrixBefore?: number;
  matrixAfter?: number;
  /** The IC that did the Matrix damage (blaster and sparky crashes damage the deck). */
  matrixIc?: IcAction;
  /** Armor (persona damage) or Shield (black IC) soaked this hit and loses rating once (v0.40.0). */
  matrixUtility?: { programId: string; name: string; rating: number; kind: 'armor' | 'shield'; degraded?: boolean };
  /** Vehicle damage: the vehicle's condition track before and after, and the Power (rigger feedback). */
  vehicleBefore?: number;
  vehicleAfter?: number;
  power?: number;
  /** Vehicle damage from a crash (nobody aboard gets the passenger share). */
  crash?: boolean;
  ramSelf?: boolean;
  /** v0.92.3 (Rigger 2 p. 53): Control Pool dice the rigger used on a vehicle's resistance, and the attacker's successes. */
  controlUsed?: number; attackHits?: number;
  /** v0.57.0: a called shot at part of the vehicle, and whether its effect was applied. */
  vehiclePart?: string; vehicleWeaponId?: string; partApplied?: boolean;
  /** Worn armor of this kind took the hit (armor degrading, v0.37.0), and whether it has been degraded. */
  armorKind?: 'ballistic' | 'impact';
  degraded?: boolean;
  /** Damage from an attack: the Power and resistance TN, for a knockdown test. */
  knockdown?: { power: number; tn: number };
  /** v0.80.0 (URR_V80.cbtDefense 'cleanMiss'): clean miss and net staging at this test. */
  cleanMiss80?: { hits: number; net: number; noClean?: boolean };
  /** Damage from a vulnerability: regeneration can't heal it (v0.39.0). */
  noRegen?: boolean;
  /** An Essence drain power: who drains, and whether the Essence has moved (v0.39.0). */
  essenceDrain?: { casterUuid: string; moved?: boolean;
    /** v0.81.0 (D1-4): the Essence this card has taken from the victim and given the caster, so a re-roll moves the difference. */
    taken?: number; gained?: number;
    /** v0.81.0 (R2-DOC 2): the caster's (or the victim's) side was left to the GM by hand, and counts as moved. */
    gmGain?: boolean; gmTake?: boolean };
  /** v0.43.0: damage from an attack can damage cyberware (a called shot's limb more likely); rolled once. */
  cyberCheck?: { location: string; rolled?: boolean };
  /** v0.48.0: a bite's disease, offered when the hit does enough Physical boxes. */
  infection?: InfectionState;
  /** v0.55.0: a weapon's toxin, offered when the hit lands (or does damage, `needsWound`). */
  toxinHit?: ToxinHit;
  /** v0.45.0: a reflecting initiate resisting a spell: what bounces back at the caster. */
  reflect?: { casterUuid: string; spellName: string; force: number; resistAttribute: AttributeKey; level: DamageLevel; damageType: DamageType; effectOnly?: boolean; defense: number;
    /** v0.48.0: a reflected critter power (resisted with its own pool). */
    noun?: 'power'; resistPool?: string };
  /** v0.45.0: a sustained power changing this target's attributes on a hit (the effect id once applied). */
  powerEffect?: FxSpec & { casterUuid: string; casterName: string; effectId?: string };
}

/**
 * v0.56.0: what a sustained power or spell puts on its target: the attribute changes (v0.45.0) and
 * the rest of an EffectBundle, scaled by successes when `perSuccess`; a TN-changing power's Special
 * adds RULES.CRITTERS_V56.powerMods; `kind` tells a spell's effect from a power's.
 */
export interface FxSpec {
  name: string;
  attributes: Record<string, number>;
  perSuccess: boolean;
  bundle?: Partial<EffectBundle>;
  special?: string;
  force?: number;
  kind?: 'power' | 'spell';
  /** Per-success effects are capped at this (a spell's Force), 0 = no cap. */
  capAt?: number;
  /** Successes per step (spells: RULES.MAGIC_V56.spellEffects.step; powers 1). */
  step?: number;
  /** Permanent from the start (a permanent spell with RULES.MAGIC_V56.permanent off). */
  permanent?: boolean;
  /** v0.78.0: minutes it lasts, rolled once when the power is used (Paralyzing Touch, RULES.BOOK_V78.paralysis 'drain'). */
  minutes?: number;
  /** v0.78.0: the user's Essence (Paralyzing Touch drains Quickness by it). */
  essence?: number;
}

/** A powerEffects flag entry (on the target actor). */
export interface FxEntry extends Partial<EffectBundle> {
  id: string; fromUuid: string; fromName: string; name: string; attributes: Record<string, number>;
  kind?: 'power' | 'spell'; special?: string; permanent?: boolean;
  /** v0.61.0: a power that holds its target (paralysis, petrification, binding): the token status, Combat Turns (0 = while it lasts), break-free TN. */
  status?: string; holdTurns?: number; breakTn?: number;
  /** v0.71.0 (R11): the successes it was built from and its spec, so a partial dispel can shrink it. */
  successes?: number; spec?: FxSpec;
  /** v0.78.0: when this entry ends by itself (Paralyzing Touch's Quickness drain, RULES.BOOK_V78.paralysis 'drain'). */
  until?: { round: number | null; worldTime: number } | any;
}

/** A summoning, carried on its chat card so a Karma re-roll can adjust the spirit's services. */
export interface ConjureContext {
  /** v0.65.0: the timed project this summoning started (re-rolls retime or drop it). */
  projectId?: string;
  force: number;
  /** v0.61.0: an insect spirit's host body (flesh form; '' = true form). */
  hostUuid?: string;
  spiritKind: SpiritKind;
  spiritType: string;
  /** A spirit actor to copy (attribute adjustments, powers, weapons), or null for a blank spirit. */
  templateUuid: string | null;
  /** Set once the spirit exists. */
  spiritUuid?: string | null;
  /** Services the spirit was given by this card's latest result. */
  servicesAfter?: number;
  element?: string;
  domain?: string;
  /** v0.48.0: an ally ritual: the Karma to bond it (charged once on success) and the days it took. */
  ally?: { karma: number; days: number; charged?: boolean };
  /** v0.71.0 (R20): a timed elemental summoning's drain, resisted when it finishes (`done` once rolled). */
  drainLater?: { force: number; pool: number; done?: boolean };
}

/** A banishing attempt, carried on its chat card so a Karma re-roll can correct the spirit's Force. */
export interface BanishContext {
  spiritUuid: string;
  spiritName: string;
  spiritSuccesses: number;
  forceBefore: number;
  forceAfter?: number;
  /** v0.56.0: successes the spirit's summoner added. */
  help?: number;
  /** v0.56.0: taking control rather than banishing: what it owed and whose it was, and whether it changed hands. */
  control?: boolean;
  servicesBefore?: number;
  summonerBefore?: string;
  taken?: boolean;
}

/**
 * v0.50.0: an opposed contest's card (perception, social, sneaking), kept so the GM can change a
 * TN afterwards: the first side is the one who made the test; a side with no result couldn't roll.
 */
export interface Contest {
  /** v0.71.0 (R1): haggling, fencing, legwork and finding gear are contests too (Karma Pool, GM TN change). */
  kind: 'perceive' | 'social' | 'sneak' | 'haggle' | 'fence' | 'legwork' | 'find';
  /** v0.71.0: one id for every card of this contest (a Karma re-roll posts a newer card; the newest is live). */
  id?: string;
  actorName: string;
  targetName?: string;
  /** v0.71.0: per side, the Karma Pool spent on it (re-rolls so far, successes bought, a disaster avoided). */
  sides: Array<{ name: string; label: string; result: SuccessTestResult | null; why?: string; uuid?: string; rerolls?: number; bought?: number; avoided?: boolean }>;
  /** v0.71.0: what a street contest needs to word its card again (haggle, fence, legwork, find). */
  deal?: Record<string, any>;
  /** GM retargets so far. */
  changed?: number;
  /** v0.58.0: a negotiated job's base pay (the card re-prices it from the net successes). */
  pay?: number;
  /** v0.79.0 (RULES.DOCS_V79.socialInfluence): a one-sided social test: only the speaker rolls (one side). */
  oneSided?: boolean;
}

/**
 * Everything about one test that a later Karma Pool re-roll needs, stored on its chat card.
 * `kind` decides what happens with the successes (see SR2Actor.#resolve).
 */
export interface TestSnapshot {
  actorUuid: string;
  label: string;
  kind: 'plain' | 'attack' | 'spell' | 'defend' | 'soak' | 'conjure' | 'banish' | 'dispel' | 'barrier' | 'track' | 'heal' | 'enchant' | 'quest' | 'system' | 'drive' | 'sensor' | 'bypass' | 'medic' | 'repair' | 'cyberRepair' | 'surgery' | 'psyche' | 'addiction' | 'disease'
    | 'cleanse' | 'divine' | 'invoke' | 'design' | 'notice' | 'rejection' | 'code' | 'install'
    | 'learn' | 'ward' | 'bindName' | 'centering' | 'assense'
    | 'jackOut' | 'mperceive' | 'maneuver' | 'mutility';
  baseTargetNumber: number;
  targetNumber: number;
  targetNumberClamped: boolean;
  modifiers: TargetNumberModifier[];
  totalDice: number;
  dice: DieResult[];
  successes: number;
  /** v0.78.0: a monowhip wielder's check after a defended miss (COMBAT_V61.monowhip 'defended'). */
  whipCheck?: { power: number; level: DamageLevel; damageType: any; weaponName: string };
  /** v0.79.0: a self-recovery test (RULES.DOCS_V79.healingGate): the result is written on resolve, so a re-roll corrects it. */
  selfRecovery?: { boxes: number; t: number };
  /** v0.80.0 (review #11): successes the test needs (the Revamp's radio decryption); the card says whether it made it. */
  need80?: number;
  botch: boolean;
  rerolls: number;
  disasterAvoided?: boolean;
  /** Successes bought with Karma Pool (v0.35.0). */
  bought?: number;
  /** v0.50.0: times the GM changed this test's TN afterwards. */
  retargets?: number;
  /** v0.50.0: the test's id, the same on every card it gets (Karma re-rolls, TN changes). */
  testId?: string;
  /**
   * v0.58.0: a plain test's extras: the time taken (base ÷ successes), what the successes reveal (a plain
   * Perception test, a language, a listening device), a gear repair, and an instructor's test for training.
   */
  timed?: { base: number; unit: string };
  reveal?: { kind: 'notice' | 'language' | 'listen' | 'knowledge'; what?: string };
  gearRepair?: { itemUuid: string; name: string; fixed?: boolean; projectId?: string };
  instruct?: { studentUuid: string; trainingId: string; days: number; instructorName: string; instructorRating: number; newRating: number; startedAt: number; readyAt?: number; attribute?: boolean };
  /** attack: the weapon's item id (a disaster can jam it). */
  weaponId?: string;
  /** attack: the attack minus successes/TN; present only when there was a target. */
  attack?: Omit<AttackState, 'attackSuccesses' | 'targetNumber'>;
  /** attack: several targets (an area elemental spell); each gets its own button. */
  attackTargets?: Omit<AttackState, 'attackSuccesses' | 'targetNumber'>[];
  /** spell: the spell minus caster successes; present only for a combat spell with a target. */
  spell?: Omit<SpellState, 'casterSuccesses'>;
  /** defend: the attack being defended against. */
  defendAgainst?: AttackState;
  /** defend (opposed melee): the defender's weapon, for a counterattack. */
  counter?: CounterWeapon;
  /** attack: a blast weapon, so a miss can scatter it. */
  blast?: BlastContext;
  soak?: SoakContext;
  conjure?: ConjureContext;
  banish?: BanishContext;
  /** spell: every target of an area spell or power (each gets its own Resist button). */
  spellTargets?: Omit<SpellState, 'casterSuccesses'>[];
  /** v0.43.0: vehicles hit by a combat spell (attacks with Power = Force, resisted with Body). */
  spellVehicles?: Array<Omit<AttackState, 'attackSuccesses' | 'targetNumber'>>;
  /** A sustained spell: added to the caster's Sustaining list once the test (or a re-roll) succeeds. */
  sustain?: { spellName: string; force: number; category: string; focusId: string; applied?: boolean; targetUuids?: string[];
    /** v0.56.0: the effect it put on its targets; a permanent spell (sustained until it takes). */
    effectId?: string; permanent?: boolean;
    /** v0.61.0: an exclusive spell. */
    exclusive?: boolean;
    /** v0.72.0 (O17): a Mana or Physical Barrier spell raises a barrier actor while sustained. */
    barrier?: 'mana' | 'physical' };
  dispel?: DispelContext;
  barrier?: BarrierContext;
  /** heal: the patient and the track being healed, before (and after) this test. */
  heal?: {
    targetUuid: string; targetName: string; track: 'physical' | 'stun'; before: number; after?: number;
    /** 'magic' (default), 'firstAid' (capped, may stabilise) or 'natural' (hours of rest). */
    mode?: 'magic' | 'firstAid' | 'natural'; hours?: number;
    /** v0.78.0: natural healing time × (symbiotes; RULES.BOOK_V78.symbiotes). */
    timeFactor?: number;
    /** v0.79.0: rolled as a healing stage (RULES.DOCS_V79.healing 'stages'): one wound level when the rest is long enough. */
    stages?: boolean;
  };
  /** enchant: the task, base days, and a focus to create on success. */
  enchant?: { label: string; task?: string; baseDays: number; focus?: { name: string; focusType: string; rating: number; category: string; target: string; size?: string }; created?: boolean; fetishFor?: string; materialsApplied?: boolean; projectId?: string };
  /** quest: the quest before this stage (and after, once applied). */
  quest?: { before: QuestState; after?: QuestState };
  /** track: what is being followed and how long the trail takes at 1 success. */
  track?: { label: string; baseHours: number };
  /** A repeating power: the card offers to use it again on the same targets. */
  repeat?: { powerUuid: string; targetUuids: string[]; modifiers?: TargetNumberModifier[]; exclude?: string[] };
  /** system: a Matrix system test against a host's subsystem, the operation and its target. */
  system?: SystemContext;
  /** attack/defend: a non-damage Matrix effect (crippler, tar, trace) once applied, so a re-roll does not repeat it. */
  matrixEffect?: { applied: boolean; net: number };
  /** medic: the persona's Matrix monitor before (and after), and the Medic program used. */
  medic?: { programId: string; programName: string; before: number; after?: number; degraded?: boolean };
  /** surgery: the patient, the item going in, its Essence or Body Index, and what has been applied. */
  surgery?: { patientUuid: string; patientName: string; itemId: string; itemName: string; points: number; installed?: boolean; harmed?: boolean;
    /** v0.54.0: this operation's id: its state is also kept on the patient (flag `surgeryState`), so a GM-applied result and a later re-roll agree. */
    id?: string;
    /** v0.55.0: the surgical trauma has been applied. */
    traumaDone?: boolean;
    /** v0.48.0: the patient's care while recovering, whether to pay for it, and whether it was paid. */
    care?: string; pay?: boolean; paid?: boolean; paidAmount?: number };
  /** cyberRepair: the damaged cyberware being repaired, and whether it has been fixed. */
  cyberRepair?: { itemId: string; itemName: string; ownerUuid?: string; fixed?: boolean; projectId?: string };
  /** repair: the deck's damage before (and after) the repair. */
  repair?: { deckId: string; deckName: string; before: DeckDamage; after?: DeckDamage; projectId?: string };
  /** drive: a vehicle test; a failed crash test crashes the vehicle at its current speed. */
  drive?: { vehicleUuid: string; vehicleName: string; crashTest: boolean; speed: number;
    /** v0.57.0: a push to this speed, and whether it was applied. */
    push?: number; pushApplied?: boolean };
  /** sensor: a vehicle's sensor test on a target; success gives a sensor lock. */
  sensor?: { targetUuid: string; targetName: string;
    /** v0.57.0: the vehicle whose sensors were used (the card is the jumped-in rigger's, for Karma). */
    vehicleUuid?: string };
  /** bypass: a lock being bypassed; what has been applied to the site so far. */
  bypass?: { siteUuid: string; deviceId: string; deviceName: string; opened?: boolean; failApplied?: boolean;
    /** v0.46.0: the device's kind (time to bypass), its tamper alarm, the bypasser's skill, and whether the alarm was rolled. */
    kind?: string; tamper?: number; skillRating?: number; tamperRolled?: boolean; tampered?: boolean;
    /** v0.57.0: opening the lock's casing (the first step). v0.78.0: 'voice' fooling a voice lock (BOOK_V78.voiceLocks). */
    step?: 'casing' | 'voice';
    /** v0.78.0 (BOOK_V78.tamper 'tn'): this step carries the anti-tamper alarm's TN (0 successes trips it). */
    tamperOnStep?: boolean;
    /** v0.78.0 (voice): the deception device's rating, the lock's rating, and the lock's own roll (once, kept for re-rolls). */
    deception?: number; lockRating?: number; lockSuccesses?: number; lockType80?: string };
  /** attack: a ram, so a hit also damages the rammer. */
  ram?: { vehicleUuid: string; power: number; level: DamageLevel | null; bodyPerSuccess?: number };
  /** addiction: a drug's addiction test on a dose, or kicking the habit (v0.42.0). */
  addiction?: { drug: string; mode: 'dose' | 'kick'; applied?: boolean };
  /** disease: resisting infection, or a disease's progress test (v0.42.0); once applied. */
  disease?: { name: string; mode: 'infect' | 'tick'; level: DamageLevel; damageType: DamageType; power: number; intervalHours: number; incubationHours: number; needed: number; index?: number; applied?: boolean; before?: Monitor;
    /** v0.48.0: how it spreads on (RULES.HEALTH.contagion), and who it was caught from. */
    contagious?: string; from?: string };
  /** v0.45.0: whisper the card to these users only (divining, noticing a ritual). */
  privateTo?: string[];
  /** cleanse: the scene, its background count, and points already taken off. */
  cleanse?: { sceneId: string; count: number; applied: number; align: string[]; projectId?: string };
  /** divine: the question asked. */
  divine?: { question: string };
  /** invoke: the spirit being invoked into a great form, once applied. */
  invoke?: { spiritUuid: string; spiritName: string; applied?: boolean };
  /** design: the spell being designed (its finished item data). */
  design?: { name: string; system: Record<string, unknown>; notes: string[]; projectId?: string };
  /** notice: a ritual being prepared against this actor. */
  notice?: { spellName: string; force: number; casterName: string };
  /** rejection: a bioware rejection test, once applied. */
  rejection?: { applied?: boolean };
  /** A sustained power changing attributes (resist 'none'): its targets and the effect id once applied. */
  powerEffect?: FxSpec & { targetUuids: string[]; effectId?: string };
  /** code: writing a program or building a deck part (v0.46.0), once applied. */
  code?: { mode: 'program' | 'deck'; name: string; baseDays: number; system?: Record<string, unknown>; part?: DeckPart; rating?: number; cost?: number; deckId?: string; applied?: boolean; size?: number; memory?: boolean; projectId?: string };
  /** v0.49.0: installing a vehicle modification (applied once; a re-roll only changes the time). */
  install?: { vehicleUuid: string; vehicleName: string; index: number; modName: string; rating: number; baseHours: number; payerUuid: string; applied?: boolean; botchApplied?: boolean; projectId?: string };
  /** v0.56.0 learn: learning (or raising) a spell; Karma paid and the spell written once. */
  learn?: { name: string; force: number; cost: number; spellId?: string; system?: Record<string, unknown>; from?: string; applied?: boolean; projectId?: string; foreign?: boolean; extraDice?: number };
  /** v0.91.8: a teacher's Instruction test for a student's spell (RULES.FORMULA_V918.teacher); `used` once learned from. */
  /** v0.92.0: a cast inside Sorcery's narrow layers (the card's interpretations line). */
  narrow?: { layers: boolean; rating: boolean };
  teach?: { studentUuid: string; teacherUuid: string; spell: string; force: number; spellId?: string; system?: Record<string, unknown>; teacherName: string; sorcery: number; foreign: boolean; fee: number };
  /** v0.56.0 ward: raising a ward by ritual; the barrier actor once made. */
  ward?: { force: number; name: string; team: number; nuyen: number; barrierUuid?: string; pending?: boolean; projectId?: string };
  /** v0.56.0 bindName: binding a free spirit by its true name. */
  bindName?: { spiritUuid: string; spiritName: string; force: number; spiritSuccesses: number; applied?: boolean; paid?: number; summonerBefore?: string; servicesBefore?: number };
  /** v0.56.0 assense: what the successes reveal about the subject (whispered to the assenser). */
  assense?: { targetUuid: string; targetName: string };
  /** v0.57.0 jackOut: breaking free of black IC to jack out. */
  jackOut?: { icUuid: string; icName: string; needed: number; applied?: boolean };
  /** v0.57.0 mperceive: Locate Decker / IC or Analyze Icon on a Matrix target (an IC relocating an evading decker: `byIc`). */
  mperceive?: { kind: PerceptionKind; targetUuid: string; targetName: string; byIc?: boolean; applied?: boolean };
  /** v0.57.0 maneuver: a cybercombat maneuver; the opponent's successes, and the entry it left. */
  maneuver?: { kind: ManeuverKind; targetUuid: string; targetName: string; opp: number; entry?: Maneuver | null; freed?: boolean };
  /** v0.57.0 mutility: Slow on an IC, or Restore on the persona; what it changed. */
  mutility?: { kind: 'slow' | 'restore'; programId: string; programName: string; rating: number; targetUuid?: string; targetName?: string;
    applied?: number; before?: { crippled: DeckDamage; deck: DeckDamage }; degraded?: boolean;
    /** v0.81.0 (D3-5): Restore: what it left (a re-roll writes only over that), and the deck it read. */
    after?: { crippled: DeckDamage; deck: DeckDamage }; deckId?: string };
  /** psyche: a psychotropic IC's test (v0.40.0); the effect it left, once applied. */
  psyche?: { icName: string; rating: number; kind: string; hostUuid?: string; applied?: boolean; effect?: PsycheEffect | null };
}

/** A system operation (v0.27.0): what it is, what it targets, and whether its effect has been applied. */
export interface SystemContext {
  hostName: string;
  subsystem: string;
  operation: string;
  hostUuid?: string;
  opId?: string;
  effect?: string;
  /** IC (analyze, decrypt), a host file, or a site device (siteUuid + deviceId). */
  targetUuid?: string;
  fileId?: string;
  siteUuid?: string;
  deviceId?: string;
  applied?: boolean;
  failApplied?: boolean;
  /** A frame ran it (v0.28.0): moves on log on/off apply to the frame. */
  frameUuid?: string;
  /** Logging on: the node it came from, for grid travel (v0.40.0). */
  fromUuid?: string;
  /** A security decker's action (v0.40.0). */
  security?: boolean;
  /** v0.46.0: logged on by dialling the node's number; a file being uploaded; how a file is edited. */
  dialled?: boolean;
  upload?: { name: string; size: number; value: number; paydata: boolean; ioSpeed: number };
  editMode?: 'alter' | 'erase';
  editNote?: string;
  /** v0.57.0: a subsystem bomb being defused; a comcall and a number; a data bomb that went off on this operation. */
  bombSubsystem?: string;
  callId?: string;
  number?: string;
  bombed?: boolean;
}

/** A change to a host's data stores or alert, applied by the GM (or the host's owner). */
export interface HostChange {
  found?: { deckerUuid: string; ids: string[] }; decrypt?: string; removeFile?: string; minAlert?: string;
  /** v0.40.0: a smoke cloud, a spotted intruder, an alert set outright (may lower it), a tally reset. */
  smoke?: SmokeCloud; spot?: string; setAlert?: string; resetTally?: boolean;
  /** v0.46.0: a file uploaded into the host, and a file edited (a note of what changed). */
  addFile?: { name: string; size: number; value: number; paydata: boolean; uploadedBy: string; foundBy: string[] };
  editFile?: { id: string; note: string };
  /** v0.57.0: a validated passcode (decker UUID) given or taken away; data bombs found, defused or set off; a comcall placed, tapped, rerouted or ended. */
  validate?: string; invalidate?: string;
  bombFound?: { deckerUuid: string; fileId?: string; subsystem?: string };
  defuse?: { fileId?: string; subsystem?: string };
  bombOff?: { fileId?: string; subsystem?: string; erase: boolean };
  call?: { op: 'place' | 'tap' | 'reroute' | 'end'; id: string; from?: string; to?: string; by?: string; who?: string };
}

/** Dispelling one of another actor's sustained spells. */
export interface DispelContext {
  targetUuid: string;
  targetName: string;
  spellName: string;
  force: number;
  successesBefore: number;
  successesAfter?: number;
}

/** Forcing through a ward or barrier. */
export interface BarrierContext {
  barrierUuid: string;
  barrierName: string;
  barrierSuccesses: number;
  ratingBefore: number;
  ratingAfter?: number;
}

type Resolved = { html: string; flags: Record<string, unknown>; snap: TestSnapshot;
  /** v0.81.0 (D2-10): whether the result was written (#resolveHeal), so the GM's Apply needn't read the card's words. */
  applied?: boolean };

/**
 * v0.81.0 (D1-5, D2-7): the follow-up cards a test's resolution asks for (a Magic loss prompt, dump shock, a host
 * or site change, ...). One object per `#post` call, handed down to the resolvers that fill it, so two tests
 * resolving at once on one actor can't clear or steal each other's (they were instance fields before).
 */
interface FollowUps {
  /** Physical damage before the last soak applied, so a Magic loss prompt can follow its card. */
  physicalBefore?: number;
  /** Set when a persona crashes, so a dump shock prompt can follow its card. */
  dumpShock?: { tn: number; level: DamageLevel };
  /** Set when a persona crashes with no dump shock (a tortoise): hitchers are still unplugged. */
  unhitch?: boolean;
  /** Set when a vehicle a rigger is jumped into is damaged or destroyed: feedback or dump shock follows. */
  riggerShock?: RiggerShock;
  /** Set by a system operation: the change to a host's data stores or alert follows its card. */
  hostChange?: { host: any; change: HostChange; label: string };
  /** Set when hot-sim Matrix damage overloads the decker: a simsense overload test follows (the Power). */
  overload?: number;
  /** Set when blaster or sparky IC crash a persona: deck damage (and sparky's biofeedback) follows. */
  deckDamage?: { ic: IcAction; reason: string };
  /** Set by a lock bypass: the change to the site's security follows its card. */
  siteChange?: { site: any; change: SiteChange; label: string };
  /** Set when a vehicle is hit: damage for the people aboard follows its card. */
  passengers?: DamageState[];
}

/**
 * v0.56.0: a change to an actor its user can't make, applied by the GM (gmActorCard, applyActorUpdate).
 * v0.81.0 (SEC1-1): typed kinds only (no free-form update); each is bounded and re-derived when applied.
 */
export interface ActorChange {
  uuid: string;
  /**
   * v0.81.0: the actor the change comes from (the roller, the caster, the dead master, the payer's installer). From a
   * card, applyActorUpdate requires its author to own this actor (or be a GM).
   */
  by?: string;
  /** Boxes added to (or taken off) a track. */
  monitor?: { track: 'physical' | 'stun'; boxes: number };
  /** Remove a dropped barrier spell's barrier. */
  remove?: boolean;
  /** A relative nuyen change (in the ledger). */
  nuyen?: { amount: number; label: string };
  /** A bound spirit's master died: what happens comes from the spirit's kind (MAGIC_V61.masterDies). */
  masterDied?: boolean;
  /** A spirit changes hands (control, binding): the new summoner and services; its owners follow the summoner. */
  handSpirit?: { toUuid: string; services: number; oldSummonerUuid: string };
  /** v0.81.0 (D2-3): a spirit's Force or a barrier's rating lowered by a banishing or a breach: only down, only from `from`. */
  lower?: { key: 'force' | 'rating'; from: number; to: number };
  /** v0.81.0 (D2-3): a sustained spell dispelled: its successes from `from` down to `to` (0 ends it). */
  dispel?: { spellName: string; force: number; from: number; to: number };
}

/** A change to a site's security: tally points, a minimum alert, a device bypassed (or restored). */
export interface SiteChange { add?: number; minAlert?: string; deviceId?: string; bypassed?: boolean;
  /** v0.57.0: a maglock's casing opened (or closed again). */
  casingOpen?: boolean }

/** Feedback or dump shock owed by a rigger after their vehicle was hit or destroyed. */
type RiggerShock = { riggerUuid: string; riggerName: string; tn: number; level: DamageLevel; type: DamageType; kind: 'feedback' | 'dump'; attribute?: 'body' | 'willpower' };
/** v0.79.0 (RULES.DOCS_V79.riggerDumpShock, Rigger 2 p64): a remote rigger's dump shock, (RCD + 4)S Stun vs Body; aboard (no deck): the old values. */
function dumpShockFor(rigger: any, viaDeck: boolean): Pick<RiggerShock, 'tn' | 'level' | 'type' | 'attribute'> {
  const s = riggerDumpShock({ rcdRating: viaDeck ? Number(rigger?.system?.derived?.rigging?.rcd ?? 0) : 0 });
  return { tn: s.tn, level: s.level as DamageLevel, type: s.type as DamageType, attribute: s.attribute };
}
/** The resisting attribute's name for a dump shock or feedback button. */
const shockAttr = (r: { attribute?: string }) => (r.attribute === 'body' ? tx('SR2E.Card.Actor.body') : tx('SR2E.Card.Actor.willpower'));

function asResult(snap: TestSnapshot): SuccessTestResult {
  // v0.81.1 (SEC2b-2): the snapshot is a card's flags: numbers as numbers (describeResult prints them raw).
  const n = (v: unknown) => (Number.isFinite(Number(v)) ? Number(v) : 0);
  return {
    baseTargetNumber: n(snap.baseTargetNumber),
    modifiers: (Array.isArray(snap.modifiers) ? snap.modifiers : []).map((m: any) => ({ ...m, label: String(m?.label ?? ''), value: n(m?.value) })),
    targetNumber: n(snap.targetNumber),
    targetNumberClamped: Boolean(snap.targetNumberClamped),
    totalDice: n(snap.totalDice),
    dice: (Array.isArray(snap.dice) ? snap.dice : []).map((d: any) => ({ ...d, faces: (Array.isArray(d?.faces) ? d.faces : []).map(n), total: n(d?.total), success: Boolean(d?.success) })),
    successes: n(snap.successes),
    botch: Boolean(snap.botch),
  };
}

function withResult(snap: TestSnapshot, r: SuccessTestResult): TestSnapshot {
  return {
    ...snap,
    baseTargetNumber: r.baseTargetNumber, modifiers: r.modifiers, targetNumber: r.targetNumber,
    targetNumberClamped: r.targetNumberClamped, totalDice: r.totalDice, dice: r.dice,
    successes: r.successes, botch: r.botch,
  };
}

/** Extra dice from foci and a totem, with a note for the card title. */
function bonusNote(focus: FocusDice, totem: number): { dice: number; note: string } {
  const notes = [...focus.notes];
  if (totem) notes.push(`totem ${totem > 0 ? '+' : ''}${totem}`);
  return { dice: focus.dice + totem, note: notes.length ? ` [${notes.join(', ')}]` : '' };
}

const cap = (s: string) => s.charAt(0).toUpperCase() + s.slice(1);
const sameMonitor = (a: Monitor, b: Monitor) => a.physical === b.physical && a.stun === b.stun;
/** v0.89.5: a counted noun in the user's language (`SR2E.Count`), named by its English word. */
const plural = (n: number, word: CountNoun) => tNoun(n, word);
/**
 * v0.89.5: an outcome word on a card ("Hit!", "Missed." …) marked with its id, so the banner above it and the look's
 * decorations find it by id in any language. Saved English cards are still read by their words (applications/look.ts).
 */
type OutcomeId = 'hit' | 'missed' | 'counter' | 'resisted' | 'fullyResisted' | 'noDrain' | 'cleanMiss';
const OUTCOME_KEYS: Record<OutcomeId, string> = {
  hit: 'SR2E.Card.Outcome.hit', missed: 'SR2E.Card.Outcome.missed', counter: 'SR2E.Card.Outcome.counterattack',
  resisted: 'SR2E.Card.Outcome.resisted', fullyResisted: 'SR2E.Card.Outcome.fullyResisted', noDrain: 'SR2E.Card.Outcome.noDrain',
  cleanMiss: 'SR2E.Card.Outcome.cleanMiss',
};
const outcomeWord = (id: OutcomeId, strong = true): string => {
  const text = tKey(OUTCOME_KEYS[id]);
  return strong ? `<strong data-sr2e-outcome="${id}">${text}</strong>` : `<span data-sr2e-outcome="${id}">${text}</span>`;
};
/** v0.89.5: the track a "Takes X …" line is on, for the banner (`data-sr2e-track`). */
type TakenTrack = 'physical' | 'stun' | 'matrix' | 'vehicle';
const takenMark = (level: string, track: TakenTrack, inner: string): string =>
  `<span data-sr2e-taken="${escText(level)}" data-sr2e-track="${track}">${inner}</span>`;
const TAKEN_BANNER: Record<TakenTrack, string> = {
  physical: 'SR2E.Card.Outcome.takenPhysical', stun: 'SR2E.Card.Outcome.takenStun',
  matrix: 'SR2E.Card.Outcome.takenMatrix', vehicle: 'SR2E.Card.Outcome.takenVehicle',
};
/** v0.89.5: a condition-monitor status (`ok`, `unconscious`, `dying`, `dead`) as words, not its id. */
const STATUS_KEYS: Record<string, string> = {
  ok: 'SR2E.Card.Status.ok', unconscious: 'SR2E.Card.Status.unconscious', dying: 'SR2E.Card.Status.dying', dead: 'SR2E.Card.Status.dead',
};
/** v0.89.5: a damage type (`physical`, `stun`) as a word, not its id. */
const damageWord = (type: string): string => (type === 'stun' ? tx('SR2E.Card.DamageType.stun') : type === 'physical' ? tx('SR2E.Card.DamageType.physical') : String(type));
const statusText = (status: string): string => (Object.hasOwn(STATUS_KEYS, status) ? tKey(STATUS_KEYS[status]!) : String(status));

export class SR2Actor extends Actor {
  get sys(): any {
    return this.system;
  }

  /**
   * v0.81.1 (SEC1-1, design 1): run `fn` as the card's author. A GM re-running a card (retarget, Karma, Buy success,
   * Avoid disaster, Use again, Send ritual, Offer to grimoire, Detonate and the blast buttons) goes through this, so
   * every "write directly or post an Apply (GM) card" choice inside follows what `author` owns; a GM author (or none)
   * acts with the GM's rights.
   * Every call is queued on the GM lock (applications/gmlock.ts) and sets and clears `actingAuthor` inside its locked
   * task, so no other GM-authority work (another re-run, a GM card, a relay request, a tick, an Apply) overlaps it.
   * There is no async context in the browser to tell a nested call from a concurrent one, so nothing inside a locked
   * task may call this (it would wait for itself; the lock warns after 15 s): retarget, reached from inside the
   * chat's wrapper, runs inline through `#retargetAs` instead.
   */
  static async runAsAuthor<T>(author: any, fn: () => Promise<T> | T): Promise<T> {
    const next = author && !realGm(author) ? author : null;
    return withGmLock(async () => {
      actingAuthor = next;
      try {
        return await fn();
      } finally {
        actingAuthor = null;
      }
    });
  }

  /**
   * v0.81.1 round 3 (FIX3-BRIEF 1): how retarget runs its re-resolution, without ever awaiting the lock itself:
   * - a GM's card (or no author), nobody acting: directly (the caller, `asCardAuthor`, already queued it, or it is a
   *   direct API call);
   * - a player's card, already acting for that player: inline (the caller is `asCardAuthor`);
   * - a player's card, nobody acting: `runAsAuthor` (queued; a direct API call);
   * - anything else (acting for someone other than the card's author): refused, "try again" (null).
   */
  static async #retargetAs<T>(author: any, fn: () => Promise<T> | T): Promise<T | null> {
    const next = author && !realGm(author) ? author : null;
    if (!next && !actingAuthor) return await fn();
    if (next && actingAuthor && String(next.id) === String(actingAuthor.id)) return await fn();
    if (next && !actingAuthor) return SR2Actor.runAsAuthor(next, fn);
    ui.notifications?.warn?.(tx('SR2E.Notify.Actor.thatCardCanTBeRe'));
    return null;
  }

  /** v0.81.1: the author a re-resolution is acting for (null when none): for the chat handlers and tests. */
  static get actingAuthor(): any {
    return actingAuthor;
  }

  /* ---- v0.22.0: conditions, actions, healing ---- */

  /** v0.70.0: why this actor can't defend itself at all ('paralysed', 'asleep', 'turned to stone'), or ''. */
  helplessStatus(): string {
    const names: Record<string, string> = { paralysis: tx('SR2E.Text.Actor.paralysed'), sleep: tx('SR2E.Text.Actor.asleep'), sr2ePetrified: tx('SR2E.Text.Actor.turnedToStone'), unconscious: tx('SR2E.Text.Actor.unconscious') };
    for (const s of (RULES.FIXES_V70.helplessStatuses as string[])) {
      if (!this.hasStatus?.(s)) continue;
      // The older switches still decide whether paralysis, sleep and petrification hold someone.
      if ((s === 'paralysis' || s === 'sleep') && !RULES.STATUSES.paralysis.blocksActions) continue;
      if (s === 'sr2ePetrified' && !RULES.MAGIC_V61.holdPowers.petrification.blocksActions) continue;
      return names[s] ?? s;
    }
    return '';
  }

  /** v0.70.0: `canAct` reasons that are physical actions (refused while projecting or unmaterialized). */
  static PHYSICAL_ACTS = new Set(['attack', 'drive', 'give first aid', 'take the controls', 'athletics', 'bypass a lock', 'jack in', 'sneak', 'physical test']);

  /**
   * v0.70.0: why this actor is on the astral plane only ('is projecting', 'is not materialized'), or ''.
   * Such a form can't act in the physical world (RULES.FIXES_V70.astralBlocksPhysical).
   */
  astralOnly(): string {
    if (this.type === 'spirit') return this.sys?.materialized === false ? tx('SR2E.Text.Actor.isNotMaterialized') : '';
    return this.sys?.derived?.astralMode === 'projecting' ? tx('SR2E.Text.Actor.isProjectingTheBodyIsEmpty') : '';
  }

  /** Whether this character can act now (unconscious, dying and dead characters cannot). Warns if not. */
  canAct(what = 'act'): boolean {
    const status = this.sys.derived?.status;
    // v0.70.0: a projecting magician or an unmaterialized spirit can't act in the physical world.
    if (RULES.FIXES_V70.astralBlocksPhysical && SR2Actor.PHYSICAL_ACTS.has(what)) {
      const why = this.astralOnly();
      // The older switch still lets a manifested form act (RULES.MAGIC_V56.manifest.blocksPhysical off).
      if (why && !(this.isManifesting() && !RULES.MAGIC_V56.manifest.blocksPhysical)) {
        const label: Record<string, string> = { 'give first aid': tx('SR2E.Card.Actor.firstAid'), 'physical test': tx('SR2E.Card.Actor.physicalTests'), 'take the controls': tx('SR2E.Card.Actor.driving'), drive: tx('SR2E.Card.Actor.driving'), 'bypass a lock': tx('SR2E.Card.Actor.bypassingLocks'), 'jack in': tx('SR2E.Card.Actor.jackingIn'), sneak: tx('SR2E.Card.Actor.sneaking'), attack: tx('SR2E.Card.Actor.attacks') };
        ui.notifications?.warn?.(tx('SR2E.Notify.Actor.inThePhysicalWorld', { name: escHtml(this.name), why, part: what === 'act' ? tx('SR2E.Notify.Actor.itCanTAct') : tx('SR2E.Notify.Actor.no', { label: escHtml(label[what] ?? what) }) }));
        return false;
      }
    }
    // A nature spirit away from its domain (v0.39.0).
    if (this.outOfDomain()) {
      const mode = RULES.MAGIC_V39.domains.enforce;
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.isOutsideItsDomain', { name: escHtml(this.name), domain: escHtml(this.sys.domain), part: mode === 'block' ? tx('SR2E.Notify.Actor.itCannotActHere') : '' }));
      if (mode === 'block') return false;
    }
    // v0.59.0: paralysed or asleep (token statuses) means no actions either.
    if (RULES.STATUSES.paralysis.blocksActions && (this.hasStatus('paralysis') || this.hasStatus('sleep'))) {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.isAndCannot', { name: escHtml(this.name), part: this.hasStatus('paralysis') ? tx('SR2E.Notify.Actor.paralysed') : tx('SR2E.Notify.Actor.asleep'), part2: what === 'act' ? tx('SR2E.Notify.Actor.act') : tx('SR2E.Notify.Actor.doThat', { what }) }));
      return false;
    }
    // v0.61.0: turned to stone (MAGIC_V61.holdPowers.petrification).
    if (RULES.MAGIC_V61.holdPowers.petrification.blocksActions && this.hasStatus('sr2ePetrified')) {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.isTurnedToStoneAndCannot', { name: escHtml(this.name), part: what === 'act' ? tx('SR2E.Notify.Actor.act') : tx('SR2E.Notify.Actor.doThat', { what }) }));
      return false;
    }
    // v0.71.0 (R13): a berserk shaman casts no spells (the totem's rage; the GM still rules the rest).
    if (RULES.FIXES_V71.holds && this.hasStatus('sr2eBerserk') && ['castSpell', 'conjure', 'dispel', 'banish'].includes(what)) {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.isBerserkAndCastsNoSpells', { name: escHtml(this.name) }));
      return false;
    }
    // v0.61.0: an exclusive spell being sustained (MAGIC_V61.exclusive).
    if (what !== 'castSpell') {
      const ex = exclusiveBlock({ sustaining: this.sustained() as any[], action: 'test' });
      if (ex) { ui.notifications?.warn?.(`${escHtml(this.name)}: ${escHtml(ex)}`); return false; }
    }
    if (!RULES.CONDITIONS.blockActions || !incapacitated(status)) return true;
    ui.notifications?.warn?.(tx('SR2E.Notify.Actor.isAndCannot2', { name: escHtml(this.name), status: escHtml(status), part: what === 'act' ? tx('SR2E.Notify.Actor.act') : tx('SR2E.Notify.Actor.doThat', { what }) }));
    return false;
  }

  /**
   * v0.81.0 (D1-8): an exclusive spell being sustained allows no other test (MAGIC_V61.exclusive.blocksAllTests).
   * canAct checks it for actions; the tests that don't go through canAct (perception, social, street, and a sheet's
   * attribute or skill roll) check here.
   */
  #exclusiveBlocks(): boolean {
    const ex = exclusiveBlock({ sustaining: this.sustained() as any[], action: 'test' });
    if (ex) ui.notifications?.warn?.(`${escHtml(this.name)}: ${escHtml(ex)}`);
    return Boolean(ex);
  }

  /**
   * v0.81.0 (D2-13): run a document-changing action once at a time per actor on this client: a double click on
   * Attack, Take dose, Apply patch or Summon would otherwise read the same ammunition, dose or stack twice.
   * A second call while the first runs returns `busy` at once.
   */
  async #oneAtATime<T>(what: string, busy: T, fn: () => Promise<T>): Promise<T> {
    const key = `${this.uuid}:${what}`;
    if (SR2Actor.#busyActions.has(key)) return busy;
    SR2Actor.#busyActions.add(key);
    try { return await fn(); } finally { SR2Actor.#busyActions.delete(key); }
  }

  static #busyActions = new Set<string>();

  /** Actions used in the current combat phase (in simple-action units), if this is that phase. */
  actionsUsed(): number {
    const phase = this.currentPhaseKey();
    const rec = this.getFlag(SYSTEM_ID, 'actions') as { phase: string; used: number } | undefined;
    return phase && rec?.phase === phase ? rec.used : 0;
  }

  /** Whether it is this actor's own action phase in a started combat. */
  isActing(): boolean {
    const c: any = game.combat;
    const a: any = c?.started ? c.combatant?.actor : null;
    if (a && (a === this || a.uuid === this.uuid || (a.id === this.id && !this.isToken))) return true;
    // A delayed action being taken now (v0.35.0).
    return this.actingNow();
  }

  // ---------------------------------------------------------------- Delaying and full defense (v0.35.0)

  /** This actor's combatant in the current combat. */
  myCombatant(): any {
    const c: any = game.combat;
    return c?.combatants?.find?.((x: any) => x.actor?.uuid === this.uuid || (x.actorId === this.id && !this.isToken)) ?? null;
  }

  #combatNow(): { combatId: string | null; round: number; pass: number } {
    const c: any = game.combat;
    return { combatId: c?.started ? c.id : null, round: Number(c?.round ?? 0), pass: Number(c?.pass ?? 0) };
  }

  /** Whether this actor is holding a delayed action this pass. */
  isDelaying(): boolean {
    return delayValid(this.getFlag(SYSTEM_ID, 'delayed') as any, this.#combatNow());
  }

  /** Whether this actor is taking its delayed action right now. */
  actingNow(): boolean {
    return delayValid(this.getFlag(SYSTEM_ID, 'actingNow') as any, this.#combatNow());
  }

  /** Delay: on your own turn, hold your action for later this pass; the turn passes on. */
  async delayAction(): Promise<boolean> {
    const c: any = game.combat;
    const a: any = c?.started ? c.combatant?.actor : null;
    // v0.81.0 (D1-6): an unlinked token's actor shares its base actor's id: compare by uuid (the id only for a base actor's sheet).
    if (!a || !(a === this || a.uuid === this.uuid || (a.id === this.id && !this.isToken))) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.itIsNotSTurn', { name: escHtml(this.name) })); return false; }
    await this.setFlag(SYSTEM_ID, 'delayed', this.#combatNow());
    await ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor: this }), content: `<p><strong>${escText(this.name)}</strong> ${tx('SR2E.Card.Actor.delays', { part: RULES.DELAY.lostAtPassEnd ? tx('SR2E.Card.Actor.untilTheEndOfThisInitiative') : '' })}</p>` });
    try { await c.nextTurn(); } catch (err) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.onlyTheGmCanMoveThe')); console.warn(err); }
    return true;
  }

  /** Take a delayed action now: you act (actions counted to your phase) until you say you're done. */
  async actNow(): Promise<boolean> {
    // v0.75.0 live: two quick clicks both passed the check before either write landed (two "acts now" cards).
    if (SR2Actor.#actNowBusy.has(String(this.uuid)) || !this.isDelaying()) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.hasNoDelayedActionThisPass', { name: escHtml(this.name) })); return false; }
    SR2Actor.#actNowBusy.add(String(this.uuid));
    try {
      await clearFlag(this, 'delayed');
      await this.setFlag(SYSTEM_ID, 'actingNow', this.#combatNow());
    } finally { SR2Actor.#actNowBusy.delete(String(this.uuid)); }
    const cur: any = (game.combat as any)?.combatant;
    await ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor: this }), content: `<p><strong>${escText(this.name)}</strong> ${tx('SR2E.Card.Actor.takesTheDelayedActionNow', { part: cur?.name ? tx('SR2E.Card.Actor.before', { curName: escText(cur.name) }) : '' })}</p>` });
    return true;
  }

  /** v0.75.0: actors taking a delayed action on this client right now (Act now never runs twice at once). */
  static #actNowBusy = new Set<string>();

  /** Done with a delayed action. */
  async endDelayedAction(): Promise<void> {
    await clearFlag(this, 'actingNow');
  }

  /** Whether this actor is on full defense right now. */
  fullDefenseUp(): boolean {
    const c: any = game.combat;
    const flag = this.getFlag(SYSTEM_ID, 'fullDefense') as any;
    if (!c?.started) return false;
    const me = this.myCombatant();
    const idx = me ? (c.turns ?? []).findIndex((t: any) => t.id === me.id) : -1;
    const reached = idx < 0 || (c.turn ?? 0) >= idx;
    return fullDefenseActive(flag, { ...this.#combatNow(), reachedOwnTurn: reached });
  }

  /**
   * Declare full defense (any time): in your own phase it is your action, out of turn it costs your
   * next action (initiative). It lasts until your next action.
   */
  async declareFullDefense(): Promise<boolean> {
    if (this.fullDefenseUp()) { ui.notifications?.info?.(tx('SR2E.Notify.Actor.isAlreadyOnFullDefense', { name: escHtml(this.name) })); return true; }
    const c: any = game.combat;
    const f = RULES.COMBAT.fullDefense;
    const cost = fullDefenseCost({ inCombat: Boolean(c?.started), ownPhase: this.isActing() });
    if (cost === 'action' && !(await this.useAction('fullDefense', tx('SR2E.Card.Actor.fullDefense')))) return false;
    if (cost === 'initiative') {
      const me = this.myCombatant();
      try { if (me && typeof me.initiative === 'number') await c.updateEmbeddedDocuments('Combatant', [{ _id: me.id, initiative: me.initiative - f.initiativeCost }]); }
      catch { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.onlyTheGmCanChangeInitiative')); }
    }
    if (c?.started) await this.setFlag(SYSTEM_ID, 'fullDefense', this.#combatNow());
    await ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor: this }), content: `<p><strong>${escText(this.name)}</strong> ${tx('SR2E.Card.Actor.goesOnFullDefenseDiceAgainst', { attribute: escText(cap(f.attribute)), part: cost === 'initiative' ? tx('SR2E.Card.Actor.initiative', { initiativeCost: f.initiativeCost }) : cost === 'action' ? tx('SR2E.Card.Actor.thatIsTheirAction') : '' })}</p>` });
    return true;
  }

  /** Clear a weapon jam (a Simple action). */
  async clearJam(weaponId: string): Promise<boolean> {
    const w: any = [...this.items].find((i: any) => i.id === weaponId);
    if (!w?.system?.jammed) return false;
    if (!(await this.useAction('clearJam', tx('SR2E.Card.Actor.clearing', { name: w.name })))) return false;
    await w.update({ 'system.jammed': false });
    await ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor: this }), content: `<p>${tx('SR2E.Card.Actor.clearsTheJamIn', { name: escText(this.name), name2: escText(w.name) })}</p>` });
    return true;
  }

  /**
   * Spend an action (RULES.ACTIONS.costs[kind]) in the current phase. Outside a started combat, or
   * with enforcement off, nothing is tracked. Over the limit: a warning, or with 'block' a refusal
   * (the GM can always act). Returns whether to go ahead.
   */
  async useAction(kind: string, label = kind): Promise<boolean> {
    const mode = RULES.ACTIONS.enforce;
    const phase = this.currentPhaseKey();
    if (mode === 'off' || !phase) return true;
    if (!this.isActing()) {
      ui.notifications?.info?.(tx('SR2E.Notify.Actor.itIsNotSActionPhase', { name: escHtml(this.name), label: escHtml(label) }));
      return true;
    }
    const cost = actionCost(kind);
    const r = spendAction(this.actionsUsed(), cost);
    if (!r.ok) {
      const msg = tx('SR2E.Card.Actor.hasLeftThisPhaseNeedsA', { name: this.name, actionsLeftLabel: actionsLeftLabel(this.actionsUsed()), label, cost });
      if (mode === 'block' && !Boolean((game as any).user?.isGM)) {
        ui.notifications?.warn?.(escHtml(msg));
        return false;
      }
      ui.notifications?.warn?.(escHtml(msg));
    }
    await this.setFlag(SYSTEM_ID, 'actions', { phase, used: r.used });
    // v0.55.0: any action but aiming or attacking loses a kept aim.
    if (!/^(aim|draw|fire:|melee|throw)/.test(kind) && this.getFlag?.(SYSTEM_ID, 'aim')) await clearFlag(this, 'aim');
    return true;
  }

  /**
   * First aid on a patient (this actor is the healer): Biotech (or Intelligence at +4) vs TN by the
   * patient's wound (v0.79.0: L4/M6/S8/D10) + the First Aid Table modifiers (RULES.DOCS_V79.firstAidMods 'table';
   * 'medkitDice': a medkit's rating as dice, old). Heals up to half the damage, once per wound,
   * within an hour of the injury; any success stabilises a dying patient.
   */
  async firstAid(patient: any, opts: { track?: 'physical' | 'stun'; medkitId?: string | null; poolDice?: number; ignoreWindow?: boolean; conditions?: 'normal' | 'bad' | 'terrible'; applyMagician?: boolean } = {}): Promise<SuccessTestResult | null> {
    if (!this.canAct('give first aid')) return null;
    const f = RULES.HEALING.firstAid;
    const track = opts.track ?? 'physical';
    const before = (patient?.system?.monitor?.[track] as number | undefined) ?? 0;
    if (before <= 0) {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.hasNoDamage', { patientName: escHtml(patient?.name ?? tx('SR2E.Notify.Actor.thePatient')), track }));
      return null;
    }
    const done = (patient.getFlag?.(SYSTEM_ID, 'firstAidAt') as Record<string, number> | undefined)?.[track];
    // v0.80.0 (RULES.URR_V80.hsFirstAidRetry): a healer with a higher Biotech than any before may try again.
    if (typeof done === 'number' && before <= done && !firstAidRetryAllowed((patient.getFlag?.(SYSTEM_ID, 'firstAidBy') as Record<string, number> | undefined)?.[track], Number(this.findSkill(f.skill)?.system?.rating ?? 0))) {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.sWoundHasAlreadyHadFirst', { patientName: escHtml(patient.name), track }));
      return null;
    }
    // v0.55.0: magic already healed this wound (and it hasn't grown since): first aid can't add to it.
    const magicked = (patient.getFlag?.(SYSTEM_ID, 'healedAt') as Record<string, number> | undefined)?.[track];
    const magicTime = (patient.getFlag?.(SYSTEM_ID, 'healedTime') as Record<string, number> | undefined)?.[track];
    const woundTime = (patient.getFlag?.(SYSTEM_ID, 'damagedAt') as Record<string, number> | undefined)?.[track];
    // Only while no new wound came after the healing spell.
    const stillMagicked = typeof magicked === 'number' && before <= magicked && !(typeof woundTime === 'number' && typeof magicTime === 'number' && woundTime > magicTime);
    if (!RULES.HEALING.firstAid.afterMagic && stillMagicked) {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.sWoundHasBeenHealedBy', { patientName: escHtml(patient.name), track }));
      return null;
    }
    const hurtAt = (patient.getFlag?.(SYSTEM_ID, 'damagedAt') as Record<string, number> | undefined)?.[track];
    const now = sysNow();
    if (!opts.ignoreWindow && typeof hurtAt === 'number' && now - hurtAt > f.windowHours * 3600) {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.moreThanHourHasPassedSince', { windowHours: tCount(f.windowHours, 'SR2E.Count.hour'), patientName: escHtml(patient.name) }));
      return null;
    }
    const t = firstAidTarget(before, track);
    // v0.92.1 (RULES.SHEET_V921.carried): a medkit left behind doesn't help.
    const medkit: any = opts.medkitId ? [...this.items].find((i: any) => i.id === opts.medkitId && isCarried(i)) ?? null : null;
    // v0.79.0 (RULES.DOCS_V79.firstAidMods 'table', SRII First Aid Table): no medkit dice; no medkit +4, bad +1 /
    // terrible +3 conditions, patient is a magician +2, the patient's natural Body 0 / −1 / −2 / −3. 'medkitDice': old.
    const kitDice = firstAidKitDice(medkit?.system?.medkitRating ?? 0);
    const tableMods = firstAidModifiers({ medkit: Boolean(medkit), conditions: opts.conditions ?? 'normal', magician: Number(patient?.system?.magic ?? 0) > 0 && patient?.type !== 'spirit', applyMagician: opts.applyMagician, naturalBody: Number(patient?.system?.attributes?.body?.natural ?? patient?.system?.attributes?.body?.total ?? 0) });
    const sd = this.#skillDice(this.findSkill(f.skill), false, null, f.fallbackAttribute as AttributeKey);
    const faResult = await this.#runTest(tx('SR2E.Card.Actor.firstAidOnWoundHealsUp', { patientName: patient.name, track, level: t.level, maxBoxes: t.maxBoxes, sdSuffix: sd.suffix, part: kitDice ? ` [${medkit.name} +${kitDice}]` : '' }),
      sd.dice + kitDice, { targetNumber: t.tn, modifiers: [...sd.modifiers, ...tableMods, ...SR2Actor.bodyIndexHealingMods(patient)], poolDice: opts.poolDice ?? 0 },
      { kind: 'heal', heal: { targetUuid: patient.uuid, targetName: patient.name, track, before, mode: 'firstAid' } });
    // v0.80.0 (RULES.URR_V80.hsMagicLossUntreated): a magician treated without the +2 may lose Magic.
    if (faResult && magicLossOnTreatment({ magician: Number(patient?.system?.magic ?? 0) > 0 && patient?.type !== 'spirit', applyMagician: opts.applyMagician })) await SR2Actor.urrMagicLossCard(patient, this);
    return faResult;
  }

  /**
   * v0.53.0: the safehouses this actor owns or lives in, with the comfort they give now (lapsed
   * upkeep drops it) and their medical modifier.
   */
  homeSafehouses(): Array<{ uuid: string; name: string; comfort: string; medical: number; workshop: number }> {
    const ids = new Set([this.uuid as string, `Actor.${this.id}`]);
    const now = sysNow();
    return allActors()
      .filter((h: any) => h.type === 'safehouse' && [...(h.system.owners ?? []), ...(h.system.residents ?? [])].some((u: string) => ids.has(u)))
      .map((h: any) => ({
        uuid: h.uuid, name: h.name,
        // Never paid, still owed for building, or lapsed: no comfort bonus and no medical bay.
        ...(() => {
          const st = safehouseUpkeepStatus(Number(h.system.paidUntil ?? -1), now);
          const off = st.lapsed || st.days == null || Number(h.system.derived?.owed ?? 0) > 0;
          return { comfort: safehouseComfort(String(h.system.derived?.comfort ?? 'street'), off), medical: off ? 0 : Number(h.system.derived?.medical ?? 0), workshop: off ? 0 : Number(h.system.derived?.workshop ?? 0) };
        })(),
      }));
  }

  /**
   * Natural healing: Body vs TN by the wound (care modifies it); successes set the hours per box; heals for the hours rested.
   * v0.79.0 (RULES.DOCS_V79.healing 'stages'): Physical heals one wound level per test (Healing Table), after the
   * self-recovery gate (healingGate) and with the Doctoring Table (doctoring). Stun keeps the per-box way.
   */
  async naturalHeal(opts: { track?: 'physical' | 'stun'; hours: number; care?: string; pay?: boolean }): Promise<SuccessTestResult | null> {
    const track = opts.track ?? 'stun';
    // v0.70.0: someone dying and not stabilised can't rest it off: first aid (or a trauma patch) first.
    if (RULES.FIXES_V70.unstabilisedRest === 'block' && this.sys.derived?.status === 'dying' && !this.sys.care?.stabilised) {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.isDyingStabiliseThemFirstAid', { name: escHtml(this.name) }));
      return null;
    }
    const before = (this.sys.monitor?.[track] as number | undefined) ?? 0;
    if (before <= 0) {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.hasNoDamage2', { name: escHtml(this.name), track }));
      return null;
    }
    const care = opts.care ?? 'none';
    // v0.79.0 (RULES.DOCS_V79.healing 'stages', healingGate 'selfTest'; SRII Wound Table and Healing Table): before a
    // Physical wound starts healing, natural Body vs 2 / 4 / 6, no modifiers, once per wound; no successes (or a Deadly
    // wound) = it needs medical attention (any care but 'none') before a stage can be rolled.
    const stages = healsInStages(track);
    if (stages) {
      const sr = this.getFlag?.(SYSTEM_ID, 'selfRecovery') as { boxes: number; ok: boolean; t: number } | undefined;
      const hurtAt = (this.getFlag?.(SYSTEM_ID, 'damagedAt') as Record<string, number> | undefined)?.physical;
      const same = sr && before <= sr.boxes && !(typeof hurtAt === 'number' && hurtAt > sr.t);
      let gate: 'passed' | 'failed' | 'untested' = same ? (sr!.ok ? 'passed' : 'failed') : 'untested';
      const st = selfRecoveryTest(before);
      if (gate === 'untested' && st.tn != null) {
        const gRolls: any[] = [];
        const g = await successTest({ dice: Number(this.sys.attributes.body.natural ?? this.sys.attributes.body.total), targetNumber: st.tn, modifiers: [], roll: foundryRoller(gRolls) });
        gate = g.successes > 0 ? 'passed' : 'failed';
        // The flag is written when the card resolves (#resolvePlain), so a Karma re-roll or a GM's TN change corrects it.
        await this.#post(this.#snapshot(tx('SR2E.Card.Actor.selfRecoveryTestPhysicalWoundNatural', { woundLevel: woundLevel(before) }), g, { kind: 'plain', selfRecovery: { boxes: before, t: sysNow() } }), g, gRolls);
      }
      const can = canRollStage({ boxes: before, care, gate });
      if (!can.ok) {
        ui.notifications?.warn?.(`${escHtml(this.name)}: ${escHtml(can.reason)}`);
        return null;
      }
    }
    // A stay in hospital or intensive care costs nuyen per day (v0.42.0); the GM can waive it.
    // v0.80.0 (review #10): the Revamp's Stun recovery ignores care, so it costs nothing.
    const cost = opts.pay === false || (track === 'stun' && RULES.URR_V80.hsStunRecovery === 'urr') ? 0 : careCost(care, opts.hours);
    if (cost > 0 && !(await this.adjustNuyen(-cost, care === 'intensive' ? tx('SR2E.Text.Actor.intensiveCareDayS', { days: Math.max(1, Math.ceil(opts.hours / 24)) }) : tx('SR2E.Text.Actor.hospitalDayS', { days: Math.max(1, Math.ceil(opts.hours / 24)) })))) {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.canTPayForThatCare', { name: escHtml(this.name), cost: cost.toLocaleString() }));
      return null;
    }
    // v0.79.0: a healing stage under way (flag healStage, same wound, no new damage since): add the rest, no new roll.
    if (stages) {
      const hs = this.getFlag?.(SYSTEM_ID, 'healStage') as { boxes: number; successes: number; stageHours: number; rested: number; t: number; timeFactor?: number } | null | undefined;
      const hurt = (this.getFlag?.(SYSTEM_ID, 'damagedAt') as Record<string, number> | undefined)?.physical;
      if (hs && hs.boxes === before && !(typeof hurt === 'number' && hurt > hs.t)) {
        const rested = Number(hs.rested ?? 0) + Math.max(0, Number(opts.hours) || 0);
        const speaker = ChatMessage.getSpeaker({ actor: this });
        if (rested + 1e-9 >= Number(hs.stageHours)) {
          const to = healingStage({ boxes: before, successes: hs.successes, timeFactor: hs.timeFactor ?? 1 }).toBoxes;
          await clearFlag(this, 'healStage');
          await this.update({ 'system.monitor.physical': to });
          await this.setFlag(SYSTEM_ID, 'restedAt', { ...(this.getFlag?.(SYSTEM_ID, 'restedAt') ?? {}), physical: to });
          await ChatMessage.create({ speaker, content: `<div class="sr2e-card"><p><strong>${escText(this.name)}</strong> ${tx('SR2E.Card.Actor.finishesAHealingStageHOf', { rested, hsStageHours: hs.stageHours, part: cost ? tx('SR2E.Card.Actor.paid', { cost: cost.toLocaleString() }) : '', before, to })}</p></div>` });
        } else {
          await this.setFlag(SYSTEM_ID, 'healStage', { ...hs, rested });
          await ChatMessage.create({ speaker, content: `<div class="sr2e-card"><p><strong>${escText(this.name)}</strong> ${tx('SR2E.Card.Actor.restsHHealingStageOfH', { hours: opts.hours, rested, hsStageHours: hs.stageHours, part: cost ? tx('SR2E.Card.Actor.paid', { cost: cost.toLocaleString() }) : '' })}</p></div>` });
        }
        return null;
      }
    }
    // v0.80.0 (RULES.URR_V80.hsStunRecovery 'urr'): Stun recovery is the higher of Body and Willpower vs 2 + wound modifiers.
    const stunUrr = track === 'stun' ? stunRecoveryTest({ body: Number(this.sys.attributes.body.total), willpower: Number(this.sys.attributes.willpower.total), monitor: this.sys.monitor }) : null;
    const tn = stunUrr ? stunUrr.tn : stages ? stageRest({ boxes: before, successes: 0, hours: 0 }).tn : naturalHealing({ track, boxes: before, successes: 0, hours: 0 }).tn;
    const attr = (stunUrr?.attribute ?? RULES.HEALING.natural.attribute) as AttributeKey;
    const rolls: any[] = [];
    // Like damage resistance, healing takes no wound modifiers.
    // Resting at home: the lifestyle sets the care (v0.42.0).
    // v0.49.0: an overdue rent counts as the street (RULES.UPKEEP.effects.overdueHomeCare).
    // v0.53.0: a safehouse the actor owns or lives in gives its comfort (if better) and its medical bay.
    const own = homeCareLifestyle(String(this.sys.lifestyle?.level ?? 'low'), this.lifestyleStatus().days);
    const home = care === 'home' ? safehouseHomeCare(own, this.homeSafehouses()) : { lifestyle: own, medical: 0, from: '' };
    const life = home.lifestyle;
    // v0.79.0 (RULES.DOCS_V79.doctoring 'table', SRII Doctoring Table): Physical healing takes the Doctoring Table when a
    // doctor is involved (care other than 'none'); Stun, and 'care' (old), keep the care rows and lifestyle home care.
    const doctoring = track === 'physical' ? doctoringModifiers({ care, magician: Number(this.sys.magic ?? 0) > 0, naturalBody: Number(this.sys.attributes.body.natural ?? this.sys.attributes.body.total), naturalWillpower: Number(this.sys.attributes.willpower.natural ?? this.sys.attributes.willpower.total) }) : null;
    const careMods = doctoring ?? (care === 'home'
      ? [...(homeCareModifier(life) ? [{ label: tx('SR2E.Card.Mod.homeLifestyle', { life, part: home.from ? `, ${home.from}` : '' }), value: homeCareModifier(life) }] : []),
        ...(home.medical ? [{ label: tx('SR2E.Card.Mod.medical', { homeFrom: home.from }), value: home.medical }] : [])]
      : careModifiers(care));
    // v0.56.0: an adept's rapid healing adds dice.
    const rapid = rapidHealingDice(adeptSpecialLevel(adeptPowersOf(this) as any, 'rapidHealing'));
    // v0.72.0 (O9): symbiotes add dice to natural healing.
    const sym = Math.max(0, Number(this.sys.derived?.bio?.vitals?.healingDice ?? 0));
    const result = await successTest({ dice: (this.sys.attributes[attr].total as number) + rapid + sym, targetNumber: tn, modifiers: [...(stunUrr ? stunUrr.modifiers : careMods), ...SR2Actor.bodyIndexHealingMods(this)], roll: foundryRoller(rolls) });
    // v0.78.0 (RULES.BOOK_V78.symbiotes 'time'): symbiotes shorten the healing time instead.
    const timeFactor = Math.min(1, Math.max(0.1, Number(this.sys.derived?.bio?.vitals?.healingTimeFactor ?? 1) || 1));
    await this.#post(this.#snapshot(tx('SR2E.Card.Actor.woundHRest', { part: stages ? tx('SR2E.Card.Actor.healingStage') : tx('SR2E.Card.Actor.naturalHealing'), track, woundLevel: woundLevel(before), hours: opts.hours, part2: cost ? tx('SR2E.Card.Actor.paid', { cost: cost.toLocaleString() }) : '', part3: rapid ? tx('SR2E.Card.Actor.rapidHealing', { rapid }) : '', part4: sym ? tx('SR2E.Card.Actor.symbiotes', { sym }) : '', part5: timeFactor < 1 ? tx('SR2E.Card.Actor.symbiotesTime', { timeFactor }) : '' }), result, {
      kind: 'heal', heal: { targetUuid: this.uuid as string, targetName: this.name as string, track, before, mode: 'natural', hours: opts.hours, ...(timeFactor < 1 ? { timeFactor } : {}), ...(stages ? { stages: true } : {}) },
    }), result, rolls);
    return result;
  }

  /**
   * Keep token statuses, sustained spells and dying state in step with the condition monitor.
   * Runs on the client that changed the monitor.
   */
  async syncCondition(prevStatus: string | undefined, grew: { physical: boolean; stun: boolean }): Promise<void> {
    const now = sysNow();
    if (grew.physical || grew.stun) {
      const prev = (this.getFlag(SYSTEM_ID, 'damagedAt') as Record<string, number> | undefined) ?? {};
      await this.setFlag(SYSTEM_ID, 'damagedAt', { ...prev, ...(grew.physical ? { physical: now } : {}), ...(grew.stun ? { stun: now } : {}) });
    }
    const status = this.sys.derived?.status as string | undefined;
    // v0.61.0: hurt in a fight, a shaman of a berserk totem may go berserk (MAGIC_V61.totems).
    if ((grew.physical || grew.stun) && !incapacitated(status) && berserkTriggered(this.totemDrawbacks(), { damaged: true, inCombat: Boolean((game.combat as any)?.started) })) await this.berserkCheck(tx('SR2E.Card.Actor.wounded'));
    // A grunt group: when the grunt in front goes down, the next steps in (v0.32.0).
    const g = this.sys.grunts;
    // A grunt on its own token (v0.44.0) going down: the group tests morale.
    const down3 = ['unconscious', 'dying', 'dead'];
    if (status && status !== prevStatus && down3.includes(status) && !down3.includes(prevStatus ?? '') && (!g || (g.size ?? 1) <= 1)) {
      const grp = this.moraleGroup();
      const prs = grp ? (grp.standing.length ? grp.standing : grp.actors).map((a: any) => Number(a.system?.professionalRating ?? 0)) : [];
      const pr = grp?.mixed ? mixedMoraleRating(prs, Number(grp.standing[0]?.system?.professionalRating ?? 0)) : Number(this.sys.professionalRating ?? 0);
      if (grp && RULES.MORALE.onCasualty && pr > 0 && grp.standing.length > 0) {
        await ChatMessage.create({
          speaker: ChatMessage.getSpeaker({ actor: this }),
          content: `<p><strong>${tx('SR2E.Card.Actor.goesDown', { name: escText(this.name) })}</strong> ${tx('SR2E.Card.Actor.ofTheGroupStanding', { status: escText(status), standingLength: grp.standing.length })}</p><p><button type="button" data-sr2e-action="morale">${tx('SR2E.Card.Actor.moraleTestPrVs', { pr, moraleTarget: moraleTarget({ casualties: grp.down, hurt: false }) })}</button></p>`,
          flags: { [SYSTEM_ID]: { morale: { actorUuid: (grp.standing[0] as any).uuid } } },
        });
      }
    }
    if (g && status && status !== prevStatus && nextGruntSteps(g.size, g.down, status)) {
      const down = (g.down ?? 0) + 1;
      await this.update({ 'system.grunts.down': down, 'system.monitor.physical': 0, 'system.monitor.stun': 0, 'system.care.dyingSince': -1, 'system.care.stabilised': false });
      const left = gruntsStanding(g.size, down);
      const morale = RULES.MORALE.onCasualty && (this.sys.professionalRating ?? 0) > 0;
      await ChatMessage.create({
        speaker: ChatMessage.getSpeaker({ actor: this }),
        content: `<p><strong>${tx('SR2E.Card.Actor.oneOfGoesDown', { name: escText(this.name) })}</strong> ${tx('SR2E.Card.Actor.theNextStepsInStanding', { status: escText(status), left })}</p>${morale ? `<p><button type="button" data-sr2e-action="morale">${tx('SR2E.Card.Actor.moraleTestPrVs2', { professionalRating: escText(this.sys.professionalRating ?? 0), moraleTarget: moraleTarget({ casualties: down, hurt: false }) })}</button></p>` : ''}`,
        flags: { [SYSTEM_ID]: { morale: { actorUuid: this.uuid } } },
      });
      return;
    }
    // Wound icons on the token (v0.36.0): the worst wound level on either track.
    if (RULES.TOKENS.woundIcons) {
      const want = woundStatus(this.sys.monitor);
      for (const id of Object.values(WOUND_STATUS_IDS)) {
        const on = Boolean((this as any).statuses?.has?.(id));
        if (on !== (id === want)) { try { await (this as any).toggleStatusEffect?.(id, { active: id === want }); } catch { /* no such status */ } }
      }
    }
    // v0.70.0: new Physical damage on a dying patient who was stabilised: they need stabilising again (and the
    // clock starts over) (RULES.FIXES_V70.newDamageUnstabilises).
    if (RULES.FIXES_V70.newDamageUnstabilises && status === 'dying' && prevStatus === 'dying' && grew.physical && this.sys.care?.stabilised) {
      await this.update({ 'system.care.stabilised': false, [`flags.${SYSTEM_ID}.dyingAt`]: { t: sysNow(), boxes: 0 } });
      await ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor: this }), content: `<p><strong>${escText(this.name)}</strong> ${tx('SR2E.Card.Actor.isHurtAgainWhileDyingNo')}</p>` });
    }
    if (!RULES.CONDITIONS.statuses || status === prevStatus) return;
    const want = conditionStatuses(status);
    const toggle = async (id: string, active: boolean, overlay = false) => {
      try { await (this as any).toggleStatusEffect?.(id, { active, overlay }); } catch { /* no such status */ }
    };
    await toggle('unconscious', want.unconscious);
    await toggle('bleeding', want.bleeding);
    await toggle('dead', want.dead, true);
    // Dying: note when it began and reset stabilisation; leaving it clears both.
    // v0.70.0: the world time too (RULES.FIXES_V70.dyingOutOfCombat: the boxes come with world time, in or out of combat).
    const round = Number((game.combat as any)?.round ?? 0);
    const nowT = sysNow();
    if (status === 'dying' && prevStatus !== 'dying') await this.update({ 'system.care.dyingSince': round, 'system.care.stabilised': false, [`flags.${SYSTEM_ID}.dyingAt`]: { t: nowT, boxes: 0 } });
    else if (status !== 'dying' && prevStatus === 'dying') await this.update({ 'system.care.dyingSince': -1, 'system.care.stabilised': false, ...clearFlagUpdate(this, 'dyingAt') });
    // v0.61.0: a DocWagon biomonitor calls the team when its wearer is dying (HEALTH_V61.docwagon).
    if (this.sys.docwagon?.tier && RULES.HEALTH_V61.docwagon.enabled && docwagonShouldCall(prevStatus ?? '', status ?? '')) await this.callDocwagon({ auto: true });
    // v0.61.0: bound spirits when their master dies (MAGIC_V61.masterDies): freed, or gone home.
    if (status === 'dead' && prevStatus !== 'dead' && this.type !== 'spirit') await this.#spiritsOnDeath();
    // Combatants: the dead are defeated.
    try {
      const c: any = game.combat;
      const mine = c?.combatants?.filter?.((x: any) => x.actor === this || x.actor?.uuid === this.uuid) ?? [];
      for (const x of mine) if (Boolean(x.defeated) !== want.dead) await x.update({ defeated: want.dead });
    } catch { /* no combat */ }
    // Falling unconscious drops the spells the character sustains personally (not focus-held, quickened or elemental-held).
    const nowDown = incapacitated(status), wasDown = incapacitated(prevStatus);
    if (nowDown && !wasDown && RULES.CONDITIONS.dropSustained) {
      const list = this.sustained();
      const keep = list.filter((x: any) => x.focusId || x.quickened || x.spiritUuid);
      if (keep.length !== list.length) {
        await this.update({ 'system.sustaining': keep });
        await ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor: this }), content: `<p>${tCount(list.length - keep.length, 'SR2E.Card.Actor.isSustainedSpellsDrop', { name: escText(this.name), status: escText(status) })}</p>` });
      }
      // Sustained powers drop too (v0.45.0).
      const n = await this.dropAllPowerEffects();
      if (n) await ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor: this }), content: `<p>${tCount(n, 'SR2E.Card.Actor.sSustainedPowersEnd', { name: escText(this.name) })}</p>` });
    }
    // v0.59.0: down means out of the Matrix and away from the controls.
    if (nowDown && !wasDown && RULES.CONDITIONS.dumpWhenDown) await this.#downedOut(String(status));
    if (status !== 'ok') {
      await ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor: this }), content: `<p><strong>${tx('SR2E.Card.Actor.is', { name: escText(this.name), status: escText(status) })}</strong>${status === 'dying' && bleedRateText() ? ` ${escText(bleedRateText())}` : status === 'dying' ? tx('SR2E.Card.Actor.loses1MorePhysicalBoxEvery', { bodyTotal: escText(this.sys.attributes.body.total), part: RULES.FIXES_V70.dyingOutOfCombat ? tx('SR2E.Card.Actor.secondsOfGameTimeInOr', { value: this.sys.attributes.body.total * RULES.COMBAT_TURN_SECONDS }) : '' }) : status === 'disrupted' ? tx('SR2E.Card.Actor.itIsDrivenBackToIts') : ''}</p>` });
    }
  }

  /**
   * v0.59.0 (RULES.CONDITIONS.dumpWhenDown): a character who goes down is dumped from the Matrix (dump
   * shock) and lets go of a vehicle or site; a jumped-in rigger takes the rigger's dump shock. The dead
   * drop out with no shock to resist.
   */
  async #downedOut(status: string): Promise<void> {
    const dead = status === 'dead' || status === 'disrupted' || status === 'banished';
    if (this.isJackedIn?.()) {
      if (dead) await this.update({ 'system.matrix.jackedIn': false, 'system.matrix.hostUuid': '', ...this.#endRunUpdate() });
      else await this.#dumped(this.currentHost(), tx('SR2E.Card.Actor.is2', { name: this.name, status }));
    }
    const r = this.sys.rigging;
    const v: any = r?.vehicleUuid ? fromUuidSync(r.vehicleUuid) : null;
    if (!v) return;
    const jumped = Boolean(r.jumpedIn);
    try { await this.releaseVehicle({ action: false }); } catch (err) { console.warn('sr2e | release vehicle', err); }
    const ds = dumpShockFor(this, !v.isAboard?.(this));
    const shock = jumped && !dead ? { riggerUuid: this.uuid as string, riggerName: this.name as string, ...ds, kind: 'dump' as const } : null;
    // Letting go of the wheel is already on the vehicle's own card; a rigger dumped out gets the shock card.
    if (!shock) return;
    await ChatMessage.create({
      speaker: ChatMessage.getSpeaker({ actor: this }),
      content: `<p>${tx('SR2E.Card.Actor.isDumpedOutOf', { name: escText(this.name), status: escText(status) })} <strong>${escText(v.name)}</strong>.</p>${shock ? `<p><button type="button" data-sr2e-action="riggerShock">${tx('SR2E.Card.Actor.resistDumpShockVs4', { name: escText(this.name), shockAttr: shockAttr(shock), shockTn: shock.tn, shockLevel: shock.level, shockType: shock.type })}</button></p>` : ''}`,
      ...(shock ? { flags: { [SYSTEM_ID]: { riggerShock: shock } } } : {}),
    });
  }

  /** Extra melee reach from the metatype (trolls). */
  get reachBonus(): number {
    return (this.sys.derived?.reachBonus as number | undefined) ?? 0;
  }

  /** Wound modifier, as a TN modifier list, for tests this actor makes. */
  woundModifiers(): TargetNumberModifier[] {
    if (!this.sys.monitor) return [];
    // v0.72.0 (O20): 'neither' (MAGIC_V72.astralWounds): a projecting magician's wounds don't count on its astral tests.
    if (this.sys.derived?.astralMode === 'projecting' && !astralWoundRules().tests) return [];
    // v0.70.0: the same inputs as the strip, the summary and Initiative (models: `derived.woundModifier`): a pain
    // editor and drugs that ignore wounds or Stun boxes count too. Before, tests used a narrower sum.
    if (['character', 'npc', 'spirit'].includes(this.type)) {
      const drugFx = combineDrugEffects(drugsForBonuses((this.sys.drugs as any[] | undefined) ?? []).map((d: any) => d?.extra ?? {}));
      if (drugFx.ignoreWounds) return [];
      const edited = painEditedMonitor(this.sys.monitor, Boolean(this.sys.derived?.bio?.ignoreStunWounds));
      const m = { ...edited, stun: Math.max(0, Number(edited.stun ?? 0) - drugFx.stunIgnoreBoxes) };
      return woundTnModifiers(compensatedMonitor(painToleranceMonitor(m, (this.sys.derived?.vitals ?? { painIgnoreBoxes: 0, painExtraBoxes: 0 })), ((this.sys.derived?.bio?.ignoreBoxes as number | undefined) ?? 0) + ((this.sys.derived?.painIgnore as number | undefined) ?? 0)));
    }
    // Damage compensators ignore the first boxes on each track (v0.30.0).
    // Adept pain resistance ignores boxes too (v0.39.0).
    return woundTnModifiers(compensatedMonitor(painToleranceMonitor(this.sys.monitor, (this.sys.derived?.vitals ?? { painIgnoreBoxes: 0, painExtraBoxes: 0 })), ((this.sys.derived?.bio?.ignoreBoxes as number | undefined) ?? 0) + ((this.sys.derived?.painIgnore as number | undefined) ?? 0)));
  }

  /** Body Index makes a patient harder to heal (RULES.BIOWARE.bodyIndex). */
  static bodyIndexHealingMods(patient: any): TargetNumberModifier[] {
    const bi = (patient?.system?.derived?.bodyIndex?.used as number | undefined) ?? 0;
    const v = bodyIndexHealingTn(bi);
    return v ? [{ label: tx('SR2E.Card.Mod.bodyIndex', { bi }), value: v }] : [];
  }

  /** Switch an adrenal pump on or off; switching it off brings the crash (a card with a resist button). */
  async setAdrenalPump(itemId: string, on: boolean): Promise<void> {
    const it: any = [...this.items].find((i: any) => i.id === itemId);
    if (!it || it.system.bioKind !== 'adrenalPump') return;
    if (Boolean(it.system.bioActive) === on) return;
    await it.update({ 'system.bioActive': on });
    if (on) {
      await ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor: this }), content: `<p><strong>${tx('SR2E.Card.Actor.sKicksIn', { name: escText(this.name), name2: escText(it.name) })}</strong></p>` });
      return;
    }
    const c = adrenalCrash(it.system.rating ?? 1);
    await ChatMessage.create({
      speaker: ChatMessage.getSpeaker({ actor: this }),
      content: `<p>${tx('SR2E.Card.Actor.sShutsDownTheCrashComes', { name: escText(this.name), name2: escText(it.name) })}</p><p><button type="button" data-sr2e-action="adrenalCrash">${tx('SR2E.Card.Actor.resistTheCrashVsStun', { attribute: escText(cap(c.attribute)), tn: c.tn, level: c.level })}</button></p>`,
      flags: { [SYSTEM_ID]: { adrenalCrash: { actorUuid: this.uuid, rating: it.system.rating ?? 1 } } },
    });
  }

  /** The adrenal pump's crash: the attribute vs its TN, Stun staged down by successes. */
  async rollAdrenalCrash(rating: number): Promise<void> {
    const c = adrenalCrash(rating);
    await this.#drainTest({ label: tx('SR2E.Card.Actor.adrenalPumpCrash'), attribute: c.attribute as AttributeKey, targetNumber: c.tn, level: c.level, type: 'stun', poolDice: 0, noun: 'damage' });
  }

  /**
   * Surgery to install cyberware or bioware: the surgeon's skill vs RULES.BIOWARE.surgery's TN for its grade.
   * Successes divide the recovery time; none means complications (Physical damage to the patient).
   */
  async surgery(itemId: string, opts: { surgeon?: any; care?: string; pay?: boolean } = {}): Promise<SuccessTestResult | null> {
    const it: any = [...this.items].find((i: any) => i.id === itemId);
    if (!it || it.type !== 'cyberware') return null;
    const who: SR2Actor = opts.surgeon ?? this;
    const sg = RULES.BIOWARE.surgery;
    const sd = who.#skillDice(who.findSkill(sg.skill), false, null, 'intelligence');
    const points = it.system.bioware ? it.system.bodyIndex ?? 0 : it.system.essenceCost ?? 0;
    return who.#runTest(tx('SR2E.Card.Actor.surgeryInto', { name: it.name, name2: this.name, grade: it.system.grade, sdSuffix: sd.suffix }), sd.dice, {
      targetNumber: surgeryTarget(it.system.grade), modifiers: sd.modifiers,
    }, { kind: 'surgery', surgery: { id: (foundry as any).utils?.randomID?.() ?? Math.random().toString(36).slice(2, 18), patientUuid: this.uuid as string, patientName: this.name as string, itemId, itemName: it.name, points,
      care: opts.care ?? RULES.BIOWARE.recovery.defaultCare, pay: opts.pay !== false } });
  }

  /** v0.48.0: change a recovering patient's care; the days left stretch or shrink (RULES.BIOWARE.recovery.care). */
  async setRecoveryCare(itemId: string, care: string): Promise<number | null> {
    const now = sysNow();
    const list: any[] = [...(this.sys.recovering ?? [])].map((r: any) => ({ ...r }));
    const r = list.find((x) => x.itemId === itemId);
    if (!r) return null;
    const lifestyle = String(this.sys.lifestyle?.level ?? '');
    const to = careFactor(care, lifestyle);
    const from = Number(r.factor) > 0 ? Number(r.factor) : 1;
    const until = rescaleRecovery(Number(r.until), from, to, now);
    // Paid care (hospital, intensive) for the days left under the new care, less what the old care cost for them.
    const leftOld = Math.max(0, Math.ceil((Number(r.until) - now) / 86400));
    const leftNew = Math.max(0, Math.ceil((until - now) / 86400));
    // Only care actually paid for is refunded.
    const newCost = recoveryCareCost(care, leftNew);
    const diff = newCost - (r.paid ? recoveryCareCost(String(r.care ?? ''), leftOld) : 0);
    if (diff > 0 && !(await this.adjustNuyen(-diff, tx('SR2E.Text.Actor.careFor', { name: r.name, days: plural(leftNew, 'day') })))) return null;
    if (diff < 0) await this.adjustNuyen(-diff, tx('SR2E.Text.Actor.careForRefund', { name: r.name }));
    r.paid = newCost > 0;
    r.until = until;
    r.care = care;
    r.factor = to;
    await this.update({ 'system.recovering': list });
    const days = Math.max(0, Math.ceil((r.until - now) / 86400));
    const label = RULES.HEALING.natural.care.find((c) => c.id === care)?.label ?? care;
    await ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor: this }), content: `<p>${tx('SR2E.Card.Actor.recoversFromUnderNewCareLeft', { name: escText(this.name), name2: escText(r.name), label: escText(label), plural: escText(plural(days, 'day')) })}</p>` });
    return days;
  }

  /** v0.54.0 (GM): apply a surgery result the surgeon's player couldn't (they don't own the patient). */
  static async applySurgeryAsGm(surgeonUuid: string, snap: TestSnapshot): Promise<boolean> {
    if (!isGmNow()) return false;
    const surgeon: any = await fromUuid(surgeonUuid);
    if (!(surgeon instanceof SR2Actor) || !snap?.surgery) return false;
    // v0.81.1 (RA2-1, D1-2, SEC1-7): the card says which operation; what it already did (installed, paid, how much)
    // comes only from the patient's own surgeryState flag, which only an owner (the GM here) writes.
    const patient: any = fromUuidSync(String(snap.surgery.patientUuid ?? ''));
    const sgOk = SR2Actor.surgeryFromCard(snap.surgery, patient, true);
    if (!sgOk) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.thatSurgeryCardDoesnTName')); return false; }
    snap = { ...SR2Actor.#cleanSnapshot(snap), successes: safeInt(snap.successes, 0, 40, 0), surgery: sgOk };
    const r = await surgeon.#resolveSurgery(snap);
    await ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor: surgeon }), content: `<p><strong>${tx('SR2E.Card.Actor.surgeryApplied')}</strong> ${tx('SR2E.Card.Actor.into', { sgOkItemName: escText(sgOk.itemName), sgOkPatientName: escText(sgOk.patientName) })}</p>${r.html}`, flags: { [SYSTEM_ID]: r.flags ?? {} } });
    return true;
  }

  /**
   * v0.81.1 (RA2-1, D1-2, SEC1-7): an operation as a card names it, re-derived from the documents. The item must be
   * cyberware on the patient (its Essence or Body Index gives the points); the care must be one of the table's;
   * what the operation already did (installed, harmed, paid, paidAmount, traumaDone) comes only from the patient's
   * `surgeryState` flag, never from the card. A card with no operation id keeps its own state (a card from before
   * v0.54.0) unless `strict` (the GM's Apply), which refuses it. Null when it names nothing real.
   */
  static surgeryFromCard(raw: any, patient: any, strict = false): NonNullable<TestSnapshot['surgery']> | null {
    if (!raw || typeof raw !== 'object' || !patient || !isActorDoc(patient)) return null;
    const id = typeof raw.id === 'string' && raw.id.length > 0 && raw.id.length <= 64 ? raw.id : '';
    if (strict && !id) return null;
    const it: any = [...(patient.items ?? [])].find((i: any) => i.id === raw.itemId && i.type === 'cyberware');
    if (strict && !it) return null;
    const careIds = (RULES.HEALING.natural.care as readonly any[]).map((c: any) => String(c.id));
    const care = raw.care === '' || careIds.includes(String(raw.care ?? '')) ? String(raw.care) : String(RULES.BIOWARE.recovery.defaultCare ?? '');
    const points = it ? Number(it.system?.bioware ? it.system?.bodyIndex ?? 0 : it.system?.essenceCost ?? 0) || 0 : Math.max(0, Math.min(6, Number(raw.points) || 0));
    const saved = id ? (patient.getFlag?.(SYSTEM_ID, 'surgeryState') as Record<string, any> | undefined)?.[id] : undefined;
    const st = id ? (saved ?? {}) : raw;
    return {
      ...(id ? { id } : {}), patientUuid: String(patient.uuid), patientName: String(patient.name ?? ''), itemId: String(it?.id ?? raw.itemId ?? ''),
      itemName: String(it?.name ?? raw.itemName ?? '').slice(0, 200), points, care, pay: Boolean(raw.pay),
      installed: Boolean(st.installed), harmed: Boolean(st.harmed), paid: Boolean(st.paid), paidAmount: safeInt(st.paidAmount, 0, 10_000_000, 0), traumaDone: Boolean(st.traumaDone),
    };
  }

  /**
   * v0.81.1 (RA2-1, SEC1-7): what applying a surgery card does with money, as plain text for the GM's confirm
   * ("¥1,200 charged to Bob", "no money changes hands"), worked out as applySurgeryAsGm will (state from the patient).
   */
  static surgeryApplyMoney(snap: any): string {
    const patient: any = fromUuidSync(String(snap?.surgery?.patientUuid ?? ''));
    const sg = SR2Actor.surgeryFromCard(snap?.surgery, patient, true);
    if (!sg) return tx('SR2E.Text.Actor.itNamesNoCyberwareThePatient');
    const base = recoveryDays(sg.points, safeInt(snap?.successes, 0, 40, 0));
    if (base === null) return tx('SR2E.Text.Actor.complicationsNoMoneyChangesHands');
    const lifestyle = String(patient?.system?.lifestyle?.level ?? '');
    const days = sg.care ? recoveryWithCare(base, sg.care, lifestyle) : base;
    const owed = sg.pay ? recoveryCareCost(sg.care ?? '', days) : 0;
    const diff = owed - (sg.paid ? Number(sg.paidAmount ?? 0) : 0);
    return diff > 0 ? tx('SR2E.Text.Actor.forCareChargedTo', { diff: diff.toLocaleString(), name: patient.name }) : diff < 0 ? tx('SR2E.Text.Actor.ofCareRefundedTo', { diff: (-diff).toLocaleString(), name: patient.name }) : tx('SR2E.Text.Actor.noMoneyChangesHands');
  }

  async #resolveSurgery(snapIn: TestSnapshot): Promise<Resolved> {
    const patient: any = fromUuidSync(String(snapIn.surgery!.patientUuid ?? ''));
    // v0.54.0: what this operation already did (installed, harmed, paid), as kept on the patient.
    // v0.81.1 (RA2-1): only as kept on the patient (surgeryFromCard), never as the card says.
    const sg0 = SR2Actor.surgeryFromCard(snapIn.surgery, patient);
    if (!sg0) return { html: `<p><em>${tx('SR2E.Card.Actor.thePatientOrTheItemIs')}</em></p>`, flags: {}, snap: snapIn };
    const snap: TestSnapshot = { ...snapIn, surgery: sg0 };
    const sg = sg0;
    const keepState = async (n: any) => {
      if (!sg.id || !canWriteNow(patient)) return;
      await patient.setFlag(SYSTEM_ID, 'surgeryState', { [sg.id]: { installed: Boolean(n.installed), harmed: Boolean(n.harmed), paid: Boolean(n.paid), paidAmount: Number(n.paidAmount ?? 0), traumaDone: Boolean(n.traumaDone) } });
    };
    // v0.54.0: a surgeon's player who doesn't own the patient posts the result for the GM to apply.
    if (patient && !canWriteNow(patient)) {
      const gms = [...((game as any).users ?? [])].filter((u: any) => u.isGM).map((u: any) => u.id);
      // v0.81.1 (D1-7): a re-roll's card replaces the earlier unapplied ones (the GM applies only the newest), as heal does.
      if (snap.testId) {
        for (const m of [...(((game as any).messages?.contents ?? []) as any[])].slice(-200)) {
          const f = m.getFlag?.(SYSTEM_ID, 'surgeryApply');
          if (f?.snap?.testId === snap.testId && !m.getFlag?.(SYSTEM_ID, 'surgeryApplied') && canWriteNow(m)) { try { await m.setFlag(SYSTEM_ID, 'surgeryApplied', 'superseded'); } catch { /* not ours */ } }
        }
      }
      await ChatMessage.create({
        speaker: ChatMessage.getSpeaker({ actor: this }), whisper: gms,
        content: `<p><em>${tx('SR2E.Card.Actor.gmOnly')}</em> ${tx('SR2E.Card.Actor.sSurgeryOnSuccessEs', { name: escText(this.name), sgPatientName: escText(sg.patientName), sgItemName: escText(sg.itemName), successes: safeInt(snap.successes, 0, 999, 0) })}</p><p><button type="button" data-sr2e-action="applySurgery">${tx('SR2E.Card.Actor.applyGm')}</button></p>`,
        flags: { [SYSTEM_ID]: { surgeryApply: { surgeonUuid: this.uuid, snap } } },
      });
      return { html: `<p>${tx('SR2E.Card.Actor.isnTYoursTheGmApplies', { sgPatientName: escText(sg.patientName) })}</p>`, flags: {}, snap };
    }
    const base = recoveryDays(sg.points, snap.successes);
    // v0.48.0: the patient's care stretches or shortens the recovery.
    const care = sg.care ?? '';
    const lifestyle = String(patient?.system?.lifestyle?.level ?? '');
    const factor = care ? careFactor(care, lifestyle) : 1;
    const days = base === null ? null : care ? recoveryWithCare(base, care, lifestyle) : base;
    const next = { ...sg };
    if (days === null) {
      // v0.81.0 (D1-1): an earlier roll of this operation already put it in (a GM's TN change can drop the
      // successes to none): no complications on top, and nothing undone here.
      if (sg.installed) return { html: `<p><em>${tx('SR2E.Card.Actor.isAlreadyInFromAnEarlier', { sgItemName: escText(sg.itemName) })}</em></p>`, flags: {}, snap: { ...snap, surgery: next } };
      let note = '';
      if (!sg.harmed && patient) {
        const level = RULES.BIOWARE.surgery.failureLevel as DamageLevel;
        const r = applyDamageToMonitor({ physical: patient.system.monitor.physical, stun: patient.system.monitor.stun }, 'physical', level, Number(patient.system.derived?.vitals?.overflowBody ?? patient.system.attributes.body.total));
        await patient.update({ 'system.monitor.physical': r.monitor.physical });
        note = tx('SR2E.Card.Actor.takesPhysical', { sgPatientName: escText(sg.patientName), level, plural: escText(plural(r.boxes, 'box')) });
        next.harmed = true;
      }
      await keepState(next);
      return { html: `<p><strong>${tx('SR2E.Card.Actor.complications')}</strong> ${tx('SR2E.Card.Actor.isNotInYet', { sgItemName: escText(sg.itemName), note })}</p>`, flags: {}, snap: { ...snap, surgery: next } };
    }
    let rejectHtml = '';
    let traumaNote = '';
    let flags: Record<string, unknown> = {};
    const now = sysNow();
    if (!sg.installed && patient) {
      const it: any = [...patient.items].find((i: any) => i.id === sg.itemId);
      if (it && !it.system.installed) await it.update({ 'system.installed': true });
      next.installed = true;
      // v0.55.0 (Shadowtech, optional): the operation itself wounds the patient by its size, once.
      const tr = !sg.traumaDone ? surgicalTrauma(Number(sg.points ?? 0)) : null;
      if (tr) {
        const r = applyDamageToMonitor({ physical: patient.system.monitor.physical, stun: patient.system.monitor.stun }, tr.type, tr.level, Number(patient.system.derived?.vitals?.overflowBody ?? patient.system.attributes.body.total));
        await patient.update({ 'system.monitor.physical': r.monitor.physical, 'system.monitor.stun': r.monitor.stun });
        next.traumaDone = true;
        traumaNote = tx('SR2E.Card.Actor.theOperationLeavesWithAWound', { sgPatientName: escText(sg.patientName), trLevel: tr.level, trType: tr.type, plural: escText(plural(r.boxes, 'box')) });
      }
      // v0.45.0: it works once the patient has recovered; a re-roll moves the date.
      await patient.update({ 'system.recovering': [...(patient.system.recovering ?? []).filter((r: any) => r.itemId !== sg.itemId), { itemId: sg.itemId, name: sg.itemName, until: now + days * 86400, care, factor }] });
      const bi = patient.system.derived?.bodyIndex;
      if (it?.system?.bioware && bi && sensitiveRejectionTn(rejectionTn(Number(bi.used ?? 0), Number(bi.max ?? 0)), Number(bi.used ?? 0), patient.system.derived?.vitals ?? { sensitive: false }) !== null) {
        rejectHtml = `<p>${tx('SR2E.Card.Actor.bodyIndexOfTheBodyMay', { biUsed: escText(bi.used), biMax: escText(bi.max) })} <button type="button" data-sr2e-action="rejectionTest">${tx('SR2E.Card.Actor.rejectionTest')}</button></p>`;
        flags = { rejection: { actorUuid: patient.uuid } };
      }
    } else if (patient && sg.installed) {
      const list = [...(patient.system.recovering ?? [])];
      const i = list.findIndex((r: any) => r.itemId === sg.itemId);
      if (i >= 0) { list[i] = { ...list[i], until: now + days * 86400, care, factor }; await patient.update({ 'system.recovering': list }); }
    }
    // v0.48.0: paid care (hospital, intensive) for the recovery days, charged once.
    // A re-roll that changes the days charges or refunds the difference.
    let careNote = '';
    const owed = sg.pay && patient ? recoveryCareCost(care, days) : 0;
    const diff = owed - (sg.paid ? Number(sg.paidAmount ?? 0) : 0);
    if (diff !== 0 && patient && (sg.pay || sg.paid)) {
      const ok = await patient.adjustNuyen?.(-diff, tx('SR2E.Text.Actor.careAfterSurgery', { itemName: sg.itemName, days: plural(days, 'day') }));
      if (ok) { next.paid = true; next.paidAmount = owed; careNote = diff > 0 ? tx('SR2E.Card.Actor.careCosts', { diff }) : tx('SR2E.Card.Actor.ofCareRefunded', { value: -diff }); }
      else careNote = ` <em>${tx('SR2E.Card.Actor.canTPayForCare', { sgPatientName: escText(sg.patientName), diff })}</em>`;
    }
    // Mark the recovery as paid (or not) so changing the care later refunds only what was paid.
    if (patient && care && recoveryCareCost(care, 1) > 0) {
      const list = [...(patient.system.recovering ?? [])].map((x: any) => ({ ...x }));
      const j = list.findIndex((x: any) => x.itemId === sg.itemId);
      const paidNow = Boolean(next.paid && Number(next.paidAmount ?? 0) >= owed && owed > 0);
      if (j >= 0 && Boolean(list[j].paid) !== paidNow) { list[j].paid = paidNow; await patient.update({ 'system.recovering': list }); }
    }
    await keepState(next);
    const careLabel = care ? RULES.HEALING.natural.care.find((c) => c.id === care)?.label ?? care : '';
    return { html: `<p><strong>${tx('SR2E.Card.Actor.isInstalled', { sgItemName: escText(sg.itemName) })}</strong> ${tx('SR2E.Card.Actor.recoversIn', { sgPatientName: escText(sg.patientName) })} <strong>${tCount(days, 'SR2E.Card.Actor.days')}</strong>${careLabel ? ` (${escText(careLabel.toLowerCase())})` : ''}${RULES.BIOWARE.recovery.inactive ? tx('SR2E.Card.Actor.itWorksFromThen') : ''}.${traumaNote}${careNote}</p>${rejectHtml}`, flags, snap: { ...snap, surgery: next } };
  }

  /** Active and inactive foci carried by this actor. */
  foci(): Focus[] {
    // v0.80.0 (RULES.URR_V80.magAdeptFoci, URR): physical adepts can use only weapon foci.
    return fociOf(this, String(this.sys?.tradition ?? '')) as Focus[];
  }

  get tradition(): Tradition {
    return (this.sys.tradition ?? 'none') as Tradition;
  }

  /** Spells this actor is sustaining. */
  sustained(): SustainedSpell[] {
    return [...(this.sys.sustaining ?? [])];
  }

  /** Stop sustaining a spell (by its index in the list). */
  async dropSustained(index: number): Promise<void> {
    const list = this.sustained();
    if (index < 0 || index >= list.length) return;
    list.splice(index, 1);
    await this.update({ 'system.sustaining': list });
  }

  /** Assense: an astral perception test (Intelligence by default) vs a TN; successes are reported. */
  async assense(opts: { targetNumber?: number; label?: string; targetUuid?: string | null; exclude?: string[] } = {}): Promise<SuccessTestResult | null> {
    if (!this.canAct('assense')) return null;
    if (!this.isAstral()) {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.mustBePerceivingOrProjectingAstrally', { name: escHtml(this.name) }));
      return null;
    }
    const target: any = opts.targetUuid ? await fromUuid(opts.targetUuid) : null;
    // A masked initiate is harder to read.
    const masking = target?.initiate ? maskingModifiers(target.initiate.grade, target.initiate.techniques) : [];
    const attr = RULES.MAGIC.assensingAttribute as AttributeKey;
    // v0.56.0: what the successes reveal about a subject (RULES.MAGIC_V56.assensing), whispered to the assenser and the GM.
    const result = await this.#runTest(opts.label ?? tx('SR2E.Card.Actor.assensing', { part: target ? ` ${target.name}` : '' }), this.sys.attributes[attr].total as number, {
      targetNumber: opts.targetNumber ?? RULES.MAGIC.assensingTn, background: true, modifiers: masking, ...(opts.exclude?.length ? { exclude: opts.exclude } : {}),
    }, target ? { kind: 'assense', assense: { targetUuid: target.uuid as string, targetName: target.name as string }, privateTo: this.#ownersAndGms() } : { kind: 'plain' });
    return result;
  }

  /** v0.56.0: what an assensing test's successes reveal about its subject (re-rolls show the new reading). */
  async #resolveAssense(snap: TestSnapshot): Promise<Resolved> {
    const a = snap.assense!;
    const t: any = await fromUuid(a.targetUuid);
    if (!t) return { html: `<p><em>${tx('SR2E.Card.Actor.theSubjectIsGone')}</em></p>`, flags: {}, snap };
    const sceneId = SR2Actor.currentSceneId();
    const subject: AssenseSubject = {
      name: t.name, physical: Number(t.system?.monitor?.physical ?? 0), stun: Number(t.system?.monitor?.stun ?? 0), status: String(t.system?.derived?.status ?? 'ok'),
      essence: Number(t.system?.derived?.essence ?? t.system?.essence ?? 0), magic: Number(t.system?.derived?.magic ?? 0),
      awakened: Number(t.system?.derived?.magic ?? 0) > 0 || t.type === 'spirit', tradition: t.type === 'spirit' ? 'spirit' : String(t.system?.tradition ?? ''),
      cyberware: [...(t.items ?? [])].filter((i: any) => i.type === 'cyberware' && i.system?.installed).map((i: any) => String(i.name)),
      foci: [...(t.items ?? [])].filter((i: any) => i.type === 'focus' && i.system?.active).map((i: any) => `${i.name} (${i.system.focusType} ${i.system.rating})`),
      sustained: typeof t.sustained === 'function' ? t.sustained().map((e: any) => `${e.spellName} (Force ${e.force})`) : [],
      signatures: sceneId ? SR2Actor.signaturesAt(sceneId).filter((x) => x.actorUuid === t.uuid).map((x) => x.label) : [],
    };
    const lines = assensingReveals(snap.successes, subject, { essence: Number(this.sys.derived?.essence ?? 6), magic: Number(this.sys.derived?.magic ?? 0) });
    if (!lines.length) return { html: `<p><em>${tx('SR2E.Card.Actor.learnsNothingAbout', { name: escText(this.name), targetName: escText(a.targetName) })}</em></p>`, flags: {}, snap };
    return { html: `<p><strong>${tx('SR2E.Card.Actor.sAura', { targetName: escText(a.targetName) })}</strong></p><ul>${lines.map((l) => `<li>${escText(l)}</li>`).join('')}</ul>`, flags: {}, snap };
  }

  /** Roll a pure attribute test (e.g. Body, Willpower). */
  async rollAttribute(key: AttributeKey, opts: TestOptions & { limbId?: string | null; resist?: boolean } = {}): Promise<SuccessTestResult | null> {
    if (!ATTRIBUTE_KEYS.includes(key)) throw new Error(`Unknown attribute: ${key}`);
    // v0.70.0: no physical attribute test while projecting or unmaterialized (an astral form uses its own).
    if (['body', 'quickness', 'strength'].includes(key) && !opts.astralAct && !this.canAct('physical test')) return null;
    // v0.81.0 (D1-8, R2-DOC 1): an exclusive spell allows no other test, a mental one included (resistance tests go
    // through #drainTest and #post, not here). v0.81.1 (D1-10): `resist` marks a resistance roll made here (a GM's
    // inline "Willpower vs 6 to resist the fear"): an exclusive spell doesn't stop resisting.
    if (!opts.resist && this.#exclusiveBlocks()) return null;
    // A Quickness test made with a cyberlimb uses the limb's own Quickness (v0.43.0).
    const limb = this.limbFor(opts.limbId ?? null, key);
    const rating = limb ? limb.quickness : this.sys.attributes[key].total as number;
    const { limbId: _l, ...rest } = opts;
    const qm = qualityModifiers(this.sys.qualities ?? [], { attribute: key });
    if (qm.length) rest.modifiers = [...(rest.modifiers ?? []), ...qm];
    return this.#runTest(`${opts.label ?? game.i18n.localize(`SR2E.Attribute.${key}`)}${limb ? ` (${limb.name} ${limb.quickness})` : ''}`, rating, rest);
  }

  /**
   * Roll a skill test. With `useSpecialization` the specialization rating is rolled instead.
   * An unrated skill defaults to `relatedSkillId` (+2 TN) if given and rated, else to the
   * linked attribute (+4 TN).
   */
  async rollSkill(skillIn: any, opts: TestOptions & { useSpecialization?: boolean; relatedSkillId?: string | null; useConcentration?: boolean; complementarySkillId?: string | null; helperUuids?: string[]; open?: boolean;
    /** v0.58.0: the task's base time (÷ successes on the card), Build/Repair tools (needed, at hand), and a language test (Read/Write; the complexity sets the TN). */
    baseTime?: { value: number; unit: string } | null; tools?: { need: string; have: string } | null; language?: { readWrite?: boolean; complexity?: string } | null } = {}): Promise<SuccessTestResult | null> {
    // A better slotted skillsoft stands in (not when rolling the skill's specialization or concentration).
    const best = !skillIn?.soft && !opts.useSpecialization && !opts.useConcentration && skillIn?.name ? this.findSkill(skillIn.name) : null;
    const skill = best?.soft ? best : skillIn;
    // v0.70.0: a physical skill (Body, Quickness, Strength or Reaction) can't be used while projecting or unmaterialized.
    if (['body', 'quickness', 'strength', 'reaction'].includes(String(skill?.system?.attribute ?? '')) && skill?.system?.kind !== 'knowledge' && skill?.system?.kind !== 'language'
      && !this.canAct('physical test')) return null;
    // v0.81.0 (D1-8, R2-DOC 1): an exclusive spell allows no other test (Etiquette, a knowledge skill, Negotiation...).
    if (this.#exclusiveBlocks()) return null;
    // v0.58.0: a job that needs tools (house rule: can't be done without), checked before anyone rolls.
    if (opts.tools && toolsModifier(opts.tools.need, opts.tools.have).blocked) {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.canTDoThisWithoutTools', { name: escHtml(this.name) }));
      return null;
    }
    const { dice, modifiers, suffix } = this.#skillDice(skill, opts.useSpecialization, opts.relatedSkillId, 'quickness', { useConcentration: opts.useConcentration });
    if (opts.open) return this.#openTest(`${opts.label ?? skill.name}${suffix}`, dice);
    // A complementary skill rolled first, and helpers (teamwork), add dice (RULES.STREET.tests, v0.44.0).
    let extra = 0;
    const notes: string[] = [];
    const tn = opts.targetNumber ?? 4;
    if (opts.complementarySkillId) {
      const comp: any = this.items.get?.(opts.complementarySkillId) ?? [...this.items].find((i: any) => i.id === opts.complementarySkillId);
      if (comp && comp.id !== skill?.id) {
        const cd = this.#skillDice(comp, false, null, 'quickness');
        const rolls: any[] = [];
        const r = await successTest({ dice: cd.dice, targetNumber: tn, modifiers: this.#testModifiers({ modifiers: cd.modifiers }), roll: foundryRoller(rolls) });
        const add = complementaryDice(r.successes);
        extra += add;
        notes.push(`${comp.name} +${add}`);
        await ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor: this }), rolls, content: `${describeResult(tx('SR2E.Card.Actor.complementary', { compName: comp.name, cdSuffix: cd.suffix }), r)}<p>${tx('SR2E.Card.Actor.adds')} <strong>${add}</strong> ${tCount(add, 'SR2E.Card.Actor.diceTo', { skillName: escText(skill?.name ?? tx('SR2E.Card.Actor.theTest')) })}</p>` });
      }
    }
    if (opts.helperUuids?.length) {
      const got: number[] = [];
      const rows: string[] = [];
      const rolls: any[] = [];
      for (const u of opts.helperUuids) {
        const h: any = await fromUuid(u);
        // v0.81.0 (D1-6): by uuid only: another unlinked token of the same base actor can help.
        if (!h || h === this || h.uuid === this.uuid || !h.helpRoll) continue;
        const r: SuccessTestResult = await h.helpRoll(skill?.name ?? '', tn, rolls);
        got.push(r.successes);
        rows.push(describeResult(tx('SR2E.Card.Actor.helps', { name: h.name }), r));
      }
      const add = teamworkDice(got, skill?.system?.rating ?? 0);
      if (rows.length) {
        extra += add;
        notes.push(tx('SR2E.Card.Actor.teamwork', { add }));
        await ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor: this }), rolls, content: `${rows.join('')}<p>${tx('SR2E.Card.Actor.teamworkAdds')} <strong>${add}</strong> ${tCount(add, 'SR2E.Card.Actor.diceToS', { name: escText(this.name), skillName: escText(skill?.name ?? tx('SR2E.Card.Actor.test')), part: RULES.STREET.tests.teamwork.cap === 'rating' ? tx('SR2E.Card.Actor.atMost', { skillRating: escText(skill?.system?.rating ?? 0) }) : '' })}</p>` });
      }
    }
    // v0.58.0: tools for a Build/Repair job, Read/Write at a lower rating, and the base time.
    const more: TargetNumberModifier[] = [];
    if (opts.tools) {
      const t = toolsModifier(opts.tools.need, opts.tools.have);
      if (t.modifier) more.push(t.modifier);
    }
    let rwCut = 0;
    if (opts.language?.readWrite) {
      const r = Number(skill?.system?.rating ?? 0);
      rwCut = r > 0 ? Math.max(0, r - readWriteRating(r)) : 0;
      if (rwCut) notes.push(tx('SR2E.Card.Actor.readWrite', { value: r - rwCut }));
    }
    const ctx: Partial<TestSnapshot> & { kind: TestSnapshot['kind'] } = { kind: 'plain',
      ...(opts.baseTime && opts.baseTime.value > 0 ? { timed: { base: opts.baseTime.value, unit: opts.baseTime.unit } } : {}),
      ...(opts.language ? { reveal: { kind: 'language' as const, what: opts.language.readWrite ? 'reading' : 'listening' } } : {}),
      // v0.80.0 (RULES.URR_V80.coreKnowledgeTest): the knowledge table's outcome on the card.
      ...(urrCoreKnowledgeCard(String(skill?.system?.kind ?? ''), Boolean(opts.language)) ? { reveal: { kind: 'knowledge' as const } } : {}) };
    return this.#runTest(`${opts.label ?? skill.name}${suffix}${notes.length ? ` [${notes.join(', ')}]` : ''}`, Math.max(0, dice + extra - rwCut), { ...opts, modifiers: [...(opts.modifiers ?? []), ...modifiers, ...more] }, ctx);
  }

  /** A helper's roll for teamwork (v0.44.0): the same skill (or its default) vs the leader's TN; the caller posts it. */
  async helpRoll(skillName: string, tn: number, rolls: any[]): Promise<SuccessTestResult> {
    const sd = this.#skillDice(this.findSkill(skillName), false, null, 'quickness', { skillName });
    return successTest({ dice: sd.dice, targetNumber: tn, modifiers: this.#testModifiers({ modifiers: sd.modifiers }), roll: foundryRoller(rolls) });
  }

  /** An open test (v0.44.0): no TN; the highest die (sixes added up) is the result, and the TN of the opposing test. */
  async #openTest(label: string, dice: number): Promise<SuccessTestResult> {
    const rolls: any[] = [];
    const list = await rollOpenEnded(Math.max(0, dice), foundryRoller(rolls));
    const result = openTestResult(list);
    await ChatMessage.create(withRollMode({
      speaker: ChatMessage.getSpeaker({ actor: this }), rolls,
      content: `<div class="sr2e-roll"><h3>${tx('SR2E.Card.Actor.openTest', { label: escText(label) })}</h3><p>${tx('SR2E.Card.Actor.dice', { dice, list: list.map((d) => `<span class="sr2e-die">${escText(d.faces.join('+'))}${d.faces.length > 1 ? `=${d.total}` : ''}</span>`).join(' ') })}</p></div><p>${tx('SR2E.Card.Actor.result')} <strong>${result}</strong>${tx('SR2E.Card.Actor.theTnOfTheOpposingTest')}</p>`,
    }));
    return { baseTargetNumber: 0, modifiers: [], targetNumber: result, targetNumberClamped: false, totalDice: dice, dice: list, successes: 0, botch: false };
  }

  /** An open test on an attribute (v0.44.0). */
  async openAttributeTest(key: AttributeKey): Promise<SuccessTestResult> {
    return this.#openTest(cap(key), (this.sys.attributes?.[key]?.total as number | undefined) ?? 0);
  }

  /**
   * v0.48.0: the skill a possessed body tests with (RULES.OCCULT.metamagic.possessing.skills): a
   * stand-in from the possessor's copied skills, the body's own, or a zero-rated stand-in (defaults).
   */
  possessedSkill(skill: any | undefined, name?: string): any | undefined {
    const by = this.getFlag?.(SYSTEM_ID, 'possessedBy') as { name?: string; skills?: SkillCopy[] } | undefined;
    if (!by?.skills || skill?.soft || skill?.possessed) return skill;
    const wanted = String(skill?.name ?? name ?? '').trim().toLowerCase();
    if (!wanted) return skill;
    const theirs = by.skills.find((x) => String(x.name).trim().toLowerCase() === wanted) ?? null;
    const choice = possessedSkillChoice(skill ? { rating: Number(skill.system?.rating ?? 0), attribute: String(skill.system?.attribute ?? ''), kind: String(skill.system?.kind ?? 'active') } : null, theirs);
    if (choice === 'body') return skill;
    const slug = wanted.replace(/[^a-z0-9]+/g, '-');
    if (choice === 'none') {
      if (!skill) return skill;
      return { id: `poss-${slug}`, name: skill.name, type: 'skill', possessed: true, possessorName: by.name ?? '', system: { ...skill.system, rating: 0, specializationRating: 0, concentrationRating: 0 } };
    }
    return { id: `poss-${slug}`, name: theirs!.name, type: 'skill', possessed: true, possessorName: by.name ?? '', system: { ...theirs } };
  }

  /** Dice and modifiers for using a skill item (or defaulting), plus a note for the card title. */
  #skillDice(skillIn: any | undefined, useSpecialization?: boolean, relatedSkillId?: string | null, fallbackAttribute: AttributeKey = 'quickness', more: { useConcentration?: boolean; skillName?: string; limbId?: string | null } = {}) {
    const skill = this.possessedSkill(skillIn, more.skillName);
    const attrKey = (skill?.system.attribute ?? fallbackAttribute) as AttributeKey;
    // A cyberlimb's own Quickness for a test made with it (v0.43.0).
    const limb = this.limbFor(more.limbId ?? null, attrKey);
    const related = relatedSkillId ? this.items.get(relatedSkillId) : null;
    // The Skill Web (v0.38.0): defaulting costs more the further the related skill is.
    const relatedTn = related ? relatedDefaultTn(getSkillWeb(), skill?.name ?? more.skillName ?? '', related.name) : null;
    // v0.80.0 (RULES.URR_V80.coreSubSkillDefault, coreWebAttributes): skillTestDice in the book.
    const r = urrCoreSkillTestDice({
      ...urrCoreAttributeTn(getSkillWeb(), skill?.name ?? more.skillName ?? '', attrKey),
      rating: skill?.system.rating ?? 0,
      specializationRating: skill?.system.specializationRating ?? 0,
      useSpecialization: Boolean(useSpecialization),
      concentrationRating: skill?.system.concentrationRating ?? 0,
      useConcentration: Boolean(more.useConcentration),
      // v0.58.0: vehicle skills link to Reaction.
      attributeRating: limb ? limb.quickness : skillAttributeRating(attrKey, this.sys.attributes ?? {}, Number(this.sys.derived?.reaction ?? 0)),
      related: related && related.type === 'skill' && relatedTn !== null ? { name: related.name, rating: related.system.rating } : null,
      ...(relatedTn !== null ? { relatedTn } : {}),
    });
    const attrName = attrKey.charAt(0).toUpperCase() + attrKey.slice(1);
    // Adept powers that improve a skill add dice whenever the skill (or its specialization) is used.
    const adept = skill && (r.using === 'skill' || r.using === 'specialization') ? adeptSkillDice(adeptPowersOf(this), skill.name) : 0;
    // Tailored pheromones help social skills (RULES.CYBERWARE.pheromones).
    const pher = skill ? pheromoneDice(skill.name, (this.sys.derived?.cyber?.pheromones as number | undefined) ?? 0) : 0;
    // v0.45.0: an encephalon helps Intelligence and knowledge skills; enhanced articulation physical ones.
    const usingSkill = Boolean(skill) && ['skill', 'specialization', 'concentration'].includes(r.using);
    const enc = usingSkill ? encephalonDice(Number(this.sys.derived?.cyber?.encephalon ?? 0), { attribute: attrKey, kind: skill?.system?.kind ?? 'active' }) : 0;
    // v0.78.0 (RULES.BOOK_V78.encephalon 'shadowtech'): its Intelligence bonus counts when defaulting to Intelligence on a skill it helps.
    const encInt = r.using === 'attribute' && !limb && attrKey === 'intelligence' && encephalonFits({ attribute: attrKey, kind: skill?.system?.kind ?? 'active' })
      ? encephalonIntelligence(Number(this.sys.derived?.cyber?.encephalon ?? 0)) : 0;
    const art = usingSkill && physicalSkill(attrKey) ? Number(this.sys.derived?.bio?.physicalSkillDice ?? 0) : 0;
    const suffix =
      r.using === 'specialization' ? ` (${skill.system.specialization} ${skill.system.specializationRating})`
      : r.using === 'concentration' ? ` (${skill.system.concentration} ${skill.system.concentrationRating})`
      : r.using === 'related' ? tx('SR2E.Text.Actor.defaultingTo', { name: related.name })
      : r.using === 'attribute' ? (limb ? tx('SR2E.Text.Actor.noSkillLimb', { attrName, quickness: limb.quickness, limb: limb.name }) : tx('SR2E.Text.Actor.noSkill', { attrName }))
      : '';
    const soft = skill?.soft ? tx('SR2E.Text.Actor.skillsoft', { chipName: skill.chipName }) : skill?.possessed ? tx('SR2E.Text.Actor.sSkill', { name: skill.possessorName || tx('SR2E.Text.Actor.thePossessor') }) : '';
    // Edges and flaws on this skill (or the attribute defaulted to) (v0.44.0).
    const qm = qualityModifiers(this.sys.qualities ?? [], { skill: skill?.name ?? more.skillName, ...(r.using === 'attribute' ? { attribute: attrKey } : {}) });
    // v0.61.0: gear and cyberware that help a named skill (climbing gear, a reflex recorder...).
    const gearName = String(skill?.name ?? more.skillName ?? '');
    const gear = gearName ? skillGearBonus((this.sys.derived?.cyber?.skillMods ?? []) as any[], { name: gearName, specialization: r.using === 'specialization' ? skill?.system?.specialization : '', concentration: r.using === 'concentration' ? skill?.system?.concentration : '' }) : { dice: 0, modifiers: [], names: [] };
    // v0.79.0: `base` = the rating actually rolled (skill, specialization, concentration, related skill or attribute),
    // without bonus dice: the Combat Pool cap (RULES.DOCS_V79.rangedPoolCap, SRII p. 83) is measured against it.
    return { base: Math.max(0, r.dice), dice: Math.max(0, r.dice + adept + pher + enc + encInt + art + gear.dice), modifiers: [...(r.modifier ? [r.modifier] : []), ...qm, ...gear.modifiers], suffix: `${suffix}${soft}${adept ? tx('SR2E.Text.Actor.adept', { adept }) : ''}${pher ? tx('SR2E.Text.Actor.pheromones', { pher }) : ''}${enc ? tx('SR2E.Text.Actor.encephalon', { enc }) : ''}${encInt ? tx('SR2E.Text.Actor.encephalonIntelligence', { encInt }) : ''}${art ? tx('SR2E.Text.Actor.articulation', { art }) : ''}${gear.dice ? ` (${gear.names.join(', ')} +${gear.dice})` : ''}` };
  }

  /** Initiate grade and metamagic techniques known. */
  get initiate(): { grade: number; techniques: string[] } {
    const mm = this.sys.metamagic ?? {};
    return { grade: (this.sys.initiateGrade as number | undefined) ?? 0, techniques: Object.keys(mm).filter((k) => mm[k]) };
  }

  /** Modifiers for this actor's own test: given ones, wounds, sustaining, and centering for magical tests. */
  #testModifiers(opts: TestOptions): TargetNumberModifier[] {
    // v0.50.0: modifiers switched off in the dialog's preview are dropped, wherever they came from.
    // v0.89.5: by key (`modKey`, the row's id where it has one), a label from a list saved earlier still matching.
    const off = new Set(opts.exclude ?? []);
    const all = this.#allTestModifiers(opts);
    return off.size ? all.filter((m) => !modIn(off, m)) : all;
  }

  /** Centering on a magical test: automatic, or (v0.56.0) from a centering test rolled just before. */
  #centering(penalties: TargetNumberModifier[]): TargetNumberModifier[] {
    if (centeringMode(this.sys.centeringSkill) === 'auto') return centeringModifiers(this.initiate.grade, this.initiate.techniques, penalties);
    if (!this.initiate.techniques.includes('centering')) return [];
    const total = penalties.filter((m) => m.value > 0 && (modifierIs(m, 'wounds', /^Wounds/) || modifierIs(m, 'sustaining', /^Sustaining/))).reduce((n, m) => n + m.value, 0);
    const cut = centeringCut(this.centeredSuccesses(), this.initiate.grade, total);
    return cut > 0 ? [{ id: 'centering', label: tx('SR2E.Card.Mod.centering'), value: -cut }] : [];
  }

  #allTestModifiers(opts: TestOptions): TargetNumberModifier[] {
    // v0.50.0: IC, frames and agents roll free of their token's statuses (RULES.TN_AUTO.matrix.icNoPenalties).
    if (this.type === 'ic' && RULES.TN_AUTO.matrix.icNoPenalties) return [...(opts.modifiers ?? [])];
    const penalties = opts.noPenalties ? [] : [...this.woundModifiers(), ...sustainingModifiers(this.sustained())];
    const centering = opts.magical ? this.#centering(penalties) : [];
    // Background count, aspected and toxic sources (v0.39.0).
    const bg = opts.magical || opts.background ? backgroundCountModifiers(this.backgroundInfo().penalty) : [];
    const extra: TargetNumberModifier[] = [];
    // Allergies the critter is exposed to (v0.39.0).
    const al = this.type === 'vehicle' ? { value: 0, names: [] as string[] } : allergyTn(this.critterTraits());
    if (al.value && !opts.noPenalties) extra.push({ label: tx('SR2E.Card.Mod.allergy', { alNames: al.names.join(', ') }), value: al.value });
    // Focus addiction withdrawal: an addict's magic without an active focus (v0.39.0).
    if (opts.magical && this.getFlag?.(SYSTEM_ID, 'focusAddict') && !this.foci().some((f) => f.active)) {
      extra.push({ id: 'focusWithdrawal', label: tx('SR2E.Card.Mod.focusWithdrawal'), value: RULES.MAGIC_V39.addiction.withdrawalTn });
    }
    // v0.61.0: a totem that dislikes daylight (Owl) (MAGIC_V61.totems).
    if (!opts.noPenalties) { const dl = daylightModifier(this.totemDrawbacks(), sysNow()); if (dl) extra.push(dl); }
    // Drug withdrawal (v0.42.0).
    if (!opts.noPenalties && this.sys.addictions?.length) extra.push(...withdrawalModifiers(this.sys.addictions as Addiction[], sysNow()));
    // v0.45.0: recovering from surgery, and a ghoul or vampire going hungry.
    if (!opts.noPenalties && this.sys.recovering?.length) {
      const r = recoveryTn(this.sys.recovering as Recovery[], sysNow());
      if (r) extra.push({ id: 'recoveringFromSurgery', label: tx('SR2E.Card.Mod.recoveringFromSurgery'), value: r });
    }
    const hu = !opts.noPenalties && this.type !== 'vehicle' ? this.hungerInfo() : null;
    if (hu?.hungry) extra.push({ label: tx('SR2E.Card.Mod.hungerDays', { huDays: hu.days }), value: hu.tn });
    // v0.56.0: powers and spells on this actor that make every test harder (Confusion, Fear...).
    if (!opts.noPenalties) for (const e of ((this.getFlag?.(SYSTEM_ID, 'powerEffects') as FxEntry[] | undefined) ?? [])) {
      const v = Number(e.testsTn ?? 0);
      if (v) extra.push({ label: `${e.special ? powerModifierLabel(e.special) : e.name} (${e.fromName})`, value: v });
    }
    // v0.70.0: drugs in effect that change the TN of the user's own tests (v0.61.0 drug extras; before, shown only).
    // v0.72.0 (O8): one entry per drug (old doubled-up doses count once).
    if (!opts.noPenalties) for (const d of drugsForBonuses((this.sys.drugs as any[] | undefined) ?? [])) {
      const v = drugEffectBundle(d?.extra ?? {}).testsTn;
      if (v) extra.push({ label: `${d.name || tx('SR2E.Card.Actor.drug')}`, value: v });
    }
    // v0.50.0: a decker's Matrix test, or a jumped-in rigger's vehicle test, isn't seen with the body's eyes.
    // Every Matrix test rolls with the Hacking Pool, so that marks one too.
    const matrix = Boolean(opts.matrix) || opts.pool === 'hacking';
    const bodyStatuses = !(matrix && RULES.TN_AUTO.matrix.skipBodyStatuses) && !(opts.vehicle && RULES.TN_AUTO.rigging.skipBodyStatuses && this.isJumpedIn());
    // Astral perception makes every physical test harder, not only attacks (v0.39.0).
    if (bodyStatuses && RULES.MAGIC_V39.perceiving.allTests && !opts.magical && !opts.background && !opts.astralAct && !this.sys.derived?.dualNatured
      && this.sys.derived?.astralMode === 'perceiving' && !(opts.modifiers ?? []).some((m) => modifierIs(m, 'astralPerception', 'Astral perception'))) {
      extra.push(...perceivingModifiers('perceiving'));
    }
    // v0.50.0: Blinded counts once (attacks and spells pass their own, perception has it in its sight modifiers).
    const blind = bodyStatuses && !opts.sightHandled && !(opts.modifiers ?? []).some((m) => modifierIs(m, 'blinded', 'Blinded') || modifierIs(m, 'flash', 'Flash')) ? this.blindMods('other') : [];
    return [...(opts.modifiers ?? []), ...penalties, ...centering, ...bg, ...extra, ...blind];
  }

  /** Roll this actor's own test (wound modifiers apply), spend pool dice, then post it. */
  async #runTest(
    label: string,
    dice: number,
    opts: TestOptions,
    context: Partial<TestSnapshot> & { kind: TestSnapshot['kind'] } = { kind: 'plain' },
  ): Promise<SuccessTestResult> {
    const pool = opts.pool ?? 'combat';
    // v0.92.0: a Spell Pool spend inside Sorcery's concentration or specialization may take their narrow dice too.
    const narrowSpend = pool === 'spell' && opts.spellUse && (opts.spellUse.conc || opts.spellUse.spec) ? opts.spellUse : null;
    const poolMax = narrowSpend ? this.spellPoolFor(narrowSpend) : ((this.sys.derived?.[`${pool}PoolLeft`] as number | undefined) ?? 0);
    const poolDice = Math.max(0, Math.min(opts.poolDice ?? 0, poolMax));
    // v0.80.0 (RULES.URR_V80.coreKarmaDice): extra dice bought from the Karma Pool, one point a die (0 in the book).
    const karmaDice = urrCoreKarmaDice(opts.karmaDice, Number(this.sys.derived?.karmaPoolLeft ?? 0));
    if (karmaDice > 0) {
      label = tx('SR2E.Card.Actor.karma', { label, karmaDice });
      await this.update({ 'system.karma.poolSpent': Number(this.sys.karma?.poolSpent ?? 0) + karmaDice });
    }
    const rolls: any[] = [];
    // An aspected background count aligned with this magician adds dice to magic (v0.39.0).
    const aligned = opts.magical || opts.background ? this.backgroundInfo().bonusDice : 0;
    if (aligned) label = tx('SR2E.Card.Actor.aspectedBackground', { label, aligned });
    const result = await successTest({
      dice: dice + aligned + karmaDice,
      poolDice,
      targetNumber: opts.targetNumber ?? 4,
      modifiers: this.#testModifiers(opts),
      roll: foundryRoller(rolls),
    });
    // v0.56.0: a centering test is used up by the next magical test.
    if (opts.magical && context.kind !== 'centering' && this.centeredSuccesses() > 0) {
      try { await clearFlag(this, 'centered'); } catch { /* not saved */ }
    }
    // v0.78.0: the Task Pool refreshes each Combat Turn, so outside combat it isn't used up.
    if (poolDice > 0 && narrowSpend) await this.#spendSpellPool(poolDice, narrowSpend);
    else if (poolDice > 0 && !(pool === 'task' && !(game as any).combat?.started)) await this.#spendPool(pool, poolDice);
    await this.#post(this.#snapshot(label, result, context), result, rolls);
    return result;
  }

  #snapshot(label: string, result: SuccessTestResult, context: Partial<TestSnapshot> & { kind: TestSnapshot['kind'] }): TestSnapshot {
    // v0.50.0: a test keeps its id through Karma re-rolls and GM TN changes (a later card with it replaces this one).
    return withResult({ actorUuid: this.uuid as string, label, rerolls: 0, testId: `t${Date.now().toString(36)}${Math.random().toString(36).slice(2, 8)}`, ...context } as TestSnapshot, result);
  }

  /**
   * Work out what a test's successes mean (hit/miss, damage to apply, follow-up buttons).
   * Shared by the original roll and any Karma Pool re-roll of it, so both behave the same.
   */
  async #resolve(snapIn: TestSnapshot, fu: FollowUps = {}): Promise<Resolved> {
    const snap = await this.#applyPowerEffect(await this.#applySustain(snapIn));
    const r = await this.#resolveKind(snap, fu);
    if (r.snap.repeat) {
      r.html += `<p><button type="button" data-sr2e-action="repeatPower">${tx('SR2E.Card.Actor.useAgainRepeatsEachTurn')}</button></p>`;
      r.flags = { ...r.flags, repeat: r.snap.repeat };
    }
    return r;
  }

  /**
   * A sustained power that changes attributes and is not resisted (v0.45.0): put its effect on each
   * target once it succeeds; a Karma re-roll updates it (or takes it off on a failure).
   */
  async #applyPowerEffect(snap: TestSnapshot): Promise<TestSnapshot> {
    const fx = snap.powerEffect;
    if (!fx) return snap;
    const s = snap.successes;
    if (s <= 0) {
      if (fx.effectId) for (const u of fx.targetUuids) await SR2Actor.setPowerEffect(u, null, fx.effectId);
      // v0.56.0: a spell's effect id is its Sustaining entry's: keep it, so a later success uses the same one.
      return { ...snap, powerEffect: { ...fx, effectId: fx.kind === 'spell' ? fx.effectId : undefined as any } };
    }
    const id = fx.effectId || SR2Actor.#newId();
    for (const u of fx.targetUuids) await SR2Actor.setPowerEffect(u, SR2Actor.fxEntry(fx, s, id, this.uuid as string, this.name as string));
    return { ...snap, powerEffect: { ...fx, effectId: id } };
  }

  /** Record a sustained spell once its test succeeds (also after a Karma re-roll), and keep its successes current. */
  async #applySustain(snap: TestSnapshot): Promise<TestSnapshot> {
    const ctx = snap.sustain;
    if (!ctx) return snap;
    const s = snap.successes;
    const list = this.sustained();
    const now = sysNow();
    const permanentAt = ctx.permanent ? permanentUntil(now, ctx.force, s, SR2Actor.secondsPerTurn()) ?? -1 : -1;
    if (!ctx.applied) {
      if (s <= 0) return snap;
      await this.update({ 'system.sustaining': [...list, { spellName: ctx.spellName, force: ctx.force, category: ctx.category, focusId: ctx.focusId, successes: s, quickened: false, targetUuids: [...(ctx.targetUuids ?? [])],
        effectId: ctx.effectId ?? '', permanentAt, exclusive: Boolean(ctx.exclusive) }] });
      // v0.72.0 (O17): a Mana or Physical Barrier spell raises a barrier at its Force (MAGIC_V72.barrierSpells).
      if (ctx.barrier && ctx.effectId) await this.#raiseBarrierSpell(ctx, s);
      return { ...snap, sustain: { ...ctx, applied: true } };
    }
    // v0.56.0: the entry with this spell's effect id, else (older cards) the first by name and Force.
    const i = ctx.effectId ? list.findIndex((e: any) => e.effectId === ctx.effectId) : list.findIndex((e) => e.spellName === ctx.spellName && e.force === ctx.force);
    // v0.50.0: a GM's TN change can turn it into a failure: the spell drops.
    if (s <= 0) {
      if (i >= 0) { list.splice(i, 1); await this.update({ 'system.sustaining': list }); }
      return { ...snap, sustain: { ...ctx, applied: false } };
    }
    if (i >= 0 && (list[i]!.successes !== s || (ctx.permanent && (list[i] as any).permanentAt !== permanentAt))) {
      list[i] = { ...list[i]!, successes: s, ...(ctx.permanent ? { permanentAt } : {}) } as any;
      await this.update({ 'system.sustaining': list });
      // v0.72.0 (O17): a barrier rated by successes follows a re-roll.
      if (ctx.barrier && ctx.effectId && RULES.MAGIC_V72.barrierSpells.rating === 'successes') {
        const b: any = SR2Actor.barrierOfSpell(ctx.effectId);
        const r = barrierSpellRating(ctx.force, s);
        if (canWriteNow(b)) await b.update({ 'system.rating': r, 'system.baseRating': r });
      }
    }
    return snap;
  }

  /** v0.72.0 (O17): the barrier actor a sustained barrier spell raised (by its effect id), if any. */
  static barrierOfSpell(effectId: string): any | null {
    if (!effectId) return null;
    return allActors().find((a: any) => a.type === 'barrier' && a.getFlag?.(SYSTEM_ID, 'barrierSpell')?.effectId === effectId) ?? null;
  }

  /** v0.72.0 (O17): raise a barrier spell's barrier actor and offer to draw it on the map (like a ward). */
  async #raiseBarrierSpell(ctx: NonNullable<TestSnapshot['sustain']>, successes: number): Promise<void> {
    if (SR2Actor.barrierOfSpell(ctx.effectId!)) return;
    const data = barrierSpellActorData({ kind: ctx.barrier!, force: ctx.force, successes, spellName: ctx.spellName, casterUuid: this.uuid as string, casterName: this.name as string, effectId: ctx.effectId, systemId: SYSTEM_ID });
    const radius = barrierSpellRadius({ force: ctx.force, magic: Number(this.sys.derived?.magic ?? 0) });
    const canCreate = canCreateActorNow();
    if (!canCreate) {
      await ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor: this }), content: `<p><strong>${escText(ctx.spellName)}</strong> ${tx('SR2E.Card.Actor.raisesARatingAboutM', { barrierKind: escText(data.system.barrierKind), rating: data.system.rating, radius })} <button type="button" data-sr2e-action="createSpirit">${tx('SR2E.Card.Actor.createItGm')}</button></p><p class="hint">${tx('SR2E.Card.Actor.thenDrawItOnTheMap')}</p>`, flags: { [SYSTEM_ID]: { pendingSpirit: data } } });
      return;
    }
    const cls: any = (Actor as any).implementation ?? Actor;
    const made: any = await cls.create({ ...data, ownership: { ...((this as any).ownership ?? {}) } });
    if (!made) return;
    await ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor: this }), content: `<p><strong>${escText(ctx.spellName)}</strong> ${tx('SR2E.Card.Actor.raisesItFallsWhenTheSpell', { madeName: escText(made.name) })} <button type="button" data-sr2e-action="placeWard">${tx('SR2E.Card.Actor.drawItOnTheMap')}</button></p>`, flags: { [SYSTEM_ID]: { wardPlace: { barrierUuid: made.uuid, name: made.name, radius } } } });
  }

  async #resolveKind(snap: TestSnapshot, fu: FollowUps): Promise<Resolved> {
    const s = snap.successes;
    switch (snap.kind) {
      case 'attack': {
        const list = snap.attackTargets ?? (snap.attack ? [snap.attack] : []);
        if (snap.blast && !list.length) {
          // Every blast scatters (Nd6 by range, less per success); the button rolls it and finds who is caught.
          const b = { ...snap.blast, successes: Math.max(0, s) };
          const dice = blastScatterDice(U80C.cbtScatterDice(b as any, scatterDiceV79(b.scatterType, scatterDiceFor(b.range))), Boolean(b.bounce));
          return {
            html: `<p>${s > 0 ? tx('SR2E.Card.Actor.scatterD6MM', { plural: escText(plural(s, 'success')), dice, value: s * U80C.cbtScatterPerSuccess(b as any), part: b.smart ? tx('SR2E.Card.Actor.smartMMore', { value: s * RULES.GEAR.grenades.smart.metresPerSuccess }) : '' }) : `<em>${tx('SR2E.Card.Actor.noSuccessesItScattersD6M', { dice })}</em>`}${b.fuse === 'airburst' ? tx('SR2E.Card.Actor.airburst', { airburstScatterFactor: RULES.GEAR.grenades.airburst.scatterFactor }) : ''}</p>
              <p><button type="button" data-sr2e-action="blastScatter">${tx('SR2E.Card.Actor.detonate')}</button></p>`,
            flags: { blast: b }, snap,
          };
        }
        if (!list.length) return { html: snap.blast ? `<p><em>${tx('SR2E.Card.Actor.noOneIsCaughtInThe')}</em></p>` : '', flags: {}, snap };
        // Opposed melee: even with no successes the defender rolls, and may counterattack.
        const opposed = opposedMelee(list[0]);
        if (s <= 0 && !(opposed && RULES.COMBAT.melee.counterattack)) return { html: `<p><em>${tx('SR2E.Card.Actor.theAttackMissed')}</em></p>`, flags: {}, snap };
        const attacks: AttackState[] = list.map((a) => ({ ...a, attackSuccesses: Math.max(0, s), targetNumber: snap.targetNumber, ...(snap.ram?.level ? { ram: snap.ram } : {}) }));
        const attack = attacks[0]!;
        // Cybercombat: the target defends first if it can (RULES.MATRIX.defense), else the hit lands now.
        if (attack.matrix && !SR2Actor.matrixCanDefend(fromUuidSync(attack.targetUuid))) return this.#matrixHit(snap, attack, 0, false);
        if (attack.noDodge && !attack.matrix) {
          // No dodge (cybercombat, blasts, or elemental spells when dodging is off): each target resists straight away.
          const damages: DamageState[] = attacks.map((a) => {
            const outcome = a.fixedDamage
              ? U80C.cbtBlastStaged({ power: a.power, level: a.level, successes: s })
              : resolveAttack({ attackSuccesses: s, defenseSuccesses: 0, power: a.power, level: a.level });
            return {
              targetUuid: a.targetUuid, melee: false, damageType: a.damageType, power: outcome.power, level: outcome.level as DamageLevel,
              ...(a.matrix ? { matrix: true } : {}), ...(a.black ? { black: true } : {}), ...(a.elemental ? { elemental: true } : {}),
              ...armorExtras(a),
            };
          });
          if (attack.fixedDamage) {
            const rows = damages.map((d, i) => `<li>${escText(fromUuidSync(d.targetUuid)?.name ?? tx('SR2E.Card.Actor.target'))}: <strong>${d.power}${d.level}</strong> <button type="button" data-sr2e-action="resist" data-index="${i}">${tx('SR2E.Card.Actor.resist')}</button></li>`).join('');
            return { html: `<p><strong>${tx('SR2E.Card.Actor.blast')}</strong></p><ul class="sr2e-blast">${rows}</ul>`, flags: { damage: damages[0], damages }, snap };
          }
          const d0 = damages[0]!;
          const what = attack.black ? tx('SR2E.Card.Actor.toTheDecker', { d0DamageType: damageWord(d0.damageType) }) : attack.matrix ? tx('SR2E.Card.Actor.matrixDamage') : tx('SR2E.Card.Actor.damageTypeDot', { damageType: damageWord(d0.damageType) });
          const buttons = damages.map((d, i) => `<button type="button" data-sr2e-action="resist" data-index="${i}">${tx('SR2E.Card.Actor.resist2', { name: escText(fromUuidSync(d.targetUuid)?.name ?? tx('SR2E.Card.Actor.target')) })}</button>`).join(' ');
          const ee = attacks.length === 1 ? elementEffectExtras(attack, attack.targetUuid) : { html: '', flags: {} };
          return {
            html: `<p>${outcomeWord('hit')} ${tCount(s, 'SR2E.Card.Actor.netSuccesses')} <strong>${d0.power}${d0.level}</strong>${escText(what)}</p><p>${buttons}${ee.html}</p>`,
            flags: { damage: d0, damages, ...ee.flags }, snap,
          };
        }
        const buttons = attacks.map((a, i) => `<button type="button" data-sr2e-action="defend" data-index="${i}">${tx('SR2E.Card.Actor.defend', { name: escText(fromUuidSync(a.targetUuid)?.name ?? tx('SR2E.Card.Actor.target')), part: a.power !== attack.power ? ` ${a.power}${a.level}` : '' })}</button>`).join(' ');
        const lead = s <= 0 ? `<p><em>${tx('SR2E.Card.Actor.noSuccessesButTheDefenderMay')}</em></p>` : '';
        // A ram that connects hurts the rammer too: v0.73.0 (O25) after the target's defense (NETRIG_V73.ram.afterDefense).
        const ram = snap.ram && ramSelfOnAttackCard(s) && snap.ram.level ? snap.ram : null;
        const ramSelf: DamageState | null = ram ? { targetUuid: ram.vehicleUuid, melee: false, damageType: 'physical', power: ramSelfPower(ram, s), level: ram.level as DamageLevel, crash: true, ramSelf: true } : null;
        const ramHtml = ramSelf ? `<p><button type="button" data-sr2e-action="ramSelf">${tx('SR2E.Card.Actor.rammerSDamage', { name: escText(fromUuidSync(ram!.vehicleUuid)?.name ?? tx('SR2E.Card.Actor.vehicle')), ramPower: ramSelf.power, ramLevel: ram!.level })}</button></p>` : '';
        return { html: `${lead}<p>${buttons}</p>${ramHtml}`, flags: { attack, attacks, ...(ramSelf ? { ramSelf } : {}) }, snap };
      }
      case 'spell': {
        const list = snap.spellTargets ?? (snap.spell ? [snap.spell] : []);
        const vlist = snap.spellVehicles ?? [];
        if (!list.length && !vlist.length) return { html: s <= 0 && snap.sustain ? `<p><em>${tx('SR2E.Card.Actor.theSpellFailed')}</em></p>` : '', flags: {}, snap };
        const noun = list[0]?.noun ?? tx('SR2E.Card.Actor.spell');
        if (s <= 0) return { html: `<p><em>${tx('SR2E.Card.Actor.theFailed', { noun })}</em></p>`, flags: {}, snap };
        const spells: SpellState[] = list.map((x) => ({ ...x, casterSuccesses: s }));
        const buttons = spells.map((sp, i) =>
          `<button type="button" data-sr2e-action="resistSpell" data-index="${i}">${tx('SR2E.Card.Actor.resist3', { noun, name: escText(fromUuidSync(sp.targetUuid)?.name ?? tx('SR2E.Card.Actor.target')) })}</button>`).join(' ');
        // Vehicles (v0.43.0): the successes stage the damage; each resists with Body.
        const damages: DamageState[] = vlist.map((a) => {
          const o = resolveAttack({ attackSuccesses: s, defenseSuccesses: 0, power: a.power, level: a.level });
          return { targetUuid: a.targetUuid, melee: false, damageType: a.damageType, power: o.power, level: o.level as DamageLevel, ...armorExtras(a) };
        });
        const vbuttons = damages.map((d, i) => `<button type="button" data-sr2e-action="resist" data-index="${i}">${tx('SR2E.Card.Actor.resist4', { name: escText(fromUuidSync(d.targetUuid)?.name ?? tx('SR2E.Card.Actor.vehicle')), power: d.power, level: d.level })}</button>`).join(' ');
        return {
          html: `${buttons ? `<p>${buttons}</p>` : ''}${vbuttons ? `<p>${vbuttons}</p>` : ''}`,
          flags: { ...(spells.length ? { spell: spells[0], spells } : {}), ...(damages.length ? { damage: damages[0], damages } : {}) }, snap,
        };
      }
      case 'dispel':
        return this.#resolveDispel(snap);
      case 'learn':
        return this.#resolveLearn(snap);
      case 'ward':
        return this.#resolveWard(snap);
      case 'bindName':
        return this.#resolveBindName(snap);
      case 'centering':
        return this.#resolveCentering(snap);
      case 'assense':
        return this.#resolveAssense(snap);
      case 'heal':
        return this.#resolveHeal(snap);
      case 'enchant':
        return this.#resolveEnchant(snap);
      case 'quest':
        return this.#resolveQuest(snap);
      case 'track': {
        const t = snap.track as { label: string; baseHours: number };
        const hours = trackingHours(s, t.baseHours);
        const html = hours === null
          ? `<p><strong>${tx('SR2E.Card.Actor.theTrailIsLost')}</strong></p>`
          : `<p><strong>${tx('SR2E.Card.Actor.trailFollowed')}</strong> ${tx('SR2E.Card.Actor.in', { label: escText(t.label) })} <strong>${tCount(hours, 'SR2E.Card.Actor.hours')}</strong> ${tCount(s, 'SR2E.Card.Actor.hSuccesses', { baseHours: t.baseHours })}</p>`;
        return { html, flags: {}, snap };
      }
      case 'barrier':
        return this.#resolveBarrier(snap);
      case 'system':
        return this.#resolveSystem(snap, fu);
      case 'medic':
        return this.#resolveMedic(snap);
      case 'repair':
        return this.#resolveRepair(snap);
      case 'surgery':
        return this.#resolveSurgery(snap);
      case 'cyberRepair': {
        const c = snap.cyberRepair!;
        if (s <= 0) {
          // v0.50.0: a GM's TN change turned a repair into a failure: it is damaged again.
          if (c.fixed && c.projectId) {
            const owner: any = c.ownerUuid ? fromUuidSync(c.ownerUuid) ?? this : this;
            await owner?.cancelProject?.(c.projectId);
            return { html: `<p><strong>${tx('SR2E.Card.Actor.isStillDamaged', { itemName: escText(c.itemName) })}</strong></p>`, flags: {}, snap: { ...snap, cyberRepair: { ...c, fixed: false, projectId: undefined } } };
          }
          if (c.fixed) {
            const owner: any = c.ownerUuid ? fromUuidSync(c.ownerUuid) ?? this : this;
            const it: any = [...owner.items].find((i: any) => i.id === c.itemId);
            if (it) await it.update({ 'system.damaged': true });
          }
          return { html: `<p><strong>${tx('SR2E.Card.Actor.isStillDamaged', { itemName: escText(c.itemName) })}</strong></p>`, flags: {}, snap: { ...snap, cyberRepair: { ...c, fixed: false } } };
        }
        const h = Number(RULES.CYBERWARE.repair.hours);
        // v0.65.0: the repair takes its hours: the ware stays damaged until the work is done.
        const repOwner: any = c.ownerUuid ? fromUuidSync(c.ownerUuid) ?? this : this;
        if (!c.fixed && repOwner?.waitsFor?.('repairs') && h > 0) {
          const pr = await repOwner.startProject({ kind: 'repair', area: 'repairs', label: tx('SR2E.Text.Actor.repairing', { name: c.itemName }), hours: h, effect: { updates: [{ itemId: c.itemId, changes: [['system.damaged', false]] }] } });
          return { html: `<p><strong>${tx('SR2E.Card.Actor.isBeingRepaired', { itemName: escText(c.itemName) })}</strong> ${tCount(h, 'SR2E.Card.Actor.readyAfterAboutHoursOfWork', { plural: escText(plural(s, 'success')) })}</p>`, flags: {}, snap: { ...snap, cyberRepair: { ...c, fixed: true, projectId: pr.id } } };
        }
        if (c.projectId) return { html: `<p><strong>${tx('SR2E.Card.Actor.isBeingRepaired', { itemName: escText(c.itemName) })}</strong> (${escText(plural(s, 'success'))}).</p>`, flags: {}, snap };
        if (!c.fixed) {
          const owner: any = c.ownerUuid ? fromUuidSync(c.ownerUuid) ?? this : this;
          const it: any = [...owner.items].find((i: any) => i.id === c.itemId);
          if (it) await it.update({ 'system.damaged': false });
        }
        return { html: `<p><strong>${tx('SR2E.Card.Actor.isRepaired', { itemName: escText(c.itemName) })}</strong> ${tCount(h, 'SR2E.Card.Actor.aboutHoursOfWork', { plural: escText(plural(s, 'success')) })}</p>`, flags: {}, snap: { ...snap, cyberRepair: { ...c, fixed: true } } };
      }
      case 'sensor':
        return this.#resolveSensor(snap);
      case 'bypass':
        return this.#resolveBypass(snap, fu);
      case 'drive': {
        const d = snap.drive!;
        if (d.push !== undefined) return this.#resolvePush(snap);
        if (s > 0) return { html: `<p><strong>${d.crashTest ? tx('SR2E.Card.Actor.staysUnderControl', { vehicleName: escText(d.vehicleName) }) : tx('SR2E.Card.Actor.success2')}</strong> (${escText(plural(s, 'success'))}).</p>`, flags: {}, snap };
        if (!d.crashTest) return { html: `<p><strong>${tx('SR2E.Card.Actor.theManeuverFails')}</strong></p>`, flags: {}, snap };
        const c = veh80CrashDamage(d.speed);
        return {
          html: `<p><strong>${tx('SR2E.Card.Actor.crash')}</strong> ${tx('SR2E.Card.Actor.crashesAtSpeed', { vehicleName: escText(d.vehicleName), speed: d.speed })}</p>
            <p><button type="button" data-sr2e-action="vehicleCrash">${tx('SR2E.Card.Actor.crashDamagePower', { power: c.power })}</button></p>`,
          flags: { crash: { vehicleUuid: d.vehicleUuid, speed: d.speed } }, snap,
        };
      }
      case 'defend': {
        const attack = snap.defendAgainst as AttackState;
        if (attack.matrix) return this.#matrixHit(snap, attack, s, true);
        if (opposedMelee(attack) && this.type !== 'vehicle') return this.#resolveMeleeDefense(snap);
        const outcome = resolveAttack({ attackSuccesses: attack.attackSuccesses, defenseSuccesses: s, power: attack.power, level: attack.level });
        // v0.73.0 (O25): the rammer's share, only when the ram still hits after the defense.
        const rs = ramSelfAfterDefense({ hit: Boolean(outcome.hit && outcome.level), ram: attack.ram, vehicleName: attack.ram ? String(fromUuidSync(attack.ram.vehicleUuid)?.name ?? '') : '' });
        if (!outcome.hit || !outcome.level) {
          return { html: `<p>${outcomeWord('missed')} ${tx('SR2E.Card.Actor.attackVsDefense', { attackAttackSuccesses: attack.attackSuccesses, s })}</p>${rs.note ? `<p>${escText(rs.note)}</p>` : ''}`, flags: {}, snap };
        }
        const ramSelfD: DamageState | null = rs.offer && attack.ram?.level ? { targetUuid: attack.ram.vehicleUuid, melee: false, damageType: 'physical', power: ramSelfPower(attack.ram, attack.attackSuccesses), level: attack.ram.level as DamageLevel, crash: true, ramSelf: true } : null;
        const ramHtmlD = ramSelfD ? `<p><button type="button" data-sr2e-action="ramSelf">${tx('SR2E.Card.Actor.rammerSDamage2', { name: escText(fromUuidSync(ramSelfD.targetUuid)?.name ?? tx('SR2E.Card.Actor.vehicle')), ramSelfDPower: ramSelfD.power, ramSelfDLevel: ramSelfD.level })}</button></p>` : '';
        const damage: DamageState = {
          targetUuid: this.uuid as string, melee: attack.melee, damageType: attack.damageType, power: outcome.power, level: outcome.level,
          ...(attack.astral ? { astral: true } : {}), ...(attack.elemental ? { elemental: true } : {}), ...armorExtras(attack),
          ...(this.type === 'vehicle' ? { attackHits: Math.max(0, Number(attack.attackSuccesses) || 0) } : {}),
        };
        const ee = elementEffectExtras(attack, this.uuid as string);
        return {
          html: `<p>${outcomeWord('hit')} ${tx('SR2E.Card.Actor.attackVsDefenseNetDamage', { attackAttackSuccesses: attack.attackSuccesses, s, outcomeNetSuccesses: outcome.netSuccesses })} <strong>${damage.power}${damage.level}</strong> ${damage.damageType}.</p>
             <p><button type="button" data-sr2e-action="resist">${tx('SR2E.Card.Actor.resistDamage')}</button>${attack.flame ? ` <button type="button" data-sr2e-action="catchFire" title="${tx('SR2E.Card.Actor.theFlamesCatchResistBeingOn')}">${tx('SR2E.Card.Actor.catchesFire')}</button>` : ''}${ee.html}</p>${ramHtmlD}`,
          flags: { damage, ...(attack.flame ? { catchFire: { targetUuid: this.uuid } } : {}), ...ee.flags, ...(ramSelfD ? { ramSelf: ramSelfD } : {}) },
          snap,
        };
      }
      case 'soak':
        return this.#wearSoakUtility(await this.#resolveSoak(snap, fu));
      case 'psyche':
        return this.#resolvePsyche(snap, fu);
      case 'addiction':
        return this.#resolveAddiction(snap);
      case 'disease':
        return this.#resolveDisease(snap);
      case 'conjure':
        return this.#resolveConjure(snap);
      case 'cleanse':
        return this.#resolveCleanse(snap);
      case 'divine':
        return { html: `<p><strong>${escText(diviningAnswer(s))}</strong></p><p class="hint">${tx('SR2E.Card.Actor.theGmAnswersWithThatMuch', { part: snap.divine?.question ? `“${escText(snap.divine.question)}”` : tx('SR2E.Card.Actor.theQuestion') })}</p>`, flags: {}, snap };
      case 'invoke':
        return this.#resolveInvoke(snap);
      case 'design':
        return this.#resolveDesign(snap);
      case 'notice': {
        const n = snap.notice!;
        return {
          html: s > 0
            ? `<p><strong>${tx('SR2E.Card.Actor.sensesARitual', { name: escText(this.name) })}</strong> ${tx('SR2E.Card.Actor.reachingForThemForce', { spellName: escText(n.spellName), force: n.force, part: s >= 2 ? tx('SR2E.Card.Actor.workedBy', { casterName: escText(n.casterName) }) : '' })}</p>`
            : `<p>${tx('SR2E.Card.Actor.noticesNothing', { name: escText(this.name) })}</p>`,
          flags: {}, snap,
        };
      }
      case 'rejection':
        return this.#resolveRejection(snap);
      case 'code':
        return this.#resolveCode(snap);
      case 'install':
        return this.#resolveInstall(snap);
      case 'banish':
        return this.#resolveBanish(snap);
      case 'jackOut':
        return this.#resolveJackOut(snap);
      case 'mperceive':
        return this.#resolvePerception(snap);
      case 'maneuver':
        return this.#resolveManeuver(snap);
      case 'mutility':
        return this.#resolveUtility(snap);
      default:
        return this.#resolvePlain(snap);
    }
  }

  /** v0.58.0: a plain test's extras on its card (time taken, what it reveals, a repair, an instructor's test); empty without them. */
  async #resolvePlain(snapIn: TestSnapshot): Promise<Resolved> {
    let snap = snapIn;
    const s = snap.successes;
    const parts: string[] = [];
    if (snap.reveal) {
      const text = snap.reveal.kind === 'notice' ? noticeReveal(s) : snap.reveal.kind === 'language' ? languageReveal(s) : snap.reveal.kind === 'knowledge' ? urrCoreKnowledgeText(s) : listenReveal(s);
      parts.push(`<p><strong>${escText(text)}</strong>${snap.reveal.what ? ` <span class="hint">(${escText(snap.reveal.what)})</span>` : ''}</p>`);
    }
    // v0.80.0 (RULES.URR_V80.coreCriticals): critical successes ('' in the book).
    const crit = snap.kind === 'plain' ? urrCoreCriticalNote(snap.dice, snap.targetNumber, snap.botch) : '';
    if (crit) parts.push(`<p class="hint">${escText(crit)}</p>`);
    if (snap.need80) parts.push(s >= snap.need80 ? `<p><strong>${tx('SR2E.Card.Actor.decrypted')}</strong> ${tx('SR2E.Card.Actor.ofSuccessesNeeded', { s, need80: snap.need80 })}</p>` : `<p><strong>${tx('SR2E.Card.Actor.notDecrypted')}</strong> ${tx('SR2E.Card.Actor.ofSuccessesNeeded', { s, need80: snap.need80 })}</p>`);
    // v0.78.0: the whip check: no successes and the wielder is struck by their own whip (a re-roll replaces the card).
    if (snap.whipCheck) {
      const w = snap.whipCheck;
      if (s > 0) parts.push(`<p><strong>${tx('SR2E.Card.Actor.underControl')}</strong> ${tx('SR2E.Card.Actor.keepsTheClear', { name: escText(this.name), weaponName: escText(w.weaponName) })}</p>`);
      else {
        const damage: DamageState = { targetUuid: this.uuid as string, melee: true, damageType: w.damageType, power: w.power, level: w.level, armorKind: 'impact', armorMultiplier: RULES.COMBAT_V61.monowhip.armorMultiplier };
        return { html: `${parts.join('')}<p><strong>${tx('SR2E.Card.Actor.struckByTheWhip')}</strong> ${tx('SR2E.Card.Actor.theLashesBackAt', { weaponName: escText(w.weaponName), name: escText(this.name) })} <strong>${damage.power}${damage.level}</strong> ${tx('SR2E.Card.Actor.impactArmor', { damageDamageType: escText(String(damage.damageType)), monowhipArmorMultiplier: RULES.COMBAT_V61.monowhip.armorMultiplier })}</p>
          <p><button type="button" data-sr2e-action="resist">${tx('SR2E.Card.Actor.resistDamage')}</button></p>`, flags: { damage }, snap };
      }
    }
    // v0.79.0: the self-recovery gate: the result follows the card (a re-roll rewrites it).
    if (snap.selfRecovery) {
      const ok = s > 0;
      if (canWriteNow(this)) await this.setFlag(SYSTEM_ID, 'selfRecovery', { boxes: snap.selfRecovery.boxes, ok, t: snap.selfRecovery.t });
      parts.push(`<p><strong>${ok ? tx('SR2E.Card.Actor.healsOnItsOwn') : tx('SR2E.Card.Actor.needsMedicalAttention')}</strong>${ok ? '' : ` <span class="hint">${tx('SR2E.Card.Actor.aDoctorAnyCareButResting')}</span>`}</p>`);
    }
    if (snap.timed && snap.timed.base > 0) {
      const t = timeTaken(snap.timed.base, snap.timed.unit, s);
      parts.push(`<p>${t.ok ? `${tx('SR2E.Card.Actor.timeTaken')} <strong>${escText(t.label)}</strong>.` : `<em>${escText(t.label)}.</em>`}</p>`);
    }
    if (snap.gearRepair) {
      const g = snap.gearRepair;
      const item: any = await fromUuid(g.itemUuid);
      let note = '';
      if (!item) note = ` <em>${tx('SR2E.Card.Actor.theItemIsGone')}</em>`;
      else if (!canWriteNow(item)) note = ` <em>${tx('SR2E.Card.Actor.onlyItsOwnerOrTheGm')}</em>`;
      else if (g.projectId) {
        // v0.65.0: a repair under way: a re-roll changes its time (or, with no successes, it's given up).
        const owner: any = item.parent;
        const hours = snap.timed ? timeTaken(snap.timed.base, snap.timed.unit, s).seconds / 3600 : 0;
        if (s > 0) await owner?.retimeProject?.(g.projectId, hours);
        else { await owner?.cancelProject?.(g.projectId); snap = { ...snap, gearRepair: { ...g, fixed: false, projectId: undefined } }; }
        note = s > 0 ? tx('SR2E.Card.Actor.itIsReadyWhenTheWork') : '';
      } else if (s > 0 && item.system?.damaged && !g.fixed && item.parent?.waitsFor?.('repairs')) {
        // v0.65.0: the repair takes its time: the item stays broken until the work is done.
        const hours = snap.timed ? timeTaken(snap.timed.base, snap.timed.unit, s).seconds / 3600 : 0;
        const pr = await item.parent.startProject({ kind: 'repair', area: 'repairs', label: tx('SR2E.Text.Actor.repairing', { name: g.name }), hours, effect: { updates: [{ itemId: item.id, changes: [['system.damaged', false]] }] } });
        snap = { ...snap, gearRepair: { ...g, fixed: true, projectId: pr.id } };
        note = tx('SR2E.Card.Actor.itIsReadyWhenTheWork');
      }
      else if (s > 0 && item.system?.damaged && !g.fixed) { await item.update({ 'system.damaged': false }); snap = { ...snap, gearRepair: { ...g, fixed: true } }; }
      else if (s <= 0 && g.fixed && !item.system?.damaged) { await item.update({ 'system.damaged': true }); snap = { ...snap, gearRepair: { ...g, fixed: false } }; }
      const waitingRepair = Boolean((snap.gearRepair as any)?.projectId);
      parts.push(`<p>${s > 0 ? `<strong>${escText(g.name)} ${waitingRepair ? tx('SR2E.Card.Actor.isBeingRepaired2') : tx('SR2E.Card.Actor.isRepaired2')}.</strong>` : `<em>${tx('SR2E.Card.Actor.isStillBroken', { name: escText(g.name) })}</em>`}${note}</p>`);
    }
    if (snap.instruct) {
      const ins = snap.instruct;
      // v0.80.0 (RULES.URR_V80.coreTraining 'urr'): rating + 2, ÷ (1 + successes); null in the book.
      const r = urrCoreInstruction({ days: ins.days, successes: s, instructorRating: ins.instructorRating, newRating: ins.newRating, attribute: ins.attribute })
        ?? instructionResult({ days: ins.days, successes: s, instructorRating: ins.instructorRating, newRating: ins.newRating });
      const readyAt = trainingReadyAt(ins.startedAt, r.days);
      const student: any = await fromUuid(ins.studentUuid);
      const list: any[] = [...(student?.system?.training ?? [])].map((x: any) => ({ ...x }));
      const e = list.find((x: any) => x.id === ins.trainingId);
      let note = '';
      if (!student || !e) note = ` <em>${tx('SR2E.Card.Actor.thatTrainingIsNoLongerUnder')}</em>`;
      else if (!canWriteNow(student)) note = ` <em>${tx('SR2E.Card.Actor.onlyItsOwnerOrTheGm2')}</em>`;
      else if (e.readyAt !== readyAt && (ins.readyAt === undefined || e.readyAt === ins.readyAt)) {
        e.readyAt = readyAt; e.days = r.days;
        await student.update({ 'system.training': list });
      } else if (ins.readyAt !== undefined && e.readyAt !== ins.readyAt && e.readyAt !== readyAt) note = ` <em>${tx('SR2E.Card.Actor.theTrainingChangedSinceThisWas')}</em>`;
      snap = { ...snap, instruct: { ...ins, readyAt } };
      parts.push(`<p>${r.usable && s > 0 ? `${tx('SR2E.Card.Actor.cutsTheTrainingTo', { insInstructorName: escText(ins.instructorName) })} <strong>${escText(plural(r.days, 'day'))}</strong>.` : `<em>${escText(String(r.note || tx('SR2E.Card.Actor.noHelpFromTheInstructor')).replace(/\.+$/, ''))}.</em> ${tx('SR2E.Card.Actor.ofTraining', { plural: escText(plural(r.days, 'day')) })}`}${note}</p>`);
    }
    // v0.91.8 (RULES.FORMULA_V918.teacher): a teacher's test: the student's learning test with its successes as dice.
    if (snap.teach) {
      const t = snap.teach;
      const dice = teacherDice(s, t.sorcery);
      const fee = t.fee > 0 ? tx('SR2E.Card.Formula.fee', { fee: Number(t.fee).toLocaleString() }) : '';
      const other = t.foreign ? tx('SR2E.Card.Formula.otherTraditionNote') : '';
      parts.push(`<p>${dice > 0 ? tx('SR2E.Card.Formula.helps', { teacher: escText(t.teacherName), dice }) : tx('SR2E.Card.Formula.noHelp', { teacher: escText(t.teacherName) })}${fee}${other}</p>`
        + `<p><button type="button" data-sr2e-action="learnTaught">${tx('SR2E.Card.Formula.learnButton', { spell: escText(t.spell), force: t.force })}</button></p>`);
    }
    return { html: parts.join(''), flags: {}, snap };
  }

  /** Opposed melee: whoever has more successes hits the other with their own weapon. */
  #resolveMeleeDefense(snap: TestSnapshot): Resolved {
    const attack = snap.defendAgainst as AttackState;
    const counter = snap.counter ?? null;
    const s = snap.successes;
    const r = resolveMelee({
      attackerSuccesses: attack.attackSuccesses, defenderSuccesses: s,
      attacker: { power: attack.power, level: attack.level },
      defender: counter ? { power: counter.power, level: counter.level } : null,
    });
    const tally = tx('SR2E.Card.Actor.attackVsDefense2', { attackAttackSuccesses: attack.attackSuccesses, s });
    const attackerName = fromUuidSync(attack.attackerUuid)?.name ?? tx('SR2E.Card.Actor.theAttacker');
    // v0.78.0 (COMBAT_V61.monowhip.on 'defended', the book): beaten only by the defender's pool successes, the
    // whip's wielder rolls its skill vs TN 6; no successes and it strikes them (the whip check button).
    const whip = attack.selfHit && whipBacklash({ attackerSuccesses: attack.attackSuccesses, defenderSuccesses: s, defenderPoolSuccesses: poolSuccesses(snap.dice ?? []) })
      ? { attackerUuid: attack.attackerUuid, skill: attack.selfHitSkill ?? 'Armed Combat', power: attack.power, level: attack.level, damageType: attack.damageType, weaponName: attack.weaponName }
      : null;
    const whipHtml = whip ? `<p>${tx('SR2E.Card.Actor.theWasTurnedAsideOnlyBy', { attackWeaponName: escText(attack.weaponName), name: escText(this.name) })} <button type="button" data-sr2e-action="whipCheck">${tx('SR2E.Card.Actor.whipCheckVs', { attackerName: escText(attackerName), whipSkill: escText(whip.skill), monowhipTn: RULES.COMBAT_V61.monowhip.tn })}</button></p>` : '';
    if (r.winner === 'none' || !r.level) {
      // v0.61.0: a monowhip that misses hits its wielder (COMBAT_V61.monowhip 'miss').
      if (attack.selfHit && RULES.COMBAT_V61.monowhip.on === 'miss' && selfHitCheck({ selfHit: true, botch: false, missed: true })) {
        const damage: DamageState = { targetUuid: attack.attackerUuid, melee: true, damageType: attack.damageType, power: attack.power, level: attack.level };
        return {
          html: `<p><strong>${tx('SR2E.Card.Actor.miss2')}</strong> ${tx('SR2E.Card.Actor.theLashesBackAt2', { tally, attackWeaponName: escText(attack.weaponName), attackerName: escText(attackerName) })} <strong>${damage.power}${damage.level}</strong> ${damage.damageType}.</p>
             <p><button type="button" data-sr2e-action="resist">${tx('SR2E.Card.Actor.resistDamage2', { attackerName: escText(attackerName) })}</button></p>`,
          flags: { damage }, snap,
        };
      }
      return { html: `<p><strong>${tx('SR2E.Card.Actor.noDamage')}</strong> ${tally}${s > attack.attackSuccesses ? tx('SR2E.Card.Actor.theBlowIsParried') : ''}.</p>${whipHtml}`, flags: whip ? { whipCheck: whip } : {}, snap };
    }
    if (r.winner === 'attacker') {
      const damage: DamageState = { targetUuid: this.uuid as string, melee: true, damageType: attack.damageType, power: r.power, level: r.level, ...armorExtras(attack), ...U80C.cbtMeleeDamage(attack.level, attack.attackSuccesses, r.net, Boolean(attack.fullDefense80)) };
      return {
        html: `<p>${outcomeWord('hit')} ${tx('SR2E.Card.Actor.netDamage', { tally, net: r.net })} <strong>${damage.power}${damage.level}</strong> ${damage.damageType}.</p>
           <p><button type="button" data-sr2e-action="resist">${tx('SR2E.Card.Actor.resistDamage')}</button></p>`,
        flags: { damage }, snap,
      };
    }
    const c = counter as CounterWeapon;
    const damage: DamageState = {
      targetUuid: attack.attackerUuid, melee: true, damageType: c.damageType, power: r.power, level: r.level, ...U80C.cbtMeleeDamage(c.level, s, r.net),
      // v0.71.0 (R10): the defending weapon's extras (armor kind, stun, material, toxin).
      ...(c.extras ? armorExtras(c.extras) : {}),
      ...(c.ignoreImmunity ? { ignoreImmunity: true } : {}), ...(c.infection ? { infection: c.infection } : {}),
    };
    return {
      html: `<p>${outcomeWord('counter')} ${tx('SR2E.Card.Actor.winsByWithTakes', { tally, name: escText(this.name), net: r.net, weaponName: escText(c.weaponName), attackerName: escText(attackerName) })} <strong>${damage.power}${damage.level}</strong> ${damage.damageType}.</p>
         <p><button type="button" data-sr2e-action="resist">${tx('SR2E.Card.Actor.resistDamage2', { attackerName: escText(attackerName) })}</button></p>${whipHtml}`,
      flags: { damage, ...(whip ? { whipCheck: whip } : {}) }, snap,
    };
  }

  /**
   * v0.78.0 (COMBAT_V61.monowhip.on 'defended'): the wielder's check after the defender's pool dice turned the whip
   * aside: the weapon's skill vs TN `monowhip.tn`; no successes and the whip strikes them (impact armor × `armorMultiplier`).
   */
  async rollWhipCheck(w: { skill: string; power: number; level: DamageLevel; damageType: any; weaponName: string }): Promise<void> {
    const M = RULES.COMBAT_V61.monowhip;
    const sd = this.#skillDice(this.findSkill(w.skill), false, null, 'quickness' as AttributeKey);
    await this.#runTest(tx('SR2E.Card.Actor.whipCheck', { weaponName: w.weaponName, skill: w.skill, sdSuffix: sd.suffix }), sd.dice, { targetNumber: M.tn, modifiers: sd.modifiers },
      { kind: 'plain', whipCheck: { power: w.power, level: w.level, damageType: w.damageType, weaponName: w.weaponName } });
  }

  /** Apply (or, on a re-roll, correct) condition-monitor damage for a soak/drain/spell-resistance test. */
  async #resolveSoak(snap: TestSnapshot, fu: FollowUps): Promise<Resolved> {
    const ctx = snap.soak as SoakContext;
    if (ctx.track === 'matrix') return this.#resolveMatrixSoak(snap, fu);
    if (ctx.track === 'vehicle') return this.#resolveVehicleSoak(snap, fu);
    const s = snap.successes;
    let level: DamageLevel | null;
    let lead = '';
    let cleanMiss = false;
    if (ctx.mode === 'spell' && ctx.effectOnly) {
      const e = resolvePowerEffect(ctx.casterSuccesses ?? 0, s);
      let html = e.hit
        ? `<p><strong>${tx('SR2E.Card.Actor.takesEffect', { spellName: escText(ctx.spellName) })}</strong> ${tx('SR2E.Card.Actor.with')} <strong>${e.netSuccesses}</strong> ${tCount(e.netSuccesses, 'SR2E.Card.Actor.netSuccessesVs', { casterSuccesses: ctx.casterSuccesses, s })}</p>`
        : `<p>${outcomeWord('resisted')} ${tx('SR2E.Card.Actor.vsResistance', { casterSuccesses: ctx.casterSuccesses, s })}</p>`;
      // Essence drain (v0.39.0): moves Essence from the victim to the drainer.
      // v0.81.0 (D1-4): a re-roll moves the difference (all of it back when the victim now resists).
      const ed = ctx.essenceDrain;
      if (ed && ed.moved && ed.taken === undefined) {
        // A card from before v0.81.0: what moved isn't recorded.
        if (!e.hit) html += `<p><em>${tx('SR2E.Card.Actor.essenceAlreadyDrainedByAnEarlier')}</em></p>`;
      } else if (ed && (e.hit || Number(ed.taken ?? 0) > 0)) {
        const r = await this.#drainEssence(ed, e.hit ? e.netSuccesses : 0);
        html += r.html;
        return { html, flags: {}, snap: { ...snap, soak: { ...ctx, essenceDrain: { ...ed, moved: r.taken > 0, taken: r.taken, gained: r.gained, ...(r.gmGain ? { gmGain: true } : {}), ...(r.gmTake ? { gmTake: true } : {}) } } } };
      }
      // A sustained power changing attributes (v0.45.0): on while it holds; a re-roll corrects it.
      if (ctx.powerEffect) {
        const fx = ctx.powerEffect;
        if (e.hit) {
          const id = fx.effectId || SR2Actor.#newId();
          const entry = SR2Actor.fxEntry(fx, e.netSuccesses, id, fx.casterUuid, fx.casterName);
          await SR2Actor.setPowerEffect(this.uuid as string, entry);
          // v0.61.0: a holding power says what it does; binding can be broken.
          const held = entry.status ? ` <strong>${tx('SR2E.Card.Actor.is3', { name: escText(this.name), part: entry.special === 'paralysis' ? tx('SR2E.Card.Actor.paralysed') : entry.special === 'petrification' ? tx('SR2E.Card.Actor.turnedToStone') : tx('SR2E.Card.Actor.bound') })}</strong>${Number(entry.holdTurns ?? 0) > 0 ? tCount(Number(entry.holdTurns), 'SR2E.Card.Actor.forCombatTurns2') : ''}.` : '';
          const fxName = escText(fx.name), bundle = escText(describeBundle(entry));
          const paralysed = Boolean(entry.until) && Number(this.sys.attributes?.quickness?.total ?? 1) <= 0;
          const lasts = entry.until
            ? (paralysed
              ? `${tx('SR2E.Card.Actor.fxForMinutes', { fxName, bundle, fxMinutes: Number(fx.minutes ?? 0) })} <strong>${tx('SR2E.Card.Actor.isParalysed', { name: escText(this.name) })}</strong> ${tx('SR2E.Card.Actor.quickness0')}`
              : tx('SR2E.Card.Actor.fxForMinutesDot', { fxName, bundle, fxMinutes: Number(fx.minutes ?? 0) }))
            : entry.status && Number(entry.holdTurns ?? 0) > 0 ? tx('SR2E.Card.Actor.fxBundle', { fxName, bundle }) : tx('SR2E.Card.Actor.fxWhileSustainsIt', { fxName, bundle, fxCasterName: escText(fx.casterName) });
          html += `<p>${lasts}${held}</p>`;
          return { html, flags: {}, snap: { ...snap, soak: { ...ctx, powerEffect: { ...fx, effectId: id } } } };
        }
        if (fx.effectId) await SR2Actor.setPowerEffect(this.uuid as string, null, fx.effectId);
        return { html, flags: {}, snap: { ...snap, soak: { ...ctx, powerEffect: { ...fx, effectId: fx.kind === 'spell' ? fx.effectId : undefined as any } } } };
      }
      const rf = this.#reflection(ctx, s);
      return { html: html + rf.html, flags: rf.flags, snap };
    }
    let reflected: { html: string; flags: Record<string, unknown> } = { html: '', flags: {} };
    if (ctx.mode === 'spell') {
      const outcome = resolveCombatSpell({ casterSuccesses: ctx.casterSuccesses ?? 0, resistSuccesses: s, level: ctx.level });
      level = outcome.level;
      lead = outcome.hit
        ? `<strong>${tx('SR2E.Card.Actor.takesEffect2', { spellName: escText(ctx.spellName) })}</strong> ${tx('SR2E.Card.Actor.casterVsResistanceNet', { casterSuccesses: ctx.casterSuccesses, s, outcomeNetSuccesses: outcome.netSuccesses })} `
        : `${outcomeWord('resisted')} ${tx('SR2E.Card.Actor.casterVsResistance', { casterSuccesses: ctx.casterSuccesses, s })}`;
      reflected = this.#reflection(ctx, s);
    } else {
      // v0.80.0 (URR_V80.cbtDefense 'cleanMiss', URR): pool successes above the attack's are a clean miss; else net staging.
      if (ctx.cleanMiss80) {
        const cm80 = U80C.cbtSoakLevel(ctx.level, ctx.cleanMiss80, s, poolSuccesses(snap.dice ?? []));
        level = cm80.level;
        lead = cm80.clean ? `${outcomeWord('cleanMiss')} ${cm80.lead}` : cm80.lead;
        cleanMiss = cm80.clean;
      } else level = resolveResistance(ctx.level, s);
    }

    // v0.72.0 (O11): Will to Live adds Overflow boxes (the death check counts them).
    const ctxBody = ctx.body + Math.max(0, Number(this.sys.derived?.vitals?.overflowBoxes ?? 0));
    const result = applyDamageToMonitor(ctx.before, ctx.type, level, ctxBody);
    // Platelet factories take boxes off each Physical hit, never below 1 (v0.30.0).
    const pf = ctx.type === 'physical' && ctx.noun === 'damage' ? ((this.sys.derived?.bio?.boxesOff as number | undefined) ?? 0) : 0;
    if (pf > 0 && result.boxes > 1) {
      const kept = plateletBoxes(result.boxes, pf);
      result.monitor.physical -= result.boxes - kept;
      result.boxes = kept;
      result.status = monitorStatus(result.monitor, ctxBody);
    }
    // Trauma dampers take boxes off each Stun hit, never below 1 (v0.45.0; only when nothing overflowed).
    const td = ctx.type === 'stun' && ctx.noun === 'damage' ? Number(this.sys.derived?.bio?.stunBoxesOff ?? 0) : 0;
    if (td > 0 && result.boxes > 1 && result.monitor.physical === ctx.before.physical) {
      const kept = dampedStunBoxes(result.boxes, td);
      result.monitor.stun -= result.boxes - kept;
      result.boxes = kept;
      result.status = monitorStatus(result.monitor, ctxBody);
    }
    const current: Monitor = { physical: this.sys.monitor.physical, stun: this.sys.monitor.stun };
    let note = '';
    // A first roll always applies. A re-roll only corrects the monitor if nothing else has
    // changed it since the previous result was applied; otherwise it says so and leaves it.
    const expected = ctx.after ?? ctx.before;
    if (sameMonitor(current, expected)) {
      await this.update({ 'system.monitor.physical': result.monitor.physical, 'system.monitor.stun': result.monitor.stun });
      fu.physicalBefore = current.physical;
      // Boxes from a vulnerability can't be regenerated (v0.39.0); a re-roll corrects the count.
      if (ctx.noRegen) {
        const prev = ctx.after ? Math.max(0, ctx.after.physical - ctx.before.physical) : 0;
        const now = Math.max(0, result.monitor.physical - ctx.before.physical);
        const nr = Number(this.getFlag(SYSTEM_ID, 'noRegen') ?? 0) || 0;
        try { await this.setFlag(SYSTEM_ID, 'noRegen', Math.max(0, nr - prev + now)); } catch { /* not saved */ }
      }
    } else {
      note = ` <em>${tx('SR2E.Card.Actor.theConditionMonitorChangedSinceThis', { monitorPhysical: result.monitor.physical, monitorStun: result.monitor.stun })}</em>`;
    }

    let body: string;
    if (level === null) {
      body = ctx.mode === 'spell' ? lead : ctx.noun === 'drain' ? outcomeWord('noDrain', false) : `${lead}${cleanMiss ? '' : outcomeWord('fullyResisted', false)}`;
    } else {
      // v0.89.5: one whole sentence per track and noun ("Takes M Stun drain (3 boxes). Status: …"), the status by its key.
      const track: 'physical' | 'stun' = ctx.type === 'stun' ? 'stun' : 'physical';
      const key = ctx.noun === 'drain'
        ? (track === 'stun' ? 'SR2E.Card.Outcome.takesStunDrain' : 'SR2E.Card.Outcome.takesPhysicalDrain')
        : (track === 'stun' ? 'SR2E.Card.Outcome.takesStunDamage' : 'SR2E.Card.Outcome.takesPhysicalDamage');
      body = `${lead}${takenMark(level, track, tKey(key, { level: `<strong>${level}</strong>`, plural: escText(plural(result.boxes, 'box')), status: `<strong>${escText(statusText(result.status))}</strong>` }))}`;
    }
    // Armor degrading (house rule, v0.37.0): a heavy hit takes points off the best worn piece, once.
    let degradeNote = '';
    let degradedNow = Boolean(ctx.degraded);
    const dg = RULES.COMBAT.armorDegrade;
    const order = ['L', 'M', 'S', 'D'];
    if (dg.enabled && ctx.armorKind && !ctx.degraded && order.indexOf(ctx.level) >= order.indexOf(dg.atLevel)) {
      const kindKey = ctx.armorKind;
      const best = [...this.items].filter((i: any) => i.type === 'armor' && i.system.worn && isCarried(i) && (i.system[kindKey] ?? 0) - (i.system.degraded ?? 0) > 0)
        .sort((a: any, b: any) => ((b.system[kindKey] ?? 0) - (b.system.degraded ?? 0)) - ((a.system[kindKey] ?? 0) - (a.system.degraded ?? 0)))[0];
      if (best) {
        await best.update({ 'system.degraded': (best.system.degraded ?? 0) + dg.points });
        degradeNote = ` <em>${tx('SR2E.Card.Actor.isDamaged', { bestName: escText(best.name), dgPoints: dg.points })}</em>`;
        degradedNow = true;
      }
    }
    // A heavy hit can knock the target down.
    const kd = ctx.knockdown && U80C.cbtKnockdownDue(knockdownTriggered({ power: ctx.knockdown.power, body: ctx.body, level }), level)
      ? `<p><button type="button" data-sr2e-action="knockdown">${tx('SR2E.Card.Actor.knockdownTestBodyVs', { knockdownTn: ctx.knockdown.tn })}</button></p>` : '';
    // A heavy Physical hit can damage cyberware (RULES.GEAR.cyberDamage, v0.43.0): rolled once per card.
    let cyber = '';
    let cyberCheck = ctx.cyberCheck;
    const hasWare = [...this.items].some((i: any) => i.type === 'cyberware' && i.system.installed && !i.system.damaged);
    if (cyberCheck && !cyberCheck.rolled && hasWare && cyberDamageDue(level, ctx.type)) {
      if (RULES.GEAR.cyberDamage.mode === 'auto') {
        await this.cyberDamageCheck(cyberCheck.location);
        cyberCheck = { ...cyberCheck, rolled: true };
      } else {
        cyber = `<p><button type="button" data-sr2e-action="cyberDamage" title="${tx('SR2E.Card.Actor.n1d6PerPieceOfCyberwareLow')}">${tx('SR2E.Card.Actor.cyberwareDamageCheck')}</button></p>`;
      }
    }
    // v0.48.0: a bite that broke the skin can pass its disease on (living targets only).
    const inf = ctx.infection && ['character', 'npc'].includes(this.type) && infects(result.boxes, ctx.type)
      ? `<p><button type="button" data-sr2e-action="infection" title="${escText(ctx.infection.name)}: ${Number(ctx.infection.power) || 0}${escText(ctx.infection.level)} ${escText(ctx.infection.damageType)}">${tx('SR2E.Card.Actor.resistInfection', { infectionName: escText(ctx.infection.name) })}</button></p>` : '';
    // v0.55.0: a weapon's toxin (a dart or a poisoned blade): on any hit, or only when it wounds.
    const tox = ctx.toxinHit && ['character', 'npc', 'spirit'].includes(this.type) && (!ctx.toxinHit.needsWound || result.boxes > 0)
      ? `<p><button type="button" data-sr2e-action="toxinHit" title="${escText(ctx.toxinHit.name)}: ${Number(ctx.toxinHit.power) || 0}${escText(ctx.toxinHit.level)} ${escText(ctx.toxinHit.damageType)}">${tx('SR2E.Card.Actor.resist5', { toxinHitName: escText(ctx.toxinHit.name) })}</button></p>` : '';
    const flags: Record<string, unknown> = {
      ...(tox ? { toxinHit: { targetUuid: this.uuid, toxin: ctx.toxinHit } } : {}),
      ...(kd ? { knockdown: { actorUuid: this.uuid, tn: ctx.knockdown!.tn, ...U80C.cbtKnockdownFlag(level) } } : {}),
      ...(cyber ? { cyberDamage: { actorUuid: this.uuid, location: cyberCheck?.location ?? '' } } : {}),
      ...(inf ? { infection: { targetUuid: this.uuid, toxin: ctx.infection } } : {}),
      ...reflected.flags,
    };
    return {
      html: `<p>${body}${note}${degradeNote}</p>${kd}${cyber}${inf}${tox}${reflected.html}`,
      flags,
      snap: { ...snap, soak: { ...ctx, after: result.monitor, ...(degradedNow ? { degraded: true } : {}), ...(cyberCheck ? { cyberCheck } : {}) } },
    };
  }

  /** Karma buttons for a card: only for actors who have a Karma Pool at all. */
  #karmaButtons(snap: TestSnapshot): string {
    if (!((this.sys.karma?.pool as number) > 0)) return '';
    const parts: string[] = [];
    if (snap.botch) {
      parts.push(`<button type="button" data-sr2e-action="avoidDisaster">${tx('SR2E.Card.Actor.avoidDisasterKarma', { avoidDisasterCost: avoidDisasterCost() })}</button>`);
    }
    const failures = snap.dice.filter((d) => !d.success).length;
    if (failures > 0) {
      parts.push(`<button type="button" data-sr2e-action="karmaReroll">${tCount(failures, 'SR2E.Card.Actor.reRollFailuresKarma', { karmaRerollCost: karmaRerollCost(snap.rerolls) })}</button>`);
    }
    const buy = canBuySuccess({ successes: snap.successes, poolLeft: (this.sys.derived?.karmaPoolLeft as number | undefined) ?? 0, botch: snap.botch });
    if (buy.ok) parts.push(`<button type="button" data-sr2e-action="buySuccess" title="${RULES.KARMA.buyPermanent ? tx('SR2E.Card.Actor.theKarmaPoolPointIsGone') : tx('SR2E.Card.Actor.spentUntilTheKarmaPoolRefreshes')}">${tx('SR2E.Card.Actor.buyASuccessKarma', { buyCost: buy.cost, part: RULES.KARMA.buyPermanent ? tx('SR2E.Card.Actor.permanent') : '' })}</button>`);
    return parts.length ? `<p class="sr2e-karma">${parts.join(' ')}</p>` : '';
  }

  /** v0.81.1 (SEC2b-2, design 4): snapshot keys that hold a number wherever they appear (cards print them raw). */
  static readonly #SNAP_NUMBER_KEYS = new Set(['successes', 'casterSuccesses', 'attackSuccesses', 'defenseSuccesses', 'netSuccesses', 'spiritSuccesses', 'power', 'tn', 'hours', 'body', 'force',
    'rating', 'targetNumber', 'baseTargetNumber', 'rerolls', 'bought', 'retargets', 'cleanMiss80', 'boxes', 'physical', 'stun', 'metres', 'speed', 'services', 'servicesBefore', 'forceBefore', 'forceAfter',
    'successesBefore', 'successesAfter', 'points', 'days', 'count', 'applied', 'timeFactor', 'net', 'hits', 'before', 'after', 'total', 'totalDice',
    // v0.81.1 (scanner flag rows): more numbers resolvers print. Not `size`: an enchanting focus's size is a word.
    'cost', 'paid', 'push', 'ratingBefore', 'ioSpeed', 'incubationHours', 'intervalHours', 'baseHours', 'baseDays']);
  /** v0.81.1: snapshot keys that hold a word (a damage level, type, noun, track or mode): printed raw, so only word characters. */
  static readonly #SNAP_WORD_KEYS = new Set(['level', 'type', 'noun', 'damageType', 'track', 'mode']);

  /**
   * v0.81.1 (SEC2b-2, design 4): a snapshot from a card's flags with its numbers coerced to numbers and its words to
   * word characters, before any resolver prints them (a forged `casterSuccesses: '<button …>'` went into the GM's
   * re-posted card). Booleans, numbers and other strings are left as they are; depth-capped.
   */
  static #cleanSnapshot<T>(v: T, depth = 0): T {
    if (depth > 8 || !v || typeof v !== 'object') return v;
    if (Array.isArray(v)) return v.map((x) => SR2Actor.#cleanSnapshot(x, depth + 1)) as any;
    const out: any = {};
    for (const [k, x] of Object.entries(v as any)) {
      if (!safeKey(k)) continue;
      // Round 2 (V-DOC 1, FIX2-BRIEF H1): a number key holding text that isn't a number keeps its word characters (a
      // toxin's speed 'hour' survives; '<button…>' becomes 'button'); numeric text becomes the number.
      if (SR2Actor.#SNAP_NUMBER_KEYS.has(k) && x !== null && x !== undefined && typeof x !== 'number' && typeof x !== 'boolean' && typeof x !== 'object') {
        const t = String(x);
        out[k] = /^\s*-?\d+(\.\d+)?\s*$/.test(t) ? Number(t) : t.replace(/[^\w -]/g, '').slice(0, 40);
      }
      else if (SR2Actor.#SNAP_WORD_KEYS.has(k) && typeof x === 'string') out[k] = x.replace(/[^\w -]/g, '').slice(0, 40);
      else out[k] = SR2Actor.#cleanSnapshot(x, depth + 1);
    }
    return out;
  }

  async #post(snapIn: TestSnapshot, result: SuccessTestResult, rolls: any[], note = '', like: any = null): Promise<any> {
    const fu: FollowUps = {};
    const { html, flags, snap } = await this.#resolve(SR2Actor.#cleanSnapshot(snapIn), fu);
    const data = {
      speaker: ChatMessage.getSpeaker({ actor: this }),
      // v0.92.0: the rules interpretations the card rests on, as a line of † links.
      content: outcomeBanner(snap, html) + describeResult(`${snap.label}${note}`, result) + html + interpLine(interpsForSnapshot(snap, RULES)) + this.#karmaButtons(snap),
      rolls,
      flags: { [SYSTEM_ID]: { ...flags, test: snap } },
      ...(snap.privateTo?.length ? { whisper: snap.privateTo } : {}),
    };
    // v0.50.0: a GM's retroactive TN change keeps the original card's speaker and who can see it.
    // The replacement keeps its author (so the player can still mark its buttons used) and asks nobody to defend again.
    const posted = await ChatMessage.create(like
      ? { ...data, speaker: like.speaker ?? data.speaker, ...SR2Actor.#sameAuthor(like), ...(like.whisper?.length ? { whisper: [...like.whisper], blind: Boolean(like.blind) } : {}),
        flags: { [SYSTEM_ID]: { ...flags, test: snap, retargetOf: like.id ?? '' } } }
      // v0.81.1 (SEC1-5): a GM re-running a player's card (Karma, Buy, Avoid) posts it as that player.
      : withRollMode(actingAuthor && !realGm(actingAuthor) ? { ...data, author: String(actingAuthor.id) } : data));
    SR2Actor.#postsBy.set(String(this.uuid ?? ''), (SR2Actor.#postsBy.get(String(this.uuid ?? '')) ?? 0) + 1);
    // v0.61.0: a monowhip that comes up all ones hits its wielder (COMBAT_V61.monowhip 'botch'; 'miss' is on the defender's card).
    // Only on the first roll: a Karma re-roll or a GM's TN change keeps the same botch (no second lash).
    if (snap.botch && !snap.disasterAvoided && snap.kind === 'attack' && snap.weaponId && RULES.COMBAT_V61.monowhip.on === 'botch' && !(Number(snap.rerolls ?? 0) > 0) && !snap.retargets) {
      const w: any = [...this.items].find((i: any) => i.id === snap.weaponId);
      const atk0 = (snap.attack ?? snap.attackTargets?.[0]) as AttackState | undefined;
      // No target picked: the weapon's own damage.
      const atk = atk0 ?? (w ? (() => { const pl = this.planAttack(w, {}); return { power: pl.power, level: pl.level, damageType: pl.damageType } as any; })() : undefined);
      if (w && atk && selfHitCheck({ selfHit: Boolean(w.system?.selfHit), botch: true, missed: true })) {
        const damage: DamageState = { targetUuid: this.uuid as string, melee: true, damageType: atk.damageType, power: atk.power, level: atk.level };
        await ChatMessage.create({
          speaker: ChatMessage.getSpeaker({ actor: this }),
          content: `<p><strong>${tx('SR2E.Card.Actor.sLashesBack', { name: escText(this.name), name2: escText(w.name) })}</strong> ${tx('SR2E.Card.Actor.atItsWielder')} <strong>${damage.power}${damage.level}</strong> ${damage.damageType}.</p><p><button type="button" data-sr2e-action="resist">${tx('SR2E.Card.Actor.resistDamage')}</button></p>`,
          flags: { [SYSTEM_ID]: { damage } },
        });
      }
    }
    // Rule of One: the GM gets a suggested consequence (and can jam the weapon) (v0.35.0).
    // v0.81.0 (D1-10): only on the first roll, as the monowhip above (a GM TN change keeps the botch: no second card).
    if (snap.botch && !snap.disasterAvoided && RULES.DISASTERS.prompt && !(Number(snap.rerolls ?? 0) > 0) && !snap.retargets) {
      const gms = [...((game as any).users ?? [])].filter((u: any) => u.isGM).map((u: any) => u.id);
      const jam = snap.kind === 'attack' && snap.weaponId && [...this.items].some((i: any) => i.id === snap.weaponId && i.type === 'weapon' && !i.system.melee);
      await ChatMessage.create({
        speaker: { alias: tx('SR2E.Card.Actor.disaster2') },
        content: `<p><em>${tx('SR2E.Card.Actor.gmOnly')}</em> · <strong>${tx('SR2E.Card.Actor.disaster3', { name: escText(this.name) })}</strong> ${tx('SR2E.Card.Actor.on', { label: escText(snap.label) })}</p><p>${escText(disasterSuggestion(snap.kind))}</p>${jam ? `<p><button type="button" data-sr2e-action="jamWeapon">${tx('SR2E.Card.Actor.jamTheWeapon')}</button></p>` : ''}`,
        whisper: gms, ...(isGmNow() ? {} : { blind: true }),
        flags: { [SYSTEM_ID]: { disaster: { actorUuid: this.uuid, weaponId: jam ? snap.weaponId : null } } },
      });
    }
    if (fu.physicalBefore !== undefined) await this.checkMagicLoss(fu.physicalBefore);
    const dump = fu.dumpShock;
    if (dump) {
      const tn = dump.tn;
      await ChatMessage.create({
        speaker: ChatMessage.getSpeaker({ actor: this }),
        content: `<p><strong>${tx('SR2E.Card.Actor.sPersonaCrashes', { name: escText(this.name) })}</strong> ${tx('SR2E.Card.Actor.andIsDumpedFromTheMatrix')}</p>
          <p><button type="button" data-sr2e-action="dumpShock">${tx('SR2E.Card.Actor.resistDumpShockWillpowerVs', { tn, dumpLevel: dump.level })}</button></p>`,
        flags: { [SYSTEM_ID]: { dumpShockFor: this.uuid, dumpShockTn: tn, dumpShockLevel: dump.level } },
      });
      // v0.57.0: hitchers feel it too, and are unplugged.
      await this.#hitcherShock(tn, dump.level);
      await this.#unhitchAll();
    } else if (fu.unhitch) {
      // v0.81.0 (D3-6): a crash with no dump shock (a tortoise) still unplugs the hitchers.
      await this.#unhitchAll();
    }
    const deckDamage = fu.deckDamage;
    if (deckDamage) {
      const ic = deckDamage.ic;
      const sparky = ic.behavior === 'sparky';
      const sp = RULES.MATRIX.sparky;
      await ChatMessage.create({
        speaker: { alias: ic.icName },
        content: `<p><strong>${escText(ic.icName)}</strong> ${tx('SR2E.Card.Actor.sDeckAsThePersonaCrashes', { part: sparky ? tx('SR2E.Card.Actor.fries') : tx('SR2E.Card.Actor.blasts'), name: escText(this.name) })}</p>
          <p><button type="button" data-sr2e-action="deckDamage">${tx('SR2E.Card.Actor.deckDamageRatingVsMpcp', { icRating: ic.rating })}</button>${sparky ? ` <button type="button" data-sr2e-action="biofeedback">${tx('SR2E.Card.Actor.resistBiofeedbackVs', { spResist: escText(cap(sp.resist)), icRating: ic.rating, spLevel: sp.level, spType: sp.type })}</button>` : ''}</p>`,
        flags: { [SYSTEM_ID]: { deckDamage: { deckerUuid: this.uuid, icName: ic.icName, rating: ic.rating, reason: tx('SR2E.Card.Actor.behaviorCrash', { behavior: ic.behavior }) }, ...(sparky ? { biofeedback: { deckerUuid: this.uuid, tn: ic.rating } } : {}) } },
      });
    }
    const overload = fu.overload;
    if (overload !== undefined) {
      const h = RULES.MATRIX.sim.hot;
      await ChatMessage.create({
        speaker: ChatMessage.getSpeaker({ actor: this }),
        content: `<p><strong>${tx('SR2E.Card.Actor.simsenseOverload')}</strong> ${tx('SR2E.Card.Actor.isRunningHotSim', { name: escText(this.name) })}</p><p><button type="button" data-sr2e-action="overload">${tx('SR2E.Card.Actor.resistOverloadWillpowerVsStun', { overload, overloadLevel: h.overloadLevel })}</button></p>`,
        flags: { [SYSTEM_ID]: { overload: { deckerUuid: this.uuid, tn: overload } } },
      });
    }
    const hostChange = fu.hostChange;
    if (hostChange) await SR2Actor.changeHost(hostChange.host, hostChange.change, hostChange.label, this.uuid as string);
    const siteChange = fu.siteChange;
    if (siteChange) await SR2Actor.changeSite(siteChange.site, siteChange.change, siteChange.label, this.uuid as string);
    const aboard = fu.passengers;
    if (aboard?.length) {
      const rows = aboard.map((d, i) => `<li>${escText(fromUuidSync(d.targetUuid)?.name ?? tx('SR2E.Card.Actor.someone'))}: <strong>${d.power}${d.level}</strong> <button type="button" data-sr2e-action="resist" data-index="${i}">${tx('SR2E.Card.Actor.resist')}</button></li>`).join('');
      await ChatMessage.create({
        speaker: ChatMessage.getSpeaker({ actor: this }),
        content: `<p>${tx('SR2E.Card.Actor.theHitCarriesThroughToEveryone', { name: escText(this.name) })}</p><ul class="sr2e-blast">${rows}</ul>`,
        flags: { [SYSTEM_ID]: { damages: aboard, damage: aboard[0] } },
      });
    }
    const shock = fu.riggerShock;
    if (shock) {
      const r = shock;
      const what = r.kind === 'dump' ? `<strong>${tx('SR2E.Card.Actor.isDestroyed', { name: escText(this.name) })}</strong>${tx('SR2E.Card.Actor.isDumpedOutOfIt', { riggerName: escText(r.riggerName) })}` : tx('SR2E.Card.Actor.feelsTheHitThroughTheControl', { riggerName: escText(r.riggerName) });
      await ChatMessage.create({
        speaker: ChatMessage.getSpeaker({ actor: this }),
        content: `<p>${what}</p><p><button type="button" data-sr2e-action="riggerShock">${tx('SR2E.Card.Actor.resistVs', { part: r.kind === 'dump' ? tx('SR2E.Card.Actor.dumpShock2') : tx('SR2E.Card.Actor.feedback'), riggerName: escText(r.riggerName), shockAttr: shockAttr(r), tn: r.tn, level: r.level, type: r.type })}</button></p>`,
        flags: { [SYSTEM_ID]: { riggerShock: r } },
      });
    }
    return posted;
  }

  async #spendKarma(points: number): Promise<boolean> {
    const left = this.sys.derived.karmaPoolLeft as number;
    if (left < points) {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.hasKarmaPoolLeftThisNeeds', { name: escHtml(this.name), left, points }));
      return false;
    }
    await this.update({ 'system.karma.poolSpent': (this.sys.karma.poolSpent as number) + points });
    return true;
  }

  /** Karma Pool: re-roll every failed die of the test on a chat card, and re-resolve what it led to. */
  async karmaReroll(snapIn: TestSnapshot): Promise<void> {
    // v0.81.0 (SEC2-8): the snapshot comes from a card's flags: a sane dice list and re-roll count, or nothing.
    if (!Array.isArray(snapIn?.dice) || snapIn.dice.length > MAX_TEST_DICE) {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.thatTestCanTBeRe'));
      return;
    }
    const snap: TestSnapshot = { ...snapIn, rerolls: safeInt(snapIn.rerolls, 0, 1000, 0), bought: safeInt(snapIn.bought, 0, MAX_TEST_DICE, 0) };
    const failures = snap.dice.filter((d) => !d.success).length;
    if (failures === 0) {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.everyDieAlreadySucceededThereIs'));
      return;
    }
    const cost = karmaRerollCost(snap.rerolls);
    if (!(await this.#spendKarma(cost))) return;
    const rolls: any[] = [];
    const rr = await rerollFailures(asResult(snap), foundryRoller(rolls));
    // v0.71.0 review (F7): successes bought earlier stay bought (and a later GM TN change counts them once).
    const result = { ...rr, successes: rr.successes + Math.max(0, snap.bought ?? 0) };
    const next = withResult({ ...snap, rerolls: snap.rerolls + 1 }, result);
    await this.#post(next, result, rolls, tx('SR2E.Card.Actor.karmaReRollCost', { nextRerolls: next.rerolls, cost }));
  }

  /** v0.50.0: a card replaced since: by a GM's TN change, or by a later card of the same test (a Karma re-roll, a bought success). */
  static isReplaced(message: any): boolean {
    if (!message) return true;
    if (message.getFlag?.(SYSTEM_ID, 'supersededBy')) return true;
    const id = SR2Actor.cardKey(message);
    if (!id) return false;
    const list: any[] = [...((game as any).messages?.contents ?? (game as any).messages ?? [])];
    const at = list.indexOf(message);
    // v0.81.1 (SEC1-2, design 5): only a newer card by a GM or by this card's own author replaces it (every flag is
    // public, so another player's card can carry the same testId).
    const mine = SR2Actor.#authorIdOf(message);
    return list.some((m: any, i: number) => m !== message && (at < 0 ? Number(m.timestamp ?? 0) > Number(message.timestamp ?? 0) : i > at)
      && SR2Actor.cardKey(m) === id && SR2Actor.#mayReplace(m, mine, message));
  }

  /** v0.81.1: a card's author id (v14 `author`, older `user`; a User or an id), or ''. */
  static #authorIdOf(message: any): string {
    const a = message?.author ?? message?.user ?? null;
    return String((a && typeof a === 'object' ? a.id : a) ?? '');
  }

  /** v0.81.1 (design 5): whether card `m` may replace a card by `authorId`: same author, or a GM's (a real User). */
  static #mayReplace(m: any, authorId: string, first: any = null): boolean {
    const id = SR2Actor.#authorIdOf(m);
    if (id === authorId) return true;
    const u = SR2Actor.#cardAuthorOf(m);
    if (Boolean(u) && realGm(u)) return true;
    // Round 2 (V-SEC 6, FIX2-BRIEF G): as chat.ts testChainMember: on a contest, the owner of one of the older card's
    // sides (spending Karma on their side) replaces it too.
    const c = first?.getFlag?.(SYSTEM_ID, 'contest') as Contest | undefined;
    return Boolean(u && c && Array.isArray(c.sides) && c.sides.some((x: any) => typeof x?.uuid === 'string' && x.uuid && userOwns(u, fromUuidSync(x.uuid))));
  }

  /**
   * What ties the cards of one test together: a snapshot's `testId`, or (v0.71.0) a contest's id (a contest
   * card from before v0.71.0 has none: its own message id stands in, and a Karma card made from it carries that).
   */
  static cardKey(message: any): string | undefined {
    const id = (message?.getFlag?.(SYSTEM_ID, 'test') as TestSnapshot | undefined)?.testId;
    if (id) return id;
    const c = message?.getFlag?.(SYSTEM_ID, 'contest') as Contest | undefined;
    return c ? (c.id ?? message.id ?? undefined) : undefined;
  }

  /** v0.81.1: a card's author as a User of this world (v14 `author`, older `user`; an id is looked up), or null. */
  static #cardAuthorOf(message: any): any {
    const a = message?.author ?? message?.user ?? null;
    if (a && typeof a === 'object') return a;
    if (typeof a === 'string' && a) {
      const users: any = (game as any)?.users;
      return users?.get?.(a) ?? [...(users ?? [])].find((u: any) => u?.id === a) ?? null;
    }
    return null;
  }

  /** The original card's author, for a GM-made replacement (v14 `author`, older `user`). */
  static #sameAuthor(like: any): Record<string, string> {
    const a = like?.author?.id ?? like?.author ?? like?.user?.id ?? like?.user ?? null;
    return typeof a === 'string' && a ? { author: a } : {};
  }

  /**
   * v0.50.0 (GM): change a rolled test's TN afterwards. No die is rolled: the dice on the card are
   * scored again against the new TN (`rescoreResult`) and what they led to is worked out again, as a
   * Karma re-roll does (the condition monitor, spirits, hosts and the rest are corrected the same way,
   * when they haven't changed since). The new card replaces the old one, whose buttons are switched off.
   * Opposed contests (perception, social, sneaking) are re-scored on the side picked (`side`).
   */
  static async retarget(message: any, o: { baseTargetNumber: number; modifiers: TargetNumberModifier[]; side?: number }): Promise<any> {
    if (!game.user?.isGM) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.onlyTheGmCanChangeA')); return null; }
    if (SR2Actor.isReplaced(message)) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.thatCardHasBeenReplacedBy')); return null; }
    const snap = message?.getFlag?.(SYSTEM_ID, 'test') as TestSnapshot | undefined;
    const contest = message?.getFlag?.(SYSTEM_ID, 'contest') as Contest | undefined;
    let posted: any = null;
    if (snap) {
      // v0.81.1 (SEC1-1, D1-1): the snapshot is the card author's data. A player's card is re-run as that player
      // (runAsAuthor): what they don't own gets the Apply (GM) cards their own re-roll would post, never a direct
      // write with the GM's rights. A snapshot naming a roller the author doesn't own is refused outright.
      if (!Array.isArray(snap.dice) || snap.dice.length > MAX_TEST_DICE) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.thatCardSDiceAreMissing')); return null; }
      const author = SR2Actor.#cardAuthorOf(message);
      const actor: any = await fromUuid(snap.actorUuid);
      if (!actor || !isActorDoc(actor)) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.theActorWhoRolledThisNo')); return null; }
      if (!realGm(author) && !userOwns(author, actor)) {
        ui.notifications?.warn?.(tx('SR2E.Notify.Actor.thatCardNamesAsTheRoller', { actorName: escText(actor.name) }));
        return null;
      }
      const clean: TestSnapshot = { ...snap, rerolls: safeInt(snap.rerolls, 0, 1000, 0), bought: safeInt(snap.bought, 0, MAX_TEST_DICE, 0), retargets: safeInt(snap.retargets, 0, 1000, 0) };
      const result = rescoreResult(asResult(clean), { baseTargetNumber: o.baseTargetNumber, modifiers: o.modifiers, bought: clean.bought ?? 0 });
      const next = withResult({ ...clean, retargets: (clean.retargets ?? 0) + 1 }, result);
      posted = await SR2Actor.#retargetAs(author, () => actor.#post(next, result, [], tx('SR2E.Card.Actor.tnChangedByTheGm', { from: safeInt(snap.targetNumber, 0, 99, 0), to: result.targetNumber }), message));
    } else if (contest) {
      const i = Math.max(0, Math.min(contest.sides.length - 1, Math.floor(o.side ?? 0)));
      const side = contest.sides[i];
      if (!side?.result) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.didnTRoll', { sideName: escHtml(side?.name ?? tx('SR2E.Notify.Actor.thatSide')) })); return null; }
      const before = side.result.targetNumber;
      const result = rescoreResult(side.result, { baseTargetNumber: o.baseTargetNumber, modifiers: o.modifiers, bought: side.bought ?? 0 });
      const next: Contest = { ...contest, id: contest.id ?? message.id, changed: (contest.changed ?? 0) + 1, sides: contest.sides.map((x, k) => (k === i ? { ...x, result } : x)) };
      posted = await ChatMessage.create({
        speaker: message.speaker, content: `${SR2Actor.contestContent(next)}<p class="hint">${tx('SR2E.Card.Actor.sTnChangedByTheGm', { sideName: escText(side.name), before, resultTargetNumber: result.targetNumber })}</p>`,
        ...SR2Actor.#sameAuthor(message), ...(message.whisper?.length ? { whisper: [...message.whisper], blind: Boolean(message.blind) } : {}),
        // v0.71.0 review (F1): a deal already closed stays closed on the GM's new card.
        flags: { [SYSTEM_ID]: { contest: next, ...SR2Actor.contestFlags(next), retargetOf: message.id ?? '', ...Object.fromEntries((['bought', 'sold', 'superseded', 'requested'] as const).filter((k) => message.getFlag?.(SYSTEM_ID, k)).map((k) => [k, true])) } },
      });
      await SR2Actor.#findRescored(next);
    } else {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.thatCardHasNoRollWhose'));
      return null;
    }
    if (posted) await message.update({ [`flags.${SYSTEM_ID}.supersededBy`]: posted.id });
    return posted;
  }

  /** v0.50.0: the scene's modifiers on this actor right now (weather, light at its token, background count), for the GM's checklist. */
  sceneCandidates(): TargetNumberModifier[] {
    const out: TargetNumberModifier[] = [];
    try {
      const vision = this.visionNow();
      const w = weatherModifier(this.weatherHere(), vision);
      if (w) out.push(w);
      const t = SR2Actor.tokenFor(this);
      const l = lightModifier((t ? targetLight(t)?.light : sceneLight()?.light) ?? null, vision);
      if (l) out.push(l);
      const bg = this.backgroundInfo?.().penalty ?? 0;
      if (bg) out.push(...backgroundCountModifiers(bg));
      out.push(...this.#testModifiers({}));
    } catch { /* no scene */ }
    return out;
  }

  /** Karma Pool: turn a disaster (all ones) into an ordinary failure. */
  async avoidDisaster(snap: TestSnapshot): Promise<void> {
    if (!snap.botch) return;
    if (!(await this.#spendKarma(avoidDisasterCost()))) return;
    const next: TestSnapshot = { ...snap, botch: false, disasterAvoided: true };
    await this.#post(next, asResult(next), [], tx('SR2E.Card.Actor.disasterAvoidedKarma'));
  }

  /** Karma Pool: buy one more success on a test (v0.35.0; permanent by default), and re-resolve it. */
  async buySuccess(snap: TestSnapshot): Promise<boolean> {
    const k = this.sys.karma ?? {};
    const left = Math.max(0, (k.pool ?? 0) - (k.poolSpent ?? 0));
    const c = canBuySuccess({ successes: snap.successes, poolLeft: left, botch: snap.botch });
    if (!c.ok) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.canTBuyASuccess', { reason: escHtml(c.reason) })); return false; }
    await this.update(RULES.KARMA.buyPermanent ? { 'system.karma.pool': (k.pool ?? 0) - c.cost } : { 'system.karma.poolSpent': (k.poolSpent ?? 0) + c.cost });
    const r = asResult(snap);
    const result = { ...r, successes: r.successes + 1 };
    const next = withResult({ ...snap, bought: (snap.bought ?? 0) + 1 }, result);
    await this.#post(next, result, [], tx('SR2E.Card.Actor.boughtSuccessKarma', { nextBought: next.bought, cost: c.cost, part: RULES.KARMA.buyPermanent ? tx('SR2E.Card.Actor.permanent') : '' }));
    return true;
  }

  // ---------------------------------------------------------------- Barriers, charges, throwing grenades back (v0.37.0)

  /**
   * Damage a wall (an SR2 barrier): Power over its rating comes off the rating; at 0 it is breached
   * (blocks nothing any more; the old settings are kept in a flag). Returns the result.
   */
  static async damageWall(doc: any, power: number, opts: { antiVehicle?: boolean; shaped?: boolean; label?: string; kind?: BarrierAttackKind } = {}): Promise<{ damage: number; left: number; breached: boolean } | null> {
    if (!doc) return null;
    const def = RULES.COMBAT.barriers.defaultWallRating;
    const rating = Number(doc.getFlag?.(SYSTEM_ID, 'barrierRating') ?? doc.flags?.sr2e?.barrierRating ?? def) || 0;
    // v0.78.0 (RULES.BOOK_V78.barriers 'book'): what hits it (firearm, melee, combat spell or blast), and doors.
    const isDoor = Number(doc.door ?? 0) > 0;
    const door = !isDoor ? 'none' : doc.getFlag?.(SYSTEM_ID, 'securityDoor') ? 'security' : 'ordinary';
    const full = Number(doc.getFlag?.(SYSTEM_ID, 'barrierFull') ?? rating) || rating;
    const r = barrierDamage({ rating, power, antiVehicle: opts.antiVehicle, shaped: opts.shaped, kind: opts.kind ?? 'firearm', door, full });
    if (r.damage > 0) {
      const update: Record<string, unknown> = { [`flags.${SYSTEM_ID}.barrierRating`]: r.left };
      if (r.holes > 0) update[`flags.${SYSTEM_ID}.barrierHoles`] = Number(doc.getFlag?.(SYSTEM_ID, 'barrierHoles') ?? 0) + r.holes;
      // v0.43.0: remember the undamaged rating, for repairs.
      if (doc.getFlag?.(SYSTEM_ID, 'barrierFull') == null) update[`flags.${SYSTEM_ID}.barrierFull`] = rating;
      if (r.breached) {
        update[`flags.${SYSTEM_ID}.breached`] = { move: doc.move, sight: doc.sight, light: doc.light, sound: doc.sound, rating };
        Object.assign(update, { move: 0, sight: 0, light: 0, sound: 0 });
      }
      await doc.update(update);
      // v0.49.0: breaking a door wired to a site open trips its tamper alarm (once: the door is then bypassed).
      if (r.breached) await SR2Actor.#wallForced(doc);
    }
    await ChatMessage.create({
      speaker: { alias: tx('SR2E.Card.Actor.barrier') },
      content: `<p><strong>${escText(opts.label ?? tx('SR2E.Card.Actor.aBarrier'))}</strong> ${tx('SR2E.Card.Actor.ratingTakesPower', { rating, part: RULES.BOOK_V78.barriers.mode === 'book' && r.adjusted !== rating ? tx('SR2E.Card.Actor.against', { adjusted: r.adjusted, part: opts.kind === 'melee' ? tx('SR2E.Card.Actor.melee2') : opts.kind === 'combatSpell' ? tx('SR2E.Card.Actor.aCombatSpell') : tx('SR2E.Card.Actor.gunfire') }) : '', power, part2: opts.shaped ? tx('SR2E.Card.Actor.shapedCharge') : opts.antiVehicle ? tx('SR2E.Card.Actor.antiVehicle') : '', part3: r.damage > 0 ? tx('SR2E.Card.Actor.now2', { damage: r.damage, left: r.left, part: r.holes ? tx('SR2E.Card.Actor.aHoleOfM', { value: r.holes * 0.5 }) : '', part2: r.breached ? (door !== 'none' && r.left > 0 ? ` <strong>${tx('SR2E.Card.Actor.theDoorBreaks')}</strong>` : ` <strong>${tx('SR2E.Card.Actor.itIsBreached')}</strong>`) : '' }) : RULES.BOOK_V78.barriers.mode === 'book' ? tx('SR2E.Card.Actor.noDamagePowerMustReachHalf', { adjusted: r.adjusted }) : tx('SR2E.Card.Actor.noDamagePowerMustBeatThe') })}</p>`,
    });
    return { damage: r.damage, left: r.left, breached: r.breached };
  }

  /** Walls on the scene that have been damaged or breached (v0.43.0). */
  static damagedWalls(scene: any = (globalThis as any).canvas?.scene): Array<{ id: string; rating: number; full: number; breached: boolean; doc: any }> {
    const out: Array<{ id: string; rating: number; full: number; breached: boolean; doc: any }> = [];
    for (const w of [...(scene?.walls ?? [])] as any[]) {
      const br = w.getFlag?.(SYSTEM_ID, 'breached') ?? w.flags?.sr2e?.breached;
      const full = Number(w.getFlag?.(SYSTEM_ID, 'barrierFull') ?? w.flags?.sr2e?.barrierFull ?? br?.rating ?? NaN);
      const rating = Number(w.getFlag?.(SYSTEM_ID, 'barrierRating') ?? w.flags?.sr2e?.barrierRating ?? 0) || 0;
      if (br || (Number.isFinite(full) && rating < full)) out.push({ id: w.id, rating, full: Number.isFinite(full) ? full : rating, breached: Boolean(br), doc: w });
    }
    return out;
  }

  /**
   * Repair a wall (v0.43.0): back to its original rating (`full`), or up by `successes` × the repair
   * rate. A breached wall blocks movement, sight, light and sound again as it did before.
   */
  static async repairWall(doc: any, opts: { successes?: number; full?: boolean; label?: string } = {}): Promise<number | null> {
    if (!doc) return null;
    const br = doc.getFlag?.(SYSTEM_ID, 'breached') ?? doc.flags?.sr2e?.breached;
    const rating = Number(doc.getFlag?.(SYSTEM_ID, 'barrierRating') ?? doc.flags?.sr2e?.barrierRating ?? 0) || 0;
    const full = Number(doc.getFlag?.(SYSTEM_ID, 'barrierFull') ?? doc.flags?.sr2e?.barrierFull ?? br?.rating ?? rating) || 0;
    const now = wallRepair({ rating, original: full, successes: opts.successes ?? 0, full: opts.full ?? (opts.successes == null) });
    const update: Record<string, unknown> = { [`flags.${SYSTEM_ID}.barrierRating`]: now };
    if (br && now > 0) {
      Object.assign(update, { move: br.move, sight: br.sight, light: br.light, sound: br.sound, [`flags.${SYSTEM_ID}.-=breached`]: null });
    }
    if (now >= full) update[`flags.${SYSTEM_ID}.-=barrierFull`] = null;
    await doc.update(update);
    await ChatMessage.create({ speaker: { alias: tx('SR2E.Card.Actor.barrier') }, content: `<p><strong>${escText(opts.label ?? tx('SR2E.Card.Actor.aBarrier'))}</strong> ${(full ? tx('SR2E.Card.Actor.isRepairedRatingWithOf', { rating, now, part2: br && now > 0 ? tx('SR2E.Card.Actor.itBlocksAgain') : '', full }) : tx('SR2E.Card.Actor.isRepairedRatingPlain', { rating, now, part2: br && now > 0 ? tx('SR2E.Card.Actor.itBlocksAgain') : '' }))}</p>` });
    return now;
  }

  /** A Build/Repair test on a damaged wall (RULES.GEAR.walls): each success puts rating back. */
  async repairWallTest(doc: any): Promise<number | null> {
    if (!doc) return null;
    const w = RULES.GEAR.walls;
    const sd = this.#skillDice(this.findSkill(w.repairSkill), false, null, w.repairAttribute as AttributeKey);
    const rolls: any[] = [];
    const r = await successTest({ dice: sd.dice, targetNumber: w.repairTn, modifiers: this.#testModifiers({ modifiers: sd.modifiers }), roll: foundryRoller(rolls) });
    await ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor: this }), rolls, content: describeResult(tx('SR2E.Card.Actor.repairsAWall', { name: this.name, repairSkill: w.repairSkill, sdSuffix: sd.suffix }), r) });
    if (r.successes <= 0) return null;
    return SR2Actor.repairWall(doc, { successes: r.successes, full: false, label: tx('SR2E.Card.Actor.theWall') });
  }

  /** Detonates a blast at a point on the viewed scene; chat.ts registers it at start-up (v0.43.0). */
  static detonator: ((actor: any, ctx: BlastContext, point: { x: number; y: number; elevation?: number }, note: string) => Promise<void>) | null = null;

  /**
   * v0.81.0 (SEC1-6, SEC1-12): the charge a Detonate card stands for, from a stored record, never the card: the
   * scene's armed charge (timed; the GM's) when `sceneId` names one, else the setter's own record of the charges
   * they set (actor flag `setCharges`, written by their own setCharge). Null when there is no such charge.
   * v0.81.1 (SEC1-16, D1-11): a setter's record is bounded by the explosive item it names; one whose item is gone or
   * isn't an explosive is refused (null): only a GM's click may set it off, after a confirm (`chargeRecordForGm`).
   * Null means "no stored charge": the caller doesn't fall back to a player's card's numbers.
   */
  static storedCharge(actor: any, chargeId: string, sceneId = ''): { name: string; power: number; perMetre: number; shaped: boolean; point?: { x: number; y: number; elevation: number } } | null {
    if (!chargeId) return null;
    const scene: any = sceneId ? (game as any).scenes?.get?.(sceneId) : null;
    const armed = scene ? SR2Actor.armedCharges(scene).find((x) => x.id === chargeId) : null;
    if (armed && armed.actorUuid === actor?.uuid) return { name: armed.name, power: armed.power, perMetre: armed.perMetre, shaped: armed.shaped, point: armed.point };
    const mine = ((actor?.getFlag?.(SYSTEM_ID, 'setCharges') as any[] | undefined) ?? []).find((x: any) => x?.id === chargeId);
    if (!mine) return null;
    // R2-SEC 6: the fall-off is a fraction for some explosives (0.5, 0.25 per metre): bounded as a number, not an integer.
    const pm = Number(mine.perMetre);
    let power = safeInt(mine.power, 0, 200, 0);
    let perMetre = Number.isFinite(pm) ? Math.min(200, Math.max(0, pm)) : 1;
    let shaped = Boolean(mine.shaped);
    // R2-SEC 10: the record is the setter's own flag, so it is checked against the explosive it names (when that is
    // still there): no more Power than the item's plus the most successes the setter's Demolitions dice can roll, and
    // the item's own fall-off and shaping.
    const item: any = mine.itemId ? actor?.items?.get?.(String(mine.itemId)) ?? null : null;
    const ex = item?.system?.explosive;
    // Round 3 (V2 #2, FIX3-BRIEF 2; SEC1-16 back): a record with no explosive item behind it (gone, or not an explosive)
    // is refused: its owner writes the record. A GM may still set one off after a confirm (chargeRecordForGm).
    if (!(ex && Number(ex.power) > 0)) return null;
    {
      const d = RULES.COMBAT.demolitions;
      const dice = actor instanceof SR2Actor ? Math.max(0, Number(actor.#skillDice(actor.findSkill(d.skill), false, null, d.attribute as AttributeKey).dice) || 0) : 0;
      power = Math.min(power, chargePower(safeInt(ex.power, 0, 200, 0), Math.min(dice, safeInt(mine.successes, 0, 100, dice))));
      const ipm = Number(ex.perMetre);
      if (Number.isFinite(ipm) && ipm >= 0) perMetre = Math.min(200, ipm);
      shaped = Boolean(ex.shaped);
    }
    return { name: String(mine.name ?? 'Charge'), power, perMetre, shaped, ...(mine.point ? { point: mine.point } : {}) };
  }

  /**
   * Round 3 (FIX3-BRIEF 2, H5): a setter's charge record whose explosive item is gone (its spent stack deleted, or a
   * card from before v0.81.0's records), for a GM's click only: the record's Power bounded at 200 and its fall-off at
   * the gentlest grenade's, with the confirm text naming them (plain text: the caller escapes it). Null for anyone
   * but a GM, or when there is no record at all.
   */
  static chargeRecordForGm(actor: any, chargeId: string): { charge: { name: string; power: number; perMetre: number; shaped: boolean; point?: { x: number; y: number; elevation: number } }; text: string } | null {
    if (!(game as any).user?.isGM || !chargeId) return null;
    const mine = ((actor?.getFlag?.(SYSTEM_ID, 'setCharges') as any[] | undefined) ?? []).find((x: any) => x?.id === chargeId);
    if (!mine) return null;
    const pm = Number(mine.perMetre);
    const charge = { name: String(mine.name ?? 'Charge').slice(0, 200), power: safeInt(mine.power, 0, 200, 0), perMetre: Number.isFinite(pm) ? Math.min(200, Math.max(0.25, pm)) : 1, shaped: Boolean(mine.shaped), ...(mine.point ? { point: mine.point } : {}) };
    return { charge, text: tx('SR2E.Text.Actor.sItsExplosiveIsnTOn', { name: String(actor?.name ?? tx('SR2E.Text.Actor.someone')), chargeName: charge.name, power: charge.power, perMetre: charge.perMetre }) };
  }

  /**
   * Round 3 (FX-APP-WIRING3 1): what chat.ts `onDetonateCharge` shows a GM before setting off a player's charge that
   * has no stored record behind it. With the setter's own record (its explosive gone): its bounded Power and fall-off.
   * Null when there is no record (chat.ts then uses the card's own bounded numbers). GM clients only.
   */
  static detonateConfirmText(actor: any, chargeId: string, _sceneId = '', _raw: unknown = null): { text: string; power: number; perMetre: number; shaped: boolean } | null {
    const rec = SR2Actor.chargeRecordForGm(actor, String(chargeId ?? ''));
    return rec ? { text: rec.text, power: rec.charge.power, perMetre: rec.charge.perMetre, shaped: rec.charge.shaped } : null;
  }

  /** Charges armed with a timer on a scene (scene flag `charges`). */
  static armedCharges(scene: any = (globalThis as any).canvas?.scene): ArmedCharge[] {
    return [...((scene?.getFlag?.(SYSTEM_ID, 'charges') as ArmedCharge[] | undefined) ?? [])];
  }

  /** Blow an armed charge now (its timer ran out, or the GM or setter sets it off early). */
  static async blowCharge(sceneId: string, chargeId: string, why = tx('SR2E.Card.Actor.goesOff')): Promise<boolean> {
    const scene: any = (game as any).scenes?.get?.(sceneId);
    const list = SR2Actor.armedCharges(scene);
    const c = list.find((x) => x.id === chargeId);
    if (!scene || !c) return false;
    await scene.setFlag(SYSTEM_ID, 'charges', list.filter((x) => x.id !== chargeId));
    const actor: any = await fromUuid(c.actorUuid);
    const ctx: BlastContext = {
      attackerUuid: c.actorUuid, weaponName: c.name, power: c.power, level: RULES.COMBAT.demolitions.level, damageType: 'physical',
      perMetre: c.shaped ? Math.max(c.perMetre, c.power) : c.perMetre, point: c.point, dodge: false, kind: 'demolition', ...(c.shaped ? { shaped: true } : {}),
    };
    const viewed = (globalThis as any).canvas?.scene?.id === sceneId;
    if (actor && viewed && SR2Actor.detonator) {
      await SR2Actor.detonator(actor, ctx, c.point, c.shaped ? tx('SR2E.Card.Actor.chargeWhyShaped', { name: escText(c.name), why: escText(why) }) : tx('SR2E.Card.Actor.chargeWhy', { name: escText(c.name), why: escText(why) }));
    } else {
      await ChatMessage.create({ speaker: { alias: tx('SR2E.Card.Actor.demolitions') }, content: `<p><strong>${escText(c.name)}</strong> ${tx('SR2E.Card.Actor.onPowerViewThatSceneTo', { why: escText(why), sceneName: escText(scene.name), power: c.power })}</p>
        <p><button type="button" data-sr2e-action="detonateCharge">${tx('SR2E.Card.Actor.detonateThere')}</button></p>`, flags: { [SYSTEM_ID]: { charge: { actorUuid: c.actorUuid, name: c.name, power: c.power, perMetre: c.perMetre, shaped: c.shaped, point: c.point, sceneId, chargeId: c.id } } } });
    }
    return true;
  }

  /** Disarm (remove) an armed charge without it going off (GM). */
  static async disarmCharge(sceneId: string, chargeId: string): Promise<boolean> {
    const scene: any = (game as any).scenes?.get?.(sceneId);
    const list = SR2Actor.armedCharges(scene);
    const c = list.find((x) => x.id === chargeId);
    if (!scene || !c) return false;
    await scene.setFlag(SYSTEM_ID, 'charges', list.filter((x) => x.id !== chargeId));
    await ChatMessage.create({ speaker: { alias: tx('SR2E.Card.Actor.demolitions') }, content: `<p>${tx('SR2E.Card.Actor.onIsDisarmed', { name: escText(c.name), sceneName: escText(scene.name) })}</p>` });
    return true;
  }

  /**
   * Try to disarm an armed charge (v0.47.0, RULES.GEAR.disarm): Demolitions vs a TN raised by the setter's
   * successes. Success removes it; all ones (a disaster) sets it off when `disasterBlows` is on.
   * Changing the scene's charges needs the GM (or the scene's owner).
   */
  async disarmChargeTest(sceneId: string, chargeId: string, opts: { modifiers?: TargetNumberModifier[] } = {}): Promise<'disarmed' | 'failed' | 'blown' | null> {
    const scene: any = (game as any).scenes?.get?.(sceneId);
    const c = SR2Actor.armedCharges(scene).find((x) => x.id === chargeId);
    if (!scene || !c) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.thatChargeIsNoLongerArmed')); return null; }
    if (!(isGmNow() || canWriteNow(scene))) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.onlyTheGmCanChangeThe')); return null; }
    const d = RULES.COMBAT.demolitions;
    const sd = this.#skillDice(this.findSkill(d.skill), false, null, d.attribute as AttributeKey);
    const tn = chargeDisarmTn(c.setterSuccesses ?? 0);
    const rolls: any[] = [];
    const r = await successTest({ dice: sd.dice, targetNumber: tn, modifiers: this.#testModifiers({ modifiers: [...(opts.modifiers ?? []), ...sd.modifiers] }), roll: foundryRoller(rolls) });
    const blows = r.botch && RULES.GEAR.disarm.disasterBlows;
    const outcome = r.successes > 0 ? 'disarmed' : blows ? 'blown' : 'failed';
    await ChatMessage.create({
      speaker: ChatMessage.getSpeaker({ actor: this }), rolls,
      content: `${describeResult(tx('SR2E.Card.Actor.disarmsTn', { name: this.name, name2: c.name, skill: d.skill, sdSuffix: sd.suffix, tn, part: c.setterSuccesses ? tx('SR2E.Card.Actor.setWith', { plural: plural(c.setterSuccesses, 'success') }) : '' }), r)}<p>${outcome === 'disarmed' ? `<strong>${tx('SR2E.Card.Actor.disarmed')}</strong>` : outcome === 'blown' ? `<strong>${tx('SR2E.Card.Actor.disaster4')}</strong> ${tx('SR2E.Card.Actor.itGoesOff')}` : `<strong>${tx('SR2E.Card.Actor.notYet')}</strong> ${tx('SR2E.Card.Actor.itIsStillArmed')}`}</p>`,
    });
    if (outcome === 'disarmed') await SR2Actor.disarmCharge(sceneId, chargeId);
    else if (outcome === 'blown') await SR2Actor.blowCharge(sceneId, chargeId, tx('SR2E.Card.Actor.goesOffAsTriesToDisarmIt', { name: this.name }));
    return outcome;
  }

  /** GM: charges whose timers have run out go off (a Combat Turn reached, or the world time passed). */
  static async chargeTicks(at: { round?: number | null; worldTime?: number; combatId?: string | null }): Promise<void> {
    const all: any = (game as any).scenes;
    const scenes: any[] = Array.isArray(all?.contents) ? all.contents : all && typeof all[Symbol.iterator] === 'function' ? [...all] : [];
    for (const scene of scenes) {
      for (const c of SR2Actor.armedCharges(scene)) {
        const card: any = c.messageId ? (game as any).messages?.get?.(c.messageId) : null;
        // v0.54.0: a player who set it off from the GM's card records that on their own actor (cardRolls).
        const setter: any = card ? fromUuidSync((card.getFlag?.(SYSTEM_ID, 'charge') as any)?.actorUuid ?? '') : null;
        const setOff = card?.getFlag?.(SYSTEM_ID, 'blasted') || ((setter?.getFlag?.(SYSTEM_ID, 'cardRolls') as string[] | undefined) ?? []).includes(`${card?.id}:blasted`);
        if (setOff) {
          // Already set off from its card: just clear the timer.
          await scene.setFlag(SYSTEM_ID, 'charges', SR2Actor.armedCharges(scene).filter((x) => x.id !== c.id));
          continue;
        }
        if (effectEnded(c.at, at)) {
          await SR2Actor.blowCharge(scene.id, c.id, tx('SR2E.Card.Actor.goesOffTimer'));
          if (canWriteNow(card)) await card.setFlag(SYSTEM_ID, 'blasted', true);
        }
      }
    }
  }

  /** Set an explosive charge (a gear item with an explosive Power): Demolitions vs TN; successes add Power. A Detonate card follows. */
  async setCharge(itemId: string, opts: { modifiers?: TargetNumberModifier[]; timerSeconds?: number; point?: { x: number; y: number; elevation: number } | null; sceneId?: string; placeName?: string } = {}): Promise<{ power: number } | null> {
    const item: any = [...this.items].find((i: any) => i.id === itemId);
    const ex = item?.system?.explosive;
    if (!item || !(ex?.power > 0)) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.thatIsNotAnExplosive')); return null; }
    if ((item.system.quantity ?? 1) < 1) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.noLeft', { itemName: escHtml(item.name) })); return null; }
    if (!isCarried(item)) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.notCarried', { name: escHtml(item.name) })); return null; }
    const d = RULES.COMBAT.demolitions;
    const sd = this.#skillDice(this.findSkill(d.skill), false, null, d.attribute as AttributeKey);
    const rolls: any[] = [];
    const r = await successTest({ dice: sd.dice, targetNumber: d.tn, modifiers: this.#testModifiers({ modifiers: [...(opts.modifiers ?? []), ...sd.modifiers] }), roll: foundryRoller(rolls) });
    const power = r.botch ? 0 : chargePower(ex.power, r.successes);
    await item.update({ 'system.quantity': Math.max(0, (item.system.quantity ?? 1) - 1) });
    // A timer (v0.43.0): the charge waits on the scene and goes off by itself.
    const secs = Math.max(0, Math.floor(opts.timerSeconds ?? 0));
    // v0.81.0 (SEC1-12): every set charge has an id and a record on the setter (storedCharge reads the Power from it).
    const chargeId: string = (foundry as any).utils?.randomID?.() ?? `c${Date.now()}`;
    if (power > 0) {
      const kept = ((this.getFlag?.(SYSTEM_ID, 'setCharges') as any[] | undefined) ?? []).slice(-19);
      try { await this.setFlag(SYSTEM_ID, 'setCharges', [...kept, { id: chargeId, itemId: item.id, successes: r.successes, name: item.name, power, perMetre: ex.perMetre, shaped: Boolean(ex.shaped), ...(opts.point ? { point: opts.point } : {}) }]); } catch (err) { console.warn('sr2e | charge record', err); }
    }
    const scene: any = opts.sceneId ? (game as any).scenes?.get?.(opts.sceneId) : (globalThis as any).canvas?.scene;
    let timed: ArmedCharge | null = null;
    if (power > 0 && secs > 0 && opts.point && scene && (isGmNow() || canWriteNow(scene))) {
      const combat: any = (game as any).combat;
      const at = effectEnds({ round: combat?.started ? Number(combat.round ?? 0) : null, worldTime: sysNow(), seconds: secs, combatId: combat?.started ? String(combat.id ?? '') : null });
      timed = { id: chargeId, actorUuid: this.uuid as string, name: item.name, power, perMetre: ex.perMetre, shaped: Boolean(ex.shaped), point: opts.point, at, seconds: secs, place: opts.placeName ?? '', messageId: '', setterSuccesses: r.successes };
    }
    const timerNote = timed ? ` ${tx('SR2E.Card.Actor.timer')} <strong>${secs} s</strong>${tx('SR2E.Card.Actor.itGoesOffByItself', { part: timed.at.round >= 0 ? tx('SR2E.Card.Actor.combatTurn', { atRound: timed.at.round }) : '', part2: timed.place ? tx('SR2E.Card.Actor.on7', { timedPlace: escText(timed.place) }) : '' })}` : secs > 0 && power > 0 ? tx('SR2E.Card.Actor.theTimerNeedsAGmTo') : '';
    const msg: any = await ChatMessage.create(withRollMode({
      speaker: ChatMessage.getSpeaker({ actor: this }),
      content: `${describeResult(tx('SR2E.Card.Actor.setting', { itemName: item.name, skill: d.skill, sdSuffix: sd.suffix }), r)}<p>${r.botch ? `<strong>${tx('SR2E.Card.Actor.disaster4')}</strong> ${tx('SR2E.Card.Actor.theChargeIsADudOr')}` : `${tx('SR2E.Card.Actor.chargeSet')} <strong>${tx('SR2E.Card.Actor.power', { power })}</strong>${ex.shaped ? tx('SR2E.Card.Actor.shapedAgainstABarrier') + RULES.COMBAT.barriers.shapedMultiplier + tx('SR2E.Card.Actor.noBlastBeyondIt') : tx('SR2E.Card.Actor.perMetre', { exPerMetre: escText(ex.perMetre) })}.${timerNote}`}</p>
        ${power > 0 ? `<p><button type="button" data-sr2e-action="detonateCharge" title="${timed ? tx('SR2E.Card.Actor.setItOffNowBeforeThe') : tx('SR2E.Card.Actor.blowsAtTheTargetedTokenOr')}">${(timed ? tx('SR2E.Card.Actor.detonate2WithNow3') : tx('SR2E.Card.Actor.detonate2Plain'))}</button></p>` : ''}`,
      rolls,
      flags: { [SYSTEM_ID]: { charge: { actorUuid: this.uuid, name: item.name, power, perMetre: ex.perMetre, shaped: Boolean(ex.shaped), ...(opts.point ? { point: opts.point } : {}), chargeId, ...(timed ? { sceneId: scene.id } : {}) } } },
    }));
    if (timed) await scene.setFlag(SYSTEM_ID, 'charges', [...SR2Actor.armedCharges(scene), { ...timed, messageId: msg?.id ?? '' }]);
    return { power };
  }

  /** Throw a grenade back: Throwing (or Quickness at +4) vs TN. Returns the successes. */
  async throwBackTest(): Promise<SuccessTestResult> {
    const t = RULES.COMBAT.throwBack;
    const sd = this.#skillDice(this.findSkill(t.skill), false, null, t.attribute as AttributeKey);
    const rolls: any[] = [];
    const r = await successTest({ dice: sd.dice, targetNumber: t.tn, modifiers: this.#testModifiers({ modifiers: sd.modifiers }), roll: foundryRoller(rolls) });
    await ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor: this }), content: `${describeResult(tx('SR2E.Card.Actor.grabsTheGrenadeToThrowIt', { name: this.name, skill: t.skill, sdSuffix: sd.suffix }), r)}<p>${r.successes > 0 ? `<strong>${tx('SR2E.Card.Actor.thrownBack')}</strong>` : `<strong>${tx('SR2E.Card.Actor.tooSlow')}</strong> ${tx('SR2E.Card.Actor.itGoesOffWhereItLanded')}`}</p>`, rolls });
    return r;
  }

  /** Repair degraded armor. */
  async repairArmor(itemId: string): Promise<boolean> {
    const item: any = [...this.items].find((i: any) => i.id === itemId);
    if (!item || !(item.system.degraded > 0)) return false;
    await item.update({ 'system.degraded': 0 });
    return true;
  }

  // ---------------------------------------------------------------- GM overrides on cards (v0.35.0)

  /**
   * v0.81.0 (SEC1-5, SEC2-8): the most boxes a track can hold: Stun the monitor, Physical the monitor plus the
   * overflow (Body) and one more (dead). Numbers from a card are clamped to this.
   */
  static #boxCap(a: any, track: 'physical' | 'stun'): number {
    const boxes = Number(RULES.MONITOR_BOXES ?? 10);
    if (track === 'stun') return boxes;
    const body = Number(a?.system?.derived?.vitals?.overflowBody ?? a?.system?.attributes?.body?.total ?? 0);
    return boxes + Math.max(0, Number.isFinite(body) ? Math.floor(body) : 0) + 1;
  }

  /**
   * GM: undo the damage a resist card applied (back to the monitor before it).
   * v0.81.0 (SEC1-5, SEC2-8): the snapshot comes from a card: only an actor's own condition monitor, the "before"
   * values clamped to the track, and (from a card, `o.author` = its server-set author) only when that author is a GM
   * or owns the actor.
   */
  static async gmUndoSoak(snap: TestSnapshot, o: { author?: any } = {}): Promise<boolean> {
    const a: any = await fromUuid(String(snap?.actorUuid ?? ''));
    const ctx = snap?.soak;
    if (!isActorDoc(a) || !a.system?.monitor || !ctx || ctx.track || !ctx.before) return false;
    if (o.author !== undefined && !userOwns(o.author, a)) return false;
    const before = { physical: safeInt(ctx.before.physical, 0, SR2Actor.#boxCap(a, 'physical'), -1), stun: safeInt(ctx.before.stun, 0, SR2Actor.#boxCap(a, 'stun'), -1) };
    if (before.physical < 0 || before.stun < 0) return false;
    const cur = { physical: a.system.monitor.physical, stun: a.system.monitor.stun };
    const changed = ctx.after && !sameMonitor(cur, ctx.after);
    await a.update({ 'system.monitor.physical': before.physical, 'system.monitor.stun': before.stun });
    await ChatMessage.create({ speaker: { alias: tx('SR2E.Card.Actor.gm') }, content: `<p><strong>${tx('SR2E.Card.Actor.gm2')}</strong> ${tx('SR2E.Card.Actor.undidSDamageFromBackTo', { name: escText(a.name), label: escText(snap.label), beforePhysical: before.physical, beforeStun: before.stun, part: changed ? tx('SR2E.Card.Actor.itHadChangedSinceSoLater') : '' })}</p>` });
    return true;
  }

  /**
   * GM: add or take off boxes on a track.
   * v0.81.0 (SEC1-5, SEC2-8): `track` is Physical or Stun only, `delta` a whole number no bigger than the track, the
   * result kept on the track; from a card (`o.author`), only when its author is a GM or owns the actor.
   */
  static async gmAdjustBoxes(actorUuid: string, track: 'physical' | 'stun', delta: number, o: { author?: any } = {}): Promise<boolean> {
    if (track !== 'physical' && track !== 'stun') return false;
    const a: any = await fromUuid(String(actorUuid ?? ''));
    if (!isActorDoc(a) || !a.system?.monitor) return false;
    if (o.author !== undefined && !userOwns(o.author, a)) return false;
    const cap = SR2Actor.#boxCap(a, track);
    const d = safeInt(delta, -cap, cap, 0);
    if (!d) return false;
    const now = Math.max(0, Math.min(cap, Number(a.system.monitor[track] ?? 0) + d));
    await a.update({ [`system.monitor.${track}`]: now });
    await ChatMessage.create({ speaker: { alias: tx('SR2E.Card.Actor.gm') }, content: `<p><strong>${tx('SR2E.Card.Actor.gm2')}</strong> ${tx('SR2E.Card.Actor.now', { name: escText(a.name), part: d > 0 ? `+${d}` : d, track, now })}</p>` });
    return true;
  }

  /** GM: apply a hit's damage without a resistance test (full level, no armor). */
  async applyUnresisted(damage: DamageState): Promise<boolean> {
    if (damage.matrix || this.type === 'vehicle') { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.applyWithoutResistingWorksOnCharacters')); return false; }
    const before = { physical: this.sys.monitor.physical, stun: this.sys.monitor.stun };
    const r = applyDamageToMonitor(before, damage.damageType, damage.level, Number(this.sys.derived?.vitals?.overflowBody ?? this.sys.attributes.body.total));
    await this.update({ 'system.monitor.physical': r.monitor.physical, 'system.monitor.stun': r.monitor.stun });
    await ChatMessage.create({ speaker: { alias: tx('SR2E.Card.Actor.gm') }, content: `<p><strong>${tx('SR2E.Card.Actor.gm2')}</strong> ${tx('SR2E.Card.Actor.takes', { name: escText(this.name) })} <strong>${damage.level}</strong> ${tx('SR2E.Card.Actor.unresistedStatus', { damageDamageType: damage.damageType, plural: escText(plural(r.boxes, 'box')) })} <strong>${r.status}</strong>.</p>` });
    return true;
  }

  /**
   * GM (v0.41.0): a quick roll for several actors at once (NPCs, a selection, the party): an
   * attribute or a skill (defaulting as usual), each with their own wound and other penalties.
   * One summary card, whispered to the GMs unless `public`. No Karma re-rolls.
   */
  static async groupRoll(actors: any[], opts: { attribute?: AttributeKey; skill?: string; targetNumber?: number; label?: string; public?: boolean }): Promise<Array<{ name: string; successes: number; botch: boolean }>> {
    const tn = opts.targetNumber ?? 4;
    const rolls: any[] = [];
    const rows: Array<{ name: string; dice: number; tn: number; successes: number; botch: boolean; note: string }> = [];
    for (const a of actors.filter((x: any) => x && x.system?.attributes)) {
      let dice: number;
      let mods: TargetNumberModifier[] = [];
      let note = '';
      if (opts.skill) {
        const sd = (a as SR2Actor).#skillDice(a.findSkill?.(opts.skill), false, null, opts.attribute ?? 'intelligence', { skillName: opts.skill });
        dice = sd.dice; mods = sd.modifiers; note = sd.suffix.replace(/^\s*\(|\)\s*$/g, '').trim();
      } else {
        const key = opts.attribute ?? 'intelligence';
        dice = a.system.attributes[key]?.total ?? 0;
      }
      // Each actor's own roll list, so only Rule of Six re-rolls count as later waves (Dice So Nice colours).
      const mine: any[] = [];
      const r = await successTest({ dice, targetNumber: tn, modifiers: [...mods, ...(a as SR2Actor).#testModifiers({ targetNumber: tn })], roll: foundryRoller(mine) });
      rolls.push(...mine);
      rows.push({ name: a.name, dice: r.totalDice, tn: r.targetNumber, successes: r.successes, botch: r.botch, note });
    }
    const what = opts.label || (opts.skill ? `${opts.skill}` : cap(opts.attribute ?? tx('SR2E.Card.Actor.intelligence')));
    const gms = [...((game as any).users ?? [])].filter((u: any) => u.isGM).map((u: any) => u.id);
    await ChatMessage.create({
      speaker: { alias: tx('SR2E.Card.Actor.gm') },
      content: `<div class="sr2e-roll"><h3>${tx('SR2E.Card.Actor.groupRollTn', { what: escText(what), tn })}</h3><table class="sr2e-group"><tr><th>${tx('SR2E.Card.Actor.who')}</th><th>${tx('SR2E.Card.Actor.dice2')}</th><th>${tx('SR2E.Card.Actor.tn2')}</th><th>${tx('SR2E.Card.Actor.successes3')}</th></tr>${rows.map((r) => `<tr><td>${escText(r.name)}${r.note ? ` <em>(${escText(r.note)})</em>` : ''}</td><td>${r.dice}</td><td>${r.tn}</td><td>${r.botch ? `<strong class="sr2e-botch">${tx('SR2E.Card.Actor.disaster2')}</strong>` : `<strong>${r.successes}</strong>`}</td></tr>`).join('')}</table></div>`,
      rolls,
      ...(opts.public ? {} : { whisper: gms }),
    });
    return rows.map((r) => ({ name: r.name, successes: r.successes, botch: r.botch }));
  }

  /**
   * GM (v0.41.0): damage several actors at once: each resists with Body against Power minus the
   * chosen armor (a card each), or takes it unresisted.
   */
  static async groupDamage(actors: any[], d: { power: number; level: DamageLevel; type: DamageType; armor: 'ballistic' | 'impact' | 'none'; mode: 'resist' | 'unresisted' }): Promise<number> {
    let n = 0;
    for (const a of actors.filter((x: any) => canWriteNow(x) && x.system?.attributes && x.type !== 'vehicle')) {
      if (d.mode === 'unresisted') {
        if (await a.applyUnresisted({ targetUuid: a.uuid, melee: false, damageType: d.type, power: d.power, level: d.level })) n++;
        continue;
      }
      const armor = d.armor === 'none' ? 0 : a.armorRating(d.armor);
      await a.resistDamage({ power: d.power, level: d.level, type: d.type, armor, ...(d.armor !== 'none' ? { armorKind: d.armor } : {}) });
      n++;
    }
    return n;
  }

  /**
   * GM (v0.51.0): the GM panel's calculator rolls a plain success test: dice vs TN with the listed
   * modifiers, on an ordinary test card (whispered to the GMs unless `public`). No actor.
   */
  static async gmRoll(o: { dice: number; targetNumber: number; modifiers?: TargetNumberModifier[]; label?: string; public?: boolean }): Promise<SuccessTestResult> {
    const rolls: any[] = [];
    const r = await successTest({ dice: Math.max(0, Math.min(60, Math.floor(Number(o.dice) || 0))), targetNumber: Math.floor(o.targetNumber), modifiers: o.modifiers ?? [], roll: foundryRoller(rolls) });
    const label = String(o.label || tx('SR2E.Card.Actor.gmRoll'));
    const html = describeResult(label, r);
    const gms = [...((game as any).users ?? [])].filter((u: any) => u.isGM).map((u: any) => u.id);
    await ChatMessage.create({
      speaker: { alias: tx('SR2E.Card.Actor.gm') },
      content: outcomeBanner({ kind: 'plain', botch: r.botch, successes: r.successes }, html) + html,
      rolls,
      flags: { [SYSTEM_ID]: { gmRoll: { dice: r.totalDice, targetNumber: r.targetNumber, successes: r.successes, botch: r.botch } } },
      ...(o.public ? {} : { whisper: gms }),
    });
    return r;
  }

  /**
   * GM (v0.51.0): heal several actors at once: take boxes off Physical, Stun or both (`boxes`
   * 'all' clears the track). One GM card lists what changed. Returns how many changed.
   */
  static async healSeveral(actors: any[], o: { track: 'physical' | 'stun' | 'both'; boxes: number | 'all' }): Promise<number> {
    const rows: string[] = [];
    for (const a of actors.filter((x: any) => canWriteNow(x) && x.system?.monitor)) {
      const upd: Record<string, number> = {};
      const parts: string[] = [];
      for (const track of (o.track === 'both' ? ['physical', 'stun'] : [o.track]) as Array<'physical' | 'stun'>) {
        const now = Number(a.system.monitor[track] ?? 0);
        const after = o.boxes === 'all' ? 0 : Math.max(0, now - Math.max(0, Math.floor(o.boxes)));
        if (after === now) continue;
        upd[`system.monitor.${track}`] = after;
        parts.push(`${track} ${now} → ${after}`);
      }
      if (!parts.length) continue;
      await a.update(upd);
      rows.push(`${escText(a.name)}: ${parts.join(', ')}`);
    }
    if (rows.length) {
      const gms = [...((game as any).users ?? [])].filter((u: any) => u.isGM).map((u: any) => u.id);
      await ChatMessage.create({ speaker: { alias: tx('SR2E.Card.Actor.gm') }, whisper: gms, content: `<p><strong>${tx('SR2E.Card.Actor.gmHealing')}</strong></p><ul>${rows.map((r) => `<li>${r}</li>`).join('')}</ul>` });
    }
    return rows.length;
  }

  /** GM: everyone picked on a multi-target card resists at once (no pool dice). Returns the indices rolled. */
  static async resistAll(damages: DamageState[], indices: number[]): Promise<number[]> {
    const done: number[] = [];
    for (const i of indices) {
      const d = damages[i];
      const t: any = d ? await fromUuid(d.targetUuid) : null;
      if (!canWriteNow(t)) continue;
      await t.resistFromState(d, 0);
      done.push(i);
    }
    return done;
  }

  /** GM: jam a weapon (after a disaster). */
  static async jamWeapon(actorUuid: string, weaponId: string): Promise<boolean> {
    const a: any = await fromUuid(actorUuid);
    const w: any = a ? [...a.items].find((i: any) => i.id === weaponId) : null;
    if (!w) return false;
    await w.update({ 'system.jammed': true });
    await ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor: a }), content: `<p><strong>${tx('SR2E.Card.Actor.sJams', { name: escText(a.name), name2: escText(w.name) })}</strong> ${tx('SR2E.Card.Actor.clearingItIsASimpleAction')}</p>` });
    return true;
  }

  /** Karma Pools refill for every character (the refresh setting, or the GM). */
  static async refreshAllKarma(reason: string): Promise<number> {
    const chars = allActors().filter((a: any) => a.type === 'character' && (a.system.karma?.poolSpent ?? 0) > 0);
    for (const a of chars) await a.refreshKarmaPool();
    if (chars.length) await ChatMessage.create({ speaker: { alias: tx('SR2E.Card.Actor.karma2') }, content: `<p>${tx('SR2E.Card.Actor.karmaPoolsRefreshed', { reason: escText(reason), chars: escText(chars.map((a: any) => a.name).join(', ')) })}</p>` });
    return chars.length;
  }

  /** Refresh the Karma Pool (GM decides when, e.g. each session or scene). */
  async refreshKarmaPool(): Promise<void> {
    await this.update({ 'system.karma.poolSpent': 0 });
  }

  /** The current combat phase (combat, round, pass, acting combatant), or null outside a started combat. */
  currentPhaseKey(): string | null {
    const c: any = game.combat;
    return combatPhaseKey({
      combatId: c?.id ?? null,
      started: Boolean(c?.started),
      round: c?.round,
      pass: c?.pass,
      combatantId: (this.actingNow() ? this.myCombatant()?.id : null) ?? c?.combatant?.id ?? null,
    });
  }

  /** Rounds this actor has already fired in the current combat phase (for recoil). */
  trackedRecoilRounds(): number {
    return trackedRounds(this.getFlag(SYSTEM_ID, 'recoil') as RecoilRecord | undefined, this.currentPhaseKey());
  }

  /** v0.79.0 (RULES.DOCS_V79.rangedRecoil): whether this phase's first shot was a single shot (undefined: not recorded). */
  trackedFirstShotSingle(): boolean | undefined {
    const f = this.getFlag(SYSTEM_ID, 'recoil') as (RecoilRecord & { firstSingle?: boolean }) | undefined;
    return f && trackedRounds(f, this.currentPhaseKey()) > 0 && typeof f.firstSingle === 'boolean' ? f.firstSingle : undefined;
  }

  /** The skill item a weapon uses, matched by name (case-insensitive), or undefined. */
  findSkill(name: string): any | undefined {
    const wanted = name.trim().toLowerCase();
    if (!wanted) return undefined;
    // v0.73.0 (O37): a skill saved under an old name ("Rotorcraft") still answers to the canonical one.
    const own = this.items.find((i: any) => i.type === 'skill' && i.name.trim().toLowerCase() === wanted)
      ?? this.items.find((i: any) => i.type === 'skill' && sameSkillName(i.name, name));
    // A slotted skillsoft stands in when it is better than the skill the character has (v0.29.0).
    const soft = this.softSkill(wanted);
    const base = soft && soft.system.rating > (own?.system?.rating ?? 0) ? soft : own;
    // v0.48.0: a possessed body thinks with the possessor's skills (even ones the body lacks).
    return this.possessedSkill(base, name);
  }

  /** A skill as a slotted skillsoft gives it (a stand-in skill item), or null. */
  softSkill(name: string): any | null {
    const wanted = String(name ?? '').trim().toLowerCase();
    const best = [...(this.sys.derived?.cyber?.softs ?? [])].filter((c: any) => String(c.skill).trim().toLowerCase() === wanted && c.effective > 0)
      .sort((a: any, b: any) => b.effective - a.effective)[0];
    if (!best) return null;
    const own: any = this.items.find((i: any) => i.type === 'skill' && i.name.trim().toLowerCase() === wanted);
    return { id: `soft-${best.gearId}`, name: own?.name ?? best.skill, type: 'skill', soft: true, chipName: best.name,
      system: { rating: best.effective, attribute: own?.system?.attribute ?? guessSkillAttribute(best.skill), specialization: '', specializationRating: 0 } };
  }

  /** Every skill a slotted skillsoft gives this character (for the sheet). */
  softSkills(): any[] {
    const names = [...new Set([...(this.sys.derived?.cyber?.softs ?? [])].filter((c: any) => c.effective > 0).map((c: any) => String(c.skill).trim().toLowerCase()))];
    return names.map((n) => this.softSkill(n)).filter(Boolean);
  }

  /** Cyberweapons installed (and not damaged), as weapons with ids `cyber-<item id>`. */
  cyberWeapons(): Array<{ id: string; name: string; system: any; limbId: string }> {
    const base = SR2Actor.unarmed().system;
    return [...this.items].filter((i: any) => i.type === 'cyberware' && i.system.kind === 'cyberweapon' && i.system.installed && !i.system.damaged).map((i: any) => {
      const w = i.system.weapon ?? {};
      return {
        id: `cyber-${i.id}`, name: i.name, limbId: i.system.housedIn ?? '',
        system: { ...base, name: i.name, skill: w.skill || 'Armed Combat', melee: true, strengthPower: w.strengthPower !== false, damagePower: w.damagePower ?? 0, damageLevel: w.damageLevel ?? 'M', damageType: w.damageType ?? 'physical', reach: w.reach ?? 0 },
      };
    });
  }

  /** A weapon by id: a weapon item, 'unarmed', or a cyberweapon ('cyber-<id>'). */
  weaponById(id: string | null | undefined): any | null {
    if (!id) return null;
    if (id === 'unarmed') return SR2Actor.unarmed();
    if (id.startsWith('cyber-')) return this.cyberWeapons().find((w) => w.id === id) ?? null;
    const it: any = [...this.items].find((i: any) => i.id === id);
    return it?.type === 'weapon' ? it : null;
  }

  // ---------------------------------------------------------------- Perception, social tests, grunts, morale (v0.32.0)

  /**
   * Opposed perception: this actor (Perception, else Intelligence) vs the target's Stealth; the target
   * (Stealth, else Quickness +4) vs this actor's Intelligence. More observer successes = noticed.
   */
  async perceive(targetUuid: string, opts: { modifiers?: TargetNumberModifier[]; whisper?: boolean; exclude?: string[]; excludeTheirs?: string[] } = {}): Promise<{ noticed: boolean; net: number } | null> {
    if (this.#exclusiveBlocks()) return null;
    // v0.81.1 (D1-4): an observer who can't perceive at all (unconscious, dying, held) doesn't roll.
    if (this.#cannotPerceive()) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.noPerceptionTest', { name: escText(this.name), cannotPerceive: escText(this.#cannotPerceive()) })); return null; }
    const target: any = await fromUuid(targetUuid);
    if (!target) return null;
    const p = RULES.PERCEPTION;
    const side = target.stealthSide?.() ?? { dice: 0, rating: 0, modifiers: [] };
    const stealthRating = side.rating;
    const myAttr = (this.sys.attributes?.[p.attribute]?.total as number | undefined) ?? 0;
    const tns = perceptionTargets({ stealthRating, observerAttribute: myAttr });
    const gms = [...((game as any).users ?? [])].filter((u: any) => u.isGM).map((u: any) => u.id);
    // v0.61.0: an invisibility spell on them is resisted first (once per spell).
    await this.seeThroughInvisibility(target);
    // v0.50.0: light, walls, smoke, weather, distance and their concealment, by this observer's eyes.
    const sight = this.perceptionAgainst(target);
    if (sight.blocked) {
      await ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor: this }), content: `<p><strong>${tx('SR2E.Card.Actor.canTNotice', { name: escText(this.name), targetName: escText(target.name) })}</strong> (${escText(sight.why)}).</p>`, ...(opts.whisper ? { whisper: gms, blind: true } : {}) });
      return { noticed: false, net: 0 };
    }
    const rolls: any[] = [];
    // Adept enhanced perception adds dice (v0.39.0); v0.71.0 (R2): through the shared skill path.
    const pd = this.perceptionDice();
    const mine = await successTest({ dice: pd.dice, targetNumber: tns.observerTn, modifiers: this.#testModifiers({ modifiers: [...(opts.modifiers ?? []), ...pd.modifiers, ...sight.modifiers], sightHandled: true, exclude: opts.exclude ?? [] }), roll: foundryRoller(rolls) });
    const theirs = await successTest({ dice: side.dice, targetNumber: tns.sneakerTn, modifiers: side.modifiers.filter((m: TargetNumberModifier) => !modIn(opts.excludeTheirs ?? [], m)), roll: foundryRoller(rolls) });
    // v0.80.0 (RULES.URR_V80.coreTies): opposedOutcome in the book.
    const o = urrCoreOpposed(mine.successes, theirs.successes);
    const noticed = o.winner === 'initiator';
    // v0.50.0: kept as a contest, so the GM can change a TN afterwards.
    const contest: Contest = { kind: 'perceive', id: SR2Actor.contestId(), actorName: this.name, targetName: target.name, sides: [
      { name: this.name, uuid: this.uuid as string, label: tx('SR2E.Card.Actor.looksForVsStealth', { name: this.name, targetName: target.name, label: pd.label, stealth: stealthRating || tx('SR2E.Card.Actor.none') }), result: mine },
      { name: target.name, uuid: target.uuid, label: stealthRating > 0 ? tx('SR2E.Card.Actor.stealthVsAttribute', { name: target.name, skill: p.stealthSkill, rating: stealthRating, suffix: side.suffix ?? '', attribute: cap(p.attribute), myAttr }) : tx('SR2E.Card.Actor.noStealthVsAttribute', { name: target.name, skill: p.stealthSkill, stealthAttribute: cap(p.stealthAttribute), attribute: cap(p.attribute), myAttr }), result: theirs },
    ] };
    await ChatMessage.create({
      speaker: ChatMessage.getSpeaker({ actor: this }), content: SR2Actor.contestContent(contest),
      rolls, ...(opts.whisper ? { whisper: gms, blind: true } : {}), flags: { [SYSTEM_ID]: { contest } },
    });
    return { noticed, net: o.winner === 'initiator' ? o.net : 0 };
  }

  /** v0.50.0: a contest's card body: both sides' rolls and the verdict (also after a GM changes a TN). */
  static contestContent(c: Contest, note = ''): string {
    return `${SR2Actor.#contestBody(c, note)}${SR2Actor.#contestKarmaHtml(c)}`;
  }

  /** v0.71.0 review (F1): why a street card's deal is closed ('' = still open): paid for, sold, or haggled over. */
  static dealDone(message: any): string {
    if (message?.getFlag?.(SYSTEM_ID, 'bought')) return tx('SR2E.Card.Actor.alreadyPaidFor');
    if (message?.getFlag?.(SYSTEM_ID, 'sold')) return tx('SR2E.Card.Actor.alreadySold');
    if (message?.getFlag?.(SYSTEM_ID, 'superseded')) return tx('SR2E.Card.Actor.alreadyHaggledOver');
    if (message?.getFlag?.(SYSTEM_ID, 'requested')) return tx('SR2E.Card.Shop.alreadyRequested');
    return '';
  }

  /** v0.71.0 (R1): a fresh id for a new contest's cards. */
  static contestId(): string {
    return (foundry as any).utils?.randomID?.() ?? `k${Date.now()}${Math.random().toString(36).slice(2, 8)}`;
  }

  static #contestBody(c: Contest, note = ''): string {
    const [first, ...rest] = c.sides;
    if (!first?.result) return '';
    const head = describeResult(`${first.label}${note}`, first.result);
    if (c.kind === 'sneak') {
      const rows: string[] = [];
      const seen: string[] = [];
      for (const w of rest) {
        if (!w.result) { rows.push(`<li>${tx('SR2E.Card.Actor.canTNotice2', { name: escText(w.name), why: escText(w.why ?? tx('SR2E.Card.Actor.unseen')) })}</li>`); continue; }
        const noticed = opposedOutcome(w.result.successes, first.result.successes).winner === 'initiator';
        if (noticed) seen.push(w.name);
        const why = escText(w.result.modifiers.map((m) => `${m.label} ${m.value >= 0 ? '+' : ''}${m.value}`).join(', '));
        rows.push(`<li>${escText(w.name)}: <span title="${tx('SR2E.Card.Actor.tnBase', { resultBaseTargetNumber: w.result.baseTargetNumber, part: why ? `; ${why}` : '' })}">${tx('SR2E.Card.Actor.tn3', { resultTargetNumber: w.result.targetNumber })}</span>, ${escText(plural(w.result.successes, 'success'))} — ${noticed ? `<strong>${tx('SR2E.Card.Actor.notices2')}</strong>` : tx('SR2E.Card.Actor.missesIt')}</li>`);
      }
      return `${head}<ul>${rows.join('')}</ul><p>${seen.length ? `<strong>${tx('SR2E.Card.Actor.seen')}</strong> ${tx('SR2E.Card.Actor.by', { seen: escText(seen.join(', ')) })}` : `<strong>${tx('SR2E.Card.Actor.slipsPastThemAll', { actorName: escText(c.actorName) })}</strong>`}</p>`;
    }
    const second = rest[0];
    const d: any = c.deal ?? {};
    // v0.71.0 (R1): the street contests, worded again from their results (a Karma re-roll or a GM TN change).
    if (c.kind === 'find') {
      const hours = SR2Actor.#findHours(c);
      // v0.91.5: what holding it risks (worked out again from the legality id, never from card text).
      const legalLine = SR2Actor.#legalLine(legalityId(d.legality), Boolean(d.permit), safeInt(d.rating, 0, 100, 0));
      // v0.91.6: a helping contact's own roll, a favour called in, and a fixer's cut (a fixer's card has no Haggle: they deal).
      const thr = SR2Actor.#findThrough(c);
      const theirs = thr.mode === 'help' && second?.result ? describeResult(second.label, second.result) : '';
      const fav = d.favNote ? `<p>${escText(String(d.favNote).replace(/<[^>]*>/g, ''))}</p>` : '';
      const feeLine = thr.mode === 'fixer' && thr.fee > 0 ? `<p class="hint">${tx('SR2E.Card.Through.feeIncluded', { contactName: escText(thr.name), fee: thr.fee.toLocaleString() })}</p>`
        // v0.92.0: the interpretations the find rests on (legality counted, a contact's help, a fixer).
        : '';
      // Review (N9): one line, with the retry rule on a card that found nothing.
      const interp = interpLine(interpsForFind({ legalityCounts: legalFindMods(d.legality).length > 0, through: thr.mode, retried: hours == null && RULES.SHOP_V91.retry === 'wait' }));
      return `${head}${theirs}${fav}${hours != null ? `<p>${tx('SR2E.Card.Actor.foundIn')} <strong>${escText(hoursLabel(hours))}</strong>.</p>${legalLine}${feeLine}${SR2Actor.#buyButtons(Number(d.price ?? 0), thr.mode !== 'fixer')}` : `<p><strong>${tx('SR2E.Card.Actor.notFound')}</strong> ${tx('SR2E.Card.Actor.thisTimeTryAgainAfter', { hoursLabel: escText(hoursLabel(Number(d.avHours ?? 0))) })}</p>`}${interp}`;
    }
    if (c.kind === 'legwork') {
      const total = contactDigSuccesses(first.result.successes, second?.result ? second.result.successes : null);
      const tier = legworkTier(total.successes);
      return `${head}${second?.result ? describeResult(second.label, second.result) : ''}${d.favNote ? `<p>${escText(String(d.favNote).replace(/<[^>]*>/g, ''))}</p>` : ''}<p><strong>${escText(tier)}.</strong>${total.note ? ` <span class="hint">(${total.note})</span>` : ''}</p>`;
    }
    // v0.79.0 (RULES.DOCS_V79.socialInfluence): a one-sided social test: one success passes, more do better.
    if (c.kind === 'social' && c.oneSided) return `${head}<p><strong>${escText(socialInfluenceLine(first.result.successes, c.targetName || 'The target'))}</strong></p>`;
    if (!second?.result) return head;
    if (c.kind === 'haggle') {
      const p = haggledPrice(Number(d.price ?? 0), first.result.successes - second.result.successes);
      return `${head}${describeResult(second.label, second.result)}
        <p>${tx('SR2E.Card.Actor.was', { part: p.percent > 0 ? `<strong>${tx('SR2E.Card.Actor.off2', { percent: p.percent })}</strong>` : p.percent < 0 ? `<strong>${tx('SR2E.Card.Actor.more', { value: -p.percent })}</strong>` : tx('SR2E.Card.Actor.noChange2'), price: p.price.toLocaleString(), price2: Number(d.price ?? 0).toLocaleString() })}</p>
        <p><button type="button" data-sr2e-action="buyItem">${tx('SR2E.Card.Actor.buyFor', { price: p.price.toLocaleString() })}</button></p>`;
    }
    if (c.kind === 'fence') {
      const p = hotFencePrice(Number(d.value ?? 0), first.result.successes - second.result.successes, Number(d.heat ?? 0));
      if (p.price <= 0) return `${head}${describeResult(second.label, second.result)}<p><strong>${tx('SR2E.Card.Actor.theFencePasses')}</strong>: ${d.heat ? tx('SR2E.Card.Actor.atHeatItIsnTWorth', { heat: escText(d.heat) }) : tx('SR2E.Card.Actor.nothingWorthPayingFor')}.</p>`;
      return `${head}${describeResult(second.label, second.result)}
        <p>${tx('SR2E.Card.Actor.theFenceOffers')} <strong>¥${p.price.toLocaleString()}</strong> (${p.percent}%${p.heatCut ? tx('SR2E.Card.Actor.lessForTheHeat', { heatCut: p.heatCut }) : ''}).</p><p><button type="button" data-sr2e-action="sellItem">${tx('SR2E.Card.Actor.sellFor', { price: p.price.toLocaleString() })}</button></p>`;
    }
    // v0.80.0 (RULES.URR_V80.coreTies): opposedOutcome in the book (an initiator's win there always has net > 0).
    const o = urrCoreOpposed(first.result.successes, second.result.successes);
    const verdict = c.kind === 'perceive'
      ? (o.winner === 'initiator' ? `<strong>${tx('SR2E.Card.Actor.notices', { actorName: escText(c.actorName), targetName: escText(c.targetName) })}</strong> ${tx('SR2E.Card.Actor.net', { net: o.net })}` : `<strong>${tx('SR2E.Card.Actor.goesUnnoticed', { targetName: escText(c.targetName) })}</strong>`)
      : (o.winner === 'initiator' ? `<strong>${tx('SR2E.Card.Actor.wins', { actorName: escText(c.actorName) })}</strong> ${o.net ? tx('SR2E.Card.Actor.by4', { net: o.net }) : tx('SR2E.Card.Actor.theTie')}.` : o.winner === 'defender' ? `<strong>${tx('SR2E.Card.Actor.holdsOut', { targetName: escText(c.targetName) })}</strong> ${tx('SR2E.Card.Actor.by2', { net: o.net })}` : `<strong>${tx('SR2E.Card.Actor.aStandOff')}</strong>`);
    // v0.58.0: a negotiated fee: each net success moves it (RULES.CHARACTERS_V58.negotiation).
    let payLine = '';
    if (c.pay !== undefined) {
      const net = o.winner === 'initiator' ? o.net : o.winner === 'defender' ? -o.net : 0;
      const np = negotiatedPay(c.pay, net);
      payLine = `<p>${tx('SR2E.Card.Actor.pay', { pay: c.pay.toLocaleString() })} <strong>¥${np.pay.toLocaleString()}</strong>${np.percent ? ` (${np.percent > 0 ? '+' : ''}${np.percent}%)` : ''}.</p>`;
    }
    // v0.89.5: the verdict line is marked for the look's contest box (applications/look.ts), not found by its words.
    return `${head}${describeResult(second.label, second.result)}<p${c.kind === 'perceive' ? '' : ' data-sr2e-contest-result="1"'}>${verdict}</p>${payLine}`;
  }

  /** v0.91.5: a find card's legality warning ('' when holding it risks nothing). */
  static #legalLine(legality: string, permit: boolean, rating: unknown = 0): string {
    const w = legalWarning({ legality, permit, rating });
    return w ? `<p class="sr2e-warn" data-sr2e-legal="${escHtml(legality)}">${escText(w)}</p>` : '';
  }

  /** The Buy and Haggle buttons under a find card (v0.91.6: no Haggle on a fixer's find). */
  static #buyButtons(price: number, haggle = true): string {
    const h = haggle ? ` <button type="button" data-sr2e-action="haggle" title="${tx('SR2E.Card.Actor.againstTheSellerPerNetSuccess', { haggleSkill: RULES.STREET.haggle.skill, hagglePercentPerNet: RULES.STREET.haggle.percentPerNet })}">${tx('SR2E.Card.Actor.haggle')}</button>` : '';
    return `<p><button type="button" data-sr2e-action="buyItem">${tx('SR2E.Card.Actor.buyFor', { price: price.toLocaleString() })}</button>${h}</p>`;
  }

  /** v0.91.6: how a find card's find was made (from its deal; anything odd counts as the character's own). */
  static #findThrough(c: Contest): { mode: ThroughMode; name: string; fee: number } {
    const t: any = (c.deal as any)?.through;
    const mode: ThroughMode = t?.mode === 'help' || t?.mode === 'fixer' ? t.mode : 'self';
    return { mode, name: String(t?.name ?? '').slice(0, 100), fee: mode === 'fixer' ? safeInt(t?.fee, 0, Number.MAX_SAFE_INTEGER, 0) : 0 };
  }

  /** v0.91.6: a find card's time (null = not found): a helping contact's own roll counts as in legwork. */
  static #findHours(c: Contest): number | null {
    const [first, second] = c.sides;
    if (!first?.result) return null;
    const mode = SR2Actor.#findThrough(c).mode;
    return findTime(Number((c.deal as any)?.avHours ?? 0), throughSuccesses(mode, first.result.successes, second?.result ? second.result.successes : null));
  }

  /** v0.71.0 (R1): the flags a street contest's buttons read (the price after haggling, the fence's offer, the time to find it). */
  static contestFlags(c: Contest): Record<string, unknown> {
    const d: any = c.deal ?? {};
    const [first, second] = c.sides;
    if (!first?.result) return {};
    if (c.kind === 'haggle' && second?.result) {
      const p = haggledPrice(Number(d.price ?? 0), first.result.successes - second.result.successes);
      return { buy: { ...(d.buy ?? {}), price: p.price }, haggled: true };
    }
    if (c.kind === 'fence' && second?.result) {
      const p = hotFencePrice(Number(d.value ?? 0), first.result.successes - second.result.successes, Number(d.heat ?? 0));
      return p.price > 0 ? { sell: { ...(d.sell ?? {}), price: p.price } } : {};
    }
    if (c.kind === 'find') {
      const hours = SR2Actor.#findHours(c);
      return hours != null ? { buy: { ...(d.buy ?? {}), hours } } : {};
    }
    return {};
  }

  /**
   * v0.71.0 (R1): Karma Pool buttons for each side of a contest whose actor has a Karma Pool (re-roll the
   * failures, avoid a disaster, buy a success). Only that actor's owner (or the GM) can use them.
   */
  static #contestKarmaHtml(c: Contest): string {
    if (!RULES.FIXES_V71.contestKarma) return '';
    const several = c.sides.filter((x) => x.uuid && x.result).length > 1;
    const rows: string[] = [];
    c.sides.forEach((side, i) => {
      if (!side.uuid || !side.result) return;
      const a: any = fromUuidSync(side.uuid);
      const k = a?.system?.karma;
      if (!a || !((Number(k?.pool) || 0) > 0)) return;
      const who = several ? `${side.name}: ` : '';
      const parts: string[] = [];
      const r = side.result;
      if (r.botch) parts.push(`<button type="button" data-sr2e-action="contestKarma" data-side="${i}" data-op="avoid">${tx('SR2E.Card.Actor.avoidDisasterKarma2', { who: escText(who), avoidDisasterCost: avoidDisasterCost() })}</button>`);
      const failures = r.dice.filter((x) => !x.success).length;
      if (failures > 0) parts.push(`<button type="button" data-sr2e-action="contestKarma" data-side="${i}" data-op="reroll">${tCount(failures, 'SR2E.Card.Actor.reRollFailuresKarma2', { who: escText(who), karmaRerollCost: karmaRerollCost(side.rerolls ?? 0) })}</button>`);
      const left = Math.max(0, (Number(k.pool) || 0) - (Number(k.poolSpent) || 0));
      const buy = canBuySuccess({ successes: r.successes, poolLeft: left, botch: r.botch });
      if (buy.ok) parts.push(`<button type="button" data-sr2e-action="contestKarma" data-side="${i}" data-op="buy" title="${RULES.KARMA.buyPermanent ? tx('SR2E.Card.Actor.theKarmaPoolPointIsGone') : tx('SR2E.Card.Actor.spentUntilTheKarmaPoolRefreshes')}">${tx('SR2E.Card.Actor.buyASuccessKarma2', { who: escText(who), buyCost: buy.cost, part: RULES.KARMA.buyPermanent ? tx('SR2E.Card.Actor.permanent') : '' })}</button>`);
      if (parts.length) rows.push(parts.join(' '));
    });
    return rows.length ? `<p class="sr2e-karma">${rows.join('<br>')}</p>` : '';
  }

  /**
   * v0.71.0 (R1): spend Karma Pool on one side of a contest card: `reroll` its failures, `avoid` a disaster or
   * `buy` a success. A newer card of the same contest replaces this one (its buttons go dead); the outcome,
   * prices and times are worked out again from the new result.
   */
  static async contestKarma(message: any, sideIndex: number, op: 'reroll' | 'avoid' | 'buy'): Promise<any> {
    if (!RULES.FIXES_V71.contestKarma) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.karmaPoolOnContestCardsIs')); return null; }
    if (SR2Actor.isReplaced(message)) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.thatCardHasBeenReplacedBy2')); return null; }
    const c = message?.getFlag?.(SYSTEM_ID, 'contest') as Contest | undefined;
    // v0.71.0 review (F1): a deal already struck (bought, sold, haggled) can't be re-rolled into a second one.
    const done = SR2Actor.dealDone(message);
    if (done) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.karmaCanTChangeThisCard', { done })); return null; }
    const i = Math.floor(Number(sideIndex) || 0);
    const side = c?.sides?.[i];
    if (!c || !side?.result || !side.uuid) return null;
    const actor: any = await fromUuid(side.uuid);
    if (!(actor instanceof SR2Actor)) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.noLongerExists', { sideName: escHtml(side.name) })); return null; }
    if (!canWriteNow(actor)) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.onlySOwnerOrTheGm', { actorName: escHtml(actor.name) })); return null; }
    const r = side.result;
    const rolls: any[] = [];
    let result: SuccessTestResult = r;
    let next = { ...side };
    let note = '';
    if (op === 'reroll') {
      if (!r.dice.some((x) => !x.success)) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.everyDieAlreadySucceededThereIs')); return null; }
      const cost = karmaRerollCost(side.rerolls ?? 0);
      if (!(await actor.#spendKarma(cost))) return null;
      // v0.71.0 review (F7): successes bought earlier stay bought.
      const rr = await rerollFailures(r, foundryRoller(rolls));
      result = { ...rr, successes: rr.successes + Math.max(0, side.bought ?? 0) };
      next.rerolls = (side.rerolls ?? 0) + 1;
      note = tx('SR2E.Card.Actor.karmaReRollCost2', { sideName: side.name, nextRerolls: next.rerolls, cost });
    } else if (op === 'avoid') {
      if (!r.botch) return null;
      if (!(await actor.#spendKarma(avoidDisasterCost()))) return null;
      result = { ...r, botch: false };
      next.avoided = true;
      note = tx('SR2E.Card.Actor.disasterAvoidedKarma2', { sideName: side.name });
    } else {
      const k = actor.sys.karma ?? {};
      const left = Math.max(0, (k.pool ?? 0) - (k.poolSpent ?? 0));
      const b = canBuySuccess({ successes: r.successes, poolLeft: left, botch: r.botch });
      if (!b.ok) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.canTBuyASuccess', { reason: escHtml(b.reason) })); return null; }
      await actor.update(RULES.KARMA.buyPermanent ? { 'system.karma.pool': (k.pool ?? 0) - b.cost } : { 'system.karma.poolSpent': (k.poolSpent ?? 0) + b.cost });
      result = { ...r, successes: r.successes + 1 };
      next.bought = (side.bought ?? 0) + 1;
      note = tx('SR2E.Card.Actor.boughtSuccessKarma2', { sideName: side.name, nextBought: next.bought, cost: b.cost, part: RULES.KARMA.buyPermanent ? tx('SR2E.Card.Actor.permanent') : '' });
    }
    next = { ...next, result };
    const nc: Contest = { ...c, id: c.id ?? message.id ?? SR2Actor.contestId(), sides: c.sides.map((x, k) => (k === i ? next : x)) };
    // Round 2 (V-SEC 7, FIX2-BRIEF G): a GM spending Karma on a player's contest card keeps the player as the new
    // card's author (as retarget's contest branch does), so the player's data is never vouched for by the GM.
    const keepAuthor = (game as any).user?.isGM && !realGm(SR2Actor.#cardAuthorOf(message)) ? SR2Actor.#sameAuthor(message) : {};
    return ChatMessage.create({
      speaker: message.speaker, content: `${SR2Actor.contestContent(nc)}<p class="hint">${escText(note)}</p>`, rolls, ...keepAuthor,
      ...(message.whisper?.length ? { whisper: [...message.whisper], blind: Boolean(message.blind) } : {}),
      flags: { [SYSTEM_ID]: { contest: nc, ...SR2Actor.contestFlags(nc) } },
    }).then(async (m: any) => { await SR2Actor.#findRescored(nc); return m; });
  }

  /** v0.91.0 review (B4): a find card re-scored as found (Karma Pool, the GM's TN change) drops the retry wait. */
  static async #findRescored(c: Contest): Promise<void> {
    if (c?.kind !== 'find') return;
    const d: any = c.deal ?? {};
    if (SR2Actor.#findHours(c) == null) return;
    // v0.91.6: a fixer's card is the fixer's roll: whose wait it is comes from the card's buyer.
    const owner = c.sides?.[0]?.uuid ?? (typeof d.buy?.actorUuid === 'string' ? d.buy.actorUuid : '');
    const a: any = owner ? await fromUuid(owner) : null;
    if (!(a instanceof SR2Actor) || !a.isOwner) return;
    const key = typeof d.buy?.shop === 'string' ? d.buy.shop : d.buy?.itemId ? `item:${d.buy.itemId}` : '';
    if (key) { try { await a.#clearFindRetry(key); } catch (err) { console.warn('sr2e | find retry', err); } }
  }

  /** v0.50.0: what a perception test against someone would add by itself (the dialog preview). */
  perceptionPreview(target: any): { observer: TargetNumberModifier[]; sneaker: TargetNumberModifier[]; blocked: boolean; why: string } {
    if (!target) return { observer: this.#testModifiers({ sightHandled: true }), sneaker: [], blocked: false, why: '' };
    const sight = this.perceptionAgainst(target);
    return { observer: this.#testModifiers({ modifiers: sight.modifiers, sightHandled: true }), sneaker: target.stealthSide?.().modifiers ?? [], blocked: sight.blocked, why: sight.why };
  }

  /**
   * An opposed social test: this actor's skill vs TN = the target's opposing attribute; the target's
   * same skill (or the attribute at +4) vs TN = this actor's. Reports the margin.
   */
  async socialTest(skillName: string, targetUuid: string, opts: { modifiers?: TargetNumberModifier[]; exclude?: string[]; excludeTheirs?: string[]; pay?: number; attribute?: 'charisma' | 'willpower' | 'intelligence' } = {}): Promise<{ winner: string; net: number } | null> {
    if (this.#exclusiveBlocks()) return null;
    const target: any = await fromUuid(targetUuid);
    // v0.73.0 (O30): a caller may name the opposed attribute (negotiating pay: RULES.CHARACTERS_V73.negotiation).
    const attr = opts.attribute ?? socialAttribute(skillName) ?? 'charisma';
    if (!target) return null;
    const mine = this.#skillDice(this.findSkill(skillName), false, null, 'charisma');
    const theirs = target.#skillDice(target.findSkill(skillName), false, null, attr === 'charisma' ? 'charisma' : attr);
    const rolls: any[] = [];
    const tnMine = Math.max(RULES.MIN_TARGET_NUMBER, (target.system.attributes?.[attr]?.total as number | undefined) ?? 4);
    const tnTheirs = Math.max(RULES.MIN_TARGET_NUMBER, (this.sys.attributes?.[attr]?.total as number | undefined) ?? 4);
    const sides0 = this.#socialSides(target, mine.modifiers, theirs.modifiers, opts.modifiers ?? []);
    const offMine = new Set(opts.exclude ?? []), offTheirs = new Set(opts.excludeTheirs ?? []);
    const sides = { mine: sides0.mine.filter((m) => !modIn(offMine, m)), theirs: sides0.theirs.filter((m) => !modIn(offTheirs, m)) };
    const a = await successTest({ dice: mine.dice, targetNumber: tnMine, modifiers: sides.mine, roll: foundryRoller(rolls) });
    // v0.79.0 (RULES.DOCS_V79.socialInfluence 'oneSided'; SRII p180-182): Etiquette, Leadership and Negotiation (not
    // negotiating pay) are the speaker's skill vs TN = the target's attribute + modifiers; the target doesn't roll.
    if (socialOneSided(skillName, { pay: opts.pay !== undefined })) {
      const one: Contest = { kind: 'social', id: SR2Actor.contestId(), actorName: this.name, targetName: target.name, oneSided: true, sides: [
        { name: this.name, uuid: this.uuid as string, label: `${this.name}: ${skillName}${mine.suffix} vs ${target.name}'s ${cap(attr)} ${tnMine}`, result: a },
      ] };
      await ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor: this }), content: SR2Actor.contestContent(one), rolls, flags: { [SYSTEM_ID]: { contest: one } } });
      const out = socialInfluenceOutcome(a.successes);
      return { winner: out.winner, net: out.net };
    }
    const b = await successTest({ dice: theirs.dice, targetNumber: tnTheirs, modifiers: sides.theirs, roll: foundryRoller(rolls) });
    // v0.80.0 (RULES.URR_V80.coreTies): opposedOutcome in the book.
    const o = urrCoreOpposed(a.successes, b.successes);
    const contest: Contest = { kind: 'social', id: SR2Actor.contestId(), actorName: this.name, targetName: target.name, sides: [
      { name: this.name, uuid: this.uuid as string, label: `${this.name}: ${skillName}${mine.suffix} vs ${target.name}'s ${cap(attr)} ${tnMine}`, result: a },
      { name: target.name, uuid: target.uuid, label: `${target.name}: ${skillName}${theirs.suffix} vs ${this.name}'s ${cap(attr)} ${tnTheirs}`, result: b },
    ], ...(opts.pay !== undefined ? { pay: Math.max(0, Math.floor(opts.pay)) } : {}) };
    await ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor: this }), content: SR2Actor.contestContent(contest), rolls, flags: { [SYSTEM_ID]: { contest } } });
    return { winner: o.winner, net: o.net };
  }

  /**
   * Both sides' modifiers in an opposed social test (v0.50.0): the speaker's own (with Street Cred and
   * metatype prejudice found by itself) and the listener's own (full penalties, RULES.TN_AUTO.social).
   */
  #socialSides(target: any, mineSkill: TargetNumberModifier[], theirSkill: TargetNumberModifier[], given: TargetNumberModifier[]): { mine: TargetNumberModifier[]; theirs: TargetNumberModifier[] } {
    const picked = given.some((m) => modifierIs(m, 'attitude:prejudiced', /^Attitude: Prejudiced/i));
    const prej = picked ? null : metatypePrejudice(this.sys.metatype, target?.system?.metatype);
    const mine = this.#testModifiers({ modifiers: [...given, ...mineSkill, ...reputationModifiers(this.sys.derived?.streetCred ?? 0), ...(prej ? [prej] : [])] });
    const theirs = RULES.TN_AUTO.social.defenderFullPenalties && target instanceof SR2Actor
      ? target.#testModifiers({ modifiers: theirSkill })
      : [...theirSkill, ...(target?.woundModifiers?.() ?? [])];
    return { mine, theirs };
  }

  /** v0.50.0: what a social test against someone adds by itself on each side (the dialog preview). */
  socialPreview(target: any, skillName: string, given: TargetNumberModifier[] = [], attribute?: 'charisma' | 'willpower' | 'intelligence'): { mine: TargetNumberModifier[]; theirs: TargetNumberModifier[]; tnMine: number | null; tnTheirs: number | null } {
    const attr = attribute ?? socialAttribute(skillName) ?? 'charisma';
    const mine = this.#skillDice(this.findSkill(skillName), false, null, 'charisma');
    if (!target) return { mine: this.#testModifiers({ modifiers: [...mine.modifiers, ...reputationModifiers(this.sys.derived?.streetCred ?? 0)] }), theirs: [], tnMine: null, tnTheirs: null };
    const theirs = target instanceof SR2Actor ? target.#skillDice(target.findSkill(skillName), false, null, attr === 'charisma' ? 'charisma' : attr) : { modifiers: [] as TargetNumberModifier[] };
    const sides = this.#socialSides(target, mine.modifiers, theirs.modifiers, given);
    return {
      mine: sides.mine.filter((m) => !given.includes(m)), theirs: sides.theirs,
      tnMine: Math.max(RULES.MIN_TARGET_NUMBER, (target.system?.attributes?.[attr]?.total as number | undefined) ?? 4),
      tnTheirs: Math.max(RULES.MIN_TARGET_NUMBER, (this.sys.attributes?.[attr]?.total as number | undefined) ?? 4),
    };
  }

  // ---------------------------------------------------------------- Characters, gear and integration (v0.58.0)

  /**
   * v0.58.0: what a plain Perception test gets by itself: by sight, the light, smoke and weather where the
   * observer stands (or at a targeted token, with walls and distance); by ear, none of those.
   */
  noticeModifiers(o: { sense?: 'sight' | 'hearing'; targetUuid?: string | null } = {}): TargetNumberModifier[] {
    const mods: TargetNumberModifier[] = [];
    const pe = Number(this.sys.derived?.bio?.perceptionTn ?? 0);
    if (pe) mods.push({ id: 'painEditor', label: tx('SR2E.Card.Mod.painEditor'), value: pe });
    mods.push(...qualityModifiers(this.sys.qualities ?? [], { skill: RULES.PERCEPTION.skill }));
    // v0.59.0: deafened (RULES.STATUSES.deaf); v0.61.0: cyberears and improved hearing.
    if (o.sense === 'hearing') return [...mods, ...hearingModifiers({ ears: this.hearingNow(), deaf: this.hasStatus('deaf') })];
    const target: any = o.targetUuid ? fromUuidSync(o.targetUuid) : null;
    try {
      const sg = this.sightTo(target ?? this, {});
      const r = perceptionSightModifiers({ light: sg.light, vision: sg.vision, los: target ? sg.los : true, smoke: target ? sg.smoke : { kind: 'none', source: '', flames: false }, metres: target ? sg.metres : null, weather: sg.weather, blind: this.hasStatus('blind') && !this.flashTnNow(), concealment: [] });
      mods.push(...r.modifiers);
      // v0.78.0: dazzled by a flash: its TN, not full blindness.
      if (this.flashTnNow()) mods.push(...this.blindMods('other'));
    } catch { /* no scene */ }
    return mods;
  }

  /**
   * v0.58.0: a plain Perception test (no one sneaking): Intelligence (+ enhanced perception) vs TN 4 with
   * the obviousness table; the card says what the successes reveal.
   */
  async notice(o: { obviousness?: string | string[]; sense?: 'sight' | 'hearing'; what?: string; targetUuid?: string | null; modifiers?: TargetNumberModifier[]; exclude?: string[]; whisper?: boolean; baseTime?: { value: number; unit: string } | null } = {}): Promise<SuccessTestResult | null> {
    if (this.#exclusiveBlocks()) return null;
    // v0.81.1 (D1-4): as perceive.
    if (this.#cannotPerceive()) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.noPerceptionTest', { name: escText(this.name), cannotPerceive: escText(this.#cannotPerceive()) })); return null; }
    const p = RULES.PERCEPTION;
    const int = Number(this.sys.attributes?.[p.attribute]?.total ?? 0);
    const enh = this.adeptSpecial('enhancedPerception') * RULES.ADEPT.enhancedPerception.dicePerLevel;
    const n = noticeTest({ intelligence: int, obviousness: o.obviousness ?? 'normal', extra: enh });
    const sense = o.sense === 'hearing' ? 'hearing' : 'sight';
    // v0.71.0 (R12): looking at someone under an invisibility spell: resisted first.
    if (sense === 'sight' && o.targetUuid) { const tt: any = fromUuidSync(o.targetUuid); if (tt) await this.spotInvisible([tt]); }
    const label = tx('SR2E.Card.Actor.perception', { part: sense === 'hearing' ? tx('SR2E.Card.Actor.listening') : tx('SR2E.Card.Actor.looking'), part2: o.what ? `: ${o.what}` : '', attribute: cap(p.attribute), int, part3: enh ? tx('SR2E.Card.Actor.enhancedPerception', { enh }) : '' });
    return this.#runTest(label, n.dice, {
      targetNumber: n.tn, sightHandled: true, exclude: o.exclude ?? [],
      modifiers: [...n.modifiers, ...this.noticeModifiers({ sense, targetUuid: o.targetUuid ?? null }), ...(o.modifiers ?? [])],
    }, { kind: 'plain', reveal: { kind: 'notice', ...(o.what ? { what: o.what } : {}) },
      ...(o.whisper ? { privateTo: [...new Set([...[...((game as any).users ?? [])].filter((u: any) => u.isGM).map((u: any) => u.id as string), String((game as any).user?.id ?? '')])].filter(Boolean) } : {}), ...(o.baseTime && o.baseTime.value > 0 ? { timed: { base: o.baseTime.value, unit: o.baseTime.unit } } : {}) });
  }

  /** v0.58.0: the Build/Repair tools this actor owns (gear with a tool level), best first. */
  toolsOwned(): Array<{ level: string; skill: string; name: string }> {
    const order = RULES.CHARACTERS_V58.tools.levels.map((l) => l.id);
    // v0.61.0: a safehouse workshop (paid up) is a shop for any Build/Repair skill (STREET_V61.workshop).
    // Not in the middle of a fight (the work is done at home; the dialogs show it as "… workshop (at home)").
    const atHome = !Boolean((game as any).combat?.started && [...((game as any).combat?.combatants ?? [])].some((c: any) => c.actor?.uuid === this.uuid));
    const shops = atHome && (this.type === 'character' || this.type === 'npc') ? this.homeSafehouses().map((h) => ({ level: workshopToolsLevel(h.workshop), skill: '', name: tx('SR2E.Text.Actor.workshopAtHome', { name: h.name }) })).filter((t) => t.level && t.level !== 'none') : [];
    return [...[...(this.items ?? [])].filter((i: any) => i.type === 'gear' && i.system?.tools?.level && i.system.tools.level !== 'none' && !i.system.damaged && (i.system.tools.level !== 'kit' || isCarried(i)))
      .map((i: any) => ({ level: String(i.system.tools.level), skill: String(i.system.tools.skill ?? ''), name: String(i.name) })), ...shops]
      .sort((a, b) => order.indexOf(b.level) - order.indexOf(a.level));
  }

  /** v0.58.0: the best tools at hand for a skill ('none' without). */
  toolsFor(skillName: string): string {
    return bestTools(this.toolsOwned(), skillName);
  }

  /**
   * v0.58.0: repair a broken weapon or piece of gear: its Build/Repair skill (the weapon's skill + " B/R",
   * or Electronics B/R) vs TN 4, tools as needed, base time ÷ successes. A success marks it working again.
   */
  async repairGear(itemId: string, o: { have?: string; modifiers?: TargetNumberModifier[]; exclude?: string[]; baseHours?: number } = {}): Promise<SuccessTestResult | null> {
    if (this.#exclusiveBlocks()) return null;
    const item: any = this.items.get(itemId);
    if (!item || !['weapon', 'gear'].includes(item.type)) return null;
    if (!item.system?.damaged) { ui.notifications?.info?.(tx('SR2E.Notify.Actor.isnTBroken', { itemName: escHtml(item.name) })); return null; }
    const plan = gearRepairPlan({ kind: item.type === 'weapon' ? 'weapon' : 'gear', weaponSkill: item.type === 'weapon' ? String(item.system.skill ?? '') : '' });
    const have = o.have ?? this.toolsFor(plan.skill);
    const t = toolsModifier(plan.needs, have);
    if (t.blocked) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.needsToolsToRepair', { name: escHtml(this.name), itemName: escHtml(item.name), tNote: escHtml(t.note) })); return null; }
    const sd = this.#skillDice(this.findSkill(plan.skill), false, null, plan.fallbackAttribute as AttributeKey, { skillName: plan.skill });
    const hours = o.baseHours ?? plan.baseHours;
    return this.#runTest(tx('SR2E.Card.Actor.repair', { itemName: item.name, planSkill: plan.skill, sdSuffix: sd.suffix }), sd.dice, {
      targetNumber: plan.tn, exclude: o.exclude ?? [], modifiers: [...(o.modifiers ?? []), ...sd.modifiers, ...(t.modifier ? [t.modifier] : [])],
    }, { kind: 'plain', gearRepair: { itemUuid: item.uuid, name: item.name }, timed: { base: hours, unit: 'hours' } });
  }

  // ---- Training (house rule trainingTime 'timed')

  /** v0.58.0: training under way, soonest first. */
  trainingList(): Array<{ id: string; label: string; readyAt: number; days: number; to: number; daysLeft: number }> {
    const now = sysNow();
    return [...((this.sys.training as any[] | undefined) ?? [])].map((t: any) => ({ id: t.id, label: t.label, readyAt: t.readyAt, days: t.days, to: t.to, daysLeft: Math.max(0, Math.ceil((t.readyAt - now) / 86400)) }))
      .sort((a, b) => a.readyAt - b.readyAt);
  }

  /** v0.58.0: start training: the Karma is spent now, the rating rises when the time has passed. */
  async #startTraining(target: { attribute?: string; skillId?: string; specialization?: boolean; concentration?: boolean }, c: { cost: number; from: number; to: number; label: string }): Promise<boolean> {
    const list: any[] = [...((this.sys.training as any[] | undefined) ?? [])];
    const part = target.attribute ? '' : target.specialization ? 'specialization' : target.concentration ? 'concentration' : 'rating';
    if (list.some((t: any) => (target.attribute ? t.attribute === target.attribute : t.skillId === target.skillId && t.part === part))) {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.isAlreadyTraining', { name: escHtml(this.name), label: escHtml(c.label) }));
      return false;
    }
    const skill: any = target.skillId ? this.items.get(target.skillId) : null;
    const kind = target.attribute ? 'attribute' : target.specialization ? 'specialization' : target.concentration ? 'concentration' : String(skill?.system?.kind ?? 'active');
    // v0.80.0 (RULES.URR_V80.coreTraining 'urr'): Karma × 8 hours at 4 (or Willpower) hours a day; null in the book.
    const days = urrCoreTrainingDays({ cost: c.cost, willpower: Number(this.sys.attributes?.willpower?.total ?? 0) }) ?? trainingDays({ kind, newRating: c.to });
    const now = sysNow();
    const entry = { id: SR2Actor.#newId(), label: `${c.label} ${c.from} → ${c.to}`, attribute: target.attribute ?? '', skillId: target.skillId ?? '', part, to: c.to, cost: c.cost, startedAt: now, readyAt: trainingReadyAt(now, days), days, baseDays: days,
      // v0.73.0 (O42): who started it (the Done line).
      ...(({ by, approvedBy }) => ({ by, approvedBy }))(projectCredit({ user: String((game as any).user?.name ?? ''), requester: approvalContext(String(this.uuid))?.requester, gm: approvalContext(String(this.uuid))?.gm })) };
    const good = this.sys.karma?.good ?? 0;
    await this.update({ 'system.training': [...list, entry], 'system.karma.good': good - c.cost, 'system.ledger': this.#ledgerWith({ kind: 'karma', amount: -c.cost, reason: tx('SR2E.Text.Actor.training', { label: entry.label }) }) });
    await ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor: this }), content: `<p><strong>${escText(this.name)}</strong> ${tx('SR2E.Card.Actor.startsTrainingForKarma', { entryLabel: escText(entry.label), cost: c.cost })} <strong>${escText(plural(days, 'day'))}</strong> ${tx('SR2E.Card.Actor.anInstructorCanShortenIt')}</p>` });
    return true;
  }

  // ---------------------------------------------------------------- v0.65.0: projects (things that take time)

  /** Does this actor wait for things in this area (player characters out of creation, the area on)? */
  waitsFor(area: WaitArea): boolean {
    return waits({ area, actorType: String(this.type), inCreation: inCreation(this) });
  }

  /** Projects under way, soonest first. */
  projects(): Project[] {
    try { return projectList((this as any).flags?.[SYSTEM_ID]?.projects); } catch { return []; }
  }

  /**
   * Start a project: what was paid is held (the caller has paid it), the effect applies when the time has
   * passed. A project from the same chat card and kind (a Karma re-roll) only gets its new time.
   */
  async startProject(o: { kind: string; area: WaitArea; label: string; subject?: string; hours: number; paid?: { karma?: number; nuyen?: number }; source?: string; effect: ProjectEffect; onCancel?: ProjectEffect; done?: string }): Promise<Project> {
    const same = o.source ? this.projects().find((p) => p.source === o.source && p.kind === o.kind) : null;
    if (same) {
      const p = retimed(same, o.hours);
      await this.update({ [`flags.${SYSTEM_ID}.projects.${p.id}`]: p });
      return p;
    }
    const now = sysNow();
    // v0.73.0 (O42): an approved request is the player's, approved by the GM (RULES.CROSSCUT_V73.advancement.creditRequester).
    const credit = projectCredit({ user: String((game as any).user?.name ?? ''), requester: approvalContext(String(this.uuid))?.requester, gm: approvalContext(String(this.uuid))?.gm });
    const p = makeProject({ ...o, id: SR2Actor.#newId(), startedAt: now, by: credit.by, ...(credit.approvedBy ? { approvedBy: credit.approvedBy } : {}) } as any);
    await this.update({ [`flags.${SYSTEM_ID}.projects.${p.id}`]: p });
    const paid = [p.paid.karma ? tx('SR2E.Card.Actor.karma3', { paidKarma: p.paid.karma }) : '', p.paid.nuyen ? `¥${p.paid.nuyen.toLocaleString()}` : ''].filter(Boolean);
    const paidText = tList(paid);
    await ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor: this }), content: `<p><strong>${escText(this.name)}</strong> ${tx('SR2E.Card.Actor.startsReadyIn', { label: escText(p.label) })} <strong>${escText(timeLabel(p.hours))}</strong> ${tx('SR2E.Card.Actor.ofGameTime', { part: paidText ? tx('SR2E.Card.Actor.paidNowGivenBackIfIt2', { paid: escText(paidText) }) : '' })}</p>` });
    return p;
  }

  /** A Karma re-roll changed the successes of the test that started a project: its new time (null when it's gone). */
  async retimeProject(id: string | undefined, hours: number): Promise<Project | null> {
    const p = id ? this.projects().find((x) => x.id === id) : null;
    if (!p) return null;
    const next = retimed(p, hours);
    await this.update({ [`flags.${SYSTEM_ID}.projects.${p.id}`]: next });
    return next;
  }

  /**
   * v0.65.0: a re-roll or a GM's TN change left a test with no successes: the project it started is given up
   * (what was paid comes back). Returns a note for the card ('' when there was none).
   */
  async dropProjectOnFailure(id: string | undefined): Promise<string> {
    if (!id || !this.projects().some((p) => p.id === id)) return '';
    await this.cancelProject(id);
    return ` <em>${tx('SR2E.Card.Actor.theWorkUnderWayIsGiven')}</em>`;
  }

  /** Give a project up: what was paid comes back. */
  async cancelProject(id: string): Promise<boolean> {
    const p = this.projects().find((x) => x.id === id);
    if (!p || SR2Actor.#projectBusy.has(id)) return false;
    // v0.91.4 review (B1): a vehicle order is the GM's record (a world setting): only the GM cancels it, and the refund is
    // what the record says was paid (not the project's flag, which the player can write).
    const vehicleOrder = (p as any).effect?.call?.method === 'deliverVehicle';
    if (vehicleOrder && !(game as any).user?.isGM) { ui.notifications?.warn?.(tx('SR2E.Notify.VehicleShop.gmCancels')); return false; }
    SR2Actor.#projectBusy.add(id);
    try { await dropFlagKeys(this, 'projects', [id]); } finally { setTimeout(() => SR2Actor.#projectBusy.delete(id), 2000); }
    if (vehicleOrder) {
      const order = await takeVehicleOrder(String((p as any).effect?.call?.args?.[0] ?? ''), String(this.uuid));
      if (order && order.paid > 0) await this.adjustNuyen(order.paid, `Given up (refund): ${p.label}`);
      await ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor: this }), content: `<p><strong>${escText(this.name)}</strong> ${tx('SR2E.Card.Actor.givesUp', { label: escText(p.label), part: order?.paid ? tx('SR2E.Card.Actor.whatWasPaidComesBack') : '' })}</p>` });
      return true;
    }
    if (p.paid.karma > 0) await this.update({ 'system.karma.good': Number(this.sys.karma?.good ?? 0) + p.paid.karma, 'system.ledger': this.#ledgerWith({ kind: 'karma', amount: p.paid.karma, reason: `Given up (refund): ${p.label}` }) });
    if (p.paid.nuyen > 0) await this.adjustNuyen(p.paid.nuyen, `Given up (refund): ${p.label}`);
    if (p.onCancel) await this.#applyEffect(p.onCancel);
    await ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor: this }), content: `<p><strong>${escText(this.name)}</strong> ${tx('SR2E.Card.Actor.givesUp', { label: escText(p.label), part: p.paid.karma || p.paid.nuyen ? tx('SR2E.Card.Actor.whatWasPaidComesBack') : '' })}</p>` });
    return true;
  }

  /** GM: finish a project now (or a training entry, by its id). */
  async finishProject(id: string): Promise<boolean> {
    if (!(game as any).user?.isGM) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.onlyTheGmCanFinishIt')); return false; }
    const p = this.projects().find((x) => x.id === id);
    if (p) {
      if (SR2Actor.#projectBusy.has(id)) return false;
      SR2Actor.#projectBusy.add(id);
      try { await dropFlagKeys(this, 'projects', [id]); } finally { setTimeout(() => SR2Actor.#projectBusy.delete(id), 2000); }
      await this.#completeProject(p, true);
      return true;
    }
    const t = [...((this.sys.training as any[] | undefined) ?? [])].find((x: any) => x.id === id);
    if (!t) return false;
    await this.update({ 'system.training': [...(this.sys.training as any[])].map((x: any) => (x.id === id ? { ...x, readyAt: sysNow() } : x)) });
    await SR2Actor.#trainingTick(this, sysNow());
    return true;
  }

  /** GM: set how much time is left on a project or a training entry (hours from now; 0 = done at the next time step). */
  async setProjectTimeLeft(id: string, hoursLeft: number): Promise<boolean> {
    if (!(game as any).user?.isGM) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.onlyTheGmCanChangeThe2')); return false; }
    const now = sysNow();
    const h = Math.max(0, Number(hoursLeft) || 0);
    const p = this.projects().find((x) => x.id === id);
    if (p) {
      const ready = projectReadyAt(now, h);
      await this.update({ [`flags.${SYSTEM_ID}.projects.${id}`]: { ...p, readyAt: ready, hours: Math.max(0, (ready - p.startedAt) / 3600) } });
      return true;
    }
    const list = [...((this.sys.training as any[] | undefined) ?? [])];
    const t = list.find((x: any) => x.id === id);
    if (!t) return false;
    const ready = projectReadyAt(now, h);
    await this.update({ 'system.training': list.map((x: any) => (x.id === id ? { ...x, readyAt: ready, days: Math.max(0, (ready - Number(x.startedAt ?? now)) / 86400) } : x)) });
    return true;
  }

  /** Projects being finished or given up on this client (a time step, Finish now and Give up never act twice). */
  static #projectBusy = new Set<string>();

  /** v0.65.0 (active GM, from timedEffects): projects whose time has passed are done. */
  static async #projectTick(a: any, time: number): Promise<void> {
    if (!(a instanceof SR2Actor)) return;
    const due = dueProjects(a.projects(), time).filter((p) => !SR2Actor.#projectBusy.has(p.id));
    if (!due.length) return;
    for (const p of due) { SR2Actor.#projectBusy.add(p.id); setTimeout(() => SR2Actor.#projectBusy.delete(p.id), 2000); }
    // Taken off first, so two quick time steps never finish one twice.
    await dropFlagKeys(a, 'projects', due.map((p) => p.id));
    for (const p of due) await a.#completeProject(p, false);
  }

  async #completeProject(p: Project, early: boolean): Promise<void> {
    let r: { ok: boolean; why?: 'gm' | 'refused' | 'failed' } = { ok: true };
    try { r = await this.#applyEffectFull(p.effect, String(p.id ?? '')); } catch (err) { console.error('sr2e | project', err); r = { ok: false, why: 'failed' }; }
    const ok = r.ok;
    if (ok) { try { await logProjectDone(this, p.label, p.by, early, (p as any).approvedBy ?? ''); } catch (err) { console.warn('sr2e | project log', err); } }
    // v0.81.1 (D1-3): the note says what really happened. A refused call ran nothing (no refund); a call that ran and
    // failed (a mod install whose mod is gone) gave back what was paid up front (or carded it for the GM).
    // v0.91.4 review (B2): an undelivered vehicle order gives back what was paid (deliverVehicle refunds it).
    const prepaid = (p.kind === 'install' && Number((p as any).effect?.call?.args?.[4] ?? 0) > 0) || (p as any).effect?.call?.method === 'deliverVehicle';
    await ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor: this }), content: ok
      ? `<p><strong>${escText(this.name)}</strong>${tx('SR2E.Card.Actor.isDone', { label: escText(p.label), part: early ? tx('SR2E.Card.Actor.theGmFinishedItEarly') : '', part2: p.done ? ` ${escText(p.done)}` : '' })}</p>`
      : r.why === 'gm'
        ? `<p><strong>${escText(this.name)}</strong>${tx('SR2E.Card.Actor.isReadyTheGmAppliesIt', { label: escText(p.label), name: escText(this.name) })}</p>`
        : `<p><strong>${escText(this.name)}</strong>${tx('SR2E.Card.Actor.couldnTBeFinishedWhatIt', { label: escText(p.label), part: prepaid && r.why === 'failed' ? tx('SR2E.Card.Actor.whatWasPaidUpFrontWas') : tx('SR2E.Card.Actor.nothingWasGivenBack') })}</p>` });
  }

  /**
   * Apply a project's effect (also what cancelling makes again).
   * v0.81.0 (SEC1-2): a project lives in the actor's flags, which its players can write, and the active GM's timer
   * finishes it with GM rights. So nothing here trusts the flag: the data written to this actor loses document keys
   * a player can't set (ownership, type, ids), and each `call` has its arguments checked (`#projectCallArgs`): actors
   * it creates are forced to their type with this actor's owners, and other documents it changes must belong to
   * this actor's players.
   */
  async #applyEffect(e: ProjectEffect): Promise<boolean> {
    return (await this.#applyEffectFull(e)).ok;
  }

  /** `#applyEffect` with why it didn't finish: 'refused' (a call whose arguments don't check out), 'gm' (carded for the GM), 'failed'. */
  async #applyEffectFull(e: ProjectEffect, projectId = ''): Promise<{ ok: boolean; why?: 'gm' | 'refused' | 'failed' }> {
    let ok = true;
    if (!e || typeof e !== 'object') return { ok: false, why: 'refused' };
    // The log gets one "Done" line for the project instead (logProjectDone).
    const quiet = { sr2eProject: true, sr2eNoAdvance: true };
    const fresh: any[] = [];
    for (const d of Array.isArray(e.creates) ? e.creates : []) {
      if (!d || typeof d !== 'object') continue;
      const c = SR2Actor.#safeItemData(foundry.utils.deepClone(d));
      // A spell already known (learned twice, or another way) only takes the higher Force; gear stacks.
      if (c.type === 'spell') {
        const known: any = [...this.items].find((i: any) => i.type === 'spell' && i.name === c.name);
        if (known) { if (Number(c.system?.learnedForce ?? 0) > Number(known.system?.learnedForce ?? 0)) await known.update({ 'system.learnedForce': Number(c.system.learnedForce) }, quiet); continue; }
      }
      if (c.type === 'gear') {
        const key = gearStackKey(c.name, c.system ?? {});
        const same: any = [...this.items].find((i: any) => i.type === 'gear' && gearStackKey(i.name, i.system) === key);
        if (same) { await same.update({ 'system.quantity': Number(same.system.quantity ?? 1) + Math.max(1, Number(c.system?.quantity ?? 1)) }, quiet); continue; }
      }
      fresh.push(c);
    }
    if (fresh.length) await this.createEmbeddedDocuments('Item', fresh, quiet);
    for (const u of Array.isArray(e.updates) ? e.updates : []) {
      const item: any = this.items.get(String(u?.itemId ?? ''));
      if (!item) { ok = false; continue; }
      const changes = SR2Actor.#safePaths(fromPairs(u.changes));
      if (Object.keys(changes).length) await item.update(changes, quiet);
    }
    if (Array.isArray(e.actor) && e.actor.length) {
      const changes = SR2Actor.#safePaths(fromPairs(e.actor));
      if (Object.keys(changes).length) await this.update(changes, quiet);
    }
    if (e.call) {
      const m = String(e.call.method);
      if (!(PROJECT_CALLS as readonly string[]).includes(m) || typeof (this as any)[m] !== 'function') return { ok: false, why: 'refused' };
      const raw = Array.isArray(e.call.args) ? e.call.args : [];
      // v0.81.1 (D1-3): a repair or mod install on a vehicle this actor's players don't own (the party's GM van, a
      // friend's car) is carded for the GM to apply, not dropped: the stored data is checked again when applied.
      if ((m === 'finishVehicleRepair' || m === 'finishModInstall') && (await this.#vehicleJobForGm(m, raw, projectId))) return { ok: false, why: 'gm' };
      // Round 2 (V-DOC 13): the vehicle is gone: the up-front money goes back (it used to be lost).
      if (m === 'finishModInstall' && (await this.#refundForGoneVehicle(raw))) return { ok: false, why: 'failed' };
      const args = await this.#projectCallArgs(m, raw);
      if (!args) { console.warn(`sr2e | project call ${m} refused: its arguments don't check out`); return { ok: false, why: 'refused' }; }
      ok = (await (this as any)[m](...args)) !== false && ok;
      if (!ok) return { ok, why: 'failed' };
    }
    return ok ? { ok } : { ok, why: 'failed' };
  }

  /**
   * v0.81.1 (D1-3): a vehicle job (finishVehicleRepair / finishModInstall) whose vehicle exists but which this
   * actor's players don't own: a whispered Apply (GM) card (flag `vehicleJob`, applied by `applyVehicleJobAsGm`),
   * true. False when the job isn't of that kind (the ordinary checks then run).
   */
  async #vehicleJobForGm(m: string, a: any[], projectId = ''): Promise<boolean> {
    const v: any = await fromUuid(String(a[0] ?? ''));
    if (!(v instanceof SR2Actor) || v.type !== 'vehicle' || this.#projectMayTouch(v)) return false;
    // Round 3 (V2 #4, FIX3-BRIEF 4): each job gets its own id (its project's), kept pending on this actor until the GM
    // settles it: two identical repairs both settle, and a card clicked again or copied doesn't.
    const jobId = String(projectId || SR2Actor.#newId()).slice(0, 64);
    const pending: string[] = [...(((this.getFlag?.(SYSTEM_ID, 'vehicleJobsPending') as string[] | undefined) ?? []))];
    try { await this.setFlag(SYSTEM_ID, 'vehicleJobsPending', [...pending.filter((x) => x !== jobId), jobId].slice(-50)); } catch { /* the GM's clock writes it */ }
    const gms = [...((game as any).users ?? [])].filter((u: any) => u.isGM).map((u: any) => u.id);
    const what = m === 'finishModInstall'
      ? tx('SR2E.Card.Actor.installIn', { slice: escText(String(a[3] ?? 'a mod').slice(0, 200)), name: escText(v.name), part: safeInt(a[4], 0, 10_000_000, 0) > 0 ? tx('SR2E.Card.Actor.paidUpFrontGiveItBack', { a: safeInt(a[4], 0, 10_000_000, 0).toLocaleString() }) : '' })
      : (Array.isArray(a[2]) && a[2].length ? tx('SR2E.Card.Actor.repairBoxEsOfWithAndIts', { a: safeInt(a[1], 0, 100, 0), name: escText(v.name), filter: escText(a[2].map((x: unknown) => String(x)).filter((x: string) => ['tires', 'engine', 'sensors'].includes(x)).join(', ')) }) : tx('SR2E.Card.Actor.repairBoxEsOfPlain', { a: safeInt(a[1], 0, 100, 0), name: escText(v.name) }));
    await ChatMessage.create({
      speaker: ChatMessage.getSpeaker({ actor: this }), whisper: gms,
      content: `<p><em>${tx('SR2E.Card.Actor.gmOnly')}</em> ${tx('SR2E.Card.Actor.sWorkIsDoneSPlayers', { name: escText(this.name), what, name2: escText(v.name) })}</p><p><button type="button" data-sr2e-action="applyVehicleJob">${tx('SR2E.Card.Actor.applyGm')}</button></p>`,
      flags: { [SYSTEM_ID]: { vehicleJob: { actorUuid: this.uuid, method: m, args: SR2Actor.#plainData(a.slice(0, 6)), jobId } } },
    });
    return true;
  }

  /**
   * v0.81.1 (D1-3, GM): apply a vehicle job card (`vehicleJob` flag) the GM's clock posted: the project actor's own
   * call, its arguments checked again (the vehicle, bounded boxes, the parts, the mod by name, a payer the project
   * actor's players own), only the vehicle's ownership waived (the GM's click is the consent).
   */
  static async applyVehicleJobAsGm(job: { actorUuid?: unknown; method?: unknown; args?: unknown; jobId?: unknown }): Promise<boolean | 'refunded'> {
    if (!isGmNow()) return false;
    const m = String(job?.method ?? '');
    if (m !== 'finishVehicleRepair' && m !== 'finishModInstall') return false;
    const a: any = await fromUuid(String(job?.actorUuid ?? ''));
    if (!(a instanceof SR2Actor)) return false;
    const raw = Array.isArray(job?.args) ? job.args as any[] : [];
    // Round 3 (V2 #4): each job settles once (applied or refunded), by its own id, pending on the project actor since
    // its card was posted: a second click or a copied card finds it gone. Two identical jobs have two ids.
    const jobId = typeof job?.jobId === 'string' ? job.jobId : '';
    const pending: string[] = [...(((a.getFlag?.(SYSTEM_ID, 'vehicleJobsPending') as string[] | undefined) ?? []))];
    if (!jobId || !pending.includes(jobId)) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.thatJobWasAlreadySettledOr')); return false; }
    const settle = async <T>(r: T): Promise<T> => { if (r) { try { await a.setFlag(SYSTEM_ID, 'vehicleJobsPending', pending.filter((x) => x !== jobId)); } catch { /* not saved */ } } return r; };
    // Round 2 (V-DOC 13): the vehicle is gone: what was paid up front goes back (once: the card is then done).
    if (m === 'finishModInstall' && (await a.#refundForGoneVehicle(raw))) return settle('refunded' as const);
    const args = await a.#projectCallArgs(m, raw, { vehicleApproved: true });
    if (!args) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.thatJobNoLongerChecksOut')); return false; }
    // Round 2 (V-DOC 3): a mod that no longer fits gives its money back: 'refunded', so the card is done (paid once).
    if (m === 'finishModInstall') { const r = await a.#finishModInstall(...(args as [string, number, string | null, string, number, string | null])); return settle(r === 'applied' ? true : r === 'refunded' ? 'refunded' as const : false); }
    return settle((await (a as any)[m](...args)) !== false);
  }

  /**
   * Round 2 (V-DOC 13): a mod install whose vehicle was deleted (or sold) meanwhile: the money paid up front goes back
   * to whoever paid it, when this actor's players own them (refundModPayer cards it for the GM otherwise). True when
   * that was the case (a refund was paid or carded).
   */
  async #refundForGoneVehicle(a: any[]): Promise<boolean> {
    const v: any = await fromUuid(String(a[0] ?? ''));
    if (v) return false;
    const prepaid = safeInt(a[4], 0, 10_000_000, 0);
    if (!prepaid || a[5] == null) return false;
    const by: any = await fromUuid(String(a[5]));
    if (!(by instanceof SR2Actor) || !this.#projectMayTouch(by)) return false;
    return (await this.refundModPayer(by.uuid, prepaid, `Installing ${String(a[3] ?? 'a mod').slice(0, 200)}`)) !== false;
  }

  /** v0.81.0 (SEC1-2): the document keys a project's data may never set (Foundry's own, and who owns it). */
  static readonly #FORBIDDEN_KEYS = new Set(['_id', '_stats', 'ownership', 'permission', 'type', 'folder', 'sort', 'pack', '__proto__', 'prototype', 'constructor']);

  /** v0.81.0 (SEC1-2): an update's paths without forbidden keys (any segment), `flags.core`, or a path that isn't text. */
  static #safePaths(changes: Record<string, unknown>): Record<string, unknown> {
    const out: Record<string, unknown> = {};
    for (const [k, v] of Object.entries(changes ?? {})) {
      const segs = String(k).replace(/^-=/, '').split('.').map((x) => x.replace(/^-=/, ''));
      if (!k || segs.some((x) => SR2Actor.#FORBIDDEN_KEYS.has(x)) || k.startsWith('flags.core')) continue;
      // v0.81.1 (D1-12): nor `flags.core` set as a nested object (`['flags', { core: … }]`).
      if (segs[0] === 'flags' && segs[1] === undefined && v && typeof v === 'object' && Object.hasOwn(v as object, 'core')) continue;
      if (v && typeof v === 'object' && !deepSafeKeys(v)) continue;
      out[k] = v;
    }
    return out;
  }

  /** v0.81.0 (SEC1-2): item data from a project's flag: a name, an item type, its system and image; nothing else. */
  static #safeItemData(d: any): any {
    const out: any = { name: String(d?.name ?? 'Item').slice(0, 200), type: String(d?.type ?? 'gear') };
    if (d?.system && typeof d.system === 'object') out.system = SR2Actor.#plainData(d.system);
    if (typeof d?.img === 'string') out.img = d.img;
    if (d?.flags?.[SYSTEM_ID] && typeof d.flags[SYSTEM_ID] === 'object') out.flags = { [SYSTEM_ID]: SR2Actor.#plainData(d.flags[SYSTEM_ID]) };
    return out;
  }

  /** A JSON copy of plain data without prototype keys (v0.81.0: data from flags). */
  static #plainData(v: any): any {
    return JSON.parse(JSON.stringify(v ?? {}), (k, x) => (k === '__proto__' || k === 'prototype' || k === 'constructor' ? undefined : x));
  }

  /**
   * v0.81.0 (SEC1-2): actor data a project creates (a ward, an ally, an elemental), forced to `type`, owned like this
   * actor (a spirit; a ward keeps Foundry's default), with this actor as its summoner; only a name, an image, the
   * token's name and link, the system data, embedded items and this system's ally marker are kept.
   */
  #projectActorData(d: any, type: 'spirit' | 'barrier'): any | null {
    if (!d || typeof d !== 'object') return null;
    const name = String(d.name ?? (type === 'spirit' ? 'Spirit' : 'Ward')).slice(0, 200);
    const system = SR2Actor.#plainData(d.system && typeof d.system === 'object' ? d.system : {});
    const out: any = { name, type, system, prototypeToken: { name, actorLink: type === 'spirit' ? true : Boolean(d.prototypeToken?.actorLink) } };
    if (typeof d.img === 'string') out.img = d.img;
    if (typeof d.prototypeToken?.texture?.src === 'string') out.prototypeToken.texture = { src: d.prototypeToken.texture.src };
    if (type === 'spirit') {
      out.ownership = { ...(this.ownership ?? {}) };
      system.summonerUuid = this.uuid;
      system.force = Math.min(30, clampSpiritForce(Number(system.force ?? 1)));
      if (Array.isArray(d.items)) out.items = d.items.slice(0, 100).filter((i: any) => i && typeof i === 'object').map((i: any) => SR2Actor.#safeItemData(i));
      if (d.flags?.[SYSTEM_ID]?.allyRitual) out.flags = { [SYSTEM_ID]: { allyRitual: true } };
    } else {
      system.barrierKind = 'ward';
      system.rating = safeInt(system.rating, 1, 30, 1);
      system.baseRating = safeInt(system.baseRating ?? system.rating, 1, 30, system.rating);
    }
    return out;
  }

  /**
   * v0.81.0 (SEC1-2): whether a project of this actor may change `target`. Yes for this actor itself. Otherwise one of
   * the players who own this actor (and so could have written the flag) must own the target too.
   * R2-SEC 1: "no player owns this actor" does not mean a GM wrote its projects (a player's card can have the GM create
   * an actor with flags in it). Such an actor's project may change only actors no player owns either; a player's
   * actor gets a GM card instead where the call has one (refundModPayer), else the project isn't finished.
   */
  #projectMayTouch(target: any): boolean {
    if (!target) return false;
    if (target === this || (target.uuid && target.uuid === this.uuid)) return true;
    const players = this.#playerOwners();
    if (!players.length) return !SR2Actor.#playerOwnersOf(target).length;
    return players.some((u: any) => Boolean(target.testUserPermission?.(u, 'OWNER')));
  }

  /** v0.81.0: the players (not GMs) who own this actor. */
  #playerOwners(): any[] {
    return SR2Actor.#playerOwnersOf(this);
  }

  /** The players (not GMs) who own a document. */
  static #playerOwnersOf(doc: any): any[] {
    return [...(((game as any).users ?? []) as any[])].filter((u: any) => !u.isGM && doc?.testUserPermission?.(u, 'OWNER'));
  }

  /** v0.81.0 (SEC1-2): a project call's arguments, checked and bounded; null when the call must not run. */
  async #projectCallArgs(m: string, a: any[], o: { vehicleApproved?: boolean } = {}): Promise<any[] | null> {
    const num = (v: unknown, max: number) => safeInt(v, 0, max, 0);
    const drain = (d: any) => (d && typeof d === 'object' ? { force: num(d.force, 30), pool: num(d.pool, 30) } : null);
    switch (m) {
      // v0.91.5: a vehicle's permit: one this actor's players own (the GM's clock may set its Permit box).
      case 'finishPermit': {
        const v: any = await fromUuid(String(a[0] ?? ''));
        if (!(v instanceof SR2Actor) || v.type !== 'vehicle' || !this.#projectMayTouch(v)) return null;
        return [v.uuid];
      }
      // v0.91.4: an ordered vehicle: a shop key (a world vehicle for sale, or a compendium's), and a player who owns this actor by name.
      // v0.91.4 review (B1): only the id of an order the GM's client recorded (deliverVehicle reads the rest from it).
      case 'deliverVehicle': {
        const id = String(a[0] ?? '');
        return /^[A-Za-z0-9]{1,64}$/.test(id) ? [id] : null;
      }
      case 'finishWard': { const d = this.#projectActorData(a[0], 'barrier'); return d ? [d, String(a[1] ?? d.name).slice(0, 200)] : null; }
      case 'finishAlly': { const d = this.#projectActorData(a[0], 'spirit'); return d ? [d] : null; }
      case 'finishElemental': { const d = this.#projectActorData(a[0], 'spirit'); return d ? [d, drain(a[1])] : null; }
      case 'giveUpElemental': return [drain(a[0])];
      case 'finishEnchant': return [String(a[0] ?? ''), num(a[1], 1000), a[2] == null ? null : String(a[2]).slice(0, 200)];
      case 'finishDesign': return [String(a[0] ?? '').slice(0, 200), SR2Actor.#plainData(a[1] && typeof a[1] === 'object' ? a[1] : {}), Array.isArray(a[2]) ? a[2].map((x: unknown) => String(x)) : []];
      case 'finishCleanse': {
        // The scene's background count is the GM's: a player's project may lower it only on a scene they are on.
        // v0.81.1 (D3-3): and finishCleanse then cards it for the GM (as the cleansing done at once does).
        const sceneId = String(a[0] ?? '');
        const onIt = [...(((game as any).scenes?.get?.(sceneId)?.tokens ?? []) as any[])].some((t: any) => t?.actor && this.#projectMayTouch(t.actor));
        if (this.#playerOwners().length && !onIt) return null;
        return [sceneId, num(a[1], MAX_BACKGROUND_COUNT), Array.isArray(a[2]) ? a[2].map((x: unknown) => String(x).slice(0, 60)).slice(0, 20) : []];
      }
      case 'finishDeckRepair': {
        const off: Record<string, number> = {};
        for (const [k, v] of Object.entries(a[1] && typeof a[1] === 'object' ? a[1] : {})) if (k in NO_DECK_DAMAGE) off[k] = num(v, 100);
        return [String(a[0] ?? ''), off];
      }
      case 'finishDeckPart': {
        const parts = ['mpcp', 'bod', 'evasion', 'masking', 'sensors', 'hardening', 'responseIncrease', 'activeMemory', 'storageMemory', 'ioSpeed'];
        if (!parts.includes(String(a[2]))) return null;
        return [a[0] == null ? null : String(a[0]), String(a[1] ?? 'Cyberdeck').slice(0, 200), String(a[2]), num(a[3], 100000), Boolean(a[4])];
      }
      case 'finishVehicleRepair': {
        const v: any = await fromUuid(String(a[0] ?? ''));
        if (!(v instanceof SR2Actor) || v.type !== 'vehicle' || !(o.vehicleApproved || this.#projectMayTouch(v))) return null;
        return [v.uuid, Math.min(num(a[1], 100), Math.max(0, Number(v.system?.condition ?? 0))), Array.isArray(a[2]) ? a[2].map((x: unknown) => String(x)).filter((x: string) => ['tires', 'engine', 'sensors'].includes(x)) : [], Boolean(a[3])];
      }
      case 'finishModInstall': {
        const v: any = await fromUuid(String(a[0] ?? ''));
        if (!(v instanceof SR2Actor) || v.type !== 'vehicle' || !(o.vehicleApproved || this.#projectMayTouch(v))) return null;
        // v0.81.1 (D3-1): the payer (charged at install) and whoever paid up front (refunded) must be this actor's
        // players' own, as the sheet's "Who pays" list is: a project's flag can't make the GM's clock charge anyone.
        const payer: any = a[2] == null ? null : await fromUuid(String(a[2]));
        if (a[2] != null && !(payer instanceof SR2Actor && this.#projectMayTouch(payer))) return null;
        const prepaidBy: any = a[5] == null ? null : await fromUuid(String(a[5]));
        if (a[5] != null && !(prepaidBy instanceof SR2Actor && this.#projectMayTouch(prepaidBy))) return null;
        return [v.uuid, num(a[1], 1000), a[2] == null ? null : String(a[2]), String(a[3] ?? '').slice(0, 200), num(a[4], 10_000_000), a[5] == null ? null : String(a[5])];
      }
      // A refund to someone this actor's players don't own goes to the GM's card (refundModPayer checks).
      case 'refundModPayer': return [a[0] == null ? null : String(a[0]), num(a[1], 10_000_000), String(a[2] ?? '').slice(0, 200)];
      default: return null;
    }
  }

  /** v0.58.0: give up training; the Karma comes back. */
  async cancelTraining(id: string): Promise<boolean> {
    const list: any[] = [...((this.sys.training as any[] | undefined) ?? [])];
    const t = list.find((x: any) => x.id === id);
    if (!t) return false;
    await this.update({ 'system.training': list.filter((x: any) => x.id !== id), 'system.karma.good': (this.sys.karma?.good ?? 0) + Number(t.cost ?? 0), 'system.ledger': this.#ledgerWith({ kind: 'karma', amount: Number(t.cost ?? 0), reason: `Training given up: ${t.label}` }) });
    return true;
  }

  /**
   * v0.58.0: an instructor's Instruction test for training under way (TN 4; their rating must reach the new
   * one): the successes divide the training time. Rolled from the student's sheet, with the instructor's dice.
   */
  async trainWith(trainingId: string, instructorUuid: string, o: { modifiers?: TargetNumberModifier[] } = {}): Promise<SuccessTestResult | null> {
    const t: any = [...((this.sys.training as any[] | undefined) ?? [])].find((x: any) => x.id === trainingId);
    const inst: any = await fromUuid(instructorUuid);
    if (!t || !inst || inst.uuid === this.uuid) return null;
    const c = RULES.CHARACTERS_V58.training;
    const isd = inst instanceof SR2Actor ? inst.#skillDice(inst.findSkill(c.instructionSkill), false, null, 'charisma', { skillName: c.instructionSkill }) : { dice: 0, modifiers: [] as TargetNumberModifier[], suffix: '' };
    const skill: any = t.skillId ? this.items.get(t.skillId) : null;
    // What the instructor needs to know: the skill itself, or the attribute.
    const theirs: any = skill ? inst.findSkill?.(skill.name) : null;
    const instructorRating = skill ? Number(theirs?.system?.rating ?? 0) : Number(inst.system?.attributes?.[t.attribute]?.total ?? 0);
    // Rolled as the instructor's test (their Karma Pool re-rolls it); each test divides the untaught time, so tests don't stack.
    const roller: SR2Actor = inst instanceof SR2Actor ? inst : this;
    return roller.#runTest(tx('SR2E.Card.Actor.instructionTeaches', { instName: inst.name, name: this.name, label: t.label, instructionSkill: c.instructionSkill, isdSuffix: isd.suffix }), isd.dice, {
      targetNumber: c.instructionTn, modifiers: [...(o.modifiers ?? []), ...isd.modifiers],
    }, { kind: 'plain', instruct: { studentUuid: this.uuid as string, trainingId, days: Number(t.baseDays || t.days || 0), instructorName: String(inst.name), instructorRating, newRating: Number(t.to ?? 0), startedAt: Number(t.startedAt ?? 0), ...urrCoreInstructExtra(t) } });
  }

  /** v0.58.0 (active GM, from timedEffects): training whose time has passed raises the rating. */
  static async #trainingTick(a: any, time: number): Promise<void> {
    const list: any[] = [...((a.system?.training as any[] | undefined) ?? [])];
    const due = list.filter((t: any) => time >= Number(t.readyAt ?? 0));
    if (!due.length) return;
    // Taken off first, so two quick time steps never raise twice.
    await a.update({ 'system.training': list.filter((t: any) => time < Number(t.readyAt ?? 0)) });
    const done: string[] = [];
    // v0.73.0 (O42): the raise is quiet; one Done line per finished entry (RULES.CROSSCUT_V73.advancement.trainingDone).
    const mode = trainingDoneMode();
    const quiet: any = mode === 'old' ? {} : { sr2eNoAdvance: true };
    for (const t of due) {
      if (t.attribute) {
        const at = a.system.attributes?.[t.attribute];
        // v0.81.1 (D1-6): an attribute that isn't there any more: the Karma comes back (it was lost silently).
        if (!at) { await SR2Actor.#refundTraining(a, t, 'gone'); continue; }
        if (Number(at.natural ?? at.base) < Number(t.to)) await a.update({ [`system.attributes.${t.attribute}.base`]: attributeRaiseBase(Number(at.base ?? 0), Number(at.rawNatural ?? at.natural ?? at.base), Number(t.to)) }, quiet);
        else { await SR2Actor.#refundTraining(a, t); continue; }
      } else {
        const sk: any = a.items?.get?.(t.skillId);
        // v0.81.1 (D1-6): the skill was deleted (renamed into a new item, re-imported) meanwhile: the Karma comes back.
        if (!sk) { await SR2Actor.#refundTraining(a, t, 'gone'); continue; }
        const path = t.part === 'specialization' ? 'system.specializationRating' : t.part === 'concentration' ? 'system.concentrationRating' : 'system.rating';
        const cur = Number(foundry.utils.getProperty(sk, path) ?? 0);
        if (cur < Number(t.to)) await sk.update({ [path]: Number(t.to) }, quiet);
        else { await SR2Actor.#refundTraining(a, t); continue; }
      }
      done.push(String(t.label));
      if (mode === 'doneLine') { try { await logProjectDone(a, `Training ${t.label}`, String(t.by ?? ''), false, String(t.approvedBy ?? '')); } catch (err) { console.warn('sr2e | training log', err); } }
    }
    if (done.length) await ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor: a }), content: `<p><strong>${escText(a.name)}</strong> ${tx('SR2E.Card.Actor.finishesTraining', { done: done.map(escText).join(', ') })}</p>` });
  }

  /** The most Karma one training entry gives back (v0.81.1: the entry is in the actor's data, which its players write). */
  static readonly #MAX_TRAINING_REFUND = 100;

  /**
   * v0.58.0: training whose rating was already reached another way: its Karma comes back.
   * v0.81.1 (D1-6): also training whose skill or attribute is gone (`why` 'gone'). The amount is bounded: the GM's
   * clock pays it from a list the actor's players can write.
   */
  static async #refundTraining(a: any, t: any, why: 'reached' | 'gone' = 'reached'): Promise<void> {
    const cost = safeInt(t.cost, 0, SR2Actor.#MAX_TRAINING_REFUND, 0);
    const label = String(t.label ?? 'training').slice(0, 200);
    if (!cost) {
      if (why === 'gone') await ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor: a }), content: `<p>${tx('SR2E.Card.Actor.sTrainingCanTFinishWhat', { name: escText(a.name), label: escText(label) })}</p>` });
      return;
    }
    const reason = why === 'gone' ? `Training refunded (no longer there): ${label}` : `Training refunded (already reached): ${label}`;
    await a.update({ 'system.karma.good': Number(a.system?.karma?.good ?? 0) + cost, 'system.ledger': (a instanceof SR2Actor ? a.#ledgerWith({ kind: 'karma', amount: cost, reason }) : a.system?.ledger ?? []) });
    await ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor: a }), content: why === 'gone'
      ? `<p>${tx('SR2E.Card.Actor.sTrainingCanTFinishWhat2', { name: escText(a.name), label: escText(label), cost })}</p>`
      : `<p>${tx('SR2E.Card.Actor.alreadyReachedKarmaComesBack', { name: escText(a.name), label: escText(label), cost })}</p>` });
  }

  // ---- Negotiating pay, recognition, Karma awards

  /**
   * v0.58.0: negotiate a job's pay with Mr. Johnson: an opposed Negotiation test (as a social test); each
   * net success moves the fee (RULES.CHARACTERS_V58.negotiation). The card keeps the fee, so a GM's TN change re-prices it.
   */
  async negotiatePay(baseFee: number, johnsonUuid: string, opts: { modifiers?: TargetNumberModifier[]; exclude?: string[]; excludeTheirs?: string[] } = {}): Promise<{ pay: number; net: number } | null> {
    const base = Math.max(0, Math.floor(baseFee));
    const r = await this.socialTest(RULES.CHARACTERS_V58.negotiation.skill, johnsonUuid, { ...opts, pay: base, attribute: negotiationAttribute() } as any);
    if (!r) return null;
    const net = r.winner === 'initiator' ? r.net : r.winner === 'defender' ? -r.net : 0;
    return { pay: negotiatedPay(base, net).pay, net };
  }

  /**
   * v0.58.0: does anyone recognise this character? Each observer rolls Intelligence vs (10 − Public
   * Awareness); whispered to the GMs.
   */
  async recognitionCheck(observerUuids: string[]): Promise<string[]> {
    const pa = Number(this.sys.reputation?.publicAwareness ?? 0);
    const tn = recognitionTn(pa);
    const attr = RULES.CHARACTERS_V58.recognition.attribute;
    const rows: string[] = [];
    const who: string[] = [];
    const rolls: any[] = [];
    for (const u of observerUuids) {
      const o: any = await fromUuid(u);
      if (!o || o.uuid === this.uuid) continue;
      const r = await successTest({ dice: Number(o.system?.attributes?.[attr]?.total ?? 0), targetNumber: tn, modifiers: o.woundModifiers?.() ?? [], roll: foundryRoller(rolls) });
      if (r.successes > 0) who.push(o.name);
      rows.push(`<li>${escText(o.name)}: ${escText(plural(r.successes, 'success'))}${r.successes > 0 ? ` — <strong>${tx('SR2E.Card.Actor.recognisesThem')}</strong>` : ''}</li>`);
    }
    if (!rows.length) return [];
    const gms = [...((game as any).users ?? [])].filter((u: any) => u.isGM).map((u: any) => u.id);
    await ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor: this }), whisper: gms, blind: true, rolls,
      content: `<div class="sr2e-roll"><h3>${tx('SR2E.Card.Actor.whoRecognises', { name: escText(this.name) })}</h3><p>${tx('SR2E.Card.Actor.vsTnPublicAwareness', { attr: escText(cap(attr)), tn, recognitionBaseTn: RULES.CHARACTERS_V58.recognition.baseTn, pa })}</p></div><ul>${rows.join('')}</ul><p>${who.length ? `<strong>${tx('SR2E.Card.Actor.recognised')}</strong> ${tx('SR2E.Card.Actor.by5', { who: who.map(escText).join(', ') })}` : tx('SR2E.Card.Actor.noOneRecognisesThem')}</p>` });
    return who;
  }

  /**
   * v0.58.0: a Karma award with the GM chapter's breakdown: team rows for everyone, individual rows per
   * character. Each gets their own total (and the reason lists the rows).
   */
  static async awardBreakdown(o: { team: Record<string, number>; individual: Record<string, Record<string, boolean | number>>; nuyen?: number; reason?: string; refreshPool?: boolean }): Promise<number> {
    let n = 0;
    const lines: string[] = [];
    for (const [uuid, ind] of Object.entries(o.individual)) {
      const a: any = await fromUuid(uuid);
      if (!a?.awardKarma) continue;
      const t = karmaAwardTotal({ team: o.team, individual: ind });
      if (t.total > 0) { await a.awardKarma(t.total, `${o.reason ? `${o.reason}: ` : ''}${t.lines.join(', ')}`); n++; }
      if (o.nuyen) await a.adjustNuyen(Math.floor(o.nuyen), o.reason || 'Pay');
      if (o.refreshPool) await a.update({ 'system.karma.poolSpent': 0 });
      lines.push(`<li>${escText(a.name)}: <strong>${t.total}</strong> ${tx('SR2E.Card.Actor.karma4', { part: t.lines.length ? ` (${t.lines.map(escText).join(', ')})` : '' })}</li>`);
    }
    if (lines.length) await ChatMessage.create({ speaker: { alias: tx('SR2E.Card.Actor.karmaAwards') }, content: `<p><strong>${tx('SR2E.Card.Actor.karmaAwarded', { part: o.reason ? `: ${escText(o.reason)}` : '' })}</strong></p><ul>${lines.join('')}</ul>` });
    return n;
  }

  // ---- Essence holes

  /** v0.58.0: hole changes one at a time per actor (several items created or deleted at once each read the hole as the last change left it). */
  static #holeQueue = new Map<string, Promise<unknown>>();
  #queueHole<T>(fn: () => Promise<T>): Promise<T> {
    const key = String(this.uuid);
    const prev = SR2Actor.#holeQueue.get(key) ?? Promise.resolve();
    const next = prev.then(fn, fn);
    SR2Actor.#holeQueue.set(key, next.catch(() => undefined));
    return next;
  }

  /** v0.58.0: an Essence hole left by cyberware leaving the body (removed or switched off); the new hole. */
  async openEssenceHole(loss: number, name: string): Promise<number> {
    return this.#queueHole(async () => {
      if (!RULES.GEAR_V58.essenceHoles.enabled || loss <= 0) return Number(this.sys.essenceHole ?? 0);
      const hole = essenceHoleAfterRemoval(Number(this.sys.essenceHole ?? 0), loss);
      await this.update({ 'system.essenceHole': hole }, { sr2eHole: true } as any);
      await ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor: this }), whisper: [...((game as any).users ?? [])].filter((u: any) => u.isGM || this.testUserPermission?.(u, 'OWNER')).map((u: any) => u.id),
        content: `<p>${tx('SR2E.Card.Actor.leavesAnEssenceHoleOf', { name: escText(name), name2: escText(this.name) })} <strong>${hole}</strong> ${tx('SR2E.Card.Actor.moreNewCyberwareFillsItFirst', { loss })} <span class="hint">${tx('SR2E.Card.Actor.aMistakeSetTheHoleOn')}</span></p>` });
      return hole;
    });
  }

  /** v0.58.0: cyberware going in fills the hole first; the hole left. */
  async fillEssenceHole(loss: number): Promise<number> {
    return this.#queueHole(async () => {
      const before = Number(this.sys.essenceHole ?? 0);
      if (!RULES.GEAR_V58.essenceHoles.enabled || loss <= 0 || before <= 0) return before;
      const r = essenceHoleAfterInstall(before, loss);
      await this.update({ 'system.essenceHole': r.hole }, { sr2eHole: true } as any);
      return r.hole;
    });
  }

  /** v0.58.0: the Essence the ware housed in a cyberlimb would cost outside it. */
  static housedEssence(limb: any, actor: any = limb?.parent): number {
    if (limb?.system?.kind !== 'cyberlimb') return 0;
    const sum = [...(actor?.items ?? [])].filter((i: any) => i.type === 'cyberware' && i.id !== limb.id && i.system?.housedIn === limb.id && i.system?.installed && !i.system?.bioware)
      .reduce((n: number, i: any) => n + essenceLoss({ essenceCost: sensitiveEssence(Number(i.system.essenceCost ?? 0), qualityVitals(actor?.system?.qualities ?? [], RULES.STREET.qualities.enabled)), grade: i.system.grade }), 0);
    return Math.round(sum * 100) / 100;
  }

  /** v0.58.0: the Essence an item costs in the body (0 for bioware, ware housed in a cyberlimb, or not installed). */
  static essenceOf(item: any, actor: any = item?.parent): number {
    if (item?.type !== 'cyberware' || item.system?.bioware || !item.system?.installed) return 0;
    const housed = item.system.housedIn && [...(actor?.items ?? [])].some((i: any) => i.id === item.system.housedIn && i.system?.kind === 'cyberlimb' && i.system?.installed);
    // v0.72.0 (O11): Sensitive System's dearer Essence, as in augmentationsOf.
    return housed ? 0 : essenceLoss({ essenceCost: sensitiveEssence(Number(item.system.essenceCost ?? 0), qualityVitals(actor?.system?.qualities ?? [], RULES.STREET.qualities.enabled)), grade: item.system.grade });
  }

  // ---- Filtration, bone lacing

  /** v0.58.0: dice a filtration system adds against a toxin of this vector. */
  filtrationFor(vector: string): { dice: number; label: string } {
    const f: any[] = (this.sys.derived?.cyber?.filters as any[] | undefined) ?? [];
    const dice = filtrationDice(f, vector);
    const best = f.filter((x) => filtrationDice([x], vector) === dice && dice > 0)[0];
    return { dice, label: best ? best.name : '' };
  }

  // ---- Surveillance gear

  /** v0.58.0: plant a bug or tap on someone (or something): kept on the bug, so a sweep can find it. */
  async plantBug(itemId: string, targetUuid: string): Promise<boolean> {
    const item: any = this.items.get(itemId);
    const k = surveillanceKind(String(item?.system?.surveillance?.kind ?? ''));
    if (!item || !k?.transmits) return false;
    const target: any = await fromUuid(targetUuid);
    if (!target) return false;
    await item.update({ 'system.surveillance.plantedOn': target.uuid, 'system.surveillance.plantedName': target.name });
    const gms = [...((game as any).users ?? [])].filter((u: any) => u.isGM).map((u: any) => u.id);
    await ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor: this }), whisper: [...new Set([...gms, (game as any).user?.id])], content: `<p>${tx('SR2E.Card.Actor.plantsRatingOn', { name: escText(this.name), itemName: escText(item.name), surveillanceRating: escText(item.system.surveillance.rating) })} <strong>${escText(target.name)}</strong>.</p>` });
    return true;
  }

  /** v0.58.0: the strongest active device of a kind someone carries (white noise, a comm jammer). */
  static strongestDevice(actor: any, kind: string): number {
    if (!actor?.items) return 0;
    return strongestActive([...actor.items].filter((i: any) => i.type === 'gear' && !i.system?.damaged && isCarried(i)).map((i: any) => ({ kind: String(i.system?.surveillance?.kind ?? ''), rating: Number(i.system?.surveillance?.rating ?? 0), active: i.system?.surveillance?.active !== false })), kind);
  }

  /**
   * v0.58.0: listen through a bug, tap or microphone: its rating vs TN 4 + the strongest active white-noise
   * generator where it listens; a comm jammer there blocks a bug's or tap's transmission.
   */
  async listenIn(itemId: string, o: { targetUuid?: string | null; modifiers?: TargetNumberModifier[]; what?: string } = {}): Promise<SuccessTestResult | null> {
    if (this.#exclusiveBlocks()) return null;
    const item: any = this.items.get(itemId);
    const sv = item?.system?.surveillance;
    const k = surveillanceKind(String(sv?.kind ?? ''));
    if (!item || !k?.listens) return null;
    if (item.system.damaged) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.isBroken', { itemName: escHtml(item.name) })); return null; }
    const where: any = k.transmits ? (sv.plantedOn ? await fromUuid(sv.plantedOn) : null) : (o.targetUuid ? await fromUuid(o.targetUuid) : null);
    if (k.transmits && !where) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.hasnTBeenPlantedOnAnyone', { itemName: escHtml(item.name) })); return null; }
    const jam = where ? SR2Actor.strongestDevice(where, 'commJammer') : 0;
    if (k.transmits && jammed(jam, Number(sv.rating ?? 0))) {
      await ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor: this }), content: `<p>${escText(item.name)}: <strong>${tx('SR2E.Card.Actor.onlyStatic')}</strong> ${tx('SR2E.Card.Actor.aCommJammerBlocksIt', { jam })}</p>` });
      return null;
    }
    const wn = where ? SR2Actor.strongestDevice(where, 'whiteNoise') : 0;
    const l = listenTest({ rating: Number(sv.rating ?? 0), whiteNoise: wn });
    return this.#runTest(where ? tx('SR2E.Card.Actor.bugTestOn', { name: item.name, kind: k.label, rating: sv.rating, where: where.name }) : tx('SR2E.Card.Actor.bugTest', { name: item.name, kind: k.label, rating: sv.rating }), l.dice, { targetNumber: l.baseTn, noPenalties: true, modifiers: [...l.modifiers, ...(o.modifiers ?? [])] },
      { kind: 'plain', reveal: { kind: 'listen', ...(o.what ? { what: o.what } : {}) } });
  }

  /**
   * v0.58.0: sweep someone (or this character) with a bug scanner: its rating vs each planted bug's rating.
   * What it finds goes to the sweeper and the GMs; the GM can take a found bug off.
   */
  async sweepForBugs(scannerId: string, targetUuid: string): Promise<string[]> {
    const sc: any = this.items.get(scannerId);
    if (!sc || sc.system?.surveillance?.kind !== 'bugScanner') return [];
    if (!isCarried(sc)) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.notCarried', { name: escHtml(sc.name) })); return []; }
    if (sc.system.damaged) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.isBroken2', { scName: escHtml(sc.name) })); return []; }
    const target: any = await fromUuid(targetUuid);
    if (!target) return [];
    const ids = new Set<string>([target.uuid, ...(target.selfUuids?.() ?? [])]);
    const owners: any[] = allActors();
    const bugs: any[] = owners.flatMap((a: any) => [...(a.items ?? [])].filter((i: any) => i.type === 'gear' && surveillanceKind(String(i.system?.surveillance?.kind ?? ''))?.transmits && ids.has(String(i.system.surveillance.plantedOn ?? ''))));
    const rating = Number(sc.system.surveillance.rating ?? 0);
    const rolls: any[] = [];
    const rows: string[] = [];
    const found: string[] = [];
    const buttons: string[] = [];
    for (const b of bugs) {
      const s = bugSweep({ scannerRating: rating, bugRating: Number(b.system.surveillance.rating ?? 0) });
      const r = await successTest({ dice: s.dice, targetNumber: s.tn, roll: foundryRoller(rolls) });
      const ok = r.successes > 0;
      if (ok) { found.push(b.name); buttons.push(`<button type="button" data-sr2e-action="removeBug" data-bug-uuid="${escText(b.uuid)}">${tx('SR2E.Card.Actor.takeOff', { name: escText(b.name) })}</button>`); }
      rows.push(`<li>${tx('SR2E.Card.Actor.ratingTn', { name: escText(b.name), surveillanceRating: escText(b.system.surveillance.rating), tn: s.tn, plural: escText(plural(r.successes, 'success')), part: ok ? ` — <strong>${tx('SR2E.Card.Actor.found3')}</strong>` : tx('SR2E.Card.Actor.missed') })}</li>`);
    }
    const gms = [...((game as any).users ?? [])].filter((u: any) => u.isGM).map((u: any) => u.id);
    await ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor: this }), whisper: [...new Set([...gms, (game as any).user?.id])],
      content: `<div class="sr2e-roll"><h3>${tx('SR2E.Card.Actor.sweepsForBugs', { name: escText(this.name), targetName: escText(target.name) })}</h3><p>${tx('SR2E.Card.Actor.rating', { scName: escText(sc.name), rating })}</p></div><p>${found.length ? `<strong>${tx('SR2E.Card.Actor.found')}</strong> ${found.map(escText).join(', ')}.` : `<strong>${tx('SR2E.Card.Actor.nothingFound')}</strong>`}</p>${buttons.length ? `<p>${buttons.join(' ')}</p>` : ''}` });
    if (rows.length) await ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor: this }), whisper: gms, blind: true, rolls, content: `<p><em>${tx('SR2E.Card.Actor.gmOnly')}</em> ${tx('SR2E.Card.Actor.theSweepOf', { targetName: escText(target.name) })}</p><ul>${rows.join('')}</ul>` });
    return found;
  }

  /** v0.58.0: take a found bug off (its owner or the GM). */
  static async removeBug(bugUuid: string): Promise<boolean> {
    const b: any = await fromUuid(bugUuid);
    if (!b) return false;
    if (!canWriteNow(b)) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.onlyTheGmOrTheBug')); return false; }
    if (!b.system?.surveillance?.plantedOn) { ui.notifications?.info?.(tx('SR2E.Notify.Actor.isnTPlantedOnAnyone', { name: escHtml(b.name) })); return false; }
    const was = String(b.system?.surveillance?.plantedName ?? '');
    await b.update({ 'system.surveillance.plantedOn': '', 'system.surveillance.plantedName': '' });
    await ChatMessage.create({ speaker: { alias: tx('SR2E.Card.Actor.bugSweep') }, content: `<p>${tx('SR2E.Card.Actor.isTakenOff', { name: escText(b.name), part: was ? ` ${escText(was)}` : '' })}</p>` });
    return true;
  }

  // ---- Legality

  /** v0.58.0: gear this character carries that the law cares about (no permit, or forbidden), with the fines. */
  legalProblems(): { problems: Array<{ name: string; label: string; fine: number }>; totalFine: number; covered: Array<{ name: string; by: string; fake: boolean }> } {
    const items = [...(this.items ?? [])].filter((i: any) => ['weapon', 'armor', 'gear', 'cyberware'].includes(i.type) && i.system?.legality)
      .map((i: any) => ({ name: String(i.name), category: String(i.system.legality), legality: String(i.system.legality), permit: Boolean(i.system.permit), rating: Number(i.system.rating ?? i.system.surveillance?.rating ?? 0) }));
    // v0.61.0: a licence (real or fake) covers what it names (STREET_V61.identity).
    const covered = legalWithLicences(items, this.licences()).filter((r) => r.coveredBy).map((r) => ({ name: r.name, by: String(r.coveredBy), fake: r.fake }));
    const out = legalSummary(items.filter((i) => !covered.some((c) => c.name === i.name)));
    return { ...out, covered };
  }

  /** v0.91.5 review (R5): the licence (real or fake) that covers a thing of this name and legality, if any. */
  licenceCover(name: string, legality: string): { by: string; fake: boolean } | null {
    const r = legalWithLicences([{ name: String(name ?? ''), legality: String(legality ?? ''), permit: false }], this.licences())[0];
    return r?.coveredBy ? { by: String(r.coveredBy), fake: Boolean(r.fake) } : null;
  }

  /** v0.61.0: the licences (permits) this actor carries, real or fake. */
  licences(): Array<{ name: string; covers: string; fake: boolean; rating: number; kind: string }> {
    return [...(this.items ?? [])].filter((i: any) => i.type === 'gear' && i.system?.identity?.kind === 'licence' && Number(i.system.quantity ?? 1) > 0 && isCarried(i))
      .map((i: any) => ({ name: String(i.name), covers: String(i.system.identity.covers ?? ''), fake: Boolean(i.system.identity.fake), rating: Number(i.system.identity.rating ?? 0), kind: 'licence' }));
  }

  /** v0.61.0: an ID (SIN or licence) against a checker: the checker's rating in dice vs the fake's rating (STREET_V61.identity). */
  async checkId(itemId: string, checkerRating: number): Promise<{ spotted: boolean } | null> {
    const it: any = [...(this.items ?? [])].find((i: any) => i.id === itemId);
    const idn = it?.system?.identity;
    if (!idn?.kind) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.thatIsNotAnId')); return null; }
    const t = idCheckTest({ checkerRating, rating: Number(idn.rating ?? 0), fake: Boolean(idn.fake) });
    const gms = [...((game as any).users ?? [])].filter((u: any) => u.isGM).map((u: any) => u.id);
    if (t.auto === 'pass') {
      await ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor: this }), content: `<p>${tx('SR2E.Card.Actor.sChecksOutAReal', { name: escText(this.name), name2: escText(it.name), part: idn.kind === 'sin' ? tx('SR2E.Card.Actor.sin') : tx('SR2E.Card.Actor.licence') })}</p>` });
      return { spotted: false };
    }
    const rolls: any[] = [];
    const r = await successTest({ dice: t.dice, targetNumber: t.tn, roll: foundryRoller(rolls) });
    // With 'netSuccess' the fake rolls back: its rating vs the checker's rating; the checker needs more.
    const forger = RULES.STREET_V61.identity.spottedOn === 'netSuccess' ? await successTest({ dice: Math.max(0, Number(idn.rating ?? 0)), targetNumber: Math.max(RULES.MIN_TARGET_NUMBER, checkerRating), roll: foundryRoller(rolls) }) : null;
    const o = idCheckOutcome(r.successes, forger?.successes ?? 0);
    await ChatMessage.create({ speaker: { alias: tx('SR2E.Card.Actor.idCheck') }, rolls, whisper: gms, ...(isGmNow() ? {} : { blind: true }),
      content: `<p><em>${tx('SR2E.Card.Actor.gmOnly')}</em> ${forger ? tCount(r.successes, 'SR2E.Card.Actor.sRatingAgainstARatingCheckerFake', { name: escText(this.name), name2: escText(it.name), idnRating: escText(idn.rating), checkerRating, dice: t.dice, tn: t.tn, forgerSuccesses: forger.successes }) : tCount(r.successes, 'SR2E.Card.Actor.sRatingAgainstARatingChecker', { name: escText(this.name), name2: escText(it.name), idnRating: escText(idn.rating), checkerRating, dice: t.dice, tn: t.tn })} <strong>${escText(o.note)}</strong></p>` });
    return { spotted: o.spotted };
  }

  /** v0.61.0: jammers switched on in the scene (gear jammers and comm jammers on any token's actor). */
  static jammersOnScene(): Array<{ name: string; rating: number }> {
    const out: Array<{ name: string; rating: number }> = [];
    const seen = new Set<string>();
    for (const t of [...(((canvas as any)?.scene?.tokens ?? []) as any[])]) {
      const a: any = t.actor;
      if (!a || seen.has(a.uuid)) continue;
      seen.add(a.uuid);
      for (const i of [...(a.items ?? [])] as any[]) {
        if (i.type !== 'gear' || i.system?.damaged) continue;
        const cj = i.system?.surveillance?.kind === 'commJammer' && i.system.surveillance.active ? Number(i.system.surveillance.rating ?? 0) : 0;
        const r = Math.max(Number(i.system?.jammer ?? 0), cj);
        if (r > 0) out.push({ name: `${i.name} (${a.name})`, rating: r });
      }
    }
    return out;
  }

  /** v0.61.0: can this character's radio get through (STREET_V61.radio)? The best radio against the strongest jammer in the scene. */
  async radioCheck(): Promise<void> {
    const radios = [...(this.items ?? [])].filter((i: any) => i.type === 'gear' && Number(i.system?.radio?.rating ?? 0) > 0 && !i.system?.damaged && isCarried(i))
      .map((i: any) => ({ name: String(i.name), signal: Number(i.system.radio.rating), encryption: Number(i.system.radio.encryption ?? 0) }));
    const own = new Set([...(this.items ?? [])].map((i: any) => `${i.name} (${this.name})`));
    const c = commsStatus({ radios, jammers: SR2Actor.jammersOnScene().filter((j) => !own.has(j.name)) });
    await ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor: this }), content: `<p><strong>${tx('SR2E.Card.Actor.sRadio', { name: escText(this.name) })}</strong> ${escText(c.note)}</p>` });
  }

  /** v0.61.0: listen in on someone's radio: Electronics (or its default) vs the encryption (STREET_V61.radio). */
  async interceptComms(targetUuid: string): Promise<SuccessTestResult | null> {
    if (this.#exclusiveBlocks()) return null;
    const target: any = await fromUuid(targetUuid);
    const radios = [...(target?.items ?? [])].filter((i: any) => i.type === 'gear' && Number(i.system?.radio?.rating ?? 0) > 0 && isCarried(i));
    if (!target || !radios.length) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.carryNoRadio', { targetName: escHtml(target?.name ?? tx('SR2E.Notify.Actor.they')) })); return null; }
    const best = radios.reduce((b: any, i: any) => (Number(i.system.radio.rating) > Number(b.system.radio.rating) ? i : b));
    const name = String(RULES.STREET_V61.radio.interceptSkill ?? 'Electronics');
    const sd = this.#skillDice(this.findSkill(name), false, null, 'intelligence', { skillName: name });
    const t = interceptTest({ dice: sd.dice, encryption: Number(best.system.radio.encryption ?? 0) });
    // v0.80.0 (RULES.URR_V80.dsRadioDecrypt 'urr', URR): vs the encryption + 3, needing half the encryption in successes.
    const u = dsRadioDecrypt({ encryption: Number(best.system.radio.encryption ?? 0) });
    if (u) return this.#runTest(tCount(u.need, 'SR2E.Card.Actor.listenInSNeedsSuccesses', { targetName: target.name, bestName: best.name, name, sdSuffix: sd.suffix }), sd.dice, { targetNumber: u.baseTn, modifiers: [...sd.modifiers, ...u.modifiers] }, { kind: 'plain', need80: u.need });
    return this.#runTest(tx('SR2E.Card.Actor.listenInS', { targetName: target.name, bestName: best.name, name, sdSuffix: sd.suffix }), t.dice, { targetNumber: t.tn - t.modifiers.reduce((n, m) => n + m.value, 0), modifiers: [...sd.modifiers, ...t.modifiers] }, { kind: 'plain' });
  }

  /** v0.58.0: a short legality note for items found on this actor (by name), for search cards. */
  legalNotes(names: readonly string[]): string[] {
    const out: string[] = [];
    for (const n of names) {
      const i: any = [...(this.items ?? [])].find((x: any) => x.name === n && x.system?.legality);
      if (!i) continue;
      // v0.61.0: a licence covering it (a fake one is noted, so the GM can have it checked).
      const lic = legalWithLicences([{ name: String(i.name), legality: String(i.system.legality), permit: Boolean(i.system.permit), rating: Number(i.system.rating ?? 0) }], this.licences())[0];
      if (lic?.coveredBy) { out.push(lic.fake ? tx('SR2E.Card.Actor.licensedFakeWorthAnIdCheck', { name: n, coveredBy: lic.coveredBy }) : tx('SR2E.Card.Actor.licensed', { name: n, coveredBy: lic.coveredBy })); continue; }
      const c = legalCheck({ category: String(i.system.legality), permit: Boolean(i.system.permit), rating: Number(i.system.rating ?? i.system.surveillance?.rating ?? 0) });
      out.push(c.ok ? (i.system.permit ? tx('SR2E.Card.Actor.legalPermit', { name: n, label: c.label }) : `${n}: ${c.label}`) : c.fine ? tx('SR2E.Card.Actor.legalNoteFine', { name: n, label: c.label, note: c.note, fine: c.fine.toLocaleString() }) : tx('SR2E.Card.Actor.legalNote', { name: n, label: c.label, note: c.note }));
    }
    return out;
  }

  // ---------------------------------------------------------------- Characters and the street (v0.44.0)

  /** Mark this NPC (and its token group) broken, or no longer broken. */
  async #setBroken(on: boolean, group: { actors: any[] } | null = this.moraleGroup()): Promise<void> {
    const list: any[] = group ? group.actors : [this];
    for (const a of list) {
      // v0.73.0 live fix: an unlinked token's actor can't drop a flag key (-= in its delta), so write false instead.
      try { await a.setFlag(SYSTEM_ID, 'broken', on); } catch { /* not saved */ }
    }
  }

  /** Whether this NPC's group has broken (a failed morale test, until rallied). */
  isBroken(): boolean {
    return Boolean(this.getFlag?.(SYSTEM_ID, 'broken'));
  }

  /** This actor's token (the synthetic actor's own, else its first active one). */
  #tokenDoc(): any {
    return (this as any).token ?? (this as any).getActiveTokens?.()?.[0]?.document ?? null;
  }

  /**
   * A grunt group spread over separate tokens (v0.44.0): the tokens sharing this one's group flag,
   * their actors, and how many are down.
   */
  gruntGroup(): { id: string; tokens: any[]; actors: any[]; standing: any[]; down: number } | null {
    const tok = this.#tokenDoc();
    const id = tok?.getFlag?.(SYSTEM_ID, 'gruntGroup');
    if (!id || !tok.parent) return null;
    const tokens = [...(tok.parent.tokens ?? [])].filter((t: any) => t.getFlag?.(SYSTEM_ID, 'gruntGroup') === id);
    const actors = tokens.map((t: any) => t.actor).filter(Boolean);
    const standing = actors.filter((a: any) => !['unconscious', 'dying', 'dead'].includes(a.system?.derived?.status ?? 'ok'));
    return { id, tokens, actors, standing, down: actors.length - standing.length };
  }

  /**
   * v0.49.0: the group this NPC tests morale with: a mixed group the GM made (token flag
   * `moraleGroup`), else its split grunt group. `mixed` is true when it holds different NPCs.
   */
  moraleGroup(): { id: string; tokens: any[]; actors: any[]; standing: any[]; down: number; mixed: boolean; flagged: boolean } | null {
    const tok = this.#tokenDoc();
    const mid = tok?.getFlag?.(SYSTEM_ID, 'moraleGroup');
    if (!mid || !tok.parent) {
      const g = this.gruntGroup();
      return g ? { ...g, mixed: false, flagged: false } : null;
    }
    const tokens = [...(tok.parent.tokens ?? [])].filter((t: any) => t.getFlag?.(SYSTEM_ID, 'moraleGroup') === mid);
    const actors = tokens.map((t: any) => t.actor).filter(Boolean);
    const standing = actors.filter((a: any) => !['unconscious', 'dying', 'dead'].includes(a.system?.derived?.status ?? 'ok'));
    // A grunt group on one sheet counts its own fallen too.
    const sheetDown = actors.reduce((n: number, a: any) => n + Number(a.system?.grunts?.down ?? 0), 0);
    const kinds = new Set(actors.map((a: any) => a.id ?? a.uuid));
    return { id: mid, tokens, actors, standing, down: actors.length - standing.length + sheetDown, mixed: kinds.size > 1, flagged: true };
  }

  /** v0.49.0 (GM): put these tokens in one mixed group for morale (null id: take them out of any). */
  static async setMoraleGroup(tokens: any[], on = true): Promise<string | null> {
    const id = on ? SR2Actor.#newId() : null;
    for (const t of tokens) {
      const doc = t.document ?? t;
      try {
        if (id) await doc.setFlag(SYSTEM_ID, 'moraleGroup', id);
        else await clearFlag(doc, 'moraleGroup');
      } catch { /* not saved */ }
    }
    return id;
  }

  /** Split a grunt group into one token per grunt next to this NPC's token (unlinked tokens only). */
  async splitGrunts(): Promise<number> {
    const tok = this.#tokenDoc();
    const size = Math.max(1, Math.floor(this.sys.grunts?.size ?? 1));
    const left = gruntsStanding(size, this.sys.grunts?.down ?? 0);
    if (!tok?.parent) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.needsATokenOnTheScene', { name: escHtml(this.name) })); return 0; }
    if (tok.actorLink) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.sTokenIsLinkedToThe', { name: escHtml(this.name) })); return 0; }
    if (left <= 1) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.isASingleGrunt', { name: escHtml(this.name) })); return 0; }
    const id = (foundry as any).utils?.randomID?.() ?? `g${Date.now()}`;
    const grid = Number(tok.parent.grid?.size ?? 100);
    const base = tok.toObject();
    const docs = Array.from({ length: left - 1 }, (_v, i) => ({
      ...base, _id: undefined, x: tok.x + ((i % 4) + 1) * grid, y: tok.y + Math.floor(i / 4) * grid,
      name: `${tok.name} ${i + 2}`, delta: { ...(base.delta ?? {}), system: { ...(base.delta?.system ?? {}), grunts: { size: 1, down: 0 } } },
      flags: { ...(base.flags ?? {}), [SYSTEM_ID]: { ...(base.flags?.[SYSTEM_ID] ?? {}), gruntGroup: id } },
    }));
    await tok.parent.createEmbeddedDocuments('Token', docs);
    await tok.update({ name: `${tok.name} 1`, [`flags.${SYSTEM_ID}.gruntGroup`]: id });
    await this.update({ 'system.grunts.size': 1, 'system.grunts.down': 0 });
    await ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor: this }), content: `<p><strong>${escText(this.name)}</strong> ${tx('SR2E.Card.Actor.spreadsOutGruntsOnTheirOwn', { left })}</p>` });
    return left;
  }

  /** Every standing grunt token of the group attacks with the same weapon (its own copy). Returns the attacks made. */
  async groupTokenAttack(weaponName: string, opts: AttackOptions = {}): Promise<number> {
    const g = this.gruntGroup();
    if (!g) return 0;
    let made = 0;
    for (const a of g.standing) {
      const w = [...(a.items ?? [])].find((i: any) => i.type === 'weapon' && i.name === weaponName) ?? (weaponName === 'Unarmed' ? SR2Actor.unarmed() : null);
      if (!w) continue;
      const r = await a.attackWith(w, a === this ? opts : (a as SR2Actor).#ownAttackOptions(w, opts));
      if (r) made++;
    }
    return made;
  }

  /**
   * v0.50.0: a group member's attack measured from its own token: its own range band and distance, and
   * its own cover, light, smoke, prone, barriers and movement (read by itself: AttackOptions.sight left
   * out). The choices made in the dialog (mode, rounds, called shot, pool, ammo) are kept.
   */
  #ownAttackOptions(weapon: any, opts: AttackOptions): AttackOptions {
    const own: AttackOptions = { ...opts };
    delete own.sight;
    delete own.measuredMetres;
    delete own.outOfRange;
    const target: any = opts.targetUuid ? fromUuidSync(opts.targetUuid) : null;
    const melee = Boolean(weapon.system?.melee);
    const ft = SR2Actor.tokenFor(this), tt = SR2Actor.tokenFor(target);
    const m = ft && tt ? measureTokens(ft, tt) : null;
    if (m && !melee) {
      const band = rangeBandForDistance(m.metres, weaponRange(weapon.system, (this.sys.attributes?.strength?.total as number | undefined) ?? 0, weapon.name));
      own.range = band ?? 'extreme';
      own.measuredMetres = m.metres;
      if (!band) own.outOfRange = true;
    }
    const auto = ['partialCover', 'attackerWalking', 'attackerRunning', 'laserSight'];
    own.situational = (opts.situational ?? []).filter((id) => !auto.includes(id));
    try {
      const moved = ft && (game as any).combat?.started ? movedThisTurn(ft) : null;
      const mv = moved == null ? 'none' : movementState(moved, (this.sys.attributes?.quickness?.total as number | undefined) ?? 0);
      if ((!melee || RULES.TN_AUTO.attack.movementInMelee) && mv !== 'none') own.situational.push(mv === 'running' ? 'attackerRunning' : 'attackerWalking');
    } catch { /* no movement */ }
    if (weapon.system?.laserSight && (opts.situational ?? []).includes('laserSight') && laserInRange(m?.metres ?? null)) own.situational.push('laserSight');
    own.modifiers = (opts.modifiers ?? []).filter((x) => !modifierIs(x, 'targetProne', 'Target prone') && !modifierIs(x, 'attackerProne', 'Attacker prone'));
    if (!melee && target) own.barrierArmor = this.attackSight(target, { melee }).barrierArmor;
    return own;
  }

  /**
   * Rally a broken group (RULES.STREET.rally): Leadership (else Charisma +4) vs TN + 1 per grunt down.
   * A success clears "broken" from the group.
   */
  async rally(targetUuid: string, opts: { modifiers?: TargetNumberModifier[] } = {}): Promise<boolean | null> {
    if (this.#exclusiveBlocks()) return null;
    const t: any = await fromUuid(targetUuid);
    if (!t) return null;
    if (!t.isBroken?.()) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.isnTBroken2', { tName: escHtml(t.name) })); return null; }
    if (!(await this.useAction('rally', tx('SR2E.Card.Actor.rallying', { name: t.name })))) return null;
    const r = RULES.STREET.rally;
    const g = t.moraleGroup?.() ?? null;
    // A GM-made group already counts every member's own fallen grunts.
    const down = g?.flagged ? g.down : ((t.system?.grunts?.down as number | undefined) ?? 0) + (g ? g.down : 0);
    const sd = this.#skillDice(this.findSkill(r.skill), false, null, r.attribute as AttributeKey);
    const res = await this.#runTest(tx('SR2E.Card.Actor.rally', { name: t.name, skill: r.skill, sdSuffix: sd.suffix, part: down ? tx('SR2E.Card.Actor.down', { down }) : '' }), sd.dice, { targetNumber: rallyTarget(down), modifiers: [...(opts.modifiers ?? []), ...sd.modifiers] });
    const ok = res.successes > 0;
    if (ok) await t.#setBroken(false, g);
    await ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor: this }), content: `<p>${ok ? `<strong>${tx('SR2E.Card.Actor.rallies', { name: escText(t.name) })}</strong> ${tx('SR2E.Card.Actor.andFightsOn')}` : `<strong>${tx('SR2E.Card.Actor.staysBroken', { name: escText(t.name) })}</strong>`}</p>` });
    return ok;
  }

  /**
   * One sneaker against several observers (v0.44.0): Stealth (else Quickness +4) once, vs the highest
   * observer Intelligence; each observer rolls Perception vs the Stealth rating and notices on more successes.
   * v0.81.0 (D1-7, R2-DOC 3): sneaking is a physical act (`canAct('sneak')`): someone down, or a projecting body,
   * can't choose to sneak. With `watched` (guards looking for intruders, guardsWatch) the watchers still look: such
   * an intruder rolls no Stealth (no successes), so any watcher with a success spots them.
   */
  async sneakPast(observerUuids: string[], opts: { modifiers?: TargetNumberModifier[]; observerModifiers?: TargetNumberModifier[]; whisper?: boolean; useSpecialization?: boolean; watched?: boolean } = {}): Promise<Array<{ name: string; noticed: boolean }>> {
    const helpless = opts.watched ? this.#cannotSneak() : '';
    if (!opts.watched && !this.canAct('sneak')) return [];
    const p = RULES.PERCEPTION;
    const watchers: any[] = [];
    for (const u of observerUuids) { const o: any = await fromUuid(u); if (o && o.uuid !== this.uuid && !(o.id && o.id === (this as any).id && !o.isToken)) watchers.push(o); }
    if (!watchers.length) return [];
    // v0.50.0: the sneaker's own side (penalties, edges and flaws, movement) and each observer's full side.
    const side = this.stealthSide({ useSpecialization: opts.useSpecialization });
    const rating = helpless ? 0 : side.rating;
    const tn = Math.max(...watchers.map((w) => perceptionTargets({ stealthRating: rating, observerAttribute: (w.system?.attributes?.[p.attribute]?.total as number | undefined) ?? 0 }).sneakerTn));
    const rolls: any[] = [];
    const mine = await successTest({ dice: helpless ? 0 : side.dice, targetNumber: tn, modifiers: [...(opts.modifiers ?? []), ...(helpless ? [] : side.modifiers)], roll: foundryRoller(rolls) });
    const out: Array<{ name: string; noticed: boolean }> = [];
    const contest: Contest = { kind: 'sneak', id: SR2Actor.contestId(), actorName: this.name, sides: [
      { name: this.name, uuid: this.uuid as string, label: helpless ? tx('SR2E.Card.Actor.noStealthAgainst', { name: this.name, helpless, count: watchers.length }) : rating > 0 ? tx('SR2E.Card.Actor.sneaksPastVsTheSharpest', { name: this.name, count: watchers.length, skill: p.stealthSkill, rating, suffix: side.suffix ?? '', attribute: cap(p.attribute), tn }) : tx('SR2E.Card.Actor.sneaksPastAttributeVsTheSharpest', { name: this.name, count: watchers.length, stealthAttribute: cap(p.stealthAttribute), attribute: cap(p.attribute), tn }), result: mine }] };
    for (const w of watchers) {
      // v0.81.1 (D1-4): an unconscious, dying, held or projecting (empty-bodied) guard spots nobody.
      const out0 = w instanceof SR2Actor ? w.#cannotPerceive(true) : '';
      if (out0) {
        out.push({ name: w.name, noticed: false });
        contest.sides.push({ name: w.name, uuid: w.uuid, label: w.name, result: null, why: `${w.name} ${out0}` });
        continue;
      }
      // v0.71.0 (R12): the observer resists an invisibility spell on the sneaker first.
      if (typeof w.spotInvisible === 'function') await w.spotInvisible([this]);
      const sight = w.perceptionAgainst ? w.perceptionAgainst(this) : { modifiers: [], blocked: false, why: '' };
      if (sight.blocked) {
        out.push({ name: w.name, noticed: false });
        contest.sides.push({ name: w.name, uuid: w.uuid, label: w.name, result: null, why: sight.why });
        continue;
      }
      const wAttr = (w.system?.attributes?.[p.attribute]?.total as number | undefined) ?? 0;
      // v0.71.0 (R2): the observer's Perception through the shared skill path.
      const pd = w.perceptionDice ? w.perceptionDice() : { dice: wAttr, modifiers: [] };
      const dice = pd.dice;
      const mods = w.previewModifiers ? w.previewModifiers({ modifiers: [...(opts.observerModifiers ?? []), ...pd.modifiers, ...sight.modifiers], sightHandled: true }) : (w.woundModifiers?.() ?? []);
      const theirs = await successTest({ dice, targetNumber: perceptionTargets({ stealthRating: rating, observerAttribute: wAttr }).observerTn, modifiers: mods, roll: foundryRoller(rolls) });
      const noticed = opposedOutcome(theirs.successes, mine.successes).winner === 'initiator';
      out.push({ name: w.name, noticed });
      contest.sides.push({ name: w.name, uuid: w.uuid, label: w.name, result: theirs });
    }
    const gms = [...((game as any).users ?? [])].filter((u: any) => u.isGM).map((u: any) => u.id);
    await ChatMessage.create({
      speaker: ChatMessage.getSpeaker({ actor: this }), rolls, ...(opts.whisper ? { whisper: gms, blind: true } : {}),
      content: SR2Actor.contestContent(contest), flags: { [SYSTEM_ID]: { contest } },
    });
    return out;
  }

  /**
   * v0.81.1 (D1-4): why this actor can't perceive anything right now ('is unconscious'), or ''. The projecting case
   * (`withAstral`) only for a sneak's watchers: a projecting magician perceives astrally. The same switches.
   */
  #cannotPerceive(withAstral = false): string {
    const status = String(this.sys.derived?.status ?? '');
    if (RULES.CONDITIONS.blockActions && incapacitated(status as any)) return tx('SR2E.Card.Actor.is4', { status });
    // Round 2 (V-DOC 12): a paralysed (or held) character is awake and still sees and hears; only the unconscious,
    // the dying and (for a sneak's watchers) an empty projecting body perceive nothing.
    if (withAstral && RULES.FIXES_V70.astralBlocksPhysical) {
      const why = this.astralOnly();
      if (why && !(this.isManifesting() && !RULES.MAGIC_V56.manifest.blocksPhysical)) return why;
    }
    return '';
  }

  /** v0.81.0 (D1-7): why this actor can't sneak right now ('is unconscious', 'is projecting (the body is empty)'), or '' (no warning). */
  #cannotSneak(): string {
    const status = String(this.sys.derived?.status ?? '');
    if (RULES.CONDITIONS.blockActions && incapacitated(status as any)) return tx('SR2E.Text.Actor.isStatus', { status });
    if (RULES.FIXES_V70.astralBlocksPhysical) {
      const why = this.astralOnly();
      if (why && !(this.isManifesting() && !RULES.MAGIC_V56.manifest.blocksPhysical)) return why;
    }
    const held = this.helplessStatus();
    return held ? tx('SR2E.Text.Actor.isStatus', { status: held }) : '';
  }

  /**
   * Climb, swim or jump (RULES.STREET.athletics): Athletics (else the attribute at +4) vs the condition's
   * TN. Successes are distance; no successes climbing is a fall, swimming means going under.
   */
  async athleticsTest(kind: AthleticsKind, opts: { condition?: string; running?: boolean; modifiers?: TargetNumberModifier[]; weather?: boolean } = {}): Promise<{ successes: number; metres: number } | null> {
    if (!this.canAct('athletics')) return null;
    if (!(await this.useAction('athletics', kind))) return null;
    const a = RULES.STREET.athletics;
    const t = athleticsTn(kind, opts.condition ?? '');
    const sd = this.#skillDice(this.findSkill(a.skill), false, null, a.attribute as AttributeKey);
    const verb = kind === 'climb' ? tx('SR2E.Card.Actor.climbing') : kind === 'swim' ? tx('SR2E.Card.Actor.swimming') : opts.running ? tx('SR2E.Card.Actor.runningJump') : tx('SR2E.Card.Actor.standingJump');
    const r = await this.#runTest(`${verb} (${t.label}): ${a.skill}${sd.suffix}`, sd.dice, { targetNumber: t.tn, modifiers: [...(opts.modifiers ?? []), ...sd.modifiers] });
    // v0.48.0: bad weather shortens the distance (RULES.HEALTH.weather movement).
    const wf = opts.weather === false ? 1 : movementInWeather({ walk: 1, run: 1 }, this.weatherHere()).factor;
    // v0.80.0 (RULES.URR_V80.hsAthletics 'urr'): distances by Fitness ((Strength + Quickness) ÷ 2) and Quickness.
    const urrMetres = athleticsDistanceUrr(kind, r.successes, Boolean(opts.running), { strength: Number(this.sys.attributes.strength.total), quickness: Number(this.sys.attributes.quickness.total), runMultiplier: Number(RULES.METATYPES.types[String(this.sys.metatype ?? 'human')]?.run ?? RULES.COMBAT.movement.run) });
    const metres = Math.floor((urrMetres ?? athleticsDistance(kind, r.successes, Boolean(opts.running))) * wf * 2) / 2;
    const what = metres > 0 ? `${kind === 'jump' ? tx('SR2E.Card.Actor.jumps') : kind === 'climb' ? tx('SR2E.Card.Actor.climbs') : tx('SR2E.Card.Actor.swims')} <strong>${metres} m</strong>${wf !== 1 ? tx('SR2E.Card.Actor.weather', { wf }) : ''}.`
      : kind === 'climb' ? `<strong>${tx('SR2E.Card.Actor.noProgress')}</strong>` + (r.botch ? tx('SR2E.Card.Actor.aFallHazardFalling') : '.') : kind === 'swim' ? `<strong>${tx('SR2E.Card.Actor.goesUnder')}</strong>${tx('SR2E.Card.Actor.drowningStartsHazardDrowning')}` : `<strong>${tx('SR2E.Card.Actor.fallsShort')}</strong>`;
    await ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor: this }), content: `<p>${escText(this.name)}: ${what}</p>` });
    return { successes: r.successes, metres };
  }

  /**
   * Fill the sheet from the build (v0.44.0): metatype, base attributes, Magic, cash left after gear, a
   * lifestyle paid ahead and the free contacts (RULES.STREET.builder). Returns what was set.
   */
  async applyBuild(b: { priorities: Partial<Record<string, string>>; metatype?: string; magic?: 'none' | 'full' | 'adept' | 'aspected'; attributes?: Record<string, number>; gearCost?: number; skills?: BuilderSkill[]; gear?: BuilderGear[]; outright?: boolean }): Promise<{ nuyen: number; lifestyle: string; contacts: number; skills: number; gear: number }> {
    const magic = b.magic ?? 'none';
    const plan0 = buildPlan({ resources: b.priorities['resources'], magic, gearCost: b.gearCost ?? 0 });
    // v0.61.0: a lifestyle bought outright (STREET_V61.creation.lifestyleOutright), and what's left of the cash (leftoverCash).
    const want = b.outright ? lifestyleOutright({ lifestyle: plan0.lifestyle }) : null;
    // Only when the cash covers it (else the usual months, and a warning).
    const extraCost = want ? Math.max(0, want.cost - (plan0.lifestyleCost ?? 0)) : 0;
    const out = want && extraCost <= plan0.nuyen ? want : null;
    if (want && !out) ui.notifications?.warn?.(tx('SR2E.Notify.Actor.buyingTheLifestyleOutrightCostsOnly', { wantCost: want.cost.toLocaleString(), value: (plan0.nuyen + (plan0.lifestyleCost ?? 0)).toLocaleString() }));
    const cash = Math.max(0, plan0.nuyen - (out ? extraCost : 0));
    const left = leftoverCash(cash);
    const plan = { ...plan0, nuyen: left.kept, lifestyleMonths: out ? out.months : plan0.lifestyleMonths };
    const now = sysNow();
    const days = RULES.UPKEEP.monthDays * plan.lifestyleMonths;
    const up: Record<string, unknown> = {
      'system.nuyen': plan.nuyen,
      'system.lifestyle.level': plan.lifestyle,
      'system.lifestyle.paidUntil': now + days * 86400,
      'system.magic': plan.magic,
      // v0.73.0 (O31): bought outright = owned for good (RULES.CHARACTERS_V73.lifestyle.outrightPermanent).
      ...creationLifestylePatch({ outright: Boolean(out), months: plan.lifestyleMonths, now }),
    };
    if (b.metatype) up['system.metatype'] = b.metatype;
    const trad = String(this.sys.tradition ?? 'none');
    if (magic === 'adept') up['system.tradition'] = 'adept';
    else if (magic === 'full' && !['hermetic', 'shamanic'].includes(trad)) up['system.tradition'] = 'hermetic';
    else if (magic === 'none') up['system.tradition'] = 'none';
    for (const [k, v] of Object.entries(b.attributes ?? {})) if (ATTRIBUTE_KEYS.includes(k as AttributeKey)) up[`system.attributes.${k}.base`] = Math.max(1, Math.floor(Number(v) || 1));
    const have = [...((this.sys.contacts as any[] | undefined) ?? [])];
    const need = Math.max(0, plan.contacts.count - have.length);
    for (let i = 0; i < need; i++) have.push({ id: (foundry as any).utils?.randomID?.() ?? `c${Date.now()}${i}`, name: `Contact ${have.length + 1}`, level: plan.contacts.level, role: '', notes: tx('SR2E.Text.Actor.fromCharacterCreation'), loyalty: 1, skills: '', fee: 0 });
    up['system.contacts'] = have;
    await this.update(up);
    // v0.75.0: written whole (setFlag merges, so a column the new build leaves out kept the old one).
    await replaceFlag(this, 'build', { ...(b.priorities ?? {}) });
    // v0.49.0: skills (new ones made, listed ones re-rated) and gear from the builder's lists.
    const made = await this.#applyBuildItems(b.skills ?? [], b.gear ?? []);
    const life = lifestyleOf(plan.lifestyle).label;
    await ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor: this }), content: `<p><strong>${escText(this.name)}</strong> ${tx('SR2E.Card.Actor.isBuiltCashLifestyle', { metatype: escText(b.metatype ?? this.sys.metatype), part: magic === 'none' ? tx('SR2E.Card.Actor.mundane') : tx('SR2E.Card.Actor.magic2', { magic, planMagic: plan.magic }), planNuyen: plan.nuyen.toLocaleString(), part2: left.lost ? ` (${escText(left.note)})` : '', life: escText(life), part3: out ? (RULES.CHARACTERS_V73.lifestyle.outrightPermanent ? tx('SR2E.Card.Actor.boughtOutrightOwnedForGood', { outCost: out.cost.toLocaleString() }) : tx('SR2E.Card.Actor.boughtOutrightMonths', { planLifestyleMonths: plan.lifestyleMonths, outCost: out.cost.toLocaleString() })) : tCount(plan.lifestyleMonths, 'SR2E.Card.Actor.forMonths'), part4: need ? tCount(need, 'SR2E.Card.Actor.newContactsToName') : '', part5: made.skills ? `, ${escText(plural(made.skills, 'skill'))}` : '', part6: made.gear ? tCount(made.gear, 'SR2E.Card.Actor.piecesOfGear') : '' })}</p>` });
    return { nuyen: plan.nuyen, lifestyle: plan.lifestyle, contacts: need, skills: made.skills, gear: made.gear };
  }

  /** The builder's skills and gear onto the sheet: a skill already there by name is re-rated; gear is added. */
  async #applyBuildItems(skills: BuilderSkill[], gear: BuilderGear[]): Promise<{ skills: number; gear: number }> {
    const creates: any[] = [];
    const updates: any[] = [];
    const have = (n: string) => [...this.items].find((i: any) => i.type === 'skill' && String(i.name).trim().toLowerCase() === n.trim().toLowerCase());
    for (const sk of skills) {
      const system: Record<string, unknown> = { rating: Math.max(0, Math.floor(sk.rating)), kind: sk.kind, ...(sk.specialization ? { specialization: sk.specialization, specializationRating: sk.specializationRating ?? sk.rating + 2 } : {}) };
      const ex: any = have(sk.name);
      if (ex) updates.push({ _id: ex.id, system });
      else creates.push({ name: sk.name, type: 'skill', system: { ...system, attribute: sk.kind === 'active' || sk.kind === 'buildRepair' ? guessSkillAttribute(sk.name) : 'intelligence' } });
    }
    for (const g of gear) {
      const n = g.type === 'gear' ? 1 : Math.max(1, g.qty);
      for (let k = 0; k < n; k++) creates.push({ name: g.name, type: g.type, system: { ...structuredClone(g.system), cost: g.cost } });
    }
    if (creates.length) await this.createEmbeddedDocuments('Item', creates);
    if (updates.length) await this.updateEmbeddedDocuments('Item', updates);
    return { skills: skills.length, gear: gear.reduce((m, g) => m + (g.type === 'gear' ? 1 : Math.max(1, g.qty)), 0) };
  }

  // ---------------------------------------------------------------- Edges and flaws with Karma (v0.49.0)

  /** Gain an edge after creation for Good Karma (RULES.STREET.qualities.karma). */
  async gainEdge(q: { name: string; points: number; target?: string; tn?: number; notes?: string }): Promise<boolean> {
    if (!(Math.floor(q.points || 0) > 0)) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.anEdgeIsWorthAtLeast')); return false; }
    const have = qualityPoints((this.sys.qualities as any[] | undefined) ?? []).edges;
    if (RULES.STREET.qualities.enabled && have + Math.floor(q.points) > RULES.STREET.qualities.maxEdges) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.wouldHavePointsOfEdgesAt', { name: escHtml(this.name), value: have + Math.floor(q.points), qualitiesMaxEdges: RULES.STREET.qualities.maxEdges })); return false; }
    const cost = qualityKarmaCost('edge', q.points);
    const good = Number(this.sys.karma?.good ?? 0);
    if (good < cost) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.hasGoodKarmaPointsCosts', { name: escHtml(this.name), good, qName: escHtml(q.name), qPoints: q.points, cost })); return false; }
    if (approvalNeeded(this)) { await fileRequest(this, { kind: 'edge', label: tx('SR2E.Text.Actor.edgePoints', { name: q.name, points: Math.floor(q.points) }), karma: cost, data: { method: 'gainEdge', args: [{ ...q }] } }); return false; }
    const list = [...((this.sys.qualities as any[] | undefined) ?? []), { id: SR2Actor.#newId(), name: q.name || 'Edge', kind: 'edge', points: Math.max(0, Math.floor(q.points || 0)), target: q.target ?? '', tn: Math.floor(q.tn ?? 0), notes: q.notes ?? '' }];
    await this.update({ 'system.qualities': list, 'system.karma.good': good - cost, 'system.ledger': this.#ledgerWith({ kind: 'karma', amount: -cost, reason: tx('SR2E.Text.Actor.edge', { name: q.name }) }) });
    await ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor: this }), content: `<p><strong>${escText(this.name)}</strong> ${tx('SR2E.Card.Actor.gainsTheEdge')} <strong>${escText(q.name)}</strong> ${tx('SR2E.Card.Actor.forKarma', { cost })}</p>` });
    return true;
  }

  /**
   * v0.82.1 (owner): an edge or flaw added, changed or deleted by hand (the sheet's +, the name and the trash). Free in
   * the creation wizard or for the GM; after creation, with the approval queue on, it goes to the GM like any other
   * change to a character (a free edge or a deleted flaw would skip what the rules charge for them).
   */
  static cleanQuality(q: any): { name: string; kind: 'edge' | 'flaw'; points: number; target: string; tn: number; notes: string } {
    const o = q && typeof q === 'object' ? q : {};
    return {
      name: String(o.name ?? '').trim().slice(0, 100) || 'Unnamed',
      kind: o.kind === 'flaw' ? 'flaw' : 'edge',
      points: Math.max(0, Math.min(20, Math.floor(Number(o.points) || 0))),
      target: String(o.target ?? '').trim().slice(0, 100),
      tn: Math.max(-20, Math.min(20, Math.floor(Number(o.tn) || 0))),
      notes: String(o.notes ?? '').slice(0, 500),
    };
  }

  /** v0.82.1: add an edge or flaw by hand (no Karma); after creation with the queue on, a request to the GM. */
  async addQuality(q: any): Promise<boolean> {
    const c = SR2Actor.cleanQuality(q);
    if (approvalNeeded(this)) { await fileRequest(this, { kind: 'quality', label: c.kind === 'flaw' ? tx('SR2E.Text.Actor.addTheFlawPointsNoKarma', { name: c.name, points: c.points }) : tx('SR2E.Text.Actor.addTheEdgePointsNoKarma', { name: c.name, points: c.points }), data: { method: 'addQuality', args: [c] } }); return false; }
    await this.update({ 'system.qualities': [...((this.sys.qualities as any[] | undefined) ?? []), { id: SR2Actor.#newId(), ...c }] });
    return true;
  }

  /** v0.82.1: change an edge or flaw by hand; after creation with the queue on, a request to the GM. */
  async editQuality(id: string, q: any): Promise<boolean> {
    const list = [...((this.sys.qualities as any[] | undefined) ?? [])].map((x: any) => ({ ...x }));
    const i = list.findIndex((x: any) => x.id === id);
    if (i < 0) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.thatEdgeOrFlawIsGone')); return false; }
    const c = SR2Actor.cleanQuality(q);
    if (approvalNeeded(this)) { await fileRequest(this, { kind: 'quality', label: c.kind === 'flaw' ? tx('SR2E.Text.Actor.changeToFlawPoints', { from: list[i].name, name: c.name, points: c.points }) : tx('SR2E.Text.Actor.changeToEdgePoints', { from: list[i].name, name: c.name, points: c.points }), data: { method: 'editQuality', args: [id, c] } }); return false; }
    list[i] = { ...list[i], ...c };
    await this.update({ 'system.qualities': list });
    return true;
  }

  /** v0.82.1: delete an edge or flaw by hand (buying a flaw off is buyOffFlaw); after creation with the queue on, a request to the GM. */
  async removeQuality(id: string): Promise<boolean> {
    const list = (this.sys.qualities as any[] | undefined) ?? [];
    const q = list.find((x: any) => x.id === id);
    if (!q) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.thatEdgeOrFlawIsGone')); return false; }
    if (approvalNeeded(this)) { await fileRequest(this, { kind: 'quality', label: q.kind === 'flaw' ? tx('SR2E.Text.Actor.removeTheFlawNoKarma', { name: String(q.name ?? '') }) : tx('SR2E.Text.Actor.removeTheEdgeNoKarma', { name: String(q.name ?? '') }), data: { method: 'removeQuality', args: [id] } }); return false; }
    await this.update({ 'system.qualities': list.filter((x: any) => x.id !== id) });
    return true;
  }

  /** Buy off a flaw for Good Karma. */
  async buyOffFlaw(id: string): Promise<boolean> {
    const list = [...((this.sys.qualities as any[] | undefined) ?? [])];
    const q = list.find((x: any) => x.id === id);
    if (!q || q.kind !== 'flaw') { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.thatFlawIsGone')); return false; }
    const cost = qualityKarmaCost('flaw', q.points);
    const good = Number(this.sys.karma?.good ?? 0);
    if (good < cost) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.hasGoodKarmaBuyingOffCosts', { name: escHtml(this.name), good, qName: escHtml(q.name), cost })); return false; }
    if (approvalNeeded(this)) { await fileRequest(this, { kind: 'buyOff', label: tx('SR2E.Text.Actor.buyOff', { name: q.name }), karma: cost, data: { method: 'buyOffFlaw', args: [id] } }); return false; }
    await this.update({ 'system.qualities': list.filter((x: any) => x.id !== id), 'system.karma.good': good - cost, 'system.ledger': this.#ledgerWith({ kind: 'karma', amount: -cost, reason: tx('SR2E.Text.Actor.boughtOff', { name: q.name }) }) });
    await ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor: this }), content: `<p><strong>${escText(this.name)}</strong> ${tx('SR2E.Card.Actor.buysOffTheFlaw')} <strong>${escText(q.name)}</strong> ${tx('SR2E.Card.Actor.forKarma', { cost })}</p>` });
    return true;
  }

  /** v0.50.0: Street Cred on haggling, fencing and finding gear, like other social tests (RULES.TN_AUTO.social.credOnDeals). */
  #dealCred(): TargetNumberModifier[] {
    return RULES.TN_AUTO.social.credOnDeals ? reputationModifiers(this.sys.derived?.streetCred ?? 0) : [];
  }

  /**
   * Haggle over a found item's price (RULES.STREET.haggle): Negotiation (else Charisma +4) opposed by the
   * seller; each net success moves the price. Posts a new Buy card. Returns the new price.
   */
  async haggle(buyIn: { itemId?: string; shop?: string; price: number; name: string; qty?: number; hours?: number }, opts: { modifiers?: TargetNumberModifier[] } = {}): Promise<number | null> {
    if (this.#exclusiveBlocks()) return null;
    // v0.81.0 (SEC1-6): from a card: the price haggled over is the item's own street price when it is on this actor
    // (else the card's, bounded: buyItem, which pays, checks the price against the item again).
    // v0.91.0: a shop find carries the shop key instead: the price is the entry's own, read again from its source.
    const shopKey = typeof (buyIn as any)?.shop === 'string' ? String((buyIn as any).shop) : '';
    const shopThing = shopKey ? await resolveShopKey(shopKey) : null;
    if (shopKey && !shopThing) { ui.notifications?.warn?.(tx('SR2E.Notify.Shop.notInTheShop', { name: escHtml(String(buyIn?.name ?? '').slice(0, 60)) })); return null; }
    const item: any = shopThing ? null : [...this.items].find((i: any) => i.id === buyIn?.itemId);
    const qty = shopThing ? copiesOrQuantity(shopThing.type, safeInt(buyIn?.qty ?? 1, 1, 10000, 1)) : safeInt(buyIn?.qty ?? 1, 1, 10000, 1);
    const hours = Math.max(0, Math.min(1e6, Number(buyIn?.hours) || 0));
    const buy = { itemId: String(buyIn?.itemId ?? ''), price: shopThing ? shopListPrice(shopThing, qty, this.type) : item ? SR2Actor.#listPrice(item, qty) : safeInt(buyIn?.price, 0, 1e9, 0), name: String(shopThing?.name ?? item?.name ?? buyIn?.name ?? 'an item').slice(0, 200), qty, ...(hours ? { hours } : {}) };
    const h = RULES.STREET.haggle;
    const sd = this.#skillDice(this.findSkill(h.skill), false, null, h.attribute as AttributeKey);
    const rolls: any[] = [];
    const mine = await successTest({ dice: sd.dice, targetNumber: h.tn, modifiers: this.#testModifiers({ modifiers: [...(opts.modifiers ?? []), ...sd.modifiers, ...this.#dealCred()] }), roll: foundryRoller(rolls) });
    // v0.80.0 (RULES.URR_V80.coreHaggleTn 'intelligence'): h.tn in the book.
    const theirs = await successTest({ dice: h.sellerDice, targetNumber: urrCoreHaggleSellerTn(Number(this.sys.attributes?.intelligence?.total ?? 0)), roll: foundryRoller(rolls) });
    const net = mine.successes - theirs.successes;
    const p = haggledPrice(buy.price, net);
    // v0.71.0 (R1): a contest card, so Karma Pool and the GM's TN change work on it.
    const contest: Contest = { kind: 'haggle', id: SR2Actor.contestId(), actorName: this.name, sides: [
      { name: this.name, uuid: this.uuid as string, label: tx('SR2E.Card.Actor.hagglesOver', { name: this.name, buyName: buy.name, skill: h.skill, suffix: sd.suffix }), result: mine },
      { name: tx('SR2E.Card.Actor.theSeller'), label: tx('SR2E.Card.Actor.theSellerDice', { dice: h.sellerDice }), result: theirs },
    ], deal: { price: buy.price, buy: { actorUuid: this.uuid, ...(shopThing ? { shop: shopThing.key } : { itemId: buy.itemId }), price: buy.price, name: buy.name, qty: buy.qty ?? 1, ...(buy.hours ? { hours: buy.hours } : {}) } } };
    await ChatMessage.create({
      speaker: ChatMessage.getSpeaker({ actor: this }), rolls,
      content: SR2Actor.contestContent(contest),
      flags: { [SYSTEM_ID]: { contest, ...SR2Actor.contestFlags(contest) } },
    });
    return p.price;
  }

  /**
   * Fence an item (RULES.STREET.fence): Negotiation (else Charisma +4) opposed by the fence; the fence
   * pays a share of the street price. Posts a card with a Sell button. Returns the offer.
   */
  async fence(itemId: string, opts: { modifiers?: TargetNumberModifier[] } = {}): Promise<number | null> {
    if (this.#exclusiveBlocks()) return null;
    const item: any = this.items.get?.(itemId) ?? [...this.items].find((i: any) => i.id === itemId);
    if (!item) return null;
    const value = itemPrice({ cost: item.type === 'cyberware' ? wareCost(item.system) : (item.system.cost ?? 0), streetIndex: item.system.streetIndex ?? 1, quantity: 1 });
    if (value <= 0) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.hasNoCostSetSoA', { itemName: escHtml(item.name) })); return null; }
    // v0.49.0: hot goods sell for less, and the hottest not at all (RULES.STREET.heat).
    const heat = RULES.STREET.heat.enabled ? currentHeat(item.system.heat ?? 0, item.system.heatAt ?? -1, sysNow()) : 0;
    if (heat > RULES.STREET.heat.refuseAbove) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.isTooHotHeatNoFence', { itemName: escHtml(item.name), heat })); return null; }
    const f = RULES.STREET.fence;
    const sd = this.#skillDice(this.findSkill(f.skill), false, null, f.attribute as AttributeKey);
    const rolls: any[] = [];
    const mine = await successTest({ dice: sd.dice, targetNumber: f.tn, modifiers: this.#testModifiers({ modifiers: [...(opts.modifiers ?? []), ...sd.modifiers, ...this.#dealCred()] }), roll: foundryRoller(rolls) });
    const theirs = await successTest({ dice: f.fenceDice, targetNumber: f.tn, roll: foundryRoller(rolls) });
    const p = hotFencePrice(value, mine.successes - theirs.successes, heat);
    // v0.71.0 (R1): a contest card (Karma Pool, the GM's TN change); a share eaten whole by the heat: the fence passes.
    const contest: Contest = { kind: 'fence', id: SR2Actor.contestId(), actorName: this.name, sides: [
      { name: this.name, uuid: this.uuid as string, label: heat ? tx('SR2E.Card.Actor.fencesStreetPriceHeat', { name: this.name, itemName: item.name, value: value.toLocaleString(), heat, skill: f.skill, suffix: sd.suffix }) : tx('SR2E.Card.Actor.fencesStreetPrice', { name: this.name, itemName: item.name, value: value.toLocaleString(), skill: f.skill, suffix: sd.suffix }), result: mine },
      { name: tx('SR2E.Card.Actor.theFence'), label: tx('SR2E.Card.Actor.theFenceDice', { dice: f.fenceDice }), result: theirs },
    ], deal: { value, heat, sell: { actorUuid: this.uuid, itemId, price: 0, name: item.name, heat } } };
    await ChatMessage.create({
      speaker: ChatMessage.getSpeaker({ actor: this }), rolls,
      content: SR2Actor.contestContent(contest),
      flags: { [SYSTEM_ID]: { contest, ...SR2Actor.contestFlags(contest) } },
    });
    return Math.max(0, p.price);
  }

  /** Sell an item to a fence: one off the quantity (or the item goes), the nuyen in. Hot goods may be traced (v0.49.0). */
  async sellItem(itemId: string, priceIn: number, heatIn = 0): Promise<boolean> {
    const item: any = this.items.get?.(itemId) ?? [...this.items].find((i: any) => i.id === itemId);
    if (!item) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.thatItemIsGone')); return false; }
    // v0.81.0 (SEC1-6): the offer comes from a card: never below nothing, never more than the best a fence could pay
    // for this item (no Heat cut); the Heat that may trace it is the card's, bounded.
    const value = itemPrice({ cost: item.type === 'cyberware' ? wareCost(item.system) : (item.system.cost ?? 0), streetIndex: item.system.streetIndex ?? 1, quantity: 1 });
    const heat = safeInt(heatIn, 0, 30, 0);
    const price = Math.min(safeInt(priceIn, 0, Number.MAX_SAFE_INTEGER, 0), Math.max(0, hotFencePrice(value, 1000, 0).price));
    const h = RULES.STREET.heat;
    if (h.enabled && h.traceRoll && heat > 0) {
      const rolls: any[] = [];
      const r = await successTest({ dice: heat, targetNumber: h.traceTn, roll: foundryRoller(rolls) });
      const gms = [...((game as any).users ?? [])].filter((u: any) => u.isGM).map((u: any) => u.id);
      await ChatMessage.create({ speaker: { alias: tx('SR2E.Card.Actor.heat') }, whisper: gms, blind: true, rolls,
        content: `<p><em>${tx('SR2E.Card.Actor.gmOnly')}</em></p>${describeResult(tx('SR2E.Card.Actor.sHeatVs', { itemName: item.name, heat, traceTn: h.traceTn }), r)}<p>${r.successes > 0 ? `<strong>${tx('SR2E.Card.Actor.wordGetsAround')}</strong> ${tx('SR2E.Card.Actor.someoneIsAskingWhoSold', { itemName: escText(item.name), plural: escText(plural(r.successes, 'success')) })}` : tx('SR2E.Card.Actor.theSaleGoesUnnoticed')}</p>` });
    }
    const q = Number(item.system.quantity ?? 1);
    if (item.type === 'gear' && q > 1) await item.update({ 'system.quantity': q - 1 });
    else await item.delete?.();
    await this.adjustNuyen(Math.max(0, Math.floor(price)), tx('SR2E.Text.Actor.soldToAFence', { name: item.name }));
    await ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor: this }), content: `<p><strong>${escText(this.name)}</strong> ${tx('SR2E.Card.Actor.sellsFor', { itemName: escText(item.name), price: Math.floor(price).toLocaleString() })}</p>` });
    return true;
  }

  /** A grunt group attacks as one: every standing grunt makes the same attack. Returns the attacks made. */
  async gruntAttack(weapon: any, opts: AttackOptions = {}): Promise<number> {
    const n = gruntsStanding(this.sys.grunts?.size ?? 1, this.sys.grunts?.down ?? 0);
    let made = 0;
    for (let i = 0; i < n; i++) {
      const r = await this.attackWith(weapon, { ...opts, note: opts.note ? tx('SR2E.Card.Actor.noteGruntOf', { note: opts.note, i: i + 1, n }) : tx('SR2E.Card.Actor.gruntOf', { i: i + 1, n }) });
      if (r) made++;
      else break;
    }
    return made;
  }

  /** Morale: Professional Rating dice vs a TN that rises with casualties; no successes = the group breaks. */
  async moraleTest(opts: { modifiers?: TargetNumberModifier[] } = {}): Promise<{ broken: boolean } | null> {
    // Grunts on separate tokens (v0.44.0): the group's fallen tokens count as casualties.
    // v0.49.0: a mixed group tests once, on RULES.MORALE.mixed of its standing members' ratings.
    const group = this.moraleGroup();
    const own = (this.sys.professionalRating as number | undefined) ?? 0;
    const pr = group?.mixed ? mixedMoraleRating((group.standing.length ? group.standing : group.actors).map((a: any) => Number(a.system?.professionalRating ?? 0)), own) : own;
    const down = group?.flagged ? group.down : ((this.sys.grunts?.down as number | undefined) ?? 0) + (group ? group.down : 0);
    const hurt = (this.sys.monitor?.physical ?? 0) >= RULES.BOXES_PER_LEVEL.S || (this.sys.monitor?.stun ?? 0) >= RULES.BOXES_PER_LEVEL.S;
    const rolls: any[] = [];
    const r = await successTest({ dice: pr, targetNumber: moraleTarget({ casualties: down, hurt }), modifiers: opts.modifiers ?? [], roll: foundryRoller(rolls) });
    const broken = moraleBroken(r.successes);
    // A broken group stays broken until rallied (v0.44.0). v0.81.0 (D1-2): so a passed test doesn't mend it.
    const wasBroken = this.isBroken();
    if (broken) await this.#setBroken(true, group);
    const who = escText(this.name);
    await ChatMessage.create({
      speaker: ChatMessage.getSpeaker({ actor: this }),
      content: `${describeResult((group?.mixed ? tx('SR2E.Card.Actor.moraleGroup', { name: this.name, actorsLength: group.actors.length, moraleMixed: RULES.MORALE.mixed, pr, part2: down ? tx('SR2E.Card.Actor.down2', { down }) : '', part3: hurt ? tx('SR2E.Card.Actor.badlyHurt') : '' }) : tx('SR2E.Card.Actor.moraleOne', { name: this.name, pr, part2: down ? tx('SR2E.Card.Actor.down2', { down }) : '', part3: hurt ? tx('SR2E.Card.Actor.badlyHurt') : '' })), r)}<p>${broken ? `<strong>${tx('SR2E.Card.Actor.breaks', { who })}</strong>${tx('SR2E.Card.Actor.theyFleeOrSurrender')}` : wasBroken ? `<strong>${tx('SR2E.Card.Actor.isStillBroken2', { who })}</strong> ${tx('SR2E.Card.Actor.untilRallied')}` : `<strong>${tx('SR2E.Card.Actor.holds', { who })}</strong>`}</p>`,
      rolls,
    });
    return { broken };
  }

  // ---------------------------------------------------------------- Upkeep (v0.33.0): Karma, nuyen, lifestyle, contacts, buying

  /** The ledger with one more entry (newest last, at most RULES.UPKEEP.ledgerMax). */
  #ledgerWith(...entries: Array<{ kind: 'karma' | 'nuyen' | 'pool'; amount: number; reason: string }>): any[] {
    const t = sysNow();
    const list = [...((this.sys.ledger as any[] | undefined) ?? []), ...entries.map((e) => ({ t, ...e }))];
    return list.slice(-RULES.UPKEEP.ledgerMax);
  }

  /** Award Karma: some may go into the Karma Pool (every 10 earned, 20 for metahumans). */
  async awardKarma(amount: number, reason = ''): Promise<{ good: number; pool: number } | null> {
    const n = Math.floor(Number(amount) || 0);
    if (n <= 0) return null;
    const k = this.sys.karma ?? {};
    const a = karmaAward({ careerBefore: k.career ?? 0, amount: n, metahuman: (this.sys.metatype ?? 'human') !== 'human' });
    await this.update({
      'system.karma.good': (k.good ?? 0) + a.good,
      'system.karma.pool': (k.pool ?? 0) + a.pool,
      'system.karma.career': a.career,
      'system.ledger': this.#ledgerWith({ kind: 'karma', amount: a.good, reason: reason || tx('SR2E.Text.Actor.karmaAward') }, ...(a.pool ? [{ kind: 'pool' as const, amount: a.pool, reason: tx('SR2E.Text.Actor.karmaPoolEarned', { pool: a.pool, career: a.career }) }] : [])),
    });
    return { good: a.good, pool: a.pool };
  }

  /** Earn (+) or spend (−) nuyen, with a ledger entry. Refuses to go below zero. */
  async adjustNuyen(amount: number, reason = ''): Promise<boolean> {
    const n = Math.round(Number(amount) || 0);
    // v0.81.0 (SEC2-8): never Infinity or a number past what a ledger can hold.
    if (!n || !Number.isSafeInteger(n)) return false;
    const have = (this.sys.nuyen as number | undefined) ?? 0;
    if (have + n < 0) { ui.notifications?.warn(tx('SR2E.Notify.Actor.hasOnlyNeeds', { name: escHtml(this.name), have: have.toLocaleString(), value: (-n).toLocaleString() })); return false; }
    await this.update({ 'system.nuyen': have + n, 'system.ledger': this.#ledgerWith({ kind: 'nuyen', amount: n, reason: reason || (n > 0 ? 'Earned' : 'Spent') }) });
    return true;
  }

  /** v0.63.0: spend Good Karma (learning a skill or spell from the Add window), with a ledger line; refuses when short. */
  async spendKarma(amount: number, reason = ''): Promise<boolean> {
    const n = Math.floor(Number(amount) || 0);
    if (n <= 0) return true;
    const have = Number(this.sys.karma?.good ?? 0);
    if (have < n) { ui.notifications?.warn(tx('SR2E.Notify.Actor.hasGoodKarmaNeeds', { name: escHtml(this.name), have, n })); return false; }
    await this.update({ 'system.karma.good': have - n, 'system.ledger': this.#ledgerWith({ kind: 'karma', amount: -n, reason: reason || tx('SR2E.Text.Actor.karmaSpent') }) });
    return true;
  }

  /** The lifestyle, its monthly cost and the days left (negative: overdue; null: never paid). */
  lifestyleStatus(): { id: string; label: string; cost: number; days: number | null; permanent: boolean } {
    const l = lifestyleOf(this.sys.lifestyle?.level ?? 'low');
    // v0.73.0 (O31): a lifestyle owned outright never lapses (RULES.CHARACTERS_V73.lifestyle).
    const st = lifestyleStanding({ paidUntil: this.sys.lifestyle?.paidUntil ?? -1, now: sysNow(), outright: Boolean(this.sys.lifestyle?.outright) });
    return { ...l, days: st.days, permanent: st.permanent };
  }

  /**
   * v0.49.0: the landlord moves an overdue tenant down a lifestyle (or the GM does, from the card).
   * The new lifestyle starts unpaid from now.
   */
  async moveLifestyleDown(reason = tx('SR2E.Card.Actor.rentOverdue')): Promise<string> {
    const from = String(this.sys.lifestyle?.level ?? 'low');
    const to = lifestyleDown(from);
    if (to === from) return from;
    await this.update({ 'system.lifestyle.level': to, 'system.lifestyle.paidUntil': sysNow() });
    await ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor: this }), content: `<p><strong>${escText(this.name)}</strong> ${tx('SR2E.Card.Actor.movesDownFromTo', { label: escText(lifestyleOf(from).label) })} <strong>${escText(lifestyleOf(to).label)}</strong> ${tx('SR2E.Card.Actor.lifestyle', { reason: escText(reason) })}</p>` });
    return to;
  }

  /** v0.49.0 (GM tick): an overdue lifestyle past the grace days, once per unpaid date. */
  static async #lifestyleTick(a: any): Promise<void> {
    if (a.type !== 'character' || !a.hasPlayerOwner) return;
    const st = a.lifestyleStatus?.();
    const level = String(a.system?.lifestyle?.level ?? 'low');
    const o = lifestyleOverdue(st?.days ?? null, level);
    if (!o.evict) return;
    const key = Number(a.system?.lifestyle?.paidUntil ?? -1);
    if (a.getFlag?.(SYSTEM_ID, 'evictionFor') === key) return;
    try { await a.setFlag(SYSTEM_ID, 'evictionFor', key); } catch { return; }
    if (RULES.UPKEEP.effects.overdue === 'auto') { await a.moveLifestyleDown(tx('SR2E.Card.Actor.daysOverdue', { daysLate: o.daysLate })); return; }
    const gms = [...((game as any).users ?? [])].filter((u: any) => u.isGM).map((u: any) => u.id);
    await ChatMessage.create({
      speaker: ChatMessage.getSpeaker({ actor: a }), whisper: gms,
      content: `<p><em>${tx('SR2E.Card.Actor.gmOnly')}</em> · <strong>${escText(a.name)}</strong>${tx('SR2E.Card.Actor.sLifestyleIs', { label: escText(lifestyleOf(level).label) })} <strong>${tx('SR2E.Card.Actor.daysOverdue', { daysLate: o.daysLate })}</strong>.</p><p><button type="button" data-sr2e-action="evict">${tx('SR2E.Card.Actor.moveThemDownTo', { label: escText(lifestyleOf(lifestyleDown(level)).label) })}</button></p>`,
      flags: { [SYSTEM_ID]: { evict: { actorUuid: a.uuid, from: level } } },
    });
  }

  /** v0.53.0 (GM tick): a safehouse's upkeep lapsed past the grace days: one GM card per unpaid date. */
  static async #safehouseTick(a: any, now: number): Promise<void> {
    if (a.type !== 'safehouse' || a.isToken) return;
    const key = Number(a.system?.paidUntil ?? -1);
    const st = safehouseUpkeepStatus(key, now);
    if (!st.lapsed) return;
    if (a.getFlag?.(SYSTEM_ID, 'lapsedFor') === key) return;
    try { await a.setFlag(SYSTEM_ID, 'lapsedFor', key); } catch { return; }
    const gms = [...((game as any).users ?? [])].filter((u: any) => u.isGM).map((u: any) => u.id);
    const comfort = safehouseComfort(String(a.system?.derived?.comfort ?? 'street'), true);
    await ChatMessage.create({
      speaker: { alias: a.name }, whisper: gms,
      content: `<p><em>${tx('SR2E.Card.Actor.gmOnly')}</em> · <strong>${escText(a.name)}</strong>${tx('SR2E.Card.Actor.sUpkeepIs')} <strong>${tx('SR2E.Card.Actor.daysOverdue2', { value: -(st.days ?? 0) })}</strong>${tx('SR2E.Card.Actor.itsComfortForHomeCareFalls', { label: escText(lifestyleOf(comfort).label) })}</p>`,
    });
  }

  /** v0.73.0 (O31): buy the current lifestyle outright (RULES.CHARACTERS_V73.lifestyle; the creation price). */
  async buyLifestyleOutright(): Promise<boolean> {
    const l = this.sys.lifestyle ?? { level: 'low', paidUntil: -1, outright: false };
    const now = sysNow();
    const p: any = outrightPurchase({ lifestyle: l.level, outright: Boolean(l.outright), paidUntil: Number(l.paidUntil ?? -1), now, nuyen: Number(this.sys.nuyen ?? 0) });
    if (!p.ok) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.canTBuyTheLifestyleOutright', { label: escHtml(p.label), reason: escHtml(p.reason) })); return false; }
    if (approvalNeeded(this)) { await fileRequest(this, { kind: 'improve', label: tx('SR2E.Text.Actor.buyLifestyleOutright', { label: p.label, cost: p.cost.toLocaleString() }), karma: 0, nuyen: p.cost, data: { method: 'buyLifestyleOutright', args: [] } }); return false; }
    if (p.cost > 0 && !(await this.adjustNuyen(-p.cost, tx('SR2E.Text.Actor.lifestyleBoughtOutright', { label: p.label })))) return false;
    await this.update({ 'system.lifestyle.outright': true, 'system.lifestyle.paidUntil': now });
    await ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor: this }), content: `<p><strong>${escText(this.name)}</strong> ${tx('SR2E.Card.Actor.buysTheLifestyleOutright', { label: escText(p.label), cost: p.cost.toLocaleString(), part: p.credit ? tx('SR2E.Card.Actor.paidAheadCounted', { credit: p.credit.toLocaleString() }) : '' })}</p>` });
    return true;
  }

  /** Pay `months` of lifestyle in advance (from now, or from the old date if that is later). */
  async payLifestyle(months = 1): Promise<boolean> {
    // v0.73.0 (O31): nothing to pay on a lifestyle owned outright.
    if (this.sys.lifestyle?.outright && RULES.CHARACTERS_V73.lifestyle.outrightPermanent) { ui.notifications?.info?.(tx('SR2E.Notify.Actor.sLifestyleIsOwnedOutrightNothing', { name: escHtml(this.name) })); return false; }
    const l = this.sys.lifestyle ?? { level: 'low', paidUntil: -1 };
    const p = payLifestyle({ lifestyle: l.level, months, paidUntil: l.paidUntil, now: sysNow() });
    const name = lifestyleOf(l.level).label;
    if (p.cost > 0 && !(await this.adjustNuyen(-p.cost, tCount(months, 'SR2E.Text.Actor.lifestyleMonths', { name })))) return false;
    await this.update({ 'system.lifestyle.paidUntil': p.paidUntil });
    await ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor: this }), content: `<p><strong>${escText(this.name)}</strong> ${tCount(months, 'SR2E.Card.Actor.paysMonthsOfLifestylePaidFor', { name: escText(name), part: p.cost ? ` (¥${p.cost.toLocaleString()})` : '', days: this.lifestyleStatus().days })}</p>` });
    return true;
  }

  /**
   * v0.61.0: a shaman's totem drawbacks by situation (MAGIC_V61.totems): berserk when wounded or in combat, a TN
   * penalty by daylight. The totem's own fields win ('none' / 0 switch one off), else the preset by its name.
   */
  totemDrawbacks(): { berserk: '' | 'wounded' | 'combat'; daylightTn: number } {
    const t = this.sys.totem;
    if (!t?.name || !['shamanic', 'shamanist', 'toxic'].includes(String(this.sys.tradition ?? ''))) return { berserk: '', daylightTn: 0 };
    const d = totemDrawback({ name: t.name, berserk: t.berserk === 'none' ? '' : t.berserk, daylightTn: Number(t.daylightTn ?? -1) > 0 ? Number(t.daylightTn) : 0 });
    return { berserk: t.berserk === 'none' ? '' : d.berserk, daylightTn: Number(t.daylightTn) === 0 ? 0 : d.daylightTn };
  }

  /** v0.61.0: a berserk-prone totem's shaman resists going berserk (Willpower vs TN); the rage lasts the turns left. */
  async berserkCheck(why: string): Promise<void> {
    if (this.hasStatus('sr2eBerserk')) return;
    const d = this.totemDrawbacks();
    if (!d.berserk) return;
    const t = berserkTest({ willpower: Number(this.sys.attributes?.[RULES.MAGIC_V61.totems.berserk.attribute]?.total ?? this.sys.attributes?.willpower?.total ?? 0) });
    const rolls: any[] = [];
    const r = await successTest({ dice: t.dice, targetNumber: t.tn, roll: foundryRoller(rolls) });
    const turns = berserkTurns(r.successes);
    if (turns > 0) await this.setTimedStatus('sr2eBerserk', turns * RULES.TOXINS.secondsPerTurn);
    await ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor: this }), rolls,
      content: `<p><strong>${escText(this.name)}</strong> ${tCount(r.successes, 'SR2E.Card.Actor.fightsTheTotemSRageWillpower', { why: escText(why), dice: t.dice, tn: t.tn, part: turns > 0 ? `<strong>${tCount(turns, 'SR2E.Card.Actor.berserkForCombatTurns')}</strong> ${tx('SR2E.Card.Actor.attacksTheNearestFoeInMelee')}` : tx('SR2E.Card.Actor.keepsControl') })}</p>` });
  }

  /** v0.61.0: the DocWagon contract: tier, whether it is paid up, and a line for the sheet. */
  docwagonState(): { tier: string; label: string; active: boolean; status: string } {
    const d = this.sys.docwagon ?? { tier: '', paidUntil: -1 };
    const tier = docwagonTier(String(d.tier ?? ''));
    if (!tier) return { tier: '', label: '', active: false, status: tx('SR2E.Text.Actor.noContract') };
    const st = docwagonStatus({ tier: tier.id, paidUntil: Number(d.paidUntil ?? -1), now: sysNow() });
    return { tier: tier.id, label: tier.label, active: st.active, status: st.label };
  }

  /** v0.61.0: pay the DocWagon contract for whole years. */
  async payDocwagon(years = 1): Promise<boolean> {
    const d = this.sys.docwagon ?? { tier: '', paidUntil: -1, resuscitationsUsed: 0 };
    const tier = docwagonTier(String(d.tier ?? ''));
    if (!tier) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.pickADocwagonContractFirst')); return false; }
    const now = sysNow();
    const p = docwagonPay({ tier: tier.id, years, paidUntil: Number(d.paidUntil ?? -1), now });
    if (!p.cost) return false;
    if (!(await this.adjustNuyen(-p.cost, tCount(years, 'SR2E.Text.Actor.docwagonYears', { label: tier.label })))) return false;
    // A lapsed contract starts a new contract year (free resuscitations again).
    const fresh = Number(d.paidUntil ?? -1) < now;
    await this.update({ 'system.docwagon.paidUntil': p.paidUntil, ...(fresh ? { 'system.docwagon.resuscitationsUsed': 0 } : {}) });
    await ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor: this }), content: `<p><strong>${escText(this.name)}</strong> ${tCount(years, 'SR2E.Card.Actor.paysDocwagonForYears', { tierLabel: escText(tier.label), cost: p.cost.toLocaleString() })}</p>` });
    return true;
  }

  /** v0.61.0: call DocWagon (the biomonitor does it when dying): who comes, when, and what it will cost. */
  async callDocwagon(o: { auto?: boolean } = {}): Promise<void> {
    const d = this.sys.docwagon ?? { tier: '', paidUntil: -1, resuscitationsUsed: 0 };
    const st = this.docwagonState();
    if (!st.tier) { if (!o.auto) ui.notifications?.warn?.(tx('SR2E.Notify.Actor.hasNoDocwagonContract', { name: escHtml(this.name) })); return; }
    const status = String(this.sys.derived?.status ?? 'ok');
    const call = docwagonCall({ tier: st.tier, active: st.active, status: status === 'dead' ? 'dead' : status === 'dying' ? 'dying' : 'wounded', hostile: false, resuscitationsUsed: Number(d.resuscitationsUsed ?? 0) });
    const who = escText(this.name);
    if (!call.responds) {
      await ChatMessage.create({ speaker: { alias: tx('SR2E.Card.Actor.docwagon') }, content: `<p>${tx('SR2E.Card.Actor.sDocwagonContract', { part: o.auto ? tx('SR2E.Card.Actor.biomonitorAlert') : '', who, stLabel: escText(st.label), part2: st.active ? tx('SR2E.Card.Actor.getsNoResponse') : tx('SR2E.Card.Actor.hasLapsedNoOneComes'), part3: call.notes.length ? ` ${escText(call.notes.join(' '))}` : '' })}</p>` });
      return;
    }
    const now = sysNow();
    const arriveAt = docwagonArrivalAt(now, call.responseSeconds);
    const fees = call.fees.length ? call.fees.map((f) => `${escText(f.label)} ¥${f.amount.toLocaleString()}`).join(', ') : tx('SR2E.Card.Actor.none');
    await ChatMessage.create({
      speaker: { alias: tx('SR2E.Card.Actor.docwagon') },
      content: `<div class="sr2e-roll"><h3>${tx('SR2E.Card.Actor.docwagon2', { stLabel: escText(st.label), part: o.auto ? tx('SR2E.Card.Actor.biomonitorAlert2') : tx('SR2E.Card.Actor.called') })}</h3><p>${tx('SR2E.Card.Actor.isATeamIsOnIts', { who, status: escText(status), span: escText(describeSpan(call.responseSeconds)) })}</p><p>${tx('SR2E.Card.Actor.feesOnArrival', { fees, part: call.notes.length ? ` <em>${escText(call.notes.join(' '))}</em>` : '' })}</p></div>
        <p><button type="button" data-sr2e-action="docwagonArrive" data-hostile="0">${tx('SR2E.Card.Actor.teamArrivesGm')}</button> <button type="button" data-sr2e-action="docwagonArrive" data-hostile="1" title="${tx('SR2E.Card.Actor.aFirefightHighThreatResponseIf')}">${tx('SR2E.Card.Actor.arrivesUnderFireGm')}</button></p>`,
      flags: { [SYSTEM_ID]: { docwagon: { actorUuid: this.uuid, calledAt: now, arriveAt } } },
    });
  }

  /** v0.61.0 (GM): the DocWagon team arrives: stabilise the patient, note a resuscitation, send the bill. */
  static async docwagonArrive(actorUuid: string, hostile: boolean): Promise<string | null> {
    if (!isGmNow()) return null;
    const a: any = await fromUuid(actorUuid);
    if (!(a instanceof SR2Actor)) return null;
    const d = a.sys.docwagon ?? { tier: '', paidUntil: -1, resuscitationsUsed: 0 };
    const st = a.docwagonState();
    const status = String(a.sys.derived?.status ?? 'ok');
    const call = docwagonCall({ tier: st.tier, active: st.active, status: status === 'dead' ? 'dead' : status === 'dying' ? 'dying' : 'wounded', hostile, resuscitationsUsed: Number(d.resuscitationsUsed ?? 0) });
    if (!call.responds) return tx('SR2E.Card.Actor.sContractGetsNoResponse', { name: a.name });
    const out: string[] = [];
    if (status === 'dying' && !a.sys.care?.stabilised) { await a.update({ 'system.care.stabilised': true }); out.push(tx('SR2E.Card.Actor.isStabilised2', { name: a.name })); }
    if (status === 'dead') {
      await a.update({ 'system.docwagon.resuscitationsUsed': Number(d.resuscitationsUsed ?? 0) + 1 });
      out.push(tx('SR2E.Card.Actor.theyTryToResuscitate', { name: a.name }));
    }
    if (call.total > 0) out.push((await a.adjustNuyen(-call.total, tx('SR2E.Text.Actor.docwagonFees', { fees: call.fees.map((f) => f.label).join(', ') }))) ? tx('SR2E.Card.Actor.billed', { total: call.total.toLocaleString() }) : tx('SR2E.Card.Actor.billedWhichCanTPay', { total: call.total.toLocaleString(), name: a.name }));
    const text = `${out.length ? tx('SR2E.Card.Actor.docwagonDone', { done: out.join('; ') }) : tx('SR2E.Card.Actor.nothingMoreToDo')}${call.notes.length ? ` ${call.notes.join(' ')}` : ''}`;
    await ChatMessage.create({ speaker: { alias: tx('SR2E.Card.Actor.docwagon') }, content: `<p><strong>${(hostile ? tx('SR2E.Card.Actor.docwagonArrivesWithUnderFire') : tx('SR2E.Card.Actor.docwagonArrivesPlain'))}</strong> ${escText(text)}</p>` });
    return text;
  }

  /** What raising an attribute or a skill (or its specialization) by one costs in Karma. */
  improveCost(target: { attribute?: string; skillId?: string; specialization?: boolean; concentration?: boolean }): { cost: number; from: number; to: number; ok: boolean; reason: string; label: string } {
    if (target.attribute) {
      const key = target.attribute as AttributeKey;
      const a = this.sys.attributes?.[key];
      if (!a) return { cost: 0, from: 0, to: 0, ok: false, reason: tx('SR2E.Text.Actor.noSuchAttribute'), label: key };
      const from = a.natural ?? a.base;
      // v0.73.0 (O38): Exceptional Attribute raises the maximum; raising above the racial maximum costs the dearer band
      // (RULES.CHARACTERS_V73.qualities / karmaAboveRacial; attributeKarmaCost = attributeCost with that switch off).
      const mx = this.usesMetatypeSafe() ? attributeMaximumsWith(this.sys.metatype, key as any, this.sys.qualities ?? []) : { natural: 99, augmented: 99 };
      const c = attributeKarmaCost({ to: from + 1, max: mx.natural, augmented: mx.augmented });
      return { cost: c.cost, ok: c.ok, reason: c.reason, from, to: from + 1, label: key.charAt(0).toUpperCase() + key.slice(1) + (c.band === 'aboveRacial' ? tx('SR2E.Text.Actor.aboveTheRacialMaximum') : '') };
    }
    const skill: any = [...this.items].find((i: any) => i.id === target.skillId && i.type === 'skill');
    if (!skill) return { cost: 0, from: 0, to: 0, ok: false, reason: tx('SR2E.Text.Actor.noSuchSkill'), label: '' };
    const kind = (skill.system.kind ?? 'active') as 'active' | 'knowledge' | 'language' | 'buildRepair';
    const attrKey = (kind === 'active' || kind === 'buildRepair' ? skill.system.attribute : 'intelligence') as AttributeKey;
    // v0.58.0: a Reaction-linked skill (vehicles) takes its band from natural Reaction.
    const at = this.sys.attributes ?? {};
    // v0.73.0 (O33): the same rating the + Add picker uses (RULES.CHARACTERS_V73.skillCost).
    const attr = skillBandAttribute(String(attrKey), at as any, { derivedReaction: Number(this.sys.derived?.reaction ?? 1), caller: 'improve' });
    if (target.concentration) {
      if (!skill.system.concentration) return { cost: 0, from: 0, to: 0, ok: false, reason: tx('SR2E.Text.Actor.noConcentrationNamed'), label: skill.name };
      const from = skill.system.concentrationRating || skill.system.rating;
      return { cost: skillCost({ to: from + 1, attribute: attr, kind, concentration: true }), from, to: from + 1, ok: true, reason: '', label: `${skill.name} (${skill.system.concentration})` };
    }
    if (target.specialization) {
      if (!skill.system.specialization) return { cost: 0, from: 0, to: 0, ok: false, reason: tx('SR2E.Text.Actor.noSpecializationNamed'), label: skill.name };
      const from = skill.system.specializationRating || skill.system.rating;
      return { cost: skillCost({ to: from + 1, attribute: attr, kind, specialization: true }), from, to: from + 1, ok: true, reason: '', label: `${skill.name} (${skill.system.specialization})` };
    }
    const from = skill.system.rating ?? 0;
    return { cost: skillCost({ to: from + 1, attribute: attr, kind }), from, to: from + 1, ok: true, reason: '', label: skill.name };
  }

  /** Whether metatype maximums apply (spirits have none). */
  usesMetatypeSafe(): boolean {
    try { return this.sys.usesMetatype?.() !== false; } catch { return true; }
  }

  /** Spend Good Karma to raise an attribute or a skill (or specialization) by one. */
  async improve(target: { attribute?: string; skillId?: string; specialization?: boolean; concentration?: boolean }): Promise<boolean> {
    const c = this.improveCost(target);
    if (!c.ok) { ui.notifications?.warn(tx('SR2E.Notify.Actor.canTRaise', { label: escHtml(c.label), reason: escHtml(c.reason) })); return false; }
    const good = this.sys.karma?.good ?? 0;
    if (good < c.cost) { ui.notifications?.warn(tx('SR2E.Notify.Actor.hasGoodKarmaRaisingToCosts', { name: escHtml(this.name), good: escHtml(good), label: escHtml(c.label), to: c.to, cost: c.cost })); return false; }
    // v0.64.0: with the approval queue on, a player's raise waits for the GM.
    if (approvalNeeded(this)) { await fileRequest(this, { kind: 'improve', label: tx('SR2E.Text.Actor.raise', { label: c.label, from: c.from, to: c.to }), karma: c.cost, data: { method: 'improve', args: [{ ...target }] } }); return false; }
    // v0.58.0: with training time on, the Karma goes now and the rating rises when the training is done.
    // v0.65.0: training time for player characters out of creation (NPCs and the wizard stay instant).
    if (RULES.CHARACTERS_V58.training.mode === 'timed' && this.type === 'character' && !inCreation(this)) return this.#startTraining(target, c);
    const ledger = this.#ledgerWith({ kind: 'karma', amount: -c.cost, reason: `${c.label} ${c.from} → ${c.to}` });
    if (target.attribute) {
      const a = this.sys.attributes[target.attribute];
      // v0.73.0 (O34): a raise counts from the raw rating when racial modifiers floored it.
      await this.update({ [`system.attributes.${target.attribute}.base`]: attributeRaiseBase(a.base ?? 0, a.rawNatural ?? a.natural ?? a.base, c.to), 'system.karma.good': good - c.cost, 'system.ledger': ledger });
    } else {
      const skill: any = [...this.items].find((i: any) => i.id === target.skillId);
      await skill.update(target.specialization ? { 'system.specializationRating': c.to } : target.concentration ? { 'system.concentrationRating': c.to } : { 'system.rating': c.to });
      await this.update({ 'system.karma.good': good - c.cost, 'system.ledger': ledger });
    }
    await ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor: this }), content: `<p><strong>${escText(this.name)}</strong> ${tx('SR2E.Card.Actor.raisesFromToForKarma', { label: escText(c.label), from: c.from, to: c.to, cost: c.cost })}</p>` });
    return true;
  }

  /** Legwork through a contact: Etiquette (or Charisma at +4) vs the information's difficulty, easier through closer contacts. */
  async legwork(contactId: string, opts: { difficultyTn?: number; skillName?: string; modifiers?: TargetNumberModifier[]; question?: string; pay?: number; contactDigs?: boolean; favour?: boolean; specialty?: boolean; fixer?: boolean; friendOfFriend?: boolean } = {}): Promise<{ successes: number; tier: string } | null> {
    if (this.#exclusiveBlocks()) return null;
    const contacts: any[] = [...((this.sys.contacts as any[] | undefined) ?? [])].map((x: any) => ({ ...x }));
    const contact = contacts.find((c: any) => c.id === contactId);
    if (!contact) return null;
    const c = RULES.UPKEEP.contacts;
    // v0.49.0: a favour called in adds dice (and may waive the fee); one asked of a contact who owes none is a debt.
    const fav = opts.favour ? callFavour(contact.favours ?? 0) : null;
    if (fav?.refused) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.alreadyOwesTooManyFavours', { name: escHtml(this.name), contactName: escHtml(contact.name) })); return null; }
    // v0.44.0: the contact's fee, and payment that buys extra dice (at most their Loyalty).
    const pay = Math.max(0, Math.floor(opts.pay ?? 0));
    const fee = fav?.waiveFee ? 0 : Math.max(0, Math.floor(contact.fee ?? 0));
    if (fee + pay > 0 && !(await this.adjustNuyen(-(fee + pay), fee && pay ? tx('SR2E.Text.Actor.legworkFeePaid', { name: contact.name, fee, pay }) : fee ? tx('SR2E.Text.Actor.legworkFee', { name: contact.name, fee }) : pay ? tx('SR2E.Text.Actor.legworkPaid', { name: contact.name, pay }) : tx('SR2E.Text.Actor.legwork', { name: contact.name })))) return null;
    if (fav) {
      contact.favours = clampFavours(fav.after);
      await this.update({ 'system.contacts': contacts });
    }
    const bought = paidDice(pay, contact.loyalty ?? 1);
    const favDice = fav?.dice ?? 0;
    const tn = legworkTarget({ difficultyTn: opts.difficultyTn ?? legworkDifficulties()[1]!.tn, contactLevel: contact.level });
    const sd = this.#skillDice(this.findSkill(opts.skillName || c.skill), false, null, c.attribute as AttributeKey);
    if (bought) sd.suffix += tx('SR2E.Card.Actor.paidDice', { bought });
    if (favDice) sd.suffix += tx('SR2E.Card.Actor.favourDice', { favDice });
    // v0.78.0 (RULES.BOOK_V78.legwork): a closer contact adds dice; the book's specialty / fixer / friend-of-a-friend TNs.
    const closer = legworkLevelDice(contact.level);
    if (closer) sd.suffix += ` (${c.levels.find((x) => x.level === contact.level)?.label ?? tx('SR2E.Card.Actor.closerContact')} +${closer})`;
    const bookMods = legworkModifiers({ specialty: opts.specialty, fixer: opts.fixer, friendOfFriend: opts.friendOfFriend });
    const rolls: any[] = [];
    const r = await successTest({ dice: sd.dice + bought + favDice + closer, targetNumber: tn, modifiers: this.#testModifiers({ modifiers: [...(opts.modifiers ?? []), ...bookMods, ...sd.modifiers, ...reputationModifiers(this.sys.derived?.streetCred ?? 0)] }), roll: foundryRoller(rolls) });
    // v0.49.0: a contact with dice of their own digs too (RULES.STREET.contacts.ownDice).
    const own = Math.max(0, Math.floor(contact.dice ?? 0));
    const digs = own > 0 && opts.contactDigs !== false && RULES.STREET.contacts.ownDice !== 'off';
    const theirs = digs ? await successTest({ dice: own, targetNumber: tn, roll: foundryRoller(rolls) }) : null;
    const total = contactDigSuccesses(r.successes, theirs ? theirs.successes : null);
    const tier = legworkTier(total.successes);
    const lvl = c.levels.find((x) => x.level === contact.level)?.label ?? tx('SR2E.Card.Actor.levelN', { level: contact.level });
    // v0.81.0 (D1-3): plain text (the contest card escapes it), not HTML kept in the card's flags.
    const favNote = fav ? `${fav.debt ? tCount(-contact.favours, 'SR2E.Card.Actor.nowOwesFavours', { name: this.name, contactName: contact.name }) : contact.favours > 0 ? tx('SR2E.Card.Actor.calledInAFavourStillOwed', { contactName: contact.name, favours: contact.favours }) : tx('SR2E.Card.Actor.calledInAFavour', { contactName: contact.name })}${fav.waiveFee && Number(contact.fee ?? 0) > 0 ? tx('SR2E.Card.Actor.noFee') : ''}` : '';
    // v0.71.0 (R1): a contest card (Karma Pool, the GM's TN change); the contact's own digging is the second side.
    const contest: Contest = { kind: 'legwork', id: SR2Actor.contestId(), actorName: this.name, sides: [
      { name: this.name, uuid: this.uuid as string, label: contact.role ? (opts.question ? tx('SR2E.Card.Actor.legworkAsksRoleAbout', { name: this.name, contactName: contact.name, lvl, role: contact.role, question: opts.question, skill: opts.skillName || c.skill, suffix: sd.suffix }) : tx('SR2E.Card.Actor.legworkAsksRole', { name: this.name, contactName: contact.name, lvl, role: contact.role, skill: opts.skillName || c.skill, suffix: sd.suffix }))
        : opts.question ? tx('SR2E.Card.Actor.legworkAsksAbout', { name: this.name, contactName: contact.name, lvl, question: opts.question, skill: opts.skillName || c.skill, suffix: sd.suffix }) : tx('SR2E.Card.Actor.legworkAsks', { name: this.name, contactName: contact.name, lvl, skill: opts.skillName || c.skill, suffix: sd.suffix }), result: r },
      ...(theirs ? [{ name: contact.name, label: tx('SR2E.Card.Actor.digsDice', { name: contact.name, own }), result: theirs }] : []),
    ], deal: { favNote } };
    await ChatMessage.create({
      speaker: ChatMessage.getSpeaker({ actor: this }),
      content: SR2Actor.contestContent(contest), flags: { [SYSTEM_ID]: { contest } },
      rolls,
    });
    return { successes: total.successes, tier };
  }

  /** v0.49.0: change what a contact and this character owe each other (+ they owe you, − you owe them). */
  async adjustFavours(contactId: string, delta: number): Promise<number | null> {
    const contacts: any[] = [...((this.sys.contacts as any[] | undefined) ?? [])].map((x: any) => ({ ...x }));
    const contact = contacts.find((c: any) => c.id === contactId);
    if (!contact) return null;
    contact.favours = clampFavours(Number(contact.favours ?? 0) + Math.floor(delta));
    await this.update({ 'system.contacts': contacts });
    return contact.favours;
  }

  /** Look for an item to buy: Etiquette vs its Availability TN; the time is base / successes. A Buy button follows. */
  async findItem(itemId: string, opts: { modifiers?: TargetNumberModifier[]; quantity?: number; through?: FindThrough | null } = {}): Promise<{ found: boolean; hours: number | null; price: number } | null> {
    if (this.#exclusiveBlocks()) return null;
    const item: any = [...this.items].find((i: any) => i.id === itemId);
    if (!item) return null;
    const qty = Math.max(1, opts.quantity ?? 1);
    const price = SR2Actor.#listPrice(item, qty);
    return this.#findCore({ name: item.name, type: item.type, system: item.system }, { actorUuid: this.uuid, itemId, price, name: item.name, qty }, `item:${itemId}`, opts);
  }

  /**
   * v0.91.0: find something in the shop (the Add window): the same Availability test as Find… on a sheet item, for an
   * entry that isn't on the sheet yet. The card's Buy pays (`buyFromShop`) and the item arrives after the time found.
   * The key is read back from the GM's catalogue, the built-in templates, world items, compendiums or kits; one this
   * user's shop doesn't show is refused.
   */
  async findFromShop(key: string, opts: { modifiers?: TargetNumberModifier[]; quantity?: number; through?: FindThrough | null } = {}): Promise<{ found: boolean; hours: number | null; price: number } | null> {
    if (this.#exclusiveBlocks()) return null;
    if (!this.isOwner) { ui.notifications?.warn?.(tx('SR2E.Notify.Shop.onlyTheOwner', { name: escHtml(this.name) })); return null; }
    const t = await resolveShopKey(key);
    if (!t) { ui.notifications?.warn?.(tx('SR2E.Notify.Shop.notInTheShopAny')); return null; }
    const qty = copiesOrQuantity(t.type, opts.quantity ?? 1);
    const price = shopListPrice(t, qty, this.type);
    return this.#findCore({ name: t.name, type: t.type, system: t.system }, { actorUuid: this.uuid, shop: t.key, price, name: t.name, qty }, t.key, { ...opts, quantity: qty });
  }

  /**
   * The find test itself (a sheet item or a shop entry). v0.91.0 (RULES.SHOP_V91.retry 'wait'): a failed find may be
   * tried again once its base time has passed (the GM is never held back); the wait is kept per thing in
   * `flags.sr2e.findRetry`.
   */
  async #findCore(src: { name: string; type: string; system: any }, buy: Record<string, unknown>, retryKey: string, opts: { modifiers?: TargetNumberModifier[]; quantity?: number; through?: FindThrough | null }): Promise<{ found: boolean; hours: number | null; price: number } | null> {
    const sys: any = src.system ?? {};
    // v0.45.0: cyberware grade and cultured bioware change Availability and cost.
    const ware = src.type === 'cyberware';
    const cultured = ware && Boolean(sys.bioware) && Boolean(sys.cultured);
    const av = ware ? gradedAvailability(sys.availability ?? '', { grade: sys.grade, cultured }) : parseAvailability(sys.availability ?? '');
    const qty = Math.max(1, opts.quantity ?? 1);
    const price = Number(buy['price'] ?? 0) || 0;
    // v0.91.6 (RULES.SHOP_V916.through): through a contact (their help on this character's roll) or a fixer (their own
    // find, for a fee and more time). The choice is checked against the character's own contacts.
    const choice = av.tn && opts.through && throughOn() && this.type === 'character' ? opts.through : null;
    const plan = choice ? throughPlan(this.sys.contacts as any, choice) : null;
    if (plan?.refused) {
      if (plan.refused === 'notFixer') ui.notifications?.warn?.(tx('SR2E.Notify.Through.notFixer', { contactName: escHtml(plan.contact.name) }));
      else if (plan.refused === 'tooManyFavours') ui.notifications?.warn?.(tx('SR2E.Notify.Through.tooManyFavours', { name: escHtml(this.name), contactName: escHtml(plan.contact.name) }));
      else ui.notifications?.warn?.(tx('SR2E.Notify.Through.noContact', { name: escHtml(this.name) }));
      return null;
    }
    const mode: ThroughMode = plan?.mode ?? 'self';
    // v0.91.5 (RULES.SHOP_V915.findByLegality): found openly, a restricted or forbidden thing is harder (TN) and slower;
    // v0.91.6: less so through a contact, not at all through a fixer (RULES.SHOP_V916).
    const legal = legalityId(sys.legality);
    const legalMods = throughLegalMods(legal, mode);
    const avHours = Number(av.hours ?? 0) * throughTimeFactor(legal, mode);
    // v0.91.5 review (R2): only a sheet item's own permit counts (a shop entry's permit doesn't come with it).
    const heldPermit = Boolean(buy['itemId']) && Boolean(sys.permit);
    const legalLine = SR2Actor.#legalLine(legal, heldPermit || Boolean(this.licenceCover(src.name, legal)), sys.rating);
    const rk = retryFlagKey(retryKey);
    const now = sysNow();
    const waitLeft = retryHoursLeft(((this.flags as any)?.[SYSTEM_ID]?.findRetry ?? {})[rk], now, Boolean(game.user?.isGM));
    if (waitLeft > 0) { ui.notifications?.warn?.(tx('SR2E.Notify.Shop.tryAgainLater', { name: escHtml(src.name), time: escHtml(timeLabel(waitLeft)) })); return null; }
    const flags = { [SYSTEM_ID]: { buy } };
    const buyBtn = SR2Actor.#buyButtons(price);
    if (!av.tn) {
      await ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor: this }), content: `<p><strong>${escText(src.name)}</strong>${tx('SR2E.Card.Actor.isReadilyAvailable', { part: qty > 1 ? ` ×${qty}` : '' })}</p>${legalLine}${buyBtn}`, flags });
      return { found: true, hours: 0, price };
    }
    const a = RULES.UPKEEP.availability;
    const shown = 'label' in av && av.label !== sys.availability ? av.label : sys.availability;
    // v0.91.6: the contact's fee and the pay for dice are paid now (as legwork); a favour called in is counted now.
    if (plan && plan.payNow > 0 && !(await this.adjustNuyen(-plan.payNow, tx('SR2E.Text.Through.paid', { name: plan.contact.name, item: src.name })))) return null;
    if (plan?.favour) {
      const contacts: any[] = [...((this.sys.contacts as any[] | undefined) ?? [])].map((x: any) => (x.id === plan.contact.id ? { ...x, favours: clampFavours(plan.favour!.after) } : { ...x }));
      await this.update({ 'system.contacts': contacts });
    }
    const rolls: any[] = [];
    let first: Contest['sides'][number];
    let second: Contest['sides'][number] | null = null;
    // A fixer's cut is on the price (the card's Buy pays it).
    const fee = mode === 'fixer' && !plan!.waiveCut ? fixerFeeOf(price) : 0;
    const total = price + fee;
    const extras = plan ? throughSuffix(plan) : '';
    if (mode === 'fixer') {
      // The fixer's own roll: their dice against the Availability TN; this character's wounds, lifestyle and Street Cred don't count.
      const fr = await successTest({ dice: plan!.dice, targetNumber: av.tn, modifiers: [...(opts.modifiers ?? []), ...legalMods, ...urrCoreFindMods()], roll: foundryRoller(rolls) });
      first = { name: plan!.contact.name, label: tx('SR2E.Card.Through.fixerFinds', { contactName: plan!.contact.name, name: src.name, qty: qty > 1 ? ` ×${qty}` : '', availability: shown, dice: plan!.dice, extras }), result: fr };
    } else {
      const sd = this.#skillDice(this.findSkill(a.skill), false, null, a.attribute as AttributeKey);
      // v0.49.0: the lifestyle's connections (RULES.UPKEEP.effects.availabilityTn).
      const lifeMods = this.type === 'character' ? lifestyleAvailabilityMods(String(this.sys.lifestyle?.level ?? 'low')) : [];
      const levelMods = plan ? contactLevelTnMods(plan.contact) : [];
      const r = await successTest({ dice: sd.dice + (plan?.dice ?? 0), targetNumber: av.tn, modifiers: this.#testModifiers({ modifiers: [...(opts.modifiers ?? []), ...sd.modifiers, ...lifeMods, ...legalMods, ...levelMods, ...urrCoreFindMods(), ...this.#dealCred()] }), roll: foundryRoller(rolls) });
      const through = plan ? tx('SR2E.Card.Through.helpedBy', { contactName: plan.contact.name, extras }) : '';
      // v0.65.0: the Buy button knows how long getting it takes (it arrives then).
      first = { name: this.name, uuid: this.uuid as string, label: `${qty > 1 ? tx('SR2E.Card.Actor.findingQtyAvailability', { name: src.name, qty, availability: shown, skill: a.skill, suffix: sd.suffix }) : tx('SR2E.Card.Actor.findingAvailability', { name: src.name, availability: shown, skill: a.skill, suffix: sd.suffix })}${through}`, result: r };
      // v0.49.0 (RULES.STREET.contacts.ownDice): a contact with dice of their own looks too.
      if (plan && plan.theirDice > 0) {
        const tr = await successTest({ dice: plan.theirDice, targetNumber: av.tn, modifiers: [...legalMods, ...levelMods], roll: foundryRoller(rolls) });
        second = { name: plan.contact.name, label: tx('SR2E.Card.Actor.digsDice', { name: plan.contact.name, own: plan.theirDice }), result: tr };
      }
    }
    const hours = findTime(avHours, throughSuccesses(mode, first.result!.successes, second?.result ? second.result.successes : null));
    const favNote = plan?.favour ? (plan.favour.debt ? tCount(-plan.favour.after, 'SR2E.Card.Actor.nowOwesFavours', { name: this.name, contactName: plan.contact.name }) : plan.favour.after > 0 ? tx('SR2E.Card.Actor.calledInAFavourStillOwed', { contactName: plan.contact.name, favours: plan.favour.after }) : tx('SR2E.Card.Actor.calledInAFavour', { contactName: plan.contact.name })) + (plan.favour && ((plan.mode === 'help' && Number(plan.contact.fee ?? 0) > 0) || plan.waiveCut) ? tx('SR2E.Card.Actor.noFee') : '') : '';
    // v0.71.0 (R1): a contest card (Karma Pool, the GM's TN change); the time and the Buy button follow its result.
    const buyAt = fee ? { ...buy, price: total } : buy;
    const contest: Contest = { kind: 'find', id: SR2Actor.contestId(), actorName: this.name, sides: [first, ...(second ? [second] : [])],
      deal: { avHours, price: total, buy: buyAt, ...(plan ? { through: { mode, name: String(plan.contact.name).slice(0, 100), fee }, ...(favNote ? { favNote } : {}) } : {}), ...(legal ? { legality: legal, permit: heldPermit, ...(Number(sys.rating) > 0 ? { rating: Math.min(100, Math.floor(Number(sys.rating))) } : {}) } : {}) } };
    await ChatMessage.create({
      speaker: ChatMessage.getSpeaker({ actor: this }),
      content: SR2Actor.contestContent(contest),
      rolls, flags: { [SYSTEM_ID]: { contest, ...SR2Actor.contestFlags(contest) } },
    });
    // v0.91.0: not found: the wait before trying again; found: any old wait goes.
    try {
      if (hours == null && RULES.SHOP_V91.retry === 'wait' && !game.user?.isGM) await this.update({ [`flags.${SYSTEM_ID}.findRetry.${rk}`]: { at: retryReadyAt(now, avHours), name: String(src.name).slice(0, 100) } });
      else if (hours != null) await this.#clearFindRetry(retryKey);
    } catch (err) { console.warn('sr2e | find retry', err); }
    return { found: hours != null, hours, price: total };
  }

  /** v0.91.0: forget a failed find's wait (found or bought after all). */
  async #clearFindRetry(retryKey: string): Promise<void> {
    const rk = retryFlagKey(retryKey);
    const m = (this.flags as any)?.[SYSTEM_ID]?.findRetry;
    if (m && typeof m === 'object' && m[rk] != null) await dropFlagKeys(this, 'findRetry', [rk]);
  }

  /**
   * v0.91.0: pay for something found in the shop (a find card's Buy, or an approved request). Like `buyItem`, the
   * price, quantity and wait come from a card or request, so they are checked here: the entry is read again from
   * its source (the buyer's shop must still show it), and the price is its street price for that quantity, moved no
   * further than haggling can move it. With the approval queue on, a player's purchase waits for the GM.
   */
  async buyFromShop(key: string, price?: number, hours = 0, qty = 1): Promise<boolean | 'requested'> {
    const ctx = approvalContext(String(this.uuid ?? ''));
    const buyer = ctx ? null : game.user;
    // An approved request is checked in the shop of the player who filed it (A-9: the server-set filer).
    // A filer this GM client didn't see arrive is checked as a plain player (never as the GM).
    const filer: any = ctx?.requesterId ? (game as any).users?.get?.(ctx.requesterId) : null;
    const requester = ctx ? (filer && !filer.isGM ? filer : { isGM: false }) : buyer;
    const t = await resolveShopKey(key, requester);
    if (!t) { ui.notifications?.warn?.(tx('SR2E.Notify.Shop.notInTheShopAny')); return false; }
    qty = copiesOrQuantity(t.type, safeInt(qty, 1, 10000, 1));
    hours = Math.max(0, Math.min(1e6, Number.isFinite(Number(hours)) ? Number(hours) : 0));
    // v0.91.0 review (R2): something with an Availability test can't arrive at once: a wait of 0 (no find card says
    // so) takes the base time, as Buy now does.
    if (hours <= 0) hours = itemAcquireHours(t.type, t.system, 0);
    const list = shopListPrice(t, qty, this.type);
    const most = 1000;
    const p = price === undefined || price === null ? list
      : Math.max(haggledPrice(list, most).price, Math.min(Math.max(haggledPrice(list, -most).price, list + fixerFeeOf(list)), safeInt(price, 0, Number.MAX_SAFE_INTEGER, list)));
    if (approvalNeeded(this)) {
      // v0.91.0 review (B2, B3): two purchases of the same thing are two requests (no replacing); a request that
      // wasn't filed leaves the card's Buy live.
      return (await fileRequest(this, { kind: 'add', label: tx('SR2E.Text.Shop.buyRequest', { name: t.name, qty: qty > 1 ? ` ×${qty}` : '', wait: hours > 0 ? tx('SR2E.Text.Shop.arrivesIn', { time: timeLabel(hours) }) : '' }), nuyen: p, keepOthers: true, data: { method: 'buyFromShop', args: [t.key, p, hours, qty] } })) ? 'requested' : false;
    }
    if (Number(this.sys.nuyen ?? 0) < p) { ui.notifications?.warn?.(tx('SR2E.Notify.Shop.notEnoughNuyen', { name: escHtml(this.name), price: p.toLocaleString(), have: Number(this.sys.nuyen ?? 0).toLocaleString() })); return false; }
    // v0.91.4: a vehicle or drone is a new actor: the GM's client makes it (a player's purchase goes over the relay).
    if (t.type === 'vehicle') {
      const ok = await this.shopVehicle('buy', t.key, p, hours, ctx ? requester : null);
      if (ok === 'pending') return 'requested';
      if (ok) { try { await this.#clearFindRetry(t.key); } catch { /* the purchase stands */ } }
      return ok;
    }
    const ok = await buyShopLine(this, t, { price: p, hours: this.waitsFor('gear') ? hours : 0, qty });
    if (ok) { try { await this.#clearFindRetry(t.key); } catch { /* the purchase stands */ } }
    return ok;
  }

  /**
   * v0.91.4: buy a vehicle or drone ('buy': price and wait as found; no price: the list price, and the base wait when
   * waiting is on) or take one free ('free': the GM, or a character in creation). Run on the GM's client: a player's
   * client asks the active GM over the relay, and the GM's client checks it all again (`vehicleShopAsGm`).
   * `asUser`: whose purchase it is when the GM applies a player's request.
   */
  async shopVehicle(action: 'buy' | 'free', key: string, price?: number, hours = 0, asUser: any = null): Promise<boolean | 'pending'> {
    let r: { ok: boolean; note?: string; timedOut?: boolean };
    // An approved request is the player's who filed it (the server-set filer; one this client never saw: a plain player).
    const ctx = approvalContext(String(this.uuid ?? ''));
    const filer: any = !asUser && ctx?.requesterId ? (game as any).users?.get?.(ctx.requesterId) : null;
    const who = asUser ?? (ctx ? (filer && !filer.isGM ? filer : { isGM: false, id: '' }) : (game as any).user);
    // v0.91.4 review (B4): the GM approving a request is the GM's consent (a gift, or a purchase the queue held).
    if ((game as any).user?.isGM) r = await this.vehicleShopAsGm(action, key, price, hours, who, { approved: Boolean(ctx) });
    else r = await requestGm('vehicleShop', { action, actorUuid: this.uuid, key: String(key ?? '').slice(0, 300), ...(price === undefined ? {} : { price }), hours });
    // v0.91.4 review (R1): no answer in time: the GM's client may still make it, so nothing may be bought again yet.
    if (!r.ok && r.timedOut) { ui.notifications?.warn?.(tx('SR2E.Notify.VehicleShop.slow')); return 'pending'; }
    if (!r.ok) { ui.notifications?.warn?.(escHtml(r.note || tx('SR2E.Notify.VehicleShop.failed'))); return false; }
    return true;
  }

  /**
   * v0.91.4 (the GM's client): a vehicle purchase or gift for `user` (the player who asked, or the GM). Nothing from the
   * request is trusted: the user must own this character; the key is read again in that user's shop (a vehicle for
   * sale: rules/shop.ts, applications/shop.ts); the price is the list price, moved no further than haggling can move
   * it; a gift is the GM's, or a character's in creation. Paid now; with waiting on, the vehicle is ordered (it arrives
   * when the time has passed: `deliverVehicle`), else it is made at once (`makeOwnedVehicle`).
   */
  async vehicleShopAsGm(action: unknown, key: unknown, price: unknown, hours: unknown, user: any, o: { approved?: boolean } = {}): Promise<{ ok: boolean; note?: string }> {
    if (!(game as any).user?.isGM) return { ok: false, note: tx('SR2E.Notify.VehicleShop.gmOnly') };
    if (this.inCompendium || (this.type !== 'character' && this.type !== 'npc')) return { ok: false, note: tx('SR2E.Notify.VehicleShop.notACharacter', { name: this.name }) };
    const player = !user?.isGM;
    if (player && (typeof user?.id !== 'string' || !user.id || !this.testUserPermission(user, 'OWNER'))) return { ok: false, note: tx('SR2E.App.Sheets.userDoesntOwn', { user: String(user?.name ?? ''), name: this.name }) };
    // v0.91.4 review (R2): the approval queue holds a player's purchase for the GM (a request sent straight here is refused).
    // (judged for the player, not for this GM client: approvalNeeded() reads the current user).
    if (player && !o.approved && needsApproval({ queueOn: queueOn(), isGM: false, actorType: String(this.type), inCreation: inCreation(this) })) return { ok: false, note: tx('SR2E.Notify.VehicleShop.needsApproval') };
    const t = await resolveShopKey(String(key ?? ''), player ? user : { isGM: true });
    if (!t || t.type !== 'vehicle') return { ok: false, note: tx('SR2E.Notify.Shop.notInTheShopAny') };
    const purchaser = player ? String(user?.id ?? '') : '';
    if (action === 'free') {
      // v0.91.4 review (R2, B4): a vehicle is given only by the GM (or with the GM's approval of a player's request).
      if (player && !o.approved) return { ok: false, note: tx('SR2E.Notify.VehicleShop.freeGmOnly') };
      return { ok: Boolean(await safeMakeOwnedVehicle(this, t.data, purchaser)) };
    }
    if (action !== 'buy') return { ok: false };
    const list = shopListPrice(t, 1, this.type);
    if (list <= 0 && player) return { ok: false, note: tx('SR2E.Notify.VehicleShop.noPrice', { name: t.name }) };
    const most = 1000;
    const p = price === undefined || price === null ? list
      : Math.max(haggledPrice(list, most).price, Math.min(Math.max(haggledPrice(list, -most).price, list + fixerFeeOf(list)), safeInt(price, 0, Number.MAX_SAFE_INTEGER, list)));
    // v0.91.4 review (R2): the wait is at least what ten successes on the find would take (a request can't make it instant).
    const av = parseAvailability(String(t.system?.availability ?? ''));
    // v0.91.5 review (R3): the legality time counts in the floor too.
    const floor = av.tn ? (findTime(av.hours * legalFindTimeFactor((t.system as any)?.legality), 10) ?? 0) : 0;
    let h = Math.max(0, Math.min(1e6, Number.isFinite(Number(hours)) ? Number(hours) : 0));
    if (h <= 0) h = itemAcquireHours('vehicle', t.system, 0);
    if (player) h = Math.max(h, floor);
    if (Number(this.sys.nuyen ?? 0) < p) return { ok: false, note: tx('SR2E.Notify.Shop.notEnoughNuyen', { name: this.name, price: p.toLocaleString(), have: Number(this.sys.nuyen ?? 0).toLocaleString() }) };
    // v0.89.6: ledger lines stay English (the advancement log reads "Bought …" by its words).
    if (p > 0 && !(await this.adjustNuyen(-p, `Bought ${t.name}`))) return { ok: false };
    if (this.waitsFor('gear') && h > 0) {
      // v0.91.4 review (B1): the order is the GM's record; the project only names it.
      const orderId = await recordVehicleOrder({ actorUuid: String(this.uuid), key: t.key, purchaserId: purchaser, paid: p, name: t.name });
      if (!orderId) { if (p > 0) await this.adjustNuyen(p, `Given up (refund): ${t.name}`); return { ok: false }; }
      await this.startProject({ kind: 'order', area: 'gear', label: `${t.name} on order`, hours: h, paid: { nuyen: p }, effect: { call: { method: 'deliverVehicle', args: [orderId] } } });
      return { ok: true };
    }
    const made = await safeMakeOwnedVehicle(this, t.data, purchaser);
    if (!made && p > 0) await this.adjustNuyen(p, `Given up (refund): ${t.name}`);
    return { ok: Boolean(made) };
  }

  /**
   * v0.91.4 (a project's call, on the GM's client): an ordered vehicle arrives. The order is the GM's record (a world
   * setting a player can't write), used up here: its key is read again in the purchaser's shop, and a copy made for this
   * character. When it can't be (the vehicle was taken out of the shop, removed, or couldn't be made), what the record
   * says was paid is given back.
   */
  async deliverVehicle(orderId: string): Promise<boolean> {
    if (!(game as any).user?.isGM) return false;
    const order = await takeVehicleOrder(orderId, String(this.uuid));
    if (!order) return false;
    const u: any = order.purchaserId ? (game as any).users?.get?.(order.purchaserId) : null;
    const t = await resolveShopKey(order.key, u && !u.isGM ? u : { isGM: true });
    const made = t && t.type === 'vehicle' ? await safeMakeOwnedVehicle(this, t.data, order.purchaserId) : null;
    if (!made && order.paid > 0) await this.adjustNuyen(order.paid, `Given up (refund): ${order.name} on order`);
    return Boolean(made);
  }

  /** v0.81.0: an item's street price for `qty` (cyberware by its grade), as a find card works it out. */
  static #listPrice(item: any, qty = 1): number {
    const ware = item?.type === 'cyberware';
    return itemPrice({ cost: ware ? wareCost(item.system) : Number(item?.system?.cost ?? 0) || 0, streetIndex: Number(item?.system?.streetIndex ?? 1) || 1, quantity: qty });
  }

  /**
   * Pay for an item (from a find card, or straight away).
   * v0.81.0 (SEC1-6): the price, quantity and wait come from a card's flags, so they are checked here: the item must
   * be on this actor, and the price is the item's own street price for that quantity, moved no further than haggling
   * can move it (never below nothing, never a gain).
   */
  async buyItem(itemId: string, price?: number, hours = 0, qty = 1): Promise<boolean> {
    const item: any = [...this.items].find((i: any) => i.id === itemId);
    if (!item) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.thatItemIsGone')); return false; }
    qty = safeInt(qty, 1, 10000, 1);
    hours = Math.max(0, Math.min(1e6, Number.isFinite(Number(hours)) ? Number(hours) : 0));
    const list = SR2Actor.#listPrice(item, qty);
    const most = 1000;
    const p = price === undefined || price === null ? list
      : Math.max(haggledPrice(list, most).price, Math.min(Math.max(haggledPrice(list, -most).price, list + fixerFeeOf(list)), safeInt(price, 0, Number.MAX_SAFE_INTEGER, list)));
    if (approvalNeeded(this)) { await fileRequest(this, { kind: 'add', label: tx('SR2E.Text.Actor.payFor', { name: item?.name ?? tx('SR2E.Text.Actor.anItem') }), nuyen: p, data: { method: 'buyItem', args: [itemId, p, hours, qty] } }); return false; }
    if (!(await this.adjustNuyen(-p, `Bought ${item?.name ?? 'an item'}`))) return false;
    // v0.65.0: it arrives when the time to get it (from the find test) has passed; until then it's off the sheet.
    if (item && Number(hours) > 0 && this.waitsFor('gear')) {
      const data = item.toObject(); delete data._id;
      const n = Math.max(1, Math.floor(Number(qty) || 1));
      const sy: any = item.system ?? {};
      // A wish-list entry (not in use, no more than was bought) goes off the sheet until it arrives; an item in use
      // (worn, installed, bonded, or a bigger stack) stays, and the bought copies arrive beside it.
      const placeholder = !sy.installed && !sy.worn && !sy.bonded && !sy.equipped && (item.type !== 'gear' || Number(sy.quantity ?? 1) <= n);
      if (placeholder) {
        await item.delete();
        await this.startProject({ kind: 'order', area: 'gear', label: `${item.name}${n > 1 ? ` ×${n}` : ''} on order`, hours: Number(hours), paid: { nuyen: p }, effect: { creates: [data] }, onCancel: { creates: [data] } });
      } else {
        const copy = { ...data, system: { ...(data.system ?? {}), ...(item.type === 'gear' ? { quantity: n } : {}), installed: false, worn: false, bonded: false } };
        await this.startProject({ kind: 'order', area: 'gear', label: `${item.name}${n > 1 ? ` ×${n}` : ''} on order`, hours: Number(hours), paid: { nuyen: p }, effect: { creates: item.type === 'gear' ? [copy] : Array.from({ length: n }, () => copy) } });
      }
      try { await this.#clearFindRetry(`item:${itemId}`); } catch { /* the purchase stands */ }
      return true;
    }
    await ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor: this }), content: `<p><strong>${escText(this.name)}</strong> ${tx('SR2E.Card.Actor.buysFor', { itemName: escText(item?.name ?? tx('SR2E.Card.Actor.it')), p: p.toLocaleString() })}</p>` });
    try { await this.#clearFindRetry(`item:${itemId}`); } catch { /* the purchase stands */ }
    return true;
  }

  /**
   * v0.91.5 (RULES.SHOP_V915.permits): what a permit is for: `item:<id>` (an item this actor carries) or `vehicle:<uuid>`
   * (a vehicle or drone this actor's players own; the GM, any). Its legality, cost (before the Street Index) and permit.
   */
  async #permitTarget(ref: string): Promise<{ kind: 'item' | 'vehicle'; id: string; uuid: string; name: string; legality: string; cost: number; permit: boolean; source: string } | null> {
    const r = String(ref ?? '');
    if (r.length > 300) return null;
    if (r.startsWith('item:')) {
      const item: any = this.items?.get?.(r.slice(5));
      if (!item || !['weapon', 'armor', 'gear', 'cyberware', 'focus', 'program', 'cyberdeck'].includes(item.type)) return null;
      const cost = item.type === 'cyberware' ? wareCost(item.system) : Number(item.system?.cost ?? 0) || 0;
      return { kind: 'item', id: item.id, uuid: String(item.uuid), name: String(item.name), legality: legalityId(item.system?.legality), cost, permit: Boolean(item.system?.permit), source: permitSource('item', String(item.id)) };
    }
    if (r.startsWith('vehicle:')) {
      const v: any = await fromUuid(r.slice(8));
      if (!(v instanceof SR2Actor) || v.type !== 'vehicle' || v.inCompendium) return null;
      // A player (or the GM running a player's request, whose data the player wrote) may name only their own vehicles.
      if ((!(game as any).user?.isGM || approvalContext(String(this.uuid ?? ''))) && !this.#projectMayTouch(v)) return null;
      // v0.91.5 review (R4): a player must own it themselves (the permit is written on it from their client when there's no wait).
      if (!(game as any).user?.isGM && !v.isOwner) return null;
      return { kind: 'vehicle', id: String(v.id), uuid: String(v.uuid), name: String(v.name), legality: legalityId((v.system as any)?.legality), cost: Number((v.system as any)?.cost ?? 0) || 0, permit: Boolean((v.system as any)?.permit), source: permitSource('vehicle', String(v.uuid)) };
    }
    return null;
  }

  /** v0.91.5: a permit's cost and time for an item or vehicle reference (null when it can't have one). For the sheets. */
  async permitQuote(ref: string): Promise<{ cost: number; hours: number; days: number; name: string; has: boolean; underWay: boolean } | null> {
    const t = await this.#permitTarget(ref);
    const plan = t ? permitPlan({ legality: t.legality, cost: t.cost }) : null;
    if (!t || !plan) return null;
    return { cost: plan.cost, hours: plan.hours, days: plan.days, name: t.name, has: t.permit, underWay: this.projects().some((p) => p.kind === 'permit' && p.source === t.source) };
  }

  /**
   * v0.91.5 (RULES.SHOP_V915.permits 'buy'): get a permit for an item this character carries, or a vehicle or drone its
   * players own. Paid now (RULES.SHOP_V915.permitCost); it is granted when its days have passed (Under way, with the
   * GM's waiting rules for gear), or at once with waiting off. With the approval queue on, a player's permit waits for
   * the GM. `filedCost`: the cost a request was filed with (an approved request runs only at that cost).
   */
  async getPermit(ref: string, filedCost?: number): Promise<boolean | 'requested'> {
    if (this.type !== 'character' && this.type !== 'npc') return false;
    const ctx = approvalContext(String(this.uuid ?? ''));
    if (!this.isOwner) { ui.notifications?.warn?.(tx('SR2E.Notify.Shop.onlyTheOwner', { name: escHtml(this.name) })); return false; }
    const t = await this.#permitTarget(ref);
    if (!t) { ui.notifications?.warn?.(tx('SR2E.Notify.Legal.gone')); return false; }
    const plan = permitPlan({ legality: t.legality, cost: t.cost });
    if (!plan) { ui.notifications?.warn?.(tx('SR2E.Notify.Legal.noPermitNeeded', { name: escHtml(t.name) })); return false; }
    if (t.permit) { ui.notifications?.warn?.(tx('SR2E.Notify.Legal.hasOne', { name: escHtml(t.name) })); return false; }
    // v0.91.5 review (R5): a real licence already covers it (a fake one doesn't stop a real permit).
    const cover = this.licenceCover(t.name, t.legality);
    if (cover && !cover.fake) { ui.notifications?.warn?.(tx('SR2E.Notify.Legal.licenceCovers', { name: escHtml(t.name), by: escHtml(cover.by) })); return false; }
    if (this.projects().some((p) => p.kind === 'permit' && p.source === t.source)) { ui.notifications?.warn?.(tx('SR2E.Notify.Legal.underWay', { name: escHtml(t.name) })); return false; }
    // An approved request runs at the cost it was filed with (the item's cost may have changed since).
    if (ctx && filedCost !== undefined && safeInt(filedCost, 0, Number.MAX_SAFE_INTEGER, -1) !== plan.cost) { ui.notifications?.warn?.(tx('SR2E.Notify.Legal.costChanged', { name: escHtml(t.name), cost: plan.cost.toLocaleString() })); return false; }
    const time = timeLabel(plan.hours);
    if (approvalNeeded(this)) {
      return (await fileRequest(this, { kind: 'add', label: tx('SR2E.Text.Legal.permitRequest', { name: t.name, cost: plan.cost.toLocaleString(), time }), nuyen: plan.cost, data: { method: 'getPermit', args: [ref, plan.cost] } })) ? 'requested' : false;
    }
    if (Number(this.sys.nuyen ?? 0) < plan.cost) { ui.notifications?.warn?.(tx('SR2E.Notify.Shop.notEnoughNuyen', { name: escHtml(this.name), price: plan.cost.toLocaleString(), have: Number(this.sys.nuyen ?? 0).toLocaleString() })); return false; }
    if (plan.cost > 0 && !(await this.adjustNuyen(-plan.cost, `Permit: ${t.name}`))) return false;
    const effect: ProjectEffect = t.kind === 'item' ? { updates: [{ itemId: t.id, changes: [['system.permit', true]] }] } : { call: { method: 'finishPermit', args: [t.uuid] } };
    if (plan.hours > 0 && this.waitsFor('gear')) {
      await this.startProject({ kind: 'permit', area: 'gear', label: tx('SR2E.Text.Legal.permitFor', { name: t.name }), subject: t.name, source: t.source, hours: plan.hours, paid: { nuyen: plan.cost }, effect });
      return true;
    }
    if (t.kind === 'item') await this.items.get(t.id)?.update({ 'system.permit': true });
    else await this.finishPermit(t.uuid);
    await ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor: this }), content: `<p><strong>${escText(this.name)}</strong> ${tx('SR2E.Card.Legal.granted', { thing: escText(t.name), cost: plan.cost.toLocaleString() })}</p>` });
    return true;
  }

  /** v0.91.5: a vehicle's or drone's permit comes through (a permit project's end, or at once). */
  async finishPermit(vehicleUuid: string): Promise<boolean> {
    const v: any = await fromUuid(String(vehicleUuid ?? ''));
    if (!(v instanceof SR2Actor) || v.type !== 'vehicle') return false;
    await v.update({ 'system.permit': true });
    return true;
  }

  /** Add a contact (returns its id). */
  async addContact(c: { name: string; level?: number; role?: string; notes?: string; loyalty?: number; skills?: string; fee?: number; dice?: number; favours?: number; fixer?: boolean }): Promise<string> {
    const id = (foundry as any).utils?.randomID?.() ?? `c${Date.now()}`;
    // v0.91.6: the new-contact form's other fields are kept too (only name, level, role and notes were before).
    const S = RULES.STREET.contacts;
    const list = [...((this.sys.contacts as any[] | undefined) ?? []), { id, name: c.name || 'New contact', level: Math.min(3, Math.max(1, c.level ?? 1)), role: c.role ?? '', notes: c.notes ?? '',
      loyalty: safeInt(c.loyalty, 1, S.maxLoyalty, 1), skills: String(c.skills ?? ''), fee: safeInt(c.fee, 0, Number.MAX_SAFE_INTEGER, 0), dice: safeInt(c.dice, 0, 100, 0),
      favours: clampFavours(Number(c.favours) || 0), fixer: Boolean(c.fixer) }];
    await this.update({ 'system.contacts': list });
    return id;
  }

  /** The GM's award: Karma and/or nuyen to several characters, optionally refreshing Karma Pools; one summary card. */
  static async awardGroup(uuids: string[], o: { karma?: number; nuyen?: number; reason?: string; refreshPool?: boolean }): Promise<number> {
    const lines: string[] = [];
    for (const u of uuids) {
      const a: any = await fromUuid(u);
      if (!a) continue;
      const parts: string[] = [];
      if ((o.karma ?? 0) > 0) {
        const r = await a.awardKarma(o.karma, o.reason);
        if (r) parts.push(tx('SR2E.Card.Actor.karma5', { good: r.good, part: r.pool ? tx('SR2E.Card.Actor.karmaPool', { pool: r.pool }) : '' }));
      }
      if (o.nuyen && (await a.adjustNuyen(o.nuyen, o.reason || 'Payment'))) parts.push(`¥${o.nuyen.toLocaleString()}`);
      if (o.refreshPool) { await a.refreshKarmaPool(); parts.push(tx('SR2E.Card.Actor.karmaPoolRefreshed')); }
      if (parts.length) lines.push(`<li>${escText(a.name)}: ${parts.join('; ')}</li>`);
    }
    if (lines.length) await ChatMessage.create({ content: `<p><strong>${tx('SR2E.Card.Actor.awards')}</strong>${o.reason ? `: ${escText(o.reason)}` : ''}</p><ul>${lines.join('')}</ul>` });
    return lines.length;
  }



  /** Whether this actor has a token status (e.g. 'blind', 'prone'). */
  hasStatus(id: string): boolean {
    try { return Boolean((this as any).statuses?.has?.(id)); } catch { return false; }
  }

  /** A blinded character's TN modifier (RULES.STATUSES.blind). */
  blindMods(what: 'attack' | 'spell' | 'other'): TargetNumberModifier[] {
    if (!this.hasStatus('blind')) return [];
    // v0.78.0 (RULES.BOOK_V78.flash 'book'): dazzled by a flash: its TN on every test, not the full blindness.
    const flash = this.flashTnNow();
    if (flash > 0) return [{ id: 'flash', label: tx('SR2E.Card.Mod.flash'), value: flash }];
    const v = blindModifier(what);
    return v ? [{ id: 'blinded', label: tx('SR2E.Card.Mod.blinded'), value: v }] : [];
  }

  /** v0.78.0: the TN a flash grenade left on this character (0 when not dazzled, or under the old blind rule). */
  flashTnNow(): number {
    if (RULES.BOOK_V78.flash.mode !== 'book' || !this.hasStatus('blind')) return 0;
    // Only while the timed Blinded status it set still runs (a Blinded status set later by hand is full blindness).
    const until = (this.getFlag?.(SYSTEM_ID, 'statusUntil') as Record<string, unknown> | undefined) ?? {};
    if (until['blind'] == null) return 0;
    const v = Number(this.getFlag?.(SYSTEM_ID, 'flashTn') ?? 0);
    return Number.isFinite(v) && v > 0 ? v : 0;
  }

  /** Set a status for a while: it clears itself when the time is up (SR2Actor.timedEffects). */
  /**
   * v0.81.1 (D2-5): a timed status (a flash's blindness, with its TN) on `a`: set here when this client may write it,
   * else a whispered Apply (GM) card (flag `timedStatus`, applied by `applyTimedStatusAsGm`). True when set here.
   */
  async #timedStatusOn(a: any, status: 'blind', seconds: number, flashTn = 0): Promise<boolean> {
    if (!notWritableNow(a)) {
      await a.setTimedStatus(status, seconds);
      if (flashTn > 0) { try { await a.setFlag(SYSTEM_ID, 'flashTn', flashTn); } catch { /* not saved */ } }
      return true;
    }
    const gms = [...((game as any).users ?? [])].filter((u: any) => u.isGM).map((u: any) => u.id);
    await ChatMessage.create({
      speaker: ChatMessage.getSpeaker({ actor: this }), whisper: gms,
      content: `<p><em>${tx('SR2E.Card.Actor.gmOnly')}</em> ${tx('SR2E.Card.Actor.isForSSFlash', { name: escText(a.name), part: status === 'blind' ? tx('SR2E.Card.Actor.blinded') : escText(status), part2: flashTn > 0 ? tx('SR2E.Card.Actor.tn11', { flashTn: safeInt(flashTn, 0, 10, 0) }) : '', seconds: safeInt(seconds, 0, 600, 0), name2: escText(this.name) })}</p><p><button type="button" data-sr2e-action="applyTimedStatus">${tx('SR2E.Card.Actor.applyGm')}</button></p>`,
      flags: { [SYSTEM_ID]: { timedStatus: { targetUuid: a.uuid, status, seconds: safeInt(seconds, 0, 600, 0), flashTn: safeInt(flashTn, 0, 10, 0), sourceUuid: this.uuid } } },
    });
    return false;
  }

  /** v0.81.1 (D2-5, GM): apply a timed status card (`timedStatus`): only blindness, bounded to 600 s and +10 TN. */
  static async applyTimedStatusAsGm(v: { targetUuid?: unknown; status?: unknown; seconds?: unknown; flashTn?: unknown }): Promise<boolean> {
    if (!isGmNow() || String(v?.status ?? '') !== 'blind') return false;
    const a: any = await fromUuid(String(v?.targetUuid ?? ''));
    if (!(a instanceof SR2Actor)) return false;
    const seconds = safeInt(v.seconds, 1, 600, 0);
    if (!seconds) return false;
    await a.setTimedStatus('blind', seconds);
    const tn = safeInt(v.flashTn, 0, 10, 0);
    if (tn > 0) { try { await a.setFlag(SYSTEM_ID, 'flashTn', tn); } catch { /* not saved */ } }
    return true;
  }

  async setTimedStatus(id: string, seconds: number): Promise<void> {
    // v0.61.0: a damper in the ears shrugs off being deafened.
    if (id === 'deaf' && deafeningBlocked(this.hearingNow())) return;
    try { await (this as any).toggleStatusEffect?.(id, { active: true }); } catch { /* no status */ }
    const combat: any = (game as any).combat;
    const ends = effectEnds({ round: combat?.started ? Number(combat.round ?? 0) : null, worldTime: sysNow(), seconds, combatId: combat?.started ? String(combat.id ?? '') : null });
    const until = { ...((this.getFlag?.(SYSTEM_ID, 'statusUntil') as Record<string, unknown> | undefined) ?? {}), [id]: ends };
    try { await this.setFlag(SYSTEM_ID, 'statusUntil', until); } catch { /* not saved */ }
  }

  /** Stand up from prone: an action (RULES.STATUSES.prone.standAction). */
  async standUp(): Promise<boolean> {
    if (!this.hasStatus('prone')) {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.isNotProne', { name: escHtml(this.name) }));
      return false;
    }
    if (!(await this.useAction('stand', tx('SR2E.Card.Actor.standingUp')))) return false;
    try { await (this as any).toggleStatusEffect?.('prone', { active: false }); } catch { /* no status */ }
    await ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor: this }), content: `<p>${tx('SR2E.Card.Actor.standsUp', { name: escText(this.name) })}</p>` });
    return true;
  }

  /** A gear item's toxin, drug or disease, as stats. */
  static toxinOf(item: any): { name: string; kind: string; vector: string; power: number; level: DamageLevel; damageType: DamageType; speed: string; effect: string; incubationHours: number; intervalHours: number; recoveries: number; contagious: string } | null {
    const t = item?.system?.toxin;
    if (!t?.kind) return null;
    return { name: item.name, kind: t.kind, vector: t.vector, power: t.power, level: t.level, damageType: t.damageType, speed: t.speed, effect: t.effect ?? '',
      incubationHours: Number(t.incubationHours ?? 24), intervalHours: Number(t.intervalHours ?? 24), recoveries: Number(t.recoveries ?? 0), contagious: t.kind === 'disease' ? String(t.contagious ?? '') : '' };
  }

  /** Worn protective gear against toxins (v0.42.0). */
  protectiveGear(): Array<{ kind: string; rating: number; worn: boolean; name: string }> {
    return [...this.items].filter((i: any) => i.type === 'gear' && i.system?.protection?.kind)
      .map((i: any) => ({ kind: i.system.protection.kind, rating: Number(i.system.protection.rating ?? 0), worn: Boolean(i.system.protection.worn) && isCarried(i), name: i.name }));
  }

  /** The scene's weather (v0.42.0): a scene flag the GM sets in the GM panel. */
  static sceneWeather(at: any = null): string {
    const scene = at ?? game.scenes?.viewed ?? game.scenes?.current;
    return String(scene?.getFlag?.(SYSTEM_ID, 'weather') ?? 'clear') || 'clear';
  }
  static async setSceneWeather(id: string): Promise<void> {
    const scene = game.scenes?.viewed ?? game.scenes?.current;
    if (scene) await scene.setFlag(SYSTEM_ID, 'weather', id || 'clear');
  }

  /** v0.48.0: smoke from a fire between this character's token and another's (Perception), for their eyes. */
  fireSmokeMods(other: any): TargetNumberModifier[] {
    try {
      const a = attackerToken(this);
      const b = other?.token?.object ?? tokenOf(other);
      if (!a || !b || !(canvas as any)?.scene) return [];
      const sm = smokeOnLine(a.center, b.center, SR2Actor.sceneFires((canvas as any).scene), pxPerMetre());
      if (sm.kind === 'none') return [];
      const v = smokeModifier(sm.kind, this.sys.derived?.vision ?? {});
      return v.value ? [{ label: `${sm.kind === 'thermal' ? tx('SR2E.Card.Actor.thermalSmoke') : tx('SR2E.Card.Actor.smoke2')} (${sm.flames ? tx('SR2E.Card.Actor.flames') : tx('SR2E.Card.Actor.fire2')})`, value: v.value }] : [];
    } catch { return []; }
  }

  /** v0.48.0: walking and running rates under the scene's weather. */
  movementNow(): { walk: number; run: number; factor: number } | null {
    const m = this.sys.derived?.movement;
    if (!m) return null;
    return movementInWeather({ walk: Number(m.walk ?? 0), run: Number(m.run ?? 0) }, this.weatherHere());
  }

  /** The weather's TN modifier for this character's eyes (v0.50.0: or the eyes given, e.g. a scope's or a vehicle's sensors). */
  weatherMods(vision: Vision | null = null): TargetNumberModifier[] {
    const w = weatherModifier(this.weatherHere(), vision ?? this.visionNow());
    return w ? [w] : [];
  }

  // ---------------------------------------------------------------- v0.50.0: target-number automation

  /**
   * The scene this actor acts in (RULES.TN_AUTO.magic.tokenScene): its token's on the canvas, an
   * unlinked token's own scene, the active scene if a linked token of it is there, else the viewed one.
   */
  sceneHere(): any {
    const viewed = game.scenes?.viewed ?? game.scenes?.current ?? null;
    if (!RULES.TN_AUTO.magic.tokenScene) return viewed;
    try {
      const t = attackerToken(this);
      if (t?.document?.parent) return t.document.parent;
      const own = (this as any).token?.parent;
      if (own) return own;
      const cur = game.scenes?.current;
      if (cur && [...(cur.tokens ?? [])].some((d: any) => d.actorId === this.id && d.actorLink)) return cur;
    } catch { /* the viewed scene */ }
    return viewed;
  }

  /**
   * The eyes this actor looks with: its own (cyber, metatype, adept), a vehicle's sensors when it is
   * a vehicle or a rigger jumped into one (RULES.TN_AUTO.rigging).
   */
  visionNow(): Vision {
    if (this.type === 'vehicle') {
      const sv = this.sys.sensorVision ?? {};
      return { lowLight: Boolean(sv.lowLight), thermographic: Boolean(sv.thermographic) };
    }
    const rig = this.sys.rigging;
    if (rig?.jumpedIn && rig.vehicleUuid) {
      const veh: any = fromUuidSync(rig.vehicleUuid);
      if (veh?.type === 'vehicle') return veh.visionNow();
    }
    const v = this.sys.derived?.vision ?? {};
    // v0.79.0: natural eyes (RULES.DOCS_V79.visionCyberNatural).
    return { lowLight: Boolean(v.lowLight), thermographic: Boolean(v.thermographic), ultrasound: Boolean(v.ultrasound), lowLightNatural: Boolean(v.lowLightNatural), thermographicNatural: Boolean(v.thermographicNatural) };
  }

  /** Jumped into a vehicle (a rigger whose senses are the vehicle's). */
  isJumpedIn(): boolean {
    const rig = this.sys.rigging;
    if (!rig?.jumpedIn || !rig.vehicleUuid) return false;
    try { return (fromUuidSync(rig.vehicleUuid) as any)?.type === 'vehicle'; } catch { return false; }
  }

  /** The token an actor is on: an unlinked token's own, else its token on the canvas (a passenger: the vehicle's). */
  static tokenFor(actor: any): any | null {
    if (!actor) return null;
    try {
      const own = actor.token?.object;
      if (own) return own;
      const t = attackerToken(actor);
      if (t) return t;
      const ride = actor.vehicleAboard?.();
      return ride ? attackerToken(ride) : null;
    } catch { return null; }
  }

  /**
   * What this actor's eyes meet looking at someone (or something) on the canvas: light at them, line
   * of sight, smoke between, distance, and the weather (v0.50.0). Missing tokens give nulls.
   */
  sightTo(other: any, opts: { vision?: Vision; from?: any; to?: any } = {}): {
    light: LightLevel | null; lit: boolean; los: boolean | null; smoke: { kind: 'none' | 'smoke' | 'thermal'; source: string; flames: boolean };
    metres: number | null; weather: TargetNumberModifier | null; vision: Vision; from: any; to: any;
  } {
    const vision = opts.vision ?? this.visionNow();
    const a = opts.from ?? SR2Actor.tokenFor(this);
    const b = opts.to ?? SR2Actor.tokenFor(other);
    let light: LightLevel | null = null, lit = false;
    try { const tl = targetLight(b); light = tl?.light ?? null; lit = Boolean(tl?.source); } catch { light = null; }
    const los = a && b ? lineOfSight(a, b) : null;
    const smoke = a && b ? smokeBetweenTokens(a, b, SR2Actor.sceneFires((canvas as any)?.scene)) : { kind: 'none' as const, source: '', flames: false };
    const metres = a && b ? measureTokens(a, b)?.metres ?? null : null;
    const weather = weatherModifier(this.weatherHere(), vision);
    return { light, lit, los, smoke, metres, weather, vision, from: a, to: b };
  }

  /**
   * Everything that makes someone harder for this actor to notice (v0.50.0): light, walls, smoke,
   * weather, distance, their concealment, this actor's blindness and pain editor. `unseen`: by ear
   * only; `blocked`: can't notice them at all (RULES.TN_AUTO.perception.noSight).
   */
  perceptionAgainst(target: any, opts: { vision?: Vision; from?: any; to?: any } = {}): { modifiers: TargetNumberModifier[]; unseen: boolean; blocked: boolean; why: string } {
    const s = this.sightTo(target, opts);
    const r = perceptionSightModifiers({
      light: s.light, vision: s.vision, los: s.los, smoke: s.smoke, metres: s.metres, weather: s.weather,
      blind: this.hasStatus('blind') && !this.flashTnNow(), concealment: target?.concealmentFor?.(this) ?? target?.concealmentOf?.() ?? [],
    });
    // v0.78.0: dazzled by a flash: its TN, not full blindness.
    if (this.flashTnNow()) r.modifiers.push(...this.blindMods('other'));
    const pe = Number(this.sys.derived?.bio?.perceptionTn ?? 0);
    if (pe) r.modifiers.push({ id: 'painEditor', label: tx('SR2E.Card.Mod.painEditor'), value: pe });
    r.modifiers.push(...qualityModifiers(this.sys.qualities ?? [], { skill: RULES.PERCEPTION.skill }));
    // v0.56.0: a Concealment power (or a spell) on the target makes it harder to notice.
    const hid = Number(target?.system?.derived?.effectMods?.perceivedTn ?? 0);
    if (hid) r.modifiers.push({ id: 'concealedMagic', label: tx('SR2E.Card.Mod.concealedMagic'), value: hid });
    // v0.59.0: noticing someone only by ear while deaf (RULES.STATUSES.deaf); v0.61.0: cyberears help.
    if (r.unseen) r.modifiers.push(...hearingModifiers({ ears: this.hearingNow(), deaf: this.hasStatus('deaf') }));
    return r;
  }

  /** v0.61.0: what this actor hears with: working cyberears plus an adept's improved hearing. */
  hearingNow(): ReturnType<typeof earsDerived> {
    const ears = (this.sys.derived?.cyber?.ears ?? earsDerived([])) as ReturnType<typeof earsDerived>;
    return { ...ears, adept: Boolean(this.sys.derived?.vision?.hearing) };
  }

  /** The sneaker's side of a perception contest: Stealth (or Quickness +4) and its modifiers, movement included (v0.50.0). */
  stealthSide(opts: { useSpecialization?: boolean } = {}): { dice: number; rating: number; modifiers: TargetNumberModifier[]; suffix?: string } {
    const p = RULES.PERCEPTION;
    const stealth: any = this.findSkill?.(p.stealthSkill);
    const rating = (stealth?.system?.rating as number | undefined) ?? 0;
    const attr = (this.sys.attributes?.[p.stealthAttribute]?.total as number | undefined) ?? 0;
    let move: TargetNumberModifier | null = null;
    try {
      const t = SR2Actor.tokenFor(this);
      const moved = t && (game as any).combat?.started ? movedThisTurn(t) : null;
      if (moved != null) move = stealthMovementModifier(movementState(moved, (this.sys.attributes?.quickness?.total as number | undefined) ?? 0));
    } catch { move = null; }
    // v0.71.0 (R2): the shared skill path (named-skill gear, adept skill powers, skillsofts, articulation, the
    // specialization when asked); defaulting and the Stealth edges and flaws come with it.
    if (RULES.FIXES_V71.contestSkillDice && this.type !== 'vehicle') {
      const sd = this.#skillDice(stealth, Boolean(opts.useSpecialization), null, p.stealthAttribute as AttributeKey, { skillName: p.stealthSkill });
      return { dice: sd.dice, rating, suffix: sd.suffix, modifiers: this.#testModifiers({ modifiers: [...sd.modifiers, ...(move ? [move] : [])] }) };
    }
    return {
      dice: rating > 0 ? rating : attr, rating,
      modifiers: this.#testModifiers({ modifiers: [
        ...(rating > 0 ? [] : [{ id: 'defaultingToAttribute', label: tx('SR2E.Card.Mod.defaultingToAttribute'), value: RULES.ATTRIBUTE_DEFAULT_TN_MOD }]),
        ...qualityModifiers(this.sys.qualities ?? [], { skill: p.stealthSkill }),
        ...(move ? [move] : []),
      ] }),
    };
  }

  /**
   * v0.71.0 (R2): this observer's dice in a perception contest: Perception through the shared skill path
   * (gear, adept skill powers, skillsofts, a possessor's skill), else Intelligence; enhanced perception adds.
   * Perception edges and flaws aren't repeated here: they come with the sight modifiers (perceptionAgainst).
   */
  perceptionDice(): { dice: number; label: string; modifiers: TargetNumberModifier[] } {
    const p = RULES.PERCEPTION;
    const per: any = this.findSkill?.(p.skill);
    const attr = Number(this.sys.attributes?.[p.attribute]?.total ?? 0);
    const enh = this.adeptSpecial('enhancedPerception') * RULES.ADEPT.enhancedPerception.dicePerLevel;
    const has = Number(per?.system?.rating ?? 0) > 0;
    if (!has || !RULES.FIXES_V71.contestSkillDice) return { dice: (has ? per.system.rating : attr) + enh, label: has ? `${per.name} ${per.system.rating}` : `${cap(p.attribute)} ${attr}`, modifiers: [] };
    const sd = this.#skillDice(per, false, null, p.attribute as AttributeKey, { skillName: p.skill });
    const qm = new Set(qualityModifiers(this.sys.qualities ?? [], { skill: p.skill }).map((m) => modKey(m)));
    return { dice: sd.dice + enh, label: `${per.name} ${per.system.rating}${sd.suffix}${enh ? tx('SR2E.Card.Actor.plusEnhancedPerception', { enh }) : ''}`, modifiers: sd.modifiers.filter((m) => !qm.has(modKey(m))) };
  }

  /** The modifiers a test of this actor's would get with these options (for dialog previews, v0.50.0). */
  previewModifiers(opts: TestOptions = {}): TargetNumberModifier[] {
    return this.#testModifiers(opts);
  }

  /** Expose people to a toxin, disease or drug overdose: a card with a Resist button for each. */
  async exposeTo(item: any, targetUuids: string[]): Promise<void> {
    const t = SR2Actor.toxinOf(item);
    if (!t) {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.isNotAToxinDrugOr', { itemName: escHtml(item?.name ?? tx('SR2E.Notify.Actor.that')) }));
      return;
    }
    const targets = targetUuids.map((u) => fromUuidSync(u)).filter(Boolean) as any[];
    if (!targets.length) {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.pickSomeoneToExpose'));
      return;
    }
    const speed = toxinSpeed(t.speed);
    // v0.61.0: a slow toxin takes effect later (HEALTH_V61.onset): Resist waits until then.
    const on = SR2Actor.#onsetFor(t.kind === 'disease' ? 'immediate' : String(t.speed ?? 'immediate'));
    const states = targets.map((a) => ({ targetUuid: a.uuid as string, ...t, ...(on.at ? { onsetAt: on.at } : {}) }));
    const rows = states.map((_st, i) => `<li>${escText(targets[i].name)} <button type="button" data-sr2e-action="resistToxin" data-index="${i}">${tx('SR2E.Card.Actor.resist')}</button></li>`).join('');
    await ChatMessage.create({
      speaker: ChatMessage.getSpeaker({ actor: this }),
      content: `<p><strong>${escText(t.name)}</strong> (${escText(t.kind)}, ${escText(t.vector)}, ${t.power}${t.level} ${t.damageType}): ${on.at ? escText(on.label) : escText(speed.label.toLowerCase())}.${t.effect ? ` ${escText(t.effect)}` : ''}</p><ul class="sr2e-blast">${rows}</ul>`,
      flags: { [SYSTEM_ID]: { toxins: states, ...(on.at ? { toxinOnset: { at: on.at, name: t.name, announced: false } } : {}) } },
    });
  }

  /** v0.61.0: when a toxin of this Speed takes effect (0 = now) and how to say it. */
  static #onsetFor(speed: string): { at: number; label: string } {
    const now = sysNow();
    const o = toxinOnset({ speed, worldTime: now });
    return o.immediate || o.seconds <= 0 ? { at: 0, label: '' } : { at: o.at, label: toxinOnsetLabel(o.seconds, now, o.at) };
  }

  /** v0.61.0 (active GM): toxins whose onset has come: say so on the card's thread, once. */
  static async toxinOnsetTick(time: number): Promise<void> {
    const recent = [...(((game as any).messages?.contents ?? []) as any[])].slice(-300);
    for (const m of recent) {
      const o = m.getFlag?.(SYSTEM_ID, 'toxinOnset') as { at: number; name: string; announced: boolean } | undefined;
      if (!o || o.announced || !toxinOnsetDue({ at: Number(o.at) }, { worldTime: time })) continue;
      await m.setFlag(SYSTEM_ID, 'toxinOnset', { ...o, announced: true });
      const names = ((m.getFlag(SYSTEM_ID, 'toxins') as any[] | undefined) ?? []).map((t: any) => fromUuidSync(t.targetUuid)?.name).filter(Boolean);
      await ChatMessage.create({ speaker: { alias: tx('SR2E.Card.Actor.sr2e') }, content: `<p><strong>${tx('SR2E.Card.Actor.takesEffectNow', { name: escText(o.name) })}</strong>${(names.length ? tx('SR2E.Card.Actor.resistItOnTheCardAboveWithOn8', { names: escText(names.join(', ')) }) : tx('SR2E.Card.Actor.resistItOnTheCardAbovePlain'))}</p>` });
    }
  }

  /** v0.55.0: expose people to a toxin carried by a weapon (a gas grenade's cloud): a card with a Resist button each. */
  async exposeToxinState(t: ToxinHit, targetUuids: string[], title = ''): Promise<void> {
    const targets = targetUuids.map((u) => fromUuidSync(u)).filter(Boolean) as any[];
    if (!targets.length) return;
    const { from: _from, needsWound: _nw, ...tox } = t;
    const on = SR2Actor.#onsetFor(t.kind === 'disease' ? 'immediate' : String(t.speed ?? 'immediate'));
    // v0.81.1 (FX-APP design 2): the exposer, the toxin card's real source for the routine rule (chat.ts onResistToxin).
    const states = targets.map((a) => ({ ...tox, targetUuid: a.uuid as string, kind: t.kind || 'toxin', speed: t.speed ?? 'immediate', effect: t.effect ?? '', sourceUuid: this.uuid as string, ...(on.at ? { onsetAt: on.at } : {}) }));
    const rows = states.map((_st, i) => `<li>${escText(targets[i].name)} <button type="button" data-sr2e-action="resistToxin" data-index="${i}">${tx('SR2E.Card.Actor.resist')}</button></li>`).join('');
    await ChatMessage.create({
      speaker: ChatMessage.getSpeaker({ actor: this }),
      content: `<p><strong>${escText(title || t.name)}</strong>: ${escText(t.name)} (${escText(t.vector)}, ${t.power}${t.level} ${t.damageType})${on.at ? `: ${escText(on.label)}` : ''}.</p><ul class="sr2e-blast">${rows}</ul>`,
      flags: { [SYSTEM_ID]: { toxins: states, ...(on.at ? { toxinOnset: { at: on.at, name: t.name, announced: false } } : {}) } },
    });
  }

  /** v0.55.0 (GM): two blasts at one spot combine (RULES.COMBAT.blastCombine): one card with the combined Power for those caught by both. */
  static async combineBlastCards(later: any, earlier: any): Promise<boolean> {
    if (!isGmNow()) return false;
    const a = (earlier?.getFlag?.(SYSTEM_ID, 'damages') as DamageState[] | undefined) ?? [];
    const b = (later?.getFlag?.(SYSTEM_ID, 'damages') as DamageState[] | undefined) ?? [];
    if (!a.length || !b.length) return false;
    const order: DamageLevel[] = ['L', 'M', 'S', 'D'];
    const by = new Map<string, DamageState[]>();
    for (const d of [...a, ...b]) by.set(d.targetUuid, [...(by.get(d.targetUuid) ?? []), d]);
    const damages: DamageState[] = [...by.values()].map((list) => {
      if (list.length === 1) return list[0]!;
      const level = list.map((d) => d.level).sort((x, y) => order.indexOf(y) - order.indexOf(x))[0]!;
      return { ...list[0]!, level, power: combinedBlastPower(list.map((d) => d.power)) };
    });
    const rows = damages.map((d, i) => `<li>${escText(fromUuidSync(d.targetUuid)?.name ?? tx('SR2E.Card.Actor.target'))}: <strong>${d.power}${d.level}</strong> <button type="button" data-sr2e-action="resist" data-index="${i}">${tx('SR2E.Card.Actor.resist')}</button></li>`).join('');
    const msg = await ChatMessage.create({
      speaker: later.speaker,
      content: `<div class="sr2e-roll"><h3>${tx('SR2E.Card.Actor.combinedBlast')}</h3><p>${tx('SR2E.Card.Actor.twoBlastsAtOneSpotThe', { value: Math.round(RULES.COMBAT.blastCombine.fraction * 100) })}</p></div><ul class="sr2e-blast">${rows}</ul>`,
      flags: { [SYSTEM_ID]: { damages, damage: damages[0] } },
    });
    for (const m of [earlier, later]) await m.setFlag(SYSTEM_ID, 'combinedInto', (msg as any)?.id ?? true);
    return true;
  }

  /** Resist a toxin: Body (+ toxin dice, + inhalant dice when inhaled) vs TN = Power; staged down, no armor. */
  async resistToxin(tIn: { name: string; vector: string; power: number; level: DamageLevel; damageType: DamageType; label?: string; kind?: string; incubationHours?: number; intervalHours?: number; recoveries?: number; contagious?: string; from?: string }): Promise<void> {
    // v0.81.1 (D2-2, RB2-1): the toxin often comes from a card's flags: every field is shaped and bounded here, the
    // boundary all routes share (a disease's recoveries, interval and incubation included: 1e9 recoveries made one
    // that is never shaken off, an interval of 0 a progress card at every time step).
    const t = SR2Actor.#cleanToxin(tIn);
    const attr = RULES.TOXINS.resistAttribute as AttributeKey;
    const d = this.sys.derived ?? {};
    // Protective gear (v0.42.0): a gas mask stops inhaled toxins; respirators and chemsuits add dice.
    const prot = protectionFor(this.protectiveGear(), t.vector);
    if (prot.immune) {
      await ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor: this }), content: `<p><strong>${escText(this.name)}</strong> ${tx('SR2E.Card.Actor.breathesThroughHasNoEffect', { protLabel: escText(prot.label), name: escText(t.name) })}</p>` });
      return;
    }
    // v0.56.0: a critter immune to poisons (or, for a disease, to pathogens) shrugs it off.
    const imm = this.immunities();
    const immHit = t.kind === 'disease' ? imm.pathogens : imm.poisons;
    // v0.78.0 (RULES.BOOK_V78.critterToxins 'dice', the book): the immunity gives 2 × Essence extra dice, not a stop.
    const immDice = immHit && RULES.BOOK_V78.critterToxins.mode === 'dice'
      ? Math.max(0, Math.floor(RULES.BOOK_V78.critterToxins.dicePerEssence * Number(d.essence ?? this.sys.essence ?? 0))) : 0;
    if (immHit && RULES.BOOK_V78.critterToxins.mode !== 'dice') {
      await ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor: this }), content: `<p><strong>${escText(this.name)}</strong> ${tx('SR2E.Card.Actor.isImmuneToHasNoEffect', { part: t.kind === 'disease' ? tx('SR2E.Card.Actor.disease') : tx('SR2E.Card.Actor.poisons'), name: escText(t.name) })}</p>` });
      return;
    }
    // v0.55.0: an antidote patch's dice, used up by this test while it lasts.
    const isToxin = !t.kind || t.kind === 'toxin';
    const anti = isToxin ? this.getFlag?.(SYSTEM_ID, 'antidote') as { dice: number; until: number; name: string } | undefined : undefined;
    const antiDice = anti && sysNow() <= anti.until ? Math.max(0, Number(anti.dice) || 0) : 0;
    if (anti) await clearFlag(this, 'antidote');
    // v0.58.0: a cyber filtration system for this vector.
    const filt = isToxin || t.kind === 'drug' ? this.filtrationFor(t.vector) : { dice: 0, label: '' };
    // v0.72.0 (O9): a nephritic screen helps against blood-borne toxins (injected, ingested); (O11) Toughness if set to.
    const neph = isToxin || t.kind === 'drug' ? nephriticDice(d.bio?.vitals ?? { bloodToxinDice: 0, toxinVectors: [] }, t.vector) : 0;
    const toughT = t.kind === 'disease' ? 0 : toughnessDice(d.vitals ?? { toughnessDice: 0, toughnessOnStun: false, toughnessOnToxins: false }, 'toxin');
    const dice = toxinResistDice({ attribute: this.sys.attributes[attr].total, toxinDice: d.toxinDice ?? 0, inhalantDice: d.bio?.inhalantDice ?? 0, vector: t.vector }) + prot.dice + antiDice + filt.dice + neph + toughT + immDice;
    // v0.78.0 (RULES.BOOK_V78.toxinBioware 'power'): a toxin extractor or tracheal filter lowers the Power (not for disease).
    const power = t.kind === 'disease' ? t.power : toxinPower(t.power, d.bio?.toxinPowerOff, t.vector);
    const powerCut = t.power - power;
    const cutBy = t.vector === RULES.TOXINS.inhalantVector ? tx('SR2E.Card.Actor.trachealFilter') : tx('SR2E.Card.Actor.toxinExtractor');
    if (powerCut > 0 && power <= 0) {
      await ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor: this }), content: `<p><strong>${escText(this.name)}</strong>${tx('SR2E.Card.Actor.sTakesThePowerOfTo', { cutBy, name: escText(t.name) })}</p>` });
      return;
    }
    const rolls: any[] = [];
    const result = await successTest({ dice, targetNumber: Math.max(RULES.MIN_TARGET_NUMBER, power), roll: foundryRoller(rolls) });
    const extra = dice - prot.dice - antiDice - filt.dice - neph - toughT - immDice - (this.sys.attributes[attr].total as number);
    // v0.89.3: the head ("Resist X", or "Resist infection: X" for a disease) is chosen before the label is built, so
    // the text can be translated. v0.89.5: a caller names where the dose came from (`from`) instead of passing an
    // English label for the head to rewrite; a caller's own label is used as it is.
    const head = t.label != null ? t.label
      : t.from ? (t.kind === 'disease' ? tx('SR2E.Card.Actor.resistInfectionFrom', { name: t.name, from: t.from }) : tx('SR2E.Card.Actor.resistFrom', { name: t.name, from: t.from }))
      : (t.kind === 'disease' ? tx('SR2E.Card.Actor.resistInfection2', { name: t.name }) : tx('SR2E.Card.Actor.resist6', { name: t.name }));
    const label = `${head} ${power}${t.level} ${t.damageType} (${extra ? tx('SR2E.Card.Actor.toxinDice', { attr: cap(attr), mark: extra > 0 ? '+' : '', extra }) : cap(attr)}${prot.dice ? `, ${prot.label} +${prot.dice}` : ''}${antiDice ? `, ${anti!.name} +${antiDice}` : ''}${filt.dice ? `, ${filt.label} +${filt.dice}` : ''}${neph ? tx('SR2E.Card.Actor.nephriticScreen', { neph }) : ''}${toughT ? tx('SR2E.Card.Actor.toughness', { toughT }) : ''}${immDice ? tx('SR2E.Card.Actor.immunityTo', { part: t.kind === 'disease' ? tx('SR2E.Card.Actor.pathogens') : tx('SR2E.Card.Actor.poisons'), immDice }) : ''}${powerCut > 0 ? tx('SR2E.Card.Actor.power2', { cutBy, powerCut }) : ''})`;
    // A disease (v0.42.0): any damage left means infected; the disease does its harm later.
    if (t.kind === 'disease') {
      await this.#post(this.#snapshot(label, result, {
        kind: 'disease',
        disease: { name: t.name, mode: 'infect', level: t.level, damageType: t.damageType, power: t.power, intervalHours: t.intervalHours ?? 24, incubationHours: t.incubationHours ?? 24, needed: t.recoveries || RULES.HEALTH.disease.recoveries,
          ...(t.contagious ? { contagious: t.contagious } : {}), ...(t.from ? { from: t.from } : {}) },
      }), result, rolls);
      return;
    }
    await this.#post(this.#snapshot(label, result, {
      kind: 'soak',
      soak: { mode: 'stage', noun: 'damage', level: t.level, type: t.damageType, body: this.sys.attributes.body.total, before: { ...this.#monitor() } },
    }), result, rolls);
  }

  /** v0.81.1 (D2-2): a toxin, drug or disease as `resistToxin` takes it, shaped and bounded. */
  static #cleanToxin(t: any): { name: string; vector: string; power: number; level: DamageLevel; damageType: DamageType; label?: string; kind?: string; incubationHours?: number; intervalHours?: number; recoveries?: number; contagious?: string; from?: string } {
    const str = (v: unknown, max: number) => (typeof v === 'string' ? v.slice(0, max) : '');
    const kind = ['toxin', 'drug', 'disease'].includes(String(t?.kind ?? '')) ? String(t.kind) : undefined;
    const D = RULES.HEALTH.disease;
    return {
      name: str(t?.name, 120) || 'Toxin', vector: str(t?.vector, 40), power: safeInt(t?.power, 0, 60, 0),
      level: (['L', 'M', 'S', 'D'].includes(String(t?.level)) ? String(t.level) : 'L') as DamageLevel,
      damageType: (String(t?.damageType) === 'stun' ? 'stun' : 'physical') as DamageType,
      ...(typeof t?.label === 'string' ? { label: str(t.label, 200) } : {}),
      ...(kind ? { kind } : {}),
      ...(t?.incubationHours != null ? { incubationHours: safeInt(t.incubationHours, 0, 24 * 365, 24) } : {}),
      ...(t?.intervalHours != null ? { intervalHours: safeInt(t.intervalHours, 1, 24 * 365, 24) } : {}),
      ...(t?.recoveries != null ? { recoveries: safeInt(t.recoveries, 1, Math.max(30, 3 * Number(D.recoveries ?? 3)), Number(D.recoveries ?? 3)) } : {}),
      ...(['airborne', 'contact', 'blood'].includes(String(t?.contagious ?? '')) ? { contagious: String(t.contagious) } : {}),
      ...(typeof t?.from === 'string' ? { from: str(t.from, 200) } : {}),
    };
  }

  /** A disease's progress test (v0.42.0): Body (+ toxin dice, + care) vs its Power; no damage left counts toward recovery. */
  async rollDiseaseTick(index: number): Promise<SuccessTestResult | null> {
    const dz: any = (this.sys.diseases ?? [])[index];
    if (!dz) {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.thatDiseaseIsGone'));
      return null;
    }
    const attr = RULES.HEALTH.disease.attribute as AttributeKey;
    const care = dz.treated ? RULES.HEALTH.disease.treatmentDice : 0;
    // v0.78.0 review fix (RULES.BOOK_V78.critterToxins 'dice'): immunity to pathogens helps on every progress test too.
    const immDice = RULES.BOOK_V78.critterToxins.mode === 'dice' && this.immunities().pathogens
      ? Math.max(0, Math.floor(RULES.BOOK_V78.critterToxins.dicePerEssence * Number(this.sys.derived?.essence ?? this.sys.essence ?? 0))) : 0;
    const dice = toxinResistDice({ attribute: this.sys.attributes[attr].total, toxinDice: this.sys.derived?.toxinDice ?? 0, inhalantDice: 0, vector: '' }) + care + immDice;
    return this.#runTest(tx('SR2E.Card.Actor.progressesVs', { dzName: dz.name, attr: cap(attr), part: care ? tx('SR2E.Card.Actor.treated', { care }) : '', part2: immDice ? tx('SR2E.Card.Actor.immunityToPathogens', { immDice }) : '', dzPower: dz.power, dzLevel: dz.level, dzDamageType: dz.damageType }), dice, {
      targetNumber: Math.max(RULES.MIN_TARGET_NUMBER, dz.power), noPenalties: true,
    }, { kind: 'disease', disease: { name: dz.name, mode: 'tick', index, level: dz.level as DamageLevel, damageType: dz.damageType as DamageType, power: dz.power, intervalHours: dz.intervalHours, incubationHours: 0, needed: dz.needed, before: { ...this.#monitor() } } });
  }

  /**
   * v0.48.0: a carrier passes a contagious disease on (RULES.HEALTH.contagion): airborne to everyone
   * within reach of their token, contact and blood to the people given (else the user's targets).
   * Posts an exposure card with a Resist button each.
   */
  async spreadDisease(index: number, targetUuids: string[] | null = null): Promise<number> {
    const d = (this.sys.diseases ?? [])[index] as DiseaseEntry | undefined;
    const now = sysNow();
    const problem = contagionProblem(d ?? null, now);
    if (problem) { ui.notifications?.warn?.(escHtml(problem)); return 0; }
    const reach = contagionReach(d!.contagious ?? '');
    const mine = new Set(this.selfUuids());
    let uuids: string[] = [];
    if (targetUuids?.length) uuids = targetUuids;
    else if (reach === 'nearby') {
      const t = attackerToken(this);
      if (!t) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.hasNoTokenOnThisScene', { name: escHtml(this.name) })); return 0; }
      uuids = tokensNear(t.center, RULES.HEALTH.contagion.radiusMetres).map((e) => e.token.actor?.uuid).filter(Boolean);
    } else uuids = [...((game as any).user?.targets ?? [])].map((t: any) => t.actor?.uuid).filter(Boolean);
    const targets = [...new Set(uuids)].filter((u) => !mine.has(u)).map((u) => fromUuidSync(u) as any)
      .filter((a: any) => a && a.system?.attributes && !['spirit', 'vehicle', 'ic', 'host', 'site', 'barrier'].includes(a.type));
    if (!targets.length) {
      ui.notifications?.warn?.(reach === 'nearby' ? tx('SR2E.Notify.Actor.nobodyIsWithinMOf', { contagionRadiusMetres: RULES.HEALTH.contagion.radiusMetres, name: escHtml(this.name) }) : tx('SR2E.Notify.Actor.targetThePeopleTouches', { name: escHtml(this.name), part: d!.contagious === 'blood' ? tx('SR2E.Notify.Actor.bloodToBlood') : '' }));
      return 0;
    }
    const caught = caughtFrom(d!, this.name as string);
    const states = targets.map((a: any) => ({ targetUuid: a.uuid as string, ...caught, from: this.name as string }));
    const rows = states.map((_x, i) => `<li>${escText(targets[i].name)} <button type="button" data-sr2e-action="resistToxin" data-index="${i}">${tx('SR2E.Card.Actor.resist')}</button></li>`).join('');
    await ChatMessage.create({
      speaker: ChatMessage.getSpeaker({ actor: this }),
      content: `<p><strong>${escText(d!.name)}</strong> ${tx('SR2E.Card.Actor.spreadsFrom', { name: escText(this.name), contagious: escText(d!.contagious), caughtPower: caught.power, caughtLevel: caught.level, caughtDamageType: caught.damageType })}</p><ul class="sr2e-blast">${rows}</ul>`,
      flags: { [SYSTEM_ID]: { toxins: states } },
    });
    return targets.length;
  }

  async #resolveDisease(snap: TestSnapshot): Promise<Resolved> {
    const dz = snap.disease!;
    const level = resolveResistance(dz.level, snap.successes);
    if (dz.applied) return { html: `<p><em>${tx('SR2E.Card.Actor.alreadyAppliedAdjustByHandIf')}</em></p>`, flags: {}, snap };
    const now = sysNow();
    const list: any[] = [...(this.sys.diseases ?? [])].map((x: any) => ({ ...x }));
    if (dz.mode === 'infect') {
      if (!level) return { html: `<p><strong>${tx('SR2E.Card.Actor.fightsOff', { name: escText(this.name), dzName: escText(dz.name) })}</strong></p>`, flags: {}, snap: { ...snap, disease: { ...dz, applied: true } } };
      // v0.48.0: already carrying it (caught twice from contagion or bites): nothing new.
      if (list.some((x: any) => x.name === dz.name)) return { html: `<p>${tx('SR2E.Card.Actor.alreadyHas', { name: escText(this.name), dzName: escText(dz.name) })}</p>`, flags: {}, snap: { ...snap, disease: { ...dz, applied: true } } };
      list.push({ name: dz.name, power: dz.power, level: dz.level, damageType: dz.damageType, intervalHours: dz.intervalHours, nextAt: now + dz.incubationHours * 3600, recovered: 0, needed: Math.max(1, dz.needed), pending: false, treated: false,
        contagious: dz.contagious ?? '', infectedAt: now, incubationHours: dz.incubationHours, source: dz.from ?? '' });
      await this.update({ 'system.diseases': list });
      return { html: `<p><strong>${tx('SR2E.Card.Actor.isInfectedWith', { name: escText(this.name), dzName: escText(dz.name) })}</strong> ${tCount(dz.incubationHours, 'SR2E.Card.Actor.itTakesHoldInHoursThen', { dzIntervalHours: dz.intervalHours })}</p>`, flags: {}, snap: { ...snap, disease: { ...dz, applied: true } } };
    }
    const i = dz.index ?? -1;
    const cur = list[i];
    if (!cur || cur.name !== dz.name) return { html: `<p><em>${tx('SR2E.Card.Actor.theDiseaseChangedSinceThisWas')}</em></p>`, flags: {}, snap };
    let html: string;
    if (!level) {
      cur.recovered += 1;
      if (cur.recovered >= cur.needed) {
        list.splice(i, 1);
        html = `<p><strong>${tx('SR2E.Card.Actor.recoversFrom', { name: escText(this.name), dzName: escText(dz.name) })}</strong></p>`;
      } else {
        html = `<p><strong>${tx('SR2E.Card.Actor.holdsOff', { name: escText(this.name), dzName: escText(dz.name) })}</strong> ${tx('SR2E.Card.Actor.ofTowardRecovery', { curRecovered: escText(cur.recovered), curNeeded: escText(cur.needed) })}</p>`;
      }
    } else {
      const r = applyDamageToMonitor(this.#monitor(), dz.damageType, level, Number(this.sys.derived?.vitals?.overflowBody ?? this.sys.attributes.body.total));
      await this.update({ 'system.monitor.physical': r.monitor.physical, 'system.monitor.stun': r.monitor.stun });
      html = `<p>${escText(dz.name)}: ${dz.damageType === 'stun'
        ? tx('SR2E.Card.Outcome.diseaseTakesStun', { level: `<strong>${level}</strong>`, plural: escText(plural(r.boxes, 'box')), status: escText(statusText(r.status)) })
        : tx('SR2E.Card.Outcome.diseaseTakesPhysical', { level: `<strong>${level}</strong>`, plural: escText(plural(r.boxes, 'box')), status: escText(statusText(r.status)) })}</p>`;
    }
    if (list[i] === cur) { cur.pending = false; cur.nextAt = now + cur.intervalHours * 3600; }
    await this.update({ 'system.diseases': list });
    return { html, flags: {}, snap: { ...snap, disease: { ...dz, applied: true } } };
  }

  /** Drug addiction (v0.42.0): a test after a dose, or kicking the habit after enough days clean. */
  async drugAddictionTest(drug: string, mode: 'dose' | 'kick' = 'dose'): Promise<SuccessTestResult | null> {
    const a: any = (this.sys.addictions ?? []).find((x: any) => x.drug === drug);
    if (!a) return null;
    const now = sysNow();
    if (mode === 'kick') {
      const st = withdrawalState(a, now);
      if (!st.canKick) {
        ui.notifications?.warn?.(tx('SR2E.Notify.Actor.hasBeenCleanOfForDay', { name: escHtml(this.name), drug: escHtml(drug), stDaysClean: st.daysClean, addictionKickDays: RULES.HEALTH.addiction.kickDays }));
        return null;
      }
      return this.#runTest(tx('SR2E.Card.Actor.kickTheHabitWillpowerVs', { drug, rating: a.rating }), this.sys.attributes.willpower.total, { targetNumber: Math.max(RULES.MIN_TARGET_NUMBER, a.rating) },
        { kind: 'addiction', addiction: { drug, mode: 'kick' } });
    }
    const t = drugAddictionTest(a.rating, a.type, (a.recent ?? []).length);
    return this.#runTest(tx('SR2E.Card.Actor.addictionTestVs', { drug, attribute: cap(t.attribute), rating: a.rating, part: t.tn > a.rating ? tx('SR2E.Card.Actor.forRecentDoses', { value: t.tn - a.rating }) : '', type: a.type }), this.sys.attributes[t.attribute].total, { targetNumber: t.tn },
      { kind: 'addiction', addiction: { drug, mode: 'dose' } });
  }

  async #resolveAddiction(snap: TestSnapshot): Promise<Resolved> {
    const ad = snap.addiction!;
    const list: any[] = [...(this.sys.addictions ?? [])].map((x: any) => ({ ...x }));
    const a = list.find((x) => x.drug === ad.drug);
    if (!a) return { html: '', flags: {}, snap };
    const ok = snap.successes > 0;
    if (ad.applied) return { html: `<p><em>${tx('SR2E.Card.Actor.alreadyAppliedAdjustByHandIf')}</em></p>`, flags: {}, snap };
    let html: string;
    if (ad.mode === 'kick') {
      if (ok) { a.addicted = false; a.dosesAddicted = 0; a.withdrawalNoted = false; a.recent = []; }
      html = ok ? `<p><strong>${tx('SR2E.Card.Actor.kicksTheHabit', { name: escText(this.name), adDrug: escText(ad.drug) })}</strong></p>` : `<p><strong>${tx('SR2E.Card.Actor.isStillHookedOn', { name: escText(this.name), adDrug: escText(ad.drug) })}</strong></p>`;
    } else {
      if (!ok && !a.addicted) a.addicted = true;
      html = ok ? `<p>${tx('SR2E.Card.Actor.doesnTGetHookedOnThis', { name: escText(this.name), adDrug: escText(ad.drug) })}</p>` : `<p><strong>${tx('SR2E.Card.Actor.isAddictedTo', { name: escText(this.name), adDrug: escText(ad.drug) })}</strong> ${tx('SR2E.Card.Actor.withoutADoseForHoursWithdrawal', { type: escText(a.type), addictionWithdrawalHours: RULES.HEALTH.addiction.withdrawalHours, addictionWithdrawalTn: RULES.HEALTH.addiction.withdrawalTn })}</p>`;
    }
    await this.update({ 'system.addictions': list });
    return { html, flags: {}, snap: { ...snap, addiction: { ...ad, applied: true } } };
  }

  /** Take a dose of a drug: its bonuses last for its duration, then the crash comes. */
  async takeDrug(itemId: string): Promise<boolean> {
    return this.#oneAtATime('takeDrug', false, () => this.#takeDrug(itemId));
  }

  async #takeDrug(itemId: string): Promise<boolean> {
    const it: any = [...this.items].find((i: any) => i.id === itemId);
    const t = it?.system?.toxin;
    if (!it || t?.kind !== 'drug') {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.thatIsNotADrug'));
      return false;
    }
    if (!isCarried(it)) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.notCarried', { name: escHtml(it.name) })); return false; }
    if ((it.system.quantity ?? 0) <= 0) {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.hasNoLeft', { name: escHtml(this.name), name2: escHtml(it.name) }));
      return false;
    }
    if (!(await this.useAction('drug', tx('SR2E.Card.Actor.taking', { name: it.name })))) return false;
    await it.update({ 'system.quantity': it.system.quantity - 1 });
    // v0.61.0: a critter immune to drugs (or poisons) feels nothing.
    // v0.78.0 (RULES.BOOK_V78.critterToxins 'dice'): the immunity only adds resistance dice (to a drug's harm), it doesn't stop it.
    // Review fix: an explicit immunity to drugs still stops one; immunity to poisons stops a dose only under the old way.
    if ((this.immunities() as Record<string, boolean>).drugs === true || (RULES.BOOK_V78.critterToxins.mode !== 'dice' && drugImmunity(this.immunities() as Record<string, boolean>))) {
      await ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor: this }), content: `<p><strong>${escText(this.name)}</strong> ${tx('SR2E.Card.Actor.takesImmuneItHasNoEffect', { name: escText(it.name) })}</p>` });
      return true;
    }
    const combat: any = (game as any).combat;
    const now = sysNow();
    const ends = effectEnds({ round: combat?.started ? Number(combat.round ?? 0) : null, worldTime: now, seconds: (t.durationMinutes ?? 0) * 60, combatId: combat?.started ? String(combat.id ?? '') : null });
    // Addiction (v0.42.0): track recent doses; an addict's tolerance takes points off the bonuses.
    const addictions: any[] = [...(this.sys.addictions ?? [])].map((x: any) => ({ ...x }));
    let add: any = null;
    let loss = 0;
    if ((t.addiction ?? 0) > 0) {
      add = addictions.find((x) => x.drug === it.name);
      if (!add) { add = { drug: it.name, rating: t.addiction, type: t.addictionType ?? 'mental', recent: [], lastDose: now, addicted: false, dosesAddicted: 0, withdrawalNoted: false }; addictions.push(add); }
      add.rating = t.addiction; add.type = t.addictionType ?? add.type;
      loss = add.addicted ? toleranceLoss(add.dosesAddicted) : 0;
      add.recent = [...recentDoses(add.recent ?? [], now), now];
      add.lastDose = now;
      add.withdrawalNoted = false;
      if (add.addicted) add.dosesAddicted += 1;
    }
    const b = applyTolerance({ attributes: { ...t.attributes }, reaction: t.reaction ?? 0, initiativeDice: t.initiativeDice ?? 0 }, loss);
    // v0.61.0: effects beyond attributes (armor, TNs, movement, ignoring wounds).
    const xb = drugEffectBundle(t.extra ?? {});
    const extra = { ballistic: xb.ballistic ?? 0, impact: xb.impact ?? 0, testsTn: xb.testsTn ?? 0, perceivedTn: xb.perceivedTn ?? 0, attackedTn: xb.attackedTn ?? 0, movementFactor: xb.movementFactor ?? 1, ignoreWounds: Boolean(xb.ignoreWounds), stunIgnoreBoxes: xb.stunIgnoreBoxes ?? 0 };
    const extraLines = drugEffectLines(t.extra ?? {});
    const entry = { name: it.name, attributes: b.attributes, reaction: b.reaction, initiativeDice: b.initiativeDice, extra, round: ends.round, worldTime: ends.worldTime, combatId: ends.combatId ?? '', crashPower: t.crashPower ?? 0, crashLevel: t.crashLevel ?? '' };
    // v0.72.0 (O8): a dose of a drug still active refreshes (or extends) it instead of adding its bonuses again
    // (RULES.HEALTH_V72.drugs.doses; 'stack' = the old way), and is an overdose to resist.
    const dosed = doseDrug((this.sys.drugs ?? []) as any[], entry as any, {
      seconds: (t.durationMinutes ?? 0) * 60, now, round: combat?.started ? Number(combat.round ?? 0) : null, combatId: combat?.started ? String(combat.id ?? '') : null,
      drug: { power: t.power, level: t.level, crashPower: t.crashPower, vector: t.vector },
    });
    await this.update({ 'system.drugs': dosed.list, ...(add ? { 'system.addictions': addictions } : {}) });
    const doseNote = dosed.mode === 'refresh' ? ` <em>${tx('SR2E.Card.Actor.alreadyInEffectTheDoseRenews', { dosedDoses: dosed.doses })}</em>`
      : dosed.mode === 'extend' ? ` <em>${tx('SR2E.Card.Actor.alreadyInEffectItLastsA', { dosedDoses: dosed.doses })}</em>` : '';
    const bonus = [...Object.entries(b.attributes ?? {}).filter(([, v]) => v).map(([k, v]) => `${cap(k)} ${Number(v) > 0 ? '+' : ''}${v}`),
      ...(b.reaction ? [tx('SR2E.Card.Actor.reaction', { reaction: b.reaction })] : []), ...(b.initiativeDice ? [tx('SR2E.Card.Actor.d6Initiative', { initiativeDice: b.initiativeDice })] : []), ...extraLines].join(', ');
    await ChatMessage.create({
      speaker: ChatMessage.getSpeaker({ actor: this }),
      content: `<p><strong>${escText(this.name)}</strong> ${tCount(Number(t.durationMinutes), 'SR2E.Card.Actor.takesForMinutes', { name: escText(it.name), part: bonus ? `: ${escText(bonus)}` : '', part2: loss ? ` <em>${tx('SR2E.Card.Actor.toleranceOnEachBonus', { loss })}</em>` : '', doseNote, part3: t.effect ? ` ${escText(t.effect)}` : '' })}</p>`,
    });
    if (dosed.overdose) {
      const od = dosed.overdose;
      const hit: ToxinHit = { name: od.name, vector: od.vector, power: od.power, level: od.level, damageType: od.damageType, kind: 'toxin', from: this.name as string, needsWound: false, speed: 'immediate' };
      await this.exposeToxinState(hit, [this.uuid as string], tx('SR2E.Card.Actor.overdoseDoseWhileActive', { name: it.name, value: od.dosesBefore + 1 }));
    }
    if (add && RULES.HEALTH.addiction.auto && !add.addicted) await this.drugAddictionTest(it.name, 'dose');
    return true;
  }

  /** A drug wears off (or is ended early): its bonuses go, and its crash is posted to resist. */
  async endDrug(index: number): Promise<void> {
    const list = [...(this.sys.drugs ?? [])];
    const d: any = list[index];
    if (!d) return;
    list.splice(index, 1);
    await this.update({ 'system.drugs': list });
    const crash = d.crashLevel && d.crashPower > 0;
    await ChatMessage.create({
      speaker: ChatMessage.getSpeaker({ actor: this }),
      content: `<p>${tx('SR2E.Card.Actor.sWearsOff', { name: escText(this.name), name2: escText(d.name) })}</p>${crash ? `<p><button type="button" data-sr2e-action="drugCrash">${tx('SR2E.Card.Actor.resistTheCrashStun', { crashPower: escText(d.crashPower), crashLevel: escText(d.crashLevel) })}</button></p>` : ''}`,
      ...(crash ? { flags: { [SYSTEM_ID]: { drugCrash: { actorUuid: this.uuid, name: d.name, power: d.crashPower, level: d.crashLevel } } } } : {}),
    });
  }

  /** Falling, fire, drowning, cold or fatigue (RULES.HAZARDS). `amount`: metres, intensity, turns, severity or hours. */
  async resistHazard(kind: 'falling' | 'fire' | 'drowning' | 'cold' | 'fatigue' | 'radiation' | 'suffocation' | 'heat' | 'electricity', amount: number | string, more: { hours?: number; insulation?: number } = {}): Promise<void> {
    // v0.56.0: a critter immune to fire takes nothing from it.
    if (kind === 'fire' && this.immunities().fire) {
      await ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor: this }), content: `<p><strong>${escText(this.name)}</strong> ${tx('SR2E.Card.Actor.isImmuneToFire')}</p>` });
      return;
    }
    const armor = { impact: this.armorRating('impact'), ballistic: this.armorRating('ballistic') };
    // v0.72.0 (O12): heat (like cold) and electric shocks (RULES.HEALTH_V72.hazards).
    if (kind === 'heat') {
      if (heatStoppedByFireImmunity() && this.immunities().fire) {
        await ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor: this }), content: `<p><strong>${escText(this.name)}</strong> ${tx('SR2E.Card.Actor.isImmuneToFireAndHeat')}</p>` });
        return;
      }
      const h = heatTest(String(amount));
      if (!h) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.heatExposureIsSwitchedOffHouse')); return; }
      return this.#drainTest({ label: h.label, attribute: h.attribute as AttributeKey, targetNumber: h.tn, level: h.level, type: h.type, poolDice: 0, noun: 'damage' });
    }
    if (kind === 'electricity') {
      const e = electricShock(String(amount), armor, { insulation: more.insulation ?? 0 });
      if (!e) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.electricShocksAreSwitchedOffHouse')); return; }
      await this.resistDamage({ power: e.power, level: e.level, type: e.type, armor: e.armor, ...(RULES.GEAR.cyberDamage.nonAttack ? { cyberCheck: { location: '' } } : {}) });
      if (e.shock) await this.applyElementEffect('shock', e.power);
      return;
    }
    // Radiation and suffocation (v0.42.0).
    if (kind === 'radiation') {
      const r = radiationTest(Number(amount) || 0, more.hours ?? 1);
      // At most a day's hourly tests per call (RADIATION_TESTS_PER_CALL); v0.81.0 (D2-8): the card says when more are owed.
      const rolled = Math.min(RADIATION_TESTS_PER_CALL, r.tests);
      for (let h = 1; h <= rolled; h++) {
        await this.#drainTest({ label: tx('SR2E.Card.Actor.radiation', { amount, part: r.tests > 1 ? tx('SR2E.Card.Actor.hourOf', { h, tests: r.tests }) : '' }), attribute: 'body', targetNumber: r.tn, level: r.level, type: r.type, poolDice: 0, noun: 'damage', physicalNote: ', physical' });
      }
      if (r.tests > rolled) await ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor: this }), content: `<p><em>${tCount(r.tests - rolled, 'SR2E.Card.Actor.moreHourlyRadiationTestsAreNot', { name: escText(this.name), radiationTestsPerCall: RADIATION_TESTS_PER_CALL, tn: r.tn, level: r.level, type: r.type })}</em></p>` });
      await this.addRadiation(Number(amount) || 0, more.hours ?? 1);
      return;
    }
    // v0.72.0 (O9): extended-volume lungs hold the breath longer before the turns count.
    // v0.80.0 (RULES.URR_V80.hsBreathHold): 30 s of held breath per point of Body before the turns count.
    const lungs = Math.max(0, Number(this.sys.derived?.bio?.vitals?.breathTurns ?? 0)) + breathHoldTurns(Number(this.sys.attributes?.body?.total ?? 0));
    if (lungs > 0 && (kind === 'drowning' || kind === 'suffocation')) {
      const left = turnsWithoutAir(Number(amount) || 0, lungs);
      if (left <= 0) { await ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor: this }), content: `<p><strong>${escText(this.name)}</strong> ${tx('SR2E.Card.Actor.stillHoldsTheirBreathCombatTurns', { part: breathHoldTurns(Number(this.sys.attributes?.body?.total ?? 0)) ? tx('SR2E.Card.Actor.heldBreath') : tx('SR2E.Card.Actor.extendedVolumeLungs'), lungs })}</p>` }); return; }
      amount = left;
    }
    if (kind === 'suffocation') {
      const s = RULES.HEALTH.suffocation;
      return this.#drainTest({ label: tCount(Number(amount), 'SR2E.Card.Actor.suffocationTurnsWithoutAir'), attribute: 'body', targetNumber: suffocationTn(Number(amount) || 0), level: s.level, type: s.type, poolDice: 0, noun: 'damage' });
    }
    if (kind === 'falling') {
      // v0.80.0 (RULES.URR_V80.hsFalling 'urr'): Power half the metres, level by height, no armor; 2 m or less is nothing.
      const f = fallingDamageUrr(Number(amount) || 0) ?? fallingDamage(Number(amount) || 0, armor);
      if (f.power <= 0 || !f.level) return;
      return this.resistDamage({ power: f.power, level: f.level, type: 'physical', armor: f.armor, ...(RULES.GEAR.cyberDamage.nonAttack ? { cyberCheck: { location: '' } } : {}) });
    }
    if (kind === 'fire') {
      const f = fireDamage(String(amount), armor);
      return this.resistDamage({ power: f.power, level: f.level, type: 'physical', armor: f.armor, ...(RULES.GEAR.cyberDamage.nonAttack ? { cyberCheck: { location: '' } } : {}) });
    }
    const e = exposureTest(kind, amount);
    return this.#drainTest({ label: e.label, attribute: RULES.HAZARDS[kind].attribute as AttributeKey, targetNumber: e.tn, level: e.level, type: e.type, poolDice: 0, noun: 'damage' });
  }

  /**
   * v0.48.0: build up a radiation dose (rating × hours, after any decay since the last update); at
   * each RULES.HEALTH.radiationSickness stage the character has radiation sickness of that stage
   * (a disease; a worse stage replaces a milder one).
   */
  async addRadiation(rating: number, hours: number): Promise<{ dose: number; stage: number }> {
    const now = sysNow();
    if (!RULES.HEALTH.radiationSickness.enabled) return { dose: Number(this.sys.radiation?.dose ?? 0), stage: -1 };
    const rad = this.sys.radiation ?? { dose: 0, at: now };
    const days = Math.max(0, Math.floor((now - Number(rad.at ?? now)) / 86400));
    const before = decayedDose(Number(rad.dose ?? 0), days);
    const dose = Math.round((before + radiationDose(rating, hours)) * 10) / 10;
    // The stage held now (the sickness entry), not the decayed dose's: a decayed dose never lowers it.
    const stages = RULES.HEALTH.radiationSickness.stages;
    const held = [...(this.sys.diseases ?? [])].filter((x: any) => isRadiationSickness(x)).map((x: any) => stages.findIndex((st) => st.name === x.name));
    const was = Math.max(sicknessStage(before), ...held, -1);
    const stage = sicknessStage(dose);
    const up: Record<string, unknown> = { 'system.radiation': { dose, at: now } };
    let note = '';
    if (stage > was && stage >= 0) {
      const entry = sicknessEntry(stage, now)!;
      const list: any[] = [...(this.sys.diseases ?? [])].map((x: any) => ({ ...x })).filter((x: any) => !isRadiationSickness(x));
      list.push(entry);
      up['system.diseases'] = list;
      note = ` <strong>${escText(entry.name)}</strong> ${tx('SR2E.Card.Actor.setsInEveryHoursCleanTests', { entryPower: entry.power, entryLevel: escText(entry.level), entryDamageType: escText(entry.damageType), entryIntervalHours: entry.intervalHours, entryNeeded: entry.needed })}`;
    }
    await this.update(up);
    await ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor: this }), content: `<p>${tx('SR2E.Card.Actor.sRadiationDose', { name: escText(this.name) })} <strong>${dose}</strong> (+${radiationDose(rating, hours)}).${note}</p>` });
    return { dose, stage };
  }

  /**
   * v0.48.0: every actor whose timers run: world actors, plus the synthetic actors of unlinked tokens
   * on every scene (their diseases, drugs and statuses are their own).
   */
  static tickActors(): SR2Actor[] {
    const out: SR2Actor[] = [...((game as any).actors ?? [])] as SR2Actor[];
    // v0.81.0 (D2-9): a Set, not out.includes per token (that was quadratic in the tokens).
    const seen = new Set<any>(out);
    const all: any = (game as any).scenes;
    const scenes: any[] = all?.contents ?? (all && typeof all[Symbol.iterator] === 'function' ? [...all] : []);
    for (const sc of scenes) {
      const coll: any = sc?.tokens;
      const tokens: any[] = coll?.contents ?? (coll && typeof coll[Symbol.iterator] === 'function' ? [...coll] : []);
      for (const t of tokens) {
        if (t.actorLink) continue;
        const a = t.actor;
        if (a && !seen.has(a)) { seen.add(a); out.push(a); }
      }
    }
    return out;
  }

  /**
   * v0.70.0: a dying character not yet stabilised takes another Physical box every (Body) Combat Turns of world
   * time, 3 s each, in or out of combat (RULES.FIXES_V70.dyingOutOfCombat; the rate is RULES.CONDITIONS.dying).
   * The boxes already taken are counted in the flag, so ticks from the clock and from combat never add twice.
   */
  static #dyingBusy = new Set<string>();
  static async #dyingWorldTick(a: any, time: number): Promise<void> {
    if (!RULES.FIXES_V70.dyingOutOfCombat || !a?.system?.care || SR2Actor.#dyingBusy.has(a.uuid)) return;
    const sys = a.system;
    if (sys.derived?.status !== 'dying' || sys.care.stabilised) return;
    SR2Actor.#dyingBusy.add(a.uuid);
    try {
      const d = a.getFlag?.(SYSTEM_ID, 'dyingAt') as { t: number; boxes: number } | undefined;
      // Dying from before v0.70.0 (or set by hand): the clock starts now.
      if (!d || !Number.isFinite(Number(d.t))) { await a.setFlag(SYSTEM_ID, 'dyingAt', { t: time, boxes: 0 }); return; }
      const body = Number(sys.attributes?.body?.total ?? 1);
      // v0.80.0 (RULES.URR_V80.hsBleedMinutes): the Revamp's minutes per box; 0 = the book's (Body) Combat Turns.
      const per = bleedTurnsPerBox(body);
      const turns = Math.floor(Math.max(0, time - Number(d.t)) / Math.max(1, Number(RULES.COMBAT_TURN_SECONDS)));
      const due = Math.min(30, Math.floor(turns / per) - Number(d.boxes ?? 0));
      if (due <= 0) return;
      const now = Number(sys.monitor?.physical ?? 0) + due;
      await a.setFlag(SYSTEM_ID, 'dyingAt', { t: Number(d.t), boxes: Number(d.boxes ?? 0) + due });
      await a.update({ 'system.monitor.physical': now });
      await ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor: a }), content: `<p>${tx('SR2E.Card.Actor.isDyingAndTakesNow', { name: escText(a.name), part: due === 1 ? tx('SR2E.Card.Actor.anotherPhysicalBox') : tx('SR2E.Card.Actor.morePhysicalBoxes', { due }), now })}</p>` });
    } finally { SR2Actor.#dyingBusy.delete(a.uuid); }
  }

  /** GM: end drugs and timed statuses that are due (a Combat Turn reached, or the world time passed). */
  static async timedEffects(now: { round?: number | null; worldTime?: number; anyGm?: boolean; combatId?: string | null } = {}): Promise<void> {
    if (!(game as any).user?.isGM) return;
    const active = (game as any).users?.activeGM;
    if (!now.anyGm && active && !isLeadGm()) return;
    const time = now.worldTime ?? sysNow();
    const at = { round: now.round ?? null, worldTime: time, ...(now.combatId !== undefined ? { combatId: now.combatId } : {}) };
    // Timed demolition charges (v0.43.0).
    await SR2Actor.chargeTicks(at);
    // Fires spreading (v0.45.0).
    await SR2Actor.fireTicks(at);
    // v0.61.0: slow toxins taking effect.
    await SR2Actor.toxinOnsetTick(time);
    for (const a of SR2Actor.tickActors()) {
      // v0.81.1 (D2-8): one actor's error (a token actor whose scene was just deleted) no longer stops the others'.
      try {
        const drugs: any[] = [...((a as any).system?.drugs ?? [])];
        for (let i = drugs.length - 1; i >= 0; i--) if (effectEnded(drugs[i], at)) await a.endDrug(i);
        await SR2Actor.#healthTicks(a, time);
        await SR2Actor.#dyingWorldTick(a, time);
        await SR2Actor.#lifestyleTick(a);
        await SR2Actor.#safehouseTick(a, time);
        await SR2Actor.#trainingTick(a, time);
        await SR2Actor.#projectTick(a, time);
        // v0.81.1 (D2-7, RA2-3): the combat whose round ticked, not the GM's viewed one.
        await SR2Actor.burningTick(a, at.round ?? null, (at as any).combatId ?? null);
        await SR2Actor.#repeatPowerTick(a, at.round ?? null, (at as any).combatId ?? null);
        // v0.78.0: effects that end by themselves (Paralyzing Touch's Quickness drain).
        for (const fx of ((a.getFlag?.(SYSTEM_ID, 'powerEffects') as any[] | undefined) ?? []).filter((e: any) => e?.until && effectEnded(e.until, at))) {
          await SR2Actor.setPowerEffect(String(a.uuid), null, String(fx.id));
          await ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor: a }), content: `<p>${tx('SR2E.Card.Actor.wearsOff', { name: escText(a.name), fxName: escText(fx.name) })}</p>` });
        }
        const until = (a.getFlag?.(SYSTEM_ID, 'statusUntil') as Record<string, any> | undefined) ?? {};
        const due = Object.entries(until).filter(([, e]) => e && effectEnded(e, at)).map(([k]) => k);
        if (!due.length) continue;
        for (const id of due) {
          try { await (a as any).toggleStatusEffect?.(id, { active: false }); } catch { /* no status */ }
        }
        // v0.78.0: a flash's TN ends with the Blinded status it set.
        if (due.includes('blind') && a.getFlag?.(SYSTEM_ID, 'flashTn') != null) await clearFlag(a, 'flashTn');
        // v0.73.0 (O41): a timed hold (paralysis for N Combat Turns) leaves no effect entry behind.
        for (const fxId of timedOutHoldIds((a.getFlag?.(SYSTEM_ID, 'powerEffects') as any[] | undefined) ?? [], due)) {
          await SR2Actor.setPowerEffect(String(a.uuid), null, fxId);
        }
        // v0.73.0 live fix: setFlag merges objects, so an ended status is written as null (a dropped key stayed and
        // repeated the "no longer" line on every later time step). Entries that are null count as ended already.
        const rest = Object.fromEntries(Object.entries(until).map(([k, e]) => [k, due.includes(k) ? null : e]));
        try { await a.setFlag(SYSTEM_ID, 'statusUntil', rest); } catch { /* not saved */ }
        await ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor: a }), content: `<p>${tx('SR2E.Card.Actor.isNoLonger', { name: escText(a.name), due: escText(due.join(', ')) })}</p>` });
      } catch (err) {
        console.error('sr2e | timed effects for', (a as any)?.name, err);
      }
    }
  }

  /** v0.61.0: a repeating power used this fight: each new Combat Turn its user is offered "Use again" (it stops when the fight ends). */
  static async #repeatPowerTick(a: any, round: number | null, combatId: string | null = null): Promise<void> {
    const f = a.getFlag?.(SYSTEM_ID, 'repeatPower') as { powerUuid: string; targetUuids: string[]; modifiers?: any[]; exclude?: string[]; name: string; combatId: string; round: number } | undefined;
    if (!f) return;
    const combat: any = SR2Actor.#tickingCombat(combatId);
    // v0.81.1 (D2-7, RA2-3): another combat's round: a power used in a fight still running elsewhere is left alone.
    if (combat?.started && f.combatId && combat.id !== f.combatId && SR2Actor.#tickingCombat(f.combatId)?.started) return;
    if (!combat?.started || combat.id !== f.combatId || incapacitated(a.system?.derived?.status)) { await clearFlag(a, 'repeatPower'); return; }
    if (round === null || !repeatDue({ combatId: f.combatId, round: f.round }, { combatId: combat.id, round })) return;
    await a.setFlag(SYSTEM_ID, 'repeatPower', { ...f, round });
    const owners = [...((game as any).users ?? [])].filter((u: any) => u.isGM || a.testUserPermission?.(u, 'OWNER')).map((u: any) => u.id);
    const { name: _n, combatId: _c, round: _r, ...repeat } = f;
    await ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor: a }), whisper: owners,
      content: `<p>${escText(a.name)}'s <strong>${escText(f.name)}</strong> ${tx('SR2E.Card.Actor.repeatsThisCombatTurn')}</p><p><button type="button" data-sr2e-action="repeatPower">${tx('SR2E.Card.Actor.useAgain')}</button> <span class="hint">${tx('SR2E.Card.Actor.orLetItGoItStops')}</span></p>`,
      flags: { [SYSTEM_ID]: { repeat } } });
  }

  /** Diseases that are due post a progress card; withdrawal setting in is announced once (v0.42.0). */
  static async #healthTicks(a: any, time: number): Promise<void> {
    // v0.55.0: a stim patch's Stun comes back when it wears off.
    const debt = (a.getFlag?.(SYSTEM_ID, 'stimDebt') as Array<{ boxes: number; at: number; name: string }> | undefined) ?? [];
    const due = debt.filter((x) => time >= x.at);
    if (due.length && a.system?.monitor) {
      const back = due.reduce((n, x) => n + Math.max(0, Number(x.boxes) || 0), 0);
      // Cleared first (two quick time steps must not both pay it back); Stun past the track spills into Physical.
      await a.setFlag(SYSTEM_ID, 'stimDebt', debt.filter((x) => time < x.at));
      // v0.70.0: the same overflow as damage (addStun: no box lost on the way).
      const m = addStun(a.system.monitor, back);
      await a.update({ 'system.monitor.stun': m.stun, 'system.monitor.physical': m.physical });
      await ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor: a }), content: `<p><strong>${escText(a.name)}</strong>${tCount(back, 'SR2E.Card.Actor.wearsOffStunBoxesComeBack', { due: due.map((x) => escText(x.name)).join(', ') })}</p>` });
    }
    const dz: any[] = [...(a.system?.diseases ?? [])].map((x: any) => ({ ...x }));
    let changed = false;
    for (let i = 0; i < dz.length; i++) {
      const d = dz[i];
      if (d.pending || time < d.nextAt) continue;
      d.pending = true; changed = true;
      // v0.48.0: a contagious carrier can pass it on from the same card.
      const spread = !contagionProblem(d, time) ? ` <button type="button" data-sr2e-action="spreadDisease" title="${tx('SR2E.Card.Actor.passItOn', { contagious: escText(d.contagious), part: contagionReach(d.contagious) === 'nearby' ? tx('SR2E.Card.Actor.everyoneWithinM', { contagionRadiusMetres: RULES.HEALTH.contagion.radiusMetres }) : tx('SR2E.Card.Actor.thePeopleTargeted') })}">${tx('SR2E.Card.Actor.spread')}</button>` : '';
      await ChatMessage.create({
        speaker: ChatMessage.getSpeaker({ actor: a }),
        content: `<p><strong>${escText(d.name)}</strong> ${tx('SR2E.Card.Actor.worksOnOfTowardRecovery', { name: escText(a.name), power: escText(d.power), level: escText(d.level), damageType: escText(d.damageType), recovered: escText(d.recovered), needed: escText(d.needed) })}</p><p><button type="button" data-sr2e-action="diseaseTick">${tx('SR2E.Card.Actor.resist6', { name: escText(d.name) })}</button>${spread}</p>`,
        flags: { [SYSTEM_ID]: { diseaseTick: { actorUuid: a.uuid, index: i, name: d.name } } },
      });
    }
    if (changed) await a.update({ 'system.diseases': dz });
    // v0.48.0: a radiation dose wears off a little each day.
    const rad = a.system?.radiation;
    if (rad && Number(rad.dose) > 0 && RULES.HEALTH.radiationSickness.decayPerDay > 0) {
      const days = Math.floor((time - Number(rad.at ?? time)) / 86400);
      if (days >= 1) await a.update({ 'system.radiation': { dose: decayedDose(Number(rad.dose), days), at: Number(rad.at ?? time) + days * 86400 } });
    }
    // v0.45.0: recoveries from surgery end; bioware over the Body Index limit risks rejection.
    const rec: Recovery[] = [...(a.system?.recovering ?? [])];
    if (rec.length) {
      const still = recovering(rec, time);
      if (still.length !== rec.length) {
        const done = rec.filter((r) => !still.includes(r));
        await a.update({ 'system.recovering': still });
        await ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor: a }), content: `<p><strong>${escText(a.name)}</strong> ${tCount(done.length, 'SR2E.Card.Actor.hasRecoveredFromSurgeryNowWork', { done: escText(done.map((r) => r.name).join(', ')) })}</p>` });
      }
    }
    const bi = a.system?.derived?.bodyIndex;
    if (bi && sensitiveRejectionTn(rejectionTn(Number(bi.used ?? 0), Number(bi.max ?? 0)), Number(bi.used ?? 0), a.system?.derived?.vitals ?? { sensitive: false }) !== null) {
      const at = Number(a.getFlag?.(SYSTEM_ID, 'rejectionAt') ?? NaN);
      if (!Number.isFinite(at)) { try { await a.setFlag(SYSTEM_ID, 'rejectionAt', nextRejectionAt(time)); } catch { /* not saved */ } }
      else if (time >= at) {
        try { await a.setFlag(SYSTEM_ID, 'rejectionAt', nextRejectionAt(time)); } catch { /* not saved */ }
        await ChatMessage.create({
          speaker: ChatMessage.getSpeaker({ actor: a }),
          content: `<p>${tx('SR2E.Card.Actor.sBodyStrainsAgainstItsBioware', { name: escText(a.name), biUsed: escText(bi.used), biMax: escText(bi.max) })}</p><p><button type="button" data-sr2e-action="rejectionTest">${tx('SR2E.Card.Actor.rejectionTest')}</button></p>`,
          flags: { [SYSTEM_ID]: { rejection: { actorUuid: a.uuid } } },
        });
      }
    }
    const ad: any[] = [...(a.system?.addictions ?? [])].map((x: any) => ({ ...x }));
    const newly = ad.filter((x) => withdrawalState(x, time).withdrawal && !x.withdrawalNoted);
    if (newly.length) {
      for (const x of newly) x.withdrawalNoted = true;
      await a.update({ 'system.addictions': ad });
      await ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor: a }), content: `<p><strong>${tx('SR2E.Card.Actor.isInWithdrawal', { name: escText(a.name) })}</strong> ${tx('SR2E.Card.Actor.fromTnOnEveryTestUntil', { newly: escText(newly.map((x) => x.drug).join(', ')), addictionWithdrawalTn: RULES.HEALTH.addiction.withdrawalTn })}</p>` });
    }
  }

  /** Repair damaged cyberware: the repair skill (RULES.CYBERWARE.repair) vs its TN; a success fixes it. */
  async repairCyberware(itemId: string, opts: { repairer?: any; modifiers?: TargetNumberModifier[] } = {}): Promise<SuccessTestResult | null> {
    const it: any = [...this.items].find((i: any) => i.id === itemId);
    if (!it || it.type !== 'cyberware' || !it.system.damaged) {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.thatCyberwareIsNotDamaged'));
      return null;
    }
    const who: SR2Actor = opts.repairer ?? this;
    const rp = RULES.CYBERWARE.repair;
    const skill = rp.skills.map((n) => who.findSkill(n)).find((x: any) => x && (x.system?.rating ?? 0) > 0);
    const sd = who.#skillDice(skill, false, null, 'intelligence');
    return who.#runTest(tx('SR2E.Card.Actor.repair2', { name: it.name, part: who !== this ? ` (${this.name}'s)` : '', part2: skill ? ` (${skill.name})` : '', sdSuffix: sd.suffix }), sd.dice, {
      targetNumber: rp.tn, modifiers: [...(opts.modifiers ?? []), ...sd.modifiers],
    }, { kind: 'cyberRepair', cyberRepair: { itemId, itemName: it.name, ownerUuid: this.uuid as string } });
  }

  /** A cyberlimb whose own Quickness stands in for this attribute on a test made with it (RULES.GEAR.cyberlimbs, v0.43.0). */
  limbFor(limbId: string | null, attribute: string): { id: string; name: string; quickness: number } | null {
    // v0.47.0: a Strength test (melee defaulting to Strength) uses the limb's own Strength too.
    if (!limbId || !((attribute === 'quickness' && RULES.GEAR.cyberlimbs.quickness) || attribute === 'strength')) return null;
    const l: any = [...(this.sys.derived?.cyber?.limbs ?? [])].find((x: any) => x.id === limbId);
    return l ? { id: l.id, name: l.name, quickness: Number((attribute === 'strength' ? l.strength : l.quickness) ?? 0) } : null;
  }

  // ---------------------------------------------------------------- Gear and combat (v0.43.0)

  /**
   * Roll for cyberware damaged by a hit (RULES.GEAR.cyberDamage): 1d6 per installed item, damaged at or
   * under its chance (higher for a called shot's limb and what it houses). Returns the damaged names.
   */
  async cyberDamageCheck(calledLocation = ''): Promise<string[]> {
    const ware = [...this.items].filter((i: any) => i.type === 'cyberware' && i.system.installed).map((i: any) => ({
      id: i.id, name: i.name, bioware: Boolean(i.system.bioware), damaged: Boolean(i.system.damaged), kind: i.system.kind,
      housedIn: i.system.housedIn ?? '', location: i.system.limb?.location ?? '',
    }));
    const odds = cyberDamageChances(ware, calledLocation);
    if (!odds.length) {
      await ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor: this }), content: `<p>${tx('SR2E.Card.Actor.hasNoWorkingCyberwareToDamage', { name: escText(this.name) })}</p>` });
      return [];
    }
    const rolls: any[] = [];
    const roll = await new Roll(`${odds.length}d6`).evaluate();
    rolls.push(roll);
    const results: number[] = (roll as any).dice?.[0]?.results?.map((r: any) => Number(r.result)) ?? [];
    const hit = odds.filter((o, i) => (results[i] ?? 6) <= o.chance);
    for (const h of hit) {
      const it: any = this.items.get?.(h.id) ?? [...this.items].find((i: any) => i.id === h.id);
      if (it) await it.update({ 'system.damaged': true });
    }
    const rows = odds.map((o, i) => `<li>${tx('SR2E.Card.Actor.damagedOn', { name: escText(o.name), results: results[i] ?? '?', part: o.chance === 1 ? '1' : `1–${o.chance}`, part2: hit.includes(o) ? ` — <strong>${tx('SR2E.Card.Actor.damaged')}</strong>` : '' })}</li>`).join('');
    await ChatMessage.create({
      speaker: ChatMessage.getSpeaker({ actor: this }), rolls,
      content: `<div class="sr2e-roll"><h3>${tx('SR2E.Card.Actor.cyberwareDamageCheck2', { part: calledLocation ? ` (${escText((LIMB_LABELS[calledLocation] ?? calledLocation).toLowerCase())})` : '' })}</h3><ul>${rows}</ul></div>
        <p>${hit.length ? `<strong>${tx('SR2E.Card.Actor.damaged2')}</strong> ${tx('SR2E.Card.Actor.givesNothingUntilRepaired', { hit: escText(hit.map((h) => h.name).join(', ')) })}` : tx('SR2E.Card.Actor.noCyberwareIsDamaged')}</p>`,
    });
    return hit.map((h) => h.name);
  }

  /** The best worn shield (a Parry rating on armor) for melee defense. */
  shieldParry(): { dice: number; tn: number; name: string } {
    return shieldParry([...this.items].filter((i: any) => i.type === 'armor').map((i: any) => ({ name: i.name, worn: Boolean(i.system.worn) && isCarried(i), parry: Number(i.system.parry ?? 0) })));
  }

  /** Set up (or fold) a weapon's bipod or tripod: setting it up takes an action (RULES.ACTIONS.costs.setUpWeapon). */
  async setUpWeapon(itemId: string, on = true): Promise<boolean> {
    const w: any = this.items.get?.(itemId) ?? [...this.items].find((i: any) => i.id === itemId);
    if (!w || w.type !== 'weapon' || !['bipod', 'tripod'].includes(String(w.system.support))) {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.thatWeaponHasNoBipodOr'));
      return false;
    }
    if (on && !(await this.useAction('setUpWeapon', tx('SR2E.Card.Actor.settingUpS', { name: w.name, support: w.system.support })))) return false;
    await w.update({ 'system.supportSetUp': on });
    await ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor: this }), content: `<p>${escText(this.name)} ${on ? tx('SR2E.Card.Actor.setsUp') : tx('SR2E.Card.Actor.folds')} ${escText(w.name)}'s ${escText(w.system.support)}${on ? tx('SR2E.Card.Actor.recoilCompensation', { accessoriesSupport: RULES.GEAR.accessories.support[w.system.support] ?? 0 }) : ''}.</p>` });
    return true;
  }

  /** What this actor carries, as a search sees it (RULES.GEAR.concealment). */
  carriedItems(): CarriedItem[] {
    // v0.92.1 (RULES.SHEET_V921.carried): what is left behind isn't on them to find.
    return [...this.items].filter((i: any) => ['weapon', 'armor', 'gear', 'cyberware'].includes(i.type) && isCarried(i)).map((i: any) => ({
      id: i.id, name: i.name, type: i.type, concealability: Number(i.system.concealability ?? 0),
      ...(i.type === 'armor' ? { worn: Boolean(i.system.worn) } : {}),
      ...(i.type === 'cyberware' ? { worn: Boolean(i.system.installed), bioware: Boolean(i.system.bioware), kind: i.system.kind } : {}),
      ...((i.type === 'gear' && Number(i.system.explosive?.power ?? 0) > 0) || (i.type === 'weapon' && i.system.blast) ? { explosive: true } : {}),
    }));
  }

  /**
   * Search someone (RULES.GEAR.concealment): look them over or frisk them (Perception vs each item's
   * Concealability), or sweep them with a scanner (gear with a scanner rating). The result is
   * whispered to the GMs and the searcher's owners; what was missed only to the GMs.
   */
  async searchFor(targetUuid: string, opts: { method?: SearchMethod; scannerId?: string; modifiers?: TargetNumberModifier[]; skipAction?: boolean } = {}): Promise<{ found: string[]; missed: string[] } | null> {
    const target: any = await fromUuid(targetUuid);
    if (!target?.carriedItems) return null;
    const method: SearchMethod = opts.method ?? 'look';
    let dice = 0;
    let who = '';
    let searchMods: TargetNumberModifier[] = [];
    let kind: ScannerKind = '';
    if (method === 'scanner') {
      const sc: any = opts.scannerId ? (this.items.get?.(opts.scannerId) ?? [...this.items].find((i: any) => i.id === opts.scannerId)) : null;
      if (!sc?.system?.scanner?.kind || !(sc.system.scanner.rating > 0) || !isCarried(sc)) {
        ui.notifications?.warn?.(tx('SR2E.Notify.Actor.pickAScannerGearWithA'));
        return null;
      }
      if (!opts.skipAction && !(await this.useAction('scan', tx('SR2E.Card.Actor.scanning', { targetName: target.name })))) return null;
      dice = sc.system.scanner.rating;
      kind = sc.system.scanner.kind as ScannerKind;
      who = tx('SR2E.Card.Actor.scanner', { scName: sc.name, kind, dice });
    } else {
      if (!opts.skipAction && !(await this.useAction('search', tx('SR2E.Card.Actor.searching', { targetName: target.name })))) return null;
      // v0.71.0 (R2): Perception through the shared skill path.
      const pd = this.perceptionDice();
      dice = pd.dice;
      who = pd.label;
      searchMods = pd.modifiers;
    }
    return SR2Actor.#runSearch({ searcherName: this.name, speaker: ChatMessage.getSpeaker({ actor: this }), who, dice, method, kind, target,
      modifiers: method === 'scanner' ? (opts.modifiers ?? []) : this.#testModifiers({ modifiers: [...(opts.modifiers ?? []), ...searchMods, ...this.#searchSight(target, method)] }),
      owners: [...((game as any).users ?? [])].filter((u: any) => this.testUserPermission?.(u, 'OWNER')).map((u: any) => u.id) });
  }

  /**
   * v0.50.0: what eyes meet in a search: looking someone over takes light (by this searcher's vision)
   * and weather; a frisk is hands-on (no weather unless RULES.TN_AUTO.perception.friskWeather, no light).
   */
  #searchSight(target: any, method: SearchMethod): TargetNumberModifier[] {
    if (method === 'frisk') return RULES.TN_AUTO.perception.friskWeather ? this.weatherMods() : [];
    const s = this.sightTo(target);
    const l = RULES.TN_AUTO.perception.light ? lightModifier(s.light, s.vision) : null;
    return [...(l ? [l] : []), ...(s.weather ? [s.weather] : [])];
  }

  /**
   * Look over or scan several people at once (v0.47.0, RULES.GEAR.concealment.groupTnPerPerson): one action,
   * +TN per person after the first. A frisk is hands-on, so it takes one person at a time.
   */
  async searchGroup(targetUuids: string[], opts: { method?: SearchMethod; scannerId?: string; modifiers?: TargetNumberModifier[] } = {}): Promise<Array<{ uuid: string; found: string[]; missed: string[] }>> {
    // Not the searcher, and only people who can carry things.
    const uuids = [...new Set(targetUuids.filter((u) => u && u !== this.uuid && typeof (fromUuidSync(u) as any)?.carriedItems === 'function'))];
    const method: SearchMethod = opts.method ?? 'look';
    if (uuids.length <= 1 || method === 'frisk') {
      if (uuids.length > 1) ui.notifications?.info?.(tx('SR2E.Notify.Actor.aFriskTakesOnePersonAt'));
      const r = uuids[0] ? await this.searchFor(uuids[0], opts) : null;
      return r ? [{ uuid: uuids[0]!, ...r }] : [];
    }
    if (method === 'scanner') {
      const sc: any = opts.scannerId ? (this.items.get?.(opts.scannerId) ?? [...this.items].find((i: any) => i.id === opts.scannerId)) : null;
      if (!sc?.system?.scanner?.kind || !(sc.system.scanner.rating > 0) || !isCarried(sc)) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.pickAScannerGearWithA')); return []; }
    }
    if (!(await this.useAction(method === 'scanner' ? 'scan' : 'search', tx('SR2E.Card.Actor.people', { part: method === 'scanner' ? tx('SR2E.Card.Actor.scanning2') : tx('SR2E.Card.Actor.searching2'), uuidsLength: uuids.length })))) return [];
    const modifiers = [...(opts.modifiers ?? []), ...groupSearchModifiers(uuids.length)];
    const out: Array<{ uuid: string; found: string[]; missed: string[] }> = [];
    for (const uuid of uuids) {
      const r = await this.searchFor(uuid, { ...opts, modifiers, skipAction: true });
      if (r) out.push({ uuid, ...r });
    }
    return out;
  }

  /** One search: a test per item; found ones go to the GMs and owners, missed ones to the GMs. */
  static async #runSearch(o: { searcherName: string; speaker: any; who: string; dice: number; method: SearchMethod; kind: ScannerKind; target: any; modifiers: TargetNumberModifier[]; owners: string[] }): Promise<{ found: string[]; missed: string[] }> {
    const list = searchTargets(o.target.carriedItems(), o.method, o.kind);
    const found: string[] = [];
    const missed: string[] = [];
    const rows: string[] = [];
    const rolls: any[] = [];
    // v0.80.0 (RULES.URR_V80.dsMadScan 'highestDie', URR): a weapon detector rolls its rating once; it turns up every weapon hidden no better than the highest die.
    const mad = dsMadScanOn(o.method, o.kind) && list.some((t) => t.tn !== null) ? (o.dice > 0 ? dsHighestDie((await rollOpenEnded(o.dice, foundryRoller(rolls))).map((d) => d.total)) : 0) : null;
    for (const t of list) {
      if (t.tn === null) { found.push(t.name); rows.push(`<li>${tx('SR2E.Card.Actor.inPlainSight', { name: escText(t.name) })}</li>`); continue; }
      if (mad !== null) {
        const m = dsMadFinds(mad, t.tn, o.modifiers);
        (m.found ? found : missed).push(t.name);
        rows.push(`<li>${tx('SR2E.Card.Actor.concealmentHighestDie', { name: escText(t.name), need: m.need, mad, part: m.found ? ` — <strong>${tx('SR2E.Card.Actor.found3')}</strong>` : tx('SR2E.Card.Actor.missed') })}</li>`);
        continue;
      }
      const r = await successTest({ dice: o.dice, targetNumber: t.tn, modifiers: o.modifiers, roll: foundryRoller(rolls) });
      const ok = searchFinds(r.successes);
      (ok ? found : missed).push(t.name);
      const why = escText(r.modifiers.map((m) => `${m.label} ${m.value >= 0 ? '+' : ''}${m.value}`).join(', '));
      rows.push(`<li>${escText(t.name)} (<span title="${tx('SR2E.Card.Actor.tnBase2', { baseTargetNumber: r.baseTargetNumber, part: why ? `; ${why}` : '' })}">${tx('SR2E.Card.Actor.tn4', { targetNumber: r.targetNumber })}</span>): ${escText(plural(r.successes, 'success'))}${ok ? ` — <strong>${tx('SR2E.Card.Actor.found3')}</strong>` : tx('SR2E.Card.Actor.missed')}</li>`);
    }
    const gms = [...((game as any).users ?? [])].filter((u: any) => u.isGM).map((u: any) => u.id);
    // v0.58.0: whether what was found is legal (and covered by a permit).
    const legal: string[] = o.target.legalNotes?.(found) ?? [];
    const how = o.method === 'frisk' ? tx('SR2E.Card.Actor.frisks') : o.method === 'scanner' ? tx('SR2E.Card.Actor.scans') : tx('SR2E.Card.Actor.looksOver');
    await ChatMessage.create({
      speaker: o.speaker, whisper: [...new Set([...gms, ...o.owners])],
      content: `<div class="sr2e-roll"><h3>${escText(o.searcherName)} ${how} ${escText(o.target.name)}</h3><p>${escText(o.who)}${o.method === 'frisk' ? tx('SR2E.Card.Actor.friskTn', { concealmentFriskTn: RULES.GEAR.concealment.friskTn }) : ''}</p></div>
        <p>${found.length ? `<strong>${tx('SR2E.Card.Actor.found')}</strong> ${escText(found.join(', '))}.` : list.length ? `<strong>${tx('SR2E.Card.Actor.nothingFound')}</strong>` : tx('SR2E.Card.Actor.thereIsNothingOfThatKind')}</p>${legal.length ? `<ul class="sr2e-legal">${legal.map((x) => `<li>${escText(x)}</li>`).join('')}</ul>` : ''}`,
    });
    if (list.some((t) => t.tn !== null)) {
      await ChatMessage.create({ speaker: o.speaker, whisper: gms, blind: true, rolls, content: `<p><em>${tx('SR2E.Card.Actor.gmOnly')}</em> ${tx('SR2E.Card.Actor.sSearchOf', { searcherName: escText(o.searcherName), targetName: escText(o.target.name) })}</p><ul>${rows.join('')}</ul>` });
    }
    return { found, missed };
  }

  /** A site's scanner device sweeps an intruder (v0.43.0): found items raise the tally. */
  async scanWithDevice(deviceId: string, intruderUuid: string): Promise<{ found: string[]; missed: string[] } | null> {
    if (this.type !== 'site') return null;
    const d = this.device(deviceId);
    if (!d || !d.scanKind) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.thatDeviceIsNotAScanner')); return null; }
    if (!d.active || d.bypassed) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.is', { name: escHtml(d.name), part: d.bypassed ? tx('SR2E.Notify.Actor.bypassed') : tx('SR2E.Notify.Actor.switchedOff') })); return null; }
    const target: any = await fromUuid(intruderUuid);
    if (!target?.carriedItems) return null;
    const r = await SR2Actor.#runSearch({ searcherName: d.name, speaker: { alias: this.name }, who: tx('SR2E.Card.Actor.scanner2', { scanKind: d.scanKind, rating: d.rating }), dice: d.rating, method: 'scanner', kind: d.scanKind as ScannerKind, target, modifiers: [], owners: [] });
    if (r.found.length) await SR2Actor.changeSite(this, { add: r.found.length * RULES.GEAR.concealment.tallyOnFind }, tx('SR2E.Card.Actor.findsOn', { name: d.name, found: r.found.join(', '), targetName: target.name }), this.uuid as string);
    return r;
  }

  /** Strength for an attack: a cyberarm's own Strength when one is used (`limbId`), else the character's. */
  attackStrength(limbId?: string | null): { strength: number; limbName: string } {
    const s = (this.sys.attributes?.strength?.total as number | undefined) ?? 0;
    const limb = limbId ? [...(this.sys.derived?.cyber?.limbs ?? [])].find((l: any) => l.id === limbId) : null;
    return limb ? { strength: limb.strength, limbName: limb.name } : { strength: s, limbName: '' };
  }

  /** v0.55.0: actors whose combatants are surprised right now (they can't see this attack coming). */
  #surprisedTargets(): string[] {
    const c: any = game.combat;
    if (!c?.started || typeof c.surprisedNow !== 'function') return [];
    const ids: string[] = c.surprisedNow() ?? [];
    return [...(c.combatants ?? [])].filter((x: any) => ids.includes(x.id) && x.actor).map((x: any) => x.actor.uuid as string);
  }

  /** v0.55.0: Take Aim kept on the actor, for this weapon at this target this Combat Turn. */
  #aimMods(weaponId: string, targetUuid: string, skillRating: number): TargetNumberModifier[] {
    const c: any = game.combat;
    if (!c?.started || !targetUuid || !weaponId) return [];
    // v0.72.0 (O2): the aim lasts into later Combat Turns while the aimer does nothing else (RULES.COMBAT_V72.aim).
    return aimModifierV72(this.getFlag?.(SYSTEM_ID, 'aim') as AimState | undefined, { targetUuid, weaponId, round: Number(c.round ?? 0), combatId: String(c.id) }, skillRating);
  }

  /** v0.55.0: ranged attacks at a different target than earlier in this Combat Phase. */
  #otherTargetMods(targetUuid: string): TargetNumberModifier[] {
    const phase = this.currentPhaseKey();
    if (!phase || !targetUuid) return [];
    const f = this.getFlag?.(SYSTEM_ID, 'phaseTargets') as { phase: string; targets: string[] } | undefined;
    return f?.phase === phase ? multipleTargetModifier(f.targets ?? [], targetUuid) : [];
  }

  /**
   * v0.55.0: Take Aim (a Simple Action) with a weapon at a target: −1 TN each on the next attack at it,
   * up to half the skill (RULES.COMBAT.aim). Any other action, another target or weapon, or a new turn loses it.
   */
  async takeAim(weaponId: string, targetUuid: string): Promise<number> {
    const c: any = game.combat;
    const weapon: any = this.weaponById(weaponId);
    const target: any = targetUuid ? fromUuidSync(targetUuid) : null;
    if (!weapon || !target) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.pickAWeaponAndTargetA')); return 0; }
    if (!c?.started) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.takingAimOnlyCountsInA')); return 0; }
    if (!(await this.useAction('aim', tx('SR2E.Card.Actor.takingAimWith', { weaponName: weapon.name })))) return 0;
    const now = { targetUuid: target.uuid as string, weaponId, round: Number(c.round ?? 0), combatId: String(c.id) };
    const next = nextAimV72(this.getFlag?.(SYSTEM_ID, 'aim') as AimState | undefined, now);
    await this.setFlag(SYSTEM_ID, 'aim', next);
    const skill = this.findSkill(weapon.system?.skill);
    // v0.72.0 (O2): capped by the rating rolled with this weapon (a specialization naming it).
    const n = Math.min(next.actions, aimCap(aimRatingForWeapon(skill?.system, String(weapon.system?.specialization ?? ''))));
    await ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor: this }), content: `<p><strong>${escText(this.name)}</strong> ${tx('SR2E.Card.Actor.takesAimAtWithTnOn', { targetName: escText(target.name), weaponName: escText(weapon.name), n, part: next.actions > n ? tx('SR2E.Card.Actor.atTheMost') : '' })}</p>` });
    return n;
  }

  /**
   * Everything an attack works out before it is rolled (no side effects): base TN, the attack's own
   * modifiers, dice, damage and notes. Used by attackWith and by the Attack dialog's live preview.
   */
  planAttack(weapon: any, opts: AttackOptions = {}) {
    const w = weapon.system;
    const melee = Boolean(w.melee);
    const blast = !melee && Boolean(w.blast);
    // Vision magnification brings the range band closer (v0.29.0); an imaging scope too (v0.43.0).
    const mag = !melee && opts.magnify ? attackMagnification(Number(w.scope ?? 0), (this.sys.derived?.cyber?.magnification as number | undefined) ?? 0) : 0;
    const range = opts.range && mag > 0 ? magnifiedRange(opts.range, mag) : opts.range;
    const base = attackBaseTargetNumber({ melee, ...(range ? { range } : {}) });
    // A cyberarm's own Strength for Strength-based attacks (a cyberweapon housed in one uses it).
    const arm = this.type === 'vehicle' ? { strength: 0, limbName: '' } : this.attackStrength(opts.limbId ?? weapon.limbId ?? null);
    const strength = arm.strength;

    // Firing mode, rounds, ammo, recoil and damage bonus (ranged only).
    let power = weaponPower(w, strength);
    let level = w.damageLevel as DamageLevel;
    let damageType = w.damageType as DamageType;
    let modeLabel = '';
    const fireMods: TargetNumberModifier[] = [];
    let rounds = 0;
    let earlier = 0;
    let wasted = 0;
    let firstShotSingle: boolean | undefined;
    const extras: Partial<AttackState> = {};
    // v0.72.0 (O3, review): a spirit's or dual-natured critter's natural attack isn't stopped outright by immunity.
    if (this.type === 'spirit' || Boolean(this.sys.derived?.dualNatured)) extras.awakenedAttacker = true;
    const notes: string[] = opts.note ? [opts.note] : [];
    // v0.55.0: the weapon's own armor kind ('auto': thrown weapons and bows by RULES.COMBAT.armorFor).
    const ownArmor = weaponArmorKind({ armorKind: w.armorKind, melee, thrown: Boolean(w.thrown), skill: w.skill, name: weapon.name });
    if (!blast && ownArmor !== armorKindFor(melee)) extras.armorKind = ownArmor;
    if (mag > 0 && range !== opts.range) notes.push(tx('SR2E.Card.Actor.magnificationRange', { mag, range }));
    if (arm.limbName && (w.strengthPower || w.strengthRange)) notes.push(tx('SR2E.Card.Actor.limbStrength', { limb: arm.limbName, strength }));
    let ammoShort: string | null = null;
    if (!melee) {
      const allowed = parseFiringModes(w.modes);
      const mode = opts.mode && allowed.includes(opts.mode) ? opts.mode : (allowed[0] as FiringMode);
      rounds = opts.rounds != null && mode === 'FA' ? Math.max(1, Math.floor(opts.rounds)) : roundsForMode(mode, opts.fullAutoRounds);
      wasted = mode === 'FA' ? Math.max(0, Math.floor(opts.wastedRounds ?? 0)) : 0;
      if (w.ammoMax > 0 && w.ammo < rounds + wasted) ammoShort = tCount(w.ammo, 'SR2E.Text.Actor.roundsLeftNeededReload', { name: weapon.name, needed: rounds + wasted });
      earlier = Math.max(0, opts.earlierRoundsThisPhase ?? this.trackedRecoilRounds()) + wasted;
      if (wasted) notes.push(tCount(wasted, 'SR2E.Card.Actor.roundsWastedWalkingFire'));
      // Fixed and turret mounts absorb recoil. Accessories add compensation: a shock pad, a set-up bipod or tripod (v0.43.0).
      const acc = accessoryRecoil(w, this.hasStatus?.('prone') ?? false);
      if (acc.parts.length) notes.push(acc.parts.join(', '));
      // v0.55.0: suppressive fire sprays an area: no recoil penalty on it (house rule).
      // v0.79.0 (RULES.DOCS_V79.vehMountRecoil 'rigger2', Rigger 2 p131): fixed and turret mounts halve the recoil, pintle 2 and ring 6 compensation.
      // v0.79.0 (RULES.DOCS_V79.rangedRecoil 'book'): the phase's first shot is free only when it was a single shot.
      firstShotSingle = earlier - wasted > 0 ? this.trackedFirstShotSingle() : rounds === 1 && wasted === 0;
      // v0.80.0 (URR_V80.cbtStrengthRecoil, URR): a strong shooter takes some recoil off what is left.
      const recoil = U80C.cbtStrengthRecoil(opts.suppressive ? 0 : mountedRecoil({ rounds, earlierRoundsThisPhase: earlier, recoilComp: (w.recoilComp ?? 0) + acc.value, mount: w.mount, mounted: Boolean(opts.mounted), heavy: veh80HeavyRecoil(Boolean(w.heavy), Boolean(opts.mounted)), ...(firstShotSingle === undefined ? {} : { firstShotSingle }) }), strength, !opts.mounted && this.type !== 'vehicle');
      if (recoil > 0) fireMods.push({ label: w.heavy ? tx('SR2E.Card.Mod.recoilHeavy') : tx('SR2E.Card.Mod.recoil'), value: recoil });
      // A gyro mount cancels recoil, then the attacker's walking/running penalty.
      if ((w.gyro ?? 0) > 0) {
        const moving = RULES.SITUATIONAL_MODIFIERS.filter((m) => (opts.situational ?? []).includes(m.id) && /^attacker(Walking|Running)$/.test(m.id)).reduce((n, m) => n + m.value, 0);
        const g = gyroOffset({ recoil, movement: moving, gyro: w.gyro });
        if (g.used > 0) fireMods.push({ label: tx('SR2E.Card.Mod.gyroMount', { gyro: w.gyro }), value: -g.used });
      }
      // v0.78.0 (RULES.BOOK_V78.barriers 'book'): a barrier takes the base Power, before burst or full-auto fire.
      extras.barrierPower = power;
      ({ power, level } = damageForMode(power, level, mode, rounds));
      modeLabel = mode === 'FA' ? `FA ×${rounds}` : mode;
      // Muzzle devices and tracers (v0.37.0).
      const mz = muzzleCheck(String(w.muzzle ?? ''), mode);
      if (!mz.ok) ammoShort = `${weapon.name}: ${mz.reason}.`;
      else if (mz.perceptionTn) notes.push(w.muzzle === 'silencer' ? tx('SR2E.Card.Actor.silencedNoticingTheShot', { tn: mz.perceptionTn }) : tx('SR2E.Card.Actor.suppressedNoticingTheShot', { tn: mz.perceptionTn }));
      // v0.80.0 (URR_V80.cbtTracers, URR): full auto only, −1 per third round (not with a smartgun), and no Power from them.
      const tr80 = U80C.cbtTracer(tracerModifier({ ammo: String(opts.ammoType ?? w.ammoType ?? ''), mode, earlierRounds: earlier }), { ammo: String(opts.ammoType ?? w.ammoType ?? ''), mode, rounds, smartgun: Boolean(w.smartgun && this.sys.derived?.smartlink) });
      const tr = tr80.tn;
      if (tr) fireMods.push({ id: 'tracers', label: tx('SR2E.Card.Mod.tracers'), value: tr });
      if (tr80.powerOff) { power = Math.max(0, power - tr80.powerOff); notes.push(tx('SR2E.Card.Actor.tracersPower', { powerOff: tr80.powerOff })); }
      if (!blast) {
        const ammo = ammoType(opts.ammoType ?? w.ammoType);
        if (ammo.id !== 'standard') {
          const beforeAmmo = power;
          // v0.79.0 (RULES.DOCS_V79.rangedFlechette 'armor', SRII p. 93): flechette's extra level is decided at the soak (no armor only).
          const fl79 = flechetteAtSoak(ammo.id);
          ({ power, level } = fl79 ? { power: ammoDamage(power, level, ammo.id).power, level } : ammoDamage(power, level, ammo.id));
          if (fl79) extras.flechette = true;
          // v0.78.0 review fix: the ammunition's Power change counts against barriers too (only burst/auto doesn't).
          if (extras.barrierPower !== undefined) extras.barrierPower = Math.max(0, extras.barrierPower + (power - beforeAmmo));
          // v0.72.0 (O6): house-rule rounds can also make an attack anti-vehicle.
          const ax = ammoExtras(ammo);
          if (ax.armorMultiplier !== undefined) extras.armorMultiplier = ax.armorMultiplier;
          if (ax.armorKind) extras.armorKind = ax.armorKind;
          if (ax.damageType) damageType = ax.damageType;
          if (ax.antiVehicle) extras.antiVehicle = true;
          notes.push(ammo.label);
        }
      }
      fireMods.push(...spreadFireModifiers(opts.spreadExtraTargets ?? 0));
    }
    // v0.55.0: suppressive fire does the weapon's base damage (the rounds are for the area, not one target).
    if (!melee && opts.suppressive) {
      power = weaponPower(w, strength);
      level = w.damageLevel as DamageLevel;
      const sa = blast ? null : ammoType(opts.ammoType ?? w.ammoType);
      if (sa && sa.id !== 'standard') ({ power, level } = flechetteAtSoak(sa.id) ? { power: ammoDamage(power, level, sa.id).power, level } : ammoDamage(power, level, sa.id));
      extras.suppressive = true;
      notes.push(tx('SR2E.Card.Actor.suppressiveFire2'));
    }
    if (blast) {
      extras.armorKind = RULES.COMBAT.blast.armorKind;
      const kind = grenadeKind(w.blastKind);
      if (kind.damageType) damageType = kind.damageType;
      if (kind.id !== 'custom') notes.push(kind.label);
    }
    // Flamethrowers (v0.37.0): fire against part of the impact armor.
    if (w.areaKind === 'flame') {
      const f = RULES.COMBAT.flame;
      extras.flame = true;
      extras.armorKind = f.armorKind;
      extras.armorMultiplier = f.armorMultiplier;
      notes.push(tx('SR2E.Card.Actor.flamethrower'));
    }
    if (melee && opts.subdue) {
      damageType = RULES.COMBAT.subdue.damageType;
      notes.push(tx('SR2E.Card.Actor.subduing'));
    }
    // v0.80.0 (URR_V80.cbtChargePower, URR): a charging blow hits harder.
    if (melee && (opts.chargePower80 ?? 0) > 0) { power += opts.chargePower80 ?? 0; notes.push(tx('SR2E.Card.Actor.chargingPower', { power: opts.chargePower80 })); }
    // Stun weapons: Stun damage against part of the impact armor (RULES.STUN_WEAPONS).
    // v0.61.0: a stun baton's charges (tracked in ammo when ammoMax > 0): out of charge it hits as a club.
    const charge = melee && w.stunWeapon ? stunCharge({ stunWeapon: true, ammo: Number(w.ammo ?? 0), ammoMax: Number(w.ammoMax ?? 0) }) : null;
    if (charge?.blocked) ammoShort = `${weapon.name}: ${charge.note}`;
    if (w.stunWeapon && (!charge || charge.stun)) {
      damageType = 'stun';
      extras.armorKind = RULES.STUN_WEAPONS.armorKind;
      extras.armorMultiplier = RULES.STUN_WEAPONS.armorMultiplier;
      notes.push(tx('SR2E.Card.Actor.stunWeapon'));
    } else if (charge && !charge.stun) notes.push(charge.note);
    if ((opts.barrierArmor ?? 0) > 0) {
      extras.extraArmor = opts.barrierArmor;
      notes.push(tx('SR2E.Card.Actor.throughBarrier', { armor: opts.barrierArmor }));
    }

    // Called shot: the TN, and the payoff.
    const called = opts.calledShot ?? 'none';
    // A laser sight doesn't add to a smartlink (v0.43.0).
    const ls = laserAndSmartlink(opts.situational ?? []);
    const situational = ls.situational;
    if (ls.dropped) notes.push(tx('SR2E.Card.Actor.laserSightNotUsedWithThe'));
    if (called !== 'none') {
      if (!situational.includes('calledShot')) situational.push('calledShot');
      const c = calledShotDamage(level, called);
      level = c.level;
      if (c.ignoreArmor) extras.ignoreArmor = true;
      // At a limb (v0.43.0): a cyberlimb's own armor counts, and its cyberware is likelier to be damaged.
      if (opts.calledLocation && opts.calledLocation !== 'other') extras.calledLocation = opts.calledLocation;
      const where = extras.calledLocation ? (LIMB_LABELS[extras.calledLocation] ?? extras.calledLocation).toLowerCase() : '';
      notes.push(called === 'damage' ? (where ? tx('SR2E.Card.Actor.calledShotDamageAt', { where }) : tx('SR2E.Card.Actor.calledShotDamage')) : (where ? tx('SR2E.Card.Actor.calledShotArmorAt', { where }) : tx('SR2E.Card.Actor.calledShotArmor')));
    }
    // v0.72.0 (O7): indirect fire: the spotter's link instead of the firer's own sight; walking fire in (RULES.COMBAT_V72.indirect).
    const indirect = blast && opts.indirect && canFireIndirect({ blast: Boolean(blast), indirect: Boolean(w.indirect), skill: w.skill, melee }) ? opts.indirect : null;
    if (indirect) {
      const c: any = game.combat;
      const pt = opts.blastPoint;
      const prev = this.getFlag?.(SYSTEM_ID, 'adjust') as AdjustState | undefined;
      const adj = pt && c?.started ? nextAdjust(prev, { x: pt.x, y: pt.y, combatId: String(c.id) }, Number((canvas as any)?.grid?.size ?? 100)) : { earlierShots: 0 };
      const ip = indirectFire({ link: indirect.link as SpotterLink, adjustShots: adj.earlierShots });
      if (!ip.allowed) ammoShort = `${weapon.name}: ${ip.reason}`;
      fireMods.push(...ip.modifiers);
      notes.push(indirect.link !== 'none' ? tx('SR2E.Card.Actor.indirectFireSpotter', { link: indirect.link }) : tx('SR2E.Card.Actor.indirectFire'));
    }
    // A bounced grenade throw (v0.43.0): harder, scatters more, needs no line of sight.
    if (blast && opts.bounce) {
      fireMods.push({ id: 'bouncedThrow', label: tx('SR2E.Card.Mod.bouncedThrow'), value: RULES.GEAR.grenades.bounce.tn });
      notes.push(tx('SR2E.Card.Actor.bounced'));
    }
    const smartGrenade = blast && Boolean(w.smartGrenade) && (!RULES.GEAR.grenades.smart.needsSmartlink || (situational.includes('smartlink') && Boolean(this.sys.derived?.smartlink)));
    if (blast && w.fuse) notes.push(tx('SR2E.Card.Actor.fuse', { fuse: w.fuse }));
    if (smartGrenade) notes.push(tx('SR2E.Card.Actor.smartGrenade'));

    // Vehicles: a mounted weapon (Gunnery; a vehicle's own autopilot rolls its rating), firing from
    // a moving vehicle, at a target in one, and sensor-enhanced gunnery.
    const mounted = opts.mounted ?? null;
    const mv: any = mounted ? fromUuidSync(mounted.vehicleUuid) : null;
    if (mounted) notes.push(mounted.role === 'autopilot' ? tx('SR2E.Card.Actor.mountAutopilot', { mount: w.mount }) : mounted.role === 'gunner' ? tx('SR2E.Card.Actor.mountGunner', { mount: w.mount }) : tx('SR2E.Card.Actor.mount', { mount: w.mount }));
    // Killing hands (adept, v0.39.0): unarmed blows do Physical damage at the power's level.
    // v0.58.0: bone lacing hardens unarmed blows.
    const lacePower = weapon.id === 'unarmed' ? Math.max(0, Number(this.sys.derived?.cyber?.lacing?.unarmedPower ?? 0)) : 0;
    if (lacePower) { power += lacePower; notes.push(tx('SR2E.Card.Actor.boneLacing2', { label: this.sys.derived.cyber.lacing.label, lacePower })); }
    const kh = weapon.id === 'unarmed' ? killingHandsLevel(this.adeptSpecial('killingHands')) : null;
    if (kh) {
      level = kh;
      damageType = 'physical';
      notes.push(tx('SR2E.Card.Actor.killingHands'));
    }
    if (w.material) extras.material = String(w.material);
    if (RULES.URR_V80.vehDamage.mode === 'urr') extras.vehHit = { basePower: weaponPower(w, strength) };
    // v0.48.0: a critter's Infection power rides on its melee blows (a ghoul's bite).
    if (melee && RULES.CRITTERS.infection.enabled) {
      const inf: any = [...this.items].find((i: any) => i.type === 'power' && i.system?.special === 'infection');
      if (inf) {
        extras.infection = { ...infectionFrom({ name: inf.name, substance: inf.system.substance, rating: inf.system.rating, damageLevel: inf.system.damageLevel }), from: this.name as string };
        notes.push(`${inf.name}: ${extras.infection.name}`);
      }
    }
    // v0.55.0: a toxin the weapon carries (a gear item with a toxin on this sheet): a dart's or blade's on a hit, a gas grenade's to everyone in the cloud.
    let blastToxin: ToxinHit | null = null;
    if (w.toxinId) {
      const ti: any = [...this.items].find((i: any) => i.id === w.toxinId);
      const t = SR2Actor.toxinOf(ti);
      if (t) {
        const th: ToxinHit = { ...t, from: this.name as string, needsWound: Boolean(w.toxinNeedsWound) };
        if (blast) blastToxin = th; else extras.toxinHit = th;
        notes.push(t.name);
      }
    }
    // A martial art stands in for Unarmed Combat when it is better (v0.38.0).
    const style = weapon.id === 'unarmed' ? this.martialStyle() : null;
    if (style) {
      const m = martialAttack({ power, level, reach: 0 }, style.style);
      power = m.power;
      level = m.level;
      notes.push(style.skill.name);
    }
    const skill = style ? style.skill : this.findSkill(mounted ? mountedSkill(w.skill) : indirect && RULES.COMBAT_V72.indirect.skill ? RULES.COMBAT_V72.indirect.skill : w.skill);
    // v0.46.0: a targeting autosoft adds dice to the autopilot's own fire.
    const targeting = this.type === 'vehicle' ? autosoftDice(this.sys.autosofts?.targeting ?? 0, this.sys.derived?.autopilotRating ?? 0) : 0;
    const sd = this.type === 'vehicle'
      ? { dice: ((this.sys.derived?.autopilotRating as number | undefined) ?? 0) + targeting, modifiers: [] as TargetNumberModifier[], suffix: ` (${this.sys.drone ? 'Pilot' : 'Autonav'} ${this.sys.derived?.autopilotRating ?? 0}${targeting ? ` + targeting autosoft ${targeting}` : ''})` }
      // v0.47.0: melee attacks default to the skill's linked attribute (RULES.COMBAT.melee.defaultAttribute).
      : this.#skillDice(skill, opts.useSpecialization, opts.relatedSkillId, melee && !style ? meleeDefaultAttribute(w.skill ?? '', null) : 'quickness', { useConcentration: opts.useConcentration, skillName: w.skill, limbId: opts.limbId ?? weapon.limbId ?? null });
    const ride: any = mv ?? this.vehicleAboard();
    const targetDoc: any = opts.targetUuid ? fromUuidSync(opts.targetUuid) : opts.hits?.[0] ? fromUuidSync(opts.hits[0].targetUuid) : null;
    const targetRide: any = targetDoc ? (targetDoc.type === 'vehicle' ? targetDoc : targetDoc.vehicleAboard?.() ?? null) : null;
    // v0.73.0 (O27): a lock that has lapsed (time, sensors shot out) doesn't count, even before the sweep drops it.
    const lockEntry: any = mv && targetDoc ? (mv.system?.locks ?? []).find((l: any) => l.targetUuid === targetDoc.uuid) : null;
    const lock = Boolean(lockEntry && !sensorLockLapse(lockEntry, { now: SR2Actor.matrixNow(), sensorRating: Number(mv.system?.derived?.working?.sensor ?? mv.system?.sensor ?? 0), sensorsOut: Boolean(mv.system?.systems?.sensors) }).lapsed);
    // v0.73.0 (O28, 5-A11): a guided missile locks on to the target's Signature, against its ECM (RULES.DRONES_V73.missiles).
    const ml = missileLockOn({
      guidance: Number(w.guidance ?? 0), melee,
      targetIsVehicle: targetDoc?.type === 'vehicle', signature: Number(targetDoc?.system?.signature ?? 0), rangeTn: base.value,
      targetEcm: Number(targetDoc?.type === 'vehicle' ? targetDoc.system?.ecm ?? 0 : 0), firerEccm: Number(mv?.system?.eccm ?? 0),
      fromVehicle: Boolean(mv), hasLock: lock,
    } as any);
    if (ml.note) notes.push(ml.note);
    // v0.57.0: sensor-enhanced gunnery: a flat bonus, or the target's Signature in place of range (dice capped at the Sensor).
    // v0.79.0 ('rigger2', the new default; Rigger 2 Sensor-Enhanced Targeting table): Gunnery (Pilot) + half Sensor vs the
    // Signature + ECM beyond ECCM; the movement modifiers don't apply (RULES.DOCS_V79.vehSeg).
    const sigMode = RULES.VEHICLES_V57.sensorGunnery !== 'flat';
    const sg = mv && lock && sigMode && !ml.applies ? sensorGunneryByMode({
      lock, signature: Number(targetDoc?.type === 'vehicle' ? targetDoc.system?.signature ?? 0 : RULES.VEHICLES.sensors.personSignature),
      rangeTn: base.value, sensor: Number(mv.system?.derived?.working?.sensor ?? mv.system?.sensor ?? 0), gunneryDice: sd.dice,
      targetEcm: Number(targetDoc?.type === 'vehicle' ? targetDoc.system?.ecm ?? 0 : 0), firerEccm: Number(mv.system?.eccm ?? 0),
    }) : null;
    if (sg) { sd.dice = sg.dice; if (sg.note) notes.push(sg.note); }
    const still = Boolean(sg?.noMovement);
    // v0.80.0 (URR_V80.vehGunnery): manual gunnery at a vehicle: speed difference and target size instead of the moving modifiers.
    const vehicleMods = veh80FireModifiers({
      firing: ride ? { speed: Number(ride.system?.speed ?? 0), currentSpeed: still ? 0 : Number(ride.system?.currentSpeed ?? 0), damageBoxes: ride.system?.condition ?? 0, mounted: Boolean(mounted) } : null,
      targetMoving: !still && Number(targetRide?.system?.currentSpeed ?? 0) > 0, sensorLock: lock && !sigMode,
      mounted: Boolean(mounted), still, targetSpeed: targetRide ? Number(targetRide.system?.currentSpeed ?? 0) : null,
      target: targetDoc ? { vehicle: targetDoc.type === 'vehicle', category: String(targetDoc.system?.category ?? ''), drone: Boolean(targetDoc.system?.drone) } : null,
    });
    if (sg) vehicleMods.push(...sg.modifiers);
    vehicleMods.push(...ml.modifiers);
    // v0.73.0 (O26): a jumped-in rigger's control rig helps their gunnery too (NETRIG_V73.controlRig.gunnery).
    const riggedFire = Boolean(mounted && this.sys.rigging?.jumpedIn && ((mounted.role === 'driver' && mv?.system?.controlMode === 'jumped') || mounted.role === 'security'));
    vehicleMods.push(...controlRigTn({ test: 'gunnery', vcr: Number(this.sys.derived?.rigging?.vcr ?? 0), jumpedIn: riggedFire } as any));
    // v0.57.0: the chase position won by maneuver score (RULES.VEHICLES_V57.maneuver).
    const combatNow: any = game.combat;
    if (ride && targetRide && ride !== targetRide) {
      const pm = positionModifier(ride.system?.position, ride.uuid, targetRide.uuid, combatNow?.started ? Number(combatNow.round ?? 0) : null, combatNow?.started ? String(combatNow.id ?? '') : null);
      if (pm) vehicleMods.push(pm);
    }
    // v0.57.0: a called shot at part of a target vehicle.
    if (targetDoc?.type === 'vehicle' && opts.vehiclePart && vehiclePart(opts.vehiclePart)) {
      const part = vehiclePart(opts.vehiclePart)!;
      const occ: any = part.id === 'occupant' && opts.occupantUuid ? fromUuidSync(opts.occupantUuid) : null;
      const inside = Boolean(occ && (targetDoc.isAboard?.(occ) || occ.uuid === targetDoc.system?.controllerUuid));
      if (part.id !== 'occupant' || inside) vehicleMods.push(vehicleCalledShotModifier(part.id));
      if (part.id === 'occupant') {
        if (inside) {
          extras.vehiclePart = 'occupant';
          extras.occupantUuid = occ.uuid;
          if (part.armorCounts) extras.occupantArmor = veh80OccupantArmor({ body: Number(targetDoc.system?.body ?? 0), armor: Number(targetDoc.system?.armor ?? 0) });
          notes.push(tx('SR2E.Card.Actor.calledShotInside', { name: occ.name }));
        }
      } else {
        extras.vehiclePart = part.id;
        if (part.id === 'mount' && opts.vehicleWeaponId) extras.vehicleWeaponId = opts.vehicleWeaponId;
        notes.push(tx('SR2E.Card.Actor.calledShotPart', { part: part.label.toLowerCase() }));
      }
    }
    const pool: PoolKind = veh80GunneryPool(mounted?.role === 'security' || (mounted?.role === 'driver' && mv?.system?.controlMode === 'jumped') ? 'control' : 'combat', mounted?.role);
    const focusExtra = melee && weapon.id !== 'unarmed' ? bonusNote(weaponFocusDice(this.foci(), weapon.name), 0) : { dice: 0, note: '' };
    // A missile's Intelligence adds dice (v0.37.0).
    const guidance = !melee && RULES.COMBAT.missileGuidance && !ml.unguided ? Math.max(0, Number(w.guidance ?? 0)) : 0;
    const dice = sd.dice + focusExtra.dice + guidance;
    const suffix = sd.suffix + focusExtra.note + (guidance ? tx('SR2E.Card.Actor.missileIntelligence', { guidance }) : '');
    const modifiers = [
      ...fireMods,
      ...(this.sys.derived?.dualNatured || this.#sensesAreVehicle(opts) ? [] : perceivingModifiers(this.sys.derived?.astralMode as AstralMode)),
      // v0.50.0: full cover is blind fire, counted with the rest of the visibility group.
      ...situationalModifiers(situational.filter((id) => id !== 'fullCover'), 'normal'),
      // Light or blind fire, smoke, weather (ranged, v0.42.0), a blinded attacker, the target's concealment: once each.
      // v0.72.0 (O7): fired indirect, the firer's own sight doesn't count (the spotter's link does); being blinded still does.
      ...(indirect ? (this.#sensesAreVehicle(opts) ? [] : this.blindMods('attack').slice(0, 1)) : this.#attackVisibilityMods(weapon, opts, { melee, situational, targetDoc })),
      // A better smartlink than the table's row (RULES.CYBERWARE.smartlink).
      ...(() => {
        const lv = (this.sys.derived?.cyber?.smartlinkLevel as number | undefined) ?? 0;
        const row = RULES.SITUATIONAL_MODIFIERS.find((m) => m.id === 'smartlink')?.value ?? 0;
        const diff = smartlinkModifier(lv) - row;
        return situational.includes('smartlink') && lv > 1 && diff ? [{ label: tx('SR2E.Card.Mod.smartlink', { lv }), value: diff }] : [];
      })(),
      ...(opts.modifiers ?? []),
      ...sd.modifiers,
      // v0.55.0: Take Aim at this target with this weapon; ranged shots at another target than earlier this phase.
      // v0.72.0 (O2): the aim cap uses the rating actually rolled (RULES.COMBAT_V72.aim.capBy).
      ...this.#aimMods(weapon.id ?? '', targetDoc?.uuid ?? '', aimRating({
        rating: Number(skill?.system?.rating ?? 0),
        specializationRating: Number(skill?.system?.specializationRating ?? 0),
        concentrationRating: Number(skill?.system?.concentrationRating ?? 0),
        useSpecialization: Boolean(opts.useSpecialization), useConcentration: Boolean(opts.useConcentration),
        relatedRating: opts.relatedSkillId ? Number(this.items.get(opts.relatedSkillId)?.system?.rating ?? 0) : 0,
      })),
      // (not for full-auto spread: it has its own per-target modifier)
      ...(melee || opts.suppressive || (opts.spreadExtraTargets ?? 0) > 0 ? [] : this.#otherTargetMods(targetDoc?.uuid ?? '')),
      ...(melee ? attackerReachModifiers(((w.reach as number | undefined) ?? 0) + this.reachBonus + (style?.style.reach ?? 0), opts.targetReach ?? 0) : []),
      ...vehicleMods,
      // v0.56.0: a Guard power (or spell) on the target.
      ...SR2Actor.attackedMods(targetDoc ? [targetDoc] : []),
      // v0.56.0: an adept's distance strike: killing hands reaching past arm's length.
      ...(opts.distanceStrike && RULES.CRITTERS_V56.distanceStrike.tn ? [{ id: 'distanceStrike', label: tx('SR2E.Card.Mod.distanceStrike'), value: RULES.CRITTERS_V56.distanceStrike.tn }] : []),
    ];
    // v0.61.0: a grenade launcher's minimum arming range (COMBAT_V61.launcher).
    const arming = blast && Number(w.minRange ?? 0) > 0 ? armingCheck({ distance: opts.measuredMetres ?? null, minRange: Number(w.minRange) }) : null;
    if (arming?.blocked) ammoShort = `${weapon.name}: ${arming.note}`;
    else if (arming && (!arming.armed || opts.measuredMetres == null)) notes.push(arming.note);
    const blastExtras = blast ? { ...(arming && !arming.armed ? { dud: true } : {}), ...(w.fuse ? { fuse: String(w.fuse) } : {}), ...(smartGrenade ? { smart: true } : {}), ...(opts.bounce ? { bounce: true } : {}), ...(blastToxin ? { toxin: blastToxin } : {}), ...(indirect ? { indirect: { spotterSuccesses: Math.min(Math.max(0, Number(RULES.COMBAT_V72.indirect.maxSpotterSuccesses) || 0), Math.max(0, Math.floor(Number(indirect.spotterSuccesses) || 0))) } } : {}) } : {};
    // v0.92.1 (RULES.SHEET_V921.tweaks): Power from custom tweaks (this weapon's own, every melee or ranged attack's, any attack's).
    const tweakPower = attackPowerTweak(this.sys?.derived?.tweaks, { weaponId: String(weapon?.id ?? ''), melee });
    if (tweakPower) { power = Math.max(0, power + tweakPower); if (extras.barrierPower !== undefined) extras.barrierPower = Math.max(0, extras.barrierPower + tweakPower); notes.push(tx('SR2E.Card.Actor.tweakPower', { value: tweakPower > 0 ? `+${tweakPower}` : `${tweakPower}` })); }
    return { w, melee, blast, base, power, level, damageType, modeLabel, rounds, earlier, wasted, extras, notes, situational, dice, suffix, modifiers, ammoShort, sd, pool, blastExtras, firstShotSingle };
  }

  /**
   * v0.50.0: what an attacker sees of a target on the canvas, by the eyes given: light at the target,
   * blind fire (walls block every sight line, or the target is unseen), partial cover, smoke on the
   * line of fire (ranged), the target's concealment, prone on either side. Nulls where unknown.
   */
  attackSight(target: any, o: { melee: boolean; vision?: Vision } = { melee: false }): {
    light: TargetNumberModifier | null; blindFire: TargetNumberModifier | null; smoke: TargetNumberModifier | null; concealment: TargetNumberModifier | null;
    partial: boolean; targetProne: boolean; attackerProne: boolean; barrierArmor: number; lit: boolean;
  } {
    const vision = o.vision ?? this.visionNow();
    const out = { light: null as TargetNumberModifier | null, blindFire: null as TargetNumberModifier | null, smoke: null as TargetNumberModifier | null, concealment: null as TargetNumberModifier | null,
      partial: false, targetProne: isProne(target), attackerProne: isProne(this), barrierArmor: 0, lit: false };
    const from = SR2Actor.tokenFor(this), to = SR2Actor.tokenFor(target);
    try {
      const tl = targetLight(to);
      out.light = lightModifier(tl?.light ?? null, vision);
      out.lit = Boolean(tl?.source);
      if (from && to && !o.melee) {
        const cv = RULES.COMBAT.cover.autoDetect ? sightCover(from, to) : null;
        if (cv?.cover === 'blind') out.blindFire = { id: 'blindFireNoLineOfSight', label: tx('SR2E.Card.Mod.blindFireNoLineOfSight'), value: RULES.COMBAT.cover.blindFireTn };
        else if (cv?.cover === 'partial') out.partial = true;
        out.barrierArmor = barrierArmor(barriersBetween(from, to));
      }
      // v0.72.0 (O5): smoke counts in melee too (RULES.COMBAT_V72.meleeSmoke).
      if (from && to && smokeCounts(o.melee)) {
        const sm = smokeBetweenTokens(from, to, SR2Actor.sceneFires((canvas as any)?.scene));
        out.smoke = smokeLook(sm.kind, vision, sm.flames ? 'flames' : sm.source);
      }
    } catch { /* no canvas */ }
    if (RULES.TN_AUTO.attack.concealment && target?.concealmentOf) {
      const c = livingConcealment(vision, target.concealmentFor?.(this) ?? target.concealmentOf());
      if (c.blind) out.blindFire = { label: tx('SR2E.Card.Mod.canTSeeTheTarget', { label: c.label }), value: RULES.COMBAT.cover.blindFireTn };
      else out.concealment = c.modifier;
    }
    return out;
  }

  /**
   * v0.50.0: the defender's side of opposed melee is a fighting roll too (RULES.TN_AUTO.attack.meleeDefenseSight):
   * a blinded defender fights blind, and the light on the attacker counts by the defender's eyes.
   */
  #meleeDefenseSight(attack: any): TargetNumberModifier[] {
    if (!RULES.TN_AUTO.attack.meleeDefenseSight) return [];
    const attacker: any = attack?.attackerUuid ? fromUuidSync(attack.attackerUuid) : null;
    const s = attacker ? this.attackSight(attacker, { melee: true }) : null;
    return attackVisibility({ light: s?.light ?? null, smoke: sightSmoke(true, s?.smoke ?? null), blinded: this.blindMods('attack')[0] ?? null, blindFire: s?.blindFire ?? null, concealment: s?.concealment ?? null });
  }

  /** v0.50.0: a jumped-in rigger firing the vehicle's guns sees with its sensors (RULES.TN_AUTO.rigging.skipBodyStatuses). */
  #sensesAreVehicle(opts: AttackOptions): boolean {
    return Boolean(opts.mounted) && RULES.TN_AUTO.rigging.skipBodyStatuses && this.isJumpedIn();
  }

  /** v0.50.0: the visibility group of an attack (see AttackOptions.sight), with no double counting. */
  #attackVisibilityMods(weapon: any, opts: AttackOptions, ctx: { melee: boolean; situational: readonly string[]; targetDoc: any }): TargetNumberModifier[] {
    const w = weapon.system ?? {};
    const vision = withScopeVision(this.visionNow(), ctx.melee ? '' : String(w.scopeVision ?? ''));
    const auto = opts.sight === undefined && ctx.targetDoc ? this.attackSight(ctx.targetDoc, { melee: ctx.melee, vision }) : null;
    const sight = opts.sight ?? auto ?? {};
    // Older callers name a RULES.VISIBILITY id instead.
    const v = opts.visibility && opts.visibility !== 'normal' ? opts.visibility : '';
    const legacyBlind = v === 'blind' ? { id: 'blindFire', label: tx('SR2E.Card.Mod.blindFire'), value: RULES.COMBAT.cover.blindFireTn } : null;
    const legacyRow = v && v !== 'blind' ? RULES.VISIBILITY.find((x) => x.id === v) : null;
    const legacyLight = legacyRow && legacyRow.value ? { label: legacyRow.label, value: legacyRow.value } : null;
    const fc = ctx.situational.includes('fullCover') ? RULES.SITUATIONAL_MODIFIERS.find((m) => m.id === 'fullCover') : null;
    const blinds = [sight.blindFire, fc ? { label: fc.label, value: fc.value } : null, legacyBlind].filter((m): m is TargetNumberModifier => Boolean(m && m.value));
    const blindFire = blinds.length ? blinds.reduce((a, b) => (b.value > a.value ? b : a)) : null;
    const out = attackVisibility({
      light: sight.light ?? legacyLight, smoke: sightSmoke(ctx.melee, sight.smoke ?? null),
      weather: ctx.melee ? null : this.weatherMods(vision)[0] ?? null,
      blindFire, blinded: this.#sensesAreVehicle(opts) ? null : this.blindMods('attack')[0] ?? null, concealment: sight.concealment ?? null,
    });
    if (auto) {
      const pc = RULES.SITUATIONAL_MODIFIERS.find((m) => m.id === 'partialCover');
      if (auto.partial && pc && !ctx.situational.some((id) => U80C.cbtIsCoverId(id)) && !blindFire) out.push({ label: pc.label, value: pc.value });
      out.push(...proneModifiers({ melee: ctx.melee, targetProne: auto.targetProne, attackerProne: auto.attackerProne }));
    }
    return out;
  }

  /**
   * The Attack dialog's live preview: the final TN with every modifier (including this actor's wound
   * and sustaining penalties), and the dice rolled (skill, focus, pool).
   */
  previewAttack(weapon: any, opts: AttackOptions = {}): { tn: number; base: number; baseLabel: string; modifiers: TargetNumberModifier[]; dice: number; pool: number; power: number; level: DamageLevel; damageType: DamageType; ammoShort: string | null } {
    const plan = this.planAttack(weapon, opts);
    const mods = this.#testModifiers({ modifiers: plan.modifiers, sightHandled: true, ...(opts.mounted ? { vehicle: true } : {}) });
    const total = plan.base.value + mods.reduce((n, m) => n + m.value, 0);
    // v0.79.0 (RULES.DOCS_V79.rangedPoolCap 'skill', SRII p. 83): Combat Pool dice on an attack at most the skill rolled.
    const asked = plan.pool === 'combat' ? offensivePoolDice(opts.poolDice ?? 0, (plan.sd as any).base ?? plan.sd.dice) : opts.poolDice ?? 0;
    const pool = Math.max(0, Math.min(asked, (this.sys.derived?.[`${plan.pool}PoolLeft`] as number | undefined) ?? 0));
    return {
      tn: Math.max(RULES.MIN_TARGET_NUMBER, total), base: plan.base.value, baseLabel: plan.base.label, modifiers: mods, dice: plan.dice, pool,
      power: plan.power, level: plan.level, damageType: plan.damageType, ammoShort: plan.ammoShort,
    };
  }

  /** The built-in unarmed attack as a weapon-like object (for attackWith and melee defense). */
  static unarmed(): { id: string; name: string; system: any } {
    const u = unarmedWeapon();
    return { id: 'unarmed', name: u.name, system: { ...u, ammo: 0, ammoMax: 0, modes: '', recoilComp: 0, magical: false, smartgun: false, specialization: '' } };
  }

  /**
   * Attack with a weapon. Rolls the weapon's skill (or Quickness at a TN penalty if the actor has
   * none) against the range/melee TN. If a target is given, the chat card carries a Defend button
   * for each target (or Resist buttons for blasts). `weapon` may be SR2Actor.unarmed().
   */
  async attackWith(weapon: any, opts: AttackOptions = {}): Promise<SuccessTestResult | null> {
    return this.#oneAtATime('attack', null, () => this.#attackWith(weapon, opts));
  }

  async #attackWith(weapon: any, opts: AttackOptions = {}): Promise<SuccessTestResult | null> {
    if (!this.canAct('attack')) return null;
    if (this.type === 'vehicle' && this.sys.derived?.destroyed) {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.isDestroyed', { name: escHtml(this.name) }));
      return null;
    }
    if (weapon?.system?.jammed) {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.isJammedClearItFirstA', { weaponName: escHtml(weapon.name) }));
      return null;
    }
    // v0.92.1 (RULES.SHEET_V921.carried): a weapon left behind can't be used until it is carried again.
    if (weapon?.system && !isCarried(weapon)) {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.notCarried', { name: escHtml(weapon.name) }));
      return null;
    }
    // v0.58.0: a broken weapon has to be repaired first.
    if (weapon?.system?.damaged) {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.isBrokenRepairItFirstIts', { weaponName: escHtml(weapon.name) }));
      return null;
    }
    // v0.55.0: a cybergun works only while its cyberware is installed, working and healed in.
    if (weapon?.system?.implantId) {
      const ware: any = [...this.items].find((i: any) => i.id === weapon.system.implantId);
      const healing = recoveringItemIds(this.sys.recovering ?? [], sysNow());
      if (!ware || !ware.system?.installed || ware.system?.damaged || healing.includes(ware.id)) {
        ui.notifications?.warn?.(tx('SR2E.Notify.Actor.isBuiltIntoWhichIs', { weaponName: escHtml(weapon.name), wareName: escHtml(ware?.name ?? tx('SR2E.Notify.Actor.cyberwareThatIsGone')), part: !ware ? tx('SR2E.Notify.Actor.missing') : !ware.system?.installed ? tx('SR2E.Notify.Actor.notInstalled') : ware.system?.damaged ? tx('SR2E.Notify.Actor.damaged') : tx('SR2E.Notify.Actor.stillHealingIn') }));
        return null;
      }
    }
    // v0.55.0: drawing the weapon first (RULES.COMBAT.ready): a Simple Action, free with a quick-draw holster.
    // (With 'action', a holstered weapon is drawn first from the sheet: a Simple Action before the attack's own.)
    if (weapon?.system && weapon.system.ready === false && typeof weapon.update === 'function' && RULES.COMBAT.ready.rule !== 'off') {
      if (RULES.COMBAT.ready.rule === 'action' && !weapon.system.quickDraw) {
        ui.notifications?.warn?.(tx('SR2E.Notify.Actor.isHolsteredDrawItFirstA', { weaponName: escHtml(weapon.name) }));
        return null;
      }
      opts = { ...opts, note: [opts.note, weapon.system.quickDraw ? tx('SR2E.Card.Actor.quickDrawn') : tx('SR2E.Card.Actor.drawnASimpleAction')].filter(Boolean).join(', ') };
    }
    // v0.71.0 (R12): every attack (group, mounted, quick rolls) resists an invisibility spell on its targets first,
    // not only the Attack dialog's (a target already resisted isn't rolled again).
    // v0.81.1 (D2-9): the refusals first (an empty magazine, a manifesting attacker), so a refused attack rolls no
    // invisibility test; the plan is then worked out again with what the observer now sees.
    const pre = this.planAttack(weapon, opts);
    if (pre.ammoShort) {
      ui.notifications?.warn?.(escHtml(pre.ammoShort));
      return null;
    }
    // v0.56.0: a manifested form is seen and heard in the physical world but can't act there.
    if (this.isManifesting() && RULES.MAGIC_V56.manifest.blocksPhysical) {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.isManifestingSeenAndHeardIn', { name: escHtml(this.name) }));
      return null;
    }
    const seen = [opts.targetUuid, ...(opts.hits ?? []).map((h: any) => h.targetUuid)].filter(Boolean).map((u) => fromUuidSync(u as string)).filter(Boolean);
    await this.spotInvisible(seen);
    const plan = seen.length ? this.planAttack(weapon, opts) : pre;
    const { w, melee, blast, base, power, level, damageType, modeLabel, rounds, earlier, wasted, extras, notes, dice, suffix, modifiers } = plan;
    // v0.81.0 (D2-15): drawn only once the attack isn't refused.
    if (weapon?.system?.ready === false && typeof weapon.update === 'function' && RULES.COMBAT.ready.rule !== 'off') await weapon.update({ 'system.ready': true });
    // Targets: one, or several with their own Power (shotgun spread, blasts).
    const hits = opts.hits ?? (opts.targetUuid ? [{ targetUuid: opts.targetUuid }] : []);
    for (const h of hits) {
      // An unmaterialized spirit is only on the astral plane: physical attacks cannot reach it.
      const target: any = await fromUuid(h.targetUuid);
      if (target?.type === 'spirit' && target.system?.materialized === false) {
        if (hits.length === 1) {
          ui.notifications?.warn?.(tx('SR2E.Notify.Actor.isNotMaterializedOnlyAstralAttacks', { targetName: escHtml(target.name) }));
          return null;
        }
      }
    }
    const reachable = [];
    for (const h of hits) {
      const t: any = await fromUuid(h.targetUuid);
      if (!(t?.type === 'spirit' && t.system?.materialized === false)) reachable.push(h);
    }
    // v0.79.0 (RULES.DOCS_V79.rangedSurprise 'order', SRII p. 86): in the surprise turn nobody may act against an opponent with more successes.
    const surpriseCombat: any = game.combat;
    if (surpriseCombat?.started && typeof surpriseCombat.surpriseBlocked === 'function' && reachable.length) {
      const blocked: any[] = surpriseCombat.surpriseBlocked(this, (await Promise.all(reachable.map((h) => fromUuid(h.targetUuid)))).filter(Boolean));
      if (blocked.length) {
        const msg = tx('SR2E.Card.Actor.surpriseTurnRolledFewerSurpriseSuccesses', { name: this.name, blocked: blocked.map((t: any) => t.name).join(', ') });
        ui.notifications?.warn?.(escHtml(msg));
        if (!(game as any).user?.isGM) return null;
      }
    }


    // v0.59.0: killing hands are magical (RULES.ADEPT.killingHands.magical).
    const khMagic = weapon.id === 'unarmed' && RULES.ADEPT.killingHands.magical && Boolean(killingHandsLevel(this.adeptSpecial('killingHands')));
    const magical = ignoresImmunity(Boolean(w.magical) || khMagic, melee && weapon.id !== 'unarmed' && weaponFocusDice(this.foci(), weapon.name).dice > 0);
    const dodge = RULES.COMBAT.blast.dodge;
    // v0.55.0: a target the attacker surprised this turn doesn't know it is coming (RULES.COMBAT.unaware).
    const surprised: string[] = RULES.COMBAT.unaware.autoFromSurprise ? this.#surprisedTargets() : [];
    const attackTargets = reachable.map((h) => ({
      attackerUuid: this.uuid as string, targetUuid: h.targetUuid, weaponName: weapon.name, melee, damageType,
      power: h.power ?? Math.max(0, power + (h.powerDelta ?? 0)), level: h.level ?? level,
      ...(magical ? { ignoreImmunity: true } : {}),
      ...(w.antiVehicle ? { antiVehicle: true } : {}),
      ...(melee ? { reach: ((w.reach as number | undefined) ?? 0) + this.reachBonus } : {}),
      // v0.56.0: a distance strike is dodged like a ranged attack: no counterattack.
      ...(melee && opts.distanceStrike ? { distance: true } : {}),
      // v0.61.0: a monowhip can hit its wielder; superior position carries to the defender's roll.
      ...(melee && w.selfHit ? { selfHit: true, selfHitSkill: String(w.skill || 'Armed Combat') } : {}),
      ...(melee && (opts.superior === 'attacker' || opts.superior === 'defender') && RULES.COMBAT_V61.superiorPosition.enabled ? { superior: opts.superior } : {}),
      ...extras,
      ...(blast ? { fixedDamage: true, ...(dodge ? {} : { noDodge: true }) } : {}),
      // The dialog's "Target unaware" is for the chosen target, not bystanders in a spread or a blast.
      ...(surprised.includes(h.targetUuid) || (opts.unaware && h.targetUuid === (opts.targetUuid ?? opts.hits?.[0]?.targetUuid)) ? { unaware: true } : {}),
    }));
    const blastCtx: BlastContext | null = blast && opts.blastPoint
      ? {
        attackerUuid: this.uuid as string, weaponName: weapon.name, power, level, damageType, dodge, point: opts.blastPoint,
        perMetre: blastFalloff(w.blastKind, Number(w.blastPerMetre ?? RULES.COMBAT.blast.powerPerMetre)),
        range: opts.range ?? 'short', kind: w.blastKind ?? 'custom',
        scatterType: grenadeScatterType({ blastKind: w.blastKind, skill: w.skill, name: weapon.name, thrown: Boolean(w.thrown) }),
        ...U80C.cbtScatterExtras({ blastKind: w.blastKind, name: weapon.name, guidance: Number(w.guidance ?? 0) }),
        ...plan.blastExtras,
      }
      : null;

    if (!melee && w.ammoMax > 0 && typeof weapon.update === 'function') await weapon.update({ 'system.ammo': w.ammo - rounds - wasted });
    // v0.61.0: a stun baton spends a charge per blow.
    if (melee && w.stunWeapon && w.ammoMax > 0 && w.ammo > 0 && typeof weapon.update === 'function') await weapon.update({ 'system.ammo': w.ammo - 1 });
    // Remember the rounds fired so the next attack in this phase picks up the recoil.
    const phase = melee ? null : this.currentPhaseKey();
    // v0.79.0 (RULES.DOCS_V79.rangedRecoil): and whether the phase's first shot was a single shot.
    if (phase) await this.setFlag(SYSTEM_ID, 'recoil', { ...recordRounds(phase, earlier, rounds), firstSingle: plan.firstShotSingle ?? true });
    // v0.55.0: the targets shot at this phase (another target next costs TN), and an aim used up.
    const phaseNow = this.currentPhaseKey();
    if (phaseNow && !melee) {
      const f = this.getFlag?.(SYSTEM_ID, 'phaseTargets') as { phase: string; targets: string[] } | undefined;
      const before = f?.phase === phaseNow ? f.targets ?? [] : [];
      const chosen = opts.suppressive ? '' : (opts.targetUuid ?? opts.hits?.[0]?.targetUuid ?? '');
      if (chosen) await this.setFlag(SYSTEM_ID, 'phaseTargets', { phase: phaseNow, targets: [...new Set([...before, chosen])] });
    }
    if (this.getFlag?.(SYSTEM_ID, 'aim')) await clearFlag(this, 'aim');
    // v0.72.0 (O7): shots fired indirect at one spot walk in (RULES.COMBAT_V72.indirect.adjustTnPerShot).
    if (plan.blastExtras && (plan.blastExtras as any).indirect && opts.blastPoint && (game.combat as any)?.started) {
      const c: any = game.combat;
      const { state } = nextAdjust(this.getFlag?.(SYSTEM_ID, 'adjust') as AdjustState | undefined, { x: opts.blastPoint.x, y: opts.blastPoint.y, combatId: String(c.id) }, Number((canvas as any)?.grid?.size ?? 100));
      await this.setFlag(SYSTEM_ID, 'adjust', state);
    }

    // v0.79.0 (RULES.DOCS_V79.rangedPoolCap 'skill', SRII p. 83): Combat Pool dice on an attack are at most the skill rolled.
    const poolAsked = Math.max(0, opts.poolDice ?? 0);
    const poolUsed = plan.pool === 'combat' ? offensivePoolDice(poolAsked, (plan.sd as any).base ?? plan.sd.dice) : poolAsked;
    if (poolUsed < poolAsked) notes.push(tx('SR2E.Card.Actor.combatPoolAtMostTheSkill', { poolUsed }));
    const measured = opts.measuredMetres != null
      ? `, ${Math.round(opts.measuredMetres * 10) / 10} m${opts.outOfRange ? (melee ? tx('SR2E.Card.Actor.outOfReach') : tx('SR2E.Card.Actor.beyondExtreme')) : ''}`
      : '';
    const title = `${weapon.name}${modeLabel ? ` [${modeLabel}]` : ''} (${base.label}${measured}, ${power}${level}${damageType !== w.damageType ? ` ${damageType}` : ''})${notes.length ? ` [${notes.join(', ')}]` : ''}${blast ? tx('SR2E.Card.Actor.blast2') : ''}${suffix}`;
    return this.#runTest(title, dice, { targetNumber: base.value, modifiers, poolDice: poolUsed, pool: plan.pool, sightHandled: true, ...(opts.exclude?.length ? { exclude: opts.exclude } : {}), ...(opts.mounted ? { vehicle: true } : {}) }, {
      kind: 'attack', ...(weapon?.id && typeof weapon.update === 'function' ? { weaponId: weapon.id } : {}),
      ...(attackTargets.length === 1 ? { attack: attackTargets[0] } : {}),
      ...(attackTargets.length > 1 ? { attackTargets } : {}),
      ...(blastCtx ? { blast: blastCtx } : {}),
    });
  }

  /**
   * A scattered blast lands: post a card with every target caught in it and their Power there.
   * `hits` come from the canvas (distance from the landing point). `note` is HTML (v0.81.0): callers escape
   * the names in it (applications/chat.ts), so it is not escaped again here.
   */
  async postBlast(ctx: BlastContext, hits: Array<{ targetUuid: string; name: string; metres: number; barrierLoss?: number; barrierArmor?: number }>, note: string, bonus = 0, at?: { x: number; y: number }): Promise<void> {
    // Where it went off (v0.37.0): the GM can then damage the walls nearby.
    // v0.81.1 (FX-APP design 2): the blast's real source for the routine rule (chat.ts damageSources).
    const blastAt = { point: at ?? ctx.point, power: ctx.power + bonus, perMetre: ctx.perMetre, ...(ctx.shaped ? { shaped: true } : {}), ...(ctx.antiVehicle ? { antiVehicle: true } : {}), ...(typeof ctx.attackerUuid === 'string' && ctx.attackerUuid && ctx.attackerUuid.length <= 400 ? { attackerUuid: ctx.attackerUuid } : {}) };
    const kind = grenadeKind(ctx.kind);
    const caught = hits
      // v0.72.0 (O1): Power lost to walls on the way (RULES.COMBAT_V72.blastBarriers).
      .map((h) => ({ h, p: ctx.power - blastLoss(h.metres, ctx.perMetre) + bonus - Math.max(0, h.barrierLoss ?? 0) }))
      .filter((e) => e.p > 0);
    // v0.61.0: a smoke grenade fills the area with smoke (a smoke region) that lingers some Combat Turns.
    if (kind.effect === 'smoke') {
      const cloud = grenadeSmoke(String(ctx.kind ?? ""));
      const point = at ?? ctx.point;
      const made = cloud && point ? await drawArea(point, cloud.radius, `${ctx.weaponName}: smoke`, 60, undefined, { turns: cloud.turns, smoke: cloud.smoke }) : null;
      const said = cloud ? tx('SR2E.Card.Actor.fillsMAroundTheSpotFor', { part: cloud.smoke === 'thermal' ? tx('SR2E.Card.Actor.thermalSmoke') : tx('SR2E.Card.Actor.smoke2'), cloudRadius: cloud.radius, cloudTurns: cloud.turns, part2: made || !isGmNow() ? '' : tx('SR2E.Card.Actor.noSceneToDrawItOn') }) : tx('SR2E.Card.Actor.smokeItsEffectIsTheGm');
      await ChatMessage.create({
        speaker: ChatMessage.getSpeaker({ actor: this }),
        content: `<div class="sr2e-roll"><h3>${escText(ctx.weaponName)} (${escText(kind.label)})</h3><p>${note}</p></div><p>${said}</p>`,
      });
      return;
    }
    // v0.78.0 (RULES.BOOK_V78.flash 'book'): a flash adds to the TNs of everyone with a clear line to it (by distance,
    // halved by flare compensation) for 5 Combat Turns less 1 per 2 successes on a Body test; the 5L blast follows.
    const flashBook = kind.effect === 'blind' && RULES.BOOK_V78.flash.mode === 'book';
    if (flashBook) {
      const F = RULES.BOOK_V78.flash;
      const rolls: any[] = [];
      const rows: string[] = [];
      for (const h of hits) {
        const a: any = await fromUuid(h.targetUuid);
        if (!a || a.type === 'vehicle') continue;
        // Review fix: someone already blind (a Blinded status with no timer) stays blind; the flash changes nothing.
        const untilNow = (a.getFlag?.(SYSTEM_ID, 'statusUntil') as Record<string, unknown> | undefined) ?? {};
        if (a.hasStatus?.('blind') && untilNow['blind'] == null) { rows.push(`<li>${tx('SR2E.Card.Actor.alreadyBlind', { name: escText(h.name) })}</li>`); continue; }
        const flare = Boolean(a.system?.derived?.cyber?.flareComp);
        const tn = flashTn({ metres: h.metres, flareComp: flare });
        if (tn <= 0) { rows.push(`<li>${tx('SR2E.Card.Actor.tooFarAwayNoEffect', { name: escText(h.name) })}</li>`); continue; }
        const body = Math.max(0, Number(a.system?.attributes?.body?.total ?? 0));
        const r = await successTest({ dice: body, targetNumber: F.bodyTn, roll: foundryRoller(rolls) });
        const turns = flashDuration(r.successes);
        let byGm = false;
        if (turns > 0) byGm = !(await this.#timedStatusOn(a, 'blind', turns * RULES.TOXINS.secondsPerTurn, tn));
        rows.push(`<li>${tCount(r.successes, 'SR2E.Card.Actor.mBodyVsSuccesses', { name: escText(h.name), metres: Math.round(h.metres), part: flare ? tx('SR2E.Card.Actor.flareCompensationHalvesIt') : '', part2: turns > 0 ? `<strong>${tx('SR2E.Card.Actor.tn12', { tn })}</strong> ${tCount(turns, 'SR2E.Card.Actor.forCombatTurns3', { part: byGm ? tx('SR2E.Card.Actor.theGmAppliesIt2') : '' })}` : tx('SR2E.Card.Actor.shakesItOff'), body, fBodyTn: F.bodyTn })}</li>`);
      }
      await ChatMessage.create({
        speaker: ChatMessage.getSpeaker({ actor: this }),
        content: `<div class="sr2e-roll"><h3>${escText(ctx.weaponName)} (${escText(kind.label)})</h3><p>${note}</p></div>${rows.length ? `<ul class="sr2e-blast">${rows.join('')}</ul>` : `<p><em>${tx('SR2E.Card.Actor.noOneSeesTheFlash')}</em></p>`}<p class="hint">${tx('SR2E.Card.Actor.everyoneWithAClearLineTo', { fBaseTn: F.baseTn, fMetresPerPoint: F.metresPerPoint, fMaxMetres: F.maxMetres })}</p>`,
        rolls,
      });
      if (!caught.length) return;
    }
    // Flash and gas grenades: an effect on everyone caught instead of damage.
    if (kind.effect && !flashBook) {
      const immune: string[] = [];
      const byGm: string[] = [];
      if (kind.effect === 'blind') {
        for (const e of caught) {
          const a: any = await fromUuid(e.h.targetUuid);
          // Flare compensation shrugs off the flash (RULES.CYBERWARE.flareCompensation).
          if (a?.system?.derived?.cyber?.flareComp && RULES.CYBERWARE.flareCompensation.blocksFlash) { immune.push(e.h.name); continue; }
          // Blinded for a while (RULES.STATUSES.blind); it clears itself.
          const bl = RULES.STATUSES.blind;
          const inCombat = Boolean((game as any).combat?.started);
          if (typeof a?.setTimedStatus === 'function') { if (!(await this.#timedStatusOn(a, 'blind', inCombat ? bl.flashTurns * RULES.TOXINS.secondsPerTurn : bl.flashSeconds))) byGm.push(e.h.name); }
          else try { await a?.toggleStatusEffect?.('blind', { active: true }); } catch { /* no status */ }
        }
      }
      const names = caught.map((e) => e.h.name).filter((n) => !immune.includes(n)).map((n) => (byGm.includes(n) ? tx('SR2E.Card.Actor.theGmAppliesIt', { n }) : n));
      // v0.55.0: a gas grenade with a toxin on it: everyone in the cloud resists that toxin (masks and filters count).
      const what = kind.effect === 'blind' ? tx('SR2E.Card.Actor.blindedForCombatTurns', { blindFlashTurns: RULES.STATUSES.blind.flashTurns }) : ctx.toxin ? tx('SR2E.Card.Actor.inTheGasCloudResistIt', { toxinName: escText(ctx.toxin.name) }) : tx('SR2E.Card.Actor.inTheGasCloudItsEffect');
      await ChatMessage.create({
        speaker: ChatMessage.getSpeaker({ actor: this }),
        content: `<div class="sr2e-roll"><h3>${escText(ctx.weaponName)} (${escText(kind.label)})</h3><p>${note}</p></div><p>${names.length ? `${escText(names.join(', '))}: ${what}.` : immune.length ? '' : `<em>${tx('SR2E.Card.Actor.noOneIsCaught')}</em>`}</p>${immune.length ? `<p>${tx('SR2E.Card.Actor.flareCompensationNotBlinded', { immune: escText(immune.join(', ')) })}</p>` : ''}`,
      });
      // The toxin's card follows the blast card ("below").
      if (kind.effect !== 'blind' && ctx.toxin && caught.length) await this.exposeToxinState(ctx.toxin, caught.map((e) => e.h.targetUuid), tx('SR2E.Card.Actor.theGasCloud', { weaponName: ctx.weaponName }));
      return;
    }
    const damages: DamageState[] = caught
      .map(({ h, p }) => ({ targetUuid: h.targetUuid, melee: false, damageType: ctx.damageType, power: p, level: ctx.level, armorKind: RULES.COMBAT.blast.armorKind, ...(h.barrierArmor ? { extraArmor: h.barrierArmor } : {}) }));
    const rows = damages.map((d, i) => `<li>${escText(hits.find((h) => h.targetUuid === d.targetUuid)?.name ?? tx('SR2E.Card.Actor.target'))}: <strong>${d.power}${d.level}</strong> <button type="button" data-sr2e-action="resist" data-index="${i}">${tx('SR2E.Card.Actor.resist')}</button></li>`).join('');
    await ChatMessage.create({
      speaker: ChatMessage.getSpeaker({ actor: this }),
      content: `<div class="sr2e-roll"><h3>${tx('SR2E.Card.Actor.detonation', { weaponName: escText(ctx.weaponName) })}</h3><p>${note}${bonus ? tx('SR2E.Card.Actor.confinedSpacePower', { bonus }) : ''}</p></div>${damages.length ? `<ul class="sr2e-blast">${rows}</ul><p><button type="button" data-sr2e-action="combineBlast" title="${tx('SR2E.Card.Actor.gmThisAndTheBlastBefore')}">${tx('SR2E.Card.Actor.combineWithTheLastBlastGm')}</button></p>` : `<p><em>${tx('SR2E.Card.Actor.noOneIsCaughtInThe')}</em></p>`}`,
      flags: { [SYSTEM_ID]: { damages, ...(damages[0] ? { damage: damages[0] } : {}), blastAt } },
    });
  }

  /**
   * Defend against an attack card. Ranged attacks can only be dodged with Combat Pool dice.
   * Melee is an opposed test (RULES.COMBAT.melee): the defender rolls their own melee skill with
   * `weaponId` (or unarmed) and may counterattack. Posts the outcome with a Resist button.
   */
  async defend(attack: AttackState, poolDice = 0, opts: { weaponId?: string | null; fullDefense?: boolean; subdue?: boolean } = {}): Promise<void> {
    if (this.type === 'vehicle') return this.#defendVehicle(attack, poolDice);
    if (attack.matrix) return this.#defendMatrix(attack, poolDice);
    const poolType = this.poolFor(attack);
    const pool = Math.min(Math.max(0, poolDice), this.sys.derived[`${poolType}PoolLeft`] as number);
    // A projecting magician's empty body cannot dodge physical attacks.
    const emptyBody = !attack.astral && RULES.MAGIC_EXTRA.projection.emptyBodyDefenseless && this.sys.derived?.astralMode === 'projecting';
    // Unconscious, dying or dead: no defense at all.
    // v0.70.0: paralysed, asleep or turned to stone too (RULES.FIXES_V70.helplessStatuses); before, they dodged in full.
    const held = attack.matrix || attack.astral ? '' : this.helplessStatus();
    const down = (RULES.CONDITIONS.blockActions && incapacitated(this.sys.derived?.status) && !attack.matrix) || Boolean(held);
    // v0.70.0: bound or held can't dodge a ranged attack (melee is still opposed) (RULES.FIXES_V70.noDodgeStatuses).
    const pinned = !attack.matrix && !attack.astral && !attack.melee && (RULES.FIXES_V70.noDodgeStatuses as string[]).some((s) => this.hasStatus(s));
    // v0.55.0: suppressive fire passes over someone who took cover (prone), when RULES.COMBAT.suppressive.coverIsSafe.
    if (attack.suppressive && RULES.COMBAT.suppressive.coverIsSafe && isProne(this)) {
      await ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor: this }), content: `<p><strong>${escText(this.name)}</strong> ${tx('SR2E.Card.Actor.isDownInCoverTheSuppressive')}</p>` });
      return;
    }
    // v0.55.0: a target that doesn't know the attack is coming can't dodge, counter or use pool dice.
    const unaware = Boolean(attack.unaware) && !attack.matrix && !attack.astral;
    // v0.80.0 (URR_V80.cbtDefense 'cleanMiss', URR): no dodge test: the Defend dialog's pool dice go to the resistance test
    // (none when helpless), where they can make it a clean miss; the attack's successes are staged there.
    if (U80C.cbtCleanMissRanged(attack, opposedMelee(attack) && !emptyBody && !down && !unaware)) {
      const cm80: DamageState = { targetUuid: this.uuid as string, melee: Boolean(attack.melee), damageType: attack.damageType, power: attack.power, level: attack.level, ...armorExtras(attack), cleanMiss80: { hits: attack.attackSuccesses, net: attack.attackSuccesses } };
      if (pool > 0 && (emptyBody || down || unaware || pinned)) await ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor: this }), content: `<p><strong>${escText(this.name)}</strong> ${tx('SR2E.Card.Actor.canTUsePoolDiceAgainst')}</p>` });
      return this.resistFromState(cm80, emptyBody || down || unaware || pinned ? 0 : pool);
    }
    const full = (Boolean(opts.fullDefense) || this.fullDefenseUp()) && !emptyBody && !down && !unaware && !pinned && !attack.astral && !attack.matrix;
    // v0.80.0 (URR_V80.cbtDefense 'cleanMiss', URR): full defense adds no dice and no pool to the melee test (the pool goes to the soak).
    const fullDice = full ? U80C.cbtFullDefenseDice(await this.#takeFullDefense()) : 0;
    // v0.80.0 (review #4): the defender's full defense rides on the snapshot, so a clean miss is allowed only then.
    if (opposedMelee(attack) && !emptyBody && !down && !unaware) return this.#defendMelee(full && U80C.cbtCleanMissOn() ? { ...attack, fullDefense80: true } : attack, U80C.cbtMeleeDefensePool(full, pool), opts.weaponId ?? null, fullDice, Boolean(opts.subdue));
    const helpless = emptyBody || down || unaware || pinned;
    // Adept combat sense adds dice to dodging (v0.39.0).
    // v0.78.0 (RULES.BOOK_V78.combatSense 'pool'): Combat Sense is in the Combat Pool instead.
    const sense = helpless || attack.astral || RULES.BOOK_V78.combatSense === 'pool' ? 0 : this.adeptSpecial('combatSense') * RULES.ADEPT.combatSense.dicePerLevel;
    // v0.47.0: a worn shield helps against ranged attacks too (RULES.GEAR.shields.ranged).
    const sh = helpless || attack.astral || attack.melee ? { dice: 0, tn: 0, name: '' } : this.shieldParry();
    const shieldDice = rangedShieldDice(sh.dice || sh.tn ? Math.max(sh.dice, -sh.tn) : 0);
    const baseDice = (helpless ? 0 : attack.astral ? this.sys.derived.astral.quickness : attack.melee ? this.sys.attributes.quickness.total : 0) + fullDice + sense + shieldDice;
    const rolls: any[] = [];
    const result = await successTest({
      dice: baseDice,
      poolDice: helpless ? 0 : pool,
      targetNumber: attack.targetNumber,
      roll: foundryRoller(rolls),
    });
    if (pool > 0 && !helpless) await this.#spendPool(poolType, pool);
    const label = held ? tx('SR2E.Card.Actor.defenseless', { held }) : down ? tx('SR2E.Card.Actor.defenseless2', { derivedStatus: this.sys.derived.status }) : pinned ? tx('SR2E.Card.Actor.defenselessHeldCannotDodge') : unaware ? tx('SR2E.Card.Actor.defenselessNeverSawItComing') : emptyBody ? tx('SR2E.Card.Actor.defenselessBodyEmptyWhileProjecting') : attack.astral ? tx('SR2E.Card.Actor.astralDefense')
      : full ? tx('SR2E.Card.Actor.fullDefenseDice', { fullDice, part: shieldDice ? ` (${sh.name} +${shieldDice})` : '' }) : pool === 0 && !attack.melee && !sense && !shieldDice ? tx('SR2E.Card.Actor.defenseNoPoolDice') : tx('SR2E.Card.Actor.defense', { part: attack.melee ? tx('SR2E.Card.Actor.melee') : tx('SR2E.Card.Actor.dodge'), part2: shieldDice ? ` (${sh.name} +${shieldDice})` : '' });
    await this.#post(this.#snapshot(label, result, { kind: 'defend', defendAgainst: attack }), result, rolls);
  }

  /** The melee weapons this actor can defend with, plus unarmed. */
  meleeWeapons(): Array<{ id: string; name: string; system: any }> {
    const parry = RULES.SKILLS.parry ? this.findSkill(RULES.SKILLS.parrySkill) : null;
    return [...[...this.items].filter((i: any) => i.type === 'weapon' && i.system.melee && isCarried(i)), ...this.cyberWeapons(), SR2Actor.unarmed(),
      // Parry (house rule, v0.38.0): block with the Parry skill; no counterattack.
      ...(parry && parry.system.rating > 0 ? [{ id: 'parry', name: tx('SR2E.Text.Actor.blockOnly', { name: parry.name }), system: { melee: true, damageLevel: 'L', damageType: 'stun', damagePower: 0 } }] : [])];
  }

  /** The best martial art / unarmed style this character knows, when it beats Unarmed Combat (v0.38.0). */
  martialStyle(): { skill: any; style: MartialStyle } | null {
    const base = this.findSkill(RULES.COMBAT.unarmed.skill)?.system?.rating ?? 0;
    const best = [...this.items].filter((i: any) => i.type === 'skill' && i.system.martial?.enabled && (i.system.rating ?? 0) > 0)
      .sort((a: any, b: any) => b.system.rating - a.system.rating)[0];
    if (!best || best.system.rating < base) return null;
    const m = best.system.martial;
    return { skill: best, style: { power: m.power ?? 0, stage: m.stage ?? 0, reach: m.reach ?? 0, defense: m.defense ?? 0 } };
  }

  /**
   * Full defense: the defender's extra dice (RULES.COMBAT.fullDefense.attribute), and in a started
   * combat their next action is given up (initiative lowered).
   */
  async #takeFullDefense(): Promise<number> {
    const f = RULES.COMBAT.fullDefense;
    const dice = (this.sys.attributes?.[f.attribute]?.total as number | undefined) ?? 0;
    // Already declared (v0.35.0): no further cost until the defender's next action.
    if (this.fullDefenseUp()) return dice;
    try {
      if ((game.combat as any)?.started) await this.setFlag(SYSTEM_ID, 'fullDefense', this.#combatNow());
    } catch { /* not ours */ }
    try {
      const c: any = game.combat;
      const combatant = c?.started ? this.myCombatant() : null;
      if (combatant && typeof combatant.initiative === 'number') await c.updateEmbeddedDocuments('Combatant', [{ _id: combatant.id, initiative: combatant.initiative - f.initiativeCost }]);
    } catch { /* no combat */ }
    return dice;
  }

  /** Opposed melee defense: melee skill with a weapon (or unarmed) vs the base melee TN, reach and own penalties. */
  async #defendMelee(attack: AttackState, pool: number, weaponId: string | null, fullDice = 0, subdue = false): Promise<void> {
    // v0.71.0 (R12): an invisible attacker is resisted first (the defense's sight modifiers then know).
    const attackerActor: any = attack?.attackerUuid ? fromUuidSync(attack.attackerUuid) : null;
    if (attackerActor) await this.spotInvisible([attackerActor]);
    // Parry (house rule, v0.38.0): the Parry skill blocks; winning means no damage, never a counterattack.
    // A worn shield's Parry rating helps every melee defense (RULES.GEAR.shields, v0.43.0).
    const sh = this.shieldParry();
    const shMods: TargetNumberModifier[] = sh.tn ? [{ label: tx('SR2E.Card.Mod.shield', { shName: sh.name }), value: sh.tn }] : [];
    const shNote = sh.dice ? ` (${sh.name} +${sh.dice})` : '';
    if (weaponId === 'parry' && RULES.SKILLS.parry) {
      const ps = this.#skillDice(this.findSkill(RULES.SKILLS.parrySkill));
      await this.#runTest((fullDice ? tx('SR2E.Card.Actor.parryWithFullDefense2', { psSuffix: ps.suffix, shNote, fullDice }) : tx('SR2E.Card.Actor.parryPlain', { psSuffix: ps.suffix, shNote })), ps.dice + fullDice + sh.dice,
        { targetNumber: RULES.MELEE_BASE_TN, modifiers: [...ps.modifiers, ...shMods, ...this.#meleeDefenseSight(attack)], poolDice: offensivePoolDice(pool, (ps as any).base ?? ps.dice) },
        { kind: 'defend', defendAgainst: attack });
      return;
    }
    const weapon = this.weaponById(weaponId) as any;
    const wpn = weapon && weapon.id !== 'unarmed' && weapon.system?.melee ? weapon : SR2Actor.unarmed();
    const ws = wpn.system;
    const strength = this.attackStrength(wpn.limbId ?? null).strength;
    // A martial art defends unarmed (v0.38.0): its skill, defense dice and counterattack damage.
    const style = wpn.id === 'unarmed' ? this.martialStyle() : null;
    const sd0 = this.#skillDice(style ? style.skill : this.findSkill(ws.skill));
    const sd = style ? { ...sd0, dice: sd0.dice + style.style.defense, suffix: `${sd0.suffix} (${style.skill.name}${style.style.defense ? ` +${style.style.defense}` : ''})` } : sd0;
    const focus = wpn.id !== 'unarmed' ? weaponFocusDice(this.foci(), wpn.name) : { dice: 0, notes: [] };
    const sm = style ? martialAttack({ power: weaponPower(ws, strength), level: ws.damageLevel as DamageLevel, reach: (ws.reach as number | undefined) ?? 0 }, style.style) : null;
    const kh = wpn.id === 'unarmed' ? killingHandsLevel(this.adeptSpecial('killingHands')) : null;
    const counter: CounterWeapon = {
      weaponName: style ? style.skill.name : wpn.name, power: sm?.power ?? weaponPower(ws, strength), level: (sm?.level ?? kh ?? ws.damageLevel) as DamageLevel,
      damageType: (kh ? 'physical' : ws.damageType) as DamageType, reach: (sm?.reach ?? ((ws.reach as number | undefined) ?? 0)) + this.reachBonus,
      ...(ignoresImmunity(Boolean(ws.magical) || Boolean(kh && RULES.ADEPT.killingHands.magical), focus.dice > 0) ? { ignoreImmunity: true } : {}),
    };
    const inf: any = RULES.CRITTERS.infection.enabled ? [...this.items].find((i: any) => i.type === 'power' && i.system?.special === 'infection') : null;
    if (inf) counter.infection = { ...infectionFrom({ name: inf.name, substance: inf.system.substance, rating: inf.system.rating, damageLevel: inf.system.damageLevel }), from: this.name as string };
    // v0.71.0 (R10): the counterattack keeps what the weapon would do on an attack of its own.
    if (RULES.FIXES_V71.counterWeaponExtras) await this.#counterExtras(wpn, counter, { subdue, killingHands: Boolean(kh), style: Boolean(style) });
    const reach = reachModifiers(attack.reach ?? 0, counter.reach);
    // v0.55.0: the defender's own side of the melee table: prone on either side, and the defender's friends in the melee.
    const situation = this.#meleeDefenderSituation(attack, counter.reach);
    const sense = RULES.BOOK_V78.combatSense === 'pool' ? 0 : this.adeptSpecial('combatSense') * RULES.ADEPT.combatSense.dicePerLevel;
    await this.#runTest((fullDice ? tx('SR2E.Card.Actor.with2WithFullDefense2', { wpnName: wpn.name, sdSuffix: sd.suffix, note: bonusNote(focus, 0).note, part2: sense ? tx('SR2E.Card.Actor.combatSense', { sense }) : '', shNote, fullDice }) : tx('SR2E.Card.Actor.with2WithMeleeDefense', { wpnName: wpn.name, sdSuffix: sd.suffix, note: bonusNote(focus, 0).note, part2: sense ? tx('SR2E.Card.Actor.combatSense', { sense }) : '', shNote })), sd.dice + focus.dice + fullDice + sense + sh.dice,
      { targetNumber: RULES.MELEE_BASE_TN, modifiers: [...reach, ...situation, ...sd.modifiers, ...shMods, ...this.#meleeDefenseSight(attack)], poolDice: offensivePoolDice(pool, (sd0 as any).base ?? sd0.dice) },
      { kind: 'defend', defendAgainst: attack, counter });
  }

  /**
   * v0.71.0 (R10): a counterattack's extras from the defending weapon, as planAttack gives an attack: its own armor
   * kind, a stun weapon's Stun against part of the impact armor (and a charge spent per blow), subduing,
   * bone lacing on unarmed blows, silver or wood (material) and a toxin on the blade.
   */
  async #counterExtras(wpn: any, counter: CounterWeapon, o: { subdue: boolean; killingHands: boolean; style: boolean }): Promise<void> {
    const ws = wpn.system ?? {};
    const extras: Partial<AttackState> = {};
    const own = weaponArmorKind({ armorKind: ws.armorKind, melee: true, thrown: false, skill: ws.skill, name: wpn.name });
    if (own !== armorKindFor(true)) extras.armorKind = own;
    if (o.subdue) counter.damageType = RULES.COMBAT.subdue.damageType as DamageType;
    const charge = ws.stunWeapon ? stunCharge({ stunWeapon: true, ammo: Number(ws.ammo ?? 0), ammoMax: Number(ws.ammoMax ?? 0) }) : null;
    if (ws.stunWeapon && charge?.stun) {
      counter.damageType = 'stun';
      extras.armorKind = RULES.STUN_WEAPONS.armorKind;
      extras.armorMultiplier = RULES.STUN_WEAPONS.armorMultiplier;
      // A stun baton spends a charge per blow, a parry included.
      if (charge.spend > 0 && typeof wpn.update === 'function') await wpn.update({ 'system.ammo': Math.max(0, Number(ws.ammo ?? 0) - charge.spend) });
    }
    if (wpn.id === 'unarmed' && !o.style) {
      const lace = Math.max(0, Number(this.sys.derived?.cyber?.lacing?.unarmedPower ?? 0));
      if (lace) counter.power += lace;
    }
    if (ws.material) extras.material = String(ws.material);
    if (ws.toxinId) {
      const ti: any = [...this.items].find((i: any) => i.id === ws.toxinId);
      const t = SR2Actor.toxinOf(ti);
      if (t) extras.toxinHit = { ...t, from: this.name as string, needsWound: Boolean(ws.toxinNeedsWound) };
    }
    if (Object.keys(extras).length) counter.extras = extras;
  }

  /** v0.55.0: the melee table on the defender's side: prone (theirs and the attacker's) and the defender's friends near the attacker. */
  #meleeDefenderSituation(attack: AttackState, ownReach: number): TargetNumberModifier[] {
    const attacker: any = attack?.attackerUuid ? fromUuidSync(attack.attackerUuid) : null;
    if (!attacker) return [];
    const out = proneModifiers({ melee: true, targetProne: isProne(attacker), attackerProne: isProne(this) })
      .map((m) => (modifierIs(m, 'targetProne', 'Target prone') ? { ...m, id: 'attackerProne', label: tx('SR2E.Card.Mod.attackerProne'), value: m.value } : modifierIs(m, 'attackerProne', 'Attacker prone') ? { ...m, id: 'defenderProne', label: tx('SR2E.Card.Mod.defenderProne'), value: m.value } : m));
    try {
      const me: any = SR2Actor.tokenFor(this), them: any = SR2Actor.tokenFor(attacker);
      if (me && them) out.push(...friendsModifiers(friendsInMelee(me, them, meleeReachMetres(ownReach + this.reachBonus))));
    } catch { /* no canvas */ }
    // v0.61.0: superior position (the attacker said who holds it).
    if (attack.superior) out.push(...superiorPositionModifiers(attack.superior, 'defender'));
    return out;
  }

  // ---------------------------------------------------------------- v0.55.0: patches, burning, holds, suppression

  /**
   * Apply a slap patch (gear with `patch.kind`, RULES.PATCHES) to this actor or a target: stim (Stun
   * off for a while, back with interest), tranq (Body vs its rating, Stun boxes), trauma (stabilises the
   * dying), antidote (dice against the next toxin). Uses one from the stack and a Simple Action.
   */
  async applyPatch(itemId: string, targetUuid = ''): Promise<boolean> {
    return this.#oneAtATime('applyPatch', false, () => this.#applyPatch(itemId, targetUuid));
  }

  async #applyPatch(itemId: string, targetUuid = ''): Promise<boolean> {
    const it: any = this.items.get(itemId);
    const p = it?.system?.patch;
    if (!it || !p?.kind) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.thatIsNotASlapPatch')); return false; }
    if ((it.system.quantity ?? 1) <= 0) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.noneLeft', { name: escHtml(it.name) })); return false; }
    if (!isCarried(it)) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.notCarried', { name: escHtml(it.name) })); return false; }
    const target: any = targetUuid ? fromUuidSync(targetUuid) : this;
    if (!target?.system?.monitor) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.pickSomeoneToPutThePatch')); return false; }
    const rating = Math.max(0, Math.floor(Number(p.rating) || 0));
    if (p.kind === 'trauma' && target.system.derived?.status !== 'dying') { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.isnTDyingATraumaPatch', { targetName: escHtml(target.name) })); return false; }
    if (!(await this.useAction('patch', tx('SR2E.Card.Actor.applying', { name: it.name })))) return false;
    // v0.70.0: on someone the player doesn't own (a guard, a teammate), the patch is used now and the GM applies
    // its effect from the card (before, it was refused: a tranq patch could never be used on an NPC).
    if (!canWriteNow(target)) {
      await it.update({ 'system.quantity': Math.max(0, Number(it.system.quantity ?? 1) - 1) });
      const gms = [...((game as any).users ?? [])].filter((u: any) => u.isGM).map((u: any) => u.id);
      await ChatMessage.create({
        speaker: ChatMessage.getSpeaker({ actor: this }),
        content: `<p><strong>${escText(it.name)}</strong> ${tx('SR2E.Card.Actor.slappedOn', { kind: escText(p.kind), rating })} <strong>${escText(target.name)}</strong>.${p.kind === 'tranq' ? ` <span class="hint">${tx('SR2E.Card.Actor.anUnwillingTargetMayNeedAn')}</span>` : ''}</p>
          <p><button type="button" data-sr2e-action="applyPatch">${tx('SR2E.Card.Actor.applyGm')}</button></p>`,
        whisper: [...new Set([...gms, (game as any).user?.id])],
        flags: { [SYSTEM_ID]: { patchApply: { targetUuid: target.uuid, kind: p.kind, rating, name: String(it.name), byName: String(this.name), sourceUuid: this.uuid } } },
      });
      return true;
    }
    const text = await SR2Actor.patchEffect(target, { kind: p.kind, rating, name: String(it.name) });
    await it.update({ 'system.quantity': Math.max(0, Number(it.system.quantity ?? 1) - 1) });
    await ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor: this }), content: `<p><strong>${escText(it.name)}</strong> ${tx('SR2E.Card.Actor.on3', { kind: escText(p.kind), rating, targetName: escText(target.name), text })}</p>` });
    return true;
  }

  /** v0.80.0 (RULES.URR_V80, health-social): a dying patient's own stabilisation test; a success stops the bleeding. */
  static async urrSelfStabilise(patient: any, dice: number, tn: number, modifiers: TargetNumberModifier[], label: string): Promise<boolean> {
    const rolls: any[] = [];
    const r = await successTest({ dice, targetNumber: tn, modifiers, roll: foundryRoller(rolls) });
    const ok = r.successes > 0;
    if (ok && patient.system.derived?.status === 'dying') await patient.update({ 'system.care.stabilised': true });
    await ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor: patient }), rolls,
      content: `<p><strong>${escText(patient.name)}</strong>${tCount(r.successes, 'SR2E.Card.Actor.diceVsSuccesses', { label: escText(label), dice, targetNumber: r.targetNumber, part: ok ? tx('SR2E.Card.Actor.stabilised') : tx('SR2E.Card.Actor.stillBleeding') })}</p>` });
    return ok;
  }

  /**
   * v0.80.0 (RULES.URR_V80.hsMagicLossUntreated): the Magic loss card for a magician treated without the +2.
   * v0.81.0 (R2-SEC 5): posted by the healer's client, so the card speaks as the healer and names them
   * (`magicLossBy`): the patient's owner sees who asks (a confirm, applications/chat.ts), and the GM may roll it.
   */
  static async urrMagicLossCard(patient: any, healer: any = null): Promise<void> {
    if (!RULES.MAGIC_LOSS.enabled || !(Number(patient?.system?.magic ?? 0) > 0) || patient?.type === 'spirit') return;
    const by = healer && healer !== patient && healer.uuid !== patient.uuid ? healer : null;
    await ChatMessage.create({
      speaker: ChatMessage.getSpeaker({ actor: by ?? patient }),
      content: `<p><strong>${escText(patient.name)}</strong> ${(by ? tx('SR2E.Card.Actor.wasTreatedWithoutTheMagicianModifierWithBy6', { byName: escText(by.name) }) : tx('SR2E.Card.Actor.wasTreatedWithoutTheMagicianModifierPlain'))}</p>
        <p><button type="button" data-sr2e-action="magicLoss">${tx('SR2E.Card.Actor.magicLossTestD6', { magicLossDice: RULES.MAGIC_LOSS.dice })}</button></p>`,
      flags: { [SYSTEM_ID]: { magicLossFor: patient.uuid, ...(by ? { magicLossBy: String(by.uuid) } : {}) } },
    });
  }

  /**
   * v0.80.0 (RULES.URR_V80, health-social): after a first aid card applies. Notes the healer's Biotech for a later
   * retry (hsFirstAidRetry), adds the treatment time (hsFirstAidTime), and when first aid on the dying failed rolls
   * the patient's self-stabilisation test (hsSelfStabilise; once per card, so a re-roll doesn't roll it again).
   */
  static async urrAfterFirstAid(healer: any, patient: any, snap: any, wasDying: boolean): Promise<string> {
    const h = snap.heal;
    let out = '';
    if (RULES.URR_V80.hsFirstAidRetry) {
      const by = { ...((patient.getFlag?.(SYSTEM_ID, 'firstAidBy') as Record<string, number> | undefined) ?? {}) };
      const mine = Number(healer.findSkill?.(RULES.HEALING.firstAid.skill)?.system?.rating ?? 0);
      if (!(Number(by[h.track]) >= mine)) { by[h.track] = mine; await patient.setFlag?.(SYSTEM_ID, 'firstAidBy', by); }
    }
    const min = firstAidMinutes(h.before, Number(snap.successes) || 0);
    if (min) out += ` <em>${tCount(min, 'SR2E.Card.Actor.treatmentTakesMinutes')}</em>`;
    const st = h.track === 'physical' && wasDying && !(Number(snap.successes) > 0) ? selfStabiliseTest(Number(patient.system.attributes?.body?.natural ?? patient.system.attributes?.body?.total ?? 0)) : null;
    if (st && patient.system.derived?.status === 'dying' && !patient.system.care?.stabilised && !(snap.testId && patient.getFlag?.(SYSTEM_ID, 'selfStabilised') === snap.testId)) {
      if (snap.testId) await patient.setFlag?.(SYSTEM_ID, 'selfStabilised', snap.testId);
      const ok = await SR2Actor.urrSelfStabilise(patient, st.dice, st.tn, [], tx('SR2E.Card.Actor.selfStabilisationNaturalBodyNoModifiers'));
      out += ok ? ` <strong>${tx('SR2E.Card.Actor.stabilisesOnTheirOwn', { patientName: escText(patient.name) })}</strong>` : tx('SR2E.Card.Actor.doesnTStabiliseAndKeepsBleeding', { patientName: escText(patient.name) });
    }
    return out;
  }

  /** v0.70.0: what a slap patch does to its target (the owner's client, or the GM's from an Apply (GM) card). */
  static async patchEffect(target: any, p: { kind: string; rating: number; name: string }): Promise<string> {
    const rating = Math.max(0, Math.floor(Number(p.rating) || 0));
    const now = sysNow();
    let text = '';
    if (p.kind === 'trauma' && target.system.derived?.status !== 'dying') return tx('SR2E.Card.Actor.isnTDyingNothingHappens', { targetName: escText(target.name) });
    if (p.kind === 'stim') {
      // v0.78.0 (RULES.BOOK_V78.patches.stim 'book'): it wears off in 2D6 minutes.
      const stun = Number(target.system.monitor.stun ?? 0);
      let minutes: number | undefined;
      if (RULES.BOOK_V78.patches.stim === 'book' && Math.min(stun, rating) > 0) {
        const faces = await foundryRoller([])(Math.max(1, RULES.BOOK_V78.patches.stimMinutesDice));
        minutes = faces.reduce((a, b) => a + b, 0);
      }
      const e = stimEffect(stun, rating, minutes);
      const debt = [...((target.getFlag?.(SYSTEM_ID, 'stimDebt') as any[] | undefined) ?? []), ...(e.off ? [{ boxes: e.back, at: now + e.backSeconds, name: p.name }] : [])];
      await target.update({ 'system.monitor.stun': Math.max(0, Number(target.system.monitor.stun) - e.off), [`flags.${SYSTEM_ID}.stimDebt`]: debt });
      text = e.off ? tCount(e.off, 'SR2E.Card.Actor.stunBoxesOffForThenCome', { part: minutes !== undefined ? tx('SR2E.Card.Actor.minutes', { minutes }) : `${e.backHours} h`, back: e.back }) : tx('SR2E.Card.Actor.noStunToTakeOff');
    } else if (p.kind === 'tranq') {
      const rolls: any[] = [];
      const body = Number(target.system.attributes?.body?.total ?? 0);
      let boxes: number;
      if (RULES.BOOK_V78.patches.tranq === 'opposed') {
        // v0.78.0 (the book): the patch rolls its rating vs the Body, the patient Body vs the rating; net patch successes.
        const patch = await successTest({ dice: rating, targetNumber: Math.max(RULES.MIN_TARGET_NUMBER, body), roll: foundryRoller(rolls) });
        const res = await successTest({ dice: body, targetNumber: Math.max(RULES.MIN_TARGET_NUMBER, rating), roll: foundryRoller(rolls) });
        boxes = tranqOpposed(patch.successes, res.successes);
        text = tx('SR2E.Card.Actor.patchRatingVsBodyAgainstBody', { successes: tCount(patch.successes, 'SR2E.Count.success'), rating, body, resSuccesses: res.successes, stunBoxes: tCount(boxes, 'SR2E.Count.stunBoxes') });
      } else {
        const res = await successTest({ dice: body, targetNumber: Math.max(RULES.MIN_TARGET_NUMBER, rating), roll: foundryRoller(rolls) });
        boxes = tranqBoxes(rating, res.successes);
        text = tx('SR2E.Card.Actor.bodyVs', { successes: tCount(res.successes, 'SR2E.Count.success'), rating, stunBoxes: tCount(boxes, 'SR2E.Count.stunBoxes') });
      }
      // v0.70.0: Stun past the track spills into Physical like any Stun (before, capped at 10).
      const m = addStun(target.system.monitor, boxes);
      await target.update({ 'system.monitor.stun': m.stun, 'system.monitor.physical': m.physical });
    } else if (p.kind === 'trauma') {
      // v0.80.0 (RULES.URR_V80.hsTraumaPatch 'bodyTest'): natural Body vs 4 + dermal armor / blood filter rating.
      const tp = traumaPatchTest(Number(target.system.attributes?.body?.natural ?? target.system.attributes?.body?.total ?? 0), target.items ?? []);
      if (tp) text = (await SR2Actor.urrSelfStabilise(target, tp.dice, tp.tn, tp.modifiers, tx('SR2E.Card.Actor.traumaPatchSelfStabilisationNaturalBody'))) ? tx('SR2E.Card.Actor.stabilisedNoLongerLosingBoxesWhile') : tx('SR2E.Card.Actor.theBodyTestFailsStillBleeding');
      else await target.update({ 'system.care.stabilised': true });
      if (!tp) text = tx('SR2E.Card.Actor.stabilisedNoLongerLosingBoxesWhile');
    } else if (p.kind === 'antidote') {
      const e = antidoteEffect(rating);
      await target.setFlag(SYSTEM_ID, 'antidote', { dice: e.dice, until: now + e.hours * 3600, name: p.name });
      text = tx('SR2E.Card.Actor.diceAgainstTheNextToxinWithin', { dice: e.dice, hours: e.hours });
    }
    return text;
  }

  /** v0.55.0: catch fire: burns each Combat Turn until put out (RULES.COMBAT.burning). */
  async setOnFire(on = true): Promise<void> {
    if (!RULES.COMBAT.burning.enabled) return;
    // v0.56.0: a critter immune to fire doesn't burn.
    if (on && this.immunities().fire) { ui.notifications?.info?.(tx('SR2E.Notify.Actor.isImmuneToFire', { name: escHtml(this.name) })); return; }
    const c: any = game.combat;
    if (on) await this.setFlag(SYSTEM_ID, 'onFire', { combatId: c?.id ?? '', round: Number(c?.round ?? 0) });
    else if (this.getFlag?.(SYSTEM_ID, 'onFire')) await clearFlag(this, 'onFire');
  }

  /** v0.55.0: put out the flames (a Complex Action by default: rolling on the ground, a blanket). */
  async putOutFire(): Promise<boolean> {
    if (!this.getFlag?.(SYSTEM_ID, 'onFire')) { ui.notifications?.info?.(tx('SR2E.Notify.Actor.isnTBurning', { name: escHtml(this.name) })); return false; }
    if (!(await this.useAction('putOutFire', tx('SR2E.Card.Actor.puttingOutTheFlames')))) return false;
    await this.setOnFire(false);
    await ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor: this }), content: `<p><strong>${escText(this.name)}</strong> ${tx('SR2E.Card.Actor.putsOutTheFlames')}</p>` });
    return true;
  }

  /** v0.55.0 (GM tick): someone on fire burns again at each new Combat Turn. */
  /** v0.81.1 (D2-7): the combat a round tick belongs to (by id), else the viewed one (the world-time hook). */
  static #tickingCombat(combatId: string | null | undefined): any {
    const g: any = game as any;
    if (combatId) return g.combats?.get?.(combatId) ?? (g.combat?.id === combatId ? g.combat : null);
    return g.combat ?? null;
  }

  static async burningTick(a: any, round: number | null, combatId: string | null = null): Promise<void> {
    const f = a?.getFlag?.(SYSTEM_ID, 'onFire') as { combatId: string; round: number } | undefined;
    const c: any = SR2Actor.#tickingCombat(combatId);
    if (!f || !RULES.COMBAT.burning.enabled || round === null || !c?.started) return;
    // v0.81.1 (D2-7, RA2-3): a fire caught in another fight that is still running burns on that fight's rounds; and
    // a round of a named combat burns only its combatants.
    // Round 2 (V-DOC 9, FIX2-BRIEF H6): someone on fire who isn't in the tracker burns on the rounds of the combat on
    // their scene; anyone else waits for their own fight.
    if (combatId && ![...(c.combatants ?? [])].some((x: any) => x?.actor === a || (x?.actor?.uuid && x.actor.uuid === a.uuid))) {
      // Round 3 (V2 #11, FIX3-BRIEF 10): a combat linked to no scene keeps the pre-v0.81.1 rule (they burn on its rounds).
      const sceneId = String(c.scene?.id ?? c.sceneId ?? (typeof c.scene === 'string' ? c.scene : '') ?? '');
      if (sceneId && !SR2Actor.#tokensAnywhere(a).some((t: any) => String(t.parent?.id ?? t.scene?.id ?? '') === sceneId)) return;
    }
    if (f.combatId && f.combatId !== c.id && SR2Actor.#tickingCombat(f.combatId)?.started) return;
    // Caught fire outside this combat (or in an earlier one): it starts burning from this Combat Turn.
    if (f.combatId !== c.id) { await a.setFlag(SYSTEM_ID, 'onFire', { combatId: c.id, round }); return; }
    if (round <= f.round) return;
    await a.setFlag(SYSTEM_ID, 'onFire', { ...f, round });
    await a.resistHazard?.('fire', RULES.COMBAT.burning.amount);
    await ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor: a }), content: `<p><strong>${escText(a.name)}</strong> ${tx('SR2E.Card.Actor.isStillBurning')} <button type="button" data-sr2e-action="putOutFire">${tx('SR2E.Card.Actor.putOutTheFlames')}</button></p>`, flags: { [SYSTEM_ID]: { putOutFire: { actorUuid: a.uuid } } } });
  }

  /**
   * v0.55.0: hold someone (after a subduing blow, or instead of one): this actor's Strength vs their
   * Body against their Body vs this Strength (RULES.COMBAT.hold); more successes pins them (restrained).
   */
  async holdTarget(targetUuid: string): Promise<'held' | 'free' | null> {
    const t: any = targetUuid ? fromUuidSync(targetUuid) : null;
    if (!t?.system?.attributes) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.targetSomeoneToHold')); return null; }
    if (!(await this.useAction('hold', tx('SR2E.Card.Actor.holding', { name: t.name })))) return null;
    const h = RULES.COMBAT.hold;
    const mine = Number(this.sys.attributes?.[h.attackerAttr]?.total ?? 0), theirs = Number(t.system.attributes?.[h.defenderAttr]?.total ?? 0);
    const rolls: any[] = [];
    const a = await successTest({ dice: mine, targetNumber: Math.max(RULES.MIN_TARGET_NUMBER, theirs), roll: foundryRoller(rolls) });
    const d = await successTest({ dice: theirs, targetNumber: Math.max(RULES.MIN_TARGET_NUMBER, mine), roll: foundryRoller(rolls) });
    const out = holdOutcome(a.successes, d.successes);
    await ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor: this }), rolls,
      content: `<p><strong>${escText(this.name)}</strong> ${tx('SR2E.Card.Actor.triesToHoldVs', { name: escText(t.name), attackerAttr: escText(cap(h.attackerAttr)), successes: a.successes, defenderAttr: escText(cap(h.defenderAttr)), successes2: d.successes })} <strong>${out === 'held' ? tx('SR2E.Card.Actor.isPinned', { name: escText(t.name) }) : tx('SR2E.Card.Actor.slipsFree', { name: escText(t.name) })}</strong></p>${out === 'held' && !canWriteNow(t) ? `<p><button type="button" data-sr2e-action="applyHold">${tx('SR2E.Card.Actor.applyGm')}</button></p>` : ''}`,
      flags: { [SYSTEM_ID]: { hold: { targetUuid: t.uuid, holderUuid: this.uuid } } } });
    if (out === 'held' && canWriteNow(t)) await SR2Actor.setHeld(t, this.uuid as string, true);
    return out;
  }

  /** v0.55.0: put on or take off the restrained status and who holds them. */
  static async setHeld(t: any, holderUuid: string, on: boolean): Promise<void> {
    const status = RULES.COMBAT.hold.status;
    if (on) {
      // Only take the status off later if the hold put it on (they may have been prone already).
      const had = Boolean(t.statuses?.has?.(status));
      if (!had) try { await t.toggleStatusEffect?.(status, { active: true }); } catch { /* no token or status */ }
      await t.setFlag(SYSTEM_ID, 'heldBy', holderUuid);
      await t.setFlag(SYSTEM_ID, 'heldStatus', !had);
    } else {
      if (t.getFlag?.(SYSTEM_ID, 'heldStatus')) try { await t.toggleStatusEffect?.(status, { active: false }); } catch { /* no token or status */ }
      if (t.getFlag?.(SYSTEM_ID, 'heldBy')) await clearFlag(t, 'heldBy');
      await clearFlag(t, 'heldStatus');
    }
  }

  /**
   * v0.71.0 (R13): why this actor can't move its token now ('' = it can): held in a grapple, or bound by a
   * binding power (MAGIC_V61.holdPowers.binding.blocksMovement).
   */
  movementHold(): string {
    if (!RULES.FIXES_V71.holds) return '';
    const by = this.getFlag?.(SYSTEM_ID, 'heldBy') as string | undefined;
    if (by) return tx('SR2E.Text.Actor.heldBy', { name: fromUuidSync(by)?.name ?? tx('SR2E.Text.Actor.someone2') });
    if (RULES.MAGIC_V61.holdPowers.binding.blocksMovement) {
      const b = ((this.getFlag?.(SYSTEM_ID, 'powerEffects') as FxEntry[] | undefined) ?? []).find((e) => e.special === 'binding');
      if (b) return tx('SR2E.Text.Actor.boundBy', { name: b.name, fromName: b.fromName });
    }
    return '';
  }

  /**
   * v0.71.0 (R13): let go of holds: those of a holder who went down (`holderUuid`), or every hold among `uuids`
   * (a combat that ended). Returns how many were let go.
   */
  static async releaseHolds(o: { holderUuid?: string; uuids?: string[] }): Promise<number> {
    if (!RULES.FIXES_V71.holds) return 0;
    const among = o.uuids ? new Set(o.uuids) : null;
    let n = 0;
    for (const a of allActors() as any[]) {
      const by = a.getFlag?.(SYSTEM_ID, 'heldBy') as string | undefined;
      if (!by || !canWriteNow(a)) continue;
      if (o.holderUuid ? by !== o.holderUuid : !(among && (among.has(a.uuid) || among.has(by)))) continue;
      // Live run: a holder going down fires several updates at once; only the first lets go (one card).
      if (SR2Actor.#releasing.has(a.uuid)) continue;
      SR2Actor.#releasing.add(a.uuid);
      try {
        await SR2Actor.setHeld(a, '', false);
        n++;
        await ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor: a }), content: `<p><strong>${escText(a.name)}</strong> ${tx('SR2E.Card.Actor.isFree', { part: o.holderUuid ? tx('SR2E.Card.Actor.canNoLongerHoldOn', { name: escText(fromUuidSync(by)?.name ?? tx('SR2E.Card.Actor.theHolder')) }) : tx('SR2E.Card.Actor.theFightIsOver') })}</p>` });
      } finally { SR2Actor.#releasing.delete(a.uuid); }
    }
    return n;
  }

  /** Held actors being let go on this client right now. */
  static #releasing = new Set<string>();

  /** v0.55.0: break free of a hold: this Strength vs the holder's, the holder's vs this; ties keep the hold. */
  async breakFree(): Promise<boolean> {
    const holderUuid = this.getFlag?.(SYSTEM_ID, 'heldBy') as string | undefined;
    const holder: any = holderUuid ? fromUuidSync(holderUuid) : null;
    if (!holderUuid) { ui.notifications?.info?.(tx('SR2E.Notify.Actor.isnTBeingHeld', { name: escHtml(this.name) })); return false; }
    if (!(await this.useAction('breakFree', tx('SR2E.Card.Actor.breakingFree')))) return false;
    const mine = Number(this.sys.attributes?.strength?.total ?? 0), theirs = Number(holder?.system?.attributes?.strength?.total ?? 0);
    const rolls: any[] = [];
    const me = await successTest({ dice: mine, targetNumber: Math.max(RULES.MIN_TARGET_NUMBER, theirs), roll: foundryRoller(rolls) });
    const them = holder ? await successTest({ dice: theirs, targetNumber: Math.max(RULES.MIN_TARGET_NUMBER, mine), roll: foundryRoller(rolls) }) : { successes: 0 };
    // Ties keep the hold: free only with more successes than the holder.
    const free = !holder || me.successes > them.successes;
    if (free) await SR2Actor.setHeld(this, '', false);
    await ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor: this }), rolls, content: `<p><strong>${escText(this.name)}</strong> ${tx('SR2E.Card.Actor.strugglesAgainstStrengthVs', { holderName: escText(holder?.name ?? tx('SR2E.Card.Actor.theHold')), meSuccesses: me.successes, themSuccesses: them.successes })} <strong>${free ? tx('SR2E.Card.Actor.free') : tx('SR2E.Card.Actor.stillHeld')}</strong></p>` });
    return free;
  }

  /**
   * v0.55.0 (Fields of Fire, optional): suppressive fire with a full-auto weapon at the targeted people
   * (RULES.COMBAT.suppressive): the weapon's base damage, a Defend button each, and a Take cover button
   * that goes prone (then the fire passes over them).
   */
  async suppressiveFire(weaponId: string, targetUuids: string[], opts: AttackOptions = {}): Promise<SuccessTestResult | null> {
    const sf = RULES.COMBAT.suppressive;
    const weapon: any = this.weaponById(weaponId);
    if (!sf.enabled) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.suppressiveFireIsSwitchedOffIn')); return null; }
    if (!weapon || weapon.system?.melee || !parseFiringModes(weapon.system?.modes ?? '').includes('FA')) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.suppressiveFireNeedsAFullAuto')); return null; }
    if (!targetUuids.length) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.targetThePeopleInTheArea')); return null; }
    if (weapon.system.jammed) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.isJammed', { weaponName: escHtml(weapon.name) })); return null; }
    if (weapon.system.damaged) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.isBrokenRepairItFirst', { weaponName: escHtml(weapon.name) })); return null; }
    if (weapon.system.ammoMax > 0 && weapon.system.ammo < sf.rounds) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.roundsLeftNeededForSuppressiveFire', { weaponName: escHtml(weapon.name), weaponAmmo: escHtml(weapon.system.ammo), sfRounds: sf.rounds })); return null; }
    if (!(await this.useAction('suppress', tx('SR2E.Card.Actor.suppressiveFireWith', { weaponName: weapon.name })))) return null;
    const result = await this.attackWith(weapon, { ...opts, mode: 'FA', rounds: sf.rounds, hits: targetUuids.map((u) => ({ targetUuid: u })), suppressive: true });
    if (!result) return null;
    const names = targetUuids.map((u) => fromUuidSync(u)).filter(Boolean) as any[];
    await ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor: this }),
      content: `<p><strong>${tx('SR2E.Card.Actor.suppressiveFire')}</strong> ${(sf.coverIsSafe ? tx('SR2E.Card.Actor.fromAnyoneInTheAreaMayWithAndTheFirePassesOverThem', { name: escText(this.name) }) : tx('SR2E.Card.Actor.fromAnyoneInTheAreaMayPlain', { name: escText(this.name) }))}</p><ul class="sr2e-blast">${names.map((a, i) => `<li>${escText(a.name)} <button type="button" data-sr2e-action="takeCover" data-index="${i}">${tx('SR2E.Card.Actor.takeCover')}</button></li>`).join('')}</ul>`,
      flags: { [SYSTEM_ID]: { takeCover: names.map((a) => a.uuid), takeCoverFrom: this.uuid } } });
    return result;
  }

  /** Knockdown test: Body vs the damage's resistance TN; no successes = knocked down (prone). */
  async rollKnockdown(tn: number, level80: DamageLevel | null = null): Promise<SuccessTestResult> {
    // Like damage resistance, the knockdown test takes no wound modifiers.
    const rolls: any[] = [];
    const result = await successTest({ dice: this.sys.attributes.body.total as number, targetNumber: tn, roll: foundryRoller(rolls) });
    await this.#post(this.#snapshot(tx('SR2E.Card.Actor.knockdownTest'), result, { kind: 'plain' }), result, rolls);
    // v0.80.0 (URR_V80.cbtKnockdown 'urr', URR): 2 / 3 / 4 successes needed for L / M / S (Deadly: down); short of it, a stagger.
    const kd80 = U80C.cbtKnockdownResult(result.successes, level80);
    if (!kd80.down && kd80.staggerMetres > 0) await ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor: this }), content: `<p><strong>${tx('SR2E.Card.Actor.staggersBackM', { name: escText(this.name), kd80StaggerMetres: kd80.staggerMetres })}</strong></p>` });
    if (kd80.down) {
      try { await (this as any).toggleStatusEffect?.('prone', { active: true }); } catch { /* no token or status */ }
      await ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor: this }), content: `<p><strong>${tx('SR2E.Card.Actor.isKnockedDown', { name: escText(this.name) })}</strong></p>` });
    }
    return result;
  }

  /**
   * Which pool this actor spends against an attack (or for its own astral attack): astral combat
   * uses RULES.ASTRAL.attackPool for magicians and the Combat Pool for spirits.
   */
  poolFor(attack?: { astral?: boolean; matrix?: boolean }): PoolKind {
    if (attack?.matrix) return 'hacking';
    if (!attack?.astral || this.type === 'spirit') return 'combat';
    // v0.72.0 (O14): adepts use the Combat Pool on the astral plane (MAGIC_V72.adeptAstral.pool); none = their 0 Spell Pool.
    return astralPoolKind({ type: this.type, tradition: String(this.tradition ?? ''), base: RULES.ASTRAL.attackPool }) ?? 'spell';
  }

  /** Resist a damage card: armor is looked up from this actor's worn armor by attack type (none astrally). */
  async resistFromState(damage: DamageState, poolDice = 0): Promise<void> {
    if (this.type === 'vehicle') {
      await this.resistVehicleDamage(damage, poolDice);
      return;
    }
    if (damage.matrix) {
      await this.resistMatrixDamage(damage, poolDice);
      return;
    }
    if (damage.astral) {
      await this.resistDamage({
        power: damage.power, level: damage.level, type: damage.damageType, armor: 0, poolDice,
        astral: true,
      });
      return;
    }
    // v0.61.0: immunity to fire stops fire damage (flamethrowers, fire elemental spells).
    if (damage.fire) {
      const im = damageImmunity(this.immunities() as Record<string, boolean>, { fire: true });
      if (im.immune) {
        await ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor: this }), content: `<p><strong>${tx('SR2E.Card.Actor.isImmuneToFire2', { name: escText(this.name) })}</strong> ${tx('SR2E.Card.Actor.noDamage2', { part: im.reason ? ` (${escText(im.reason)})` : '' })}</p>` });
        return;
      }
    }
    // Critter vulnerability to the weapon's material (v0.39.0): staged up, past immunity, not regenerated.
    const vuln = damage.material ? vulnerabilityTo(this.critterTraits(), damage.material) : null;
    if (vuln) damage = { ...damage, level: vulnerableLevel(damage.level), ...(RULES.CRITTERS.vulnerability.ignoresImmunity ? { ignoreImmunity: true } : {}) };
    // A weapon of something the critter is allergic to: contact damage on top, unresisted.
    const allergic = damage.material ? this.critterTraits().find((t) => t.special === 'allergy' && tags(t.substance ?? '').some((x) => tags(damage.material ?? '').includes(x))) : null;
    const contact = allergic ? allergyContact(allergic.severity ?? 'mild') : null;
    // v0.78.0 (RULES.BOOK_V78.allergy 'book', Core Rules): a Severe or Extreme allergy adds +2 to the weapon's Power.
    const allergyPower = damage.material ? allergyWeaponPower(this.critterTraits(), damage.material) : 0;
    if (allergyPower) {
      damage = { ...damage, power: Number(damage.power ?? 0) + allergyPower };
      await ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor: this }), content: `<p><strong>${tx('SR2E.Card.Actor.allergy')}</strong> ${tx('SR2E.Card.Actor.isBadlyAllergicToTheWeapon', { name: escText(this.name), damageMaterial: escText(damage.material ?? ''), allergyPower, damagePower: damage.power })}</p>` });
    }
    if (vuln || contact) {
      await ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor: this }),
        content: `<p>${vuln ? `<strong>${tx('SR2E.Card.Actor.isVulnerableTo', { name: escText(this.name), damageMaterial: escText(damage.material) })}</strong> ${(RULES.CRITTERS.vulnerability.ignoresImmunity ? tx('SR2E.Card.Actor.theDamageStagesUpToAndWithAndIgnoresImmunity', { damageLevel: damage.level }) : tx('SR2E.Card.Actor.theDamageStagesUpToAndPlain', { damageLevel: damage.level }))}` : ''}${contact ? ` <strong>${tx('SR2E.Card.Actor.allergy')}</strong> ${tx('SR2E.Card.Actor.burnsUnresisted', { damageMaterial: escText(damage.material), name: escText(this.name), contact })}` : ''}</p>` });
      if (contact) await this.applyUnresisted({ targetUuid: this.uuid as string, melee: false, damageType: 'physical', power: 0, level: contact });
    }
    const kind = damage.armorKind ?? armorKindFor(damage.melee);
    const opts = { ignoreImmunity: Boolean(damage.ignoreImmunity), noWorn: Boolean(damage.ignoreArmor), calledLocation: damage.calledLocation ?? '' };
    // v0.72.0 (O3): immunity to normal weapons stops an attack whose Power doesn't exceed it (RULES.COMBAT_V72.immunity).
    if (!damage.elemental && !damage.ignoreImmunity && !damage.awakenedAttacker) {
      const withImm = this.armorRating(kind, opts);
      const without = this.armorRating(kind, { ...opts, ignoreImmunity: true });
      const st = immunityStops({ power: damage.power, immunity: withImm - without, otherArmor: without, armorMultiplier: damage.armorMultiplier ?? 1 });
      if (st.stops) {
        await ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor: this }), content: `<p><strong>${escText(this.name)}</strong> ${tx('SR2E.Card.Actor.shrugsItOffPowerDoesnT', { damagePower: damage.power, stAgainst: st.against })}</p>` });
        return;
      }
    }
    // v0.79.0 (RULES.DOCS_V79.rangedFlechette 'armor', SRII p. 93): +1 level only against no armor; against armor the higher of
    // ballistic and impact, doubled, instead of the attack's own kind.
    const fl79 = damage.flechette && !damage.elemental ? flechetteSoak({ ballistic: this.armorRating('ballistic', opts), impact: this.armorRating('impact', opts), level: damage.level }) : null;
    if (fl79) damage = { ...damage, level: fl79.level };
    const armor = damage.elemental
      ? elementalArmor({ ballistic: this.armorRating('ballistic', opts), impact: this.armorRating('impact', opts) })
      : fl79 ? fl79.armor + Math.max(0, damage.extraArmor ?? 0)
      : armorAfterAmmo(this.armorRating(kind, opts), damage.armorMultiplier ?? 1) + Math.max(0, damage.extraArmor ?? 0);
    // v0.92.3 (RULES.VEHICLES_V923.occupant 'book', Rigger 2 p. 53): shot inside a vehicle: no Combat Pool, and a rigger
    // jacked in (their mind is in the machine) +3 TN.
    const occ = Boolean(damage.occupantShot) && veh923('occupant') === 'book';
    const occTn = occ && this.sys.rigging?.jumpedIn ? Math.max(0, Number(RULES.VEHICLES_V923.occupantRiggerTn) || 0) : 0;
    if (occ) poolDice = 0;
    await this.resistDamage({ power: damage.power, level: damage.level, type: damage.damageType, armor, poolDice, ...(occTn ? { tnPlus: occTn } : {}), knockdown: !damage.black, knockdownMelee: damage.melee, ...(damage.cleanMiss80 ? { cleanMiss80: damage.cleanMiss80 } : {}), ...(damage.ignoreArmor || damage.elemental ? {} : { armorKind: kind }), ...(vuln ? { noRegen: true } : {}),
      ...(damage.black ? {} : { cyberCheck: { location: damage.calledLocation ?? '' } }), ...(damage.infection ? { infection: damage.infection } : {}), ...(damage.toxinHit ? { toxinHit: damage.toxinHit } : {}) });
  }

  /** Resist incoming damage: Body test against (Power - armor), then stage down and mark the monitor. */
  async resistDamage(opts: {
    power: number; level: DamageLevel; type?: DamageType; armor?: number; poolDice?: number;
    /** v0.55.0: a weapon's toxin carried to the soak card. */
    toxinHit?: ToxinHit;
    /** Soak astral damage with astral Body and the astral pool. */
    astral?: boolean;
    /** Damage from an attack: offer a knockdown test if it is heavy enough. */
    knockdown?: boolean;
    /** v0.80.0: a melee hit (the Revamp's knockdown TN), and the clean-miss tally (URR_V80.cbtDefense). */
    knockdownMelee?: boolean;
    cleanMiss80?: { hits: number; net: number; noClean?: boolean };
    /** Damage regeneration can't heal (a vulnerability, v0.39.0). */
    noRegen?: boolean;
    /** Worn armor of this kind stopped it (the armor-degrading house rule, v0.37.0). */
    armorKind?: 'ballistic' | 'impact';
    /** v0.43.0: damage from an attack: check for damaged cyberware. */
    cyberCheck?: { location: string };
    /** v0.48.0: a bite that passes on a disease when it does Physical damage. */
    infection?: InfectionState;
    /** v0.92.3: added to the resistance TN (a rigger jacked in, shot inside a vehicle). */
    tnPlus?: number;
  }): Promise<void> {
    const type: DamageType = opts.type ?? 'physical';
    const tn = resistanceTargetNumber(opts.power, opts.armor ?? 0) + Math.max(0, Number(opts.tnPlus ?? 0) || 0);
    const rolls: any[] = [];
    const poolType = this.poolFor({ astral: Boolean(opts.astral) });
    const poolDice = Math.max(0, Math.min(opts.poolDice ?? 0, this.sys.derived[`${poolType}PoolLeft`] as number));
    const lacing = opts.astral ? 0 : Math.max(0, Number(this.sys.derived?.cyber?.lacing?.soakDice ?? 0));
    // v0.72.0 (O11): Toughness adds dice to resist damage (not astral).
    const tough = opts.astral ? 0 : toughnessDice(this.sys.derived?.vitals ?? { toughnessDice: 0, toughnessOnStun: false, toughnessOnToxins: false }, type);
    const result = await successTest({
      // v0.58.0: bone lacing adds to Body for damage resistance only.
      dice: opts.astral ? this.sys.derived.astral.body : this.sys.attributes.body.total + lacing + tough,
      poolDice,
      targetNumber: tn,
      roll: foundryRoller(rolls),
    });
    if (poolDice > 0) await this.#spendPool(poolType, poolDice);
    const armorNote = `${opts.armor ? tx('SR2E.Card.Actor.armor', { armor: opts.armor }) : ''}${lacing ? tx('SR2E.Card.Actor.boneLacing', { lacingLabel: this.sys.derived.cyber.lacing.label, lacing }) : ''}${tough ? tx('SR2E.Card.Actor.toughness2', { tough }) : ''}`;
    await this.#post(this.#snapshot((opts.astral ? tx('SR2E.Card.Actor.resist7WithAstral', { power: opts.power, level: opts.level, type, armorNote }) : tx('SR2E.Card.Actor.resist7Plain', { power: opts.power, level: opts.level, type, armorNote })), result, {
      kind: 'soak',
      soak: {
        mode: 'stage', noun: 'damage', level: opts.level, type, body: this.sys.attributes.body.total, before: { ...this.#monitor() },
        ...(opts.knockdown && !opts.astral ? { knockdown: { power: opts.power, tn: U80C.cbtKnockdownTn({ power: opts.power, tn, melee: Boolean(opts.knockdownMelee) }) } } : {}),
        ...(opts.cleanMiss80 ? { cleanMiss80: opts.cleanMiss80 } : {}),
        ...(opts.armorKind && (opts.armor ?? 0) > 0 ? { armorKind: opts.armorKind } : {}),
        ...(opts.noRegen ? { noRegen: true } : {}),
        ...(opts.cyberCheck && !opts.astral ? { cyberCheck: { location: opts.cyberCheck.location } } : {}),
        ...(opts.infection && !opts.astral ? { infection: opts.infection } : {}),
        ...(opts.toxinHit && !opts.astral ? { toxinHit: opts.toxinHit } : {}),
      },
    }), result, rolls);
  }

  #monitor(): Monitor {
    return { physical: this.sys.monitor.physical, stun: this.sys.monitor.stun };
  }

  /** Convenience for macros: resistDamage using a damage code string such as "9M". */
  async resistDamageCode(code: string, extra: { type?: DamageType; armor?: number; poolDice?: number } = {}): Promise<void> {
    const parsed = parseDamageCode(code);
    if (!parsed) throw new Error(`Not a damage code: ${code}`);
    await this.resistDamage({ ...parsed, ...extra });
  }

  /**
   * Total armor of one kind: worn armor, adept powers and cyberware, plus a spirit's immunity to normal weapons.
   * `noWorn` (a called shot at a gap) leaves out the parts RULES.COMBAT_V72.calledShotGap.bypasses lists (v0.72.0: worn armor).
   */
  armorRating(kind: 'ballistic' | 'impact', opts: { ignoreImmunity?: boolean; noWorn?: boolean; calledLocation?: string } = {}): number {
    // Layering (v0.37.0): only the best piece counts, plus pieces that add to others (RULES.COMBAT.armorLayering).
    const worn = armorTotal([...this.items]
      .filter((i: any) => i.type === 'armor' && i.system.worn && isCarried(i))
      .map((i: any) => ({ ballistic: i.system.ballistic ?? 0, impact: i.system.impact ?? 0, adds: Boolean(i.system.adds), degraded: i.system.degraded ?? 0 })), kind);
    // v0.56.0: a critter's immunity to normal weapons (RULES.CRITTERS_V56.immunity), and armor from spells and powers on it.
    const critterImmune = this.type !== 'spirit' && !opts.ignoreImmunity && this.immunities().normalWeapons ? immunityArmorFromEssence(Number(this.sys.derived?.essence ?? this.sys.essence ?? 0)) : 0;
    const spiritImmune = this.type === 'spirit' && !opts.ignoreImmunity ? immunityArmor(this.sys.force, Boolean(this.sys.immuneNormalWeapons)) : 0;
    // v0.72.0 (O4): a called shot at a gap (`noWorn`) bypasses only the parts in RULES.COMBAT_V72.calledShotGap.bypasses
    // (worn armor by default; dermal plating, orthoskin and limb armor still count).
    return armorFromParts({
      worn,
      adept: adeptArmor(adeptPowersOf(this), kind),
      cyber: (this.sys.derived?.cyberArmor?.[kind] as number | undefined) ?? 0,
      // Cyberlimbs' armor: only against a called shot at the limb (RULES.GEAR.cyberlimbs, v0.43.0).
      limb: limbArmorFor([...(this.sys.derived?.cyber?.limbs ?? [])], kind, opts.calledLocation ?? ''),
      effect: Math.max(0, Number(this.sys.derived?.effectArmor?.[kind] ?? 0)),
      immunity: critterImmune + spiritImmune,
    }, Boolean(opts.noWorn));
  }

  /** v0.56.0: how far an adept's distance strike reaches (metres; 0 = none). */
  distanceStrikeReach(): number {
    return distanceStrikeMetres(adeptSpecialLevel(adeptPowersOf(this) as any, 'distanceStrike'), Number(this.sys.derived?.magic ?? 0));
  }

  /** v0.56.0: what this critter is immune to (Power items with Special "immunity"). */
  immunities(): { normalWeapons: boolean; fire: boolean; poisons: boolean; pathogens: boolean; age: boolean } {
    if (this.type === 'vehicle' || this.type === 'host' || this.type === 'site' || this.type === 'safehouse' || this.type === 'barrier') return { normalWeapons: false, fire: false, poisons: false, pathogens: false, age: false };
    return critterImmunities(this.critterTraits());
  }

  async #spendPool(pool: PoolKind, dice: number): Promise<void> {
    await this.update({ [`system.poolSpent.${pool}`]: ((this.sys.poolSpent[pool] as number | undefined) ?? 0) + dice });
  }

  /**
   * v0.92.0 (RULES.MAGIC_V920): which of Sorcery's narrow layers (concentration, specialization) a magical action falls
   * inside. With both switches back to the old way, none.
   */
  sorceryUseFor(action: SorceryAction, o: { category?: string; spellName?: string; skill?: any } = {}): SorceryUse {
    if (!layersOn() && !narrowCastingOn()) return { conc: false, spec: false };
    // Review (N11): the skill the test rolls when the caller has it, else the highest Sorcery.
    return sorceryUse((o.skill ?? sorcerySkillOf([...this.items] as any[]))?.system ?? null, action, o);
  }

  /** v0.92.0: the Spell Pool dice a casting's Drain may take (the narrow layers only with RULES.MAGIC_V920.drainNarrow). */
  drainPoolFor(use: SorceryUse | null | undefined): number {
    return drainNarrowOn() ? this.spellPoolFor(use) : Number(this.sys.derived?.spellPoolLeft ?? 0);
  }

  /** v0.92.0: the Spell Pool dice an action may use: the general dice left plus the narrow layers it falls inside. */
  spellPoolFor(use: SorceryUse | null | undefined): number {
    const d: any = this.sys.derived ?? {};
    const l = d.spellLayers ?? { concLeft: 0, specLeft: 0 };
    return poolForUse(Number(d.spellPoolLeft ?? 0), { conc: Number(l.concLeft ?? 0), spec: Number(l.specLeft ?? 0) }, use ?? { conc: false, spec: false });
  }

  /** v0.92.0: spend Spell Pool dice for an action: the specialization's first, then the concentration's, then general. */
  async #spendSpellPool(dice: number, use: SorceryUse): Promise<void> {
    const d: any = this.sys.derived ?? {};
    const l = d.spellLayers ?? { concLeft: 0, specLeft: 0 };
    const p = spendPlan(dice, Number(d.spellPoolLeft ?? 0), { conc: Number(l.concLeft ?? 0), spec: Number(l.specLeft ?? 0) }, use);
    const ps: any = this.sys.poolSpent ?? {};
    await this.update({
      'system.poolSpent.spell': Number(ps.spell ?? 0) + p.general,
      'system.poolSpent.spellConc': Number(ps.spellConc ?? 0) + p.conc,
      'system.poolSpent.spellSpec': Number(ps.spellSpec ?? 0) + p.spec,
    });
  }

  /**
   * Cast a spell: a Sorcery test with Spell Pool dice. Against a combat spell the TN is the
   * target's resisting attribute; otherwise it is the spell's own TN. Drain is resolved
   * straight afterwards. A combat spell that scores successes against a target carries a
   * Resist Spell button.
   */
  async castSpell(spell: any, opts: {
    force?: number; targetUuid?: string | null; poolDice?: number; drainPoolDice?: number;
    /** Area spells: every target (the TN is the highest of their resisting attributes). */
    targetUuids?: string[];
    /** Sustained spells: hold it with a free sustaining focus instead of taking the TN penalty. */
    useSustainingFocus?: boolean;
    /** Fetish-limited spells cannot be cast without the fetish (defaults to having it). */
    fetishInHand?: boolean;
    /** Ritual sorcery: the other team members, whether the target is in sight or linked, and a spotter. */
    ritual?: { teamUuids: string[]; materialLink: boolean; spotterUuid?: string | null; sending?: boolean } | null;
    /** An elemental of the spell's element adding its Force as dice (costs a service). */
    aidUuid?: string | null;
    /** A ward or mana barrier between caster and target: its rating adds resistance dice. */
    barrierUuid?: string | null;
    /** Anchoring metamagic: store the spell to release later instead of casting it now. */
    anchor?: { trigger: string } | null;
    /** v0.50.0: found-by-themselves modifiers switched off in the dialog. */
    exclude?: string[];
  } = {}): Promise<SuccessTestResult | null> {
    if (!this.canAct('castSpell')) return null;
    const sp = spell.system;
    // v0.61.0: an exclusive spell limits other spellcasting (MAGIC_V61.exclusive).
    {
      const ex = opts.anchor ? null : exclusiveBlock({ sustaining: this.sustained() as any[], action: 'cast', newSpellExclusive: Boolean(sp.exclusive) && ['sustained', 'permanent'].includes(String(sp.duration ?? '')) });
      if (ex) { ui.notifications?.warn?.(`${escHtml(this.name)}: ${escHtml(ex)}`); return null; }
    }
    const blocked = traditionBlocks(this.tradition, 'cast')
      ?? aspectRestriction(this.tradition, 'cast', { aspectElement: this.sys.aspectElement, category: sp.category, spellElement: sp.element, totem: this.sys.totem });
    if (blocked) {
      ui.notifications?.warn?.(`${escHtml(this.name)}: ${escHtml(blocked)}`);
      return null;
    }
    if (opts.anchor) return this.#anchorSpell(spell, opts.force ?? sp.learnedForce, opts.anchor.trigger);
    const sorcery = this.findSkill('Sorcery');
    // v0.92.0 (RULES.MAGIC_V920): inside Sorcery's concentration or specialization the test rolls its rating, and the
    // Spell Pool's narrow layers may pay for the test and its Drain.
    const castUse = this.sorceryUseFor(opts.ritual ? 'ritual' : 'cast', { category: sp.category, spellName: spell.name, skill: sorcery });
    const castRating = narrowRating(sorcery?.system ?? null, castUse);
    // v0.72.0 (O18): a spirit (Force) or a critter's innate spell (Magic, else Essence) casts without a Sorcery skill (MAGIC_V72.innateSpells).
    const caster = innateSpellDice({ actorType: this.type, sorceryRating: castRating, spellInnate: Boolean(sp.innate),
      spiritKind: String(this.sys.spiritKind ?? ''), force: Number(this.sys.force ?? 0), magic: Number(this.sys.derived?.magic ?? 0),
      essence: Number(this.sys.derived?.essence ?? this.sys.essence ?? 0), intelligence: Number(this.sys.attributes?.intelligence?.total ?? 0) });
    if (!caster) {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.hasNoSorcerySkillAndCannot', { name: escHtml(this.name) }));
      return null;
    }
    if (!caster.innate && (this.sys.derived.magic as number) <= 0) {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.hasNoMagicAndCannotCast', { name: escHtml(this.name) }));
      return null;
    }
    if (sp.fetish && opts.fetishInHand === false) {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.isFetishLimitedNeedsTheFetish', { spellName: escHtml(spell.name), name: escHtml(this.name) }));
      return null;
    }
    const drainForce = clampForce(opts.force ?? sp.learnedForce, sp.learnedForce);
    // v0.80.0 (RULES.URR_V80.magExclusiveForce / magFetishForce, URR): exclusive and fetish spells take effect higher.
    const force = drainForce + urrMagSpellForceBonus({ exclusive: Boolean(sp.exclusive), fetish: Boolean(sp.fetish) });
    const combat = sp.category === 'combat';
    const heals = sp.category === 'health' && Boolean(sp.heals);
    // Elemental manipulations (Fireball...) work like a ranged attack instead of a resisted spell.
    const elemental = Boolean(sp.elemental) && !heals;
    // Combat spells are resisted by Willpower (mana) or Body (physical); other spells only if the
    // spell names a resisting attribute (e.g. a Confusion or Control spell on an unwilling target).
    const resistAttribute: AttributeKey | null = elemental ? null : combat
      ? spellResistAttribute(sp.spellType)
      : !heals && sp.resist && sp.resist !== 'none' ? (sp.resist as AttributeKey) : null;
    const uuids = [...new Set([...(opts.targetUuids ?? []), ...(opts.targetUuid ? [opts.targetUuid] : [])])];
    // v0.56.0: a touch spell needs contact, not sight (RULES.MAGIC_V56.touch).
    const touch = sp.range === 'touch';

    // Ritual sorcery: the team adds dice; a target must be in sight or linked by a material link.
    const team: any[] = [];
    let spotter: any = null;
    if (opts.ritual) {
      spotter = opts.ritual.spotterUuid ? await fromUuid(opts.ritual.spotterUuid) : null;
      if (spotter && !spotter.isAstral?.()) {
        ui.notifications?.warn?.(tx('SR2E.Notify.Actor.mustBeOnTheAstralPlane', { spotterName: escHtml(spotter.name) }));
        spotter = null;
      }
      if (RULES.RITUAL.needsMaterialLink && uuids.length && !ritualCanReach({ materialLink: opts.ritual.materialLink, spotter: Boolean(spotter) })) {
        ui.notifications?.warn?.(tx('SR2E.Notify.Actor.ritualSorceryAgainstATargetOut'));
        return null;
      }
      for (const u of opts.ritual.teamUuids) {
        const m: any = await fromUuid(u);
        if (m && m.uuid !== this.uuid) team.push(m);
      }
      // v0.80.0 (RULES.URR_V80.magRitualNoCombat / magRitualTeamCap, URR).
      const rp = urrMagRitualProblem({ category: String(sp.category ?? ''), sorcery: [Number(sorcery?.system?.rating ?? 0),
        ...[...team, ...(spotter && !team.includes(spotter) ? [spotter] : [])].map((m: any) => Number(m?.findSkill?.('Sorcery')?.system?.rating ?? 0))] });
      if (rp) { ui.notifications?.warn?.(rp); return null; }
    }

    // v0.80.0 (RULES.URR_V80.magElementalTn, URR): a ranged manipulation (elemental) spell at a fixed TN.
    let targetNumber = elemental ? urrMagElementalTn(sp.targetNumber as number) : sp.targetNumber as number;
    let tnLabel = tx('SR2E.Card.Actor.spellTn');
    const targets: any[] = [];
    // Vehicles (v0.43.0): mana spells can't touch them; the TN against one is its Object Resistance.
    const vehicles: Array<{ actor: any; tn: number }> = [];
    let refused = 0;
    for (const u of uuids) {
      const t: any = await fromUuid(u);
      if (t?.type === 'vehicle') {
        if (heals) continue;
        const v = spellVsVehicle({ spellType: sp.spellType, objectResistance: t.system?.objectResistance });
        if (!v.ok) { refused++; ui.notifications?.warn?.(tx('SR2E.Notify.Actor.canTAffect', { spellName: escHtml(spell.name), tName: escHtml(t.name), reason: escHtml(v.reason) })); }
        else vehicles.push({ actor: t, tn: v.tn });
      } else if (t?.system?.attributes) targets.push(t);
    }
    if (refused && !targets.length && !vehicles.length) return null;
    // v0.71.0 (R12): invisible targets are resisted first (once per spell on them).
    if (!opts.ritual && !touch) await this.spotInvisible([...targets, ...vehicles.map((v) => v.actor)]);
    // v0.50.0: no line of sight from the caster's token (RULES.TN_AUTO.magic.lineOfSight 'block'); a ritual reaches by link.
    if (RULES.TN_AUTO.magic.lineOfSight === 'block' && !opts.ritual && !touch) {
      const unseen = this.#unseenTargets([...targets, ...vehicles.map((v) => v.actor)]);
      if (unseen.length) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.hasNoLineOfSightTo', { name: escHtml(this.name), unseen: escHtml(unseen.join(', ')) })); return null; }
    }
    // Spells cannot cross between the astral and physical worlds freely.
    for (const t of targets) {
      const astralOnly = (t.type === 'spirit' && t.system.materialized === false) || t.system.derived?.astralMode === 'projecting';
      const problem = castingPlaneProblem({ mode: this.sys.derived.astralMode ?? 'physical', isSpirit: this.type === 'spirit' }, { astralOnly, name: t.name }, sp.spellType);
      if (problem) {
        ui.notifications?.warn?.(escHtml(problem));
        return null;
      }
    }
    // v0.56.0: a detection spell's range (Magic × Force metres; RULES.MAGIC_V56.detectionRange).
    const dr = RULES.MAGIC_V56.detectionRange;
    if (sp.category === 'detection' && dr.enforce !== 'off' && !opts.ritual) {
      const from = SR2Actor.tokenFor(this);
      for (const t of targets) {
        const to = SR2Actor.tokenFor(t);
        const d = from && to && from !== to ? measureTokens(from, to)?.metres ?? null : null;
        const problem = detectionRangeProblem(d, Number(this.sys.derived.magic ?? 0), force, Boolean(sp.extendedRange));
        if (!problem) continue;
        ui.notifications?.warn?.(`${escHtml(t.name)} ${problem}`);
        if (dr.enforce === 'block') return null;
      }
    }
    // v0.56.0: a touch spell: close enough, and a touch test against each unwilling target.
    if (touch && targets.length && !opts.ritual) {
      const t56 = RULES.MAGIC_V56.touch;
      const mine = this.selfUuids();
      const others = targets.filter((t) => !mine.includes(t.uuid));
      if (t56.distance !== 'off') {
        const from = SR2Actor.tokenFor(this);
        const far = others.filter((t) => { const to = SR2Actor.tokenFor(t); return touchReach(from && to ? measureTokens(from, to)?.metres ?? null : null) === 'far'; });
        if (far.length) {
          ui.notifications?.warn?.(tx('SR2E.Notify.Actor.isATouchSpellMoreThan', { spellName: escHtml(spell.name), map: escHtml(far.map((t) => t.name).join(', ')), plural: far.length === 1 ? tx('SR2E.Notify.Actor.is2') : tx('SR2E.Notify.Actor.are'), t56ReachMetres: t56.reachMetres }));
          if (t56.distance === 'block') return null;
        }
      }
      if (combat || resistAttribute) {
        for (const t of others) if (!(await this.#touchTest(t, spell.name))) targets.splice(targets.indexOf(t), 1);
        if (!targets.length && !vehicles.length) return null;
      }
    }
    // An elemental aiding the spell.
    let aid: any = opts.aidUuid ? await fromUuid(opts.aidUuid) : null;
    if (aid) {
      const sKind = aid.system?.spiritKind;
      if (aid.type !== 'spirit' || sKind !== 'elemental' || aid.system.summonerUuid !== this.uuid) {
        ui.notifications?.warn?.(tx('SR2E.Notify.Actor.isNotOneOfSElementals', { aidName: escHtml(aid.name), name: escHtml(this.name) }));
        aid = null;
      } else if (!elementalServes(aid.system.element ?? '', { element: sp.element ?? '', category: sp.category ?? '' })) {
        ui.notifications?.warn?.(tx('SR2E.Notify.Actor.canOnlyAidIs', { aidName: escHtml(aid.name), aidElement: escHtml(aid.system.element || tx('SR2E.Notify.Actor.noElement')), elementalServesLabel: escHtml(elementalServesLabel(aid.system.element ?? '')), spellName: escHtml(spell.name), part: RULES.MAGIC_EXTRA.elementalMatch === 'element' ? escHtml(sp.element || tx('SR2E.Notify.Actor.ofNoElement')) : (sp.category ? tx('SR2E.Notify.Actor.aCategorySpell', { category: escHtml(sp.category) }) : tx('SR2E.Notify.Actor.aSpellOfNoCategory')) }));
        aid = null;
      } else if (RULES.MAGIC_EXTRA.elementalAid.costsService && (aid.system.services ?? 0) <= 0) {
        ui.notifications?.warn?.(tx('SR2E.Notify.Actor.owesNoServices', { aidName: escHtml(aid.name) }));
        aid = null;
      }
    }
    // v0.60.0: not chosen (a macro, a quick roll): the ward region between the caster and the first target.
    let barrierUuid = opts.barrierUuid;
    if (barrierUuid === undefined && targets[0] && !elemental) {
      // v0.72.0 (O17): a physical barrier doesn't stop spells (MAGIC_V72; VERIFY).
      try { barrierUuid = wardsBetween(attackerToken(this), SR2Actor.tokenFor(targets[0])).find((b: any) => barrierBlocks(String(b.system?.barrierKind ?? 'ward'), 'spell'))?.uuid ?? null; } catch { barrierUuid = null; }
    }
    const barrier: any = barrierUuid ? await fromUuid(barrierUuid) : null;
    // v0.78.0 (RULES.BOOK_V78.manaBarrier.spells): a mana barrier adds its rating to the caster's TN (the book), a ward its dice.
    const barrierFx = barrier && barrier.type === 'barrier' && !elemental ? barrierSpellEffect(barrier.system.rating, String(barrier.system.barrierKind ?? 'ward')) : { dice: 0, tn: 0 };
    const barrierDice = barrierFx.dice;
    const barrierTn = barrierFx.tn;
    let healContext: TestSnapshot['heal'] | undefined;
    if (heals) {
      const patient: any = targets[0] ?? this;
      targetNumber = healingTargetNumber(patient.system.derived?.essence ?? 6, sp.targetNumber);
      tnLabel = RULES.SPELLCRAFT.healing.tn === 'essence' ? tx('SR2E.Card.Actor.sEssence', { healingBase: RULES.SPELLCRAFT.healing.base, patientName: patient.name }) : tx('SR2E.Card.Actor.spellTn');
      const track = (sp.healTrack ?? 'physical') as 'physical' | 'stun';
      const healedAt = patient.getFlag?.(SYSTEM_ID, 'healedAt') as Record<string, number> | undefined;
      if (RULES.SPELLCRAFT.healing.oncePerWound && healedAt && typeof healedAt[track] === 'number' && patient.system.monitor[track] <= healedAt[track]) {
        ui.notifications?.warn?.(tx('SR2E.Notify.Actor.sDamageHasAlreadyBeenHealed', { patientName: escHtml(patient.name), track }));
      }
      // v0.56.0: Treat works only soon after the wound (RULES.MAGIC_V56.healing.treatHours).
      if (sp.treat) {
        const at = (patient.getFlag?.(SYSTEM_ID, 'damagedAt') as Record<string, number> | undefined)?.[track];
        const problem = treatWindowProblem(at, sysNow());
        if (problem) {
          ui.notifications?.warn?.(tx('SR2E.Notify.Actor.on', { spellName: escHtml(spell.name), patientName: escHtml(patient.name), problem: escHtml(problem) }));
          if (RULES.MAGIC_V56.healing.treatBlock) return null;
        }
      }
      healContext = { targetUuid: patient.uuid, targetName: patient.name, track, before: patient.system.monitor[track] };
    } else if (resistAttribute) {
      const withAttr = targets.filter((t) => typeof t.system.attributes[resistAttribute]?.total === 'number');
      targets.splice(0, targets.length, ...withAttr);
      const attrName = resistAttribute.charAt(0).toUpperCase() + resistAttribute.slice(1);
      if (targets.length === 1) {
        targetNumber = targets[0].system.attributes[resistAttribute].total;
        tnLabel = `${targets[0].name}'s ${attrName}`;
      } else if (targets.length > 1) {
        targetNumber = areaTargetNumber(targets.map((t) => t.system.attributes[resistAttribute].total));
        tnLabel = tx('SR2E.Card.Actor.ofTargets', { magicAreaTn: RULES.MAGIC.areaTn, attrName, targetsLength: targets.length });
      }
    }

    // Vehicles: the caster rolls against the highest Object Resistance (with the living targets' attribute, the higher).
    if (vehicles.length && !elemental) {
      const vtn = Math.max(...vehicles.map((v) => v.tn));
      const vLabel = vehicles.length === 1 ? tx('SR2E.Card.Actor.sObjectResistance', { actorName: vehicles[0]!.actor.name }) : tx('SR2E.Card.Actor.objectResistanceOfVehicles', { vehiclesLength: vehicles.length });
      if (!resistAttribute) {
        if (vtn > targetNumber) { targetNumber = vtn; tnLabel = vLabel; }
      } else if (!targets.length) { targetNumber = vtn; tnLabel = vLabel; }
      else if (vtn > targetNumber) { targetNumber = vtn; tnLabel = `${tnLabel} / ${vLabel}`; }
    }
    const vs = RULES.GEAR.spellsVsVehicles;
    const vehicleHit = (v: any) => ({
      attackerUuid: this.uuid as string, targetUuid: v.uuid as string, weaponName: spell.name, melee: false,
      damageType: 'physical' as DamageType, power: force, level: sp.damageLevel as DamageLevel, noDodge: true,
      ...(vs.antiVehicle ? { antiVehicle: true } : {}), ...(vs.combatArmor ? {} : { ignoreArmor: true }),
      ...(RULES.URR_V80.vehDamage.mode === 'urr' ? { vehHit: { spell: true } } : {}),
    });
    const spellVehicles = combat && !elemental ? vehicles.map((v) => vehicleHit(v.actor)) : [];
    const spellTargets = heals || !resistAttribute ? [] : targets.map((t) => ({
      casterUuid: this.uuid as string, targetUuid: t.uuid as string, spellName: spell.name, force, resistAttribute,
      level: sp.damageLevel as DamageLevel, damageType: sp.damageType as DamageType,
      ...(combat ? {} : { effectOnly: true }),
      ...(barrierDice ? { barrierDice, barrierName: barrier.name } : {}),
      ...(opts.ritual ? urrMagRitualResistTn(force, Number(sorcery?.system?.rating ?? 0)) : {}),
    }));
    // v0.56.0: a sustained (or permanent) spell that changes its target's stats: one effect id for every target.
    const lasting = sp.duration === 'sustained' || (sp.duration === 'permanent' && RULES.MAGIC_V56.permanent.enabled);
    // With the permanent house rule off, a permanent spell takes at once: its effect is permanent from the start.
    const takesAtOnce = sp.duration === 'permanent' && !RULES.MAGIC_V56.permanent.enabled;
    const fxBase = (lasting || takesAtOnce) && !elemental && !heals && !combat ? SR2Actor.spellFx(spell, force) : null;
    const fxSpec = fxBase && takesAtOnce ? { ...fxBase, permanent: true } : fxBase;
    // Every lasting spell gets its own id (its Sustaining entry and its effect share it).
    const effectId = lasting || fxSpec ? `sp${SR2Actor.#newId()}` : '';
    if (fxSpec) for (const st of spellTargets) (st as any).powerEffect = { ...fxSpec, effectId };
    const ownFx = fxSpec && !resistAttribute ? { powerEffect: { ...fxSpec, effectId, targetUuids: targets.length ? targets.map((t) => t.uuid as string) : [this.uuid as string] } } : {};
    // Elemental spells: a ranged attack on each target with Power = Force; part of their armor counts.
    const dodge = RULES.MAGIC_EXTRA.elemental.dodge;
    const attackTargets = elemental ? targets.map((t) => ({
      attackerUuid: this.uuid as string, targetUuid: t.uuid as string, weaponName: spell.name, melee: false,
      damageType: sp.damageType as DamageType, power: force, level: sp.damageLevel as DamageLevel, elemental: true,
      ...(dodge ? {} : { noDodge: true }),
      // The element's secondary effect (v0.39.0).
      ...(elementEffect(sp.element ?? '') !== 'none' ? { elementEffect: elementEffect(sp.element ?? ''), spellForce: force } : {}),
    })) : [];
    // Elemental spells hit vehicles like any attack (v0.43.0).
    if (elemental) for (const v of vehicles) attackTargets.push({ ...vehicleHit(v.actor), elemental: true, damageType: sp.damageType as DamageType } as any);
    // Ritual sorcery (v0.39.0): it needs a library or lodge, then is prepared before it is sent.
    if (opts.ritual && !opts.ritual.sending) {
      const missing = missingSites('ritual', this.tradition, this.magicSites(), { force, totem: this.sys.totem?.name ?? '' });
      if (missing.length && !this.#siteProblem(tx('SR2E.Card.Actor.ritualSorceryAtForce', { force }), missing)) return null;
      if (RULES.MAGIC_V39.ritualStages.enabled) {
        await this.#prepareRitual(spell, force, { ...opts, targetUuids: uuids, targetUuid: null }, team, spotter);
        return null;
      }
    }
    let holder: Focus | null = null;
    if (lasting && opts.useSustainingFocus) {
      holder = availableSustainingFocus(this.foci(), this.sustained(), { force, category: sp.category });
      if (!holder) ui.notifications?.warn?.(tx('SR2E.Notify.Actor.noFreeSustainingFocusCanHold', { spellName: escHtml(spell.name), force, name: escHtml(this.name) }));
    }
    // v0.80.0 (RULES.URR_V80.magSustainCap, URR): no more self-sustained spells than the Sorcery rating.
    if (lasting && !holder && !caster.innate) {
      const cap = urrMagSustainCapProblem(this.sustained() as any[], Number(sorcery?.system?.rating ?? 0));
      if (cap) { ui.notifications?.warn?.(`${escHtml(this.name)} ${cap}`); return null; }
    }

    this.#warnGeasa(tx('SR2E.Card.Actor.casts'));
    const focus = sorceryFocusDice(this.foci(), { name: spell.name, category: sp.category });
    const totem = totemDice(this.tradition, this.sys.totem, sp.category);
    const extra = bonusNote(focus, totem);
    // v0.92.0: say which narrow rating the test rolls.
    if (sorcery && castRating > Number(sorcery.system?.rating ?? 0)) extra.note += ` [${tx('SR2E.Card.MagicPool.narrow', { name: castUse.spec ? sorcery.system.specialization : sorcery.system.concentration, rating: castRating })}]`;
    const env = totemEnvironmentDice(this.tradition, this.sys.totem, this.environmentHere());
    if (env.dice) {
      extra.dice += env.dice;
      extra.note = extra.note ? extra.note.replace(/\]$/, `, ${env.note}]`) : ` [${env.note}]`;
    }
    const aidDice = aid ? elementalAidDice(aid.system.force) : 0;
    if (aidDice) extra.note += ` [${aid.name} aids +${aidDice}]`;
    const teamDice = team.length ? ritualTeamDice(team.map((m) => m.findSkill?.('Sorcery')?.system.rating ?? 0)) : 0;
    const ritualNote = team.length || opts.ritual
      ? tx('SR2E.Card.Actor.ritualMembersH', { value: team.length + 1, part: teamDice ? tx('SR2E.Card.Actor.team', { teamDice }) : '', part2: spotter ? tx('SR2E.Card.Actor.spotter', { spotterName: spotter.name }) : '', ritualHours: ritualHours(force) }) : '';
    const barrierNote = barrierDice ? tx('SR2E.Card.Actor.through', { barrierName: barrier.name, barrierDice }) : barrierTn ? tx('SR2E.Card.Actor.acrossTn', { barrierName: barrier.name, barrierTn }) : '';
    if (aid && RULES.MAGIC_EXTRA.elementalAid.costsService) await aid.update({ 'system.services': Math.max(0, (aid.system.services as number) - 1) });
    const innateNote = caster.innate ? tx('SR2E.Card.Actor.innate', { casterLabel: caster.label, casterDice: caster.dice }) : '';
    const result = await this.#runTest(tx('SR2E.Card.Actor.forceTn', { spellName: spell.name, force, part: elemental ? tx('SR2E.Card.Actor.spellTn2') : tnLabel, extraNote: extra.note, ritualNote, barrierNote, innateNote }),
      // v0.80.0 (RULES.URR_V80.magCastDice 'force', URR): the spell's Force instead of Sorcery.
      Math.max(0, urrMagCastingDice({ dice: caster.dice, force, innate: caster.innate }) + extra.dice + teamDice + aidDice),
      // v0.79.0 (RULES.DOCS_V79.magicPool.castingCap 'magic', SR2 p85): at most Magic-rating Spell Pool dice on the success test.
      { targetNumber, poolDice: castingPoolDice(opts.poolDice ?? 0, Number(this.sys.derived?.magic ?? 0)), pool: 'spell', spellUse: castUse, magical: true, sightHandled: true,
        modifiers: [...(touch ? [] : this.#spellEnvironment(elemental, targets[0] ?? vehicles[0]?.actor ?? null)), ...(combat || elemental || resistAttribute ? SR2Actor.attackedMods(targets) : []),
          ...(barrierTn ? [{ label: tx('SR2E.Card.Mod.across', { barrierName: barrier.name }), value: barrierTn }] : [])],
        ...(opts.exclude?.length ? { exclude: opts.exclude } : {}) },
      {
        kind: elemental ? 'attack' : heals ? 'heal' : 'spell',
        // v0.92.0: which interpretations the cast rests on (its card's † line).
        // Review (N13): the layers this cast falls inside, not any layer.
        ...(castUse.conc || castUse.spec ? { narrow: { layers: layersOn() && ((castUse.conc && Number(this.sys.derived?.spellLayers?.conc ?? 0) > 0) || (castUse.spec && Number(this.sys.derived?.spellLayers?.spec ?? 0) > 0)), rating: castRating > Number(sorcery?.system?.rating ?? 0) } } : {}),
        ...(attackTargets.length === 1 ? { attack: attackTargets[0] } : {}),
        ...(attackTargets.length > 1 ? { attackTargets } : {}),
        ...(healContext ? { heal: healContext } : {}),
        ...(spellTargets.length === 1 ? { spell: spellTargets[0] } : {}),
        ...(spellTargets.length > 1 ? { spellTargets } : {}),
        ...(spellVehicles.length ? { spellVehicles } : {}),
        // A sustained spell stays up once it succeeds: on a free sustaining focus, or on the caster (+TN).
        // v0.56.0: a permanent one too, until it takes; and the effect it puts on its targets.
        ...(lasting ? { sustain: { spellName: spell.name, force, category: sp.category, focusId: holder?.id ?? '', targetUuids: uuids.filter((u) => targets.some((t) => t.uuid === u) || vehicles.some((v) => v.actor.uuid === u)),
          ...(effectId ? { effectId } : {}), ...(sp.duration === 'permanent' ? { permanent: true } : {}), ...(sp.exclusive ? { exclusive: true } : {}),
          ...(barrierSpellKind(spell) ? { barrier: barrierSpellKind(spell)! } : {}) } } : {}),
        ...ownFx,
      });

    await this.leaveSignature('spell', spell.name, force);
    const drainMods = spellOptionDrainMods({ exclusive: sp.exclusive, fetish: sp.fetish });
    // v0.56.0: a healing spell set to drain by the wound drains at the level of the damage it heals.
    const drainLevel = heals && sp.healDrain === 'wound' && healContext ? healDrainLevel(healContext.before, sp.drainLevel) : undefined;
    // v0.80.0 (RULES.URR_V80.magRuleOfOneDrain, URR): a disaster on the casting adds to the caster's drain TN.
    const ownDrainMods = [...drainMods, ...urrMagRuleOfOneDrain(Boolean((result as any)?.botch))];
    if (!caster.innate || innateDrains()) await this.#resistDrain(spell, drainForce, opts.drainPoolDice ?? 0, team.length ? [...ownDrainMods, ...(RULES.RITUAL.leaderDrainMod ? [{ id: 'ritualLeader', label: tx('SR2E.Card.Mod.ritualLeader'), value: RULES.RITUAL.leaderDrainMod }] : [])] : ownDrainMods, tx('SR2E.Card.Actor.drain'), drainLevel, castUse);
    // Every ritual team member resists the drain too.
    const memberHow = tx('SR2E.Card.Actor.willpowerVsTnDrain', { value: drainTargetNumber(drainForce, sp.drainModifier) + drainMods.reduce((n, x) => n + Number(x.value ?? 0), 0), spDrainLevel: sp.drainLevel });
    for (const m of team) if (typeof m.ritualDrain === 'function') await this.#memberDrain(m, tx('SR2E.Card.Actor.force', { spellName: spell.name, drainForce }), () => m.ritualDrain(spell, drainForce, drainMods), memberHow);
    // v0.80.0 (RULES.URR_V80.magSpotterDrain, URR): the spotter (guide) drains as a team member.
    if (spotter && RULES.URR_V80.magSpotterDrain && !team.includes(spotter) && typeof spotter.ritualDrain === 'function') await this.#memberDrain(spotter, tx('SR2E.Card.Actor.force', { spellName: spell.name, drainForce }), () => spotter.ritualDrain(spell, drainForce, drainMods), memberHow);
    return result;
  }

  /**
   * v0.56.0: touching an unwilling target for a touch spell (RULES.MAGIC_V56.touch): the caster's skill
   * vs the TN, opposed by the target's attribute; posts one card and says whether contact was made.
   */
  async #touchTest(target: any, what: string): Promise<boolean> {
    const t56 = RULES.MAGIC_V56.touch;
    const skill = this.findSkill(t56.skill);
    const mine = this.#skillDice(skill, false, null, 'quickness', { skillName: t56.skill });
    const rolls: any[] = [];
    const me = await successTest({ dice: mine.dice, targetNumber: t56.tn, modifiers: this.#testModifiers({ modifiers: mine.modifiers }), roll: foundryRoller(rolls) });
    let them: SuccessTestResult | null = null;
    if (t56.opposed) {
      const dice = Number(target.system?.attributes?.[t56.defense]?.total ?? 0);
      them = await successTest({ dice, targetNumber: t56.tn, roll: foundryRoller(rolls) });
    }
    const ok = touchContact(me.successes, them?.successes ?? 0);
    await ChatMessage.create({
      speaker: ChatMessage.getSpeaker({ actor: this }), rolls,
      content: `${describeResult(tx('SR2E.Card.Actor.touchFor', { targetName: target.name, what, t56Skill: t56.skill, mineSuffix: mine.suffix }), me)}${them ? describeResult(tx('SR2E.Card.Actor.avoidsTheTouch', { targetName: target.name, t56Defense: cap(t56.defense) }), them) : ''}
        <p>${ok ? `<strong>${tx('SR2E.Card.Actor.contact')}</strong> ${tx('SR2E.Card.Actor.goesAheadOn', { what: escText(what), targetName: escText(target.name) })}` : `<strong>${tx('SR2E.Card.Actor.noContact')}</strong> ${tx('SR2E.Card.Actor.avoidsTheTouch2', { targetName: escText(target.name) })}`}</p>`,
    });
    return ok;
  }

  /** v0.56.0: world seconds per Combat Turn for permanent spells: the house rule, else Foundry's round time, else 3. */
  static secondsPerTurn(): number {
    return Number(RULES.MAGIC_V56.permanent.secondsPerTurn) || Number((globalThis as any).CONFIG?.time?.roundTime) || 3;
  }

  /** v0.56.0: a spell's stat changes as an effect spec (null when it changes nothing). */
  static spellFx(spell: any, force: number): FxSpec | null {
    const e = spell?.system?.effects ?? {};
    const bundle: Partial<EffectBundle> = {
      reaction: Number(e.reaction ?? 0), initiativeDice: Number(e.initiativeDice ?? 0), ballistic: Number(e.ballistic ?? 0), impact: Number(e.impact ?? 0),
      testsTn: Number(e.testsTn ?? 0), perceivedTn: Number(e.perceivedTn ?? 0), attackedTn: Number(e.attackedTn ?? 0), movementFactor: Number(e.movementFactor ?? 1) || 1,
    };
    const attributes = Object.fromEntries(Object.entries(e.attributes ?? {}).map(([k, v]) => [k, Number(v) || 0]).filter(([, v]) => v)) as Record<string, number>;
    if (!bundleHasEffect({ ...bundle, attributes })) return null;
    return {
      name: spell.name, attributes, perSuccess: Boolean(spell.system.effectPerSuccess), bundle, kind: 'spell',
      capAt: RULES.MAGIC_V56.spellEffects.capAtForce ? force : 0, step: RULES.MAGIC_V56.spellEffects.step,
    };
  }

  /** v0.56.0: an effect spec at this many successes, as a powerEffects flag entry. */
  static fxEntry(fx: FxSpec, successes: number, id: string, fromUuid: string, fromName: string): FxEntry {
    const isSpell = fx.kind === 'spell';
    const base = scaleBundle({ ...(fx.bundle ?? {}), attributes: fx.attributes ?? {} }, {
      perSuccess: fx.perSuccess, successes, step: fx.step ?? (isSpell ? RULES.MAGIC_V56.spellEffects.step : 1), capAt: fx.capAt && fx.capAt > 0 ? fx.capAt : null,
    });
    // Powers keep their own per-success cap on attributes (RULES.OCCULT.powers, v0.45.0).
    if (!isSpell) base.attributes = successes > 0 ? powerAttributeChanges(fx.attributes ?? {}, fx.perSuccess, successes) : {};
    // A TN-changing power's Special fills in what its own fields leave at 0 (RULES.CRITTERS_V56.powerMods).
    let special: Partial<EffectBundle> = {};
    if (successes > 0 && fx.special && (TN_POWER_SPECIALS as readonly string[]).includes(fx.special)) {
      const filled = powerModifierBundle(fx.special, { force: fx.force ?? 0, successes });
      special = Object.fromEntries(Object.entries(filled).filter(([k]) => (k === 'movementFactor' ? (base.movementFactor ?? 1) === 1 : !Number((base as any)[k] ?? 0)))) as Partial<EffectBundle>;
    }
    // v0.78.0 (RULES.BOOK_V78.paralysis 'drain', Core Rules): Paralyzing Touch lowers Quickness by the being's Essence for
    // 2D6 minutes (touches stack; at Quickness 0 the victim is paralysed), instead of holding for some Combat Turns.
    const drain = successes > 0 && fx.special === 'paralysis' && RULES.BOOK_V78.paralysis.mode === 'drain';
    // v0.61.0: paralysis, petrification and binding hold their target (MAGIC_V61.holdPowers).
    const hold = successes > 0 && fx.special && !drain ? holdEffect(fx.special, { force: fx.force ?? 0, successes }) : null;
    const sum = sumBundles([base, special, ...(hold?.armorBonus ? [{ ballistic: hold.armorBonus, impact: hold.armorBonus }] : []),
      ...(drain ? [{ attributes: { quickness: -Math.max(0, Math.floor(Number(fx.essence ?? fx.force ?? 0))) } }] : [])]);
    const combat: any = (globalThis as any).game?.combat;
    const until = drain ? effectEnds({ round: combat?.started ? Number(combat.round ?? 0) : null, worldTime: sysNow(), seconds: Math.max(1, Number(fx.minutes ?? 7)) * 60, combatId: combat?.started ? String(combat.id ?? '') : null }) : null;
    return { ...sum, attributes: sum.attributes as Record<string, number>, id, fromUuid, fromName, name: fx.name, kind: fx.kind ?? 'power', successes, spec: fx, ...(fx.special ? { special: fx.special } : {}), ...(fx.permanent ? { permanent: true } : {}),
      ...(hold ? { status: hold.status, holdTurns: hold.turns, ...(hold.breakTest ? { breakTn: hold.breakTest.tn } : {}) } : {}),
      ...(until ? { until } : {}) };
  }

  /** v0.56.0: TN on attacks and spells against these targets from effects on them (Guard): the highest counts. */
  static attackedMods(targets: any[]): TargetNumberModifier[] {
    let best = 0, who = '';
    for (const t of targets ?? []) {
      const v = Number(t?.system?.derived?.effectMods?.attackedTn ?? 0);
      if (v > best) { best = v; who = t.name; }
    }
    return best > 0 ? [{ label: tx('SR2E.Card.Mod.guarded', { who }), value: best }] : [];
  }

  /** v0.50.0: names of targets the caster's token has no line of sight to (walls). */
  #unseenTargets(list: any[]): string[] {
    const from = SR2Actor.tokenFor(this);
    // v0.71.0 (R12): an invisibility spell this caster hasn't seen through hides its subject as a wall would.
    const hidden = (t: any) => RULES.FIXES_V71.invisibilityEverywhere && t !== this && typeof t?.concealmentFor === 'function'
      && livingConcealment(this.visionNow(), t.concealmentFor(this).filter((c: any) => ['invisibility', 'improvedInvisibility'].includes(c.kind))).blind;
    return list.filter((t) => {
      if (hidden(t)) return true;
      if (!from) return false;
      const to = SR2Actor.tokenFor(t); return to && to !== from && lineOfSight(from, to) === false;
    }).map((t) => t.name);
  }

  /**
   * v0.71.0 (R12): before acting on them, this actor resists each invisibility spell on these once (as Perceive
   * and the Attack dialog already did); what it sees through stops hiding them from it.
   */
  async spotInvisible(list: any[]): Promise<void> {
    if (!RULES.FIXES_V71.invisibilityEverywhere) return;
    // Only someone with eyes (and Intelligence) resists; a client that doesn't own it keeps the result in memory.
    if (this.type === 'vehicle' || this.type === 'ic' || !this.sys.attributes) return;
    for (const t of list) if (t && t !== this) { try { await this.seeThroughInvisibility(t); } catch (err) { console.warn('sr2e | see through invisibility', err); } }
  }

  /**
   * v0.50.0: light, smoke and weather on a spell (RULES.TN_AUTO.magic.environment): 'elemental' spells only
   * (they work like ranged attacks), 'all' spells with a target, or 'off'. By the caster's eyes, at the target.
   */
  #spellEnvironment(elemental: boolean, target: any): TargetNumberModifier[] {
    const env = RULES.TN_AUTO.magic.environment;
    const blinded = this.blindMods('spell')[0] ?? null;
    if (!target || env === 'off' || (env === 'elemental' && !elemental)) return blinded ? [blinded] : [];
    const s = this.sightTo(target);
    // Blinded and the light, smoke and weather are one problem: the caster who can't see takes Blinded only.
    return attackVisibility({ light: lightModifier(s.light, s.vision), smoke: smokeLook(s.smoke.kind, s.vision, s.smoke.source), weather: s.weather, blinded });
  }

  /**
   * v0.50.0: the Cast dialog's preview: the spell's base TN against these targets (healing: the patient's
   * Essence; resisted: the highest resisting attribute; vehicles: Object Resistance) and what it finds by itself.
   */
  spellPreview(spell: any, opts: { targetUuids?: string[] } = {}): { base: number; baseLabel: string; modifiers: TargetNumberModifier[]; unseen: string[] } {
    const sp = spell.system;
    const heals = sp.category === 'health' && Boolean(sp.heals);
    const elemental = Boolean(sp.elemental) && !heals;
    const resist: AttributeKey | null = elemental ? null : sp.category === 'combat' ? spellResistAttribute(sp.spellType) : !heals && sp.resist && sp.resist !== 'none' ? (sp.resist as AttributeKey) : null;
    const all = (opts.targetUuids ?? []).map((u) => fromUuidSync(u) as any).filter(Boolean);
    const people = all.filter((t) => t.type !== 'vehicle' && t.system?.attributes);
    const vehicles = all.filter((t) => t.type === 'vehicle');
    let base = Number(sp.targetNumber ?? 4);
    let baseLabel = tx('SR2E.Text.Actor.spellTn');
    if (heals) { const p = people[0] ?? this; base = healingTargetNumber(p.system.derived?.essence ?? 6, sp.targetNumber); baseLabel = tx('SR2E.Text.Actor.sEssence', { name: p.name }); }
    else if (resist && people.length) {
      base = areaTargetNumber(people.map((t) => t.system.attributes[resist]?.total ?? 0));
      baseLabel = people.length === 1 ? tx('SR2E.Text.Actor.sAttribute', { name: people[0].name, attribute: cap(resist) }) : `${RULES.MAGIC.areaTn} ${cap(resist)}`;
    }
    if (vehicles.length && !elemental) {
      const vtn = Math.max(...vehicles.map((v) => spellVsVehicle({ spellType: sp.spellType, objectResistance: v.system?.objectResistance }).tn ?? 0));
      // As castSpell: the higher of the two, or Object Resistance alone when nobody living resists.
      if ((resist && !people.length) || vtn > base) { base = vtn; baseLabel = tx('SR2E.Text.Actor.objectResistance'); }
    }
    const mods = this.#testModifiers({ magical: true, pool: 'spell', sightHandled: true, modifiers: this.#spellEnvironment(elemental, people[0] ?? vehicles[0] ?? null) });
    return { base, baseLabel, modifiers: mods, unseen: this.#unseenTargets(all) };
  }

  /** Anchoring: store a spell to release later (no roll now). */
  async #anchorSpell(spell: any, force: number, trigger: string): Promise<null> {
    await this.#anchorSpellNow(spell, force, trigger);
    return null;
  }

  /** The anchoring itself; true when it was done (the approval queue reads this). */
  async #anchorSpellNow(spell: any, force: number, trigger: string): Promise<boolean> {
    if (!this.initiate.techniques.includes('anchoring')) {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.doesNotKnowTheAnchoringMetamagic', { name: escHtml(this.name) }));
      return false;
    }
    const f = clampForce(force, spell.system.learnedForce);
    // v0.72.0 (O21): anchoring costs Good Karma by Force, like quickening (MAGIC_V72.anchoring). VERIFY
    const cost = anchoringKarma(f);
    const good = Number(this.sys.karma?.good ?? 0);
    if (cost > good) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.anchoringCostsGoodKarmaHas', { spellName: escHtml(spell.name), cost, name: escHtml(this.name), good })); return false; }
    if (cost && approvalNeeded(this)) { await fileRequest(this, { kind: 'improve', label: tx('SR2E.Text.Actor.anchorForce', { name: spell.name, force: f }), karma: cost, data: { method: 'anchorSpell', args: [spell.id ?? '', f, trigger ?? ''] } }); return false; }
    await this.update({ 'system.anchored': [...(this.sys.anchored ?? []), { spellId: spell.id ?? '', spellName: spell.name, force: f, trigger: trigger ?? '', karma: cost }],
      ...(cost ? { 'system.karma.good': good - cost, 'system.ledger': this.#ledgerWith({ kind: 'karma', amount: -cost, reason: tx('SR2E.Text.Actor.anchoredForce', { name: spell.name, force: f }) }) } : {}) });
    await ChatMessage.create({
      speaker: ChatMessage.getSpeaker({ actor: this }),
      content: `<p><strong>${escText(this.name)}</strong> ${(cost ? tx('SR2E.Card.Actor.anchorsForceItIsCastWithWithForGoodKarma', { spellName: escText(spell.name), f, part2: trigger ? `${tx('SR2E.Card.Actor.toTriggerWhen')} <em>${escText(trigger)}</em>` : '', cost }) : tx('SR2E.Card.Actor.anchorsForceItIsCastWithPlain', { spellName: escText(spell.name), f, part2: trigger ? `${tx('SR2E.Card.Actor.toTriggerWhen')} <em>${escText(trigger)}</em>` : '' }))}</p>`,
    });
    return true;
  }

  /** v0.72.0 (O21): the ally spirit this magician may teach (theirs: kind ally, summoned by them), else null with a warning. */
  #myAlly(allyUuid: string): any | null {
    const ally: any = allyUuid ? fromUuidSync(allyUuid) : null;
    if (!RULES.MAGIC_V72.ally.enabled) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.allyAbilitiesAreSwitchedOffHouse')); return null; }
    if (!ally || ally.type !== 'spirit' || ally.system?.spiritKind !== 'ally' || ally.system?.summonerUuid !== this.uuid) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.thatIsNotSAlly', { name: escHtml(this.name) })); return null; }
    if (!canWriteNow(ally)) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.onlyTheGmOrSOwner', { allyName: escHtml(ally.name) })); return null; }
    return ally;
  }

  /** v0.72.0 (O21): teach the ally one of this magician's spells for Good Karma (MAGIC_V72.ally.spellKarmaPerForce). VERIFY */
  async teachAlly(allyUuid: string, spellId: string): Promise<boolean> {
    const ally = this.#myAlly(allyUuid);
    const spell: any = this.items.get(spellId);
    if (!ally) return false;
    if (!spell || spell.type !== 'spell') { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.doesnTKnowThatSpell', { name: escHtml(this.name) })); return false; }
    if ([...ally.items].some((i: any) => i.type === 'spell' && i.name === spell.name)) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.alreadyKnows', { allyName: escHtml(ally.name), spellName: escHtml(spell.name) })); return false; }
    const cost = allySpellKarma(Number(spell.system?.learnedForce ?? 1));
    const good = Number(this.sys.karma?.good ?? 0);
    if (cost > good) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.teachingCostsGoodKarmaHas', { spellName: escHtml(spell.name), cost, name: escHtml(this.name), good })); return false; }
    if (cost && approvalNeeded(this)) { await fileRequest(this, { kind: 'improve', label: tx('SR2E.Text.Actor.teach', { allyName: ally.name, spellName: spell.name }), karma: cost, data: { method: 'teachAlly', args: [allyUuid, spellId] } }); return false; }
    const data = spell.toObject(); delete data._id;
    await ally.createEmbeddedDocuments('Item', [data]);
    if (cost) await this.update({ 'system.karma.good': good - cost, 'system.ledger': this.#ledgerWith({ kind: 'karma', amount: -cost, reason: tx('SR2E.Text.Actor.taught', { allyName: ally.name, spellName: spell.name }) }) });
    await ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor: this }), content: `<p><strong>${escText(this.name)}</strong> ${(cost ? tx('SR2E.Card.Actor.teachesWithForGoodKarma', { allyName: escText(ally.name), spellName: escText(spell.name), cost }) : tx('SR2E.Card.Actor.teachesPlain', { allyName: escText(ally.name), spellName: escText(spell.name) }))}</p>` });
    return true;
  }

  /** v0.72.0 (O21): give the ally an ability (sense link, astral gateway) for Good Karma (MAGIC_V72.ally.abilities). VERIFY */
  async buyAllyAbility(allyUuid: string, id: string): Promise<boolean> {
    const ally = this.#myAlly(allyUuid);
    const ab = allyAbility(id);
    if (!ally) return false;
    if (!ab) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.unknownAllyAbility')); return false; }
    const have = (ally.getFlag?.(SYSTEM_ID, 'allyAbilities') ?? {}) as Record<string, boolean>;
    if (have[ab.id]) { ui.notifications?.info?.(tx('SR2E.Notify.Actor.alreadyHas', { allyName: escHtml(ally.name), abLabel: escHtml(ab.label) })); return false; }
    const good = Number(this.sys.karma?.good ?? 0);
    if (ab.karma > good) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.costsGoodKarmaHas', { abLabel: escHtml(ab.label), abKarma: ab.karma, name: escHtml(this.name), good })); return false; }
    if (ab.karma && approvalNeeded(this)) { await fileRequest(this, { kind: 'improve', label: `${ally.name}: ${ab.label}`, karma: ab.karma, data: { method: 'buyAllyAbility', args: [allyUuid, id] } }); return false; }
    await ally.setFlag(SYSTEM_ID, 'allyAbilities', { ...have, [ab.id]: true });
    if (ab.karma) await this.update({ 'system.karma.good': good - ab.karma, 'system.ledger': this.#ledgerWith({ kind: 'karma', amount: -ab.karma, reason: `${ally.name}: ${ab.label}` }) });
    await ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor: this }), content: `<p><strong>${escText(ally.name)}</strong> ${tx('SR2E.Card.Actor.gains', { abLabel: escText(ab.label), part: ab.karma ? tx('SR2E.Card.Actor.goodKarma', { abKarma: ab.karma }) : '' })}</p>` });
    return true;
  }

  /** v0.72.0 (O21): switch the sense link with an ally on or off (shown as a status; the GM rules what is perceived). */
  async setSenseLink(allyUuid: string, on: boolean): Promise<void> {
    const ally: any = allyUuid ? fromUuidSync(allyUuid) : null;
    // Review fix: only this magician's own ally.
    if (on && (!ally || ally.type !== 'spirit' || ally.system?.spiritKind !== 'ally' || ally.system?.summonerUuid !== this.uuid)) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.thatIsNotSAlly', { name: escHtml(this.name) })); return; }
    const abilities = (ally?.getFlag?.(SYSTEM_ID, 'allyAbilities') ?? {}) as Record<string, boolean>;
    if (on && !senseLinkSource({ linkOn: true, allyUuid, allyAbilities: abilities })) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.hasNoSenseLink', { allyName: escHtml(ally?.name ?? tx('SR2E.Notify.Actor.theAlly')) })); return; }
    await this.setFlag(SYSTEM_ID, 'senseLink', { allyUuid, on: Boolean(on) });
    await ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor: this }), content: `<p><strong>${escText(this.name)}</strong> ${on ? tx('SR2E.Card.Actor.usesSSenses', { allyName: escText(ally?.name ?? tx('SR2E.Card.Actor.theAlly')) }) : tx('SR2E.Card.Actor.isBackInTheirOwnSenses')}.</p>` });
  }

  /** v0.72.0 (O21): anchor a known spell by id (the approval queue's entry point; the sheet goes through castSpell). */
  async anchorSpell(spellId: string, force: number, trigger = ''): Promise<boolean> {
    const spell: any = this.items.get(spellId);
    if (!spell || spell.type !== 'spell') { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.doesnTKnowThatSpellAny', { name: escHtml(this.name) })); return false; }
    return this.#anchorSpellNow(spell, force, trigger);
  }

  /** Release an anchored spell: it is cast now (the sheet asks for targets). */
  async releaseAnchored(index: number, opts: { targetUuid?: string | null; targetUuids?: string[] } = {}): Promise<SuccessTestResult | null> {
    const list = [...(this.sys.anchored ?? [])];
    const entry = list[index];
    if (!entry) return null;
    const spell: any = this.items.get?.(entry.spellId) ?? [...this.items].find((i: any) => i.type === 'spell' && i.name === entry.spellName);
    if (!spell) {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.isNoLongerKnown', { entrySpellName: escHtml(entry.spellName) }));
      return null;
    }
    // v0.81.0 (D2-1): cast first; the anchor goes only when the spell is cast (a refused cast keeps it), once.
    const key = `${this.uuid}:${entry.spellId ?? entry.spellName}:${entry.trigger ?? ''}`;
    if (SR2Actor.#anchorBusy.has(key)) return null;
    SR2Actor.#anchorBusy.add(key);
    try {
      const r = await this.castSpell(spell, { force: entry.force, ...opts });
      if (r) {
        const now = [...(this.sys.anchored ?? [])];
        const j = now.findIndex((e: any) => e.spellId === entry.spellId && e.spellName === entry.spellName && e.trigger === entry.trigger && e.force === entry.force);
        if (j >= 0) { now.splice(j, 1); await this.update({ 'system.anchored': now }); }
      }
      return r;
    } finally { SR2Actor.#anchorBusy.delete(key); }
  }

  /** Anchored spells being released on this client (a double click releases one once). */
  static #anchorBusy = new Set<string>();

  /** Let one of this magician's elementals sustain a spell (costs a service); no TN penalty. */
  async sustainWithElemental(index: number, spiritUuid: string): Promise<boolean> {
    const list = this.sustained();
    const entry = list[index];
    const spirit: any = await fromUuid(spiritUuid);
    if (!entry || !spirit) return false;
    if (spirit.system?.spiritKind !== 'elemental' || spirit.system.summonerUuid !== this.uuid) {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.isNotOneOfSElementals2', { spiritName: escHtml(spirit.name), name: escHtml(this.name) }));
      return false;
    }
    // v0.54.0: the same spells it could aid (RULES.MAGIC_EXTRA.elementalMatch): the category is the
    // sustained entry's; the element is the spell's on the sheet (found by name).
    const spellItem: any = [...this.items].find((i: any) => i.type === 'spell' && i.name === entry.spellName);
    const served = { element: String(spellItem?.system?.element ?? ''), category: String(entry.category || spellItem?.system?.category || '') };
    if (!elementalServes(spirit.system.element ?? '', served)) {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.canOnlySustainIs', { spiritName: escHtml(spirit.name), spiritElement: escHtml(spirit.system.element || tx('SR2E.Notify.Actor.noElement')), elementalServesLabel: escHtml(elementalServesLabel(spirit.system.element ?? '')), entrySpellName: escHtml(entry.spellName), part: RULES.MAGIC_EXTRA.elementalMatch === 'element' ? escHtml(served.element || tx('SR2E.Notify.Actor.ofNoElement')) : `${escHtml(served.category || tx('SR2E.Notify.Actor.ofNoCategory'))}` }));
      return false;
    }
    if (RULES.MAGIC_EXTRA.elementalSustain.costsService) {
      if ((spirit.system.services ?? 0) <= 0) {
        ui.notifications?.warn?.(tx('SR2E.Notify.Actor.owesNoServices2', { spiritName: escHtml(spirit.name) }));
        return false;
      }
      await spirit.update({ 'system.services': spirit.system.services - 1 });
    }
    // It holds the spell for a limited time (v0.39.0).
    const now = sysNow();
    const until = elementalSustainUntil(now, Number(spirit.system.force ?? 1));
    list[index] = { ...entry, spiritUuid: spirit.uuid, until } as any;
    await this.update({ 'system.sustaining': list });
    await ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor: this }), content: `<p><strong>${escText(spirit.name)}</strong> ${(until >= 0 ? tx('SR2E.Card.Actor.sustainsForWithForUpTo', { entrySpellName: escText(entry.spellName), name: escText(this.name), hoursLabel: escText(hoursLabel((until - now) / 3600)) }) : tx('SR2E.Card.Actor.sustainsForPlain', { entrySpellName: escText(entry.spellName), name: escText(this.name) }))}</p>` });
    return true;
  }

  /** Raise (or learn) a spell's Force for Good Karma. */
  async raiseSpellForce(spell: any, newForce: number, o: { formulaId?: string; teachMessage?: string } = {}): Promise<boolean> {
    // v0.65.0: one study of a spell at a time (the Force rises only when it's done).
    if (this.projects().some((p) => p.kind === 'learn' && (p.effect.updates?.some((u) => u.itemId === spell?.id) || p.subject === spell?.name || (p.subject === undefined && p.label.startsWith(`Learning ${spell?.name} at`))))) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.isAlreadyStudying', { name: escHtml(this.name), spellName: escHtml(spell?.name) })); return false; }
    // v0.91.8 (RULES.FORMULA_V918.raise): a higher Force needs a formula of that Force (or a teacher who knows it).
    // v0.91.8: a teacher's help is read again from their card (`o.teachMessage`), a formula item from the sheet.
    const help = o.teachMessage ? await this.#teachHelp(o.teachMessage, String(spell?.name ?? ''), newForce) : null;
    if (o.teachMessage && !help) return false;
    const src = help ? { from: help.from, foreign: help.foreign } : o.formulaId ? this.#formulaItemSource(o.formulaId, String(spell?.name ?? ''), newForce) : this.#formulaSource(spell?.name, newForce, raiseNeedsFormula());
    if (!src) return false;
    if (newForce <= Number(spell?.system?.learnedForce ?? 0)) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.isAlreadyForce', { spellName: escHtml(spell.name), spellLearnedForce: escHtml(spell.system.learnedForce) })); return false; }
    // v0.56.0: a learning test (RULES.MAGIC_V56.learning); Karma is paid on success.
    if (RULES.MAGIC_V56.learning.enabled) {
      if (approvalNeeded(this)) { await fileRequest(this, { kind: 'spellForce', label: tx('SR2E.Text.Actor.forceLearningTest', { name: spell.name, from: spell.system.learnedForce, to: newForce }), karma: spellKarmaCost(newForce), data: { method: 'raiseSpellForce', args: [spell.id, newForce, o] } }); return false; }
      if (help && !(await this.#payTeacher(help.fee, spell.name, newForce))) return false;
      const r = await this.learnSpellTest({ name: spell.name, force: newForce, spellId: spell.id, ...(src.from ? { from: src.from } : {}), foreign: src.foreign, extraDice: help?.dice ?? 0 });
      return Boolean(r && r.successes > 0);
    }
    const cost = spellKarmaCost(newForce);
    const good = (this.sys.karma?.good as number | undefined) ?? 0;
    if (newForce <= spell.system.learnedForce) {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.isAlreadyForce', { spellName: escHtml(spell.name), spellLearnedForce: escHtml(spell.system.learnedForce) }));
      return false;
    }
    if (good < cost) {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.forceCostsGoodKarmaHas', { newForce, spellName: escHtml(spell.name), cost, name: escHtml(this.name), good }));
      return false;
    }
    if (approvalNeeded(this)) { await fileRequest(this, { kind: 'spellForce', label: tx('SR2E.Text.Actor.forceFromTo', { name: spell.name, from: spell.system.learnedForce, to: newForce }), karma: cost, data: { method: 'raiseSpellForce', args: [spell.id, newForce, o] } }); return false; }
    if (help && !(await this.#payTeacher(help.fee, spell.name, newForce))) return false;
    const from = Number(spell.system.learnedForce ?? 0);
    // v0.65.0: the study takes Force × days per Force (no test to shorten it): the Force rises when it has passed.
    if (this.waitsFor('magic')) {
      await this.update({ 'system.karma.good': good - cost, 'system.ledger': this.#ledgerWith({ kind: 'karma', amount: -cost, reason: tx('SR2E.Text.Actor.forceStudying', { name: spell.name, from, to: newForce }) }) });
      await this.startProject({ kind: 'learn', area: 'magic', subject: spell.name, label: tx('SR2E.Card.Actor.learningAtForce', { name: spell.name, force: newForce }), hours: Number(foreignAdjust(learningPlan(newForce, 1), src.foreign).days ?? newForce) * 24, paid: { karma: cost }, effect: { updates: [{ itemId: spell.id, changes: [['system.learnedForce', newForce]] }] } });
      return true;
    }
    await spell.update({ 'system.learnedForce': newForce });
    // v0.64.0: with a ledger line (it had none).
    await this.update({ 'system.karma.good': good - cost, 'system.ledger': this.#ledgerWith({ kind: 'karma', amount: -cost, reason: `${spell.name} Force ${from} → ${newForce}` }) });
    await ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor: this }), content: `<p><strong>${escText(this.name)}</strong> ${tx('SR2E.Card.Actor.learnsAtForceForGoodKarma', { spellName: escText(spell.name), newForce, cost })}</p>` });
    return true;
  }

  /**
   * v0.56.0: the learning test (RULES.MAGIC_V56.learning): the learning skill vs the Force; it takes
   * Force × daysPerForce days ÷ successes and a sorcery library (hermetic) or lodge of the totem (shaman)
   * of at least the Force. Good Karma is paid, and the spell written, on success only.
   */
  /** The learning test's site problem at `force` (no library or lodge, or too low a rating); '' when fine or off. */
  #learnSiteProblem(force: number): string {
    if (RULES.MAGIC_V56.learning.site === 'off') return '';
    const shaman = isShamanic(this.tradition);
    const site = bestSite(this.magicSites(), shaman ? 'lodge' : 'library', shaman ? this.sys.totem?.name ?? '' : 'sorcery');
    const what = shaman ? tx('SR2E.Card.Actor.aLodge', { part: this.sys.totem?.name ? ` (${this.sys.totem.name})` : '' }) : tx('SR2E.Card.Actor.aSorceryLibrary');
    return !site ? what : site.rating < force ? tx('SR2E.Card.Actor.ofRatingOrMoreIs', { what, force, siteName: site.name, siteRating: site.rating }) : '';
  }

  async learnSpellTest(o: { name: string; force: number; spellId?: string; system?: Record<string, unknown>; from?: string; poolDice?: number; foreign?: boolean; extraDice?: number }): Promise<SuccessTestResult | null> {
    const L = RULES.MAGIC_V56.learning;
    const force = Math.max(1, Math.floor(Number(o.force) || 1));
    const cost = spellKarmaCost(force);
    const good = Number(this.sys.karma?.good ?? 0);
    if (good < cost) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.learningAtForceCostsGoodKarma', { name: escHtml(o.name), force, cost, name2: escHtml(this.name), good })); return null; }
    const skill = this.findSkill(L.skill);
    if (!skill || !((skill.system?.rating ?? 0) > 0)) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.needsToLearnSpells', { name: escHtml(this.name), lSkill: L.skill })); return null; }
    const problem = this.#learnSiteProblem(force);
    if (problem) {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.needsToLearnAtForce', { name: escHtml(this.name), problem: escHtml(problem), name2: escHtml(o.name), force, part: L.site === 'block' ? '' : tx('SR2E.Notify.Actor.allowedTheHouseRuleOnlyWarns') }));
      if (L.site === 'block') return null;
    }
    // v0.91.8 (RULES.FORMULA_V918.foreign): the other tradition's formula or teacher: a higher TN and more time.
    const foreign = Boolean(o.foreign);
    const plan = foreignAdjust(learningPlan(force, 0), foreign);
    // v0.80.0 (RULES.URR_V80.magLearning 'theory', URR): Sorcery + Magical Theory.
    const theory = urrMagLearnExtraDice(Number(this.findSkill('Magical Theory')?.system?.rating ?? 0));
    // v0.91.8 (RULES.FORMULA_V918.teacher): a teacher's successes as extra dice.
    // Capped (a request carries the number): no teacher's Sorcery goes past 12.
    const extra = Math.min(12, Math.max(0, Math.floor(Number(o.extraDice ?? 0)) || 0));
    const parts = `${theory ? tx('SR2E.Card.Actor.magicalTheory', { theory }) : ''}${extra ? tx('SR2E.Card.Formula.teacherDice', { dice: extra }) : ''}${foreign ? tx('SR2E.Card.Formula.otherTradition') : ''}`;
    return this.#runTest(tx('SR2E.Card.Actor.learnAtForceVsSuccessesGood', { name: o.name, force, skillName: skill.name, part: parts, planTn: plan.tn, plural: plural(plan.baseDays, 'day'), cost }), Number(skill.system.rating) + theory + extra,
      { targetNumber: plan.tn, poolDice: 0, pool: 'spell' },
      { kind: 'learn', learn: { name: o.name, force, cost, ...(o.spellId ? { spellId: o.spellId } : {}), ...(o.system ? { system: { ...o.system } } : {}), ...(o.from ? { from: o.from } : {}), ...(foreign ? { foreign: true } : {}), ...(extra ? { extraDice: extra } : {}) } });
  }

  async #resolveLearn(snap: TestSnapshot): Promise<Resolved> {
    const l = snap.learn!;
    const plan = foreignAdjust(learningPlan(l.force, snap.successes), Boolean(l.foreign));
    if (snap.successes <= 0 && l.projectId) {
      const note = await this.dropProjectOnFailure(l.projectId);
      return { html: `<p><strong>${tx('SR2E.Card.Actor.isNotLearnedThisTime', { name: escText(l.name) })}</strong>${note}</p>`, flags: {}, snap: { ...snap, learn: { ...l, applied: false, projectId: undefined } } };
    }
    if (snap.successes <= 0) return { html: `<p><strong>${tx('SR2E.Card.Actor.isNotLearnedThisTime2', { name: escText(l.name) })}</strong>${tx('SR2E.Card.Actor.noKarmaIsSpentTryAgain', { part: l.applied ? ` <em>${tx('SR2E.Card.Actor.itWasAlreadyLearnedFromAn')}</em>` : '' })}</p>`, flags: {}, snap };
    const days = `<strong>${escText(plural(plan.days ?? 0, 'day'))}</strong> ${tx('SR2E.Card.Actor.ofStudy', { planBaseDays: plan.baseDays, successes: snap.successes })}`;
    if (l.applied) {
      // v0.65.0: a re-roll after the study started changes how long it takes.
      const p = await this.retimeProject(l.projectId, Number(plan.days ?? 0) * 24);
      return { html: `<p><strong>${tx('SR2E.Card.Actor.atForce', { name: escText(this.name), part: p ? tx('SR2E.Card.Actor.studies') : tx('SR2E.Card.Actor.learns'), name2: escText(l.name), force: l.force })}</strong> ${tx('SR2E.Card.Actor.in2', { days })}</p>`, flags: {}, snap };
    }
    const good = Number(this.sys.karma?.good ?? 0);
    if (good < l.cost) return { html: `<p><em>${tx('SR2E.Card.Actor.noLongerHasTheGoodKarma', { name: escText(this.name), cost: l.cost, name2: escText(l.name) })}</em></p>`, flags: {}, snap };
    const spell: any = l.spellId ? this.items.get?.(l.spellId) : null;
    const known: any = spell ?? [...this.items].find((i: any) => i.type === 'spell' && i.name === l.name);
    if (known && Number(known.system?.learnedForce ?? 0) >= l.force) return { html: `<p><em>${tx('SR2E.Card.Actor.alreadyKnowsAtForceNothingMore', { name: escText(this.name), name2: escText(l.name), knownLearnedForce: escText(known.system.learnedForce) })}</em></p>`, flags: {}, snap: { ...snap, learn: { ...l, applied: true } } };
    // v0.65.0: the study takes its days: the Karma is paid now and the spell is known when they have passed.
    if (this.waitsFor('magic')) {
      await this.update({ 'system.karma.good': good - l.cost, 'system.ledger': this.#ledgerWith({ kind: 'karma', amount: -l.cost, reason: tx('SR2E.Text.Actor.studyingForce', { name: l.name, force: l.force }) }) });
      const effect: ProjectEffect = spell ? { updates: [{ itemId: spell.id, changes: [['system.learnedForce', l.force]] }] } : { creates: [{ name: l.name, type: 'spell', system: { ...(l.system ?? {}), learnedForce: l.force } }] };
      const pr = await this.startProject({ kind: 'learn', area: 'magic', subject: l.name, label: tx('SR2E.Card.Actor.learningAtForce', { name: l.name, force: l.force }), hours: Number(plan.days ?? 0) * 24, paid: { karma: l.cost }, effect });
      return { html: `<p><strong>${tx('SR2E.Card.Actor.studiesAtForce', { name: escText(this.name), name2: escText(l.name), force: l.force })}</strong>${(l.from ? tx('SR2E.Card.Actor.forGoodKarmaPaidNowTheWithFrom', { days, cost: l.cost, from: escText(l.from) }) : tx('SR2E.Card.Actor.forGoodKarmaPaidNowThePlain', { days, cost: l.cost }))}</p>`, flags: {}, snap: { ...snap, learn: { ...l, applied: true, projectId: pr.id } } };
    }
    if (spell) await spell.update({ 'system.learnedForce': l.force });
    else if (![...this.items].some((i: any) => i.type === 'spell' && i.name === l.name)) await this.createEmbeddedDocuments('Item', [{ name: l.name, type: 'spell', system: { ...(l.system ?? {}), learnedForce: l.force } }]);
    await this.update({ 'system.karma.good': good - l.cost, 'system.ledger': this.#ledgerWith({ kind: 'karma', amount: -l.cost, reason: tx('SR2E.Text.Actor.learnedForce', { name: l.name, force: l.force }) }) });
    return { html: `<p><strong>${tx('SR2E.Card.Actor.learnsAtForce', { name: escText(this.name), name2: escText(l.name), force: l.force })}</strong>${(l.from ? tx('SR2E.Card.Actor.inForGoodKarmaWithFrom', { days, cost: l.cost, from: escText(l.from) }) : tx('SR2E.Card.Actor.inForGoodKarmaPlain', { days, cost: l.cost }))}</p>`, flags: {}, snap: { ...snap, learn: { ...l, applied: true } } };
  }

  /**
   * v0.56.0: raise a ward by ritual (RULES.MAGIC_V56.ward): the leader's skill plus team dice vs the Force;
   * Force × hoursPerForce hours ÷ successes; materials from nuyen; every member resists drain. Any success
   * makes a ward (a barrier actor at the Force).
   */
  async raiseWardRitual(o: { force: number; name?: string; teamUuids?: string[]; poolDice?: number; drainPoolDice?: number; payMaterials?: boolean }): Promise<SuccessTestResult | null> {
    if (!this.canAct('conjure')) return null;
    const W = RULES.MAGIC_V56.ward;
    const force = Math.max(1, Math.floor(Number(o.force) || 1));
    const skill = this.findSkill(W.skill);
    if (!skill || !((skill.system?.rating ?? 0) > 0) || !(Number(this.sys.derived?.magic ?? 0) > 0)) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.needsMagicAndToRaiseA', { name: escHtml(this.name), wSkill: W.skill })); return null; }
    const team: any[] = [];
    for (const u of o.teamUuids ?? []) { const m: any = await fromUuid(u); if (m && m.uuid !== this.uuid && m.findSkill) team.push(m); }
    // v0.80.0 (RULES.URR_V80.magWardMaxForce, URR): a ward's Force is at most 2 × the team's combined Magic.
    const wf = urrMagWardForceProblem(force, [this, ...team].reduce((s: number, m: any) => s + Number(m.system?.derived?.magic ?? 0), 0));
    if (wf) { ui.notifications?.warn?.(wf); return null; }
    const plan = wardPlan(force, 0);
    if (plan.nuyen > 0 && o.payMaterials !== false && !(await this.adjustNuyen(-plan.nuyen, tx('SR2E.Text.Actor.wardMaterialsForce', { force })))) return null;
    const teamDice = team.length ? ritualTeamDice(team.map((m) => m.findSkill?.(W.skill)?.system?.rating ?? 0)) : 0;
    const name = (o.name ?? '').trim() || `Ward (Force ${force})`;
    const result = await this.#runTest(tx('SR2E.Card.Actor.raiseTnSuccesses', { name, skillName: skill.name, planTn: plan.tn, part: teamDice ? tx('SR2E.Card.Actor.teamOf', { value: team.length + 1, teamDice }) : '', plural: plural(plan.baseHours, 'hour'), part2: plan.nuyen && o.payMaterials !== false ? tx('SR2E.Card.Actor.materials', { planNuyen: plan.nuyen }) : '' }),
      Math.max(0, Number(skill.system.rating) + teamDice),
      { targetNumber: plan.tn, poolDice: o.poolDice ?? 0, pool: 'spell', magical: true },
      { kind: 'ward', ward: { force, name, team: team.length, nuyen: o.payMaterials === false ? 0 : plan.nuyen } });
    await this.leaveSignature('ritual', tx('SR2E.Text.Actor.raising', { name }), force);
    await this.wardDrain(force, o.drainPoolDice ?? 0, Number(result?.successes ?? 0));
    for (const m of team) if (typeof m.wardDrain === 'function') await this.#memberDrain(m, tx('SR2E.Card.Actor.theWardForce', { force }), () => m.wardDrain(force, 0, Number(result?.successes ?? 0)), (() => { const wp = wardPlan(force, Number(result?.successes ?? 0)); return tx('SR2E.Card.Actor.willpowerVsTnDrain2', { wpDrainTn: wp.drainTn, wpDrainLevel: wp.drainLevel }); })());
    return result;
  }

  /** v0.56.0: a ward ritual's drain for one member. */
  async wardDrain(force: number, poolDice = 0, successes = 0): Promise<void> {
    const plan = wardPlan(force, successes);
    // v0.80.0 (RULES.URR_V80.magWardDrain 'urr', URR): Force + successes, always Stun.
    const urr = urrMagWardDrain(force, successes);
    await this.#drainTest({ label: tx('SR2E.Card.Actor.wardDrain'), attribute: 'willpower', targetNumber: plan.drainTn, level: plan.drainLevel as DamageLevel, type: urr?.type ?? drainDamageType(force, Number(this.sys.derived?.drainMagic ?? this.sys.derived?.magic ?? 0)), poolDice });
  }

  async #resolveWard(snap: TestSnapshot): Promise<Resolved> {
    const w = snap.ward!;
    const plan = wardPlan(w.force, snap.successes);
    if (snap.successes <= 0 && w.projectId) return { html: `<p><strong>${tx('SR2E.Card.Actor.theWardFailsToRise')}</strong>${await this.dropProjectOnFailure(w.projectId)}</p>`, flags: {}, snap: { ...snap, ward: { ...w, projectId: undefined } } };
    if (snap.successes <= 0) return { html: `<p><strong>${tx('SR2E.Card.Actor.theWardFailsToRise')}</strong>${w.barrierUuid ? ` <em>${tx('SR2E.Card.Actor.theWardFromAnEarlierRoll')}</em>` : ''}</p>`, flags: {}, snap };
    const time = `${tx('SR2E.Card.Actor.after')} <strong>${escText(plural(plan.hours ?? 0, 'hour'))}</strong> (${plan.baseHours} ÷ ${snap.successes})`;
    if (w.projectId) { await this.retimeProject(w.projectId, Number(plan.hours ?? 0)); return { html: `<p><strong>${escText(w.name)}</strong> ${tx('SR2E.Card.Actor.risesUpkeepTabUnderWay', { time })}</p>`, flags: {}, snap }; }
    if (w.barrierUuid || w.pending) return { html: `<p><strong>${escText(w.name)}</strong> ${tx('SR2E.Card.Actor.rises', { time })}</p>`, flags: {}, snap };
    const data = { name: w.name, type: 'barrier', system: { barrierKind: 'ward', rating: w.force, baseRating: w.force } };
    // v0.65.0: the ward rises when the ritual's hours have passed.
    if (this.waitsFor('magic')) {
      const pr = await this.startProject({ kind: 'ward', area: 'magic', label: tx('SR2E.Text.Actor.raising', { name: w.name }), hours: Number(plan.hours ?? 0), effect: { call: { method: 'finishWard', args: [data, w.name] } } });
      return { html: `<p><strong>${escText(w.name)}</strong> ${tx('SR2E.Card.Actor.aForceWardRisesUpkeepTab', { force: w.force, time })}</p>`, flags: {}, snap: { ...snap, ward: { ...w, projectId: pr.id } } };
    }
    const canCreate = canCreateActorNow();
    if (!canCreate) return { html: `<p><strong>${escText(w.name)}</strong> ${tx('SR2E.Card.Actor.rises', { time })} <button type="button" data-sr2e-action="createSpirit">${tx('SR2E.Card.Actor.createWardGm')}</button></p>`, flags: { pendingSpirit: data }, snap: { ...snap, ward: { ...w, pending: true } } };
    const cls: any = (Actor as any).implementation ?? Actor;
    const made: any = await cls.create(data);
    // v0.61.0: a button to draw it on the map (a region carrying the ward).
    return { html: `<p><strong>${escText(w.name)}</strong> ${tx('SR2E.Card.Actor.aForceWardRisesItIs', { force: w.force, time, part: made?.uuid ? ` <button type="button" data-sr2e-action="placeWard">${tx('SR2E.Card.Actor.drawItOnTheMap')}</button>` : '' })}</p>`, flags: made?.uuid ? { wardPlace: { barrierUuid: made.uuid, name: w.name } } : {}, snap: { ...snap, ward: { ...w, barrierUuid: made?.uuid ?? 'made' } } };
  }

  /**
   * v0.56.0: a centering test (Grimoire; RULES.MAGIC_V56.centering 'test'): the character's centering skill
   * vs the TN; each success, up to the grade, comes off the next magical test's wound and sustaining penalties.
   */
  async centeringTest(): Promise<SuccessTestResult | null> {
    if (!this.#knows('centering')) return null;
    const name = String(this.sys.centeringSkill ?? '').trim();
    if (!name) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.hasNoCenteringSkillNamedMagic', { name: escHtml(this.name) })); return null; }
    const skill = this.findSkill(name);
    const d = this.#skillDice(skill, false, null, 'charisma', { skillName: name });
    return this.#runTest(tx('SR2E.Card.Actor.centering', { name, suffix: d.suffix }), d.dice, { targetNumber: RULES.MAGIC_V56.centering.tn, modifiers: d.modifiers }, { kind: 'centering' });
  }

  async #resolveCentering(snap: TestSnapshot): Promise<Resolved> {
    const s = Math.max(0, snap.successes);
    const cap = Math.max(0, this.initiate.grade) * RULES.MAGIC.centeringPerGrade;
    // A Karma re-roll only changes a centering still unused (a used one isn't given back).
    const cur = this.getFlag?.(SYSTEM_ID, 'centered') as { testId?: string } | undefined;
    const fresh = !(snap.rerolls > 0) && !(snap.retargets ?? 0);
    const mine = Boolean(cur && cur.testId && cur.testId === snap.testId);
    try {
      if (fresh || mine) {
        if (s > 0) await this.setFlag(SYSTEM_ID, 'centered', { successes: s, at: fresh ? sysNow() : Number((cur as any)?.at ?? 0), testId: snap.testId ?? '' });
        else await clearFlag(this, 'centered');
      }
    } catch { /* not saved */ }
    if (!fresh && !mine) return { html: `<p><em>${tx('SR2E.Card.Actor.thatCenteringWasAlreadyUsedOr')}</em></p>`, flags: {}, snap };
    return { html: s > 0
      ? `<p><strong>${tx('SR2E.Card.Actor.centered')}</strong> ${tx('SR2E.Card.Actor.upTo')} <strong>${Math.min(s, cap)}</strong> ${tx('SR2E.Card.Actor.offTheWoundAndSustainingPenalties', { name: escText(this.name), centeringWindowSeconds: RULES.MAGIC_V56.centering.windowSeconds })}</p>`
      : `<p><strong>${tx('SR2E.Card.Actor.notCentered')}</strong></p>`, flags: {}, snap };
  }

  /** v0.56.0: an unused centering test's successes still in time, or 0. */
  centeredSuccesses(): number {
    const c = this.getFlag?.(SYSTEM_ID, 'centered') as { successes: number; at: number } | undefined;
    if (!c) return 0;
    const now = sysNow();
    return now - Number(c.at ?? 0) <= RULES.MAGIC_V56.centering.windowSeconds ? Math.max(0, Number(c.successes) || 0) : 0;
  }

  /**
   * Initiate to the next grade for Good Karma, learning a metamagic technique (v0.45.0: with an
   * ordeal and/or in a magical group, each lowering the cost; a library or lodge may be needed).
   */
  async advanceInitiation(technique: string | null = null, o: { ordeal?: string | null; groupId?: string | null; attribute?: string | null; geas?: string | null; deedDone?: boolean } = {}): Promise<boolean> {
    if (!((this.sys.magic as number) > 0)) {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.hasNoMagicToInitiate', { name: escHtml(this.name) }));
      return false;
    }
    // v0.72.0 (O15): adepts and aspected magicians can't learn every technique (MAGIC_V72.metamagicLimits).
    // v0.81.0: the technique becomes a document path (system.metamagic.<technique>): a known technique only.
    if (technique && !(METAMAGIC as readonly string[]).includes(String(technique))) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.thereIsNoMetamagicTechniqueCalled', { name: escHtml(this.name), technique: escHtml(technique) })); return false; }
    if (technique) {
      const mm = metamagicAllowed(String(this.tradition ?? ''), technique);
      if (mm.reason) ui.notifications?.warn?.(`${escHtml(this.name)}: ${escHtml(mm.reason)}${mm.block ? '' : tx('SR2E.Notify.Actor.allowedTheHouseRuleOnlyWarns')}`);
      if (mm.block) return false;
    }
    const grade = (this.sys.initiateGrade as number) + 1;
    // v0.65.0: one initiation at a time (an ordeal under way holds the next grade).
    if (this.projects().some((p) => p.kind === 'initiation')) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.isAlreadyInitiatingUpkeepTabUnder', { name: escHtml(this.name) })); return false; }
    const ordeal = ordealById(o.ordeal ?? null);
    const io = RULES.OCCULT.initiation;
    let group: MagicGroup | null = null;
    if (o.groupId) {
      group = this.myGroups().find((g) => g.id === o.groupId) ?? null;
      if (!group) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.isNotAMemberOfThat', { name: escHtml(this.name) })); return false; }
      if (inBreach(group, this.selfUuids())) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.hasBrokenSStricturesNoGroup', { name: escHtml(this.name), groupName: escHtml(group.name) })); return false; }
    }
    if (ordeal?.effect === 'quest') {
      const q = this.quest();
      if (!q || questStatus(q) !== 'complete') { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.theAstralQuestOrdealNeedsA')); return false; }
    }
    // v0.48.0: the familiar ordeal needs an ally conjured since the last initiation; an oath may need a group.
    const familiar = this.getFlag(SYSTEM_ID, 'familiar') as { allyUuid?: string; allyName?: string; usedForGrade?: number | null } | undefined;
    if (ordeal?.effect === 'familiar' && io.familiar.needsAlly !== 'off' && !familiarReady(familiar)) {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.theFamiliarOrdealNeedsAnAlly', { name: escHtml(this.name), part: io.familiar.needsAlly === 'block' ? '' : tx('SR2E.Notify.Actor.allowedTheHouseRuleOnlyWarns') }));
      if (io.familiar.needsAlly === 'block') return false;
    }
    if (ordeal?.effect === 'oath' && io.oath.needsGroup && !group) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.theOathOrdealIsSwornTo')); return false; }
    const attr = ordeal?.effect === 'attribute' ? (o.attribute ?? '') : '';
    if (ordeal?.effect === 'attribute' && (!ATTRIBUTE_KEYS.includes(attr as AttributeKey) || Number(this.sys.attributes?.[attr]?.base ?? 0) <= 1)) {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.asceticismNeedsAnAttributeWithA'));
      return false;
    }
    const missing = initiationSiteMissing(this.tradition, this.magicSites(), grade, String(this.sys.totem?.name ?? ''));
    if (missing.length) {
      const mode = RULES.OCCULT.initiation.site;
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.needsToInitiateToGrade', { name: escHtml(this.name), missing: escHtml(tList(missing)), grade, part: mode === 'block' ? '' : tx('SR2E.Notify.Actor.allowedTheHouseRuleOnlyWarns') }));
      if (mode === 'block') return false;
    }
    const { cost, multiplier } = initiationCost(grade, { group: Boolean(group), ordeal: Boolean(ordeal) });
    const good = (this.sys.karma?.good as number | undefined) ?? 0;
    if (good < cost) {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.gradeCostsGoodKarmaHas', { grade, cost, name: escHtml(this.name), good }));
      return false;
    }
    // v0.70.0: the request carries its Karma (before, it showed as free in the GM's queue).
    if (approvalNeeded(this)) { await fileRequest(this, { kind: 'improve', label: technique ? tx('SR2E.Text.Actor.initiateToGradeTechnique', { grade, technique }) : tx('SR2E.Text.Actor.initiateToGrade', { grade }), karma: cost, data: { method: 'advanceInitiation', args: [technique, { ...o }] } }); return false; }
    // v0.48.0: a deed waits for the GM to confirm it is done (the Karma is paid then).
    if (ordeal?.effect === 'deed' && io.deed.gmConfirms && !o.deedDone && !Boolean((game as any).user?.isGM)) {
      const pending = { technique, ordeal: o.ordeal ?? null, groupId: o.groupId ?? null, attribute: o.attribute ?? null, geas: o.geas ?? null, grade };
      await this.setFlag(SYSTEM_ID, 'pendingInitiation', pending);
      const gms = [...((game as any).users ?? [])].filter((u: any) => u.isGM).map((u: any) => u.id);
      await ChatMessage.create({
        speaker: ChatMessage.getSpeaker({ actor: this }), whisper: [...new Set([...gms, game.user?.id].filter(Boolean))],
        content: `<p><strong>${escText(this.name)}</strong> ${tx('SR2E.Card.Actor.undertakesADeedToInitiateTo', { grade, cost })}</p><p><button type="button" data-sr2e-action="confirmDeed">${tx('SR2E.Card.Actor.theDeedIsDoneGm')}</button></p>`,
        flags: { [SYSTEM_ID]: { deed: { actorUuid: this.uuid, grade } } },
      });
      return false;
    }
    // v0.48.0: meditation and a thesis are tests; a failure postpones the initiation (no Karma spent).
    let ordealNote = '';
    if (ordeal?.effect === 'meditation' || ordeal?.effect === 'thesis') {
      const rolls: any[] = [];
      let dice: number; let label: string; let tn: number; let mods: TargetNumberModifier[] = [];
      if (ordeal.effect === 'meditation') {
        const at = io.meditation.attribute as AttributeKey;
        dice = Number(this.sys.attributes?.[at]?.total ?? 0);
        tn = meditationTn(grade);
        label = tx('SR2E.Card.Actor.meditationOrdealVs', { at: cap(at), tn });
      } else {
        const t = io.thesis;
        const sd = this.#skillDice(this.findSkill(t.skill), false, null, t.fallback as AttributeKey, { skillName: t.skill });
        const site = t.siteDice ? (bestSite(this.magicSites(), isShamanic(this.tradition) ? 'lodge' : 'library')?.rating ?? 0) : 0;
        dice = sd.dice + site;
        mods = sd.modifiers;
        tn = thesisTn(grade);
        label = tx('SR2E.Card.Actor.thesisOrdealVs', { skill: t.skill, sdSuffix: sd.suffix, part: site ? tx('SR2E.Card.Actor.library', { site }) : '', tn });
      }
      const r = await successTest({ dice, targetNumber: tn, modifiers: this.#testModifiers({ modifiers: mods }), roll: foundryRoller(rolls) });
      const weeks = ordealWeeks(ordeal.effect, grade);
      await ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor: this }), rolls,
        content: `${describeResult(label, r)}<p>${r.successes > 0 ? `<strong>${tx('SR2E.Card.Actor.theOrdealIsMet')}</strong> ${tx('SR2E.Card.Actor.after2', { plural: escText(plural(weeks, 'week')) })}` : `<strong>${tx('SR2E.Card.Actor.theOrdealFails')}</strong> ${tx('SR2E.Card.Actor.afterTheInitiationWaitsNoKarma', { plural: escText(plural(weeks, 'week')) })}`}</p>` });
      if (!(r.successes > 0)) return false;
      ordealNote = ` (${plural(weeks, 'week')})`;
    }
    const up: Record<string, unknown> = {
      'system.initiateGrade': grade, 'system.karma.good': good - cost,
      'system.ledger': this.#ledgerWith({ kind: 'karma', amount: -cost, reason: tx('SR2E.Text.Actor.initiationToGrade', { grade }) }),
      ...(technique ? { [`system.metamagic.${technique}`]: true } : {}),
    };
    if (attr) up[`system.attributes.${attr}.base`] = Number(this.sys.attributes[attr].base) - 1;
    if (ordeal?.effect === 'geas') up['system.geasa'] = [...(this.sys.geasa ?? []), { text: o.geas?.trim() || tx('SR2E.Text.Actor.initiationGeasGrade', { grade }), magic: 1, met: true, checkOnCast: true }];
    // v0.48.0: an oath is kept like a geas.
    if (ordeal?.effect === 'oath') up['system.geasa'] = [...(this.sys.geasa ?? []), { text: group ? tx('SR2E.Text.Actor.oathTo', { group: group.name, text: o.geas?.trim() || tx('SR2E.Text.Actor.keptFaithfully') }) : tx('SR2E.Text.Actor.oath', { text: o.geas?.trim() || tx('SR2E.Text.Actor.keptFaithfully') }), magic: Math.max(0, io.oath.geasMagic), met: true, checkOnCast: false }];
    // v0.65.0: a meditation or thesis ordeal takes its weeks: the Karma now, the grade when they have passed.
    if ((ordeal?.effect === 'meditation' || ordeal?.effect === 'thesis') && this.waitsFor('magic')) {
      const weeks = ordealWeeks(ordeal.effect, grade);
      const { 'system.karma.good': k, 'system.ledger': _l, ...rest } = up;
      await this.update({ 'system.karma.good': k, 'system.ledger': this.#ledgerWith({ kind: 'karma', amount: -cost, reason: tx('SR2E.Text.Actor.initiationToGradeOrdealUnderWay', { grade }) }) });
      if (this.getFlag(SYSTEM_ID, 'pendingInitiation')) { try { await clearFlag(this, 'pendingInitiation'); } catch { /* none */ } }
      await this.startProject({ kind: 'initiation', area: 'magic', label: technique ? tx('SR2E.Text.Actor.initiationToGradeOrdealLearning', { grade, ordeal: ordeal.label.replace(/ \(.*\)$/, ''), technique }) : tx('SR2E.Text.Actor.initiationToGradeOrdeal', { grade, ordeal: ordeal.label.replace(/ \(.*\)$/, '') }), hours: weeks * 168, paid: { karma: cost },
        effect: { actor: Object.entries(rest) }, done: tx('SR2E.Text.Actor.isNowAnInitiateOfGrade', { name: this.name, grade }) });
      return true;
    }
    await this.update(up);
    if (ordeal?.effect === 'familiar' && familiar?.allyUuid) await this.setFlag(SYSTEM_ID, 'familiar', { ...familiar, usedForGrade: grade });
    if (this.getFlag(SYSTEM_ID, 'pendingInitiation')) { try { await clearFlag(this, 'pendingInitiation'); } catch { /* none */ } }
    const how = [group ? tx('SR2E.Card.Actor.with3', { groupName: group.name }) : '', ordeal ? tx('SR2E.Card.Actor.ordeal', { replace: ordeal.label.replace(/ \(.*\)$/, ''), part: attr ? ` (−1 ${cap(attr)})` : '', part2: ordeal.effect === 'familiar' && familiar?.allyName ? ` (${familiar.allyName})` : '', ordealNote }) : ''].filter(Boolean).join('; ');
    await ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor: this }),
      content: `<p><strong>${escText(this.name)}</strong> ${tx('SR2E.Card.Actor.initiatesToGradeForGoodKarma', { grade, cost, multiplier, part: how ? ` [${escText(how)}]` : '', part2: technique ? tx('SR2E.Card.Actor.learning', { technique: escText(technique) }) : '' })}</p>` });
    return true;
  }

  /** Bond a focus for Good Karma (rating x the type's cost). */
  async bondFocus(focus: any): Promise<boolean> {
    if (focus.system.bonded) return true;
    const cost = focusKarmaCost(focus.system.focusType, focus.system.rating, { target: focus.system.target, category: focus.system.category, size: focus.system.size });
    const good = (this.sys.karma?.good as number | undefined) ?? 0;
    if (good < cost) {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.bondingCostsGoodKarmaHas', { focusName: escHtml(focus.name), cost, name: escHtml(this.name), good }));
      return false;
    }
    if (approvalNeeded(this)) { await fileRequest(this, { kind: 'improve', label: tx('SR2E.Text.Actor.bond', { name: focus.name }), karma: cost, data: { method: 'bondFocus', args: [focus.id] } }); return false; }
    await focus.update({ 'system.bonded': true });
    // v0.64.0: with a ledger line (it had none).
    await this.update({ 'system.karma.good': good - cost, 'system.ledger': this.#ledgerWith({ kind: 'karma', amount: -cost, reason: tx('SR2E.Text.Actor.bonded', { name: focus.name }) }) });
    await ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor: this }), content: `<p><strong>${escText(this.name)}</strong> ${tx('SR2E.Card.Actor.bondsForGoodKarma', { focusName: escText(focus.name), cost })}</p>` });
    return true;
  }

  /** Environment tags of the scene being viewed (for totem environments). */
  static sceneEnvironment(at: any = null): string[] {
    const scene = at ?? game.scenes?.viewed ?? game.scenes?.current;
    return tags(String(scene?.getFlag?.(SYSTEM_ID, 'environment') ?? ''));
  }

  /** GM: set the environment tags of the scene being viewed. */
  static async setSceneEnvironment(text: string): Promise<void> {
    const scene = game.scenes?.viewed ?? game.scenes?.current;
    if (!scene) {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.openASceneFirstTheEnvironment'));
      return;
    }
    await scene.setFlag(SYSTEM_ID, 'environment', String(text ?? ''));
  }

  /** v0.56.0: projecting (or an unmaterialized spirit) and manifesting in the physical world. */
  isManifesting(): boolean {
    if (!this.sys?.manifesting || !RULES.MAGIC_V56.manifest.enabled) return false;
    return this.type === 'spirit' ? this.sys.materialized === false : this.sys.derived?.astralMode === 'projecting';
  }

  /**
   * v0.56.0: manifest (or stop): only while projecting, or as an unmaterialized spirit (RULES.MAGIC_V56.manifest).
   * The token shows faintly while manifesting.
   */
  async setManifesting(on: boolean): Promise<boolean> {
    if (on) {
      if (!RULES.MAGIC_V56.manifest.enabled) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.manifestingIsSwitchedOffHouseRule')); return false; }
      const can = this.type === 'spirit' ? this.sys.materialized === false : this.sys.derived?.astralMode === 'projecting';
      if (!can) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.mustBeToManifest', { name: escHtml(this.name), part: this.type === 'spirit' ? tx('SR2E.Notify.Actor.unmaterialized') : tx('SR2E.Notify.Actor.projecting') })); return false; }
    }
    await this.update({ 'system.manifesting': on });
    await this.#manifestTokens(on);
    await ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor: this }), content: `<p><strong>${escText(this.name)}</strong> ${on ? tx('SR2E.Card.Actor.manifestsSeenAndHeardInThe') : tx('SR2E.Card.Actor.stopsManifesting')}.</p>` });
    return true;
  }

  async #manifestTokens(on: boolean): Promise<void> {
    const alpha = on ? RULES.MAGIC_V56.manifest.alpha : 1;
    try {
      for (const t of (this as any).getActiveTokens?.(false, true) ?? []) if (!notWritableNow(t) && typeof t.update === 'function') await t.update({ alpha });
    } catch { /* no canvas */ }
  }

  /** Track when projection starts, and charge Essence for overstaying when the magician returns. */
  async onAstralModeChange(from: string, to: string, opts: { noAction?: boolean } = {}): Promise<void> {
    // v0.81.0 (D2-6): a character who can't leave the physical (Magic 0, or an aspected sorcerer or conjurer under the
    // Revamp) never goes astral: the switch goes back, with no action spent and no projection clock.
    const noAstral = !this.sys.derived?.dualNatured && this.sys.tradition !== 'adept'
      && (Number(this.sys.derived?.magic ?? this.sys.magic ?? 0) <= 0 || urrMagAstralModeFor(String(this.sys.tradition ?? ''), to) === 'physical');
    if (to !== 'physical' && noAstral) {
      if (from !== to) await this.update({ 'system.astral': 'physical' }, { sr2eNoAction: true });
      return;
    }
    const now = sysNow();
    // v0.71.0 (R19): perceiving or projecting takes an action in combat (RULES.ACTIONS.costs astralPerceive / astralProject);
    // refused (actions 'block'), the switch is put back. Coming back to the body is free.
    if (RULES.FIXES_V71.astralSwitchCost && !opts.noAction && to !== 'physical' && from !== to && !(this.sys.tradition === 'adept' && to === 'projecting')) {
      const kind = to === 'projecting' ? 'astralProject' : 'astralPerceive';
      if (!(await this.useAction(kind, to === 'projecting' ? tx('SR2E.Card.Actor.projectingAstrally') : tx('SR2E.Card.Actor.shiftingToAstralPerception')))) {
        await this.update({ 'system.astral': from }, { sr2eNoAction: true });
        return;
      }
    }
    // v0.56.0: leaving projection ends manifesting.
    if (from === 'projecting' && to !== 'projecting' && this.sys.manifesting) { await this.update({ 'system.manifesting': false }); await this.#manifestTokens(false); }
    // Adepts (v0.39.0): perceiving needs the astral perception power; projecting is not for them.
    if (this.sys.tradition === 'adept' && to !== 'physical') {
      if (this.adeptSpecial('astralPerception') <= 0) ui.notifications?.warn?.(tx('SR2E.Notify.Actor.needsTheAstralPerceptionAdeptPower', { name: escHtml(this.name) }));
      else if (to === 'projecting') ui.notifications?.warn?.(tx('SR2E.Notify.Actor.adeptsCanTProjectPerceivesInstead', { name: escHtml(this.name) }));
      if (to === 'projecting' || this.adeptSpecial('astralPerception') <= 0) return;
    }
    if (to === 'projecting' && from !== 'projecting') {
      await this.setFlag(SYSTEM_ID, 'projectionStart', now);
      return;
    }
    if (from === 'projecting' && to !== 'projecting') {
      // A possessing initiate who stops projecting leaves the body (v0.45.0).
      if (this.getFlag(SYSTEM_ID, 'possessing')) await this.endPossession();
      const start = this.getFlag(SYSTEM_ID, 'projectionStart') as number | undefined;
      await this.setFlag(SYSTEM_ID, 'projectionStart', null);
      if (typeof start !== 'number') return;
      const hours = Math.max(0, (now - start) / 3600);
      const o = projectionOverstay(hours, this.sys.derived.essence);
      if (o.essenceLoss > 0) {
        await this.update({ 'system.essence': Math.max(0, Math.round(((this.sys.essence as number) - o.essenceLoss) * 100) / 100) });
      }
      await ChatMessage.create({
        speaker: ChatMessage.getSpeaker({ actor: this }),
        content: `<p><strong>${escText(this.name)}</strong> ${tx('SR2E.Card.Actor.returnsToTheirBodyAfterH', { value: Math.round(hours * 10) / 10, limit: o.limit, part: o.essenceLoss > 0 ? ` <strong>${tx('SR2E.Card.Actor.overstayedHLosesEssence', { over: o.over, essenceLoss: o.essenceLoss })}</strong>` : '' })}</p>`,
      });
    }
  }

  /** Hours spent projecting so far and the limit, or null if not projecting. */
  projectionStatus(): { hours: number; limit: number; over: number } | null {
    if (this.sys.derived?.astralMode !== 'projecting') return null;
    const start = this.getFlag(SYSTEM_ID, 'projectionStart') as number | undefined;
    const now = sysNow();
    const hours = typeof start === 'number' ? Math.max(0, (now - start) / 3600) : 0;
    const o = projectionOverstay(hours, this.sys.derived.essence);
    return { hours: Math.round(hours * 10) / 10, limit: o.limit, over: o.over };
  }

  async _preCreate(data: any, options: any, user: any): Promise<boolean | void> {
    // v0.73.0 (O35): a new hand-made NPC has no Karma Pool unless given one (RULES.CHARACTERS_V73.npcs.handMadeKarmaPool).
    const kp = npcStartingKarmaPool(String(data?.type ?? this.type), data);
    if (kp !== null) (this as any).updateSource({ 'system.karma.pool': kp });
    return (super._preCreate as any)?.(data, options, user);
  }

  async _preUpdate(changed: any, options: any, user: any): Promise<any> {
    // v0.73.0 (O31): a different lifestyle level is a new rent (an outright lifestyle was the old one's), unless the
    // same update says otherwise.
    if (this.type === 'character' || this.type === 'npc') {
      const to = changed?.['system.lifestyle.level'] ?? changed?.system?.lifestyle?.level;
      const setsOutright = changed?.['system.lifestyle.outright'] !== undefined || changed?.system?.lifestyle?.outright !== undefined;
      if (!setsOutright) {
        const lp = lifestyleLevelChangePatch({ from: String(this.sys.lifestyle?.level ?? 'low'), to, outright: Boolean(this.sys.lifestyle?.outright), now: sysNow() } as any);
        for (const [k, v] of Object.entries(lp)) foundry.utils.setProperty(changed, k, v);
      }
    }
    // v0.57.0: in a started combat a vehicle's speed changes only by its Acceleration (a push test goes further).
    if (this.type === 'vehicle' && !options?.sr2eSpeedOk) {
      const flat = changed?.['system.currentSpeed'];
      const want = flat ?? changed?.system?.currentSpeed;
      if (want !== undefined && Number(want) !== Number(this.sys.currentSpeed ?? 0)) {
        const win = this.speedWindow();
        if (win.limited) {
          const c = clampSpeed({ accel: Number(this.sys.accel ?? 0), turnStart: win.start, to: Math.max(0, Number(want)), extra: win.extra });
          const st = { round: win.round ?? -1, start: win.start, extra: win.extra };
          if (flat !== undefined) { changed['system.currentSpeed'] = c.speed; changed['system.speedTurn'] = st; }
          else { changed.system.currentSpeed = c.speed; changed.system.speedTurn = st; }
          if (c.clamped) ui.notifications?.info?.(tx('SR2E.Notify.Actor.canChangeSpeedByAtMost', { name: escHtml(this.name), limit: c.limit, accel: escHtml(this.sys.accel), part: win.extra ? tx('SR2E.Notify.Actor.pushed', { winExtra: win.extra }) : '', speed: c.speed }));
        }
      }
    }
    // v0.57.0: a host set to shutdown by hand (its sheet) dumps everyone too.
    if (this.type === 'host' && (changed?.system?.alert ?? changed?.['system.alert']) === 'shutdown' && this.sys.alert !== 'shutdown') options.sr2eShutdown = true;
    if (changed?.system?.astral !== undefined || changed?.['system.astral'] !== undefined) options.sr2ePrevAstral = this.sys.astral;
    // v0.56.0: spells leaving the Sustaining list take their effects with them (see #sustainingDropped).
    if ((changed?.system?.sustaining !== undefined || changed?.['system.sustaining'] !== undefined) && Array.isArray(this.sys?.sustaining)) {
      options.sr2ePrevSustaining = this.sys.sustaining.map((e: any) => ({ ...e, targetUuids: [...(e.targetUuids ?? [])], healed: { ...(e.healed ?? {}) } }));
    }
    // Condition monitor changes: remember the status and damage before, to sync statuses afterwards.
    const mon = changed?.system?.monitor;
    if (this.sys?.monitor && (mon || changed?.['system.monitor.physical'] !== undefined || changed?.['system.monitor.stun'] !== undefined)) {
      options.sr2ePrevStatus = this.sys.derived?.status;
      options.sr2ePrevMonitor = { physical: this.sys.monitor.physical, stun: this.sys.monitor.stun };
    }
    // v0.59.0: a vehicle's condition before, for the floating numbers on its token.
    if (this.type === 'vehicle' && (changed?.system?.condition !== undefined || changed?.['system.condition'] !== undefined)) options.sr2ePrevCondition = Number(this.sys.condition ?? 0);
    return super._preUpdate?.(changed, options, user);
  }

  _onUpdate(changed: any, options: any, userId: string): void {
    super._onUpdate?.(changed, options, userId);
    // v0.81.0 (D2-14): each follow-up's failure is logged with its name (not an anonymous unhandled rejection).
    const after = (what: string, p: unknown): void => { Promise.resolve(p).catch((err) => console.error(`sr2e | after an update: ${what}`, err)); };
    // v0.71.0 (R18): a vehicle destroyed some other way than a resisted hit (its sheet's boxes, a botched mod):
    // the dead marker, and a jumped-in rigger is dumped as a hit would dump them.
    if (this.type === 'vehicle' && madeHere(options, userId) && options?.sr2ePrevCondition !== undefined && !options?.sr2eSoak && RULES.FIXES_V71.vehicleRepair.enabled
      && Number(options.sr2ePrevCondition) < RULES.VEHICLES.conditionBoxes && this.sys.derived?.destroyed) after('destroyed', this.#destroyedElsewhere());
    if (options?.sr2eShutdown && madeHere(options, userId)) after('shutdown', SR2Actor.startShutdown(this));
    if (options?.sr2ePrevAstral !== undefined && madeHere(options, userId) && options.sr2ePrevAstral !== this.sys.astral) {
      after('astral mode', this.onAstralModeChange(options.sr2ePrevAstral, this.sys.astral, { noAction: Boolean(options.sr2eNoAction) }));
    }
    if (options?.sr2ePrevSustaining && madeHere(options, userId)) after('sustaining', this.#sustainingDropped(options.sr2ePrevSustaining, this.sustained()));
    // v0.56.0: a spirit that materializes stops manifesting.
    if (this.type === 'spirit' && changed?.system?.materialized === true && this.sys.manifesting && madeHere(options, userId)) after('manifesting', this.setManifesting(false));
    if (options?.sr2ePrevMonitor && madeHere(options, userId)) {
      const before = options.sr2ePrevMonitor as Monitor;
      after('condition', this.syncCondition(options.sr2ePrevStatus, { physical: this.sys.monitor.physical > before.physical, stun: this.sys.monitor.stun > before.stun }));
    }
  }

  /** v0.72.0 (O17): take a barrier spell's barrier down: its regions on every scene, then the actor (or ask the GM). */
  static async #dropBarrierSpell(effectId: string, spellName: string): Promise<void> {
    const b: any = SR2Actor.barrierOfSpell(effectId);
    if (!b) return;
    // Scene regions are the GM's: a player's drop asks the GM.
    if (isGmNow()) await SR2Actor.removeBarrier(b);
    else await SR2Actor.gmActorCard(b.uuid, { remove: true, by: String(b.getFlag?.(SYSTEM_ID, 'barrierSpell')?.casterUuid ?? '') }, tx('SR2E.Card.Actor.isDroppedRemoveAndItsRegions', { spellName: escText(spellName), name: escText(b.name) }));
  }

  /** v0.72.0 (O17): delete a barrier actor and the regions drawn for it (GM). */
  static async removeBarrier(b: any): Promise<void> {
    for (const sc of [...((game as any).scenes ?? [])]) {
      const ids = [...(sc.regions ?? [])].filter((r: any) => r.flags?.[SYSTEM_ID]?.env?.wardUuid === b.uuid).map((r: any) => r.id);
      if (ids.length) { try { await sc.deleteEmbeddedDocuments('Region', ids); } catch { /* no right */ } }
    }
    try { await b.delete(); } catch { /* gone */ }
  }

  /**
   * v0.56.0: spells that left the Sustaining list: their effects come off their targets (unless the spell
   * became permanent), and a permanent healing spell dropped before it took gives the boxes back.
   */
  async #sustainingDropped(before: any[], after: any[]): Promise<void> {
    const now = sysNow();
    const still = (e: any) => after.some((x: any) => (e.effectId ? x.effectId === e.effectId : x.spellName === e.spellName && x.force === e.force));
    for (const e of before) {
      if (still(e)) continue;
      // v0.72.0 (O17): a dropped or dispelled barrier spell's barrier falls (its actor and its regions).
      if (e.effectId) await SR2Actor.#dropBarrierSpell(e.effectId, String(e.spellName ?? ''));
      const took = typeof e.permanentAt === 'number' && e.permanentAt >= 0 && e.permanentAt <= now;
      if (e.effectId && !took) {
        const targets: string[] = e.targetUuids?.length ? e.targetUuids : [this.uuid as string];
        for (const u of targets) {
          const t: any = fromUuidSync(u);
          const has = ((t?.getFlag?.(SYSTEM_ID, 'powerEffects') as any[] | undefined) ?? []).find((x: any) => x.id === e.effectId);
          if (has && !has.permanent) await SR2Actor.setPowerEffect(u, null, e.effectId);
        }
      }
      const h = e.healed;
      if (!took && e.permanentAt >= 0 && RULES.MAGIC_V56.permanent.undoHealing && h?.targetUuid && Number(h.boxes) > 0) {
        const p: any = fromUuidSync(h.targetUuid);
        const track = h.track === 'stun' ? 'stun' : 'physical';
        const what = tCount(h.boxes, 'SR2E.Card.Actor.isDroppedBeforeItBecamePermanent', { spellName: escText(e.spellName), name: escText(p?.name ?? tx('SR2E.Card.Actor.thePatient')), track });
        if (p?.system?.monitor && canWriteNow(p)) {
          await p.update({ [`system.monitor.${track}`]: Math.min(RULES.MONITOR_BOXES, Number(p.system.monitor[track] ?? 0) + Number(h.boxes)) });
          await ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor: this }), content: `<p>${what}.</p>` });
        } else if (p?.system?.monitor) await SR2Actor.gmActorCard(h.targetUuid, { monitor: { track, boxes: Number(h.boxes) }, by: this.uuid as string }, what);
      }
    }
  }

  /**
   * v0.81.0 (D2-2): a ritual team member's drain, rolled on the leader's client. A member this client can't write (another
   * player's character) gets a card instead of a failed update that would stop the loop; so does one whose drain fails.
   * R2-DOC 4: a drain that failed after its card was posted is not asked for again; the card states the TN and level
   * (`how`) so it can be rolled by hand.
   * TODO(hole): a "Resist ritual drain" button for the member's owner needs a chat action (applications/chat.ts).
   */
  async #memberDrain(m: any, what: string, roll: () => Promise<unknown>, how = ''): Promise<void> {
    if (canWriteNow(m)) {
      const key = String(m.uuid ?? '');
      const before = SR2Actor.#postsBy.get(key) ?? 0;
      try { await roll(); return; } catch (err) {
        console.warn('sr2e | ritual drain', err);
        if ((SR2Actor.#postsBy.get(key) ?? 0) > before) return;
      }
    }
    await ChatMessage.create({
      speaker: ChatMessage.getSpeaker({ actor: m }),
      content: `<p><strong>${escText(m?.name ?? tx('SR2E.Card.Actor.aTeamMember'))}</strong> ${tx('SR2E.Card.Actor.resistsTheRitualDrainForTheir', { what: escText(what), part: how ? ` (${escText(how)})` : '' })}</p>`,
    });
  }

  /** R2-DOC 4: how many test cards each actor (uuid) has posted on this client (#post), so a drain that failed after posting isn't asked for twice. */
  static #postsBy = new Map<string, number>();

  /** A ritual team member's share of the drain. */
  async ritualDrain(spell: any, force: number, modifiers: TargetNumberModifier[] = []): Promise<void> {
    await this.#resistDrain(spell, force, 0, modifiers, tx('SR2E.Card.Actor.ritualDrain', { spellName: spell.name }));
  }

  /**
   * Cast a spell at an object rather than a living target (v0.47.0, RULES.GEAR.spellsVsObjects): Sorcery
   * vs the object's resistance TN (natural, low-tech, high-tech, processed). Mana spells don't affect
   * objects. A physical combat spell at a wall damages it with Power Force + net successes. Drain as usual.
   */
  async castAtObject(spell: any, opts: { force?: number; objectKind?: string; wall?: any; poolDice?: number; drainPoolDice?: number; modifiers?: TargetNumberModifier[]; fetishInHand?: boolean; spendAction?: boolean } = {}): Promise<SuccessTestResult | null> {
    if (!this.canAct('castSpell')) return null;
    const sp = spell.system;
    if (sp.spellType === 'mana') { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.isAManaSpellItHas', { spellName: escHtml(spell.name) })); return null; }
    const blocked = traditionBlocks(this.tradition, 'cast')
      ?? aspectRestriction(this.tradition, 'cast', { aspectElement: this.sys.aspectElement, category: sp.category, spellElement: sp.element, totem: this.sys.totem });
    if (blocked) { ui.notifications?.warn?.(`${escHtml(this.name)}: ${escHtml(blocked)}`); return null; }
    const sorcery = this.findSkill('Sorcery');
    const objUse = this.sorceryUseFor('cast', { category: sp.category, spellName: spell.name, skill: sorcery });
    if (!sorcery || sorcery.system.rating <= 0 || (this.sys.derived.magic as number) <= 0) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.cannotCastSpells', { name: escHtml(this.name) })); return null; }
    if (sp.fetish && opts.fetishInHand === false) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.isFetishLimitedNeedsTheFetish', { spellName: escHtml(spell.name), name: escHtml(this.name) })); return null; }
    // The action is spent only once the cast can go ahead.
    if (opts.spendAction && !(await this.useAction('cast', tx('SR2E.Card.Actor.casting', { spellName: spell.name })))) return null;
    const drainForce = clampForce(opts.force ?? sp.learnedForce, sp.learnedForce);
    // v0.80.0 (RULES.URR_V80.magExclusiveForce / magFetishForce, URR).
    const force = drainForce + urrMagSpellForceBonus({ exclusive: Boolean(sp.exclusive), fetish: Boolean(sp.fetish) });
    const kind = opts.objectKind || RULES.GEAR.spellsVsObjects.wallKind;
    const tn = objectResistanceTn(kind);
    const kindLabel = ({ natural: 'natural', lowTech: 'low-tech', highTech: 'high-tech', processed: 'highly processed' } as Record<string, string>)[kind] ?? kind;
    const wall = sp.category === 'combat' ? opts.wall ?? null : null;
    this.#warnGeasa(tx('SR2E.Card.Actor.casts'));
    const focus = sorceryFocusDice(this.foci(), { name: spell.name, category: sp.category });
    const totem = totemDice(this.tradition, this.sys.totem, sp.category);
    const extra = bonusNote(focus, totem);
    // v0.92.0: say which narrow rating the test rolls.
    if (narrowRating(sorcery.system, objUse) > Number(sorcery.system?.rating ?? 0)) extra.note += ` [${tx('SR2E.Card.MagicPool.narrow', { name: objUse.spec ? sorcery.system.specialization : sorcery.system.concentration, rating: narrowRating(sorcery.system, objUse) })}]`;
    const env = totemEnvironmentDice(this.tradition, this.sys.totem, this.environmentHere());
    if (env.dice) { extra.dice += env.dice; extra.note = extra.note ? extra.note.replace(/\]$/, `, ${env.note}]`) : ` [${env.note}]`; }
    // Through the usual pipeline: magical modifiers (background count, centering), Spell Pool, Karma; a sustained spell stays up.
    const result = await this.#runTest(tx('SR2E.Card.Actor.forceAtTn', { spellName: spell.name, force, part: wall ? tx('SR2E.Card.Actor.aWall') : tx('SR2E.Card.Actor.aObject', { kindLabel }), tn, extraNote: extra.note }),
      // v0.80.0 (RULES.URR_V80.magCastDice 'force', URR).
      // v0.92.0 (RULES.MAGIC_V920): inside Sorcery's concentration or specialization, its rating.
      Math.max(0, urrMagCastingDice({ dice: narrowRating(sorcery.system, objUse), force }) + extra.dice),
      { targetNumber: tn, poolDice: castingPoolDice(opts.poolDice ?? 0, Number(this.sys.derived?.magic ?? 0)), pool: 'spell', spellUse: objUse, magical: true, modifiers: [...this.blindMods('spell'), ...(opts.modifiers ?? [])] },
      { kind: 'spell', ...(sp.duration === 'sustained' ? { sustain: { spellName: spell.name, force, category: sp.category, focusId: '' } } : {}) });
    await this.leaveSignature('spell', spell.name, force);
    if (wall && result.successes > 0) {
      const power = objectSpellPower(force, result.successes);
      // Damaging a wall needs the GM; a player's cast posts a card the GM applies.
      if (isGmNow() || wall.canUserModify?.(actingAuthor ?? game.user, 'update')) await SR2Actor.damageWall(wall, power, { label: `${spell.name} on a wall`, kind: 'combatSpell' });
      else await ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor: this }), whisper: [...((game as any).users ?? [])].filter((u: any) => u.isGM).map((u: any) => u.id),
        content: `<p>${tx('SR2E.Card.Actor.sHitsAWallWith', { name: escText(this.name), spellName: escText(spell.name) })} <strong>${tx('SR2E.Card.Actor.power', { power })}</strong>.</p><p><button type="button" data-sr2e-action="spellWall">${tx('SR2E.Card.Actor.applyToTheWallGm')}</button></p>`,
        flags: { [SYSTEM_ID]: { spellWall: { wallUuid: wall.uuid, power, label: `${spell.name} on a wall` } } } });
    }
    // v0.80.0 (RULES.URR_V80.magRuleOfOneDrain, URR): drain at the normal Force, +2 on a disaster.
    await this.#resistDrain(spell, drainForce, opts.drainPoolDice ?? 0, [...spellOptionDrainMods({ exclusive: sp.exclusive, fetish: sp.fetish }), ...urrMagRuleOfOneDrain(Boolean((result as any)?.botch))], tx('SR2E.Card.Actor.drain'), undefined, objUse);
    return result;
  }

  /** Drain: Willpower (plus Spell Pool dice) vs floor(Force/2) + modifier; 2 successes stage it down a level. */
  async #resistDrain(spell: any, force: number, poolDice: number, modifiers: TargetNumberModifier[] = [], label = 'Drain', levelOverride?: DamageLevel, use?: SorceryUse): Promise<void> {
    const sp = spell.system;
    const baseDrain80 = drainDamageType(force, Number(this.sys.derived.drainMagic ?? this.sys.derived.magic ?? 0) || (this.type === 'npc' && spell?.system?.innate ? Math.floor(Number(this.sys.derived?.essence ?? this.sys.essence ?? 0)) : 0));
    const drainType80 = urrMagAstralDrainType(baseDrain80, this.sys.derived?.astralMode);
    await this.#drainTest({
      label: levelOverride && levelOverride !== sp.drainLevel ? tx('SR2E.Card.Actor.byTheWound', { label }) : label,
      attribute: 'willpower',
      targetNumber: drainTargetNumber(force, sp.drainModifier),
      level: (levelOverride ?? sp.drainLevel) as DamageLevel,
      // v0.72.0 (O18, live run): a critter's innate spell measures Force against its Essence when it has no Magic.
      // v0.80.0 (RULES.URR_V80.magAstralDrainPhysical, URR): cast while projecting, the drain is Physical.
      type: drainType80,
      // v0.80.0: the card says why the drain is Physical when only projecting made it so (the book text otherwise).
      ...(drainType80 === 'physical' && baseDrain80 !== 'physical' ? { physicalNote: tx('SR2E.Card.Actor.castWhileProjectingPhysical') } : {}),
      poolDice,
      modifiers,
      // v0.92.0 (RULES.MAGIC_V920.drainNarrow): the narrow dice left may pay for this casting's Drain.
      ...(use && drainNarrowOn() ? { spellUse: use } : {}),
    });
  }

  /** A drain test: the attribute (plus Spell Pool dice) vs the TN; every 2 successes stage the level down. */
  async #drainTest(o: {
    label: string; attribute: AttributeKey; targetNumber: number; level: DamageLevel; type: DamageType; poolDice: number;
    modifiers?: TargetNumberModifier[];
    /** Wording on the card: 'drain' (default) or 'damage' (e.g. dump shock). */
    noun?: 'drain' | 'damage';
    /** Title note for physical damage (default: Force over Magic). */
    physicalNote?: string;
    /** v0.46.0: extra dice (an ICCM filter), and their note for the title. */
    extraDice?: number;
    extraNote?: string;
    /** v0.48.0: a hazard, not magic: no background count. v0.81.0 (D2-5): implied by `noun: 'damage'` (hazards, shocks). */
    noBackground?: boolean;
    /** v0.92.0: the casting's narrow layers (its Drain may take their dice). */
    spellUse?: SorceryUse;
  }): Promise<void> {
    const narrow = o.spellUse && (o.spellUse.conc || o.spellUse.spec) ? o.spellUse : null;
    const pool = Math.max(0, Math.min(o.poolDice, narrow ? this.spellPoolFor(narrow) : this.sys.derived.spellPoolLeft as number));
    const rolls: any[] = [];
    const bgi = this.backgroundInfo();
    const bg = o.noBackground || o.noun === 'damage' ? [] : RULES.SPELLCRAFT.backgroundCount.affectsDrain || (bgi.toxic && RULES.MAGIC_V39.background.toxicAffectsDrain)
      ? backgroundCountModifiers(bgi.penalty).map((m) => (bgi.toxic ? { ...m, label: tx('SR2E.Card.Actor.toxicBackgroundCount') } : m)) : [];
    const result = await successTest({
      dice: this.sys.attributes[o.attribute].total + Math.max(0, o.extraDice ?? 0),
      poolDice: pool,
      targetNumber: o.targetNumber,
      modifiers: [...(o.modifiers ?? []), ...bg],
      roll: foundryRoller(rolls),
    });
    if (pool > 0 && narrow) await this.#spendSpellPool(pool, narrow);
    else if (pool > 0) await this.#spendPool('spell', pool);
    await this.#post(this.#snapshot(tx('SR2E.Card.Actor.tn5', { label: o.label, level: o.level, targetNumber: o.targetNumber, part: o.extraDice ? ` [${o.extraNote ?? tx('SR2E.Card.Actor.dice5', { extraDice: o.extraDice })}]` : '', part2: o.type === 'physical' ? (o.physicalNote ?? tx('SR2E.Card.Actor.forceOverMagicPhysical')) : '' }), result, {
      kind: 'soak',
      soak: { mode: 'stage', noun: o.noun ?? 'drain', level: o.level, type: o.type, body: this.sys.attributes.body.total, before: this.#monitor() },
    }), result, rolls);
  }

  /** Conjuring drain for a spirit of this Force: Charisma vs Force, level from Force vs Charisma. */
  async #conjuringDrain(force: number, poolDice: number): Promise<void> {
    const attribute = RULES.CONJURING.drainAttribute as AttributeKey;
    await this.#drainTest({
      label: tx('SR2E.Card.Actor.conjuringDrain'),
      attribute,
      targetNumber: conjuringDrainTargetNumber(force),
      level: conjuringDrainLevel(force, this.sys.attributes[attribute].total),
      type: conjuringDrainType(force, Number(this.sys.derived.drainMagic ?? this.sys.derived.magic ?? 0), this.sys.attributes[attribute].total),
      ...(RULES.URR_V80.magConjDrain === 'charisma' ? { physicalNote: tx('SR2E.Card.Actor.forceOverCharismaPhysical') } : {}),
      poolDice: RULES.CONJURING.spellPoolAllowed ? poolDice : 0,
    });
  }

  /** Whether this actor is on the astral plane right now (perceiving, projecting, or a spirit). */
  isAstral(): boolean {
    return astrallyActive(this.sys.derived.astralMode as AstralMode, this.type === 'spirit');
  }

  /**
   * Astral combat: like melee at RULES.ASTRAL.attackBaseTn. Magicians roll the astral attack skill
   * (defaulting to Willpower) plus astral pool dice, for Power = Charisma; spirits roll Force plus
   * Combat Pool for Power = Force. Both sides must be on the astral plane.
   */
  async astralAttack(opts: {
    targetUuid?: string | null; poolDice?: number; damageType?: DamageType; modifiers?: TargetNumberModifier[];
  } = {}): Promise<SuccessTestResult | null> {
    if (!this.canAct('astralAttack')) return null;
    if (!this.isAstral()) {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.isNotOnTheAstralPlane', { name: escHtml(this.name) }));
      return null;
    }
    const targetUuid = opts.targetUuid ?? null;
    if (targetUuid) {
      const target: any = await fromUuid(targetUuid);
      if (target && typeof target.isAstral === 'function' && !target.isAstral()) {
        ui.notifications?.warn?.(tx('SR2E.Notify.Actor.isNotOnTheAstralPlane2', { targetName: escHtml(target.name) }));
        return null;
      }
    }
    const spirit = this.type === 'spirit';
    let dice: number;
    let modifiers: TargetNumberModifier[] = [];
    let suffix = '';
    // v0.72.0 (O14): adepts fight with Unarmed Combat (or a better martial art), the Combat Pool and killing hands (MAGIC_V72.adeptAstral).
    const ms = spirit ? null : this.martialStyle();
    const prof = astralCombatProfile({
      type: this.type, tradition: String(this.tradition ?? ''),
      base: { skill: RULES.ASTRAL.attackSkill, pool: RULES.ASTRAL.attackPool, level: RULES.ASTRAL.damageLevel as DamageLevel },
      killingHandsLevel: spirit ? 0 : this.adeptSpecial('killingHands'), killingHandsLevels: RULES.ADEPT.killingHands.levels,
      unarmedRating: Number(this.findSkill(RULES.COMBAT.unarmed.skill)?.system?.rating ?? 0),
      martial: ms ? { name: String(ms.skill.name), rating: Number(ms.skill.system?.rating ?? 0) } : null,
    });
    if (spirit) {
      dice = this.sys.force as number;
    } else {
      const skill = prof.mode === 'adept' && ms && ms.skill.name === prof.skill ? ms.skill : this.findSkill(prof.skill);
      ({ dice, modifiers, suffix } = this.#skillDice(skill, false, null, prof.fallback as AttributeKey));
      const extra = bonusNote(weaponFocusDice(this.foci(), null), 0);
      dice += extra.dice;
      suffix += extra.note + prof.note;
    }
    // v0.80.0 (RULES.URR_V80.magAstralDamage 'urr', URR): unarmed L; a weapon focus adds its rating to the Power at M.
    const ad = urrMagAstralDamage({ mode: prof.mode, power: spirit ? (this.sys.force as number) : (this.sys.attributes[RULES.ASTRAL.powerAttribute].total as number),
      level: prof.damageLevel as DamageLevel, focusRating: spirit ? 0 : urrMagWeaponFocusRating(this.foci() as any[]) });
    const power = ad.power;
    const level = ad.level;
    suffix += ad.note;
    const damageType: DamageType = opts.damageType ?? 'physical';
    const attack = targetUuid
      ? { attackerUuid: this.uuid as string, targetUuid, weaponName: tx('SR2E.Card.Actor.astralAttack'), melee: true, damageType, power, level, astral: true }
      : undefined;
    const base = RULES.ASTRAL.attackBaseTn;
    return this.#runTest((damageType === 'stun' ? tx('SR2E.Card.Actor.astralAttackTnWithStun', { base, power, level, suffix }) : tx('SR2E.Card.Actor.astralAttackTnPlain', { base, power, level, suffix })), dice, {
      targetNumber: base,
      modifiers: [...(opts.modifiers ?? []), ...modifiers],
      poolDice: opts.poolDice ?? 0,
      pool: this.poolFor({ astral: true }),
      background: true,
    }, { kind: 'attack', ...(attack ? { attack } : {}) });
  }

  /** The Conjuring skill, or null after warning why this actor cannot conjure. */
  #conjuringSkill(quiet = false): any | null {
    const skill = this.findSkill('Conjuring');
    if (quiet) return skill && skill.system.rating > 0 && (this.sys.derived.magic as number) > 0 ? skill : null;
    if (!skill || skill.system.rating <= 0) {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.hasNoConjuringSkillAndCannot', { name: escHtml(this.name) }));
      return null;
    }
    if ((this.sys.derived.magic as number) <= 0) {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.hasNoMagicAndCannotSummon', { name: escHtml(this.name) }));
      return null;
    }
    return skill;
  }

  /** v0.61.0: what happens to this magician's bound spirits now they are dead (owners update, else a GM card). */
  async #spiritsOnDeath(): Promise<void> {
    for (const sp of this.summonedSpirits()) {
      // v0.72.0 (O13): by kind (MAGIC_V72.masterDies): nature spirits and watchers depart, allies (and elementals) go free.
      const r = boundSpiritOnMasterDeath(String(sp.system?.spiritKind ?? ''), RULES.MAGIC_V61.masterDies);
      if (r.action === 'none') continue;
      const text = `${sp.name}: ${r.note}`;
      if (canWriteNow(sp)) {
        await sp.update(r.update);
        await ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor: sp }), content: `<p>${tx('SR2E.Card.Actor.isDead', { name: escText(this.name), text: escText(text) })}</p>` });
      } else await SR2Actor.gmActorCard(sp.uuid, { masterDied: true, by: this.uuid as string }, tx('SR2E.Card.Actor.isDead', { name: escText(this.name), text: escText(text) }));
    }
  }

  /** Spirit actors this actor has summoned (in the world's actor directory). */
  summonedSpirits(): any[] {
    return allActors().filter((a: any) => a.type === 'spirit' && a.system?.summonerUuid === this.uuid);
  }

  /**
   * Summon a spirit or elemental: Conjuring vs TN = Force; each success is a service. On success a
   * spirit actor is created (copied from `templateUuid` if given) owned like the summoner. Drain
   * follows straight away.
   */
  async conjure(opts: ConjureOptions): Promise<SuccessTestResult | null> {
    return this.#oneAtATime('conjure', null, () => this.#conjure(opts));
  }

  /** The summoning itself (conjure guards it against a double click). */
  async #conjure(opts: ConjureOptions): Promise<SuccessTestResult | null> {
    if (!this.canAct('conjure')) return null;
    const kindIn: SpiritKind = opts.spiritKind ?? 'nature';
    const elementIn = (opts.element ?? '').trim().toLowerCase()
      || (kindIn === 'elemental' ? RULES.MAGIC_EXTRA.elements.find((e) => (opts.spiritType ?? '').toLowerCase().includes(e)) ?? '' : '');
    const blocked = traditionBlocks(this.tradition, 'conjure')
      ?? aspectRestriction(this.tradition, 'conjure', { aspectElement: this.sys.aspectElement, spiritKind: kindIn, spiritElement: elementIn });
    if (blocked) {
      ui.notifications?.warn?.(`${escHtml(this.name)}: ${escHtml(blocked)}`);
      return null;
    }
    const skill = this.#conjuringSkill();
    if (!skill) return null;
    const spiritKind: SpiritKind = opts.spiritKind ?? 'nature';
    let force = clampSpiritForce(opts.force);
    if (spiritKind === 'watcher' && force > RULES.SPIRITS_EXTRA.watcherMaxForce) {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.watchersAreAtMostForce', { sPIRITS_EXTRAWatcherMaxForce: RULES.SPIRITS_EXTRA.watcherMaxForce }));
      force = RULES.SPIRITS_EXTRA.watcherMaxForce;
    }
    if (spiritKind === 'ally' || spiritKind === 'free') {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.createTheSpiritActorDirectlyAnd', { part: spiritKind === 'ally' ? tx('SR2E.Notify.Actor.alliesAreMadeByRitual') : tx('SR2E.Notify.Actor.freeSpiritsAreNotSummoned') }));
      return null;
    }
    const spiritType = (opts.spiritType ?? '').trim();
    this.#warnGeasa(tx('SR2E.Card.Actor.summons'));
    const warning = traditionSpiritWarning(this.tradition, spiritKind) ?? traditionKindWarning(this.tradition, spiritKind);
    if (warning) ui.notifications?.warn?.(escHtml(warning));
    // Insect shamans need a hive (v0.45.0).
    if (spiritKind === 'insect' && hiveMissing(this.tradition, this.magicSites()) && !this.#siteProblem(tx('SR2E.Card.Actor.summoningInsectSpirits'), ['a hive (a lodge)'])) return null;
    // v0.56.0: the totem's conjuring dice only for the spirit types or domains it favours (totem.spirits).
    const extra = bonusNote(conjuringFocusDice(this.foci(), { kind: spiritKind, type: spiritType }), totemConjuringDice(this.tradition, this.sys.totem, { kind: spiritKind, type: spiritType, domain: (opts.domain ?? '').trim() }));
    const env = totemEnvironmentDice(this.tradition, this.sys.totem, this.environmentHere());
    if (env.dice) {
      extra.dice += env.dice;
      extra.note = extra.note ? extra.note.replace(/\]$/, `, ${env.note}]`) : ` [${env.note}]`;
    }
    const domain = (opts.domain ?? '').trim();
    let bindNote = '';
    if (spiritKind === 'elemental') {
      // Hermetic libraries and circles (v0.39.0).
      const missing = missingSites('elemental', this.tradition, this.magicSites(), { force, element: elementIn });
      if (missing.length && !this.#siteProblem(elementIn ? tx('SR2E.Text.Actor.aForceElemental', { force, element: elementIn }) : tx('SR2E.Text.Actor.aForceElementalPlain', { force }), missing)) return null;
      const max = maxBoundElementals(this.sys.attributes.charisma.total);
      // v0.71.0 (R20): elementals still being summoned count against the limit too.
      const coming = RULES.FIXES_V71.conjureDrainAtEnd ? this.projects().filter((p: any) => p.kind === 'elemental').length : 0;
      const bound = this.summonedSpirits().filter((a: any) => a.system.spiritKind === 'elemental' && a.system.services > 0).length + coming;
      if (bound >= max) ui.notifications?.warn?.(tx('SR2E.Notify.Actor.alreadyHasBoundElementalLimit', { name: escHtml(this.name), bound: tCount(bound, 'SR2E.Count.boundElemental'), max }));
      // Elementals need conjuring materials and take time.
      const cost = bindingCost(force);
      if (opts.useMaterials) {
        const nuyen = (this.sys.nuyen as number | undefined) ?? 0;
        if (nuyen < cost.nuyen) {
          ui.notifications?.warn?.(tx('SR2E.Notify.Actor.conjuringMaterialsForAForceElemental', { force, costNuyen: cost.nuyen, name: escHtml(this.name), nuyen }));
          return null;
        }
        if (cost.nuyen > 0 && !(await this.adjustNuyen(-cost.nuyen, tx('SR2E.Text.Actor.conjuringMaterialsForce', { force })))) return null;
        bindNote = tx('SR2E.Card.Actor.materialsH', { costNuyen: cost.nuyen, costHours: cost.hours });
      } else bindNote = ` [${cost.hours} h]`;
    }
    if (spiritKind === 'nature') {
      const domains = this.summonedSpirits().filter((a: any) => a.system.spiritKind === 'nature' && a.system.services > 0).map((a: any) => a.system.domain ?? '');
      const conflict = domainConflict(domains, domain);
      if (conflict) ui.notifications?.warn?.(escHtml(conflict));
    }

    // v0.61.0: an insect spirit takes a host body (MAGIC_V61.insect): flesh form, else its true form.
    let hostUuid = '';
    if (spiritKind === 'insect') {
      const tgt: any = opts.hostUuid ? fromUuidSync(opts.hostUuid) : [...((game as any).user?.targets ?? [])][0]?.actor ?? null;
      hostUuid = tgt && tgt !== this && ['character', 'npc'].includes(tgt.type) ? String(tgt.uuid) : '';
      if (!hostUuid && RULES.MAGIC_V61.insect.needsHost) ui.notifications?.info?.(tx('SR2E.Notify.Actor.noHostBodyTargetedTheInsect'));
    }
    const what = spiritType || (spiritKind === 'elemental' ? 'elemental' : spiritKind === 'nature' ? 'nature spirit' : 'spirit');
    const pool = RULES.CONJURING.spellPoolAllowed ? opts.poolDice ?? 0 : 0;
    // v0.71.0 (R20): an elemental that takes its hours of ritual is drained when it arrives (or now, if none answers).
    const drainLater = spiritKind === 'elemental' && RULES.FIXES_V71.conjureDrainAtEnd && this.waitsFor('magic') ? { force, pool: opts.drainPoolDice ?? 0 } : null;
    const result = await this.#runTest(tx('SR2E.Card.Actor.summonForceTn', { what, force, extraNote: extra.note, bindNote, part: domain && spiritKind === 'nature' ? tx('SR2E.Card.Actor.domain', { domain }) : '' }), Math.max(0, skill.system.rating + extra.dice),
      { targetNumber: force, poolDice: pool, pool: 'spell', magical: true, ...(opts.exclude?.length ? { exclude: opts.exclude } : {}) },
      { kind: 'conjure', conjure: { force, spiritKind, spiritType, templateUuid: opts.templateUuid ?? SR2Actor.spiritTemplateFor(spiritType)?.uuid ?? null, spiritUuid: null, element: elementIn, domain, ...(hostUuid ? { hostUuid } : {}), ...(drainLater ? { drainLater } : {}) } });
    await this.leaveSignature('summoning', tx('SR2E.Text.Actor.summoning', { name: what }), force);
    if (!drainLater) await this.#conjuringDrain(force, opts.drainPoolDice ?? 0);
    return result;
  }

  /**
   * v0.48.0: create an ally spirit by ritual (RULES.OCCULT.ally): an initiate's Conjuring (+ a
   * library, circle or lodge) vs Force; ritual materials from nuyen; any success creates the ally and
   * bonds it for Good Karma. It counts for the familiar ordeal of the next initiation.
   */
  async createAlly(opts: { force: number; spiritType?: string; templateUuid?: string | null; poolDice?: number; drainPoolDice?: number; payMaterials?: boolean }): Promise<SuccessTestResult | null> {
    if (!this.canAct('conjure')) return null;
    const blocked = traditionBlocks(this.tradition, 'conjure') ?? aspectRestriction(this.tradition, 'conjure', { aspectElement: this.sys.aspectElement, spiritKind: 'ally', spiritElement: '' });
    if (blocked) { ui.notifications?.warn?.(`${escHtml(this.name)}: ${escHtml(blocked)}`); return null; }
    const skill = this.#conjuringSkill();
    if (!skill) return null;
    const force = Math.max(1, Math.floor(Number(opts.force) || 1));
    const problem = allyProblem({ grade: this.initiate.grade, magic: Number(this.sys.derived?.magic ?? 0), force });
    if (problem) { ui.notifications?.warn?.(`${escHtml(this.name)}: ${problem}`); return null; }
    const c = allyCosts(force);
    const good = Number(this.sys.karma?.good ?? 0);
    if (good < c.karma) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.bondingAForceAllyCostsGood', { force, karma: c.karma, name: escHtml(this.name), good })); return null; }
    // v0.70.0: the ally's Karma (and materials) wait for the GM when the approval queue is on; the ritual runs on approval.
    if (approvalNeeded(this)) { await fileRequest(this, { kind: 'improve', label: tx('SR2E.Text.Actor.allyRitualForce', { spiritType: (opts.spiritType ?? '').trim() || 'Ally spirit', force }), karma: c.karma, ...(opts.payMaterials !== false && c.nuyen > 0 ? { nuyen: c.nuyen } : {}), data: { method: 'createAlly', args: [{ ...opts }] } }); return null; }
    if (opts.payMaterials !== false && c.nuyen > 0) {
      if (!(await this.adjustNuyen(-c.nuyen, tx('SR2E.Text.Actor.allyRitualMaterialsForce', { force })))) return null;
    }
    const a = RULES.OCCULT.ally;
    const site = a.siteDice ? (bestSite(this.magicSites(), isShamanic(this.tradition) ? 'lodge' : 'circle')?.rating ?? 0) : 0;
    const spiritType = (opts.spiritType ?? '').trim() || 'Ally spirit';
    this.#warnGeasa(tx('SR2E.Card.Actor.summons'));
    // v0.50.0: a shaman's totem environment counts here too, as when summoning.
    const envA = totemEnvironmentDice(this.tradition, this.sys.totem, this.environmentHere());
    const result = await this.#runTest(tx('SR2E.Card.Actor.allyRitualForceTn', { spiritType, force, tn: c.tn, part: site ? tx('SR2E.Card.Actor.site', { site }) : '', part2: envA.dice ? ` [${envA.note}]` : '', plural: plural(c.days, 'day'), part3: opts.payMaterials !== false && c.nuyen ? tx('SR2E.Card.Actor.materials2', { nuyen: c.nuyen }) : '' }), Math.max(0, skill.system.rating + site + envA.dice),
      { targetNumber: c.tn, poolDice: RULES.CONJURING.spellPoolAllowed ? opts.poolDice ?? 0 : 0, pool: 'spell', magical: true },
      { kind: 'conjure', conjure: { force, spiritKind: 'ally', spiritType, templateUuid: opts.templateUuid ?? SR2Actor.spiritTemplateFor(spiritType)?.uuid ?? null, spiritUuid: null, element: '', domain: '', ally: { karma: c.karma, days: c.days } } });
    await this.leaveSignature('summoning', tx('SR2E.Text.Actor.allyRitual', { spiritType }), force);
    await this.#conjuringDrain(force, opts.drainPoolDice ?? 0);
    return result;
  }

  /** An ally ritual's outcome: any success creates the ally (once) and bonds it for Good Karma. */
  /**
   * v0.81.1 (D2-3): the spirit (or ally) the GM already created from an earlier card of this test (its Create spirit
   * button stamps `spiritCreated` with the new actor's uuid), or null. A re-roll then adjusts that one, never asks
   * for a second.
   */
  static #spiritCreatedFor(testId: string | undefined, summoner: any = null): { spirit: any; services: number | null } | null {
    const summonerUuid = String(summoner?.uuid ?? '');
    if (!testId) return null;
    for (const m of [...(((game as any).messages?.contents ?? []) as any[])].slice(-300)) {
      const made = m.getFlag?.(SYSTEM_ID, 'spiritCreated');
      if (typeof made !== 'string' || !made) continue;
      if ((m.getFlag?.(SYSTEM_ID, 'test') as TestSnapshot | undefined)?.testId !== testId) continue;
      // Round 3 (V2 #3, FIX3-BRIEF 3): the GM's Create spirit writes the stamp onto the summoner's own card (its author
      // is the player), so a stamp counts on a card by a GM or by a user who owns the summoner; and the spirit must
      // exist and be this summoner's. (The services change still goes to an Apply (GM) card unless a GM is acting, and
      // the "changed since" check holds it to the stamp's value, so a forged stamp gains nothing.)
      const by = SR2Actor.#cardAuthorOf(m);
      if (!realGm(by) && !(summoner && userOwns(by, summoner))) continue;
      const a: any = fromUuidSync(made);
      if (!a || !isActorDoc(a)) continue;
      if (!summonerUuid || String(a.system?.summonerUuid ?? '') !== summonerUuid) continue;
      const pend = Number(m.getFlag?.(SYSTEM_ID, 'pendingSpirit')?.system?.services);
      return { spirit: a, services: Number.isFinite(pend) ? pend : null };
    }
    return null;
  }

  async #resolveAlly(snap: TestSnapshot): Promise<Resolved> {
    const c = snap.conjure as ConjureContext;
    const al = c.ally!;
    if (c.spiritUuid) return { html: `<p><em>${tx('SR2E.Card.Actor.theAllyAlreadyExistsARe')}</em></p>`, flags: {}, snap };
    // v0.81.1 (D2-3): the GM already created it from an earlier card of this test.
    const madeAlly = SR2Actor.#spiritCreatedFor(snap.testId, this)?.spirit;
    if (madeAlly) return { html: `<p><em>${tx('SR2E.Card.Actor.alreadyExistsAReRollChanges', { madeAllyName: escText(madeAlly.name) })}</em></p>`, flags: {}, snap: { ...snap, conjure: { ...c, spiritUuid: madeAlly.uuid } } };
    if (!(snap.successes > 0) && c.projectId) return { html: `<p><em>${tx('SR2E.Card.Actor.theRitualFailsNoAllyTakes')}</em>${await this.dropProjectOnFailure(c.projectId)}</p>`, flags: {}, snap: { ...snap, conjure: { ...c, projectId: undefined, ally: { ...al, charged: false } } as any } };
    if (!(snap.successes > 0)) return { html: `<p><em>${tx('SR2E.Card.Actor.theRitualFailsNoAllyTakes')}</em></p>`, flags: {}, snap };
    const data = await this.#spiritData(c, 0);
    data.name = `${c.spiritType || 'Ally'} (ally of ${this.name}, F${c.force})`;
    data.flags = { ...(data.flags ?? {}), [SYSTEM_ID]: { ...(data.flags?.[SYSTEM_ID] ?? {}), allyRitual: true } };
    data.prototypeToken = { ...(data.prototypeToken ?? {}), name: data.name };
    let next: TestSnapshot = snap;
    let karmaNote = '';
    let allyPaid = 0;
    if (!al.charged) {
      const good = Number(this.sys.karma?.good ?? 0);
      const paid = Math.min(good, al.karma);
      allyPaid = paid;
      await this.update({ 'system.karma.good': good - paid, 'system.ledger': this.#ledgerWith({ kind: 'karma', amount: -paid, reason: tx('SR2E.Text.Actor.bondingTheAlly', { name: data.name }) }) });
      karmaNote = tx('SR2E.Card.Actor.bondedForGoodKarma', { paid, part: paid < al.karma ? tx('SR2E.Card.Actor.short', { value: al.karma - paid }) : '' });
      next = { ...next, conjure: { ...c, ally: { ...al, charged: true } } };
    }
    // v0.65.0: the ally takes shape after its days (the Karma is paid now).
    if (this.waitsFor('magic') && !c.projectId) {
      const pr = await this.startProject({ kind: 'ally', area: 'magic', label: tx('SR2E.Text.Actor.theAllyRitualFor', { name: data.name }), hours: Number(al.days ?? 0) * 24, paid: { karma: allyPaid }, effect: { call: { method: 'finishAlly', args: [data] } } });
      return { html: `<p><strong>${escText(data.name)}</strong> ${tx('SR2E.Card.Actor.takesShapeAfterUpkeepTabUnder', { plural: escText(plural(al.days, 'day')), karmaNote })}</p>`, flags: {}, snap: { ...next, conjure: { ...(next.conjure as ConjureContext), projectId: pr.id } } };
    }
    if (c.projectId) return { html: `<p><em>${tx('SR2E.Card.Actor.theAllyRitualIsUnderWay')}</em></p>`, flags: {}, snap };
    const canCreate = canCreateActorNow();
    if (!canCreate) {
      return {
        html: `<p><strong>${escText(data.name)}</strong> ${tx('SR2E.Card.Actor.takesShapeAfter', { plural: escText(plural(al.days, 'day')), karmaNote })} <button type="button" data-sr2e-action="createSpirit">${tx('SR2E.Card.Actor.createSpiritGm')}</button></p>`,
        flags: { pendingSpirit: data }, snap: next,
      };
    }
    const cls: any = (Actor as any).implementation ?? Actor;
    const spirit: any = await cls.create(data);
    await this.setFlag(SYSTEM_ID, 'familiar', { allyUuid: spirit?.uuid ?? '', allyName: data.name, usedForGrade: null });
    return {
      html: `<p><strong>${escText(data.name)}</strong> ${tx('SR2E.Card.Actor.takesShapeAfterItCountsFor', { plural: escText(plural(al.days, 'day')), karmaNote })}</p>`,
      flags: {}, snap: { ...next, conjure: { ...(next.conjure as ConjureContext), spiritUuid: spirit?.uuid ?? null } },
    };
  }

  /** v0.65.0: an ally ritual's time has passed: the ally takes shape (and counts for the familiar ordeal). */
  async finishAlly(data: any): Promise<boolean> {
    const cls: any = (Actor as any).implementation ?? Actor;
    const spirit: any = await cls.create(data);
    if (!spirit) return false;
    await this.setFlag(SYSTEM_ID, 'familiar', { allyUuid: spirit.uuid ?? '', allyName: data.name, usedForGrade: null });
    return true;
  }

  /** v0.65.0: a ward's ritual time has passed: the ward rises (a barrier actor; a card offers to draw it). */
  async finishWard(data: any, name: string): Promise<boolean> {
    const cls: any = (Actor as any).implementation ?? Actor;
    const made: any = await cls.create(data);
    if (!made) return false;
    await ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor: this }), content: `<p><strong>${escText(name)}</strong> ${tx('SR2E.Card.Actor.aForceWardHasRisenIt', { rating: escText(data.system?.rating ?? '') })} <button type="button" data-sr2e-action="placeWard">${tx('SR2E.Card.Actor.drawItOnTheMap')}</button></p>`, flags: { [SYSTEM_ID]: { wardPlace: { barrierUuid: made.uuid, name } } } });
    return true;
  }

  /** Data for a new spirit actor from a summoning. */
  async #spiritData(c: ConjureContext, services: number): Promise<any> {
    const template: any = c.templateUuid ? await fromUuid(c.templateUuid) : null;
    const base: any = template?.toObject?.() ?? { system: {} };
    delete base._id;
    delete base.folder;
    delete base.sort;
    const typeName = c.spiritType || template?.system?.spiritType || template?.name || 'Spirit';
    // v0.61.0: an insect spirit in a host body (flesh form): its physical attributes from the host (offsets from Force).
    const host: any = c.hostUuid ? fromUuidSync(c.hostUuid) : null;
    const flesh = host && insectForm({ hostUuid: c.hostUuid ?? '' }) === 'flesh'
      ? fleshFormAttributes({ body: Number(host.system?.attributes?.body?.base ?? 0), quickness: Number(host.system?.attributes?.quickness?.base ?? 0), strength: Number(host.system?.attributes?.strength?.base ?? 0) }, c.force, insectRole(typeName)) : null;
    const offsets = flesh ? { ...(base.system?.offsets ?? {}), body: flesh.body - c.force, quickness: flesh.quickness - c.force, strength: flesh.strength - c.force } : base.system?.offsets;
    const name = `${typeName} (F${c.force})${host && flesh ? ` in ${host.name}` : ''}`;
    return {
      ...base,
      name,
      type: 'spirit',
      ownership: { ...(this.ownership ?? {}) },
      prototypeToken: { ...(base.prototypeToken ?? {}), name, actorLink: true },
      system: {
        ...(base.system ?? {}),
        force: c.force,
        spiritKind: c.spiritKind,
        spiritType: c.spiritType || template?.system?.spiritType || '',
        services,
        summonerUuid: this.uuid,
        element: c.element ?? base.system?.element ?? '',
        domain: c.domain ?? '',
        ...(offsets ? { offsets } : {}),
        ...(flesh ? { hostUuid: c.hostUuid, materialized: true } : {}),
        // v0.56.0: a nature spirit stays only until the next sunrise or sunset (RULES.MAGIC_V56.natureSpirits).
        departsAt: c.spiritKind === 'nature' && RULES.MAGIC_V56.natureSpirits.departs === 'dawnDusk' ? nextDawnOrDusk(sysNow()).at : -1,
        monitor: { physical: 0, stun: 0 },
        poolSpent: { combat: 0, spell: 0, spellConc: 0, spellSpec: 0 },
      },
    };
  }

  async #resolveConjure(snap: TestSnapshot): Promise<Resolved> {
    const c = snap.conjure as ConjureContext;
    if (c.ally) return this.#resolveAlly(snap);
    const services = servicesForSuccesses(snap.successes);
    const next = (patch: Partial<ConjureContext>) => ({ ...snap, conjure: { ...(snap.conjure as ConjureContext), ...patch } });

    // v0.71.0 (R20): the drain a deferred summoning still owes, rolled now (it failed) and marked done.
    const drainNow = async (): Promise<ConjureContext> => {
      if (!c.drainLater || c.drainLater.done) return c;
      await this.#conjuringDrain(c.drainLater.force, c.drainLater.pool);
      return { ...c, drainLater: { ...c.drainLater, done: true } };
    };
    const owedDrain = c.drainLater && !c.drainLater.done ? { force: c.drainLater.force, pool: c.drainLater.pool } : null;
    // v0.65.0: an elemental summoning still under way: a re-roll changes the services it will owe.
    if (c.projectId && services <= 0) {
      // v0.71.0 review (F5): giving the project up rolls its owed drain (its onCancel), so it isn't rolled twice here.
      const had = this.projects().some((x) => x.id === c.projectId);
      const dropped = await this.dropProjectOnFailure(c.projectId);
      const c2 = had && c.drainLater ? { ...c, drainLater: { ...c.drainLater, done: true } } : await drainNow();
      return { html: `<p><em>${tx('SR2E.Card.Actor.theSummoningFailedNoSpiritAnswers')}</em>${dropped}</p>`, flags: {}, snap: { ...snap, conjure: { ...c2, projectId: undefined } } };
    }
    if (c.projectId) {
      const p = this.projects().find((x) => x.id === c.projectId);
      if (!p) return { html: `<p><em>${tx('SR2E.Card.Actor.theSummoningIsOverOrWas')}</em></p>`, flags: {}, snap };
      const data = await this.#spiritData(c, services);
      await this.update({ [`flags.${SYSTEM_ID}.projects.${p.id}`]: { ...p, effect: { call: { method: 'finishElemental', args: owedDrain ? [data, owedDrain] : [data] } } } });
      return { html: `<p><strong>${escText(data.name)}</strong> ${tx('SR2E.Card.Actor.willOwe')} <strong>${services}</strong> ${tCount(services, 'SR2E.Card.Actor.servicesWhenTheSummoningIsDone')}</p>`, flags: {}, snap };
    }

    if (c.spiritUuid) {
      // A Karma re-roll of a summoning that already produced a spirit: adjust its services.
      const spirit: any = await fromUuid(c.spiritUuid);
      if (!spirit) return { html: `<p><em>${tx('SR2E.Card.Actor.theSummonedSpiritNoLongerExists')}</em></p>`, flags: {}, snap };
      if (spirit.system.services !== (c.servicesAfter ?? 0)) {
        return {
          html: `<p><em>${tx('SR2E.Card.Actor.sServicesChangedSinceThisWas', { spiritName: escText(spirit.name), services })}</em></p>`,
          flags: {}, snap: next({ servicesAfter: services }),
        };
      }
      await spirit.update({ 'system.services': services });
      const html = services > 0
        ? `<p><strong>${escText(spirit.name)}</strong> ${tx('SR2E.Card.Actor.nowOwes')} <strong>${services}</strong> ${tCount(services, 'SR2E.Card.Actor.services')}</p>`
        : `<p><strong>${escText(spirit.name)}</strong> ${tx('SR2E.Card.Actor.owesNoServicesDismissItFrom')}</p>`;
      return { html, flags: {}, snap: next({ servicesAfter: services }) };
    }

    // v0.81.1 (D2-3): the GM already created this summoning's spirit from an earlier card (Create spirit): a re-roll
    // changes its services (as above), it never posts a second Create spirit button.
    const found = SR2Actor.#spiritCreatedFor(snap.testId, this);
    if (found) {
      const made = found.spirit;
      const n = Math.max(0, services);
      // Round 2 (V-DOC 4, FIX2-BRIEF H4): "changed since": the spirit must still owe what the created card gave it
      // (services used meanwhile are not given back by a re-roll).
      const expected = c.servicesAfter ?? found.services;
      if (expected === null || expected === undefined || Number(made.system?.services ?? 0) !== Number(expected)) {
        return { html: `<p><em>${tx('SR2E.Card.Actor.sServicesChangedSinceItWas', { madeName: escText(made.name), n })}</em></p>`, flags: {}, snap: next({ spiritUuid: made.uuid, servicesAfter: Number(made.system?.services ?? 0) }) };
      }
      // A GM's card (or a GM acting) writes it; a player's re-roll asks the GM (an Apply card), owner or not.
      const direct = isGmNow();
      if (direct) await made.update({ 'system.services': n });
      else await SR2Actor.gmActorCard(made.uuid, { handSpirit: { toUuid: String(made.system?.summonerUuid || this.uuid), services: n, oldSummonerUuid: String(made.system?.summonerUuid || this.uuid) }, by: this.uuid as string }, tx('SR2E.Card.Actor.owes', { madeName: escText(made.name), plural: plural(n, 'service') }));
      const html = n > 0
        ? `<p><strong>${escText(made.name)}</strong> ${tx('SR2E.Card.Actor.nowOwes')} <strong>${n}</strong> ${tCount(n, 'SR2E.Card.Actor.services2', { part: direct ? '' : tx('SR2E.Card.Actor.theGmAppliesIt2') })}</p>`
        : `<p><strong>${escText(made.name)}</strong> ${tx('SR2E.Card.Actor.owesNoServicesDismissItFrom2', { part: direct ? '' : tx('SR2E.Card.Actor.theGmAppliesIt2') })}</p>`;
      return { html, flags: {}, snap: next({ spiritUuid: made.uuid, servicesAfter: n }) };
    }

    if (services <= 0) {
      const c2 = await drainNow();
      return { html: `<p><em>${tx('SR2E.Card.Actor.theSummoningFailedNoSpiritAnswers')}</em></p>`, flags: {}, snap: { ...snap, conjure: c2 } };
    }

    const data = await this.#spiritData(c, services);
    const owes = `${tx('SR2E.Card.Actor.owing')} <strong>${services}</strong> ${tCount(services, 'SR2E.Card.Actor.services3')}`;
    // v0.65.0: an elemental takes its hours of ritual (Force × hours per Force) to arrive.
    if (c.spiritKind === 'elemental' && this.waitsFor('magic')) {
      const hours = bindingCost(c.force).hours;
      // v0.71.0 review (F5): given up, the ritual still costs its drain.
      const pr = await this.startProject({ kind: 'elemental', area: 'magic', label: tx('SR2E.Text.Actor.summoning', { name: data.name }), hours, effect: { call: { method: 'finishElemental', args: owedDrain ? [data, owedDrain] : [data] } }, ...(owedDrain ? { onCancel: { call: { method: 'giveUpElemental', args: [owedDrain] } } } : {}) });
      return { html: `<p>${tx('SR2E.Card.Actor.theRitualFor')} <strong>${escText(data.name)}</strong> ${tx('SR2E.Card.Actor.isUnderWayHItArrives', { hours, owes, part: owedDrain ? tx('SR2E.Card.Actor.andTheConjuringDrainComesThen') : '' })}</p>`, flags: {}, snap: next({ projectId: pr.id }) };
    }
    // Not waiting after all (the rule changed in between): the drain owed comes now.
    if (owedDrain) { const c2 = await drainNow(); snap = { ...snap, conjure: c2 }; }
    const canCreate = canCreateActorNow();
    if (!canCreate) {
      return {
        html: `<p><strong>${escText(data.name)}</strong> ${tx('SR2E.Card.Actor.answers', { owes })} <button type="button" data-sr2e-action="createSpirit">${tx('SR2E.Card.Actor.createSpiritGm')}</button></p>`,
        flags: { pendingSpirit: data }, snap,
      };
    }
    const cls: any = (Actor as any).implementation ?? Actor;
    const spirit: any = await cls.create(data);
    return {
      html: `<p><strong>${escText(data.name)}</strong> ${tx('SR2E.Card.Actor.answersDragItFromTheActors', { owes })}</p>`,
      flags: {}, snap: next({ spiritUuid: spirit?.uuid ?? null, servicesAfter: services }),
    };
  }

  /** v0.71.0 review (F5): a timed elemental summoning given up: its conjuring drain is still resisted. */
  async giveUpElemental(drain: { force: number; pool: number } | null = null): Promise<boolean> {
    if (drain && Number(drain.force) > 0) await this.#conjuringDrain(Number(drain.force), Number(drain.pool) || 0);
    return true;
  }

  /** v0.65.0: an elemental's summoning time has passed: it arrives (the GM's client makes the actor). */
  async finishElemental(data: any, drain: { force: number; pool: number } | null = null): Promise<boolean> {
    const cls: any = (Actor as any).implementation ?? Actor;
    const spirit: any = await cls.create(data);
    // v0.71.0 (R20): the conjuring drain comes as the ritual ends (RULES.FIXES_V71.conjureDrainAtEnd).
    if (drain && Number(drain.force) > 0) await this.#conjuringDrain(Number(drain.force), Number(drain.pool) || 0);
    return Boolean(spirit);
  }

  /**
   * Banish a spirit: Conjuring vs TN = its Force, opposed by its Force dice vs this actor's Magic.
   * Each net success lowers its Force by 1. Conjuring drain for its starting Force follows.
   */
  async banish(spirit: any, opts: { poolDice?: number; drainPoolDice?: number; exclude?: string[];
    /** v0.56.0: try to take control of the spirit instead of banishing it (RULES.MAGIC_V56.control). */
    control?: boolean } = {}): Promise<SuccessTestResult | null> {
    if (!this.canAct('banish')) return null;
    if (!spirit || spirit.type !== 'spirit') {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.onlySpiritActorsCanBeBanished'));
      return null;
    }
    const force = spirit.system.force as number;
    if (force <= 0) {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.isAlreadyBanished', { spiritName: escHtml(spirit.name) }));
      return null;
    }
    await this.spotInvisible([spirit]);
    if (RULES.TN_AUTO.magic.lineOfSight === 'block' && this.#unseenTargets([spirit]).length) {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.hasNoLineOfSightTo2', { name: escHtml(this.name), spiritName: escHtml(spirit.name) }));
      return null;
    }
    const skill = this.#conjuringSkill();
    if (!skill) return null;

    // The spirit resists first, so its successes are known when the banisher's card resolves.
    const magic = this.sys.derived.magic as number;
    const spiritRolls: any[] = [];
    const control = Boolean(opts.control) && RULES.MAGIC_V56.control.enabled;
    if (control && this.selfUuids().includes(String(spirit.system.summonerUuid ?? ''))) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.isAlreadyS', { spiritName: escHtml(spirit.name), name: escHtml(this.name) })); return null; }
    const resistDice = banishResistDice(force, spirit.system.spiritKind, spirit.system.spiritEnergy ?? 0);
    const resist = await successTest({ dice: resistDice, targetNumber: magic, roll: foundryRoller(spiritRolls) });
    const energy = resistDice > force ? tx('SR2E.Card.Actor.spiritEnergy', { value: resistDice - force }) : '';
    await spirit.#post(spirit.#snapshot(tx('SR2E.Card.Actor.resistForceVsSMagic', { part: control ? tx('SR2E.Card.Actor.beingTakenOver') : tx('SR2E.Card.Actor.banishing'), force, energy, name: this.name, magic }), resist, { kind: 'plain' }), resist, spiritRolls);
    // v0.56.0: a bound spirit's summoner helps it resist: their conjuring successes vs the banisher's Magic add to its own.
    let help = 0;
    const summoner: any = spirit.system.summonerUuid ? fromUuidSync(spirit.system.summonerUuid) : null;
    if (summoner && summoner.uuid !== this.uuid && RULES.MAGIC_V56.control.summonerHelps && typeof summoner.helpResistBanishing === 'function' && (spirit.system.services ?? 0) > 0) {
      help = await summoner.helpResistBanishing(spirit, magic);
    }

    const pool = RULES.CONJURING.spellPoolAllowed ? opts.poolDice ?? 0 : 0;
    const extra = bonusNote(conjuringFocusDice(this.foci(), null), totemConjuringDice(this.tradition, this.sys.totem, { kind: spirit.system.spiritKind, type: spirit.system.spiritType ?? '', domain: spirit.system.domain ?? '' }));
    // v0.50.0: a shaman's totem environment counts when banishing too.
    const envB = totemEnvironmentDice(this.tradition, this.sys.totem, this.environmentHere());
    if (envB.dice) { extra.dice += envB.dice; extra.note = extra.note ? extra.note.replace(/\]$/, `, ${envB.note}]`) : ` [${envB.note}]`; }
    const result = await this.#runTest(tx('SR2E.Card.Actor.tnForce', { part: control ? tx('SR2E.Card.Actor.takeControlOf') : tx('SR2E.Card.Actor.banish'), spiritName: spirit.name, force, extraNote: extra.note }), Math.max(0, skill.system.rating + extra.dice),
      { targetNumber: force, poolDice: pool, pool: 'spell', magical: true, ...(opts.exclude?.length ? { exclude: opts.exclude } : {}) },
      { kind: 'banish', banish: { spiritUuid: spirit.uuid, spiritName: spirit.name, spiritSuccesses: resist.successes + help, forceBefore: force,
        ...(help ? { help } : {}), ...(control ? { control: true, servicesBefore: Number(spirit.system.services ?? 0), summonerBefore: String(spirit.system.summonerUuid ?? '') } : {}) } });
    await this.leaveSignature('banishing', tx('SR2E.Text.Actor.banishing', { name: spirit.name }), force);
    await this.#conjuringDrain(force, opts.drainPoolDice ?? 0);
    return result;
  }

  async #resolveBanish(snap: TestSnapshot): Promise<Resolved> {
    const b = snap.banish as BanishContext;
    if (b.control) return this.#resolveControl(snap);
    const outcome = resolveBanishing({ banisherSuccesses: snap.successes, spiritSuccesses: b.spiritSuccesses, force: b.forceBefore });
    const spirit: any = await fromUuid(b.spiritUuid);
    const expected = b.forceAfter ?? b.forceBefore;
    let note = '';
    // v0.81.0 (D2-3): what the spirit's Force is after this card (what a later re-roll compares against).
    let after = expected;
    if (!spirit) note = ` <em>${tx('SR2E.Card.Actor.theSpiritNoLongerExists')}</em>`;
    else if (spirit.system.force !== expected) {
      note = ` <em>${tx('SR2E.Card.Actor.sForceChangedSinceThisWas', { spiritName: escText(spirit.name), outcomeForce: outcome.force })}</em>`;
    } else if (!canWriteNow(spirit)) {
      // Someone else's spirit: an Apply (GM) card (only down, and only while it still has this Force).
      if (outcome.force < spirit.system.force) await SR2Actor.gmActorCard(spirit.uuid, { lower: { key: 'force', from: spirit.system.force, to: outcome.force }, by: this.uuid as string }, tx('SR2E.Card.Actor.banishesForce', { name: escText(this.name), spiritName: escText(spirit.name), spiritForce: spirit.system.force, outcomeForce: outcome.force }));
      note = ` <em>${tx('SR2E.Card.Actor.isnTYoursTheGmApplies2', { spiritName: escText(spirit.name), outcomeForce: outcome.force })}</em>`;
    } else if (outcome.force !== spirit.system.force) {
      await spirit.update({ 'system.force': outcome.force });
      after = outcome.force;
    }
    const lead = tx('SR2E.Card.Actor.vs', { successes: snap.successes, spiritSuccesses: b.spiritSuccesses });
    const sn = escText(b.spiritName);
    const body = outcome.banished
      ? `<strong>${tx('SR2E.Card.Actor.isBanished', { sn })}</strong> (${lead})`
      : outcome.netSuccesses > 0
        ? `<strong>${tx('SR2E.Card.Actor.weakens', { sn })}</strong> ${tx('SR2E.Card.Actor.force2', { forceBefore: b.forceBefore, outcomeForce: outcome.force, lead })}`
        : `<strong>${tx('SR2E.Card.Actor.holds2', { sn })}</strong> (${lead})`;
    return { html: `<p>${body}${note}</p>`, flags: {}, snap: { ...snap, banish: { ...b, forceAfter: after } } };
  }

  /** v0.56.0: a summoner's conjuring test to help their bound spirit resist banishing; returns the successes. */
  async helpResistBanishing(spirit: any, banisherMagic: number): Promise<number> {
    const skill = this.#conjuringSkill(true);
    const dice = Number(skill?.system?.rating ?? 0);
    if (!(dice > 0)) return 0;
    const rolls: any[] = [];
    const r = await successTest({ dice, targetNumber: Math.max(RULES.MIN_TARGET_NUMBER, banisherMagic), roll: foundryRoller(rolls) });
    const add = banishHelp(r.successes);
    await ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor: this }), rolls,
      content: `${describeResult(tx('SR2E.Card.Actor.helpsResistVsMagic', { name: this.name, spiritName: spirit.name, skillName: skill.name, banisherMagic }), r)}<p>${tx('SR2E.Card.Actor.adds')} <strong>${add}</strong> ${tx('SR2E.Card.Actor.toTheSpiritSSuccesses')}</p>` });
    return add;
  }

  /** v0.56.0: taking control of someone else's spirit: with net successes it becomes this magician's (applied once). */
  async #resolveControl(snap: TestSnapshot): Promise<Resolved> {
    const b = snap.banish as BanishContext;
    const net = Math.max(0, snap.successes - b.spiritSuccesses);
    const services = controlServices(net, b.servicesBefore ?? 0);
    const spirit: any = await fromUuid(b.spiritUuid);
    const lead = tx('SR2E.Card.Actor.vs2', { successes: snap.successes, spiritSuccesses: b.spiritSuccesses, part: b.help ? tx('SR2E.Card.Actor.itsSummonerAdded', { help: b.help }) : '' });
    if (!spirit) return { html: `<p><em>${tx('SR2E.Card.Actor.theSpiritNoLongerExists')}</em></p>`, flags: {}, snap };
    if (net <= 0) {
      // A re-roll that turns a win into a loss gives the spirit back.
      let back = '';
      if (b.taken) {
        if (spirit.system.summonerUuid === this.uuid) await SR2Actor.handSpirit(spirit, b.summonerBefore ? fromUuidSync(b.summonerBefore) : null, b.servicesBefore ?? 0, this.uuid as string, tx('SR2E.Card.Actor.goesBackToItsOldMaster', { spiritName: escText(spirit.name) }));
        else back = ` <em>${tx('SR2E.Card.Actor.changedHandsSinceSoItWas', { spiritName: escText(spirit.name) })}</em>`;
      }
      return { html: `<p><strong>${tx('SR2E.Card.Actor.staysItsOwnMasterS', { spiritName: escText(b.spiritName) })}</strong> (${lead})${back}</p>`, flags: {}, snap: { ...snap, banish: { ...b, taken: false } } };
    }
    let note = '';
    if (b.taken && spirit.system.summonerUuid !== this.uuid) note = ` <em>${tx('SR2E.Card.Actor.changedHandsSinceThisWasRolled', { spiritName: escText(spirit.name) })}</em>`;
    else if (!b.taken || spirit.system.services !== services) {
      const done = await SR2Actor.handSpirit(spirit, this, services, String(b.summonerBefore ?? ''), tx('SR2E.Card.Actor.becomesSOwing', { spiritName: escText(spirit.name), name: escText(this.name), plural: plural(services, 'service') }));
      if (!done) note = ` <em>${tx('SR2E.Card.Actor.theGmAppliesTheChange')}</em>`;
    }
    return { html: `<p><strong>${tx('SR2E.Card.Actor.takesControlOf', { name: escText(this.name), spiritName: escText(b.spiritName) })}</strong>${tx('SR2E.Card.Actor.itOwes', { plural: escText(plural(services, 'service')), lead, note })}</p>`, flags: {}, snap: { ...snap, banish: { ...b, taken: true } } };
  }

  /**
   * v0.56.0: bind a free spirit by its true name (RULES.MAGIC_V56.trueName): the name must match the one on
   * the spirit's sheet; conjuring skill vs its Force, opposed by its Force + spirit energy vs Magic; net
   * successes become services and it costs Good Karma.
   */
  async bindByTrueName(spirit: any, name: string, opts: { poolDice?: number; drainPoolDice?: number } = {}): Promise<SuccessTestResult | null> {
    if (!spirit || spirit.type !== 'spirit') return null;
    const truth = String(spirit.system.trueName ?? '').trim().toLowerCase();
    if (!truth || truth !== String(name ?? '').trim().toLowerCase()) {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.thatIsNotSTrueName', { spiritName: escHtml(spirit.name) }));
      return null;
    }
    if (this.selfUuids().includes(String(spirit.system.summonerUuid ?? ''))) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.isAlreadyBoundTo', { spiritName: escHtml(spirit.name), name: escHtml(this.name) })); return null; }
    const skill = this.#conjuringSkill();
    if (!skill) return null;
    const force = Number(spirit.system.force ?? 1);
    // v0.70.0: the binding's Karma waits for the GM when the approval queue is on; the test runs on approval.
    if (approvalNeeded(this)) { await fileRequest(this, { kind: 'improve', label: tx('SR2E.Text.Actor.bindByItsTrueName', { name: spirit.name }), karma: force * RULES.MAGIC_V56.trueName.karmaPerForce, data: { method: 'bindByTrueName', args: [spirit.uuid, name, { ...opts }] } }); return null; }
    const magic = Number(this.sys.derived?.magic ?? 0);
    const rolls: any[] = [];
    const resistDice = banishResistDice(force, spirit.system.spiritKind, spirit.system.spiritEnergy ?? 0);
    const resist = await successTest({ dice: resistDice, targetNumber: Math.max(RULES.MIN_TARGET_NUMBER, magic), roll: foundryRoller(rolls) });
    await ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor: spirit }), rolls, content: describeResult(tx('SR2E.Card.Actor.resistsTheBindingDiceVsMagic', { spiritName: spirit.name, resistDice, magic }), resist) });
    const karma = force * RULES.MAGIC_V56.trueName.karmaPerForce;
    const result = await this.#runTest(tx('SR2E.Card.Actor.bindByItsTrueNameTn', { spiritName: spirit.name, force, karma }), Math.max(0, skill.system.rating),
      { targetNumber: force, poolDice: RULES.CONJURING.spellPoolAllowed ? opts.poolDice ?? 0 : 0, pool: 'spell', magical: true },
      { kind: 'bindName', bindName: { spiritUuid: spirit.uuid as string, spiritName: spirit.name as string, force, spiritSuccesses: resist.successes, summonerBefore: String(spirit.system.summonerUuid ?? ''), servicesBefore: Number(spirit.system.services ?? 0) } });
    await this.leaveSignature('summoning', tx('SR2E.Text.Actor.binding', { name: spirit.name }), force);
    await this.#conjuringDrain(force, opts.drainPoolDice ?? 0);
    return result;
  }

  async #resolveBindName(snap: TestSnapshot): Promise<Resolved> {
    const b = snap.bindName!;
    const o = trueNameOutcome(snap.successes, b.spiritSuccesses, b.force);
    const spirit: any = await fromUuid(b.spiritUuid);
    const lead = tx('SR2E.Card.Actor.vs', { successes: snap.successes, spiritSuccesses: b.spiritSuccesses });
    if (!o.bound) {
      // A re-roll that turns a binding into a failure: the Karma comes back and the spirit goes free again.
      let undo = '';
      if (b.applied) {
        const good = Number(this.sys.karma?.good ?? 0);
        if (b.paid) await this.update({ 'system.karma.good': good + b.paid, 'system.ledger': this.#ledgerWith({ kind: 'karma', amount: b.paid, reason: `Binding ${b.spiritName} undone` }) });
        if (spirit && spirit.system.summonerUuid === this.uuid) await SR2Actor.handSpirit(spirit, b.summonerBefore ? fromUuidSync(b.summonerBefore) : null, b.servicesBefore ?? 0, this.uuid as string, tx('SR2E.Card.Actor.isFreeAgain', { spiritName: escText(spirit.name) }));
        undo = ` <em>${(b.paid ? tx('SR2E.Card.Actor.theBindingIsUndoneWithAndGoodKarmaRefunded', { paid: b.paid }) : tx('SR2E.Card.Actor.theBindingIsUndonePlain'))}</em>`;
      }
      return { html: `<p><strong>${tx('SR2E.Card.Actor.resistsTheBinding', { spiritName: escText(b.spiritName) })}</strong> (${lead})${undo}</p>`, flags: {}, snap: { ...snap, bindName: { ...b, applied: false, paid: 0 } } };
    }
    if (b.applied) {
      if (spirit && spirit.system.summonerUuid === this.uuid && spirit.system.services !== o.services) await SR2Actor.handSpirit(spirit, this, o.services, String(b.summonerBefore ?? ''), tx('SR2E.Card.Actor.owes2', { spiritName: escText(spirit.name), plural: plural(o.services, 'service') }));
      return { html: `<p><strong>${tx('SR2E.Card.Actor.isBound', { spiritName: escText(b.spiritName) })}</strong> ${tx('SR2E.Card.Actor.andOwes', { plural: escText(plural(o.services, 'service')), lead })}</p>`, flags: {}, snap };
    }
    let note = '';
    const good = Number(this.sys.karma?.good ?? 0);
    const paid = Math.min(good, o.karma);
    await this.update({ 'system.karma.good': good - paid, 'system.ledger': this.#ledgerWith({ kind: 'karma', amount: -paid, reason: tx('SR2E.Text.Actor.bindingByItsTrueName', { name: b.spiritName }) }) });
    if (paid < o.karma) note += ` <em>${tx('SR2E.Card.Actor.goodKarmaShort', { value: o.karma - paid })}</em>`;
    if (!spirit) note += ` <em>${tx('SR2E.Card.Actor.theSpiritNoLongerExists')}</em>`;
    else if (!(await SR2Actor.handSpirit(spirit, this, o.services, String(b.summonerBefore ?? ''), tx('SR2E.Card.Actor.isBoundToOwing', { spiritName: escText(spirit.name), name: escText(this.name), plural: plural(o.services, 'service') })))) note += ` <em>${tx('SR2E.Card.Actor.theGmAppliesTheBinding')}</em>`;
    return { html: `<p><strong>${tx('SR2E.Card.Actor.bindsByItsTrueName', { name: escText(this.name), spiritName: escText(b.spiritName) })}</strong>${tx('SR2E.Card.Actor.itOwesGoodKarma', { plural: escText(plural(o.services, 'service')), paid, lead, note })}</p>`, flags: {}, snap: { ...snap, bindName: { ...b, applied: true, paid } } };
  }

  /** The background count of the scene being viewed (0 if none). */
  static backgroundCount(at: any = null): number {
    const scene = at ?? game.scenes?.viewed ?? game.scenes?.current;
    return Number(scene?.getFlag?.(SYSTEM_ID, 'backgroundCount') ?? 0) || 0;
  }

  /** GM: set the background count of the scene being viewed. */
  static async setBackgroundCount(value: number): Promise<void> {
    const scene = game.scenes?.viewed ?? game.scenes?.current;
    if (!scene) {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.openASceneFirstBackgroundCount'));
      return;
    }
    await scene.setFlag(SYSTEM_ID, 'backgroundCount', Math.floor(value) || 0);
  }

  /** The scene an action happens in: the one being viewed, else the active one. */
  static currentSceneId(): string {
    return game.scenes?.viewed?.id ?? game.scenes?.current?.id ?? '';
  }

  /** Leave an astral signature at the current scene (kept on this actor, faded ones pruned). */
  async leaveSignature(kind: string, label: string, force: number): Promise<void> {
    const sceneId = SR2Actor.currentSceneId();
    if (!sceneId || !(force > 0)) return;
    const now = sysNow();
    const mask = maskingModifiers(this.initiate.grade, this.initiate.techniques)[0]?.value ?? 0;
    const sig: Signature & { masking?: number } = { id: `${Date.now().toString(36)}${Math.random().toString(36).slice(2, 6)}`, sceneId, kind, label, force, worldTime: now, ...(mask ? { masking: mask } : {}) };
    const list = pruneSignatures([...((this.getFlag(SYSTEM_ID, 'signatures') as Signature[] | undefined) ?? []), sig], now);
    try {
      await this.setFlag(SYSTEM_ID, 'signatures', list);
    } catch (err) {
      console.warn(`sr2e | Could not record ${this.name}'s astral signature`, err);
    }
  }

  /** Signatures still lingering at a scene, from every actor in the world, newest first. */
  static signaturesAt(sceneId: string): Array<Signature & { actorUuid: string; actorName: string; ageHours: number; hoursLeft: number }> {
    const now = sysNow();
    const out: any[] = [];
    for (const a of allActors()) {
      const sigs = (a.getFlag?.(SYSTEM_ID, 'signatures') as Signature[] | undefined) ?? [];
      for (const s of sigs) {
        if (s.sceneId !== sceneId || signatureHoursLeft(s, now) <= 0) continue;
        out.push({ ...s, actorUuid: a.uuid, actorName: a.name, ageHours: signatureAgeHours(s, now), hoursLeft: signatureHoursLeft(s, now) });
      }
    }
    return out.sort((x, y) => y.worldTime - x.worldTime);
  }

  /** Forget every signature this actor left at a scene (GM tidy-up). */
  async clearSignatures(sceneId: string): Promise<void> {
    const sigs = (this.getFlag(SYSTEM_ID, 'signatures') as Signature[] | undefined) ?? [];
    await this.setFlag(SYSTEM_ID, 'signatures', sigs.filter((s) => s.sceneId !== sceneId));
  }

  /**
   * Astral tracking: follow a signature (or any trail the GM describes) back to its source. Rolls
   * the tracking attribute vs the TN plus a freshness modifier; the card gives the time it takes.
   * The GM is whispered whose signature it is.
   */
  async track(opts: { signature?: (Signature & { actorName?: string; masking?: number }) | null; targetNumber?: number; baseHours?: number; label?: string } = {}): Promise<SuccessTestResult | null> {
    if (!this.isAstral()) {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.mustBePerceivingOrProjectingAstrally2', { name: escHtml(this.name) }));
      return null;
    }
    const sig = opts.signature ?? null;
    const now = sysNow();
    // A signature on an object doesn't fade like one left at a scene (v0.39.0).
    // v0.61.0: a magical link (MAGIC_V61.links) doesn't fade; its own TN modifiers.
    const link = (sig as any)?.link ? linkTrackTest({ dice: 0, kind: String((sig as any).link), force: Number(sig!.force ?? 1) }) : null;
    const mods = sig ? [...((sig as any).onObject ? [] : freshnessModifier(signatureAgeHours(sig, now))), ...(link?.modifiers ?? []), ...(sig.masking ? [{ id: 'masking', label: tx('SR2E.Card.Mod.masking'), value: sig.masking }] : [])] : [];
    // v0.80.0 (RULES.URR_V80.magTrackRating, URR): −2 / +2 by the Force against the tracker's Sorcery.
    if (sig) mods.push(...urrMagTrackingMods(Number(sig.force ?? 0), Number(this.findSkill('Sorcery')?.system?.rating ?? 0)));
    const label = opts.label ?? (sig ? `${sig.label}, Force ${sig.force}` : 'astral trail');
    const attr = RULES.TRACKING.trackingAttribute as AttributeKey;
    const baseHours = opts.baseHours ?? RULES.TRACKING.baseHours;
    const result = await this.#runTest(tx('SR2E.Card.Actor.astralTracking', { label }), this.sys.attributes[attr].total as number, {
      targetNumber: opts.targetNumber ?? RULES.TRACKING.trackingTn, modifiers: mods, background: true,
    }, { kind: 'track', track: { label, baseHours } });
    if (sig?.actorName && result.successes > 0) {
      const gms = [...(game.users ?? [])].filter((u: any) => u.isGM).map((u: any) => u.id);
      await ChatMessage.create({
        speaker: ChatMessage.getSpeaker({ actor: this }),
        content: `<p><em>${tx('SR2E.Card.Actor.gmOnly2')}</em> ${tx('SR2E.Card.Actor.sTrailLeadsTo', { name: escText(this.name), label: escText(label) })} <strong>${escText(sig.actorName)}</strong>.${SR2Actor.#planesNote((sig as any).actorUuid)}</p>`,
        whisper: gms, ...(isGmNow() ? {} : { blind: true }),
      });
    }
    return result;
  }

  /**
   * v0.61.0: magical links on an actor an astral tracker can follow back to the magician (MAGIC_V61.links):
   * spells someone sustains on them, a bound spirit's summoner, and active foci they carry.
   */
  static magicalLinksOn(target: any): Array<Signature & { label: string; actorName: string; actorUuid: string; link: string; onObject: boolean; ageHours: number; hoursLeft: number }> {
    if (!target) return [];
    const out: any[] = [];
    const me = new Set<string>(target.selfUuids?.() ?? [target.uuid]);
    for (const c of SR2Actor.tickActors()) {
      for (const e of ((c as any).system?.sustaining ?? []) as any[]) {
        if (!(e.targetUuids ?? []).some((u: string) => me.has(u)) || c === target) continue;
        out.push({ link: 'spell', label: tx('SR2E.Text.Actor.linkOn', { spellName: e.spellName, name: target.name }), force: Number(e.force ?? 1), actorUuid: c.uuid, actorName: c.name, onObject: true, ageHours: 0, hoursLeft: Infinity });
      }
    }
    if (target.type === 'spirit' && target.system?.summonerUuid) {
      const m: any = fromUuidSync(target.system.summonerUuid);
      if (m) out.push({ link: 'spirit', label: tx('SR2E.Text.Actor.linkBoundToItsSummoner', { name: target.name }), force: Number(target.system.force ?? 1), actorUuid: m.uuid, actorName: m.name, onObject: true, ageHours: 0, hoursLeft: Infinity });
    }
    for (const it of [...(target.items ?? [])] as any[]) {
      if (it.type === 'focus' && it.system?.active && it.system?.bonded) out.push({ link: 'focus', label: tx('SR2E.Text.Actor.linkActiveFocus', { name: it.name }), force: Number(it.system.rating ?? 1), actorUuid: target.uuid, actorName: target.name, onObject: true, ageHours: 0, hoursLeft: Infinity });
    }
    return out;
  }

  /** Tracking across planes (v0.39.0): where a projecting or physical owner's trail goes on to. */
  static #planesNote(uuid: string | undefined): string {
    const a: any = uuid ? fromUuidSync(uuid) : null;
    const mode = a?.system?.derived?.astralMode;
    if (mode === 'projecting') return tx('SR2E.Card.Actor.theyAreProjectingTheTrailLeads');
    if (a?.type === 'spirit' && a.system?.materialized === false) return tx('SR2E.Card.Actor.itIsOnTheAstralPlane');
    return '';
  }

  /** Geasa on this actor. */
  geasa(): Geas[] {
    return [...(this.sys.geasa ?? [])];
  }

  async setGeasa(list: Geas[]): Promise<void> {
    await this.update({ 'system.geasa': list });
  }

  /** Warn (once per action) about unmet geasa that should be checked before casting or summoning. */
  #warnGeasa(what: string): void {
    const unmet = unmetCastingGeasa(this.geasa());
    if (unmet.length) {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.withNotMetMagicIs', { name: escHtml(this.name), what, part: unmet.length === 1 ? tx('SR2E.Notify.Actor.aGeas') : tx('SR2E.Notify.Actor.geasa', { unmetLength: unmet.length }), map: escHtml(unmet.map((g) => g.text || tx('SR2E.Notify.Actor.unnamed')).join('; ')), derivedMagic: escHtml(this.sys.derived.magic) }));
    }
  }

  /** Apply (or, on a re-roll, correct) magical healing. */
  async #resolveHeal(snap: TestSnapshot, gmApply = false): Promise<Resolved> {
    const h = snap.heal!;
    const patient: any = await fromUuid(h.targetUuid);
    // v0.79.0: a healing stage (h.stages, RULES.DOCS_V79.healing 'stages') drops one wound level when the rest covers the stage's time.
    const stage = h.mode === 'natural' && h.stages ? stageRest({ boxes: h.before, successes: snap.successes, hours: h.hours ?? 0, timeFactor: h.timeFactor ?? 1 }) : null;
    const nat = h.mode === 'natural' && !stage ? naturalHealing({ track: h.track, boxes: h.before, successes: snap.successes, hours: h.hours ?? 0, timeFactor: h.timeFactor ?? 1 }) : null;
    const healed = h.mode === 'firstAid' ? firstAidBoxes(snap.successes, h.before, h.track) : stage ? stage.boxes : nat ? nat.boxes : boxesHealed(snap.successes, h.before);
    const target = h.before - healed;
    const expected = h.after ?? h.before;
    let note = '';
    if (!patient) note = ` <em>${tx('SR2E.Card.Actor.thePatientNoLongerExists')}</em>`;
    else if (patient.system.monitor[h.track] !== expected) note = ` <em>${tx('SR2E.Card.Actor.sDamageChangedSinceThisWas', { targetName: escText(h.targetName), track: h.track, target })}</em>`;
    // v0.61.0: a GM applying a player's card only ever heals (a forged card can't add damage).
    else if (gmApply && (!(target <= Number(patient.system.monitor[h.track] ?? 0)) || !(Number(snap.successes) >= 0 && Number(snap.successes) <= 40) || !['physical', 'stun'].includes(String(h.track)))) note = ` <em>${tx('SR2E.Card.Actor.thatCardDoesnTAddUp')}</em>`;
    else if (!canWriteNow(patient)) {
      // v0.61.0: a healer's player who doesn't own the patient posts an Apply (GM) card (healApplyRoute).
      if (healApplyRoute({ isOwner: false, isGm: Boolean(isGmNow()), gmOnline: Boolean((game as any).users?.activeGM) }) === 'gmCard') {
        const gms = [...((game as any).users ?? [])].filter((u: any) => u.isGM).map((u: any) => u.id);
        // A re-roll's card replaces the earlier one (the GM applies only the newest).
        if (snap.testId) {
          for (const m of [...(((game as any).messages?.contents ?? []) as any[])].slice(-200)) {
            const f = m.getFlag?.(SYSTEM_ID, 'healApply');
            if (f?.testId === snap.testId && !m.getFlag?.(SYSTEM_ID, 'healApplied') && canWriteNow(m)) { try { await m.setFlag(SYSTEM_ID, 'healApplied', 'superseded'); } catch { /* not ours */ } }
          }
        }
        await ChatMessage.create({
          speaker: ChatMessage.getSpeaker({ actor: this }), whisper: gms,
          content: `<p><em>${tx('SR2E.Card.Actor.gmOnly')}</em> ${tx('SR2E.Card.Actor.healsSuccessEs', { name: escText(this.name), targetName: escText(h.targetName), track: h.track, part: h.mode === 'firstAid' ? tx('SR2E.Card.Actor.firstAid') : h.mode, successes: snap.successes, before: h.before, target })}</p><p><button type="button" data-sr2e-action="applyHeal">${tx('SR2E.Card.Actor.applyGm')}</button></p>`,
          flags: { [SYSTEM_ID]: { healApply: { healerUuid: this.uuid, snap, testId: snap.testId ?? '' } } },
        });
      }
      note = ` <em>${tx('SR2E.Card.Actor.isnTYoursTheGmApplies3', { targetName: escText(h.targetName), before: h.before, target })}</em>`;
    }
    const applies = Boolean(patient) && !note;
    const wasDying = patient?.system?.derived?.status === 'dying';
    if (!patient || note) { /* nothing applied */ }
    else if (target !== patient.system.monitor[h.track]) {
      await patient.update({ [`system.monitor.${h.track}`]: target });
      const key = h.mode === 'firstAid' ? 'firstAidAt' : h.mode === 'natural' ? 'restedAt' : 'healedAt';
      await patient.setFlag?.(SYSTEM_ID, key, { ...(patient.getFlag?.(SYSTEM_ID, key) ?? {}), [h.track]: target });
      // v0.55.0: when magic healed it, so a later wound (damagedAt) frees first aid again.
      if (key === 'healedAt') await patient.setFlag?.(SYSTEM_ID, 'healedTime', { ...(patient.getFlag?.(SYSTEM_ID, 'healedTime') ?? {}), [h.track]: sysNow() });
    } else if (h.mode === 'firstAid') {
      // A failed attempt still uses up first aid for this wound.
      await patient.setFlag?.(SYSTEM_ID, 'firstAidAt', { ...(patient.getFlag?.(SYSTEM_ID, 'firstAidAt') ?? {}), [h.track]: target });
    }
    // First aid on a dying patient: any success stabilises them.
    if (h.mode === 'firstAid' && snap.successes > 0 && canWriteNow(patient) && h.track === 'physical' && wasDying && !patient.system.care?.stabilised) {
      if (patient.system.derived?.status === 'dying') await patient.update({ 'system.care.stabilised': true });
      note += ` <strong>${tx('SR2E.Card.Actor.isStabilised', { targetName: escText(h.targetName) })}</strong>`;
    }
    // v0.80.0 (RULES.URR_V80, health-social): after first aid, the healer's Biotech (for a retry), the treatment time,
    // and a dying patient's own stabilisation test when the first aid failed.
    if (h.mode === 'firstAid' && applies && patient) note += await SR2Actor.urrAfterFirstAid(this, patient, snap, wasDying);
    if (nat && snap.successes > 0) note += ` <em>${tx('SR2E.Card.Actor.hPerBoxOverHOf', { natHoursPerBox: nat.hoursPerBox, hours: h.hours })}</em>`;
    if (stage && snap.successes > 0) note += stage.done
      ? ` <em>${tx('SR2E.Card.Actor.theStageTakesDoneInH', { span: escText(describeSpan(Math.round(stage.stageHours! * 3600))), hours: h.hours })}</em>`
      : ` <em>${tx('SR2E.Card.Actor.thisStageTakesHOfRest', { span: escText(describeSpan(Math.round(stage.stageHours! * 3600))), hours: h.hours })}</em>`;
    // v0.79.0: an unfinished stage keeps its successes (flag healStage): the next Rests add hours without a new roll,
    // so a stage can't be re-rolled until the successes suit. A Karma re-roll of this card rewrites it.
    if (stage && canWriteNow(patient) && h.track === 'physical') {
      if (!stage.done && snap.successes > 0) await patient.setFlag(SYSTEM_ID, 'healStage', { boxes: h.before, successes: snap.successes, stageHours: stage.stageHours, rested: h.hours ?? 0, t: sysNow(), timeFactor: h.timeFactor ?? 1 });
      else if (patient.getFlag?.(SYSTEM_ID, 'healStage') != null) await clearFlag(patient, 'healStage');
    }
    // v0.56.0: a permanent healing spell remembers what it healed until it takes (dropped early, it comes back).
    if (snap.sustain?.permanent && RULES.MAGIC_V56.permanent.enabled && patient && !note) {
      const list = this.sustained();
      const i = snap.sustain.effectId ? list.findIndex((e: any) => e.effectId === snap.sustain!.effectId)
        : list.findIndex((e: any) => e.spellName === snap.sustain!.spellName && e.force === snap.sustain!.force && e.permanentAt >= 0);
      if (i >= 0 && ((list[i] as any).healed?.boxes ?? -1) !== healed) {
        list[i] = { ...list[i]!, healed: { targetUuid: h.targetUuid, track: h.track, boxes: healed } } as any;
        await this.update({ 'system.sustaining': list });
      }
      const at = (list[i] as any)?.permanentAt;
      if (healed > 0 && typeof at === 'number' && at >= 0) note += ` <em>${tx('SR2E.Card.Actor.itMustBeSustainedUntilIt', { span: escText(describeSpan(Math.max(0, at - sysNow()))) })}</em>`;
    }
    const body = snap.successes <= 0 ? `<strong>${tx('SR2E.Card.Actor.theHealingFails')}</strong>`
      : healed > 0 ? `<strong>${escText(h.targetName)}</strong> ${tCount(healed, 'SR2E.Card.Actor.healsBoxes', { track: h.track, before: h.before, target })}`
      : h.mode === 'firstAid' && firstAidDeadlyOnly(h.track, h.before) ? `<strong>${escText(h.targetName)}</strong>${tx('SR2E.Card.Actor.sDeadlyWoundCanOnlyBe')}`
      : stage && !stage.done ? `<strong>${escText(h.targetName)}</strong> ${tx('SR2E.Card.Actor.isnTHealedYet')}`
      : `<strong>${escText(h.targetName)}</strong> ${tx('SR2E.Card.Actor.hasNoDamageToHeal', { track: h.track })}`;
    // v0.61.0: nothing applied (not owned, or changed meanwhile): a re-roll compares against what is there now.
    const after = applies ? target : expected;
    return { html: `<p>${body}${note}</p>`, flags: {}, snap: { ...snap, heal: { ...h, after } }, applied: applies };
  }

  /** v0.61.0 (GM): apply a healing result for a healer's player who doesn't own the patient. */
  static async applyHealAsGm(healerUuid: string, snap: TestSnapshot): Promise<boolean> {
    if (!isGmNow()) return false;
    const healer: any = await fromUuid(healerUuid);
    if (!(healer instanceof SR2Actor) || !snap?.heal) return false;
    // v0.81.1 (SEC2b-2): the card's snapshot with its numbers coerced (the GM's own card prints them).
    const r = await healer.#resolveHeal(SR2Actor.#cleanSnapshot(snap), true);
    const refused = !r.applied;
    await ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor: healer }), content: `<p><strong>${refused ? tx('SR2E.Card.Actor.healingNotApplied') : tx('SR2E.Card.Actor.healingApplied')}</strong> ${tx('SR2E.Card.Actor.gm3')}</p>${r.html}` });
    return !refused;
  }

  /** Ask for a Magic loss test when a magician's Physical damage has just reached Deadly. */
  async checkMagicLoss(physicalBefore: number): Promise<void> {
    if (!RULES.MAGIC_LOSS.enabled || !((this.sys.magic as number) > 0) || this.type === 'spirit') return;
    if (reachedDeadly(physicalBefore) || !reachedDeadly(this.sys.monitor.physical)) return;
    await ChatMessage.create({
      speaker: ChatMessage.getSpeaker({ actor: this }),
      content: `<p><strong>${escText(this.name)}</strong> ${tx('SR2E.Card.Actor.isDeadlyWoundedAndMayLose')}</p>
        <p><button type="button" data-sr2e-action="magicLoss">${tx('SR2E.Card.Actor.magicLossTestD6', { magicLossDice: RULES.MAGIC_LOSS.dice })}</button></p>`,
      flags: { [SYSTEM_ID]: { magicLossFor: this.uuid } },
    });
  }

  /** Roll the Magic loss test: the dice total below Magic costs a point of (natural) Magic. */
  async rollMagicLoss(): Promise<{ total: number; lost: number }> {
    const roll = await new Roll(`${RULES.MAGIC_LOSS.dice}d6`).evaluate();
    const total = roll.total as number;
    const natural = this.sys.magic as number;
    const outcome = magicLossOutcome(total, natural);
    if (outcome.lost > 0) await this.update({ 'system.magic': Math.max(0, natural - outcome.lost) });
    await ChatMessage.create({
      speaker: ChatMessage.getSpeaker({ actor: this }),
      content: `<div class="sr2e-roll"><h3>${tx('SR2E.Card.Actor.magicLossTest')}</h3><p>${RULES.MAGIC_LOSS.dice}d6 = <strong>${total}</strong> ${tx('SR2E.Card.Actor.vs3', { outcomeThreshold: outcome.threshold })}</p>
        <p>${outcome.lost > 0 ? `<strong>${tx('SR2E.Card.Actor.losesMagic', { name: escText(this.name), outcomeLost: outcome.lost })}</strong> ${tx('SR2E.Card.Actor.now4', { value: Math.max(0, natural - outcome.lost) })}` : tx('SR2E.Card.Actor.noMagicIsLost')}</p></div>`,
      rolls: [roll],
    });
    return { total, lost: outcome.lost };
  }

  /**
   * Enchanting: the Enchanting skill (defaulting to Intelligence) vs the task's TN; time = base days
   * / successes. Making a focus creates it on success and costs Good Karma = rating x the type's cost.
   */
  async enchant(opts: { task: string; targetNumber?: number; baseDays?: number; focus?: { name: string; focusType: string; rating: number; category?: string; target?: string; size?: string } | null; fetishFor?: string }): Promise<SuccessTestResult | null> {
    const task = RULES.ENCHANTING.tasks[opts.task];
    if (!task) {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.unknownEnchantingTask', { task: escHtml(opts.task) }));
      return null;
    }
    const focus = opts.task === 'focus' && opts.focus
      ? { name: opts.focus.name || `${opts.focus.focusType} focus`, focusType: opts.focus.focusType, rating: Math.max(1, Math.floor(opts.focus.rating || 1)), category: opts.focus.category ?? '', target: opts.focus.target ?? '', ...(opts.focus.size === 'large' || opts.focus.size === 'small' ? { size: opts.focus.size } : {}) }
      : undefined;
    if (focus) {
      const cost = focusKarmaCost(focus.focusType, focus.rating, { target: focus.target, category: focus.category, size: focus.size });
      const good = (this.sys.karma?.good as number | undefined) ?? 0;
      if (good < cost) {
        ui.notifications?.warn?.(tx('SR2E.Notify.Actor.aFocusOfRatingCostsGood', { focusFocusType: escHtml(focus.focusType), focusRating: focus.rating, cost, name: escHtml(this.name), good }));
        return null;
      }
      // v0.70.0: making and bonding a focus waits for the GM when the approval queue is on; the test runs on approval.
      if (approvalNeeded(this)) { await fileRequest(this, { kind: 'improve', label: tx('SR2E.Text.Actor.makeAndBondRating', { name: focus.name, rating: focus.rating }), karma: cost, data: { method: 'enchant', args: [{ ...opts }] } }); return null; }
    }
    const { dice, modifiers, suffix } = this.#skillDice(this.findSkill('Enchanting'), false, null, 'intelligence');
    const baseDays = opts.baseDays ?? task.days;
    if (focus) {
      const need = focusMaterialNeed(focus.rating);
      const have = this.materialStock()[need.kind as 'raw' | 'refined' | 'radical'] ?? 0;
      if (have < need.n) {
        ui.notifications?.warn?.(tx('SR2E.Notify.Actor.aRatingFocusNeedsMaterialHas', { focusRating: focus.rating, need: tCount(need.n, 'SR2E.Count.kindMaterial', { kind: need.kind }), name: escHtml(this.name), have }));
        return null;
      }
    }
    return this.#runTest(`${task.label}${focus ? tx('SR2E.Card.Actor.rating2', { focusName: focus.name, focusRating: focus.rating }) : ''}${opts.fetishFor ? tx('SR2E.Card.Actor.for', { fetishFor: opts.fetishFor }) : ''}${suffix}`, dice, {
      targetNumber: opts.targetNumber ?? task.tn, modifiers, magical: true,
    }, { kind: 'enchant', enchant: { label: task.label, task: opts.task, baseDays, ...(focus ? { focus } : {}), ...(opts.fetishFor ? { fetishFor: opts.fetishFor } : {}) } });
  }

  async #resolveEnchant(snap: TestSnapshot): Promise<Resolved> {
    const e = snap.enchant!;
    const days = enchantingDays(e.baseDays, snap.successes);
    if (days === null && e.projectId) return { html: `<p><strong>${tx('SR2E.Card.Actor.theWorkFails')}</strong>${await this.dropProjectOnFailure(e.projectId)}</p>`, flags: {}, snap: { ...snap, enchant: { ...e, projectId: undefined, materialsApplied: false, created: false } as any } };
    if (days === null) return { html: `<p><strong>${tx('SR2E.Card.Actor.theWorkFails')}</strong></p>`, flags: {}, snap };
    let extra = '';
    let next = snap;
    // v0.65.0: the work takes its days: what is used goes now, what is made comes when they have passed.
    const wait = this.waitsFor('magic');
    if (e.projectId) await this.retimeProject(e.projectId, days * 24);
    // Materials move once, on the first successful result (a re-roll does not move them again).
    if (e.task && !e.materialsApplied && !e.focus) {
      const step = materialStep(e.task, snap.successes, this.materialStock());
      if (step.short) extra += ` <em>${escText(step.short)}</em>`;
      if (step.consume) await this.#changeMaterial(step.consume.kind, -step.consume.n);
      const fetishName = step.produce?.kind === 'fetish' ? `Fetish${e.fetishFor ? ` (${e.fetishFor})` : ''}` : undefined;
      let projectId: string | undefined;
      if (step.produce && wait) {
        const pr = await this.startProject({ kind: 'enchant', area: 'magic', label: `${e.label}: ${step.produce.n} ${step.produce.kind}`, hours: days * 24, effect: { call: { method: 'finishEnchant', args: [step.produce.kind, step.produce.n, fetishName ?? null] } },
          ...(step.consume ? { onCancel: { call: { method: 'finishEnchant', args: [step.consume.kind, step.consume.n, null] } } } : {}) });
        projectId = pr.id;
      } else if (step.produce) await this.#changeMaterial(step.produce.kind, step.produce.n, fetishName);
      if (step.produce) {
        const pn = step.produce.n, pk = step.produce.kind;
        extra += step.consume
          ? (projectId ? tx('SR2E.Card.Actor.materialsConsumeProduceWhen', { cn: step.consume.n, ck: step.consume.kind, pn, pk }) : tx('SR2E.Card.Actor.materialsConsumeProduce', { cn: step.consume.n, ck: step.consume.kind, pn, pk }))
          : (projectId ? tx('SR2E.Card.Actor.materialsProduceWhen', { pn, pk }) : tx('SR2E.Card.Actor.materialsProduce', { pn, pk }));
      }
      next = { ...next, enchant: { ...e, materialsApplied: true, ...(projectId ? { projectId } : {}) } as any };
    }
    if (e.focus && !e.created) {
      const cost = focusKarmaCost(e.focus.focusType, e.focus.rating, { target: e.focus.target, category: e.focus.category, size: e.focus.size });
      const good = (this.sys.karma?.good as number | undefined) ?? 0;
      const need = focusMaterialNeed(e.focus.rating);
      const have = this.materialStock()[need.kind as 'raw' | 'refined' | 'radical'] ?? 0;
      if (good < cost) extra = ` <em>${tx('SR2E.Card.Actor.notEnoughGoodKarmaToBond', { good, cost })}</em>`;
      else if (have < need.n) extra = ` <em>${tx('SR2E.Card.Actor.notEnoughMaterialsOf', { needKind: need.kind, have, need: need.n })}</em>`;
      else {
        await this.#changeMaterial(need.kind, -need.n);
        const focusData = {
          name: e.focus.name, type: 'focus',
          system: { focusType: e.focus.focusType, rating: e.focus.rating, category: e.focus.category, target: e.focus.target, ...(e.focus.size ? { size: e.focus.size } : {}), active: true, bonded: true },
          // The maker's astral signature stays on the object (v0.39.0).
          ...(RULES.MAGIC_V39.objectSignatures ? { flags: { [SYSTEM_ID]: { signature: this.objectSignature(e.focus.rating, `Made ${e.focus.name}`) } } } : {}),
        };
        await this.update({ 'system.karma.good': good - cost, 'system.ledger': this.#ledgerWith({ kind: 'karma', amount: -cost, reason: tx('SR2E.Text.Actor.madeAndBonded', { name: e.focus.name }) }) });
        if (wait) {
          const pr = await this.startProject({ kind: 'enchant', area: 'magic', label: tx('SR2E.Text.Actor.making', { name: e.focus.name }), hours: days * 24, paid: { karma: cost }, effect: { creates: [focusData] }, onCancel: { call: { method: 'finishEnchant', args: [need.kind, need.n, null] } } });
          extra = ` <strong>${escText(e.focus.name)}</strong> ${tCount(need.n, 'SR2E.Card.Actor.isUnderWayGoodKarmaAnd', { cost, needKind: need.kind })}`;
          next = { ...snap, enchant: { ...e, created: true, projectId: pr.id } };
        } else {
          await this.createEmbeddedDocuments('Item', [focusData]);
          extra = ` <strong>${escText(e.focus.name)}</strong> ${tCount(need.n, 'SR2E.Card.Actor.isMadeAndBondedForGood', { cost, needKind: need.kind })}`;
          next = { ...snap, enchant: { ...e, created: true } };
        }
      }
    }
    return { html: `<p>${tx('SR2E.Card.Actor.doneIn', { label: escText(e.label) })} <strong>${tCount(days, 'SR2E.Card.Actor.days')}</strong> (${e.baseDays} / ${snap.successes}).${extra}</p>`, flags: {}, snap: next };
  }

  /** v0.65.0: enchanting work whose time has passed: what it makes arrives. */
  async finishEnchant(kind: string, n: number, name: string | null): Promise<boolean> {
    await this.#changeMaterial(kind as any, Number(n) || 0, name ?? undefined);
    return true;
  }

  /** Enchanting materials on hand, by kind (summing gear quantities). */
  materialStock(): { raw: number; refined: number; radical: number; fetish: number } {
    const out = { raw: 0, refined: 0, radical: 0, fetish: 0 };
    for (const i of [...this.items] as any[]) {
      const k = i.type === 'gear' ? i.system.material : '';
      if (k && k in out) out[k as keyof typeof out] += Math.max(0, i.system.quantity ?? 0);
    }
    return out;
  }

  /** Add (or remove) material units, on one gear item per kind (fetishes: one item each). */
  async #changeMaterial(kind: MaterialKind, delta: number, name?: string): Promise<void> {
    if (!kind || !delta) return;
    const LABEL: Record<string, string> = { raw: 'Raw materials', refined: 'Refined materials', radical: 'Radicals', fetish: 'Fetish' };
    if (delta > 0) {
      const existing: any = kind === 'fetish' ? null : [...this.items].find((i: any) => i.type === 'gear' && i.system.material === kind);
      if (existing) await this.updateEmbeddedDocuments('Item', [{ _id: existing.id, system: { quantity: existing.system.quantity + delta } }]);
      else await this.createEmbeddedDocuments('Item', [{ name: name ?? LABEL[kind] ?? kind, type: 'gear', system: { quantity: delta, material: kind } }]);
      return;
    }
    let left = -delta;
    for (const i of [...this.items].filter((x: any) => x.type === 'gear' && x.system.material === kind) as any[]) {
      if (left <= 0) break;
      const take = Math.min(left, i.system.quantity);
      left -= take;
      await this.updateEmbeddedDocuments('Item', [{ _id: i.id, system: { quantity: i.system.quantity - take } }]);
    }
  }

  /** The astral quest under way, if any. */
  quest(): QuestState | null {
    return (this.getFlag(SYSTEM_ID, 'quest') as QuestState | undefined) ?? null;
  }

  async startQuest(q: { name: string; stages: number; targetNumber: number }): Promise<void> {
    await this.setFlag(SYSTEM_ID, 'quest', { name: q.name || 'Astral quest', stages: Math.max(1, Math.floor(q.stages)), passed: 0, targetNumber: Math.max(2, Math.floor(q.targetNumber)), failed: false });
  }

  async endQuest(): Promise<void> {
    await clearFlag(this, 'quest');
  }

  /** Face the next stage of the astral quest: an attribute test vs the quest's TN, while projecting. */
  async questStage(attribute: AttributeKey = 'willpower'): Promise<SuccessTestResult | null> {
    const q = this.quest();
    if (!q) {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.isNotOnAnAstralQuest', { name: escHtml(this.name) }));
      return null;
    }
    if (questStatus(q) !== 'underway') {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.theQuestIsAlready', { qName: escHtml(q.name), questStatus: questStatus(q) }));
      return null;
    }
    if (this.sys.derived.astralMode !== 'projecting') {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.mustBeProjectingToGoOn', { name: escHtml(this.name) }));
      return null;
    }
    const name = attribute.charAt(0).toUpperCase() + attribute.slice(1);
    return this.#runTest(tx('SR2E.Card.Actor.stageOf', { name: q.name, value: q.passed + 1, stages: q.stages, name2: name }), this.sys.attributes[attribute].total as number, {
      targetNumber: q.targetNumber, background: true,
    }, { kind: 'quest', quest: { before: q } });
  }

  async #resolveQuest(snap: TestSnapshot): Promise<Resolved> {
    const ctx = snap.quest!;
    const next = advanceQuest(ctx.before, snap.successes);
    const current = this.quest();
    const expected = ctx.after ?? ctx.before;
    let note = '';
    if (current && JSON.stringify(current) === JSON.stringify(expected)) await this.setFlag(SYSTEM_ID, 'quest', next);
    else note = ` <em>${tx('SR2E.Card.Actor.theQuestChangedSinceThisWas')}</em>`;
    const st = questStatus(next);
    const body = st === 'complete' ? `<strong>${tx('SR2E.Card.Actor.isComplete', { nextName: escText(next.name) })}</strong>`
      : st === 'failed' ? `<strong>${tx('SR2E.Card.Actor.hasFailed', { nextName: escText(next.name) })}</strong>`
      : snap.successes > 0 ? tx('SR2E.Card.Actor.stagePassedOf', { nextPassed: next.passed, nextStages: next.stages }) : tx('SR2E.Card.Actor.theStageIsNotPassed');
    return { html: `<p>${body}${note}</p>`, flags: {}, snap: { ...snap, quest: { ...ctx, after: next } } };
  }

  /**
   * Dispel (metamagic): Sorcery vs TN = the spell's Force; each success removes one of the spell's
   * successes, and at 0 it ends. The dispeller takes drain at floor(Force/2).
   */
  async dispel(target: any, spellIndex: number, opts: { poolDice?: number; drainPoolDice?: number } = {}): Promise<SuccessTestResult | null> {
    if (!this.canAct('dispel')) return null;
    if (!this.initiate.techniques.includes('dispelling')) {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.doesNotKnowTheDispellingMetamagic', { name: escHtml(this.name) }));
      return null;
    }
    const sorcery = this.findSkill('Sorcery');
    if (!sorcery || sorcery.system.rating <= 0) {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.hasNoSorcerySkillAndCannot2', { name: escHtml(this.name) }));
      return null;
    }
    const entry = target?.sustained?.()[spellIndex] as SustainedSpell | undefined;
    if (!entry) {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.thatSpellIsNoLongerBeing'));
      return null;
    }
    // Review (R7): the dispelled spell's category and name count for a Dispelling specialization.
    const dispelUse = this.sorceryUseFor('dispel', { category: entry.category, spellName: entry.spellName, skill: sorcery });
    const extra = bonusNote(sorceryFocusDice(this.foci(), { name: entry.spellName, category: entry.category }), 0);
    const dispelRating = narrowRating(sorcery.system, dispelUse);
    // Review (B3): the card says which narrow rating it rolls, and carries its interpretations.
    if (dispelRating > Number(sorcery.system?.rating ?? 0)) extra.note += ` [${tx('SR2E.Card.MagicPool.narrow', { name: dispelUse.spec ? sorcery.system.specialization : sorcery.system.concentration, rating: dispelRating })}]`;
    const result = await this.#runTest(tx('SR2E.Card.Actor.dispelOnTnForce', { entrySpellName: entry.spellName, targetName: target.name, entryForce: entry.force, extraNote: extra.note }),
      // v0.92.0 (RULES.MAGIC_V920): a Dispelling concentration or specialization rolls its rating and its narrow dice.
      Math.max(0, dispelRating + extra.dice),
      { targetNumber: entry.force, poolDice: opts.poolDice ?? 0, pool: 'spell', spellUse: dispelUse, magical: true },
      { kind: 'dispel', dispel: { targetUuid: target.uuid, targetName: target.name, spellName: entry.spellName, force: entry.force, successesBefore: entry.successes ?? 1 },
        ...(dispelUse.conc || dispelUse.spec ? { narrow: { layers: layersOn() && ((dispelUse.conc && Number(this.sys.derived?.spellLayers?.conc ?? 0) > 0) || (dispelUse.spec && Number(this.sys.derived?.spellLayers?.spec ?? 0) > 0)), rating: dispelRating > Number(sorcery.system?.rating ?? 0) } } : {}) });
    await this.leaveSignature('dispelling', tx('SR2E.Text.Actor.dispelling', { name: entry.spellName }), entry.force);
    await this.#drainTest({
      label: tx('SR2E.Card.Actor.dispellingDrain'), attribute: 'willpower',
      targetNumber: drainTargetNumber(entry.force, RULES.MAGIC.dispelDrainModifier),
      level: RULES.MAGIC.dispelDrainLevel as DamageLevel,
      type: drainDamageType(entry.force, Number(this.sys.derived.drainMagic ?? this.sys.derived.magic ?? 0)),
      // v0.72.0 (O16): Spell Pool dice go to dispelling drain as to casting drain (MAGIC_V72.dispelDrainPool).
      poolDice: dispelDrainPoolDice(opts.drainPoolDice ?? 0, this.spellPoolFor(drainNarrowOn() ? dispelUse : null)),
      ...(drainNarrowOn() ? { spellUse: dispelUse } : {}),
    });
    return result;
  }

  async #resolveDispel(snap: TestSnapshot): Promise<Resolved> {
    const d = snap.dispel as DispelContext;
    const outcome = resolveDispel(d.successesBefore, snap.successes);
    const target: any = await fromUuid(d.targetUuid);
    const expected = d.successesAfter ?? d.successesBefore;
    const list: SustainedSpell[] = target?.sustained?.() ?? [];
    const i = list.findIndex((e) => e.spellName === d.spellName && e.force === d.force && (e.successes ?? 1) === expected);
    let note = '';
    // v0.81.0 (D2-3): the spell's successes after this card (what a later re-roll compares against).
    let after = expected;
    if (!target) note = ` <em>${tx('SR2E.Card.Actor.theTargetNoLongerExists')}</em>`;
    else if (i < 0) note = ` <em>${tx('SR2E.Card.Actor.changedOrEndedSinceThisWas', { spellName: escText(d.spellName) })}</em>`;
    else if (!canWriteNow(target)) {
      // Someone else's spell: an Apply (GM) card (only fewer successes, and only while it still has these).
      if (outcome.remaining < expected) await SR2Actor.gmActorCard(target.uuid, { dispel: { spellName: d.spellName, force: d.force, from: expected, to: outcome.remaining }, by: this.uuid as string }, tx('SR2E.Card.Actor.dispelsOnSuccessEs', { name: escText(this.name), spellName: escText(d.spellName), targetName: escText(target.name), expected, outcomeRemaining: outcome.remaining }));
      note = ` <em>${tx('SR2E.Card.Actor.isnTYoursTheGmApplies4', { targetName: escText(target.name) })}</em>`;
    } else if (outcome.remaining !== expected) {
      after = outcome.remaining;
      const entry: any = list[i];
      if (outcome.dispelled) list.splice(i, 1);
      else list[i] = { ...list[i]!, successes: outcome.remaining };
      await target.update({ 'system.sustaining': list });
      // v0.71.0 (R11): what's left of the spell does less (Armor at 1 success no longer gives +5).
      if (!outcome.dispelled && RULES.FIXES_V71.dispelShrinks && entry?.effectId) note += await SR2Actor.#shrinkSpellEffect(entry, expected - outcome.remaining, target);
    }
    const spn = escText(d.spellName);
    const body = outcome.dispelled
      ? `<strong>${tx('SR2E.Card.Actor.isDispelled', { spn })}</strong> ${tx('SR2E.Card.Actor.on4', { targetName: escText(d.targetName) })}`
      : snap.successes > 0
        ? `<strong>${tx('SR2E.Card.Actor.weakens2', { spn })}</strong> ${tCount(outcome.remaining, 'SR2E.Card.Actor.successesLeft')}`
        : `<strong>${tx('SR2E.Card.Actor.holds3', { spn })}</strong>`;
    return { html: `<p>${body}${note}</p>`, flags: {}, snap: { ...snap, dispel: { ...d, successesAfter: after } } };
  }

  /**
   * v0.71.0 (R11): rebuild a sustained spell's effect on each subject with `lost` fewer successes (negative: a
   * dispel re-roll gives some back). Effects made before v0.71.0 don't carry what they were built from: left alone.
   */
  static async #shrinkSpellEffect(entry: any, lost: number, caster: any): Promise<string> {
    if (!lost) return '';
    const subjects: string[] = entry.targetUuids?.length ? entry.targetUuids : [caster.uuid];
    const old: string[] = [];
    for (const u of subjects) {
      const t: any = fromUuidSync(u);
      const fx: FxEntry | undefined = ((t?.getFlag?.(SYSTEM_ID, 'powerEffects') as FxEntry[] | undefined) ?? []).find((x) => x.id === entry.effectId);
      if (!fx || fx.permanent) continue;
      if (!fx.spec || typeof fx.successes !== 'number') { old.push(t.name); continue; }
      const left = Math.max(0, Math.min(Number(fx.successes), Number(fx.successes) - lost));
      if (left <= 0) { await SR2Actor.setPowerEffect(u, null, fx.id); continue; }
      const rebuilt = { ...SR2Actor.fxEntry(fx.spec, left, fx.id, fx.fromUuid, fx.fromName), ...(fx.permanent ? { permanent: true } : {}) };
      // v0.81.1 (RB2-3): the spec is the effect's own data: a rebuild outside the Apply (GM) bounds isn't written.
      if (!powerEffectShapeOk(rebuilt)) { old.push(t.name); continue; }
      await SR2Actor.setPowerEffect(u, rebuilt);
    }
    return old.length ? ` <em>${tx('SR2E.Card.Actor.theEffectOnPredatesV0710', { names: escText(old.join(', ')) })}</em>` : '';
  }

  /** Quicken (metamagic) a sustained spell: it becomes permanent with no TN penalty, for Karma = Force. */
  async quicken(index: number, spellName = ''): Promise<boolean> {
    if (!this.initiate.techniques.includes('quickening')) {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.doesNotKnowTheQuickeningMetamagic', { name: escHtml(this.name) }));
      return false;
    }
    const list = this.sustained();
    // v0.70.0: an approved request finds the spell again by name (the list may have changed since).
    if (spellName && list[index]?.spellName !== spellName) index = list.findIndex((e: any) => e.spellName === spellName && !e.quickened);
    const entry = list[index];
    if (!entry || entry.quickened) return false;
    const cost = entry.force * RULES.MAGIC.quickenKarmaPerForce;
    const good = (this.sys.karma?.good as number | undefined) ?? 0;
    if (good < cost) {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.quickeningCostsGoodKarmaHas', { entrySpellName: escHtml(entry.spellName), cost, name: escHtml(this.name), good }));
      return false;
    }
    // v0.70.0: through the approval queue, with a ledger line (it had neither).
    if (approvalNeeded(this)) { await fileRequest(this, { kind: 'improve', label: tx('SR2E.Text.Actor.quickenForce', { name: entry.spellName, force: entry.force }), karma: cost, data: { method: 'quicken', args: [index, entry.spellName] } }); return false; }
    list[index] = { ...entry, quickened: true };
    await this.update({ 'system.sustaining': list, 'system.karma.good': good - cost, 'system.ledger': this.#ledgerWith({ kind: 'karma', amount: -cost, reason: tx('SR2E.Text.Actor.quickenedForce', { name: entry.spellName, force: entry.force }) }) });
    await ChatMessage.create({
      speaker: ChatMessage.getSpeaker({ actor: this }),
      content: `<p><strong>${escText(this.name)}</strong> ${tx('SR2E.Card.Actor.quickensForceForGoodKarma', { entrySpellName: escText(entry.spellName), entryForce: entry.force, cost })}</p>`,
    });
    return true;
  }

  /**
   * Force through a ward or astral barrier: astral attack dice vs TN = its rating, opposed by its
   * rating vs this actor's Magic (spirits: Force). Net successes lower its rating; at 0 it is breached.
   */
  async breachBarrier(barrier: any, opts: { poolDice?: number } = {}): Promise<SuccessTestResult | null> {
    if (!barrier || barrier.type !== 'barrier') {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.pickABarrierToForceThrough'));
      return null;
    }
    const rating = barrier.system.rating as number;
    if (rating <= 0) {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.isAlreadyBreached', { barrierName: escHtml(barrier.name) }));
      return null;
    }
    if (!this.isAstral()) {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.mustBeOnTheAstralPlane2', { name: escHtml(this.name), barrierName: escHtml(barrier.name) }));
      return null;
    }
    const spirit = this.type === 'spirit';
    let dice: number;
    let modifiers: TargetNumberModifier[] = [];
    let suffix = '';
    if (spirit) dice = this.sys.force as number;
    else {
      ({ dice, modifiers, suffix } = this.#skillDice(this.findSkill(RULES.ASTRAL.attackSkill), false, null, 'willpower'));
      const extra = bonusNote(weaponFocusDice(this.foci(), null), 0);
      dice += extra.dice;
      suffix += extra.note;
    }
    const opposing = spirit ? (this.sys.force as number) : (this.sys.derived.magic as number);
    const barrierRolls: any[] = [];
    const resist = await successTest({ dice: rating, targetNumber: Math.max(RULES.MIN_TARGET_NUMBER, opposing), roll: foundryRoller(barrierRolls) });
    await ChatMessage.create({
      speaker: { alias: barrier.name },
      content: describeResult(tx('SR2E.Card.Actor.resistsRatingVsS', { barrierName: barrier.name, rating, name: this.name, part: spirit ? tx('SR2E.Card.Actor.force3') : tx('SR2E.Card.Actor.magic3'), opposing }), resist),
      rolls: barrierRolls,
    });
    await this.leaveSignature('barrier', tx('SR2E.Text.Actor.forcing', { name: barrier.name }), spirit ? (this.sys.force as number) : (this.sys.derived.magic as number));
    return this.#runTest(tx('SR2E.Card.Actor.forceThroughTnRating', { barrierName: barrier.name, rating, suffix }), dice, {
      targetNumber: rating, modifiers, poolDice: opts.poolDice ?? 0, pool: this.poolFor({ astral: true }), magical: !spirit,
    }, { kind: 'barrier', barrier: { barrierUuid: barrier.uuid, barrierName: barrier.name, barrierSuccesses: resist.successes, ratingBefore: rating } });
  }

  async #resolveBarrier(snap: TestSnapshot): Promise<Resolved> {
    const b = snap.barrier as BarrierContext;
    const outcome = resolveBarrier({ attackerSuccesses: snap.successes, barrierSuccesses: b.barrierSuccesses, rating: b.ratingBefore });
    const barrier: any = await fromUuid(b.barrierUuid);
    const expected = b.ratingAfter ?? b.ratingBefore;
    let note = '';
    const bn = escText(b.barrierName);
    // v0.81.0 (D2-3): the rating after this card (what a later re-roll compares against).
    let after = expected;
    if (!barrier) note = ` <em>${tx('SR2E.Card.Actor.theBarrierNoLongerExists')}</em>`;
    else if (barrier.system.rating !== expected) note = ` <em>${tx('SR2E.Card.Actor.sRatingChangedSinceThisWas', { bn, outcomeRating: outcome.rating })}</em>`;
    else if (!canWriteNow(barrier)) {
      if (outcome.rating < barrier.system.rating) await SR2Actor.gmActorCard(barrier.uuid, { lower: { key: 'rating', from: barrier.system.rating, to: outcome.rating }, by: this.uuid as string }, tx('SR2E.Card.Actor.breaksRating', { name: escText(this.name), bn, barrierRating: barrier.system.rating, outcomeRating: outcome.rating }));
      note = ` <em>${tx('SR2E.Card.Actor.theGmLowersToAGm', { bn, outcomeRating: outcome.rating })}</em>`;
    } else {
      if (outcome.rating !== barrier.system.rating) await barrier.update({ 'system.rating': outcome.rating });
      after = outcome.rating;
    }
    const lead = tx('SR2E.Card.Actor.vs4', { successes: snap.successes, barrierSuccesses: b.barrierSuccesses });
    const body = outcome.breached
      ? `<strong>${tx('SR2E.Card.Actor.isBreached', { bn })}</strong> (${lead})`
      : outcome.netSuccesses > 0
        ? `<strong>${tx('SR2E.Card.Actor.weakens3', { bn })}</strong> ${tx('SR2E.Card.Actor.rating3', { ratingBefore: b.ratingBefore, outcomeRating: outcome.rating, lead })}`
        : `<strong>${tx('SR2E.Card.Actor.holds4', { bn })}</strong> (${lead})`;
    return { html: `<p>${body}${note}</p>`, flags: {}, snap: { ...snap, barrier: { ...b, ratingAfter: after } } };
  }

  /** A spirit performs one service; posts a note and counts it down. */
  async useService(): Promise<void> {
    if (this.type !== 'spirit') return;
    if (!spiritOwesServices(this.sys.spiritKind)) {
      await ChatMessage.create({
        speaker: ChatMessage.getSpeaker({ actor: this }),
        content: `<p><strong>${escText(this.name)}</strong> ${(this.sys.spiritKind === 'ally' ? tx('SR2E.Card.Actor.actsWithForItsMasterAlliesDoNot') : tx('SR2E.Card.Actor.actsWithOfItsOwnFreeWill'))}</p>`,
      });
      return;
    }
    const left = Math.max(0, (this.sys.services as number) - 1);
    if ((this.sys.force as number) <= 0) {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.isBanishedAndCanPerformNo', { name: escHtml(this.name) }));
      return;
    }
    if ((this.sys.services as number) <= 0) {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.owesNoServices3', { name: escHtml(this.name) }));
      return;
    }
    await this.update({ 'system.services': left });
    await ChatMessage.create({
      speaker: ChatMessage.getSpeaker({ actor: this }),
      content: `<p><strong>${escText(this.name)}</strong> ${tx('SR2E.Card.Actor.performsAService', { part: left > 0 ? tx('SR2E.Card.Actor.left', { left }) : tx('SR2E.Card.Actor.thatWasItsLastItDeparts') })}</p>`,
    });
  }

  /**
   * Resist a combat spell: the resisting attribute plus Spell Pool dice vs the spell's Force.
   * Net caster successes stage the spell's damage, applied directly (armor does not help).
   */
  /** v0.81.1 (D2-1): protectors whose spell defense is being spent right now (two quick Resists don't both use it). */
  static readonly #spellDefenseBusy = new Set<string>();

  /**
   * v0.81.1 (D2-1, D3-2, SEC1-12): why `protector`'s held spell defense can't cover `target` for `user` ('' when it
   * can). It can when `user` is a GM or owns the protector; when the protector's holder named the target (actor flag
   * `spellDefenseCovers`, `setSpellDefenseCovers`); or when both have a token on the same scene with the same
   * disposition (allies at the table, in a fight or not). An enemy's defense never covers you.
   */
  static spellDefenseCoverProblem(protector: any, target: any, user: any): string {
    if (!protector || !target) return tx('SR2E.Text.Actor.thatCharacterIsGone');
    if (protector === target || (protector.uuid && protector.uuid === target.uuid)) return '';
    // Round 2 (FIX2-BRIEF H2): a GM's card (or a GM acting), or the requester's own protector.
    if (user && (realGm(user) || userOwns(user, protector))) return '';
    // A player who owns the protector also owns the character (one player's two characters, a shared party member).
    const players: any[] = [...(((game as any).users ?? []) as any[])].filter((u: any) => !u?.isGM);
    if (players.some((u: any) => userOwns(u, protector) && userOwns(u, target))) return '';
    const covers = protector.getFlag?.(SYSTEM_ID, 'spellDefenseCovers');
    if (Array.isArray(covers) && covers.includes(String(target.uuid))) return '';
    // Round 2 (V-DOC 2): tokens on any scene, not only this client's canvas (the relay runs on the GM's, who may be
    // viewing another scene). Same disposition is the same side (hostile + hostile too: NPC allies); friendly against
    // hostile is an enemy and never covers, whatever the fight.
    const pt = SR2Actor.#tokensAnywhere(protector), tt = SR2Actor.#tokensAnywhere(target);
    const scene = (t: any) => String(t.parent?.id ?? t.scene?.id ?? '');
    const pairs = pt.flatMap((p: any) => tt.filter((t: any) => scene(t) && scene(t) === scene(p)).map((t: any) => [Number(p.disposition), Number(t.disposition)] as [number, number]));
    const all: any = (game as any).combats;
    const combats: any[] = Array.isArray(all?.contents) ? all.contents : all && typeof all[Symbol.iterator] === 'function' ? [...all] : (game as any).combat ? [(game as any).combat] : [];
    const inIt = (a: any, c: any) => [...(c?.combatants ?? [])].some((x: any) => x?.actor === a || (x?.actor?.uuid && x.actor.uuid === a.uuid));
    const sameFight = combats.some((c: any) => inIt(protector, c) && inIt(target, c));
    // Round 3 (V2 #10, FIX3-BRIEF 9): two player characters (each owned by some player) in the same fight or on the
    // same scene cover each other whatever their tokens' dispositions (a PC token left at the default hostile).
    const pc = (a: any) => players.some((u: any) => userOwns(u, a));
    if (pc(protector) && pc(target) && (sameFight || pairs.length > 0)) return '';
    if (pairs.some(([a, b]) => a * b < 0)) return tx('SR2E.Text.Actor.isOnTheOtherSideItsSpell', { name: protector.name, targetName: target.name });
    if (pairs.some(([a, b]) => a === b)) return '';
    // Both in one combat (any combat on the world, not only the viewed one).
    if (sameFight) return '';
    return tx('SR2E.Text.Actor.isnTCoveringWithSpellDefense', { name: protector.name, targetName: target.name });
  }

  /** Round 2 (V-DOC 2): an actor's tokens on every scene (a linked actor's by id; a token actor's own token). */
  static #tokensAnywhere(a: any): any[] {
    if (a?.isToken && a.token) return [a.token];
    const out: any[] = [];
    for (const sc of [...(((game as any).scenes ?? []) as any[])]) {
      for (const t of [...(sc?.tokens ?? [])]) if ((t?.actorLink !== false && t?.actorId && t.actorId === a?.id) || t?.actor === a) out.push(t);
    }
    if (!out.length) { try { out.push(...((a?.getActiveTokens?.(false, true) ?? []) as any[])); } catch { /* none */ } }
    return out;
  }

  /** v0.81.1 (D2-1): name the characters this actor's held spell defense covers (its owner's choice; the relay checks it). */
  async setSpellDefenseCovers(uuids: string[]): Promise<void> {
    await this.setFlag(SYSTEM_ID, 'spellDefenseCovers', [...new Set((uuids ?? []).map((u) => String(u)).filter(Boolean))].slice(0, 20));
  }

  async resistSpell(state: SpellState, poolDice = 0, opts: { protectorUuid?: string | null } = {}): Promise<void> {
    const poolType = state.resistPool ?? 'spell';
    const pool = poolType === 'none' ? 0 : Math.max(0, Math.min(poolDice, this.sys.derived[`${poolType}PoolLeft`] as number));
    // Spell defense dice held back earlier this Combat Turn protect against spells (not powers): the
    // target's own, or a protector's who is covering them. Shielding initiates add their grade.
    const isSpell = state.noun !== 'power';
    let protector: any = isSpell && opts.protectorUuid && opts.protectorUuid !== this.uuid ? await fromUuid(opts.protectorUuid) : null;
    // v0.81.1 (D2-1, D3-2): only a protector covering this character: its own owner's, one whose holder named this
    // character (flag spellDefenseCovers), or one on the same side here (a token on the same scene, same disposition).
    if (protector) {
      const why = SR2Actor.spellDefenseCoverProblem(protector, this, actingAuthor ?? (game as any).user);
      if (why) { ui.notifications?.warn?.(escText(why)); protector = null; }
    }
    const defender: any = protector ?? this;
    // v0.81.1 (D2-1): spent first, then rolled: only the dice actually spent count (a refused or doubled spend adds none).
    let defense = 0;
    const held = isSpell ? Math.max(0, Number(defender.system?.spellDefense ?? 0) || 0) : 0;
    if (held > 0 && RULES.MAGIC.spellDefenseSpentOnUse) {
      const key = String(defender.uuid ?? '');
      if (SR2Actor.#spellDefenseBusy.has(key)) ui.notifications?.warn?.(tx('SR2E.Notify.Actor.sSpellDefenseIsBeingSpent', { defenderName: escText(defender.name) }));
      else {
        SR2Actor.#spellDefenseBusy.add(key);
        try {
          if (canWriteNow(defender)) { await defender.update({ 'system.spellDefense': 0, 'system.poolSpent.spell': Number(defender.system.poolSpent?.spell ?? 0) + held }); defense = held; }
          else {
            const r = await requestGm('spendSpellDefense', { protectorUuid: defender.uuid, targetUuid: this.uuid, amount: held });
            if (r.ok) defense = held;
            else ui.notifications?.warn?.(tx('SR2E.Notify.Actor.sSpellDefenseWasnTSpent', { defenderName: escText(defender.name), note: escText(r.note ?? tx('SR2E.Notify.Actor.noGmAnswered')) }));
          }
        } catch (e) {
          console.warn('SR2e | spending spell defense failed', e);
        } finally {
          SR2Actor.#spellDefenseBusy.delete(key);
        }
      }
    } else defense = held;
    const shield = isSpell ? shieldingDice(this.initiate.grade, this.initiate.techniques) : 0;
    // v0.56.0: an adept's spell resistance power.
    // v0.78.0 (RULES.BOOK_V78.spellResistanceVsPowers false, Awakenings): against spells only, not critter powers.
    const adeptSr = isSpell || RULES.BOOK_V78.spellResistanceVsPowers ? spellResistanceDice(adeptSpecialLevel(adeptPowersOf(this) as any, 'spellResistance')) : 0;
    const rolls: any[] = [];
    const result = await successTest({
      dice: this.sys.attributes[state.resistAttribute].total + adeptSr,
      poolDice: pool + defense + shield + (state.barrierDice ?? 0),
      // v0.80.0 (RULES.URR_V80.magRitualResistTn 'leader', URR): set only on a ritual led by a higher Sorcery.
      targetNumber: state.resistTn ?? state.force,
      roll: foundryRoller(rolls),
    });
    if (pool > 0 && poolType !== 'none') await this.#spendPool(poolType, pool);
    // v0.79.0 (spell defense spent on use, SRII p. 132): a protector the resisting player doesn't own is spent
    // through the active GM (requestGm 'spendSpellDefense'). v0.81.1: before the roll, above.
    const attr = state.resistAttribute.charAt(0).toUpperCase() + state.resistAttribute.slice(1);
    const label = tx('SR2E.Card.Actor.resistVs2', { stateSpellName: state.spellName, attr, part: state.noun === 'power' ? tx('SR2E.Card.Actor.rating10') : tx('SR2E.Card.Actor.force3'), stateForce: state.force })
      + `${defense ? (protector ? tx('SR2E.Card.Actor.spellDefenseWithFrom2', { defense, protectorName: protector.name }) : tx('SR2E.Card.Actor.spellDefensePlain', { defense })) : ''}${shield ? tx('SR2E.Card.Actor.shielding', { shield }) : ''}${adeptSr ? tx('SR2E.Card.Actor.spellResistance', { adeptSr }) : ''}`
      + `${state.barrierDice ? ` + ${state.barrierDice} ${state.barrierName ?? tx('SR2E.Card.Actor.barrier2')}` : ''}`;
    await this.#post(this.#snapshot(label, result, {
      kind: 'soak',
      soak: { mode: 'spell', noun: 'damage', level: state.level, type: state.damageType, body: this.sys.attributes.body.total,
        casterSuccesses: state.casterSuccesses, spellName: state.spellName, before: this.#monitor(),
        ...(state.effectOnly ? { effectOnly: true } : {}),
        ...(state.essenceDrain ? { essenceDrain: { casterUuid: state.casterUuid } } : {}),
        // v0.45.0: a reflecting initiate bounces a spell back; a sustained power changes attributes.
        // v0.48.0: powers bounce too (RULES.OCCULT.metamagic.reflecting.powers).
        ...((isSpell || RULES.OCCULT.metamagic.reflecting.powers) && !state.reflected && this.initiate.techniques.includes('reflecting') ? { reflect: {
          casterUuid: state.casterUuid, spellName: state.spellName, force: state.force, resistAttribute: state.resistAttribute,
          level: state.level, damageType: state.damageType, ...(state.effectOnly ? { effectOnly: true } : {}),
          defense: isSpell ? defense : Number(this.system?.spellDefense ?? 0),
          ...(isSpell ? {} : { noun: 'power' as const, resistPool: state.resistPool ?? 'none' }),
        } } : {}),
        ...(state.powerEffect ? { powerEffect: { ...state.powerEffect, casterUuid: state.casterUuid, casterName: (fromUuidSync(state.casterUuid) as any)?.name ?? tx('SR2E.Card.Actor.theCaster') } } : {}) },
    }), result, rolls);
  }

  /**
   * Use a critter or spirit power: roll its potency (Force, rating, Magic or an attribute) against a
   * fixed TN or the target's attribute. If the target can resist, the card carries a Resist button
   * that works like resisting a combat spell; otherwise the successes stand on their own.
   */
  async usePower(power: any, opts: { targetUuid?: string | null; targetUuids?: string[]; poolDice?: number; modifiers?: TargetNumberModifier[]; exclude?: string[] } = {}): Promise<SuccessTestResult | null> {
    if (!this.canAct('usePower')) return null;
    const p = power.system;
    if (!p.active) {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.isAPassivePowerThereIs', { powerName: escHtml(power.name) }));
      return null;
    }
    const potency = powerPotency(p.dice, p.rating, {
      attributes: Object.fromEntries(ATTRIBUTE_KEYS.map((k) => [k, this.sys.attributes[k].total])) as any,
      // A great form spirit's powers are stronger (v0.45.0).
      ...(this.type === 'spirit' ? { force: (this.sys.force as number) + (this.sys.greatForm ? RULES.OCCULT.metamagic.invoking.powerBonus : 0) } : {}),
      magic: this.sys.derived.magic as number,
    });
    const uuids = [...new Set([...(opts.targetUuids ?? []), ...(opts.targetUuid ? [opts.targetUuid] : [])])];
    const targets: any[] = [];
    for (const u of uuids) {
      const t: any = await fromUuid(u);
      if (t?.system?.attributes) targets.push(t);
    }
    // v0.70.0: powers don't cross the astral/physical divide (as spells don't: castingPlaneProblem). An astral-only
    // user reaches only targets on the astral plane; an astral-only target only an astral or dual-natured user.
    if (RULES.FIXES_V70.astralBlocksPhysical) {
      const mine = this.astralOnly();
      for (const t of targets) {
        const theirs: string = t.astralOnly?.() ?? '';
        if (mine && !t.isAstral?.() && !t.system?.derived?.dualNatured) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.itsPowersCanTReachIn', { name: escHtml(this.name), mine, tName: escHtml(t.name) })); return null; }
        if (!mine && theirs && !this.isAstral() && !this.sys.derived?.dualNatured) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.onlySomethingOnTheAstralPlane', { tName: escHtml(t.name), theirs: escHtml(theirs) })); return null; }
      }
    }
    // v0.50.0: no line of sight, no power (RULES.TN_AUTO.magic.lineOfSight 'block'); v0.71.0 (R12): invisibility first.
    await this.spotInvisible(targets);
    if (RULES.TN_AUTO.magic.lineOfSight === 'block') {
      const unseen = this.#unseenTargets(targets);
      if (unseen.length) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.hasNoLineOfSightTo', { name: escHtml(this.name), unseen: escHtml(unseen.join(', ')) })); return null; }
    }
    const attrsOf = (t: any) => Object.fromEntries(ATTRIBUTE_KEYS.map((k) => [k, t.system.attributes[k]?.total ?? 0])) as any;
    const tnName = p.tnSource.charAt(0).toUpperCase() + p.tnSource.slice(1);
    let tn = powerTargetNumber(p.tnSource, p.targetNumber, targets.length ? attrsOf(targets[0]) : null);
    let tnLabel = tn.fromTarget ? tx('SR2E.Card.Actor.tnS', { name: targets[0].name, tnName }) : tx('SR2E.Card.Actor.tn6', { tnValue: tn.value });
    if (targets.length > 1 && p.tnSource !== 'fixed') {
      tn = { value: areaTargetNumber(targets.map((t) => attrsOf(t)[p.tnSource])), fromTarget: true };
      tnLabel = tx('SR2E.Card.Actor.tnOfTargets', { magicAreaTn: RULES.MAGIC.areaTn, tnName, targetsLength: targets.length });
    }

    // v0.45.0: a sustained power that changes attributes (effect-only powers).
    // v0.56.0: and TN or movement changes (its Mods fields, or a TN-changing Special: concealment, confusion, movement, fear, guard).
    const tnSpecial = (TN_POWER_SPECIALS as readonly string[]).includes(p.special ?? '');
    const modBundle: Partial<EffectBundle> = { testsTn: Number(p.mods?.testsTn ?? 0), perceivedTn: Number(p.mods?.perceivedTn ?? 0), attackedTn: Number(p.mods?.attackedTn ?? 0), movementFactor: Number(p.mods?.movementFactor ?? 1) || 1 };
    // v0.61.0: paralysis, petrification and binding hold the target (an effect with a token status).
    const holdSpecial = HOLD_SPECIALS.includes(String(p.special ?? ''));
    const fx: FxSpec | null = p.effect === 'effect' && ((p.sustained && (hasAttributeChange(p.attributes) || bundleHasEffect(modBundle))) || tnSpecial || holdSpecial)
      ? { name: power.name as string, attributes: { ...p.attributes }, perSuccess: Boolean(p.perSuccess), bundle: modBundle, kind: 'power', force: potency, ...(tnSpecial || holdSpecial ? { special: p.special } : {}) } : null;
    // v0.78.0 (RULES.BOOK_V78.paralysis 'drain'): the 2D6 minutes are rolled once here, so a re-rolled resistance keeps them.
    if (fx && p.special === 'paralysis' && RULES.BOOK_V78.paralysis.mode === 'drain') {
      fx.minutes = (await foundryRoller([])(Math.max(1, RULES.BOOK_V78.paralysis.minutesDice))).reduce((a, b) => a + b, 0);
      // Review fix: the drain is the being's Essence, not the power's dice.
      fx.essence = Math.max(0, Math.floor(Number(this.sys.derived?.essence ?? this.sys.essence ?? 0)));
    }
    const spellTargets = p.resist === 'none' ? [] : targets.map((t) => ({
      casterUuid: this.uuid as string, targetUuid: t.uuid as string, spellName: power.name, force: potency,
      resistAttribute: p.resist as AttributeKey, level: p.damageLevel as DamageLevel, damageType: p.damageType as DamageType,
      noun: 'power' as const, resistPool: RULES.POWERS.resistPool,
      ...(p.effect === 'effect' || p.special === 'essenceDrain' ? { effectOnly: true } : {}),
      ...(p.special === 'essenceDrain' ? { essenceDrain: true } : {}),
      ...(fx ? { powerEffect: fx } : {}),
    }));
    // v0.50.0: the modifiers picked (and switched off) go with it, so "Use again" keeps them.
    const repeat = p.repeating && power.uuid ? { repeat: { powerUuid: power.uuid as string, targetUuids: uuids, modifiers: opts.modifiers ?? [], exclude: opts.exclude ?? [] } } : {};
    // Unresisted sustained powers put their effect on straight away (on the user without a target).
    const own = fx && p.resist === 'none' ? { powerEffect: { ...fx, targetUuids: targets.length ? targets.map((t) => t.uuid as string) : [this.uuid as string] } } : {};
    const usePool = RULES.POWERS.usePool;
    // v0.61.0: in a fight, a repeating power is offered again each Combat Turn (MAGIC_V61.repeating).
    const fight: any = (game as any).combat;
    if (repeat.repeat && fight?.started && RULES.MAGIC_V61.repeating.autoPrompt) await replaceFlag(this, 'repeatPower', { ...repeat.repeat, name: power.name, combatId: fight.id, round: Number(fight.round ?? 0) }); // v0.75.0: written whole (today its keys never change; kept exact if they ever do)
    await this.leaveSignature('power', power.name, potency);
    return this.#runTest(tx('SR2E.Card.Actor.dice3', { powerName: power.name, potency, tnLabel }), potency, {
      targetNumber: tn.value,
      modifiers: opts.modifiers ?? [],
      // v0.50.0: powers count the background count like spells (RULES.TN_AUTO.magic.powersBackground).
      ...(RULES.TN_AUTO.magic.powersBackground ? { background: true } : {}),
      ...(opts.exclude?.length ? { exclude: opts.exclude } : {}),
      poolDice: usePool === 'none' ? 0 : opts.poolDice ?? 0,
      pool: usePool === 'none' ? 'combat' : usePool,
    }, spellTargets.length === 1 ? { kind: 'spell', spell: spellTargets[0], ...repeat }
      : spellTargets.length > 1 ? { kind: 'spell', spellTargets, ...repeat }
      : { kind: 'plain', ...repeat, ...own });
  }

  /**
   * Fill this actor from a parsed stat block. Attributes and ratings are overwritten; skills and
   * weapons with the same name are updated, others are created; armor goes on one
   * "Armor (imported)" item. Reaction and initiative are matched by adjusting the manual
   * bonuses, after allowing for any cyberware already on the actor.
   */
  async applyStatBlock(p: ParsedStatBlock, opts: { adept?: boolean } = {}): Promise<{ created: number; updated: number; warnings: string[] }> {
    const byName = (type: string, name: string) =>
      this.items.find((i: any) => i.type === type && i.name.trim().toLowerCase() === name.trim().toLowerCase());
    // v0.49.0: cyberware, bioware, spells and powers go in first, so the manual bonuses below don't count them twice.
    const extra = statBlockItems(p, opts.adept === undefined ? {} : { adept: opts.adept });
    const itemCreates: any[] = [];
    const itemUpdates: any[] = [];
    for (const it of extra.items) {
      const ex: any = byName(it.type, it.name);
      if (ex) itemUpdates.push({ _id: ex.id, system: it.system });
      else itemCreates.push({ name: it.name, type: it.type, system: it.system });
    }
    if (itemCreates.length) await this.createEmbeddedDocuments('Item', itemCreates);
    if (itemUpdates.length) await this.updateEmbeddedDocuments('Item', itemUpdates);
    const bonus = statBlockAttributeBonuses(extra.items);
    const update: Record<string, unknown> = {};
    for (const [key, v] of Object.entries(p.attributes)) {
      if (!v) continue;
      update[`system.attributes.${key}.base`] = v.base;
      update[`system.attributes.${key}.mod`] = (v.augmented ?? v.base) - v.base - ((bonus as Record<string, number>)[key] ?? 0);
    }
    if (p.magic !== undefined) update['system.magic'] = p.magic;
    if (p.karmaPool !== undefined) update['system.karma.pool'] = p.karmaPool;
    if (p.professionalRating !== undefined) update['system.professionalRating'] = p.professionalRating;
    await this.update(update);

    // The block shows current Essence; store the base so installed cyberware still adds up.
    const second: Record<string, unknown> = {};
    const d = this.sys.derived;
    if (p.essence !== undefined) {
      second['system.essence'] = Math.round((p.essence + d.essenceLoss) * 100) / 100;
      // v0.49.0: a block whose Essence doesn't match its cyberware.
      const max = 6;
      if ((second['system.essence'] as number) > max + 0.001) extra.warnings.push(tx('SR2E.Text.Actor.theBlockShowsEssenceButIts', { essence: p.essence, loss: Math.round(d.essenceLoss * 100) / 100, base: second['system.essence'], max }));
    }
    if (p.reaction) {
      const shown = p.reaction.augmented ?? p.reaction.base;
      second['system.reactionBonus'] = shown - (d.reaction - this.sys.reactionBonus);
    }
    if (p.initiativeDice !== undefined) {
      second['system.initiativeDiceBonus'] = Math.max(0, p.initiativeDice - (d.initiativeDice - this.sys.initiativeDiceBonus));
    }
    if (Object.keys(second).length) await this.update(second);

    const creates: any[] = [];
    const updates: any[] = [];

    for (const sk of p.skills) {
      const existing = byName('skill', sk.name);
      const spec = sk.specialization ? splitSpecialization(sk.specialization) : null;
      const system = { rating: sk.rating, ...(spec ? { specialization: spec.name, specializationRating: spec.rating } : {}) };
      if (existing) updates.push({ _id: existing.id, system });
      else creates.push({ name: sk.name, type: 'skill', system: { ...system, attribute: sk.attribute } });
    }
    for (const w of p.weapons) {
      const system = {
        damagePower: w.power, damageLevel: w.level, damageType: w.damageType, melee: w.melee, skill: w.skill,
        ...(w.strengthPower ? { strengthPower: true } : {}), ...(w.reach !== undefined ? { reach: w.reach } : {}),
      };
      const existing = byName('weapon', w.name);
      if (existing) updates.push({ _id: existing.id, system });
      else creates.push({ name: w.name, type: 'weapon', system });
    }
    if (p.armor && (p.armor.ballistic > 0 || p.armor.impact > 0)) {
      const system = { ballistic: p.armor.ballistic, impact: p.armor.impact, worn: true };
      const existing = byName('armor', 'Armor (imported)');
      if (existing) updates.push({ _id: existing.id, system });
      else creates.push({ name: 'Armor (imported)', type: 'armor', system });
    }
    if (creates.length) await this.createEmbeddedDocuments('Item', creates);
    if (updates.length) await this.updateEmbeddedDocuments('Item', updates);
    return { created: creates.length + itemCreates.length, updated: updates.length + itemUpdates.length, warnings: extra.warnings };
  }


  // ---------------------------------------------------------------- Matrix

  /** The cyberdeck in use, or null. */
  activeDeck(): any | null {
    return activeDeckOf(this);
  }

  /** Utility programs on this actor. */
  programs(): any[] {
    return [...this.items].filter((i: any) => i.type === 'program');
  }

  /**
   * v0.71.0 (R7): the rating a program runs at on this decker's deck: no higher than the working (damaged) MPCP
   * (RULES.FIXES_V71.mpcpCaps 'cap'). Frames, agents and IC (no MPCP of their own) run at their rating.
   */
  utilityRating(p: any): number {
    const r = Number(p?.system?.rating ?? 0);
    if (!p || this.type === 'ic') return r;
    const mp = Number(this.sys.derived?.matrix?.effectiveMpcp);
    if (!Number.isFinite(mp) || mp <= 0) return r;
    return programRunRating(r, mp).rating;
  }

  /** The best loaded (not erased) utility of a kind, or null. */
  bestUtility(kind: string): any | null {
    if (!kind) return null;
    return this.programs().filter((p: any) => p.system.loaded && !p.system.erased && p.system.kind === kind && SR2Actor.programReady(p))
      .sort((x: any, y: any) => (y.system.rating ?? 0) - (x.system.rating ?? 0))[0] ?? null;
  }

  /** v0.73.0 (O24): what this character knows of a host, for lists (the GM sees all). */
  hostKnowledgeOf(host: any): HostKnowledge {
    const cur: any = this.currentHost?.() ?? null;
    return hostKnowledge({ uuid: host.uuid, gridKind: host.system?.gridKind, ltgNumber: host.system?.ltgNumber } as any, {
      known: this.sys.matrix?.knownHosts ?? [], numbers: this.sys.matrix?.numbers ?? [],
      currentUuid: cur?.uuid ?? '', currentParentUuid: cur?.system?.parentUuid ?? '', isGM: Boolean(Boolean((game as any).user?.isGM)),
    } as any);
  }

  /** v0.73.0 (O24): learn a host ('located' or 'analyzed'). */
  async learnHostKnowledge(uuid: string, level: 'located' | 'analyzed'): Promise<void> {
    if (!uuid || !this.sys.matrix || !Array.isArray(this.sys.matrix.knownHosts)) return;
    const next = learnHost(this.sys.matrix.knownHosts ?? [], uuid, level);
    if (JSON.stringify(next) !== JSON.stringify(this.sys.matrix.knownHosts ?? [])) await this.update({ 'system.matrix.knownHosts': next });
  }

  /** The host this decker is in (null on the open grid or not jacked in). */
  currentHost(): any | null {
    const uuid = this.sys.matrix?.hostUuid;
    return uuid ? fromUuidSync(uuid) ?? null : null;
  }

  /** Whether this decker is jacked in with a working persona. */
  isJackedIn(): boolean {
    return Boolean(this.sys.matrix?.jackedIn) && Boolean(this.activeDeck());
  }

  /** IC actors in a host. */
  static hostIc(host: any): any[] {
    if (!host) return [];
    // v0.57.0: unlinked IC tokens too.
    return SR2Actor.tickActors().filter((a: any) => a.type === 'ic' && a.system?.hostUuid === host.uuid);
  }

  /** Updates that end a Matrix run's temporary state: crippling, decrypted barriers, any trace, frenzy, travel. */
  #endRunUpdate(): Record<string, unknown> {
    const t = this.sys.matrix?.trace ?? {};
    return {
      'system.matrix.crippled': { bod: 0, evasion: 0, masking: 0, sensors: 0 },
      'system.matrix.passed': [],
      'system.matrix.trace': { ...t, active: false },
      // Psychotropic effects that last the run (frenzy) end with it (v0.40.0).
      'system.matrix.psyche': [...(this.sys.matrix?.psyche ?? [])].filter((e: any) => e.until >= 0),
      'system.matrix.transit': { hostUuid: '', hops: 0, round: -1, worldTime: -1 },
      // v0.57.0: black IC holds, maneuvers and the reality filter end with the run.
      'system.matrix.engagedBy': [],
      'system.matrix.maneuvers': [],
      'system.matrix.filter': { hostUuid: '', ok: -1 },
    };
  }

  /** Jack in (or move to another host): needs a cyberdeck in use and a persona that has not crashed. */
  async jackIn(hostUuid: string | null = null): Promise<boolean> {
    if (!this.sys.matrix?.jackedIn && !this.canAct('jack in')) return false;
    // v0.70.0: black IC holding the decker: no moving away (jack out takes a test). The GM may still move them.
    const hold = this.isJackedIn() ? this.blackIcHold() : null;
    if (hold && !Boolean((game as any).user?.isGM)) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.isHoldingJackingOutTakesA', { holdName: escHtml(hold.name), name: escHtml(this.name) })); return false; }
    if (!this.activeDeck()) {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.hasNoCyberdeckInUse', { name: escHtml(this.name) }));
      return false;
    }
    if (this.sys.derived.matrix?.crashed) {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.sPersonaHasCrashedRepairThe', { name: escHtml(this.name) }));
      return false;
    }
    if (!this.#linkOk()) return false;
    // v0.57.0: a host that is shut down takes nobody in.
    const target: any = hostUuid ? fromUuidSync(hostUuid) : null;
    if (RULES.MATRIX_V57.shutdown.enabled && target?.system?.alert === 'shutdown') {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.isShutDownNobodyCanLog', { targetName: escHtml(target.name) }));
      return false;
    }
    // A datajack to plug the deck into (RULES.CYBERWARE.datajack).
    if (!this.isJackedIn()) {
      const dj = datajackCheck('decking', Boolean(this.sys.derived?.cyber?.datajack));
      if (dj === 'block') {
        ui.notifications?.warn?.(tx('SR2E.Notify.Actor.hasNoDatajackToJackIn', { name: escHtml(this.name) }));
        return false;
      }
      if (dj === 'warn') ui.notifications?.warn?.(tx('SR2E.Notify.Actor.hasNoDatajackJackingInAnyway', { name: escHtml(this.name) }));
    }
    const was = this.isJackedIn();
    // v0.59.0: jacking in takes an action (RULES.ACTIONS.costs.jackIn); moving between hosts is the Matrix's own.
    if (!was && !(await this.useAction('jackIn', tx('SR2E.Card.Actor.jackingIn')))) return false;
    const moved = (this.sys.matrix?.hostUuid ?? '') !== (hostUuid ?? '');
    await this.update({
      'system.matrix.jackedIn': true, 'system.matrix.hostUuid': hostUuid ?? '',
      // Barrier IC decrypted in one host do not stay decrypted in the next.
      ...(moved ? { 'system.matrix.passed': [] } : {}),
    });
    // v0.73.0 (O24): where it jacks in is known now.
    if (hostUuid) await this.learnHostKnowledge(hostUuid, hostEntryKnowledge());
    const host: any = hostUuid ? await fromUuid(hostUuid) : null;
    await ChatMessage.create({
      speaker: ChatMessage.getSpeaker({ actor: this }),
      content: `<p><strong>${escText(this.name)}</strong> ${host ? (was ? tx('SR2E.Card.Actor.movesToHost', { host: `<strong>${escText(host.name)}</strong>` }) : tx('SR2E.Card.Actor.jacksInToHost', { host: `<strong>${escText(host.name)}</strong>` })) : (was ? tx('SR2E.Card.Actor.movesToTheGrid') : tx('SR2E.Card.Actor.jacksInToTheGrid'))}.</p>`,
    });
    if (host) await this.realityFilterCheck(host);
    return true;
  }

  /**
   * Jack out on purpose (no dump shock). Ends crippling, decrypted barriers and any trace.
   * v0.57.0: a decker engaged by black IC must break free first (a test; `force` skips it).
   */
  async jackOut(opts: { poolDice?: number; force?: boolean } = {}): Promise<void> {
    if (!this.sys.matrix?.jackedIn) return;
    const hold = opts.force ? null : this.blackIcHold();
    if (hold) {
      const cfg = RULES.MATRIX_V57.blackIcHold;
      const attr = (this.sys.attributes?.[cfg.attribute]?.total as number | undefined) ?? 0;
      const t = jackOutTest(hold, attr, hold.name);
      await this.#runTest(t.label, t.dice, {
        targetNumber: t.tn, poolDice: cfg.pool ? (opts.poolDice ?? 0) : 0, pool: 'hacking', modifiers: matrixWoundModifiers(Number(this.sys.matrix?.monitor ?? 0)),
      }, { kind: 'jackOut', jackOut: { icUuid: hold.uuid, icName: hold.name, needed: t.needed } });
      return;
    }
    // v0.59.0: jacking out on purpose takes an action (RULES.ACTIONS.costs.jackOut).
    if (!opts.force && !(await this.useAction('jackOut', tx('SR2E.Card.Actor.jackingOut')))) return;
    await this.#leaveMatrix();
  }

  /** v0.57.0: jack out now (no dump shock); hitchers come out with the decker. */
  async #leaveMatrix(): Promise<void> {
    await this.update({ 'system.matrix.jackedIn': false, 'system.matrix.hostUuid': '', ...this.#endRunUpdate() });
    await ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor: this }), content: `<p><strong>${escText(this.name)}</strong> ${tx('SR2E.Card.Actor.jacksOut')}</p>` });
    await this.#unhitchAll();
  }

  /** v0.57.0: the black IC holding this decker in their host (null when nothing holds them). */
  blackIcHold(): HoldingIc | null {
    if (!RULES.MATRIX_V57.blackIcHold.enabled || !this.isJackedIn()) return null;
    const host = this.currentHost();
    if (!host) return null;
    const ics: HoldingIc[] = SR2Actor.hostIc(host).map((i: any) => ({
      uuid: i.uuid as string, name: i.name as string, rating: Number(i.system.rating ?? 0), black: i.system.category === 'black',
      crashed: Boolean(i.system.derived?.crashed), hostUuid: String(i.system.hostUuid ?? ''),
    }));
    const evaded = activeManeuvers(this.sys.matrix?.maneuvers ?? [], SR2Actor.matrixNow()).filter((m) => m.kind === 'evade').map((m) => m.targetUuid);
    return holdingIc(this.sys.matrix?.engagedBy ?? [], ics, host.uuid, evaded);
  }

  /** v0.57.0: a jack-out test against black IC: enough successes and the decker is out. */
  async #resolveJackOut(snap: TestSnapshot): Promise<Resolved> {
    const j = snap.jackOut!;
    const free = snap.successes >= j.needed;
    if (!free) {
      // A re-roll or GM change that turns an escape into a failure can't pull the decker back in.
      const out = j.applied && !this.sys.matrix?.jackedIn
        ? tx('SR2E.Card.Actor.isAlreadyOutJackThemBack', { name: escText(this.name) }) : '';
      return { html: `<p><strong>${tx('SR2E.Card.Actor.holds5', { jIcName: escText(j.icName), name: escText(this.name) })}</strong> ${tx('SR2E.Card.Actor.inTheMatrix', { out })}</p>`, flags: {}, snap };
    }
    if (j.applied) return { html: `<p><strong>${tx('SR2E.Card.Actor.breaksFree', { name: escText(this.name) })}</strong> ${tx('SR2E.Card.Actor.alreadyOut')}</p>`, flags: {}, snap };
    if (this.sys.matrix?.jackedIn) await this.#leaveMatrix();
    return { html: `<p><strong>${tx('SR2E.Card.Actor.breaksFreeOf', { name: escText(this.name), jIcName: escText(j.icName) })}</strong> ${tx('SR2E.Card.Actor.andJacksOut')}</p>`, flags: {}, snap: { ...snap, jackOut: { ...j, applied: true } } };
  }

  /** TN modifiers for how this decker is connected (RULES.MATRIX.connections), and a moving vehicle they ride in. */
  connectionMods(): TargetNumberModifier[] {
    const ride: any = this.type === 'vehicle' ? null : (this.vehicleAboard?.() ?? null);
    const moving = Boolean(ride && Number(ride.system?.currentSpeed ?? 0) > 0);
    return connectionModifiers(this.sys.matrix?.connection ?? 'jackpoint', moving);
  }

  /** Now, for Matrix timers: the Combat Turn of a started combat (else null), and the world time. */
  static matrixNow(): { round: number | null; worldTime: number; combatId: string | null } {
    // v0.81.0: the combat's id too, so a round stamped in one combat isn't compared with another's (rules/util.ts sameCombatRound).
    const combat: any = (game as any).combat;
    return { round: combat?.started ? Number(combat.round ?? 0) : null, worldTime: sysNow(), combatId: combat?.started ? String(combat.id ?? '') : null };
  }

  /** Smoke released in a host (v0.40.0): + TN on every Matrix test there while it lasts. */
  static smokeMods(host: any): TargetNumberModifier[] {
    const c = host?.system?.smoke;
    if (!smokeActive(c, SR2Actor.matrixNow())) return [];
    return [{ label: tx('SR2E.Card.Mod.smoke', { rating: c.rating }), value: c.tn }];
  }

  /** Mirrors on a persona (v0.40.0): + TN on attacks rolled against its Evasion. */
  static mirrorsMods(target: any): TargetNumberModifier[] {
    if (!target?.isJackedIn?.()) return [];
    // v0.57.0: read live (a utility that finished loading counts at once).
    const r = Number(target.bestUtility?.('mirrors')?.system?.rating ?? target.system?.derived?.matrix?.mirrors ?? 0);
    const tn = mirrorsTn(r);
    return tn ? [{ label: tx('SR2E.Card.Mod.sMirrors', { targetName: target.name, r }), value: tn }] : [];
  }

  /** TN modifiers on this decker's own Matrix tests: connection, cyberphobia, smoke in the host (v0.40.0). */
  matrixTestMods(host: any = this.currentHost(), opts: { wounds?: boolean } = {}): TargetNumberModifier[] {
    const t = this.isTortoise() && RULES.MATRIX.tortoise.tn ? [{ id: 'tortoise', label: tx('SR2E.Card.Mod.tortoise'), value: RULES.MATRIX.tortoise.tn }] : [];
    // v0.57.0: the persona's own Matrix damage, and a reality filter that failed in this host.
    const filter = this.sys.derived?.matrix?.filterModifiers ?? [];
    return [...this.connectionMods(), ...(this.matrixLink()?.modifiers ?? []), ...t, ...psycheModifiers(this.sys.matrix?.psyche ?? [], SR2Actor.matrixNow().worldTime), ...SR2Actor.smokeMods(host),
      ...(opts.wounds === false ? [] : matrixWoundModifiers(Number(this.sys.matrix?.monitor ?? 0))), ...filter];
  }

  /** Grid travel still to go (v0.40.0): the node, and Combat Turns or seconds left; null once arrived. */
  transitLeft(): { hostUuid: string; hostName: string; turns: number | null; seconds: number | null } | null {
    const t = this.sys.matrix?.transit;
    if (!t?.hostUuid || t.hostUuid !== (this.sys.matrix?.hostUuid ?? '')) return null;
    const now = SR2Actor.matrixNow();
    if (traceComplete(t, now)) return null;
    const turns = t.round >= 0 && now.round != null ? Math.max(0, t.round - now.round) : null;
    const seconds = t.worldTime >= 0 ? Math.max(0, t.worldTime - now.worldTime) : null;
    return { hostUuid: t.hostUuid, hostName: fromUuidSync(t.hostUuid)?.name ?? tx('SR2E.Card.Actor.theNode'), turns, seconds };
  }

  /** Refuse (or warn about) acting while still travelling to the node (RULES.MATRIX.travel). True = go on. */
  #arrived(force = false): boolean {
    const t = this.transitLeft();
    if (!t) return true;
    const msg = tx('SR2E.Card.Actor.isStillOnTheWayTo', { name: this.name, hostName: t.hostName, part: t.turns != null ? tCount(t.turns, 'SR2E.Card.Actor.combatTurns') : `${t.seconds} s` });
    if (RULES.MATRIX.travel.blockInTransit && !force) {
      ui.notifications?.warn?.(escHtml(msg));
      return false;
    }
    ui.notifications?.info?.(escHtml(msg));
    return true;
  }

  /** Release a loaded Smoke utility into this decker's host (v0.40.0): no test. */
  async releaseSmoke(programId: string): Promise<SmokeCloud | null> {
    const prog: any = this.items.get(programId);
    if (!prog || prog.system.kind !== 'smoke' || !prog.system.loaded || prog.system.erased || !(prog.system.rating > 0) || !SR2Actor.programReady(prog)) {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.pickALoadedSmokeUtility'));
      return null;
    }
    const host: any = this.isJackedIn() ? this.currentHost() : null;
    if (!host) {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.mustBeInAHostTo', { name: escHtml(this.name) }));
      return null;
    }
    const now = SR2Actor.matrixNow();
    const cloud = smokeCloud(this.utilityRating(prog), this.name as string, now);
    const turns = now.round != null ? cloud.round - now.round : Math.round((cloud.worldTime - now.worldTime) / Math.max(1, RULES.MATRIX.utilities.smoke.secondsPerTurn));
    await ChatMessage.create({
      speaker: ChatMessage.getSpeaker({ actor: this }),
      content: `<p><strong>${escText(this.name)}</strong> ${tx('SR2E.Card.Actor.releasesSmokeIn', { progName: escText(prog.name), utilityRating: this.utilityRating(prog) })} <strong>${escText(host.name)}</strong>${tx('SR2E.Card.Actor.everyMatrixTestThereIsAt')} <strong>${tx('SR2E.Card.Actor.tn7', { cloudTn: cloud.tn })}</strong> ${tCount(turns, 'SR2E.Card.Actor.forCombatTurns', { part: now.round != null ? tx('SR2E.Card.Actor.untilCombatTurn', { cloudRound: cloud.round }) : '' })}</p>`,
    });
    await SR2Actor.changeHost(host, { smoke: cloud }, tx('SR2E.Card.Actor.releasesSmokeIn2', { name: this.name, hostName: host.name }), this.uuid as string);
    return cloud;
  }

  /** The Computer skill (or Intelligence) dice for Matrix tests. */
  #matrixDice() {
    return this.#skillDice(this.findSkill(RULES.MATRIX.skill), false, null, 'intelligence');
  }

  /** A host's files that this decker has located. */
  static foundFiles(host: any, deckerUuid: string): DataFile[] {
    return [...(host?.system?.files ?? [])].filter((f: any) => (f.foundBy ?? []).includes(deckerUuid));
  }

  /** Site devices reachable through a host's Slave subsystem (sites linked to it). */
  static slaveDevices(host: any): Array<{ site: any; device: any }> {
    if (!host) return [];
    const out: Array<{ site: any; device: any }> = [];
    for (const site of allActors().filter((a: any) => a.type === 'site' && a.system.hostUuid === host.uuid)) {
      for (const d of site.system.devices ?? []) out.push({ site, device: d });
    }
    return out;
  }

  /** Whether an actor is one of a host's security deckers (v0.40.0). */
  static isSecurityDecker(host: any, actor: any): boolean {
    return Boolean(host && actor && (host.system?.securityDeckers ?? []).includes(actor.uuid));
  }

  /** Jacked-in personas in a host that are not its security deckers: the intruders. */
  static intruders(host: any): any[] {
    if (!host) return [];
    return allActors().filter((a: any) => a.isJackedIn?.() && (a.system.matrix?.hostUuid ?? '') === host.uuid && !SR2Actor.isSecurityDecker(host, a));
  }

  /**
   * A security decker acts in their own host (v0.40.0, RULES.MATRIX.security): Computer + Hacking
   * Pool, no detection roll. 'spotIntruder' (TN = their Detection Factor), 'traceIntruder' (TN =
   * their Evasion + Mirrors, minus a loaded Track utility), 'rearmDevice' (a bypassed device of a
   * linked site) and 'cancelAlert' (TN legitTn).
   */
  async securityAction(op: 'spotIntruder' | 'traceIntruder' | 'rearmDevice' | 'cancelAlert', opts: {
    targetUuid?: string | null; siteUuid?: string | null; deviceId?: string | null; poolDice?: number; modifiers?: TargetNumberModifier[];
  } = {}): Promise<SuccessTestResult | null> {
    const host: any = this.isJackedIn() ? this.currentHost() : null;
    if (!host || !SR2Actor.isSecurityDecker(host, this)) {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.isNotASecurityDeckerOf', { name: escHtml(this.name) }));
      return null;
    }
    if (!this.#arrived()) return null;
    const sec = RULES.MATRIX.security;
    const labels = { spotIntruder: tx('SR2E.Card.Actor.spotIntruder'), traceIntruder: tx('SR2E.Card.Actor.traceIntruder'), rearmDevice: tx('SR2E.Card.Actor.reArmDevice'), cancelAlert: tx('SR2E.Card.Actor.cancelAlert') };
    const ctx: SystemContext = { hostName: host.name, hostUuid: host.uuid, subsystem: 'Security', operation: labels[op], opId: op, effect: op, security: true };
    let tn = sec.legitTn;
    let tnNote = tx('SR2E.Card.Actor.tn8', { tn });
    let extra: TargetNumberModifier[] = [];
    if (op === 'spotIntruder' || op === 'traceIntruder') {
      const target: any = opts.targetUuid ? fromUuidSync(opts.targetUuid) : null;
      if (!target || !SR2Actor.intruders(host).some((a: any) => a.uuid === target.uuid)) {
        ui.notifications?.warn?.(tx('SR2E.Notify.Actor.pickAnIntruderIn', { hostName: escHtml(host.name) }));
        return null;
      }
      const m = target.system.derived.matrix;
      if (op === 'spotIntruder') {
        tn = target.liveDetectionFactor?.() ?? m.detectionFactor;
        tnNote = tx('SR2E.Card.Actor.sDetectionFactor', { targetName: target.name, tn });
      } else {
        tn = m.evasion;
        tnNote = tx('SR2E.Card.Actor.sEvasion', { targetName: target.name, tn });
        const track: any = this.bestUtility('track');
        extra = [...SR2Actor.mirrorsMods(target), ...utilityModifiers(track ? { name: `${track.name} ${track.system.rating}`, rating: this.utilityRating(track) } : null)];
      }
      ctx.targetUuid = target.uuid;
    } else if (op === 'rearmDevice') {
      const dev = SR2Actor.slaveDevices(host).find((x) => x.site.uuid === opts.siteUuid && x.device.id === opts.deviceId);
      if (!dev) {
        ui.notifications?.warn?.(tx('SR2E.Notify.Actor.pickADeviceOfASite', { hostName: escHtml(host.name) }));
        return null;
      }
      if (!dev.device.bypassed) {
        ui.notifications?.warn?.(tx('SR2E.Notify.Actor.hasNotBeenBypassed', { deviceName: escHtml(dev.device.name) }));
        return null;
      }
      ctx.siteUuid = dev.site.uuid;
      ctx.deviceId = dev.device.id;
      tnNote = tx('SR2E.Card.Actor.tn9', { deviceName: dev.device.name, tn });
    }
    const own = this.#matrixDice();
    return this.#runTest(tx('SR2E.Card.Actor.securityDecker', { labels: labels[op], hostName: host.name, tnNote, ownSuffix: own.suffix }), own.dice, {
      targetNumber: tn, poolDice: opts.poolDice ?? 0, pool: 'hacking',
      modifiers: [...extra, ...(opts.modifiers ?? []), ...this.matrixTestMods(host), ...own.modifiers],
    }, { kind: 'system', system: ctx });
  }

  /**
   * A system test: the host first rolls its Security Value vs this decker's Detection Factor (its
   * successes go on the security tally, seen by the GM), then the decker rolls Computer + Hacking
   * Pool vs the subsystem rating, lowered by the loaded utility used.
   *
   * v0.27.0: `operationId` picks an operation from RULES.MATRIX.operations, which sets the
   * subsystem, the default utility (the best loaded one of its kind) and what a success does.
   * A barrier IC guarding the subsystem refuses the test until it is crashed or decrypted.
   */
  async systemTest(subsystem: string, opts: {
    programId?: string | null; poolDice?: number; modifiers?: TargetNumberModifier[]; operation?: string;
    operationId?: string; targetUuid?: string | null; fileId?: string | null; siteUuid?: string | null; deviceId?: string | null; force?: boolean;
    /** A frame of this decker's runs the operation in its own host (v0.28.0). */
    frameUuid?: string | null;
    /** v0.50.0: found-by-themselves modifiers switched off in the dialog. */
    exclude?: string[];
    /** v0.46.0: log on by dialling this LTG number; upload this deck file (deck id + index); edit a file (alter with a note, or erase). */
    number?: string | null; upload?: { deckId: string; index: number } | null; editMode?: 'alter' | 'erase'; editNote?: string;
    /** v0.46.0: an agent searching by itself: the grid path is not enforced. */
    ignorePath?: boolean;
    /** v0.57.0: a subsystem data bomb to defuse; a comcall on the LTG. */
    bombSubsystem?: string | null; callId?: string | null;
  } = {}): Promise<SuccessTestResult | null> {
    const m = this.sys.derived.matrix;
    const frame: any = opts.frameUuid ? await fromUuid(opts.frameUuid) : null;
    if (opts.frameUuid && (!frame || !['frame', 'agent'].includes(frame.system?.kind) || frame.system.ownerUuid !== this.uuid || frame.system.derived?.crashed)) {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.thatFrameIsNotOneOf'));
      return null;
    }
    // An agent works on its own; the decker (and a frame's owner) must be jacked in (v0.40.0).
    const agent = frame?.system?.kind === 'agent';
    if (!agent && (!this.isJackedIn() || !m)) {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.isNotJackedIn', { name: escHtml(this.name) }));
      return null;
    }
    const op = opts.operationId ? operation(opts.operationId) : null;
    if (opts.operationId && !op) {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.unknownOperation', { operationId: escHtml(opts.operationId) }));
      return null;
    }
    if (!frame && op?.effect !== 'logon' && !this.#arrived(opts.force)) return null;
    if (!frame && !this.#linkOk(opts.force)) return null;
    // Where it happens: the decker's (or frame's) host; logging on happens at the node logged on to.
    const hereUuid = frame ? frame.system.hostUuid : this.sys.matrix.hostUuid;
    const here: any = hereUuid ? await fromUuid(hereUuid) : null;
    let host: any = here;
    let dialled = false;
    if (op?.effect === 'logon') {
      // v0.70.0: black IC holding the decker: no logging on elsewhere either (jacking out takes a test).
      const held = frame ? null : this.blackIcHold();
      if (held && !Boolean((game as any).user?.isGM)) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.isHoldingNoLoggingOnElsewhere', { heldName: escHtml(held.name), name: escHtml(this.name) })); return null; }
      // v0.46.0: dialling an LTG number finds the node by its number.
      if (opts.number && !opts.targetUuid) {
        const byNumber: any = allActors().find((a: any) => a.type === 'host' && numberMatches(opts.number, a.system?.ltgNumber));
        if (!byNumber) {
          ui.notifications?.warn?.(tx('SR2E.Notify.Actor.noNodeAnswers', { number: escHtml(opts.number) }));
          return null;
        }
        opts = { ...opts, targetUuid: byNumber.uuid };
      }
      host = opts.targetUuid ? await fromUuid(opts.targetUuid) : null;
      if (!host || host.type !== 'host') {
        ui.notifications?.warn?.(tx('SR2E.Notify.Actor.pickTheHostLtgOrRtg'));
        return null;
      }
      dialled = Boolean(opts.number) && numberMatches(opts.number, host.system?.ltgNumber) && RULES.MATRIX.numbers.dialAnywhere;
      if (host.uuid === hereUuid) {
        ui.notifications?.warn?.(tx('SR2E.Notify.Actor.alreadyIn', { hostName: escHtml(host.name) }));
        return null;
      }
      // v0.57.0: a host that is shut down takes no log-ons.
      if (RULES.MATRIX_V57.shutdown.enabled && host.system?.alert === 'shutdown' && !opts.force) {
        ui.notifications?.warn?.(tx('SR2E.Notify.Actor.isShutDownNobodyCanLog2', { hostName: escHtml(host.name) }));
        return null;
      }
      const node = (h: any): GridNode => ({ uuid: h.uuid, gridKind: h.system.gridKind ?? 'host', parentUuid: h.system.parentUuid ?? '' });
      if (!dialled && !opts.ignorePath && !gridReachable(here ? node(here) : null, node(host)) && !opts.force) {
        const msg = tx('SR2E.Card.Actor.isNotReachableFromGoThrough', { hostName: host.name, hereName: here?.name ?? tx('SR2E.Card.Actor.outsideTheGrid'), part: host.system.parentUuid ? ` (${fromUuidSync(host.system.parentUuid)?.name ?? tx('SR2E.Card.Actor.itsParent')})` : '' });
        if (RULES.MATRIX.grid.enforcePath === 'block') {
          ui.notifications?.warn?.(escHtml(msg));
          return null;
        }
        ui.notifications?.info?.(escHtml(msg));
      }
    }
    // v0.73.0 (O22): black IC holding the decker: Graceful Logoff doesn't get away (NETRIG_V73.logoffHold).
    if (op?.effect === 'logoff') {
      const lh = logoffHoldCheck({ hold: frame ? null : this.blackIcHold(), deckerName: this.name, frame: Boolean(frame), isGM: Boolean(Boolean((game as any).user?.isGM)), force: opts.force } as any);
      if (lh.block) { ui.notifications?.warn?.(escHtml(lh.note)); return null; }
    }
    if (!host || host.type !== 'host') {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.isNotInAHostFirst', { part: frame ? escHtml(frame.name) : escHtml(this.name), part2: frame ? tx('SR2E.Notify.Actor.launchItIntoOne') : tx('SR2E.Notify.Actor.jackInToOne') }));
      return null;
    }
    const sub = op?.subsystem ?? subsystem;
    const rating = host.system.subsystems?.[sub];
    if (typeof rating !== 'number') {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.unknownSubsystem', { sub: escHtml(sub) }));
      return null;
    }
    // The utility: the one asked for, else (for a catalog operation) the best loaded one of its kind.
    // A frame or agent uses the utilities it carries; without any, its owner's (v0.40.0).
    const carried = frame ? frame.programs().filter((p: any) => p.system.loaded && !p.system.erased && SR2Actor.programReady(p)) : [];
    const source: any = !frame ? this : carried.length || !RULES.MATRIX.carry.ownerUtilities ? frame : this;
    const prog: any = opts.programId
      ? source.items.get(opts.programId) ?? null
      : opts.programId === undefined && op?.utility ? source.bestUtility(op.utility) : null;
    if (prog && (!prog.system.loaded || prog.system.erased || !SR2Actor.programReady(prog))) {
      ui.notifications?.warn?.((prog.system.loaded && !prog.system.erased ? tx('SR2E.Notify.Actor.isNotLoadedWithYetStillLoading', { progName: escHtml(prog.name) }) : tx('SR2E.Notify.Actor.isNotLoadedPlain', { progName: escHtml(prog.name) })));
      return null;
    }
    const effect = op?.effect ?? 'none';
    // Barrier IC on this subsystem.
    const ics = SR2Actor.hostIc(host).map((i: any) => ({ uuid: i.uuid as string, behavior: i.system.behavior as string, guards: i.system.guards as string, crashed: Boolean(i.system.derived?.crashed), name: i.name as string, rating: i.system.rating as number }));
    const guard = guardingIc(ics, sub, this.sys.matrix?.passed ?? []);
    if (guard && effect !== 'decryptGuard' && !opts.force) {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.guardsTheSubsystemCrashItOr', { guardName: escHtml(guard.name), sub: escHtml(cap(sub)) }));
      return null;
    }
    const ctx: SystemContext = { hostName: host.name, hostUuid: host.uuid, subsystem: cap(sub), operation: opts.operation || op?.label || '', ...(op ? { opId: op.id, effect } : {}), ...(frame ? { frameUuid: frame.uuid } : {}) };
    if (effect === 'logon') {
      ctx.targetUuid = host.uuid;
      ctx.fromUuid = hereUuid ?? '';
      if (dialled) ctx.dialled = true;
    }
    // v0.46.0: uploading a file from the deck, and how a file is edited.
    if (effect === 'upload') {
      const deck: any = opts.upload ? this.items.get(opts.upload.deckId) : null;
      const f = deck?.system?.files?.[opts.upload?.index ?? -1];
      if (!f) {
        ui.notifications?.warn?.(tx('SR2E.Notify.Actor.pickAFileInSDeck', { name: escHtml(this.name) }));
        return null;
      }
      ctx.upload = { name: f.name, size: f.size ?? 0, value: f.value ?? 0, paydata: Boolean(f.paydata), ioSpeed: Number(deck.system.ioSpeed ?? 0) };
    }
    if (effect === 'editFile') {
      ctx.editMode = opts.editMode === 'erase' ? 'erase' : 'alter';
      if (opts.editNote) ctx.editNote = String(opts.editNote).slice(0, 200);
    }
    // What the operation works on, and a TN from the target for decrypting.
    let tn = rating as number;
    let tnNote = `${cap(sub)} ${rating}`;
    const found = SR2Actor.foundFiles(host, this.uuid);
    // v0.57.0: a subsystem's data bomb to defuse.
    if (effect === 'defuseBomb' && !opts.fileId) {
      const b = (host.system.bombs ?? []).find((x: any) => x.subsystem === (opts.bombSubsystem ?? '') && x.rating > 0 && (x.foundBy ?? []).includes(this.uuid));
      if (!b) {
        ui.notifications?.warn?.(tx('SR2E.Notify.Actor.knowsOfNoDataBombOn', { name: escHtml(this.name), bombSubsystem: escHtml(cap(opts.bombSubsystem ?? '?')) }));
        return null;
      }
      tn = b.rating;
      tnNote = tx('SR2E.Card.Actor.dataBombOn', { rating: b.rating, subsystem: cap(b.subsystem) });
      ctx.bombSubsystem = b.subsystem;
    }
    const needFile = ['download', 'decryptFile', 'editFile', 'scanFile'].includes(effect) || (effect === 'defuseBomb' && Boolean(opts.fileId));
    if (needFile) {
      const file = found.find((f) => f.id === opts.fileId);
      if (!file) {
        ui.notifications?.warn?.(tx('SR2E.Notify.Actor.hasNotLocatedThatFileLocate', { name: escHtml(this.name) }));
        return null;
      }
      const protection = file.scramble || file.encrypted;
      if (effect === 'defuseBomb') {
        if (!(Number(file.bomb ?? 0) > 0) || !(file.bombFoundBy ?? []).includes(this.uuid)) {
          ui.notifications?.warn?.(tx('SR2E.Notify.Actor.knowsOfNoDataBombOn2', { name: escHtml(this.name), fileName: escHtml(file.name) }));
          return null;
        }
        tn = Number(file.bomb ?? 0);
        tnNote = tx('SR2E.Card.Actor.dataBomb', { fileName: file.name, tn });
      } else if (effect === 'scanFile') {
        // Scanning a file for bombs is a plain Files test.
      } else if (effect === 'decryptFile') {
        if (!protection) {
          ui.notifications?.warn?.(tx('SR2E.Notify.Actor.isNotEncrypted', { fileName: escHtml(file.name) }));
          return null;
        }
        tn = protection;
        tnNote = `${file.name}: ${file.scramble ? tx('SR2E.Card.Actor.scrambleIc') : tx('SR2E.Card.Actor.encryption')} ${protection}`;
      } else if (protection && !opts.force) {
        ui.notifications?.warn?.(tx('SR2E.Notify.Actor.isDecryptItFirst', { fileName: escHtml(file.name), part: file.scramble ? tx('SR2E.Notify.Actor.protectedByScrambleIc') : tx('SR2E.Notify.Actor.encrypted') }));
        return null;
      }
      ctx.fileId = file.id;
    }
    if (effect === 'decryptGuard') {
      const target = ics.find((i) => i.uuid === opts.targetUuid) ?? guard;
      if (!target || target.behavior !== 'barrier') {
        ui.notifications?.warn?.(tx('SR2E.Notify.Actor.noBarrierIcGuardsTheSubsystem', { sub: escHtml(cap(sub)) }));
        return null;
      }
      tn = target.rating;
      tnNote = `${target.name} ${target.rating}`;
      ctx.targetUuid = target.uuid;
    }
    if (effect === 'analyzeIc') {
      const target = ics.find((i) => i.uuid === opts.targetUuid);
      if (!target) {
        ui.notifications?.warn?.(tx('SR2E.Notify.Actor.pickAnIcInThisHost'));
        return null;
      }
      ctx.targetUuid = target.uuid;
    }
    if (effect === 'controlSlave' || effect === 'monitorSlave') {
      const dev = SR2Actor.slaveDevices(host).find((x) => x.site.uuid === opts.siteUuid && x.device.id === opts.deviceId);
      if (!dev) {
        ui.notifications?.warn?.(tx('SR2E.Notify.Actor.pickADeviceOfASite', { hostName: escHtml(host.name) }));
        return null;
      }
      ctx.siteUuid = dev.site.uuid;
      ctx.deviceId = dev.device.id;
    }

    // v0.57.0: passcodes and comcalls.
    if (effect === 'invalidate') {
      const v: string[] = host.system.validated ?? [];
      const t = opts.targetUuid && v.includes(opts.targetUuid) ? opts.targetUuid : null;
      if (!t) {
        ui.notifications?.warn?.(tx('SR2E.Notify.Actor.pickADeckerHoldingAValid', { hostName: escHtml(host.name) }));
        return null;
      }
      ctx.targetUuid = t;
    }
    if (['makeCall', 'tapCall', 'rerouteCall'].includes(effect)) {
      if (RULES.MATRIX_V57.comcalls.needsLtg && host.system.gridKind !== 'ltg') {
        ui.notifications?.warn?.(tx('SR2E.Notify.Actor.isNotAnLtgComcallsGo', { hostName: escHtml(host.name) }));
        return null;
      }
      if (effect !== 'makeCall') {
        const call = (host.system.calls ?? []).find((c: any) => c.id === opts.callId);
        if (!call) {
          ui.notifications?.warn?.(tx('SR2E.Notify.Actor.pickACallOn', { hostName: escHtml(host.name) }));
          return null;
        }
        ctx.callId = call.id;
      }
      if (effect !== 'tapCall') {
        const n = String(opts.number ?? '').trim();
        if (!n) {
          ui.notifications?.warn?.(tx('SR2E.Notify.Actor.enterTheNumberToCall'));
          return null;
        }
        ctx.number = n.slice(0, 40);
      }
    }

    // The host's detection roll: against the decker's Detection Factor, or an agent's own (v0.40.0).
    // A security decker of this host is a legitimate user: no detection roll.
    const legit = !frame && SR2Actor.isSecurityDecker(host, this) && RULES.MATRIX.security.noDetection;
    if (!legit) {
      const ownDf = agent && RULES.MATRIX.agents.ownDetection;
      // v0.57.0: a validated passcode makes the decker harder to spot.
      const validated = !ownDf && (host.system.validated ?? []).includes(this.uuid);
      const df = ownDf ? agentDetectionFactor(frame.system.rating, frame.bestUtility('sleaze')?.system?.rating ?? 0) : validatedDf(this.liveDetectionFactor(), validated);
      const hostRolls: any[] = [];
      // v0.50.0: smoke in the host hampers its own detection too (RULES.TN_AUTO.matrix.smokeOnDetection).
      const detect = await successTest({ dice: host.system.securityValue, targetNumber: df, modifiers: RULES.TN_AUTO.matrix.smokeOnDetection ? SR2Actor.smokeMods(host) : [], roll: foundryRoller(hostRolls) });
      await SR2Actor.addToTally(host, detect.successes, {
        label: tx('SR2E.Card.Actor.detectsSecurityValueVsSDetection', { hostName: host.name, hostSecurityValue: host.system.securityValue, part: ownDf ? frame.name : this.name, df, part2: validated ? tx('SR2E.Card.Actor.passcodeValidated') : '' }),
        result: detect, rolls: hostRolls,
      }, this.tallyFor(frame), this.uuid as string);
    }

    const own = this.#matrixDice();
    const fd = frame ? (agent ? agentDice(frame.system.rating) : frameDice(frame.system.rating, Boolean(frame.system.smart))) : null;
    // v0.49.0: an otaku's channel for this subsystem works like a utility (or adds dice).
    // v0.71.0 (R7): a decker's utility runs no higher than the working MPCP.
    const progRating = prog ? (fd ? Number(prog.system?.rating ?? 0) : this.utilityRating(prog)) : 0;
    const ch = !fd && this.sys.derived?.matrix?.living ? channelEffect(this.otakuChannel(sub), progRating) : null;
    const dice = (fd ? fd.dice + fd.pool : own.dice) + (ch?.dice ?? 0);
    const modifiers = fd ? [] : own.modifiers;
    const suffix = (fd ? tx('SR2E.Card.Actor.rating4', { part: agent ? tx('SR2E.Card.Actor.agent') : tx('SR2E.Card.Actor.frame'), fdDice: fd.dice, part2: fd.pool ? tx('SR2E.Card.Actor.pool', { fdPool: fd.pool }) : '' }) : own.suffix) + (ch?.dice ? ` (${ch.note})` : '');
    const channelUsed = ch && ch.utility > progRating;
    const utility = channelUsed ? { name: tx('SR2E.Card.Actor.channel', { sub: cap(sub), utility: ch!.utility }), rating: ch!.utility } : prog ? { name: progRating < Number(prog.system.rating ?? 0) ? tx('SR2E.Card.Actor.runsAtMpcp', { name: prog.name, rating: prog.system.rating, progRating }) : `${prog.name} ${prog.system.rating}`, rating: progRating } : null;
    return this.#runTest(`${frame ? `${frame.name}: ` : ''}${ctx.operation ? `${ctx.operation}: ` : ''}${host.name} ${tnNote}${suffix}${legit ? tx('SR2E.Card.Actor.securityDecker2') : ''}`, dice, {
      targetNumber: tn, poolDice: fd ? 0 : opts.poolDice ?? 0, pool: 'hacking', noPenalties: Boolean(fd), ...(opts.exclude?.length ? { exclude: opts.exclude } : {}),
      // A frame runs inside the host: the decker's own connection does not slow it (smoke does).
      modifiers: [...utilityModifiers(utility), ...(opts.modifiers ?? []), ...(fd ? [...SR2Actor.smokeMods(host), ...matrixWoundModifiers(Number(frame.system.matrix?.monitor ?? 0), { ic: true })] : this.matrixTestMods(host)), ...modifiers],
    }, { kind: 'system', system: ctx });
  }

  /** What a system test's success (or failure) does; each effect is applied once, even across Karma re-rolls. */
  async #resolveSystem(snap: TestSnapshot, fu: FollowUps): Promise<Resolved> {
    const sy = snap.system!;
    const s = snap.successes;
    const name = sy.operation || tx('SR2E.Card.Actor.theOperation');
    const host: any = sy.hostUuid ? fromUuidSync(sy.hostUuid) : null;
    const next: SystemContext = { ...sy };
    const files: DataFile[] = [...(host?.system?.files ?? [])];
    const file = sy.fileId ? files.find((f) => f.id === sy.fileId) : undefined;
    if (s <= 0) {
      let extra = '';
      // A failed decryption of a file guarded by scramble IC destroys it.
      if (sy.effect === 'decryptFile' && file?.scramble && !sy.failApplied && !sy.applied && host) {
        fu.hostChange = { host, change: { removeFile: file.id }, label: tx('SR2E.Card.Actor.scrambleIcDestroys2', { name: file.name }) };
        next.failApplied = true;
        extra = ` <strong>${tx('SR2E.Card.Actor.scrambleIcDestroys', { fileName: escText(file.name) })}</strong>`;
      }
      return { html: `<p><strong>${tx('SR2E.Card.Actor.fails', { name: escText(name) })}</strong>${extra}</p>`, flags: {}, snap: { ...snap, system: next } };
    }
    const head = `<p><strong>${tx('SR2E.Card.Actor.succeeds', { name: escText(name) })}</strong> (${escText(sy.subsystem)}, ${escText(plural(s, 'success'))}).</p>`;
    // Who did it, for the GM's notes: the frame that ran it, or the decker.
    const by: string = sy.frameUuid ? (fromUuidSync(sy.frameUuid)?.name ?? this.name) : this.name;
    if (sy.applied || sy.failApplied) return { html: `${head}<p><em>${tx('SR2E.Card.Actor.itsEffectWasAlreadyAppliedAdjust', { part: sy.failApplied ? tx('SR2E.Card.Actor.theFailure') : '' })}</em></p>`, flags: {}, snap };
    // v0.57.0: a data bomb on the subsystem, or on the file this touches, goes off.
    const bomb = host ? this.#bombCheck(host, sy, file) : null;
    if (bomb) {
      next.bombed = true;
      if (bomb.stops) {
        fu.hostChange = { host, change: bomb.change, label: tx('SR2E.Card.Actor.aDataBombGoesOffOn', { by }) };
        next.applied = true;
        return { html: head + bomb.html, flags: bomb.flags, snap: { ...snap, system: next } };
      }
    }
    let body = '';
    let fileGone = false;
    switch (sy.effect) {
      case 'analyzeHost': {
        // v0.73.0 (O24): its code and Security Value are known now.
        if (host) await this.learnHostKnowledge(host.uuid, 'analyzed');
        const subs = RULES.MATRIX.subsystems.map((k) => `${cap(k)} ${host?.system?.subsystems?.[k] ?? '?'}`).join(', ');
        // v0.57.0: and its subsystems' data bombs.
        const bombs = [...(host?.system?.bombs ?? [])].filter((b: any) => b.rating > 0);
        if (bombs.length && host) fu.hostChange = { host, change: { bombFound: { deckerUuid: this.uuid as string, subsystem: '*' } }, label: tx('SR2E.Card.Actor.spotsDataBombsIn', { by, hostName: host.name }) };
        body = host ? `<p>${escText(host.name)}: <strong>${escText(cap(host.system.securityCode))}-${escText(host.system.securityValue)}</strong>. ${escText(subs)}.${bombs.length ? ` <strong>${tx('SR2E.Card.Actor.dataBombs')}</strong> ${bombs.map((b: any) => `${escText(cap(b.subsystem))} ${escText(b.rating)}${b.pavlov ? tx('SR2E.Card.Actor.pavlov') : ''}`).join(', ')}.` : ''}</p>` : '';
        break;
      }
      case 'analyzeSecurity': {
        const nextStep = host?.system?.derived?.nextStep;
        // v0.57.0: the decker's own tally when each intruder has one.
        const own = RULES.MATRIX_V57.tally.perDecker ? deckerTallyOf(host?.system?.tallies ?? [], this.tallyFor(sy.frameUuid ? fromUuidSync(sy.frameUuid) : null).key) : null;
        body = host ? `<p>${tx('SR2E.Card.Actor.alert', { part: own != null ? `${tx('SR2E.Card.Actor.yourSecurityTally')} <strong>${own}</strong>` : `${tx('SR2E.Card.Actor.securityTally')} <strong>${escText(host.system.tally)}</strong>` })} <strong>${escText(host.system.alert)}</strong>${nextStep && own == null ? tx('SR2E.Card.Actor.theNextStepIsAt', { nextStepStep: escText(nextStep.step) }) : ''}.</p>` : '';
        break;
      }
      case 'validate':
        if (host) {
          fu.hostChange = { host, change: { validate: this.uuid as string }, label: tx('SR2E.Card.Actor.validatesAPasscodeIn', { by, hostName: host.name }) };
          body = `<p>${tx('SR2E.Card.Actor.nowHoldsA', { name: escText(this.name) })} <strong>${tx('SR2E.Card.Actor.validPasscode')}</strong> ${tx('SR2E.Card.Actor.inItsDetectionRollsAgainstThem', { hostName: escText(host.name), validateDfBonus: RULES.MATRIX_V57.utilities.validate.dfBonus })}</p>`;
        }
        break;
      case 'invalidate':
        if (host && sy.targetUuid) {
          fu.hostChange = { host, change: { invalidate: sy.targetUuid }, label: `${by} invalidates ${fromUuidSync(sy.targetUuid)?.name ?? 'a'} passcode` };
          body = `<p>${tx('SR2E.Card.Actor.sPasscodeIs', { name: escText(fromUuidSync(sy.targetUuid)?.name ?? tx('SR2E.Card.Actor.theDecker')) })} <strong>${tx('SR2E.Card.Actor.noLongerValid')}</strong>.</p>`;
        }
        break;
      case 'scanFile':
        if (file && host) {
          const f: any = file;
          if (f.bomb > 0) fu.hostChange = { host, change: { bombFound: { deckerUuid: this.uuid as string, fileId: file.id } }, label: tx('SR2E.Card.Actor.findsADataBombOn', { by, name: file.name }) };
          body = f.bomb > 0 ? `<p><strong>${tx('SR2E.Card.Actor.carriesADataBomb', { fileName: escText(file.name) })}</strong> ${tx('SR2E.Card.Actor.rating5', { bomb: escText(f.bomb), part: f.pavlov ? tx('SR2E.Card.Actor.pavlov2') : '' })}</p>` : `<p>${tx('SR2E.Card.Actor.noDataBomb', { fileName: escText(file.name) })}</p>`;
        }
        break;
      case 'defuseBomb':
        if (host) {
          fu.hostChange = { host, change: { defuse: sy.fileId ? { fileId: sy.fileId } : { subsystem: sy.bombSubsystem ?? '' } }, label: tx('SR2E.Card.Actor.defusesADataBomb', { by }) };
          body = `<p>${(file ? tx('SR2E.Card.Actor.theDataBombIsWithOn9', { fileName: escText(file.name) }) : (sy.bombSubsystem ? tx('SR2E.Card.Actor.theDataBombIsWithOnTheSubsystem', { syBombSubsystem: escText(cap(sy.bombSubsystem)) }) : tx('SR2E.Card.Actor.theDataBombIsPlain')))} <strong>${tx('SR2E.Card.Actor.defused')}</strong>.</p>`;
        }
        break;
      case 'makeCall':
        if (host) {
          const id = (foundry as any).utils?.randomID?.() ?? `c${Date.now()}`;
          fu.hostChange = { host, change: { call: { op: 'place', id, from: host.system.ltgNumber || host.name, to: sy.number ?? '', by: by } }, label: tx('SR2E.Card.Actor.placesACallTo', { by, number: sy.number }) };
          body = `<p>${tx('SR2E.Card.Actor.placesAComcallTo', { by: escText(by) })} <strong>${escText(sy.number ?? '')}</strong> ${tx('SR2E.Card.Actor.through2', { hostName: escText(host.name) })}</p>`;
        }
        break;
      case 'tapCall':
      case 'rerouteCall': {
        const call: any = (host?.system?.calls ?? []).find((c: any) => c.id === sy.callId);
        if (host && call) {
          const tap = sy.effect === 'tapCall';
          fu.hostChange = { host, change: { call: tap ? { op: 'tap', id: call.id, who: by } : { op: 'reroute', id: call.id, to: sy.number ?? '' } }, label: `${by} ${tap ? 'taps' : 'reroutes'} a call` };
          body = tap ? `<p>${escText(by)} <strong>${tx('SR2E.Card.Actor.listensIn')}</strong> ${tx('SR2E.Card.Actor.onTheCallFromTo', { callFrom: escText(call.from), callRerouted: escText(call.rerouted || call.to) })}</p>` : `<p>${tx('SR2E.Card.Actor.theCallFromNowGoesTo', { callFrom: escText(call.from) })} <strong>${escText(sy.number ?? '')}</strong>.</p>`;
        }
        break;
      }
      case 'analyzeIc': {
        const ic: any = sy.targetUuid ? fromUuidSync(sy.targetUuid) : null;
        if (ic?.system) {
          const b = ic.system.behavior as IcBehavior;
          body = `<p>${escText(ic.name)}: <strong>${escText(ic.system.icType || IC_BEHAVIOR_LABELS[b] || tx('SR2E.Card.Actor.ic2'))}</strong> ${tx('SR2E.Card.Actor.rating6', { icBehaviorLabels: escText(IC_BEHAVIOR_LABELS[b] ?? b), icCategory: escText(ic.system.category) })} <strong>${escText(ic.system.rating)}</strong>${ic.system.guards ? tx('SR2E.Card.Actor.guards2', { icGuards: escText(cap(ic.system.guards)) }) : ''}${b === 'trace' ? tx('SR2E.Card.Actor.traceAnd', { icTraceMode: escText(ic.system.traceMode) }) : ''}.</p>`;
        }
        break;
      }
      case 'redirectTrace': {
        const t = this.sys.matrix?.trace;
        if (t?.active) {
          await this.update({ 'system.matrix.trace': { ...t, active: false } });
          body = `<p>${tx('SR2E.Card.Actor.shakesOffSTraceItMust', { name: escText(this.name), icName: escText(t.icName) })}</p>`;
        } else body = `<p>${tx('SR2E.Card.Actor.noTraceToShakeOff')}</p>`;
        break;
      }
      case 'crashHost':
        if (host) {
          fu.hostChange = { host, change: { minAlert: 'shutdown' }, label: `${by} crashes ${host.name}` };
          body = `<p><strong>${tx('SR2E.Card.Actor.crashes', { hostName: escText(host.name) })}</strong> ${tx('SR2E.Card.Actor.shutdown')}</p>`;
        }
        break;
      case 'decryptGuard': {
        const ic: any = sy.targetUuid ? fromUuidSync(sy.targetUuid) : null;
        await this.update({ 'system.matrix.passed': [...new Set([...(this.sys.matrix?.passed ?? []), sy.targetUuid])] });
        body = `<p>${tx('SR2E.Card.Actor.isDecryptedCanUseTheSubsystem', { icName: escText(ic?.name ?? tx('SR2E.Card.Actor.theBarrier')), name: escText(this.name), sySubsystem: escText(sy.subsystem) })}</p>`;
        break;
      }
      case 'logoff': {
        // v0.73.0 (O22): a hold that started since the roll keeps the decker in.
        const lh = logoffHoldCheck({ hold: sy.frameUuid ? null : this.blackIcHold(), deckerName: this.name, frame: Boolean(sy.frameUuid), isGM: Boolean(Boolean((game as any).user?.isGM)) } as any);
        if (lh.block) { body = `<p>${escText(lh.note)}</p>`; break; }
        // To the parent grid (or out onto the grid when there is none).
        const parentUuid = (host?.system?.parentUuid as string | undefined) ?? '';
        const parent: any = parentUuid ? fromUuidSync(parentUuid) : null;
        const who: any = sy.frameUuid ? fromUuidSync(sy.frameUuid) : this;
        if (sy.frameUuid) await who?.update({ 'system.hostUuid': parentUuid });
        else await this.update({ 'system.matrix.hostUuid': parentUuid, 'system.matrix.passed': [] });
        body = `<p>${tx('SR2E.Card.Actor.logsOffTo', { whoName: escText(who?.name ?? this.name), hostName: escText(host?.name ?? tx('SR2E.Card.Actor.theHost')), name: escText(parent?.name ?? tx('SR2E.Card.Actor.theGrid')) })}</p>`;
        break;
      }
      case 'logon': {
        const who: any = sy.frameUuid ? fromUuidSync(sy.frameUuid) : this;
        // Grid travel (v0.40.0): hops between grids on the way take Combat Turns.
        const node = (h: any): GridNode => ({ uuid: h.uuid, gridKind: h.system?.gridKind ?? 'host', parentUuid: h.system?.parentUuid ?? '' });
        const all: GridNode[] = allActors().filter((a: any) => a.type === 'host').map(node);
        const from: any = sy.fromUuid ? fromUuidSync(sy.fromUuid) : null;
        const hops = host ? gridHops(from ? node(from) : null, node(host), all) : 0;
        const turns = travelTurns(hops);
        let travel = '';
        if (sy.frameUuid) await who?.update({ 'system.hostUuid': sy.targetUuid ?? '' });
        else {
          const now = SR2Actor.matrixNow();
          const transit = turns > 0
            ? { hostUuid: sy.targetUuid ?? '', hops, round: now.round != null ? now.round + turns : -1, worldTime: now.worldTime + turns * RULES.MATRIX.travel.secondsPerTurn }
            : { hostUuid: '', hops: 0, round: -1, worldTime: -1 };
          await this.update({ 'system.matrix.hostUuid': sy.targetUuid ?? '', 'system.matrix.passed': [], 'system.matrix.transit': transit });
          if (turns > 0) travel = ` ${tCount(hops, 'SR2E.Card.Actor.hopsAcrossTheGridArrivesIn')} <strong>${tCount(turns, 'SR2E.Card.Actor.combatTurns')}</strong>${transit.round >= 0 ? tx('SR2E.Card.Actor.combatTurn2', { transitRound: transit.round }) : ` (${turns * RULES.MATRIX.travel.secondsPerTurn} s)`}.`;
        }
        // Dialling a number logs on from anywhere, and the decker remembers it (v0.46.0).
        if (!sy.frameUuid && host?.system?.ltgNumber) await this.update({ 'system.matrix.numbers': learnNumbers(this.sys.matrix?.numbers ?? [], [host.system.ltgNumber]) });
        body = `<p>${(sy.dialled ? tx('SR2E.Card.Actor.logsOnToWithDialsAnd', { whoName: escText(who?.name ?? this.name), hostLtgNumber: escText(host?.system?.ltgNumber) }) : tx('SR2E.Card.Actor.logsOnToPlain', { whoName: escText(who?.name ?? this.name) }))} <strong>${escText(host?.name ?? tx('SR2E.Card.Actor.theHost'))}</strong>.${travel}</p>`;
        // v0.73.0 (O24): the host it logs on to is known now.
        if (sy.targetUuid) await this.learnHostKnowledge(sy.targetUuid, hostEntryKnowledge());
        // v0.57.0: a reality filter meets the new host's sculpting.
        if (!sy.frameUuid && host) await this.realityFilterCheck(host);
        break;
      }
      case 'locateNumber': {
        // This node's number and those of the nodes connected to it.
        const nodes: any[] = host ? [host, ...allActors().filter((a: any) => a.type === 'host' && (a.system?.parentUuid === host.uuid || a.uuid === host.system?.parentUuid))] : [];
        const found = nodes.filter((n: any) => n.system?.ltgNumber).map((n: any) => ({ name: n.name as string, number: n.system.ltgNumber as string }));
        if (found.length) await this.update({ 'system.matrix.numbers': learnNumbers(this.sys.matrix?.numbers ?? [], found.map((f) => f.number)) });
        // v0.73.0 (O24): the nodes it finds are located.
        if (Array.isArray(this.sys.matrix?.knownHosts) && nodes.length) await this.update({ 'system.matrix.knownHosts': nodes.reduce((k: any[], n: any) => learnHost(k, n.uuid, 'located'), this.sys.matrix?.knownHosts ?? []) });
        body = found.length ? `<p>${tx('SR2E.Card.Actor.numbers', { found: found.map((f) => `${escText(f.name)} <strong>${escText(f.number)}</strong>`).join('; ') })}</p>` : `<p>${tx('SR2E.Card.Actor.noLtgNumbersHere')}</p>`;
        break;
      }
      case 'upload': {
        const u = sy.upload;
        if (u && host) {
          const turns = downloadTurns(u.size, u.ioSpeed);
          fu.hostChange = { host, change: { addFile: { ...u, uploadedBy: by, foundBy: [this.uuid as string] } }, label: tx('SR2E.Card.Actor.uploadsTo', { by, name: u.name, hostName: host.name }) };
          body = `<p>${tx('SR2E.Card.Actor.uploading')} <strong>${escText(u.name)}</strong> ${tx('SR2E.Card.Actor.mpTakes', { size: Number(u.size) || 0 })} <strong>${tCount(turns, 'SR2E.Card.Actor.combatTurns')}</strong> ${tx('SR2E.Card.Actor.atIO', { ioSpeed: u.ioSpeed })}</p>`;
        }
        break;
      }
      case 'locateFile':
      case 'locatePaydata': {
        const ids = host ? locateFiles(files, this.uuid as string, s, sy.effect === 'locatePaydata') : [];
        const names = files.filter((f) => ids.includes(f.id));
        if (ids.length && host) fu.hostChange = { host, change: { found: { deckerUuid: this.uuid as string, ids } }, label: `${by} locates ${names.map((f) => f.name).join(', ')}` };
        body = names.length
          ? `<p>${tx('SR2E.Card.Actor.found2', { names: names.map((f) => `<strong>${escText(f.name)}</strong> ${tx('SR2E.Card.Actor.mp', { size: f.size, part: f.paydata ? tx('SR2E.Card.Actor.paydata', { value: f.value }) : '', part2: f.scramble ? tx('SR2E.Card.Actor.scrambleIc2') : f.encrypted ? tx('SR2E.Card.Actor.encrypted') : '' })}`).join('; ') })}</p>`
          : `<p>${tx('SR2E.Card.Actor.nothingNewFound')}</p>`;
        break;
      }
      case 'locateSlave': {
        const devs = SR2Actor.slaveDevices(host);
        body = devs.length ? `<p>${tx('SR2E.Card.Actor.slaves', { devs: devs.map((x) => `${escText(x.device.name)} (${escText(x.site.name)}, ${escText(x.device.kind)} ${escText(x.device.rating)})`).join('; ') })}</p>` : `<p>${tx('SR2E.Card.Actor.noSlavedDevicesFound')}</p>`;
        break;
      }
      case 'download': {
        const deck: any = this.activeDeck();
        // v0.81.1 (D2-10): the file was erased between the roll and this re-resolution: nothing to take.
        if (!file) { body = `<p><em>${tx('SR2E.Card.Actor.theFileIsGone')}</em></p>`; fileGone = true; break; }
        if (file && deck) {
          const list = [...(deck.system.files ?? []), { name: file.name, size: file.size, value: file.value, paydata: file.paydata, source: host?.name ?? '' }];
          await deck.update({ 'system.files': list });
          const used = list.reduce((t: number, f: any) => t + (f.size ?? 0), 0);
          const turns = downloadTurns(file.size, deck.system.ioSpeed ?? 0);
          body = `<p>${tx('SR2E.Card.Actor.downloading')} <strong>${escText(file.name)}</strong> ${tx('SR2E.Card.Actor.mpTakes2', { fileSize: file.size })} <strong>${tCount(turns, 'SR2E.Card.Actor.combatTurns')}</strong> ${tx('SR2E.Card.Actor.atIOStorageMp', { deckIoSpeed: escText(deck.system.ioSpeed), used: escText(used), deckStorageMemory: escText(deck.system.storageMemory), part: used > deck.system.storageMemory ? ` <strong class="sr2e-warn">${tx('SR2E.Card.Actor.over')}</strong>` : '' })}</p>`;
        }
        break;
      }
      case 'editFile':
        // v0.46.0: alter the file (a note of what changed), or erase it.
        if (!file) { body = `<p><em>${tx('SR2E.Card.Actor.theFileIsGone')}</em></p>`; fileGone = true; break; }
        if (file && host) {
          if (sy.editMode === 'erase') {
            fu.hostChange = { host, change: { removeFile: file.id }, label: `${by} erases ${file.name}` };
            body = `<p><strong>${tx('SR2E.Card.Actor.isErased', { fileName: escText(file.name) })}</strong></p>`;
          } else {
            const note = `${by}: ${sy.editNote || 'altered'}`;
            fu.hostChange = { host, change: { editFile: { id: file.id, note } }, label: `${by} edits ${file.name}` };
            body = `<p><strong>${tx('SR2E.Card.Actor.isEdited', { fileName: escText(file.name) })}</strong>${sy.editNote ? `: ${escText(sy.editNote)}` : ''}.</p>`;
          }
        }
        break;
      case 'decryptFile':
        if (!file) { body = `<p><em>${tx('SR2E.Card.Actor.theFileIsGone')}</em></p>`; fileGone = true; break; }
        if (file && host) {
          fu.hostChange = { host, change: { decrypt: file.id }, label: `${by} decrypts ${file.name}` };
          body = `<p><strong>${escText(file.name)}</strong> ${tx('SR2E.Card.Actor.isDecrypted')}</p>`;
        }
        break;
      case 'controlSlave': {
        const site: any = sy.siteUuid ? fromUuidSync(sy.siteUuid) : null;
        const d = site?.device?.(sy.deviceId);
        if (site && d) {
          fu.siteChange = { site, change: { deviceId: d.id, bypassed: true }, label: `${by} takes over ${d.name} through ${host?.name ?? 'the host'}` };
          body = `<p>${tx('SR2E.Card.Actor.controls', { name: escText(this.name) })} <strong>${escText(d.name)}</strong> ${tx('SR2E.Card.Actor.itIsBypassed', { siteName: escText(site.name) })}</p>`;
        }
        break;
      }
      case 'monitorSlave': {
        const site: any = sy.siteUuid ? fromUuidSync(sy.siteUuid) : null;
        const d = site?.device?.(sy.deviceId);
        if (d) body = `<p>${escText(d.name)} (${escText(site.name)}): ${escText(d.kind)} ${escText(d.rating)}, ${d.active ? tx('SR2E.Card.Actor.on5') : tx('SR2E.Card.Actor.off')}${d.bypassed ? tx('SR2E.Card.Actor.bypassed') : ''}.</p>`;
        break;
      }
      // Security deckers (v0.40.0).
      case 'spotIntruder': {
        const t: any = sy.targetUuid ? fromUuidSync(sy.targetUuid) : null;
        const alert = RULES.MATRIX.security.spotAlert;
        if (host) fu.hostChange = { host, change: { spot: sy.targetUuid, ...(alert !== 'none' ? { minAlert: alert } : {}) }, label: `${this.name} spots ${t?.name ?? 'an intruder'}` };
        body = `<p>${tx('SR2E.Card.Actor.spots', { name: escText(this.name) })} <strong>${escText(t?.name ?? tx('SR2E.Card.Actor.theIntruder'))}</strong> ${tx('SR2E.Card.Actor.in3', { hostName: escText(host?.name ?? tx('SR2E.Card.Actor.theHost')) })}</p>`;
        break;
      }
      case 'traceIntruder': {
        const t: any = sy.targetUuid ? fromUuidSync(sy.targetUuid) : null;
        const turns = traceTurns(s) ?? RULES.MATRIX.trace.baseTurns;
        const now = SR2Actor.matrixNow();
        const due = traceDue({ round: now.round, worldTime: now.worldTime, turns, combatId: now.combatId });
        const mode = RULES.MATRIX.security.traceMode;
        try {
          const cur = t?.system?.matrix?.trace ?? {};
          await t?.update({ 'system.matrix.trace': { ...cur, active: true, icUuid: this.uuid, icName: this.name, mode, rating: this.findSkill(RULES.MATRIX.skill)?.system?.rating ?? 0, hostUuid: host?.uuid ?? '', round: due.round, worldTime: due.worldTime, combatId: due.combatId ?? '' } });
          body = `<p><strong>${tx('SR2E.Card.Actor.locksATraceOn', { name: escText(this.name), name2: escText(t?.name ?? tx('SR2E.Card.Actor.theIntruder')) })}</strong>${tx('SR2E.Card.Actor.itCompletesIn')} <strong>${tCount(turns, 'SR2E.Card.Actor.combatTurns')}</strong>${tx('SR2E.Card.Actor.then', { part: now.round != null ? tx('SR2E.Card.Actor.combatTurn3', { dueRound: due.round }) : '', part2: mode === 'report' ? tx('SR2E.Card.Actor.reportsTheirLocation') : mode === 'burn' ? tx('SR2E.Card.Actor.dumpsThemAndBurnsTheDeck') : tx('SR2E.Card.Actor.dumpsThem') })}</p>`;
        } catch {
          body = `<p>${tx('SR2E.Card.Actor.locksATraceOnCombatTurns', { name: escText(this.name), name2: escText(t?.name ?? tx('SR2E.Card.Actor.theIntruder')), turns })} <em>${tx('SR2E.Card.Actor.gmSetItOnTheirSheet')}</em></p>`;
        }
        break;
      }
      case 'rearmDevice': {
        const site: any = sy.siteUuid ? fromUuidSync(sy.siteUuid) : null;
        const d = site?.device?.(sy.deviceId);
        if (site && d) {
          fu.siteChange = { site, change: { deviceId: d.id, bypassed: false }, label: `${this.name} re-arms ${d.name} through ${host?.name ?? 'the host'}` };
          body = `<p>${tx('SR2E.Card.Actor.reArms', { name: escText(this.name) })} <strong>${escText(d.name)}</strong> (${escText(site.name)}).</p>`;
        }
        break;
      }
      case 'cancelAlert':
        if (host) {
          fu.hostChange = { host, change: { setAlert: 'none', ...(RULES.MATRIX.security.cancelResetsTally ? { resetTally: true } : {}) }, label: `${this.name} cancels ${host.name}'s alert` };
          body = `<p>${tx('SR2E.Card.Actor.cancelsTheAlertIn', { name: escText(this.name) })} <strong>${escText(host.name)}</strong>.</p>`;
        }
        break;
      default:
        break;
    }
    // v0.57.0: a Pavlov or subsystem bomb goes off on top of what the operation did.
    if (bomb && host) {
      const prior = (fu.hostChange ?? null);
      const change: HostChange = { ...bomb.change, ...(prior?.change ?? {}) };
      const order = RULES.MATRIX.alerts as readonly string[];
      if (prior?.change?.minAlert && bomb.change.minAlert) change.minAlert = order.indexOf(prior.change.minAlert) >= order.indexOf(bomb.change.minAlert) ? prior.change.minAlert : bomb.change.minAlert;
      fu.hostChange = { host, change, label: prior ? tx('SR2E.Card.Actor.aDataBombGoesOffAfter', { label: prior.label }) : tx('SR2E.Card.Actor.aDataBombGoesOffOn', { by }) };
      body += bomb.html;
    }
    next.applied = (Boolean(sy.effect && sy.effect !== 'none') && !fileGone) || Boolean(bomb);
    return { html: head + body, flags: bomb?.flags ?? {}, snap: { ...snap, system: next } };
  }

  /**
   * v0.57.0: a data bomb this successful operation sets off: on the file it touches (download, edit,
   * decrypt) or on the subsystem it works on. The persona (or frame) that ran it gets a Resist button;
   * a bomb that isn't Pavlov is used up and, on a file, erases it (`stops`: the operation does nothing).
   */
  #bombCheck(host: any, sy: SystemContext, file: DataFile | undefined): { html: string; flags: Record<string, unknown>; change: HostChange; stops: boolean } | null {
    if (sy.effect === 'defuseBomb' || sy.effect === 'scanFile') return null;
    const f: any = file;
    const sub = String(sy.subsystem ?? '').toLowerCase();
    const sb: any = (host.system.bombs ?? []).find((b: any) => b.subsystem === sub && b.rating > 0);
    const onFile = f && touchesFile(sy.effect ?? '') && Number(f.bomb ?? 0) > 0;
    if (!onFile && !sb) return null;
    const rating = onFile ? Number(f.bomb) : Number(sb.rating);
    const pavlov = onFile ? Boolean(f.pavlov) : Boolean(sb.pavlov);
    const b = bombBlast(rating, pavlov);
    const victim: string = sy.frameUuid || (this.uuid as string);
    const damage: DamageState = { targetUuid: victim, melee: false, damageType: 'physical', power: b.power, level: b.level, matrix: true };
    const change: HostChange = {
      bombOff: onFile ? { fileId: f.id, erase: b.erases } : { subsystem: sub, erase: b.erases },
      ...(b.alert && b.alert !== 'none' ? { minAlert: b.alert } : {}),
    };
    const where = onFile ? f.name : tx('SR2E.Card.Actor.theSubsystem', { sub: cap(sub) });
    const html = `<p><strong>${tx('SR2E.Card.Actor.aDataBombGoesOff')}</strong> ${tx('SR2E.Card.Actor.on6', { where: escText(where) })} <strong>${b.power}${b.level}</strong> ${tx('SR2E.Card.Actor.matrixDamage2', { part: b.erases ? (onFile ? tx('SR2E.Card.Actor.andIsErased', { name: escText(f.name) }) : '') : tx('SR2E.Card.Actor.pavlovItReArms') })}</p>
      <p><button type="button" data-sr2e-action="resist" data-index="0">${tx('SR2E.Card.Actor.resist2', { name: escText(fromUuidSync(victim)?.name ?? this.name) })}</button></p>`;
    return { html, flags: { damage, damages: [damage] }, change, stops: Boolean(onFile && b.erases) };
  }

  /**
   * Add host successes to its security tally. The GM applies it at once (with a card listing any
   * sheaf steps reached); a player's client posts a card for the GM to apply.
   */
  static async addToTally(host: any, successes: number, roll: { label: string; result: SuccessTestResult; rolls: any[] }, who: { key: string; name: string } | null = null, sourceUuid = ''): Promise<void> {
    const gms = [...(game.users ?? [])].filter((u: any) => u.isGM).map((u: any) => u.id);
    const canApply = Boolean(canWriteNow(host));
    let body = '';
    let flags: Record<string, unknown> = {};
    const whose = who && RULES.MATRIX_V57.tally.perDecker ? `${escText(who.name)}'s` : tx('SR2E.Card.Actor.the');
    if (successes <= 0) body = `<p>${tx('SR2E.Card.Actor.noChangeToSecurityTally', { whose })}</p>`;
    else if (canApply) body = await SR2Actor.#applyTally(host, successes, who);
    else {
      body = `<p>${tx('SR2E.Card.Actor.toSecurityTally', { successes, whose })} <button type="button" data-sr2e-action="applyTally">${tx('SR2E.Card.Actor.applyGm')}</button></p>`;
      // v0.81.0: `sourceUuid` (who rolled) binds the card to its author (rules/trust.ts).
      flags = { [SYSTEM_ID]: { tally: { hostUuid: host.uuid, successes, ...(who ? { key: who.key, name: who.name } : {}), ...(sourceUuid ? { sourceUuid } : {}) } } };
    }
    await ChatMessage.create({
      speaker: { alias: host.name },
      content: `<p><em>${tx('SR2E.Card.Actor.gmOnly')}</em></p>${describeResult(roll.label, roll.result)}${body}`,
      rolls: roll.rolls,
      whisper: gms,
      blind: true,
      flags,
    });
  }

  /** Raise a host's alert (only up), and the alert of sites linked to it. */
  static async #raiseHostAlert(host: any, alert: AlertLevel): Promise<void> {
    const was = String(host.system.alert ?? 'none');
    await host.update({ 'system.alert': alert });
    for (const site of allActors().filter((a: any) => a.type === 'site' && a.system.hostUuid === host.uuid)) {
      const want = siteAlertForHost(alert);
      if (!alertAtLeast(site.system.alert, want)) await SR2Actor.applySiteChange(site.uuid, { minAlert: want });
    }
    // v0.57.0: a host that reaches shutdown dumps everyone inside.
    if (alert === 'shutdown' && was !== 'shutdown') await SR2Actor.startShutdown(host);
  }

  /** v0.70.0 (GM): add new actors (launched IC) to the running combat that holds `nearUuid` (else the viewed one). */
  static async #joinCombat(actors: any[], nearUuid: string | null): Promise<number> {
    if (!actors.length || !isGmNow()) return 0;
    const running = [...((game as any).combats ?? [])].filter((c: any) => c.started);
    const combat: any = running.find((c: any) => nearUuid && [...(c.combatants ?? [])].some((x: any) => x.actor?.uuid === nearUuid)) ?? ((game as any).combat?.started ? (game as any).combat : null);
    if (!combat) return 0;
    try {
      await combat.createEmbeddedDocuments('Combatant', actors.map((a: any) => ({ actorId: a.id, hidden: true })));
      return actors.length;
    } catch (err) { console.warn('sr2e | IC joining the combat', err); return 0; }
  }

  /** Raise a host's tally (v0.57.0: the intruder's own tally) and alert; returns a note of what happened. */
  static async #applyTally(host: any, successes: number, who: { key: string; name: string } | null = null): Promise<string> {
    const sheaf = (host.system.sheaf ?? []) as SheafStep[];
    let before: number, tally: number, triggered: SheafStep[];
    let whoName = '';
    if (RULES.MATRIX_V57.tally.perDecker && who?.key) {
      const r = advanceDeckerTally((host.system.tallies ?? []) as DeckerTally[], who.key, who.name, successes, sheaf);
      ({ before, after: tally, triggered } = r);
      whoName = escText(who.name);
      // The host's own tally shows the highest intruder's.
      await host.update({ 'system.tallies': r.tallies, 'system.tally': r.highest });
    } else {
      before = host.system.tally as number;
      ({ tally, triggered } = advanceTally(before, successes, sheaf));
      await host.update({ 'system.tally': tally });
    }
    const was = String(host.system.alert ?? 'none');
    const alert = raiseAlert(host.system.alert as AlertLevel, triggered);
    // Sites linked to this host raise their alert with it.
    await SR2Actor.#raiseHostAlert(host, alert);
    // v0.61.0: steps that launch IC do so, once each until the tally is reset (SECURITY_V61.sheafIc).
    const launched: string[] = [];
    // v0.70.0: with per-decker tallies each intruder's steps launch their own IC (before, the host remembered a
    // step for everyone, so a second decker reaching it launched nothing). Kept as "<key>|<step>" in a host flag.
    const perDecker = Boolean(RULES.MATRIX_V57.tally.perDecker && who?.key);
    const mineDone: string[] = perDecker ? [...((host.getFlag?.(SYSTEM_ID, 'sheafLaunched') as string[] | undefined) ?? [])] : [];
    const already = perDecker
      ? mineDone.filter((k) => k.startsWith(`${who!.key}|`)).map((k) => Number(k.slice(k.lastIndexOf('|') + 1)))
      : [...(host.system.launchedSteps ?? [])].map(Number);
    const toLaunch = stepsToLaunch(triggered, already);
    const made: any[] = [];
    if (toLaunch.length) {
      const canCreate = canCreateActorNow();
      const done: number[] = [];
      for (const n of toLaunch) {
        const st = triggered.find((t) => t.step === n);
        const ic = st ? icFromStep(st as any, { securityValue: Number(host.system.securityValue ?? 0), name: String(host.name) }) : null;
        if (!ic) continue;
        if (!canCreate) { launched.push(tx('SR2E.Card.Actor.theGmLaunchesIt', { name: escText(ic.name), copies: ic.copies })); continue; }
        try {
          for (let k = 0; k < ic.copies; k++) made.push(await SR2Actor.launchIc(host, { ...ic, name: ic.copies > 1 ? `${ic.name} #${k + 1}` : ic.name }));
        } catch (err) { console.warn('sr2e | launch IC', err); launched.push(tx('SR2E.Card.Actor.couldnTBeCreatedLaunchIt', { name: escText(ic.name) })); continue; }
        launched.push(`${escText(ic.name)}${ic.copies > 1 ? ` ×${ic.copies}` : ''}`);
        done.push(n);
      }
      if (done.length) {
        if (perDecker) await host.setFlag(SYSTEM_ID, 'sheafLaunched', [...mineDone, ...done.map((n) => `${who!.key}|${n}`)].slice(-200));
        else await host.update({ 'system.launchedSteps': [...(host.system.launchedSteps ?? []), ...done] });
      }
      // v0.70.0: IC launched while a combat runs joins it (hidden from players until the GM shows it); it rolls
      // initiative with everyone at the next Combat Turn.
      const joined = await SR2Actor.#joinCombat(made.filter(Boolean), who?.key ?? null);
      if (joined) launched.push(tx('SR2E.Card.Actor.addedToTheCombatHidden', { joined }));
    }
    const events = triggered.map((t) => `<li>${tx('SR2E.Card.Actor.stepN', { step: t.step })} <strong>${t.event ? escText(t.event) : tx('SR2E.Card.Actor.noEvent')}</strong>${t.alert ? tx('SR2E.Card.Actor.alertParen', { alert: t.alert }) : ''}</li>`).join('');
    // v0.81.0 (D3-18): compared with the alert before #raiseHostAlert wrote the new one (after it, they were always equal).
    return `${launched.length ? `<p>${tx('SR2E.Card.Actor.icLaunched', { launched: launched.join(', ') })}</p>` : ''}<p>${whoName ? tx('SR2E.Card.Actor.sSecurityTallyArrow', { name: whoName, before }) : tx('SR2E.Card.Actor.securityTallyArrow', { before })} <strong>${tally}</strong>${alert !== was || triggered.some((t) => t.alert) ? ` ${tx('SR2E.Card.Actor.alertLabel')} <strong>${alert}</strong>` : ''}.</p>${events ? `<ul>${events}</ul>` : ''}`;
  }

  /**
   * v0.61.0: a gas device releases its toxin: everyone inside the regions watched by it (Region config "Watched by"),
   * and within its radius of its linked token, resists it (masks and filters count); a smoke cloud may show it.
   */
  static async #releaseGas(site: any, d: any): Promise<string> {
    const tox = gasDeviceToxin(d);
    const radius = gasDeviceRadius(d);
    const scene: any = (game as any).scenes?.get?.(d.sceneId) ?? (canvas as any)?.scene;
    const caught = new Map<string, any>();
    const onCanvas = scene && (canvas as any)?.scene?.id === scene.id;
    if (onCanvas) {
      for (const r of [...(scene.regions ?? [])] as any[]) {
        const env = r.flags?.[SYSTEM_ID]?.env;
        if (env?.siteUuid !== site.uuid || env?.deviceId !== d.id) continue;
        for (const tk of tokensInRegion(r)) if (tk.actor && ['character', 'npc', 'spirit'].includes(tk.actor.type)) caught.set(tk.actor.uuid, tk.actor);
      }
    }
    const devTok: any = d.tokenUuid ? fromUuidSync(d.tokenUuid) : null;
    const point = devTok ? { x: Number(devTok.x ?? 0) + (Number(devTok.width ?? 1) * Number(scene?.grid?.size ?? 100)) / 2, y: Number(devTok.y ?? 0) + (Number(devTok.height ?? 1) * Number(scene?.grid?.size ?? 100)) / 2 } : null;
    if (onCanvas && point && radius > 0) for (const c of tokensNear(point, radius, { vehicles: false })) if (c.token?.actor && ['character', 'npc', 'spirit'].includes(c.token.actor.type)) caught.set(c.token.actor.uuid, c.token.actor);
    if (point && radius > 0 && RULES.SECURITY_V61.gas.cloud === 'smoke') await drawArea(point, radius, `${d.name || 'Gas'}: gas cloud`, 60, scene?.id, { turns: RULES.COMBAT_V61.smoke.lingerTurns, smoke: 'smoke' });
    const hit: ToxinHit = { name: tox.name, vector: tox.vector, power: tox.power, level: tox.level as DamageLevel, damageType: tox.damageType as DamageType, kind: 'toxin', from: site.name, needsWound: false, speed: tox.speed };
    if (caught.size) await site.exposeToxinState(hit, [...caught.keys()], `${site.name}: ${d.name || 'gas'}`);
    return caught.size ? tx('SR2E.Text.Actor.releasesCaught', { name: d.name || tx('SR2E.Text.Actor.aGasDevice'), toxName: tox.name, caught: caught.size }) : onCanvas ? tx('SR2E.Text.Actor.releasesNoOneInside', { name: d.name || tx('SR2E.Text.Actor.aGasDevice'), toxName: tox.name }) : tx('SR2E.Text.Actor.releasesNotOnTheViewedScene', { name: d.name || tx('SR2E.Text.Actor.aGasDevice'), toxName: tox.name });
  }

  /** GM: apply a tally card a player's client posted. */
  static async applyTallyCard(hostUuid: string, successes: number, who: { key: string; name: string } | null = null, sourceUuid = ''): Promise<string | null> {
    const host: any = await fromUuid(hostUuid);
    if (!host) return null;
    // v0.81.1 (D3-7): whose tally is the actor `key` names (its name read here, never the card's), and, when the card
    // names its source, it must be that source's own tally (it, or a frame or agent it runs).
    let w: { key: string; name: string } | null = null;
    if (who?.key) {
      const k: any = fromUuidSync(String(who.key));
      if (!k || !isActorDoc(k)) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.thatTallyCardNamesNoDecker')); return null; }
      if (sourceUuid) {
        const src: any = fromUuidSync(String(sourceUuid));
        const keys = new Set<string>(src?.tallyFor ? [src.tallyFor().key, ...((src.frames?.() as any[] | undefined) ?? []).map((f: any) => src.tallyFor(f).key)] : []);
        // Round 2 (V-DOC 11): IC's probe and scout cards name the decker they engage; IC is no player's (the GM runs it).
        // Round 3 (V2 #15): IC only (any GM NPC was let through before).
        const ic = src && src.type === 'ic';
        if (!ic && !keys.has(String(who.key))) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.thatCardPutsSuccessesOnS', { name: escText(k.name) })); return null; }
      }
      w = { key: String(who.key), name: String(k.name ?? '') };
    }
    return SR2Actor.#applyTally(host, safeInt(successes, 0, 30, 0), w);
  }

  /** v0.57.0: whose tally a detection roll on this decker's behalf goes on (a frame's owner, an agent itself or its owner). */
  tallyFor(frame: any = null): { key: string; name: string } {
    const key = tallyKeyFor({ deckerUuid: this.uuid as string, frame: frame && ['frame', 'agent'].includes(frame.system?.kind) ? { uuid: frame.uuid, kind: frame.system.kind, ownerUuid: frame.system.ownerUuid ?? '' } : null });
    return { key, name: key === this.uuid ? (this.name as string) : (fromUuidSync(key)?.name ?? frame?.name ?? this.name) };
  }

  /** Apply a change to a host's data stores or alert (owner/GM). Returns an HTML note. */
  /**
   * v0.81.1 (D3-11, RA2-2, SEC1-7): a host change from a card, every nested value shaped and bounded: alerts from the
   * alert list, file numbers bounded, `found.ids` and `foundBy` lists of text, a call's op from its four, and smoke
   * rebuilt here from its rating (its end from the clock now, never the card's round or time).
   */
  static #cleanHostChange(c: any): HostChange {
    const str = (v: unknown, max = 200) => (typeof v === 'string' ? v.slice(0, max) : '');
    const strs = (v: unknown, n = 50) => (Array.isArray(v) ? v.filter((x) => typeof x === 'string').slice(0, n).map((x: string) => x.slice(0, 200)) : []);
    const alerts = RULES.MATRIX.alerts as readonly string[];
    const out: any = {};
    if (c?.found && typeof c.found === 'object') out.found = { ids: strs(c.found.ids, 200), deckerUuid: str(c.found.deckerUuid) };
    for (const k of ['decrypt', 'removeFile', 'spot', 'validate', 'invalidate'] as const) if (typeof c?.[k] === 'string' && c[k]) out[k] = str(c[k]);
    if (c?.addFile && typeof c.addFile === 'object') {
      const f = c.addFile;
      out.addFile = { name: str(f.name, 120) || 'File', size: safeInt(f.size, 0, 100_000, 0), value: safeInt(f.value, 0, 10_000_000, 0), paydata: Boolean(f.paydata), foundBy: strs(f.foundBy, 20), uploadedBy: str(f.uploadedBy) };
    }
    if (c?.editFile && typeof c.editFile === 'object' && typeof c.editFile.id === 'string') out.editFile = { id: str(c.editFile.id), note: str(c.editFile.note, 500) };
    if (c?.smoke && typeof c.smoke === 'object') {
      const rating = safeInt(c.smoke.rating, 0, 20, 0);
      if (rating > 0) out.smoke = smokeCloud(rating, str(c.smoke.by, 120), SR2Actor.matrixNow());
    }
    if (c?.resetTally) out.resetTally = true;
    if (alerts.includes(String(c?.setAlert ?? ''))) out.setAlert = String(c.setAlert);
    if (alerts.includes(String(c?.minAlert ?? ''))) out.minAlert = String(c.minAlert);
    const bombKey = (b: any) => (b && typeof b === 'object' ? { ...(typeof b.fileId === 'string' ? { fileId: str(b.fileId) } : {}), ...(typeof b.subsystem === 'string' ? { subsystem: str(b.subsystem, 40) } : {}) } : null);
    if (c?.bombFound) { const k = bombKey(c.bombFound); if (k) out.bombFound = { ...k, deckerUuid: str(c.bombFound.deckerUuid) }; }
    if (c?.defuse) { const k = bombKey(c.defuse); if (k) out.defuse = k; }
    if (c?.bombOff) { const k = bombKey(c.bombOff); if (k) out.bombOff = { ...k, erase: Boolean(c.bombOff.erase) }; }
    if (c?.call && typeof c.call === 'object' && ['place', 'tap', 'reroute', 'end'].includes(String(c.call.op))) {
      out.call = { op: String(c.call.op), id: str(c.call.id), ...(c.call.from != null ? { from: str(c.call.from) } : {}), ...(c.call.to != null ? { to: str(c.call.to) } : {}), ...(c.call.by != null ? { by: str(c.call.by) } : {}), ...(c.call.who != null ? { who: str(c.call.who) } : {}) };
    }
    return out as HostChange;
  }

  static async applyHostChange(hostUuid: string, cIn: HostChange): Promise<string | null> {
    const host: any = await fromUuid(hostUuid);
    if (!host || host.type !== 'host') return null;
    const c = SR2Actor.#cleanHostChange(cIn);
    let files: DataFile[] = [...(host.system.files ?? [])].map((f: any) => ({ ...f, foundBy: [...(f.foundBy ?? [])] }));
    const notes: string[] = [];
    if (c.found) {
      for (const f of files) if (c.found.ids.includes(f.id) && !f.foundBy.includes(c.found.deckerUuid)) f.foundBy.push(c.found.deckerUuid);
      notes.push(tx('SR2E.Card.Actor.located', { filter: files.filter((f) => c.found!.ids.includes(f.id)).map((f) => f.name).join(', ') }));
    }
    if (c.decrypt) {
      const f = files.find((x) => x.id === c.decrypt);
      if (f) { f.encrypted = 0; f.scramble = 0; notes.push(tx('SR2E.Card.Actor.decrypted2', { name: f.name })); }
    }
    if (c.removeFile) {
      const f = files.find((x) => x.id === c.removeFile);
      files = files.filter((x) => x.id !== c.removeFile);
      if (f) notes.push(tx('SR2E.Card.Actor.destroyed', { name: f.name }));
    }
    if (c.addFile) {
      const id = (foundry as any).utils?.randomID?.() ?? `f${Date.now()}`;
      files.push({ id, name: c.addFile.name, size: c.addFile.size, value: c.addFile.value, paydata: c.addFile.paydata, encrypted: 0, scramble: 0, foundBy: [...c.addFile.foundBy], edited: '', uploadedBy: c.addFile.uploadedBy });
      notes.push(tx('SR2E.Card.Actor.uploaded', { addFileName: c.addFile.name }));
    }
    if (c.editFile) {
      const f: any = files.find((x) => x.id === c.editFile!.id);
      if (f) { f.edited = c.editFile.note; notes.push(tx('SR2E.Card.Actor.edited', { name: f.name })); }
    }
    const extra: Record<string, unknown> = { 'system.files': files };
    if (c.smoke) {
      extra['system.smoke'] = c.smoke;
      notes.push(tx('SR2E.Card.Actor.smokeTn', { smokeTn: c.smoke.tn }));
    }
    if (c.spot && !(host.system.spotted ?? []).includes(c.spot)) {
      extra['system.spotted'] = [...(host.system.spotted ?? []), c.spot];
      notes.push(tx('SR2E.Card.Actor.spotted', { name: fromUuidSync(c.spot)?.name ?? tx('SR2E.Card.Actor.anIntruder') }));
    }
    if (c.resetTally) {
      extra['system.tally'] = 0;
      extra['system.tallies'] = [];
      // v0.61.0: steps launch their IC again after a reset (v0.70.0: each decker's too).
      extra['system.launchedSteps'] = [];
      extra[`flags.${SYSTEM_ID}.sheafLaunched`] = [];
      notes.push(tx('SR2E.Card.Actor.tallyReset'));
    }
    // v0.57.0: passcodes, data bombs and comcalls.
    if (c.validate || c.invalidate) {
      let v: string[] = [...(host.system.validated ?? [])];
      if (c.validate && !v.includes(c.validate)) { v.push(c.validate); notes.push(tx('SR2E.Card.Actor.holdsAValidPasscode', { name: fromUuidSync(c.validate)?.name ?? tx('SR2E.Card.Actor.aDecker') })); }
      if (c.invalidate) { v = v.filter((u) => u !== c.invalidate); notes.push(tx('SR2E.Card.Actor.sPasscodeIsInvalidated', { name: fromUuidSync(c.invalidate)?.name ?? tx('SR2E.Card.Actor.aDecker') })); }
      extra['system.validated'] = v;
    }
    let bombs: any[] = [...(host.system.bombs ?? [])].map((b: any) => ({ ...b, foundBy: [...(b.foundBy ?? [])] }));
    const bombEdit = (k: { fileId?: string; subsystem?: string }, fn: (b: any) => void, fileFn: (f: any) => void) => {
      if (k.fileId) { const f: any = files.find((x) => x.id === k.fileId); if (f) fileFn(f); }
      else if (k.subsystem) bombs.filter((b) => (k.subsystem === '*' || b.subsystem === k.subsystem) && b.rating > 0).forEach(fn);
    };
    if (c.bombFound) {
      const who = c.bombFound.deckerUuid;
      bombEdit(c.bombFound, (b) => { if (!b.foundBy.includes(who)) b.foundBy.push(who); }, (f) => { f.bombFoundBy = [...new Set([...(f.bombFoundBy ?? []), who])]; });
      notes.push(tx('SR2E.Card.Actor.aDataBombFound'));
    }
    if (c.defuse) {
      bombEdit(c.defuse, (b) => { b.rating = 0; }, (f) => { f.bomb = 0; f.pavlov = false; });
      notes.push(tx('SR2E.Card.Actor.aDataBombDefused'));
    }
    if (c.bombOff) {
      if (c.bombOff.fileId && c.bombOff.erase) {
        const f = files.find((x) => x.id === c.bombOff!.fileId);
        files = files.filter((x) => x.id !== c.bombOff!.fileId);
        if (f) notes.push(tx('SR2E.Card.Actor.erasedByItsDataBomb', { name: f.name }));
      } else if (c.bombOff.subsystem && c.bombOff.erase) bombEdit(c.bombOff, (b) => { b.rating = 0; }, () => {});
      notes.push(tx('SR2E.Card.Actor.aDataBombGoesOff2'));
    }
    bombs = bombs.filter((b) => b.rating > 0);
    if (c.bombFound || c.defuse || c.bombOff) { extra['system.bombs'] = bombs; extra['system.files'] = files; }
    if (c.call) {
      const calls: Comcall[] = [...(host.system.calls ?? [])].map((x: any) => ({ ...x, tappedBy: [...(x.tappedBy ?? [])] }));
      const k = c.call;
      const next = k.op === 'place' ? placeCall(calls, { id: k.id, from: k.from ?? '', to: k.to ?? '', by: k.by ?? '' })
        : k.op === 'tap' ? tapCall(calls, k.id, k.who ?? '') : k.op === 'reroute' ? rerouteCall(calls, k.id, k.to ?? '') : endCall(calls, k.id);
      extra['system.calls'] = next;
      notes.push(k.op === 'place' ? tx('SR2E.Card.Actor.aCallTo', { to: k.to }) : k.op === 'tap' ? tx('SR2E.Card.Actor.aCallTapped') : k.op === 'reroute' ? tx('SR2E.Card.Actor.aCallReroutedTo', { to: k.to }) : tx('SR2E.Card.Actor.aCallEnded'));
    }
    // v0.81.1 (D3-11): one update, the alert with the rest (a refused alert used to leave half a change behind, and a
    // second click then uploaded a second copy of the file).
    const was = String(host.system.alert ?? 'none');
    if (c.setAlert) { extra['system.alert'] = c.setAlert; notes.push(tx('SR2E.Card.Actor.alert2', { setAlert: c.setAlert })); }
    await host.update(extra);
    if (c.setAlert === 'shutdown' && was !== 'shutdown') await SR2Actor.startShutdown(host);
    if (c.minAlert) {
      const order = RULES.MATRIX.alerts as readonly string[];
      if (order.indexOf(c.minAlert) > order.indexOf(host.system.alert)) {
        await SR2Actor.#raiseHostAlert(host, c.minAlert as AlertLevel);
        notes.push(tx('SR2E.Card.Actor.alert3', { minAlert: c.minAlert }));
      }
    }
    return `<p>${escText(host.name)}: ${escText(notes.join('; ') || tx('SR2E.Card.Actor.noChange'))}.</p>`;
  }

  /** Apply a host change (or, for a player who does not own the host, post it for the GM), whispered to the GMs. */
  static async changeHost(host: any, c: HostChange, label: string, sourceUuid = ''): Promise<void> {
    const gms = [...((game as any).users ?? [])].filter((u: any) => u.isGM).map((u: any) => u.id);
    let body: string;
    let flags: Record<string, unknown> = {};
    if (canWriteNow(host)) body = (await SR2Actor.applyHostChange(host.uuid, c)) ?? '';
    else {
      body = `<p><button type="button" data-sr2e-action="applyHost">${tx('SR2E.Card.Actor.applyGm')}</button></p>`;
      flags = { [SYSTEM_ID]: { hostChange: { hostUuid: host.uuid, ...c, ...(sourceUuid ? { sourceUuid } : {}) } } };
    }
    // Blind when a player's client posts it, so the player doesn't read the GM's card (v0.34.0).
    await ChatMessage.create({ speaker: { alias: host.name }, content: `<p><em>${tx('SR2E.Card.Actor.gmOnly')}</em> · <strong>${escText(label)}</strong></p>${body}`, whisper: gms, flags, ...(isGmNow() ? {} : { blind: true }) });
  }

  /** GM: generate paydata files for a host from its security code (RULES.MATRIX.paydata). */
  static async generatePaydata(host: any): Promise<number> {
    const code = host.system.securityCode as string;
    const c = RULES.MATRIX.paydata.codes[code] ?? RULES.MATRIX.paydata.codes['orange']!;
    const d6 = async (n: number) => n > 0 ? ((await new Roll(`${n}d6`).evaluate()).dice[0].results.map((r: any) => r.result as number)) : [];
    const count = paydataCount(code, await d6(c.pointsDice));
    const existing = [...(host.system.files ?? [])];
    const start = existing.filter((f: any) => f.paydata).length;
    const made: DataFile[] = [];
    for (let i = 0; i < count; i++) {
      const sizes = await d6(c.sizeDice);
      const [def] = await d6(1);
      const id = (foundry as any).utils?.randomID?.() ?? `f${Date.now()}${i}`;
      made.push({ id, ...paydataFile(code, host.system.securityValue, sizes, def ?? 1, start + i + 1), foundBy: [] });
    }
    await host.update({ 'system.files': [...existing, ...made] });
    const gms = [...((game as any).users ?? [])].filter((u: any) => u.isGM).map((u: any) => u.id);
    await ChatMessage.create({
      speaker: { alias: host.name },
      content: `<p><em>${tx('SR2E.Card.Actor.gmOnly')}</em> · <strong>${tx('SR2E.Card.Actor.paydataFor', { hostName: escText(host.name) })}</strong> ${tCount(count, 'SR2E.Card.Actor.files', { code: escText(code) })}</p>${made.length ? `<ul>${made.map((f) => `<li>${tx('SR2E.Card.Actor.mp2', { name: escText(f.name), size: f.size, value: f.value, part: f.scramble ? tx('SR2E.Card.Actor.scramble', { scramble: f.scramble }) : f.encrypted ? tx('SR2E.Card.Actor.encrypted2', { encrypted: f.encrypted }) : '' })}</li>`).join('')}</ul>` : ''}`,
      whisper: gms,
    });
    return count;
  }

  /** Whether the target of a Matrix attack gets to defend (RULES.MATRIX.defense). */
  static matrixCanDefend(target: any): boolean {
    if (!target) return false;
    if (target.type === 'ic') return RULES.MATRIX.defense.ic === 'rating';
    return RULES.MATRIX.defense.persona === 'pool' && Boolean(target.isJackedIn?.());
  }

  /** v0.50.0: the system-operation dialog's preview: what this decker's (or a frame's) operation in the host finds by itself. */
  systemTestPreview(host: any = this.currentHost(), frame: any = null): TargetNumberModifier[] {
    if (frame) return SR2Actor.smokeMods(host);
    return this.#testModifiers({ pool: 'hacking', modifiers: [...this.matrixTestMods(host), ...this.#matrixDice().modifiers] });
  }

  /** v0.50.0: the cybercombat dialog's preview: the target's TN and everything this decker's attack would find by itself. */
  matrixAttackPreview(targetUuid: string | null): { base: number; label: string; modifiers: TargetNumberModifier[] } | null {
    const target: any = targetUuid ? fromUuidSync(targetUuid) : null;
    if (target && target.type !== 'ic' && !target.isJackedIn?.()) return null;
    const t = !target ? { tn: 4, label: tx('SR2E.Card.Actor.tn8', { tn: 4 }), modifiers: [] as TargetNumberModifier[] }
      : target.type === 'ic' ? { tn: target.system.rating, label: tx('SR2E.Card.Actor.sRating', { name: target.name }), modifiers: [] as TargetNumberModifier[] }
      : { tn: target.system.derived.matrix.evasion, label: tx('SR2E.Card.Actor.sEvasion2', { name: target.name }), modifiers: SR2Actor.mirrorsMods(target) };
    const own = this.#matrixDice();
    return { base: Number(t.tn) || 4, label: t.label, modifiers: this.#testModifiers({ pool: 'hacking', modifiers: [...t.modifiers, ...(target ? this.#maneuverMods(target) : []), ...this.matrixTestMods(), ...own.modifiers] }) };
  }

  /**
   * Cybercombat attack by a decker: Computer + Hacking Pool vs TN = the IC's rating (or another
   * persona's Evasion), Power = the attack utility's rating at its damage level. The target may
   * defend (RULES.MATRIX.defense), then resists.
   */
  async matrixAttack(opts: { targetUuid?: string | null; programId?: string | null; poolDice?: number; modifiers?: TargetNumberModifier[]; exclude?: string[] } = {}): Promise<SuccessTestResult | null> {
    // Frames and agents fight with their rating and a carried attack utility (v0.40.0).
    if (this.type === 'ic' && ['frame', 'agent'].includes(this.sys.kind)) return this.#frameAttack(opts);
    if (!this.isJackedIn()) {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.isNotJackedIn', { name: escHtml(this.name) }));
      return null;
    }
    const prog: any = opts.programId ? this.items.get(opts.programId) : null;
    if (!prog || prog.system.kind !== 'attack' || !prog.system.loaded || prog.system.erased) {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.needsALoadedAttackUtility', { name: escHtml(this.name) }));
      return null;
    }
    if (!SR2Actor.programReady(prog)) {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.isStillLoadingIntoActiveMemory', { progName: escHtml(prog.name) }));
      return null;
    }
    if (!this.#arrived() || !this.#linkOk()) return null;
    const target: any = opts.targetUuid ? await fromUuid(opts.targetUuid) : null;
    const t = SR2Actor.#matrixTargetTn(target);
    if (!t) return null;
    const { dice, modifiers, suffix } = this.#matrixDice();
    // v0.71.0 (R7): no higher than the working MPCP.
    const power = this.utilityRating(prog);
    const level = prog.system.damageLevel as DamageLevel;
    // v0.57.0: a maneuver for position on the target (used up by this attack); the target's parry.
    const pos = target ? this.#maneuverMods(target) : [];
    const attack = target ? { attackerUuid: this.uuid as string, targetUuid: target.uuid as string, weaponName: prog.name, melee: false, damageType: 'physical' as DamageType, power, level, matrix: true } : undefined;
    const r = await this.#runTest(`${prog.name} (${t.label}, ${power}${level})${suffix}`, dice, {
      targetNumber: t.tn, poolDice: opts.poolDice ?? 0, pool: 'hacking', modifiers: [...(opts.modifiers ?? []), ...t.modifiers, ...pos, ...this.matrixTestMods(), ...modifiers],
      ...(opts.exclude?.length ? { exclude: opts.exclude } : {}),
    }, { kind: 'attack', ...(attack ? { attack } : {}) });
    if (target && pos.some((m) => m.value < 0)) await this.update({ 'system.matrix.maneuvers': consumePosition(this.sys.matrix?.maneuvers ?? [], target.uuid, SR2Actor.matrixNow()) });
    return r;
  }

  /** v0.57.0: this persona's position on a target (−TN) and the target persona's parry against it (+TN). */
  #maneuverMods(target: any): TargetNumberModifier[] {
    const now = SR2Actor.matrixNow();
    const out: TargetNumberModifier[] = [];
    const pos = positionBonus(this.sys.matrix?.maneuvers ?? [], target.uuid, now);
    if (pos) out.push(pos);
    if (target.type !== 'ic') {
      const parry = parryPenalty(target.system?.matrix?.maneuvers ?? [], this.uuid as string, target.name, now);
      if (parry) out.push(parry);
    }
    return out;
  }

  /**
   * The TN of a cybercombat attack on a target: IC, frames and agents by their rating, a persona by
   * its Evasion (+ its Mirrors). No target: TN 4. Null (warned) when the target is not in the Matrix.
   */
  static #matrixTargetTn(target: any): { tn: number; label: string; modifiers: TargetNumberModifier[] } | null {
    if (!target) return { tn: 4, label: tx('SR2E.Card.Actor.tn42'), modifiers: [] };
    if (target.type === 'ic') return { tn: target.system.rating, label: tx('SR2E.Card.Actor.tnSRating', { targetName: target.name }), modifiers: [] };
    if (target.isJackedIn?.()) return { tn: target.system.derived.matrix.evasion, label: tx('SR2E.Card.Actor.tnSEvasion', { targetName: target.name }), modifiers: SR2Actor.mirrorsMods(target) };
    ui.notifications?.warn?.(tx('SR2E.Notify.Actor.isNotInTheMatrix', { targetName: escHtml(target.name) }));
    return null;
  }

  /** A frame or agent attacks (v0.40.0): rating + pool dice, Power from its carried attack utility. */
  async #frameAttack(opts: { targetUuid?: string | null; programId?: string | null; modifiers?: TargetNumberModifier[] }): Promise<SuccessTestResult | null> {
    const agent = this.sys.kind === 'agent';
    if (this.sys.derived?.crashed) {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.hasCrashed', { name: escHtml(this.name) }));
      return null;
    }
    const owner: any = this.sys.ownerUuid ? fromUuidSync(this.sys.ownerUuid) : null;
    if (!agent && !owner?.isJackedIn?.()) {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.sOwnerMustBeJackedIn', { name: escHtml(this.name) }));
      return null;
    }
    const attacks = (src: any) => (src?.programs?.() ?? []).filter((p: any) => p.system.kind === 'attack' && p.system.loaded && !p.system.erased && SR2Actor.programReady(p));
    const own = attacks(this);
    const list = own.length || !RULES.MATRIX.carry.ownerUtilities ? own : attacks(owner);
    const prog: any = (opts.programId ? list.find((p: any) => p.id === opts.programId) : null) ?? [...list].sort((a: any, b: any) => (b.system.rating ?? 0) - (a.system.rating ?? 0))[0] ?? null;
    if (!prog) {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.carriesNoAttackUtility', { name: escHtml(this.name) }));
      return null;
    }
    const target: any = opts.targetUuid ? await fromUuid(opts.targetUuid) : null;
    if (target && target.uuid === this.uuid) return null;
    const t = SR2Actor.#matrixTargetTn(target);
    if (!t) return null;
    const host: any = this.sys.hostUuid ? fromUuidSync(this.sys.hostUuid) : null;
    const fd = agent ? agentDice(this.sys.rating) : frameDice(this.sys.rating, Boolean(this.sys.smart));
    const power = prog.system.rating as number;
    const level = prog.system.damageLevel as DamageLevel;
    const attack = target ? { attackerUuid: this.uuid as string, targetUuid: target.uuid as string, weaponName: `${this.name}: ${prog.name}`, melee: false, damageType: 'physical' as DamageType, power, level, matrix: true } : undefined;
    // v0.57.0: the frame's own Matrix damage, and a target persona's parry against it.
    const parry = target && target.type !== 'ic' ? parryPenalty(target.system?.matrix?.maneuvers ?? [], this.uuid as string, target.name, SR2Actor.matrixNow()) : null;
    return this.#runTest(tx('SR2E.Card.Actor.rating7', { name: this.name, progName: prog.name, label: t.label, power, level, fdDice: fd.dice, part: fd.pool ? tx('SR2E.Card.Actor.pool', { fdPool: fd.pool }) : '' }), fd.dice + fd.pool, {
      targetNumber: t.tn, poolDice: 0, noPenalties: true, modifiers: [...(opts.modifiers ?? []), ...t.modifiers, ...SR2Actor.smokeMods(host), ...matrixWoundModifiers(Number(this.sys.matrix?.monitor ?? 0), { ic: true }), ...(parry ? [parry] : [])],
    }, { kind: 'attack', ...(attack ? { attack } : {}) });
  }

  /**
   * An IC acts on a jacked-in decker, by its behavior (RULES.MATRIX.icAttackTn): killer, blaster,
   * sparky and black IC damage; probe and scout raise the tally; crippler and ripper go after a
   * persona program; tar baby and tar pit after a utility; trace locks on. Barrier and scramble IC
   * only guard.
   */
  async icAttack(opts: { targetUuid?: string | null; modifiers?: TargetNumberModifier[]; attribute?: string; programId?: string | null; behavior?: string | null; force?: boolean } = {}): Promise<SuccessTestResult | null> {
    if (this.type !== 'ic') return null;
    if (this.sys.derived.crashed) {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.hasBeenDerezzed', { name: escHtml(this.name) }));
      return null;
    }
    // v0.46.0: a construct IC can act as any of its component behaviors.
    const can = constructBehaviors(this.sys.behavior ?? 'killer', this.sys.construct ?? []);
    if (opts.behavior && !can.includes(opts.behavior as IcBehavior)) {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.cannotActAsIc', { name: escHtml(this.name), iC_BEHAVIOR_LABELS: escHtml(IC_BEHAVIOR_LABELS[opts.behavior as IcBehavior] ?? opts.behavior) }));
      return null;
    }
    const behavior = (opts.behavior || this.sys.behavior || 'killer') as IcBehavior;
    const kind = icActionKind(behavior);
    const host: any = this.sys.hostUuid ? await fromUuid(this.sys.hostUuid) : null;
    if (kind === 'passive') {
      ui.notifications?.warn?.((this.sys.guards ? tx('SR2E.Notify.Actor.isIcItGuardsAndDoesWithTheSubsystem', { name: escHtml(this.name), iC_BEHAVIOR_LABELS: escHtml(IC_BEHAVIOR_LABELS[behavior]), guards: escHtml(cap(this.sys.guards)) }) : tx('SR2E.Notify.Actor.isIcItGuardsAndDoesPlain', { name: escHtml(this.name), iC_BEHAVIOR_LABELS: escHtml(IC_BEHAVIOR_LABELS[behavior]) })));
      return null;
    }
    const target: any = opts.targetUuid ? await fromUuid(opts.targetUuid) : null;
    // IC can also go after a decker's frames and agents, but only to damage them (v0.40.0).
    const program = target?.type === 'ic' && ['frame', 'agent'].includes(target.system?.kind);
    if (program && (target.system.derived?.crashed || (kind !== 'damage' && kind !== 'report'))) {
      ui.notifications?.warn?.(target.system.derived?.crashed ? tx('SR2E.Notify.Actor.hasCrashed2', { targetName: escHtml(target.name) }) : tx('SR2E.Notify.Actor.icOnlyWorkOnADecker', { iC_BEHAVIOR_LABELS: escHtml(IC_BEHAVIOR_LABELS[behavior]), targetName: escHtml(target.name) }));
      return null;
    }
    if (target && !program && !target.isJackedIn?.()) {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.isNotJackedIn2', { targetName: escHtml(target.name) }));
      return null;
    }
    if (!target && kind !== 'damage' && kind !== 'report') {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.needsADeckerToActOn', { name: escHtml(this.name) }));
      return null;
    }
    const m = target?.system?.derived?.matrix;
    const pr = program ? Number(target.system.rating ?? 0) : null;
    const persona = pr != null
      ? { evasion: pr, masking: pr, detectionFactor: pr, bod: pr, sensors: pr }
      : { evasion: m?.evasion ?? 4, masking: m?.masking ?? 4, detectionFactor: target?.liveDetectionFactor?.() ?? m?.detectionFactor ?? 4, bod: m?.bod ?? 4, sensors: m?.sensors ?? 4 };
    // v0.57.0: a decker who broke contact must be found again first.
    const now57 = SR2Actor.matrixNow();
    if (target && !program && evadedBy(target.system?.matrix?.maneuvers ?? [], this.uuid as string, now57) && !opts.force) {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.hasBrokenContactWithItMust', { targetName: escHtml(target.name), name: escHtml(this.name) }));
      return null;
    }
    // Smoke in the host, and the target's Mirrors on attacks against its Evasion (v0.40.0).
    // v0.57.0: the IC's own Matrix damage, and the target's parry.
    const parry = target && !program ? parryPenalty(target.system?.matrix?.maneuvers ?? [], this.uuid as string, target.name, now57) : null;
    const situational = (from: string) => [...SR2Actor.smokeMods(host), ...(!program && from === 'evasion' ? SR2Actor.mirrorsMods(target) : []),
      ...matrixWoundModifiers(Number(this.sys.matrix?.monitor ?? 0), { ic: true }), ...(parry ? [parry] : [])];
    const rating = this.sys.rating as number;
    // v0.57.0: the IC may roll the host's Security Value (its rating stays the Power).
    const atk = icAttackDiceFor({ rating, securityValue: Number(host?.system?.securityValue ?? 0) });
    if (kind === 'tally') {
      // Probe and scout: their successes go on the security tally.
      const t = icActionTarget(behavior, persona);
      const rolls: any[] = [];
      const r = await successTest({ dice: atk.dice, targetNumber: t.tn, modifiers: [...(opts.modifiers ?? []), ...situational('detectionFactor')], roll: foundryRoller(rolls) });
      const label = tx('SR2E.Card.Actor.ratingVs', { name: this.name, part: behavior === 'scout' ? tx('SR2E.Card.Actor.scouts') : tx('SR2E.Card.Actor.probes'), targetName: target.name, rating, label: t.label, tn: t.tn });
      // v0.57.0: onto the target's own tally (a frame's goes on its owner's).
      const owner: any = program ? (target.system.ownerUuid ? fromUuidSync(target.system.ownerUuid) : null) : target;
      const who = owner?.tallyFor ? owner.tallyFor(program ? target : null) : { key: target.uuid as string, name: target.name as string };
      if (host?.type === 'host') await SR2Actor.addToTally(host, r.successes, { label, result: r, rolls }, who, this.uuid as string);
      else await this.#post(this.#snapshot(label, r, { kind: 'plain' }), r, rolls);
      return r;
    }
    let prog: any = null;
    if (kind === 'utility') {
      prog = opts.programId ? target.items.get(opts.programId) : null;
      prog ??= target.programs().filter((p: any) => p.system.loaded && !p.system.erased).sort((x: any, y: any) => (y.system.rating ?? 0) - (x.system.rating ?? 0))[0] ?? null;
      if (!prog || !prog.system.loaded || prog.system.erased) {
        ui.notifications?.warn?.(tx('SR2E.Notify.Actor.hasNoLoadedUtilityForTo', { targetName: escHtml(target.name), name: escHtml(this.name) }));
        return null;
      }
    }
    const attribute = opts.attribute || this.sys.attribute || 'evasion';
    const t = target ? icActionTarget(behavior, persona, { attribute, utilityRating: prog?.system?.rating }) : { tn: 4, label: tx('SR2E.Card.Actor.tn8', { tn: 4 }) };
    // v0.46.0: a tortoise has no ASIST for black IC to reach the decker through.
    const tortoise = Boolean(target?.system?.derived?.matrix?.tortoise) && RULES.MATRIX.tortoise.immuneToBlackIc;
    const black = kind === 'damage' && this.sys.category === 'black' && !program && !tortoise;
    const power = rating;
    const level = this.sys.damageLevel as DamageLevel;
    // Cold sim: black IC do Stun instead of Physical (RULES.MATRIX.sim.cold); so does an ICCM filter (v0.46.0).
    const iccm = Number(target?.system?.derived?.cyber?.iccm ?? 0) > 0 && RULES.MATRIX.iccm.blackIcStun;
    const damageType = (black ? (iccm ? 'stun' : blackIcDamageType(target?.system?.derived?.matrix?.sim ?? target?.system?.matrix?.sim ?? 'cold', this.sys.damageType)) : 'physical') as DamageType;
    const ic: IcAction = {
      behavior, icUuid: this.uuid as string, icName: this.name as string, rating,
      ...(kind === 'attribute' ? { attribute } : {}), ...(prog ? { programId: prog.id as string, programName: prog.name as string } : {}),
      ...(kind === 'trace' ? { traceMode: this.sys.traceMode as string } : {}), ...(host ? { hostUuid: host.uuid as string } : {}),
      ...(behavior === 'psychotropic' ? { payload: (this.sys.payload as string) || psychotropicKindFromName(`${this.sys.icType ?? ''} ${this.name}`) } : {}),
    };
    const attack = target ? { attackerUuid: this.uuid as string, targetUuid: target.uuid as string, weaponName: this.name, melee: false, damageType, power, level, matrix: true, ...(black ? { black: true } : {}), ic } : undefined;
    const label = kind === 'damage'
      ? tx('SR2E.Card.Actor.attacks2', { name: this.name, part: behavior !== this.sys.behavior ? tx('SR2E.Card.Actor.construct2', { icBehaviorLabels: IC_BEHAVIOR_LABELS[behavior] }) : '', part2: target ? tx('SR2E.Card.Actor.tnS2', { targetName: target.name, part: program ? tx('SR2E.Card.Actor.rating10') : tx('SR2E.Card.Actor.evasion') }) : tx('SR2E.Card.Actor.tn42'), power, level, part3: black ? ` ${damageType}` : '', part4: tortoise && this.sys.category === 'black' ? tx('SR2E.Card.Actor.aTortoiseMatrixDamageOnly') : '' })
      : `${this.name} (${IC_BEHAVIOR_LABELS[behavior]}${behavior !== this.sys.behavior ? tx('SR2E.Card.Actor.construct') : ''}) ${kind === 'trace' ? tx('SR2E.Card.Actor.traces') : kind === 'utility' ? tx('SR2E.Card.Actor.goesAfter', { progName: prog?.name }) : kind === 'attribute' ? tx('SR2E.Card.Actor.goesAfter2', { attribute: cap(attribute) }) : tx('SR2E.Card.Actor.acts2')}${target ? tx('SR2E.Card.Actor.tn10', { label: t.label, tn: t.tn }) : ''}`;
    const from = RULES.MATRIX.icAttackTn[behavior] ?? 'evasion';
    // v0.57.0: black IC that attack a decker engage them: they can't simply jack out.
    if (this.sys.category === 'black' && target && !program && RULES.MATRIX_V57.blackIcHold.enabled) await SR2Actor.#engage(target, this.uuid as string);
    return this.#runTest(`${label}${atk.note ? tx('SR2E.Card.Actor.dice4', { atkNote: atk.note }) : ''}`, atk.dice, { targetNumber: t.tn, modifiers: [...(opts.modifiers ?? []), ...(target ? situational(from) : [...SR2Actor.smokeMods(host), ...matrixWoundModifiers(Number(this.sys.matrix?.monitor ?? 0), { ic: true })])] }, { kind: 'attack', ...(attack ? { attack } : {}) });
  }

  /** v0.57.0: mark a decker as engaged by a black IC (the GM's client when the player owns the decker and the IC is the GM's). */
  static async #engage(target: any, icUuid: string): Promise<void> {
    const list: string[] = [...(target.system?.matrix?.engagedBy ?? [])];
    if (list.includes(icUuid)) return;
    try { await target.update({ 'system.matrix.engagedBy': [...list, icUuid] }); } catch (err) { console.warn('sr2e | engage (not the owner: the GM\'s own client runs IC)', err); }
  }

  /** The IC of this IC's party in its host (itself included), alive (v0.46.0). */
  partyMembers(): any[] {
    if (this.type !== 'ic') return [];
    const party = String(this.sys.party ?? '').trim();
    if (!party) return [this];
    return allActors().filter((a: any) => a.type === 'ic' && String(a.system?.party ?? '').trim() === party && a.system.hostUuid === this.sys.hostUuid && !a.system.derived?.crashed);
  }

  /**
   * Party IC (v0.46.0): every live member of this IC's party in the host acts on the target, one
   * after another, each by its own behavior (guard IC sit it out).
   */
  async partyAttack(targetUuid: string, opts: { modifiers?: TargetNumberModifier[] } = {}): Promise<number> {
    let n = 0;
    for (const m of this.partyMembers()) {
      // A construct guarding by its own behavior still joins in with an active one.
      const act = constructBehaviors(m.system.behavior ?? 'killer', m.system.construct ?? []).find((b) => icActionKind(b) !== 'passive');
      if (!act) continue;
      if (await m.icAttack({ targetUuid, ...(act !== m.system.behavior ? { behavior: act } : {}), ...(opts.modifiers ? { modifiers: opts.modifiers } : {}) })) n++;
    }
    if (!n) ui.notifications?.warn?.(tx('SR2E.Notify.Actor.noMemberOfSPartyCould', { party: escHtml(this.sys.party || this.name) }));
    return n;
  }

  /** Defend in cybercombat: a persona with Hacking Pool dice, an IC with its rating (RULES.MATRIX.defense). */
  async #defendMatrix(attack: AttackState, poolDice: number): Promise<void> {
    const ic = this.type === 'ic';
    const dice = ic && RULES.MATRIX.defense.ic === 'rating' ? (this.sys.rating as number) : 0;
    const pool = ic ? 0 : Math.max(0, Math.min(poolDice, (this.sys.derived?.hackingPoolLeft as number | undefined) ?? 0));
    const rolls: any[] = [];
    const result = await successTest({ dice, poolDice: pool, targetNumber: attack.targetNumber, roll: foundryRoller(rolls) });
    if (pool > 0) await this.#spendPool('hacking', pool);
    const label = ic ? tx('SR2E.Card.Actor.defendsRating', { name: this.name, dice }) : pool ? tx('SR2E.Card.Actor.matrixDefenseHackingPool', { pool }) : tx('SR2E.Card.Actor.matrixDefenseNoHackingPoolDice');
    await this.#post(this.#snapshot(label, result, { kind: 'defend', defendAgainst: attack }), result, rolls);
  }

  /**
   * A Matrix attack that got through `defense` successes: damage (with a Resist button), or the
   * IC's effect (crippling, tar, trace), applied once even across Karma re-rolls.
   */
  async #matrixHit(snap: TestSnapshot, attack: AttackState, defense: number, defended: boolean): Promise<Resolved> {
    const ic = attack.ic;
    const kind = ic ? icActionKind(ic.behavior) : 'damage';
    const target: any = fromUuidSync(attack.targetUuid);
    const tName = target?.name ?? tx('SR2E.Card.Actor.theTarget');
    const tally = defended ? tx('SR2E.Card.Actor.attackVsDefense3', { attackAttackSuccesses: attack.attackSuccesses, defense }) : '';
    if (kind === 'damage') {
      const o = resolveAttack({ attackSuccesses: attack.attackSuccesses, defenseSuccesses: defense, power: attack.power, level: attack.level });
      if (!o.hit || !o.level) return { html: `<p>${outcomeWord('missed')} ${tally || tx('SR2E.Card.Actor.noNetSuccesses')}.</p>`, flags: {}, snap };
      const damage: DamageState = {
        targetUuid: attack.targetUuid, melee: false, damageType: attack.damageType, power: o.power, level: o.level, matrix: true,
        ...(attack.black ? { black: true } : {}), ...(ic ? { ic } : {}),
      };
      const what = attack.black ? tx('SR2E.Card.Actor.toTheDecker2', { damageDamageType: damageWord(damage.damageType) }) : tx('SR2E.Card.Actor.matrixDamage');
      const lead = defended ? tx('SR2E.Card.Actor.net2', { tally, netSuccesses: o.netSuccesses }) : tCount(o.netSuccesses, 'SR2E.Card.Actor.netSuccesses2');
      // Psychotropic IC: the hit also works on the decker's mind (v0.40.0).
      const psycho = ic?.behavior === 'psychotropic' && target?.type !== 'ic';
      const kindLabel = PSYCHOTROPIC_LABELS[(ic?.payload ?? 'cyberphobia') as keyof typeof PSYCHOTROPIC_LABELS] ?? ic?.payload;
      const ps = RULES.MATRIX.psychotropic;
      const psychoBtn = psycho ? ` <button type="button" data-sr2e-action="psychotropic" title="${tx('SR2E.Card.Actor.theIcSPsychotropicPayload')}">${tx('SR2E.Card.Actor.resistVs3', { kindLabel: escText(kindLabel), psResist: escText(cap(ps.resist)), icRating: ic!.rating })}</button>` : '';
      // v0.57.0: black IC reach everyone riding the decker's hitcher jacks.
      const riders: any[] = attack.black && RULES.MATRIX_V57.hitchers.blackIc && target?.hitchers ? target.hitchers() : [];
      const damages: DamageState[] = [damage, ...riders.map((h: any) => ({ ...damage, targetUuid: h.uuid as string }))];
      const riderBtns = riders.map((h: any, i: number) => ` <button type="button" data-sr2e-action="resist" data-index="${i + 1}">${tx('SR2E.Card.Actor.resistHitcher', { name: escText(h.name) })}</button>`).join('');
      return {
        html: `<p>${outcomeWord('hit')} ${lead}: <strong>${damage.power}${damage.level}</strong>${escText(what)}</p><p><button type="button" data-sr2e-action="resist" data-index="0">${tx('SR2E.Card.Actor.resist8', { tName: escText(tName) })}</button>${riderBtns}${psychoBtn}</p>`,
        flags: { damage, damages, ...(psycho ? { psychotropic: { deckerUuid: attack.targetUuid, icName: ic!.icName, rating: ic!.rating, kind: ic!.payload ?? 'cyberphobia', hostUuid: ic!.hostUuid ?? '' } } : {}) }, snap,
      };
    }
    const net = attack.attackSuccesses - defense;
    if (net <= 0) return { html: `<p><strong>${defended ? tx('SR2E.Card.Actor.evaded') : tx('SR2E.Card.Actor.noEffect')}.</strong> ${tally || tx('SR2E.Card.Actor.noNetSuccesses')}.</p>`, flags: {}, snap };
    const lead = `${tally ? `${tally}: ` : ''}${escText(plural(net, 'net success'))}`;
    if (kind === 'report') return { html: `<p><strong>${escText(ic!.icName)}</strong> ${tx('SR2E.Card.Actor.succeeds2', { lead })}</p>`, flags: {}, snap };
    if (snap.matrixEffect?.applied) {
      return { html: `<p>${lead}. <em>${tx('SR2E.Card.Actor.icEffectAlreadyApplied', { icName: escText(ic!.icName), plural: escText(plural(snap.matrixEffect.net, 'net success')) })}</em></p>`, flags: {}, snap };
    }
    let body = '';
    try {
      if (kind === 'attribute') {
        const attr = (ic!.attribute ?? 'evasion') as 'bod' | 'evasion' | 'masking' | 'sensors';
        const loss = personaAttributeLoss(net);
        if (ic!.behavior === 'ripper') {
          const deck: any = target?.activeDeck?.();
          const dmg = { ...NO_DECK_DAMAGE, ...(deck?.system?.damage ?? {}) };
          await deck?.update({ 'system.damage': { ...dmg, [attr]: dmg[attr] + loss } });
          body = `<strong>${tx('SR2E.Card.Actor.rips', { icIcName: escText(ic!.icName), attr: escText(cap(attr)), loss })}</strong> ${tx('SR2E.Card.Actor.fromSDeckUntilRepaired', { tName: escText(tName) })}`;
        } else {
          const cur = { bod: 0, evasion: 0, masking: 0, sensors: 0, ...(target?.system?.matrix?.crippled ?? {}) };
          await target?.update({ 'system.matrix.crippled': { ...cur, [attr]: cur[attr] + loss } });
          body = `<strong>${tx('SR2E.Card.Actor.cripples', { icIcName: escText(ic!.icName), attr: escText(cap(attr)), loss })}</strong> ${tx('SR2E.Card.Actor.onSPersonaUntilTheyJack', { tName: escText(tName) })}`;
        }
      } else if (kind === 'utility') {
        const prog: any = ic!.programId ? target?.items?.get?.(ic!.programId) : null;
        // v0.49.0: an otaku's complex form is part of them: it can be crashed but never erased.
        const form = Boolean(prog?.system?.complexForm) && RULES.MATRIX.otaku.complexForms.neverErased;
        const pit = ic!.behavior === 'tarPit' && !form;
        if (prog) await prog.update({ 'system.loaded': false, ...(pit ? { 'system.erased': true } : {}) });
        body = `<strong>${tx('SR2E.Card.Actor.crashes2', { icIcName: escText(ic!.icName), icProgramName: escText(ic!.programName ?? tx('SR2E.Card.Actor.theUtility')) })}</strong>${pit ? tx('SR2E.Card.Actor.andErasesItFromTheDeck') : form && ic!.behavior === 'tarPit' ? tx('SR2E.Card.Actor.aComplexFormCanTBe') : tx('SR2E.Card.Actor.reloadItToUseItAgain')}.`;
        if (ic!.behavior === 'tarBaby' && RULES.MATRIX.tar.tarBabyDerezzes) {
          const icActor: any = fromUuidSync(ic!.icUuid);
          try {
            await icActor?.update({ 'system.matrix.monitor': RULES.MATRIX.monitorBoxes });
            body += tx('SR2E.Card.Actor.derezzes', { icIcName: escText(ic!.icName) });
          } catch { body += ` <em>${tx('SR2E.Card.Actor.gmDerez', { icIcName: escText(ic!.icName) })}</em>`; }
        }
      } else if (kind === 'trace') {
        const turns = traceTurns(net) ?? RULES.MATRIX.trace.baseTurns;
        const combat: any = (game as any).combat;
        const round = combat?.started ? Number(combat.round ?? 0) : null;
        const due = traceDue({ round, worldTime: sysNow(), turns, combatId: combat?.started ? String(combat.id ?? '') : null });
        const t = target?.system?.matrix?.trace ?? {};
        await target?.update({ 'system.matrix.trace': { ...t, active: true, icUuid: ic!.icUuid, icName: ic!.icName, mode: ic!.traceMode ?? 'dump', rating: ic!.rating, hostUuid: ic!.hostUuid ?? '', round: due.round, worldTime: due.worldTime, combatId: due.combatId ?? '' } });
        body = `<strong>${tx('SR2E.Card.Actor.locksOnTo', { icIcName: escText(ic!.icName), tName: escText(tName) })}</strong>${tx('SR2E.Card.Actor.theTraceCompletesIn')} <strong>${tCount(turns, 'SR2E.Card.Actor.combatTurns')}</strong>${tx('SR2E.Card.Actor.thenJackOutDerezItOr', { part: round != null ? tx('SR2E.Card.Actor.combatTurn3', { dueRound: due.round }) : '', part2: ic!.traceMode === 'report' ? tx('SR2E.Card.Actor.reportsTheirLocation') : ic!.traceMode === 'burn' ? tx('SR2E.Card.Actor.dumpsThemAndBurnsTheDeck') : tx('SR2E.Card.Actor.dumpsThem') })}`;
      }
    } catch (err) {
      console.warn('sr2e | Matrix effect not applied', err);
      body += ` <em>${tx('SR2E.Card.Actor.couldNotApplyThisHereGm')}</em>`;
    }
    return { html: `<p>${lead}. ${body}</p>`, flags: {}, snap: { ...snap, matrixEffect: { applied: true, net } } };
  }

  /**
   * Resist Matrix damage. IC: rating vs Power. A persona: Bod + Hacking Pool vs Power - Hardening,
   * marking the Matrix monitor. Black IC: the decker resists with Willpower (+ Hacking Pool) on
   * their own Physical or Stun track.
   */
  async resistMatrixDamage(damage: DamageState, poolDice = 0): Promise<void> {
    const rolls: any[] = [];
    const ic = this.type === 'ic';
    const m = this.sys.derived.matrix;
    // v0.57.0: a hitcher (no deck of their own) still resists black IC on their own track.
    if (!ic && !m && !damage.black) {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.hasNoCyberdeckInUse', { name: escHtml(this.name) }));
      return;
    }
    const pool = ic ? 0 : Math.max(0, Math.min(poolDice, Number(this.sys.derived.hackingPoolLeft ?? 0)));
    // Armor soaks persona damage, Shield black IC damage: rating off the Power (v0.40.0).
    const soaker = (k: 'armor' | 'shield') => {
      const p: any = ic ? null : this.bestUtility(k);
      // v0.71.0 review (F3): no higher than the working MPCP.
      return p && p.system.rating > 0 ? { programId: p.id as string, name: p.name as string, rating: this.utilityRating(p), kind: k } : null;
    };
    if (damage.black && !ic) {
      const attr = RULES.MATRIX.blackIcResist as AttributeKey;
      const shield = soaker('shield');
      const iccm = iccmDice(this.sys.derived?.cyber?.iccm ?? 0);
      const result = await successTest({ dice: this.sys.attributes[attr].total + iccm, poolDice: pool, targetNumber: matrixSoakTn(damage.power, 0, shield?.rating ?? 0), roll: foundryRoller(rolls) });
      if (pool > 0) await this.#spendPool('hacking', pool);
      await this.#post(this.#snapshot(tx('SR2E.Card.Actor.resistBlackIc', { damagePower: damage.power, damageLevel: damage.level, damageDamageType: damage.damageType, attr: cap(attr), part: iccm ? tx('SR2E.Card.Actor.iccm', { iccm }) : '', part2: shield ? `, ${shield.name} ${shield.rating}` : '' }), result, {
        kind: 'soak',
        soak: { mode: 'stage', noun: 'damage', level: damage.level, type: damage.damageType, body: this.sys.attributes.body.total, before: this.#monitor(), ...(shield ? { matrixUtility: shield } : {}) },
      }), result, rolls);
      return;
    }
    const dice = ic ? (this.sys.rating as number) : (m.bod as number);
    const hardening = ic ? 0 : (m.hardening as number);
    const armor = soaker('armor');
    const result = await successTest({ dice, poolDice: pool, targetNumber: matrixSoakTn(damage.power, hardening, armor?.rating ?? 0), roll: foundryRoller(rolls) });
    if (pool > 0) await this.#spendPool('hacking', pool);
    const before = (this.sys.matrix?.monitor as number | undefined) ?? 0;
    await this.#post(this.#snapshot(tx('SR2E.Card.Actor.resistMatrixDamage', { damagePower: damage.power, damageLevel: damage.level, part: ic ? tx('SR2E.Card.Actor.rating10') : tx('SR2E.Card.Actor.bod'), part2: hardening ? tx('SR2E.Card.Actor.hardening', { hardening }) : '', part3: armor ? `, ${armor.name} ${armor.rating}` : '' }), result, {
      kind: 'soak',
      soak: { mode: 'stage', noun: 'damage', level: damage.level, type: 'physical', body: 0, before: { physical: 0, stun: 0 }, track: 'matrix', matrixBefore: before, power: damage.power, ...(damage.ic ? { matrixIc: damage.ic } : {}), ...(armor ? { matrixUtility: armor } : {}) },
    }), result, rolls);
  }

  /** Armor or Shield that soaked a hit loses rating, once per card (RULES.MATRIX.utilities). */
  async #wearSoakUtility(r: Resolved): Promise<Resolved> {
    const u = r.snap.soak?.matrixUtility;
    if (!u || u.degraded) return r;
    const per = RULES.MATRIX.utilities[u.kind]?.degradesPerHit ?? 0;
    const prog: any = this.items.get(u.programId);
    let note = '';
    if (per > 0 && prog) {
      const after = Math.max(0, (prog.system.rating ?? 0) - per);
      await prog.update({ 'system.rating': after });
      note = `<p>${tx('SR2E.Card.Actor.soaksTheHitAndDropsTo', { name: escText(u.name) })} <strong>${after}</strong>.</p>`;
    }
    return { ...r, html: r.html + note, snap: { ...r.snap, soak: { ...r.snap.soak!, matrixUtility: { ...u, degraded: true } } } };
  }

  /**
   * A psychotropic IC's payload (v0.40.0): Willpower (+ Shield dice) vs the IC's rating. Too few
   * successes and the effect takes hold (RULES.MATRIX.psychotropic).
   */
  async resistPsychotropic(p: { icName: string; rating: number; kind: string; hostUuid?: string }, poolDice = 0): Promise<SuccessTestResult | null> {
    const ps = RULES.MATRIX.psychotropic;
    const attr = ps.resist as AttributeKey;
    const shield = ps.shieldDice ? this.utilityRating(this.bestUtility('shield')) : 0;
    const label = PSYCHOTROPIC_LABELS[p.kind as keyof typeof PSYCHOTROPIC_LABELS] ?? p.kind;
    return this.#runTest(tx('SR2E.Card.Actor.resistVs4', { label, icName: p.icName, attr: cap(attr), part: shield ? tx('SR2E.Card.Actor.shield', { shield }) : '', rating: p.rating }), (this.sys.attributes?.[attr]?.total ?? 0) + shield, {
      targetNumber: Math.max(RULES.MIN_TARGET_NUMBER, p.rating), poolDice, pool: 'hacking',
    }, { kind: 'psyche', psyche: { icName: p.icName, rating: p.rating, kind: p.kind, ...(p.hostUuid ? { hostUuid: p.hostUuid } : {}) } });
  }

  async #resolvePsyche(snap: TestSnapshot, fu: FollowUps): Promise<Resolved> {
    const ps = snap.psyche!;
    const label = PSYCHOTROPIC_LABELS[ps.kind as keyof typeof PSYCHOTROPIC_LABELS] ?? ps.kind;
    const held = snap.successes >= RULES.MATRIX.psychotropic.successesNeeded;
    const list: PsycheEffect[] = [...(this.sys.matrix?.psyche ?? [])].map((e: any) => ({ ...e }));
    const same = (e: PsycheEffect) => (x: PsycheEffect) => x.kind === e.kind && x.icName === e.icName && x.until === e.until;
    if (held) {
      // A Karma re-roll that turns a failure into a success takes the effect off again.
      if (ps.applied && ps.effect) {
        await this.update({ 'system.matrix.psyche': list.filter((x) => !same(ps.effect!)(x)) });
        return { html: `<p><strong>${tx('SR2E.Card.Actor.shakesOff', { name: escText(this.name), label: escText(label) })}</strong> ${tx('SR2E.Card.Actor.afterAll')}</p>`, flags: {}, snap: { ...snap, psyche: { ...ps, applied: false, effect: null } } };
      }
      return { html: `<p><strong>${tx('SR2E.Card.Actor.resists', { name: escText(this.name), label: escText(label) })}</strong></p>`, flags: {}, snap };
    }
    if (ps.applied) return { html: `<p><strong>${tx('SR2E.Card.Actor.takesHold', { label: escText(label) })}</strong> ${tx('SR2E.Card.Actor.alreadyApplied')}</p>`, flags: {}, snap };
    const effect = psychotropicEffect(ps.kind, ps.icName, ps.rating, SR2Actor.matrixNow().worldTime);
    await this.update({ 'system.matrix.psyche': [...list, effect] });
    const days = effect.until < 0 ? '' : tCount(Number(Math.round((effect.until - SR2Actor.matrixNow().worldTime) / 86400)), 'SR2E.Card.Actor.forDays');
    const what: Record<string, string> = {
      cyberphobia: tx('SR2E.Card.Actor.tnOnEveryMatrixTest', { tn: RULES.MATRIX.psychotropic.cyberphobiaTn }),
      frenzy: tx('SR2E.Card.Actor.theyMustAttackInCybercombatUntil'),
      judas: tx('SR2E.Card.Actor.theyAreCompelledToBetrayTheir'),
      conditioning: tx('SR2E.Card.Actor.theyAreConditionedInTheCorp'),
    };
    if (ps.kind === 'judas') {
      const gms = [...((game as any).users ?? [])].filter((u: any) => u.isGM).map((u: any) => u.id);
      await ChatMessage.create({ speaker: { alias: ps.icName }, whisper: gms, ...(isGmNow() ? {} : { blind: true }),
        content: `<p><em>${tx('SR2E.Card.Actor.gmOnly')}</em> · <strong>${tx('SR2E.Card.Actor.judas')}</strong> ${effect.until < 0 ? tx('SR2E.Card.Actor.isCompelledToBetrayTheirTeam', { name: escText(this.name) }) : tCount(Number(Math.round((effect.until - SR2Actor.matrixNow().worldTime) / 86400)), 'SR2E.Card.Actor.isCompelledToBetrayTheirTeamFor', { name: escText(this.name) })}</p>` });
      const host: any = ps.hostUuid ? fromUuidSync(ps.hostUuid) : null;
      const alert = RULES.MATRIX.psychotropic.judasAlert;
      if (host?.type === 'host' && alert !== 'none') fu.hostChange = { host, change: { minAlert: alert }, label: tx('SR2E.Card.Actor.sJudasPayloadReports', { icName: ps.icName, name: this.name }) };
    }
    return { html: `<p><strong>${tx('SR2E.Card.Actor.takesHold', { label: escText(label) })}</strong>${days}: ${what[ps.kind] ?? tx('SR2E.Card.Actor.theGmPlaysTheEffect')}.</p>`, flags: {}, snap: { ...snap, psyche: { ...ps, applied: true, effect } } };
  }

  /** Apply (or, on a re-roll, correct) damage on the Matrix condition monitor. */
  async #resolveMatrixSoak(snap: TestSnapshot, fu: FollowUps): Promise<Resolved> {
    const ctx = snap.soak as SoakContext;
    const level = resolveResistance(ctx.level, snap.successes);
    const before = ctx.matrixBefore ?? 0;
    const result = applyMatrixDamage(before, level);
    const current = (this.sys.matrix?.monitor as number | undefined) ?? 0;
    const expected = ctx.matrixAfter ?? before;
    const ic = this.type === 'ic';
    let note = '';
    if (current === expected) {
      const update: Record<string, unknown> = { 'system.matrix.monitor': result.after };
      const newlyCrashed = result.crashed && current < RULES.MATRIX.monitorBoxes;
      if (newlyCrashed && !ic && this.sys.matrix?.jackedIn) {
        const host: any = this.currentHost();
        update['system.matrix.jackedIn'] = false;
        update['system.matrix.hostUuid'] = '';
        Object.assign(update, this.#endRunUpdate());
        // A tortoise takes no dump shock (v0.46.0).
        if (!(this.isTortoise() && !RULES.MATRIX.tortoise.dumpShock)) fu.dumpShock = { tn: (host?.system?.securityValue as number | undefined) ?? RULES.MATRIX.dumpShockTn, level: dumpShockLevel(String(host?.system?.securityCode ?? '')) };
        else fu.unhitch = true;
        // Blaster and sparky crashes damage the deck too.
        if (ctx.matrixIc && (ctx.matrixIc.behavior === 'blaster' || ctx.matrixIc.behavior === 'sparky')) fu.deckDamage = { ic: ctx.matrixIc, reason: ctx.matrixIc.behavior };
      }
      await this.update(update);
      // Hot sim: heavy Matrix damage overloads the decker's senses.
      if (!ic && ctx.matrixAfter === undefined && simsenseOverload(this.matrixSim(), level)) fu.overload = ctx.power ?? 0;
    } else {
      note = ` <em>${tx('SR2E.Card.Actor.theMatrixMonitorChangedSinceThis', { resultAfter: result.after })}</em>`;
    }
    const body = level === null
      ? outcomeWord('fullyResisted', false)
      : takenMark(level, 'matrix', tx('SR2E.Card.Outcome.takesMatrix', { level: `<strong>${level}</strong>`, plural: escText(plural(result.boxes, 'box')), resultAfter: result.after, matrixMonitorBoxes: RULES.MATRIX.monitorBoxes })) + (result.crashed ? ` <strong>${ic ? tx('SR2E.Card.Actor.isDerezzed', { name: escText(this.name) }) : tx('SR2E.Card.Actor.thePersonaCrashes')}</strong>` : '');
    return { html: `<p>${body}${note}</p>`, flags: {}, snap: { ...snap, soak: { ...ctx, matrixAfter: result.after } } };
  }

  /** Dump shock after a crash: Willpower vs the host's Security Value, stun damage staged down. */
  async rollDumpShock(targetNumber: number = RULES.MATRIX.dumpShockTn, level: DamageLevel = dumpShockLevel('')): Promise<void> {
    const iccm = iccmDice(this.sys.derived?.cyber?.iccm ?? 0);
    await this.#drainTest({
      label: tx('SR2E.Card.Actor.dumpShock'), attribute: 'willpower', targetNumber,
      level, type: dumpShockType(this.matrixSim()) as DamageType, poolDice: 0, noun: 'damage', physicalNote: tx('SR2E.Card.Actor.hotSim'),
      extraDice: iccm, extraNote: `ICCM +${iccm}`,
    });
  }

  /** The sim mode in force (a tortoise is always cold, v0.46.0). */
  matrixSim(): string {
    return this.sys.derived?.matrix?.sim ?? this.sys.matrix?.sim ?? 'cold';
  }

  /** Whether this decker runs a tortoise (no ASIST, v0.46.0). */
  isTortoise(): boolean {
    return Boolean(this.sys.derived?.matrix?.tortoise);
  }

  /**
   * The wireless link in use (v0.46.0): for a cellular or relayed connection, the deck's signal
   * against the distance to the relay (`system.matrix.relayKm`). Null for hard lines.
   */
  matrixLink(): SignalCheck | null {
    const conn = this.sys.matrix?.connection ?? 'jackpoint';
    if (!wirelessConnection(conn)) return null;
    return signalCheck(Number(this.sys.derived?.matrix?.signal ?? 0), Number(this.sys.matrix?.relayKm ?? 0), 'matrix');
  }

  /** Refuse (or warn about) a wireless link out of range (RULES.SIGNAL). True = go on. */
  #linkOk(force = false): boolean {
    // v0.49.0: a jammed wireless link carries nothing.
    if (this.sys.matrix?.jammed?.active && wirelessConnection(this.sys.matrix?.connection ?? 'jackpoint')) {
      ui.notifications?.warn?.((this.sys.matrix.jammed.by ? tx('SR2E.Notify.Actor.sWirelessLinkIsJammedClearWithBy', { name: escHtml(this.name), jammedBy: escHtml(this.sys.matrix.jammed.by) }) : tx('SR2E.Notify.Actor.sWirelessLinkIsJammedClearPlain', { name: escHtml(this.name) })));
      return false;
    }
    const c = this.matrixLink();
    if (!c?.checked || c.inRange) return true;
    const msg = tx('SR2E.Card.Actor.sLinkIsOutOfRange', { name: this.name, matrixConnection: this.sys.matrix?.connection ?? '', note: c.note });
    if (RULES.SIGNAL.outOfRange === 'block' && !force) {
      ui.notifications?.warn?.(escHtml(msg));
      return false;
    }
    ui.notifications?.info?.(escHtml(msg));
    return true;
  }

  /** Simsense overload (hot sim): Willpower vs the damage's Power, RULES.MATRIX.sim.hot.overloadLevel Stun. */
  async rollOverload(targetNumber: number): Promise<void> {
    const iccm = iccmDice(this.sys.derived?.cyber?.iccm ?? 0);
    await this.#drainTest({
      label: tx('SR2E.Card.Actor.simsenseOverload2'), attribute: 'willpower', targetNumber: Math.max(RULES.MIN_TARGET_NUMBER, targetNumber),
      level: RULES.MATRIX.sim.hot.overloadLevel as DamageLevel, type: 'stun', poolDice: 0, noun: 'damage',
      extraDice: iccm, extraNote: `ICCM +${iccm}`,
    });
  }

  /**
   * Launch a frame or agent program: an IC actor of kind 'frame' (into the decker's host) or
   * 'agent' (into the host, or onto the grid), owned by the decker. `carry`: ids of the decker's
   * loaded utilities it takes copies of, at most rating × RULES.MATRIX.carry.carryPerRating (v0.40.0).
   */
  async launchFrame(programId: string, opts: { carry?: string[] } = {}): Promise<any | null> {
    const prog: any = this.items.get(programId);
    if (!prog || !['frame', 'smart-frame', 'agent'].includes(prog.system.kind) || !prog.system.loaded || prog.system.erased || !SR2Actor.programReady(prog)) {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.pickALoadedFrameOrAgent'));
      return null;
    }
    const agent = prog.system.kind === 'agent';
    if (!this.isJackedIn() || (!agent && !this.sys.matrix?.hostUuid)) {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.mustBeToLaunch', { name: escHtml(this.name), part: agent ? tx('SR2E.Notify.Actor.jackedIn') : tx('SR2E.Notify.Actor.inAHost'), part2: agent ? tx('SR2E.Notify.Actor.anAgent') : tx('SR2E.Notify.Actor.aFrame') }));
      return null;
    }
    const carry = [...new Set(opts.carry ?? [])].map((id) => this.items.get(id)).filter((p: any) => p && p.type === 'program' && p.id !== prog.id);
    if (carry.some((p: any) => !p.system.loaded || p.system.erased || !SR2Actor.programReady(p) || ['frame', 'smart-frame', 'agent'].includes(p.system.kind))) {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.aFrameOrAgentCanOnly'));
      return null;
    }
    const limit = carryLimit(prog.system.rating);
    if (carry.length > limit) {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.ratingCanCarryAtMostUtilit', { progName: escHtml(prog.name), progRating: escHtml(prog.system.rating), limit: tCount(limit, 'SR2E.Count.utility') }));
      return null;
    }
    const cls: any = (Actor as any).implementation ?? Actor;
    const name = `${prog.name} (${this.name})`;
    const owners = Object.fromEntries([...((game as any).users ?? [])].filter((u: any) => !u.isGM && this.testUserPermission?.(u, 'OWNER')).map((u: any) => [u.id, 3]));
    const copy = (p: any) => {
      const o = typeof p.toObject === 'function' ? p.toObject() : { name: p.name, type: p.type, system: { ...p.system } };
      delete o._id;
      return { ...o, system: { ...o.system, loaded: true } };
    };
    const frame = await cls.create({
      name, type: 'ic', ownership: { default: 0, ...owners },
      prototypeToken: { name, actorLink: true },
      system: {
        kind: agent ? 'agent' : 'frame', ownerUuid: this.uuid, smart: agent || prog.system.kind === 'smart-frame', rating: prog.system.rating, behavior: 'other', category: 'white',
        hostUuid: this.sys.matrix.hostUuid ?? '', initiativeDice: agent ? RULES.MATRIX.agents.initiativeDice : RULES.MATRIX.frames.initiativeDice,
      },
      ...(carry.length ? { items: carry.map(copy) } : {}),
    });
    const where = this.currentHost()?.name ?? tx('SR2E.Card.Actor.theGrid');
    await ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor: this }), content: `<p><strong>${escText(this.name)}</strong> ${tx('SR2E.Card.Actor.launchesInto', { frameName: escText(frame?.name ?? (agent ? tx('SR2E.Card.Actor.anAgent') : tx('SR2E.Card.Actor.aFrame'))), where: escText(where), part: carry.length ? tx('SR2E.Card.Actor.carrying', { carry: carry.map((p: any) => `${escText(p.name)} ${escText(p.system.rating)}`).join(', ') }) : '' })}</p>` });
    return frame;
  }

  /** This decker's frames and agents. */
  frames(): any[] {
    return allActors().filter((a: any) => a.type === 'ic' && ['frame', 'agent'].includes(a.system.kind) && a.system.ownerUuid === this.uuid);
  }

  /** Sparky biofeedback: the decker resists the IC's rating (RULES.MATRIX.sparky). */
  async rollBiofeedback(targetNumber: number): Promise<void> {
    const sp = RULES.MATRIX.sparky;
    const iccm = iccmDice(this.sys.derived?.cyber?.iccm ?? 0);
    await this.#drainTest({
      label: tx('SR2E.Card.Actor.sparkyBiofeedback'), attribute: sp.resist as AttributeKey, targetNumber: Math.max(RULES.MIN_TARGET_NUMBER, targetNumber),
      level: sp.level as DamageLevel, type: sp.type as DamageType, poolDice: 0, noun: 'damage', physicalNote: '',
      extraDice: iccm, extraNote: `ICCM +${iccm}`,
    });
  }

  /**
   * Deck damage (blaster or sparky crash, trace and burn): the IC rolls its rating vs TN = this
   * decker's MPCP; each RULES.MATRIX.mpcpDamage.successesPerPoint successes = 1 MPCP damage.
   */
  async takeDeckDamage(icName: string, rating: number, reason = tx('SR2E.Card.Actor.crashReason')): Promise<number> {
    const deck: any = this.activeDeck() ?? [...this.items].find((i: any) => i.type === 'cyberdeck');
    if (!deck) {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.hasNoCyberdeck', { name: escHtml(this.name) }));
      return 0;
    }
    const mpcp = (this.sys.derived?.matrix?.mpcp as number | undefined) ?? deck.system.mpcp;
    const rolls: any[] = [];
    const r = await successTest({ dice: rating, targetNumber: Math.max(RULES.MIN_TARGET_NUMBER, mpcp), roll: foundryRoller(rolls) });
    const points = mpcpDamage(r.successes);
    const dmg = { ...NO_DECK_DAMAGE, ...(deck.system.damage ?? {}) };
    if (points > 0) await deck.update({ 'system.damage': { ...dmg, mpcp: dmg.mpcp + points } });
    await ChatMessage.create({
      speaker: { alias: icName },
      content: `${describeResult(tx('SR2E.Card.Actor.damagesRatingVsMpcp', { icName, deckName: deck.name, reason, rating, mpcp }), r)}<p>${points > 0 ? `<strong>${tx('SR2E.Card.Actor.mpcp', { points })}</strong> ${tx('SR2E.Card.Actor.nowUntilRepaired', { value: Math.max(0, deck.system.mpcp - dmg.mpcp - points) })}` : tx('SR2E.Card.Actor.theMpcpHolds')}</p>`,
      rolls,
    });
    return points;
  }

  /** Medic: the Medic utility's rating (+ Hacking Pool) vs a TN by the persona's damage; repairs Matrix boxes. */
  async runMedic(programId: string, opts: { poolDice?: number } = {}): Promise<SuccessTestResult | null> {
    if (!this.sys.derived?.matrix) {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.hasNoCyberdeckInUse', { name: escHtml(this.name) }));
      return null;
    }
    const prog: any = this.items.get(programId);
    if (!prog || prog.system.kind !== 'medic' || !prog.system.loaded || prog.system.erased || !(prog.system.rating > 0)) {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.needsALoadedMedicUtility', { name: escHtml(this.name) }));
      return null;
    }
    const before = (this.sys.matrix?.monitor as number | undefined) ?? 0;
    if (before <= 0) {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.sPersonaIsNotDamaged', { name: escHtml(this.name) }));
      return null;
    }
    const t = medicTarget(before);
    const md = RULES.MATRIX.medic;
    return this.#runTest(tx('SR2E.Card.Actor.personaDamage', { progName: prog.name, utilityRating: this.utilityRating(prog), level: t.level }), this.utilityRating(prog), {
      // v0.50.0: the utility's own rating rolls (not the decker's meat body), in the host's conditions: link, smoke, psyche.
      targetNumber: t.tn, poolDice: md.pool ? opts.poolDice ?? 0 : 0, pool: 'hacking', modifiers: this.matrixTestMods(undefined, { wounds: false }), noPenalties: true,
    }, { kind: 'medic', medic: { programId: prog.id, programName: prog.name, before } });
  }

  async #resolveMedic(snap: TestSnapshot): Promise<Resolved> {
    const md = snap.medic!;
    const r = medicRepair(md.before, snap.successes);
    const current = (this.sys.matrix?.monitor as number | undefined) ?? 0;
    const expected = md.after ?? md.before;
    let note = '';
    if (current === expected) await this.update({ 'system.matrix.monitor': r.after });
    else note = ` <em>${tx('SR2E.Card.Actor.theMatrixMonitorChangedSinceThis2', { after: r.after })}</em>`;
    let degraded = md.degraded ?? false;
    let wear = '';
    if (RULES.MATRIX.medic.degrades && !degraded) {
      const prog: any = this.items.get(md.programId);
      if (prog) {
        await prog.update({ 'system.rating': Math.max(0, (prog.system.rating ?? 0) - 1) });
        wear = tx('SR2E.Card.Actor.dropsToRating', { mdProgramName: md.programName, progRating: prog.system.rating });
      }
      degraded = true;
    }
    const html = `<p>${tx('SR2E.Card.Actor.persona', { part: r.repaired ? `${tx('SR2E.Card.Actor.repairs')} <strong>${escText(plural(r.repaired, 'box'))}</strong>` : tx('SR2E.Card.Actor.noRepair2'), after: r.after, matrixMonitorBoxes: RULES.MATRIX.monitorBoxes, wear: escText(wear), note })}</p>`;
    return { html, flags: {}, snap: { ...snap, medic: { ...md, after: r.after, degraded } } };
  }

  /** Repair a damaged deck (MPCP first): the repair skill vs RULES.MATRIX.repair.tn. */
  async repairDeckTest(opts: { deckId?: string | null; poolDice?: number } = {}): Promise<SuccessTestResult | null> {
    const deck: any = opts.deckId ? this.items.get(opts.deckId) : this.activeDeck();
    if (!deck || deck.type !== 'cyberdeck') {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.hasNoCyberdeckToRepair', { name: escHtml(this.name) }));
      return null;
    }
    const before: DeckDamage = { ...NO_DECK_DAMAGE, ...(deck.system.damage ?? {}) };
    if (!Object.values(before).some((v) => v > 0)) {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.isNotDamaged', { deckName: escHtml(deck.name) }));
      return null;
    }
    const rp = RULES.MATRIX.repair;
    const skill = rp.skills.map((n) => this.findSkill(n)).find((x) => x && (x.system?.rating ?? 0) > 0);
    const sd = this.#skillDice(skill, false, null, 'intelligence');
    return this.#runTest(tx('SR2E.Card.Actor.repair3', { deckName: deck.name, part: skill ? ` (${skill.name})` : '', sdSuffix: sd.suffix }), sd.dice, {
      targetNumber: rp.tn, modifiers: sd.modifiers, poolDice: 0,
    }, { kind: 'repair', repair: { deckId: deck.id, deckName: deck.name, before } });
  }

  async #resolveRepair(snap: TestSnapshot): Promise<Resolved> {
    const rp = snap.repair!;
    const r = repairDeck(rp.before, snap.successes);
    const deck: any = this.items.get(rp.deckId);
    const current: DeckDamage = { ...NO_DECK_DAMAGE, ...(deck?.system?.damage ?? {}) };
    const expected = rp.after ?? rp.before;
    const same = (Object.keys(NO_DECK_DAMAGE) as Array<keyof DeckDamage>).every((k) => current[k] === expected[k]);
    let note = '';
    const hours = r.repaired * RULES.MATRIX.repair.hoursPerPoint;
    // v0.81.0 (D3-4): a re-roll that now repairs nothing drops the project (as the other timed tests do).
    if (rp.projectId && r.repaired <= 0) return { html: `<p>${tx('SR2E.Card.Actor.noRepair', { value: await this.dropProjectOnFailure(rp.projectId) })}</p>`, flags: {}, snap: { ...snap, repair: { ...rp, projectId: undefined } } };
    // v0.65.0: the repair takes its hours: the deck stays damaged until the work is done (a re-roll changes the result).
    if (rp.projectId || (deck && same && r.repaired > 0 && hours > 0 && this.waitsFor('repairs'))) {
      const p = this.projects().find((x) => x.id === rp.projectId);
      // What comes off each part (damage taken meanwhile stays).
      const off = Object.fromEntries(Object.keys(NO_DECK_DAMAGE).map((k) => [k, Math.max(0, Number((rp.before as any)[k] ?? 0) - Number((r.after as any)[k] ?? 0))]));
      const effect: ProjectEffect = { call: { method: 'finishDeckRepair', args: [rp.deckId, off] } };
      let id = p?.id;
      if (p) await this.update({ [`flags.${SYSTEM_ID}.projects.${p.id}`]: { ...retimed(p, hours), effect } });
      else if (!rp.projectId) id = (await this.startProject({ kind: 'repair', area: 'repairs', label: tx('SR2E.Text.Actor.repairing', { name: rp.deckName }), hours, effect })).id;
      else return { html: `<p><em>${tx('SR2E.Card.Actor.theRepairIsOverOrWas')}</em></p>`, flags: {}, snap };
      return { html: `<p>${tx('SR2E.Card.Actor.repairing')} <strong>${tCount(r.repaired, 'SR2E.Card.Actor.points')}</strong> ${tCount(hours, 'SR2E.Card.Actor.ofReadyAfterHoursOfWork', { rpDeckName: escText(rp.deckName) })}</p>`, flags: {}, snap: { ...snap, repair: { ...rp, projectId: id } } };
    }
    if (deck && same) await deck.update({ 'system.damage': r.after });
    else note = ` <em>${tx('SR2E.Card.Actor.theDeckChangedSinceThisWas')}</em>`;
    const left = Object.entries(r.after).filter(([, v]) => v > 0).map(([k, v]) => `${k === 'mpcp' ? tx('SR2E.Card.Actor.mpcp2') : cap(k)} −${v}`).join(', ');
    const html = `<p>${r.repaired ? `${tx('SR2E.Card.Actor.repairs')} <strong>${tCount(r.repaired, 'SR2E.Card.Actor.points')}</strong> ${tCount(hours, 'SR2E.Card.Actor.hoursOfWork')}` : tx('SR2E.Card.Actor.noRepair2')}. ${left ? tx('SR2E.Card.Actor.stillDamaged', { left: escText(left) }) : tx('SR2E.Card.Actor.isFullyRepaired', { rpDeckName: escText(rp.deckName) })}${note}</p>`;
    return { html, flags: {}, snap: { ...snap, repair: { ...rp, after: r.after } } };
  }

  /** A trace on this decker: who, and Combat Turns (or seconds) left; null without one. */
  traceStatus(): { icName: string; mode: string; turnsLeft: number | null; secondsLeft: number | null } | null {
    const t = this.sys.matrix?.trace;
    if (!t?.active) return null;
    const combat: any = (game as any).combat;
    const turnsLeft = t.round >= 0 && combat?.started ? Math.max(0, t.round - Number(combat.round ?? 0)) : null;
    const secondsLeft = t.worldTime >= 0 ? Math.max(0, t.worldTime - sysNow()) : null;
    return { icName: t.icName, mode: t.mode, turnsLeft, secondsLeft };
  }

  /** GM: complete traces that are due (a Combat Turn reached, or the world time passed); drop lost ones. */
  static async matrixTraces(now: { round?: number | null; worldTime?: number; anyGm?: boolean; combatId?: string | null } = {}): Promise<void> {
    // v0.57.0 (every client): utilities that have finished loading count in the derived values (Detection Factor, Armor…) and the sheet.
    for (const a of SR2Actor.tickActors().filter((x: any) => (x.system?.derived?.matrix?.loading ?? []).length)) {
      if ((a.system.derived.matrix.loading as string[]).some((id) => SR2Actor.programReady(a.items?.get?.(id)))) {
        try { (a as any).prepareData?.(); if ((a as any).sheet?.rendered) (a as any).sheet.render(false); } catch { /* stubs */ }
      }
    }
    if (!(game as any).user?.isGM) return;
    const active = (game as any).users?.activeGM;
    if (!now.anyGm && active && !isLeadGm()) return;
    const time = now.worldTime ?? sysNow();
    for (const a of allActors().filter((x: any) => x.system?.matrix?.trace?.active)) {
      const t = a.system.matrix.trace;
      if (!a.isJackedIn?.()) {
        await a.update({ 'system.matrix.trace': { ...t, active: false } });
        continue;
      }
      const ic: any = t.icUuid ? fromUuidSync(t.icUuid) : null;
      // A security decker's trace is lost when they jack out (v0.40.0).
      const gone = !ic || (ic.type === 'ic' ? ic.system?.derived?.crashed : !ic.isJackedIn?.());
      if (gone) {
        await a.update({ 'system.matrix.trace': { ...t, active: false } });
        await ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor: a }), content: ic && ic.type !== 'ic' ? `<p>${tx('SR2E.Card.Actor.hasJackedOutTheirTraceOn', { icName: escText(t.icName), name: escText(a.name) })}</p>` : `<p>${tx('SR2E.Card.Actor.isGoneItsTraceOnIs', { icName: escText(t.icName), name: escText(a.name) })}</p>` });
        continue;
      }
      if (!traceComplete(t, { round: now.round ?? null, worldTime: time, ...(now.combatId !== undefined ? { combatId: now.combatId } : {}) })) continue;
      await (a as SR2Actor).#completeTrace();
    }
    // v0.57.0: hosts that shut down dump everyone inside when it comes due.
    await SR2Actor.hostShutdowns({ round: now.round ?? null, worldTime: time, ...(now.combatId !== undefined ? { combatId: now.combatId } : {}) });
  }

  // ---------------------------------------------------------------- Matrix (v0.57.0)

  /** v0.57.0: the Detection Factor now (a Sleaze that finished loading counts at once). */
  liveDetectionFactor(): number {
    const m = this.sys.derived?.matrix;
    if (!m) return 2;
    return detectionFactor(Number(m.masking ?? 0), this.utilityRating(this.bestUtility('sleaze')));
  }

  /** v0.57.0: whether a loaded utility has finished loading into active memory. */
  static programReady(p: any): boolean {
    const l = p?.system?.loading;
    const r = Number(l?.round ?? -1), w = Number(l?.worldTime ?? -1);
    if (r < 0 && w < 0) return true;
    return loadingDone({ round: r, worldTime: w, combatId: String(l?.combatId ?? '') }, SR2Actor.matrixNow());
  }

  /** v0.57.0: how long a loading utility still takes (null when ready). */
  static loadingLeft(p: any): { turns: number | null; seconds: number | null } | null {
    if (!p?.system?.loaded || SR2Actor.programReady(p)) return null;
    const l = p.system.loading;
    const now = SR2Actor.matrixNow();
    return {
      turns: Number(l.round) >= 0 && now.round != null ? Math.max(0, Number(l.round) - now.round) : null,
      seconds: Number(l.worldTime) >= 0 ? Math.max(0, Number(l.worldTime) - now.worldTime) : null,
    };
  }

  /**
   * v0.57.0 (Swap Memory): load a utility into active memory or unload it. Jacked in, loading takes
   * size ÷ load speed Combat Turns and an action (RULES.MATRIX_V57.loading); unloading is instant.
   */
  async swapProgram(programId: string, load: boolean): Promise<boolean> {
    const p: any = this.items.get(programId);
    if (!p || p.type !== 'program') return false;
    if (load && p.system.erased) {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.hasBeenErasedRestoreItFirst', { name: escHtml(p.name) }));
      return false;
    }
    if (Boolean(p.system.loaded) === load) return true;
    const deck: any = this.activeDeck();
    // v0.71.0 (R8): it has to fit in active memory (RULES.FIXES_V71.activeMemory 'block'); R7: say if it runs capped.
    if (load) {
      const m = this.sys.derived?.matrix;
      const fit = canLoadProgram({ activeMemory: Number(m?.activeMemory ?? deck?.system?.activeMemory ?? 0), programs: this.programs().map((i: any) => ({ id: i.id, name: i.name, ...i.system })) }, { id: p.id, name: p.name, ...p.system });
      if (!fit.ok) { ui.notifications?.warn?.(escHtml(fit.reason ?? tx('SR2E.Notify.Actor.doesnTFitInActiveMemory', { name: p.name }))); return false; }
      if (fit.reason) ui.notifications?.info?.(escHtml(fit.reason));
      const run = this.utilityRating(p);
      if (run < Number(p.system.rating ?? 0)) ui.notifications?.info?.(tx('SR2E.Notify.Actor.ratingRunsAtTheMpcpLimits', { name: escHtml(p.name), rating: escHtml(p.system.rating), run }));
    }
    const size = p.system.complexForm && RULES.MATRIX.otaku.complexForms.noMemory ? 0 : programSize(p.system);
    const plan = swapMemoryPlan({ jackedIn: this.isJackedIn(), load, size, loadSpeed: deck ? loadSpeedOf(deck.system) : 0, now: SR2Actor.matrixNow() });
    if (!plan.instant && plan.action !== 'free' && !(await this.useAction(`matrix:${plan.action}`, tx('SR2E.Card.Actor.swappingMemory', { name: p.name })))) return false;
    await p.update({ 'system.loaded': load, 'system.loading': plan.due ?? { round: -1, worldTime: -1 } });
    if (!plan.instant) {
      const speed = deck ? loadSpeedOf(deck.system) : 0;
      await ChatMessage.create({
        speaker: ChatMessage.getSpeaker({ actor: this }),
        content: `<p><strong>${escText(this.name)}</strong> ${tx('SR2E.Card.Actor.swapsMemoryLoading')} <strong>${escText(p.name)}</strong> ${tx('SR2E.Card.Actor.mpAtMpPerCombatTurn', { size, speed })} <strong>${tCount(plan.turns, 'SR2E.Card.Actor.combatTurns')}</strong>${plan.due && plan.due.round >= 0 ? tx('SR2E.Card.Actor.combatTurn3', { dueRound: plan.due.round }) : ''}.</p>`,
      });
    }
    return true;
  }

  /** v0.57.0: begin a host's shutdown: everyone inside is dumped when it comes due (RULES.MATRIX_V57.shutdown). */
  static #shuttingDown = new Set<string>();
  static async startShutdown(host: any): Promise<void> {
    if (!RULES.MATRIX_V57.shutdown.enabled || host?.type !== 'host' || host.system.shutdown?.pending || SR2Actor.#shuttingDown.has(host.uuid)) return;
    SR2Actor.#shuttingDown.add(host.uuid);
    try { await SR2Actor.#beginShutdown(host); } finally { SR2Actor.#shuttingDown.delete(host.uuid); }
  }

  static async #beginShutdown(host: any): Promise<void> {
    const now = SR2Actor.matrixNow();
    const due = shutdownDue(now);
    try { await host.update({ 'system.shutdown': { pending: true, round: due.round, worldTime: due.worldTime, combatId: due.combatId ?? '' } }); } catch (err) { console.warn('sr2e | shutdown not started', err); ui.notifications?.warn?.(tx('SR2E.Notify.Actor.sShutdownCouldnTStartHere', { hostName: escHtml(host.name) })); return; }
    const turns = Number(RULES.MATRIX_V57.shutdown.turns);
    await ChatMessage.create({
      speaker: { alias: host.name },
      content: `<p><strong>${tx('SR2E.Card.Actor.shutsDown', { hostName: escText(host.name) })}</strong> ${turns > 0 ? tCount(turns, 'SR2E.Card.Actor.everyoneInsideIsDumpedInCombat', { part: due.round >= 0 ? tx('SR2E.Card.Actor.combatTurn3', { dueRound: due.round }) : ` (${turns * RULES.MATRIX_V57.shutdown.secondsPerTurn} s)` }) : tx('SR2E.Card.Actor.everyoneInsideIsDumped')}</p>`,
    });
    if (turns <= 0) await SR2Actor.#completeShutdown(host);
  }

  /** v0.57.0 (GM): shutdowns that have come due. */
  static async hostShutdowns(now: { round: number | null; worldTime: number; combatId?: string | null }): Promise<void> {
    if (!(game as any).user?.isGM) return;
    for (const h of allActors().filter((x: any) => x.type === 'host' && x.system?.shutdown?.pending)) {
      const s = h.system.shutdown;
      if (loadingDone({ round: Number(s.round), worldTime: Number(s.worldTime), combatId: String(s.combatId ?? '') }, now)) await SR2Actor.#completeShutdown(h);
    }
  }

  /** v0.57.0 (GM): dump everyone in a host now (the host sheet's button). */
  static async dumpHost(host: any): Promise<void> {
    if (host?.type === 'host') await SR2Actor.#completeShutdown(host);
  }

  /** v0.57.0: a shutdown completes: every persona in the host is dumped (dump shock), frames and agents fall off to the parent grid. */
  static async #completeShutdown(host: any): Promise<void> {
    await host.update({ 'system.shutdown': { pending: false, round: -1, worldTime: -1 } });
    const names: string[] = [];
    for (const a of SR2Actor.tickActors().filter((x: any) => x.isJackedIn?.() && (x.system?.matrix?.hostUuid ?? '') === host.uuid)) {
      await (a as SR2Actor).#dumped(host, tx('SR2E.Card.Actor.shutsDown2', { hostName: host.name }));
      names.push(a.name as string);
    }
    for (const f of allActors().filter((x: any) => x.type === 'ic' && ['frame', 'agent'].includes(x.system?.kind) && x.system.hostUuid === host.uuid)) {
      await f.update({ 'system.hostUuid': host.system.parentUuid ?? '' });
      names.push(f.name as string);
    }
    const gms = [...((game as any).users ?? [])].filter((u: any) => u.isGM).map((u: any) => u.id);
    await ChatMessage.create({ speaker: { alias: host.name }, whisper: gms, content: `<p><em>${tx('SR2E.Card.Actor.gmOnly')}</em> · <strong>${tx('SR2E.Card.Actor.isDown', { hostName: escText(host.name) })}</strong> ${names.length ? tx('SR2E.Card.Actor.dumped', { names: names.map(escText).join(', ') }) : tx('SR2E.Card.Actor.nobodyWasInside')}</p>` });
  }

  /** v0.57.0: this decker is dumped from the Matrix (a shutdown): the run ends and dump shock follows; hitchers feel it too. */
  async #dumped(host: any, why: string): Promise<void> {
    await this.update({ 'system.matrix.jackedIn': false, 'system.matrix.hostUuid': '', ...this.#endRunUpdate() });
    await this.#dumpFollowUps(host, why, true);
  }

  /**
   * What follows a decker being dumped (already jacked out): the dump shock card (`card`), the hitchers' shock, and
   * everyone riding them unplugged. v0.81.0 (D3-6): shared by a shutdown and a jam.
   */
  async #dumpFollowUps(host: any, why: string, card: boolean): Promise<void> {
    const tn = (host?.system?.securityValue as number | undefined) ?? RULES.MATRIX.dumpShockTn;
    const level = dumpShockLevel(String(host?.system?.securityCode ?? ''));
    const none = this.isTortoise() && !RULES.MATRIX.tortoise.dumpShock;
    if (card) {
      await ChatMessage.create({
        speaker: ChatMessage.getSpeaker({ actor: this }),
        content: `<p><strong>${escText(why)}:</strong> ${tx('SR2E.Card.Actor.isDumpedFromTheMatrix', { name: escText(this.name) })}</p><p>${none ? tx('SR2E.Card.Actor.aTortoiseNoDumpShock') : `<button type="button" data-sr2e-action="dumpShock">${tx('SR2E.Card.Actor.resistDumpShockWillpowerVs2', { tn, level })}</button>`}</p>`,
        flags: { [SYSTEM_ID]: { dumpShockFor: this.uuid, dumpShockTn: tn, dumpShockLevel: level } },
      });
    }
    await this.#hitcherShock(tn, level);
    await this.#unhitchAll();
  }

  /** v0.57.0: everyone riding this decker's hitcher jacks. */
  hitchers(): any[] {
    return SR2Actor.tickActors().filter((a: any) => a !== this && (a.system?.matrix?.ridingWith ?? '') === this.uuid);
  }

  /** v0.57.0: dump shock reaches the hitchers too (RULES.MATRIX_V57.hitchers.dumpShock). */
  async #hitcherShock(tn: number, level: DamageLevel): Promise<void> {
    if (!RULES.MATRIX_V57.hitchers.dumpShock) return;
    for (const h of this.hitchers()) {
      await ChatMessage.create({
        speaker: ChatMessage.getSpeaker({ actor: h }),
        content: `<p>${tx('SR2E.Card.Actor.ridesSHitcherJackAndFeels', { name: escText(h.name), name2: escText(this.name) })}</p><p><button type="button" data-sr2e-action="dumpShock">${tx('SR2E.Card.Actor.resistDumpShockWillpowerVs2', { tn, level })}</button></p>`,
        flags: { [SYSTEM_ID]: { dumpShockFor: h.uuid, dumpShockTn: tn, dumpShockLevel: level } },
      });
    }
  }

  /** v0.57.0: unplug everyone riding this decker (when they jack out or are dumped). */
  async #unhitchAll(): Promise<void> {
    for (const h of this.hitchers()) {
      try { await h.update({ 'system.matrix.ridingWith': '' }); } catch (err) { console.warn('sr2e | unhitch', err); await ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor: h }), whisper: [...((game as any).users ?? [])].filter((u: any) => u.isGM).map((u: any) => u.id), content: `<p><em>${tx('SR2E.Card.Actor.gmOnly')}</em> ${tx('SR2E.Card.Actor.stillRidesSHitcherJackUnplug', { name: escText(h.name), name2: escText(this.name) })}</p>` }); }
    }
  }

  /** v0.57.0: plug into a decker's hitcher jack (or unplug: null). */
  async rideWith(deckerUuid: string | null): Promise<boolean> {
    if (!deckerUuid) {
      await this.update({ 'system.matrix.ridingWith': '' });
      return true;
    }
    const d: any = fromUuidSync(deckerUuid);
    const deck: any = d?.activeDeck?.();
    if (!d || d === this || !deck) {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.pickADeckerWithACyberdeck'));
      return false;
    }
    const room = hitcherRoom(deck.system, (d.hitchers?.() ?? []).filter((h: any) => h !== this).length);
    if (room.free <= 0) {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.sHas', { name: escHtml(d.name), deckName: escHtml(deck.name), part: room.capacity ? tx('SR2E.Notify.Actor.onlyHitcherJackAllInUse', { roomCapacity: tCount(room.capacity, 'SR2E.Count.hitcherJack') }) : tx('SR2E.Notify.Actor.noHitcherJacks') }));
      return false;
    }
    await this.update({ 'system.matrix.ridingWith': d.uuid });
    await ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor: this }), content: `<p>${tx('SR2E.Card.Actor.plugsIntoSHitcherJackAnd', { name: escText(this.name), name2: escText(d.name) })}</p>` });
    return true;
  }

  /**
   * v0.57.0: a deck's reality filter on entering a host: MPCP vs the host's Security Value. It works
   * (+Matrix Reaction and Hacking Pool there) or fights the host's sculpting (+TN there).
   */
  async realityFilterCheck(host: any): Promise<void> {
    const deck: any = this.activeDeck();
    if (!deck?.system?.realityFilter || host?.type !== 'host' || (host.system.gridKind ?? 'host') !== 'host') return;
    if ((this.sys.matrix?.filter?.hostUuid ?? '') === host.uuid) return;
    const t = realityFilterTest(Number(this.sys.derived?.matrix?.mpcp ?? deck.system.mpcp ?? 0), Number(host.system.securityValue ?? 0));
    const rolls: any[] = [];
    const r = await successTest({ dice: t.dice, targetNumber: t.tn, roll: foundryRoller(rolls) });
    const ok = r.successes > 0;
    await this.update({ 'system.matrix.filter': { hostUuid: host.uuid, ok: ok ? 1 : 0 } });
    const f = RULES.MATRIX_V57.realityFilter;
    await ChatMessage.create(withRollMode({
      speaker: ChatMessage.getSpeaker({ actor: this }), rolls,
      content: `${describeResult(tx('SR2E.Card.Actor.sRealityFilterMpcpVsS', { deckName: deck.name, dice: t.dice, hostName: host.name, tn: t.tn }), r)}<p>${ok ? `<strong>${tx('SR2E.Card.Actor.theFilterHolds')}</strong> ${tx('SR2E.Card.Actor.matrixReactionAndHackingPoolIn', { reaction: f.reaction, pool: f.pool, hostName: escText(host.name) })}` : `<strong>${tx('SR2E.Card.Actor.theFilterFightsTheHostS')}</strong> ${tx('SR2E.Card.Actor.tnOnMatrixTestsIn', { failTn: f.failTn, hostName: escText(host.name) })}`}</p>`,
    }));
  }

  /**
   * v0.57.0: Matrix perception: Locate Decker, Locate IC or Analyze Icon (RULES.MATRIX_V57.perception).
   * Sensors (or Computer) + Hacking Pool vs the target's Detection Factor, Masking or rating; Lock-On helps.
   */
  async matrixPerception(kind: PerceptionKind, targetUuid: string, opts: { poolDice?: number; modifiers?: TargetNumberModifier[] } = {}): Promise<SuccessTestResult | null> {
    if (!this.isJackedIn()) {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.isNotJackedIn', { name: escHtml(this.name) }));
      return null;
    }
    if (!this.#arrived() || !this.#linkOk()) return null;
    const target: any = await fromUuid(targetUuid);
    const tk = target?.type === 'ic' ? (target.system.kind === 'frame' ? 'frame' : target.system.kind === 'agent' ? 'agent' : 'ic') : target?.isJackedIn?.() ? 'persona' : null;
    if (!target || !tk) {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.pickAnIconInTheMatrix'));
      return null;
    }
    const m = this.sys.derived.matrix;
    const lockOn = this.utilityRating(this.bestUtility('lock-on'));
    const tm = target.system?.derived?.matrix;
    const t = perceptionTarget(kind, { kind: tk, name: target.name, detectionFactor: target.liveDetectionFactor?.() ?? tm?.detectionFactor, masking: tm?.masking, rating: Number(target.system?.rating ?? 0) }, lockOn);
    const pd = perceptionDice({ sensors: Number(m?.sensors ?? 0), computer: Number(this.findSkill(RULES.MATRIX.skill)?.system?.rating ?? 0) });
    const labels: Record<PerceptionKind, string> = { locateDecker: tx('SR2E.Card.Actor.locateDecker'), locateIc: tx('SR2E.Card.Actor.locateIc'), analyzeIcon: tx('SR2E.Card.Actor.analyzeIcon') };
    return this.#runTest(tx('SR2E.Card.Actor.vs5', { labels: labels[kind], targetName: target.name, pdLabel: pd.label, label: t.label, tn: t.tn }), pd.dice, {
      targetNumber: t.tn, poolDice: RULES.MATRIX_V57.perception.pool ? (opts.poolDice ?? 0) : 0, pool: 'hacking',
      modifiers: [...t.modifiers, ...(opts.modifiers ?? []), ...this.matrixTestMods()],
    }, { kind: 'mperceive', mperceive: { kind, targetUuid: target.uuid, targetName: target.name } });
  }

  /** v0.57.0 (IC): find a decker who broke contact with it again: its rating vs their Detection Factor. */
  async icLocate(targetUuid: string): Promise<SuccessTestResult | null> {
    if (this.type !== 'ic' || this.sys.derived?.crashed) return null;
    const target: any = await fromUuid(targetUuid);
    if (!target?.isJackedIn?.()) {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.pickAJackedInDecker'));
      return null;
    }
    const host: any = this.sys.hostUuid ? fromUuidSync(this.sys.hostUuid) : null;
    const t = perceptionTarget('locateDecker', { kind: 'persona', name: target.name, detectionFactor: target.liveDetectionFactor?.() ?? target.system.derived?.matrix?.detectionFactor ?? 4 });
    const atk = icAttackDiceFor({ rating: Number(this.sys.rating ?? 0), securityValue: Number(host?.system?.securityValue ?? 0) });
    return this.#runTest(tx('SR2E.Card.Actor.looksForVs', { name: this.name, targetName: target.name, atkNote: atk.note || tx('SR2E.Card.Actor.rating11', { atkDice: atk.dice }), label: t.label, tn: t.tn }), atk.dice, {
      targetNumber: t.tn, modifiers: [...SR2Actor.smokeMods(host), ...matrixWoundModifiers(Number(this.sys.matrix?.monitor ?? 0), { ic: true })],
    }, { kind: 'mperceive', mperceive: { kind: 'locateDecker', targetUuid: target.uuid, targetName: target.name, byIc: true } });
  }

  async #resolvePerception(snap: TestSnapshot): Promise<Resolved> {
    const p = snap.mperceive!;
    const s = snap.successes;
    const target: any = fromUuidSync(p.targetUuid);
    if (s <= 0) return { html: `<p><strong>${p.byIc ? tx('SR2E.Card.Actor.canTFind', { name: escText(this.name), targetName: escText(p.targetName) }) : tx('SR2E.Card.Actor.isNotFound', { targetName: escText(p.targetName) })}.</strong></p>`, flags: {}, snap };
    if (p.byIc) {
      // The decker's evasion against this IC is over.
      if (!p.applied && target) {
        const list = (target.system?.matrix?.maneuvers ?? []).filter((m: any) => !(m.kind === 'evade' && m.targetUuid === this.uuid));
        try { await target.update({ 'system.matrix.maneuvers': list }); } catch { /* the GM's client runs IC */ }
      }
      return { html: `<p><strong>${tx('SR2E.Card.Actor.findsAgain', { name: escText(this.name), targetName: escText(p.targetName) })}</strong></p>`, flags: {}, snap: { ...snap, mperceive: { ...p, applied: true } } };
    }
    if (p.kind !== 'analyzeIcon') return { html: `<p><strong>${tx('SR2E.Card.Actor.located2', { targetName: escText(p.targetName) })}</strong> (${escText(plural(s, 'success'))}).</p>`, flags: {}, snap };
    const reveals = analyzeReveals(s);
    const out: string[] = [];
    const ts: any = target?.system;
    const isIc = target?.type === 'ic';
    for (const r of reveals) {
      if (r === 'kind') out.push(isIc ? `${ts.kind === 'ic' ? tx('SR2E.Card.Actor.ic', { tsCategory: escText(cap(ts.category)), part: ts.icType ? ` (${escText(ts.icType)})` : '' }) : escText(cap(ts.kind))}` : tx('SR2E.Card.Actor.aPersona', { matrixDeckName: escText(ts?.derived?.matrix?.deckName ?? tx('SR2E.Card.Actor.cyberdeck')) }));
      if (r === 'rating') out.push(isIc ? tx('SR2E.Card.Actor.rating8', { tsRating: ts.rating }) : tx('SR2E.Card.Actor.mpcp3', { matrixMpcp: ts?.derived?.matrix?.mpcp ?? '?' }));
      if (r === 'state') out.push(tx('SR2E.Card.Actor.matrixDamage4', { matrixMonitor: ts?.matrix?.monitor ?? 0, matrixMonitorBoxes: RULES.MATRIX.monitorBoxes }));
      if (r === 'details') out.push(isIc
        ? `${escText(IC_BEHAVIOR_LABELS[ts.behavior as IcBehavior] ?? ts.behavior)}${ts.guards ? tx('SR2E.Card.Actor.guards', { tsGuards: escText(cap(ts.guards)) }) : ''}`
        : tx('SR2E.Card.Actor.bodEvasionMaskingSensorsLoaded', { matrixBod: ts?.derived?.matrix?.bod ?? '?', matrixEvasion: ts?.derived?.matrix?.evasion ?? '?', matrixMasking: ts?.derived?.matrix?.masking ?? '?', matrixSensors: ts?.derived?.matrix?.sensors ?? '?', filter: (target?.programs?.() ?? []).filter((x: any) => x.system.loaded && !x.system.erased).map((x: any) => escText(x.name)).join(', ') || tx('SR2E.Card.Actor.nothing') }));
    }
    return { html: `<p><strong>${escText(p.targetName)}:</strong> ${out.join('; ')}.</p>`, flags: {}, snap };
  }

  /**
   * v0.57.0: a cybercombat maneuver (RULES.MATRIX_V57.maneuvers): position (−TN on the next attack
   * on them), parry (+TN on their attacks on this decker) or evade (break contact). Opposed: Evasion
   * (+ Hacking Pool, Cloak helps) against the opponent's Sensors (IC: rating; Lock-On helps them).
   */
  async matrixManeuver(kind: ManeuverKind, targetUuid: string, opts: { poolDice?: number; modifiers?: TargetNumberModifier[] } = {}): Promise<SuccessTestResult | null> {
    if (!RULES.MATRIX_V57.maneuvers.enabled) return null;
    if (!this.isJackedIn()) {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.isNotJackedIn', { name: escHtml(this.name) }));
      return null;
    }
    if (!this.#arrived() || !this.#linkOk()) return null;
    const target: any = await fromUuid(targetUuid);
    const ic = target?.type === 'ic';
    if (!target || target === this || (!ic && !target.isJackedIn?.())) {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.pickAnOpponentInTheMatrix'));
      return null;
    }
    const m = this.sys.derived.matrix;
    const tm = target.system?.derived?.matrix;
    const sides = maneuverSides({
      evasion: Number(m?.evasion ?? 0), cloak: this.utilityRating(this.bestUtility('cloak')),
      opponent: { ic, rating: Number(target.system?.rating ?? 0), sensors: Number(tm?.sensors ?? 0), lockOn: ic ? 0 : Number(target.bestUtility?.('lock-on')?.system?.rating ?? 0) },
    });
    const host: any = this.currentHost();
    const oppRolls: any[] = [];
    const opp = await successTest({ dice: sides.theirs.dice, targetNumber: sides.theirs.tn, modifiers: [...sides.theirs.modifiers, ...SR2Actor.smokeMods(host), ...matrixWoundModifiers(Number(target.system?.matrix?.monitor ?? 0), { ic })], roll: foundryRoller(oppRolls) });
    const labels: Record<ManeuverKind, string> = { position: tx('SR2E.Card.Actor.position'), parry: tx('SR2E.Card.Actor.parry2'), evade: tx('SR2E.Card.Actor.evade') };
    return this.#runTest(tx('SR2E.Card.Actor.maneuverAgainstEvasionVsRollsVs', { labels: labels[kind], targetName: target.name, mineDice: sides.mine.dice, part: ic ? tx('SR2E.Card.Actor.rating10') : tx('SR2E.Card.Actor.sensors'), mineTn: sides.mine.tn, theirsDice: sides.theirs.dice, theirsTn: sides.theirs.tn, plural: plural(opp.successes, 'success') }), sides.mine.dice, {
      targetNumber: sides.mine.tn, poolDice: RULES.MATRIX_V57.maneuvers.pool ? (opts.poolDice ?? 0) : 0, pool: 'hacking',
      modifiers: [...sides.mine.modifiers, ...(opts.modifiers ?? []), ...this.matrixTestMods(host)],
    }, { kind: 'maneuver', maneuver: { kind, targetUuid: target.uuid, targetName: target.name, opp: opp.successes } });
  }

  /** A maneuver's outcome; a Karma re-roll replaces the entry it left (or takes it away). */
  async #resolveManeuver(snap: TestSnapshot): Promise<Resolved> {
    const mv = snap.maneuver!;
    const o = maneuverOutcome(mv.kind, snap.successes, mv.opp);
    const now = SR2Actor.matrixNow();
    const same = (e: any) => mv.entry && e.kind === mv.entry.kind && e.targetUuid === mv.entry.targetUuid && e.round === mv.entry.round && e.worldTime === mv.entry.worldTime;
    let list: Maneuver[] = activeManeuvers(this.sys.matrix?.maneuvers ?? [], now).filter((e) => !same(e));
    let entry: Maneuver | null = null;
    const up: Record<string, unknown> = {};
    const engaged: string[] = [...(this.sys.matrix?.engagedBy ?? [])];
    let freed = Boolean(mv.freed);
    if (o.won) {
      entry = maneuverEntry(mv.kind, mv.targetUuid, o.net, now);
      list = [...list.filter((e) => !(e.kind === mv.kind && e.targetUuid === mv.targetUuid)), entry];
      if (o.frees && engaged.includes(mv.targetUuid)) { up['system.matrix.engagedBy'] = engaged.filter((u) => u !== mv.targetUuid); freed = true; }
    } else if (freed && !engaged.includes(mv.targetUuid)) {
      // A re-roll that loses after all: the IC holds them again.
      up['system.matrix.engagedBy'] = [...engaged, mv.targetUuid];
      freed = false;
    }
    up['system.matrix.maneuvers'] = list;
    await this.update(up);
    const vs = tx('SR2E.Card.Actor.vs6', { successes: snap.successes, mvOpp: mv.opp });
    const what = !o.won ? `<strong>${tx('SR2E.Card.Actor.keepsUp', { mvTargetName: escText(mv.targetName) })}</strong> (${vs}).`
      : mv.kind === 'position' ? `<strong>${tx('SR2E.Card.Actor.gainsPosition', { name: escText(this.name) })}</strong> ${tx('SR2E.Card.Actor.onTnOnTheNextAttack', { mvTargetName: escText(mv.targetName), vs, tn: o.tn })}`
      : mv.kind === 'parry' ? `<strong>${tx('SR2E.Card.Actor.parries', { name: escText(this.name) })}</strong> ${tx('SR2E.Card.Actor.tnOnTheirAttacksOn', { mvTargetName: escText(mv.targetName), vs, tn: o.tn, name: escText(this.name) })}`
      : `<strong>${tx('SR2E.Card.Actor.breaksContact', { name: escText(this.name) })}</strong> ${tx('SR2E.Card.Actor.with4', { mvTargetName: escText(mv.targetName), vs, part: RULES.MATRIX_V57.maneuvers.evadeBlocks ? tx('SR2E.Card.Actor.itMustFindThemAgainBefore') : '' })}`;
    return { html: `<p>${what}</p>`, flags: {}, snap: { ...snap, maneuver: { ...mv, entry, freed } } };
  }

  /**
   * v0.57.0: run a Slow or Restore utility (RULES.MATRIX_V57.utilities). Slow: Computer + Hacking Pool
   * vs an IC's rating, taking Initiative off it. Restore: its rating + Hacking Pool vs the TN,
   * restoring crippled persona points (and deck damage when the house rule allows).
   */
  async useUtility(programId: string, opts: { targetUuid?: string | null; poolDice?: number; modifiers?: TargetNumberModifier[] } = {}): Promise<SuccessTestResult | null> {
    const p: any = this.items.get(programId);
    if (!p || !['slow', 'restore'].includes(p.system.kind) || !p.system.loaded || p.system.erased || !SR2Actor.programReady(p)) {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.pickALoadedSlowOrRestore'));
      return null;
    }
    if (!this.isJackedIn()) {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.isNotJackedIn', { name: escHtml(this.name) }));
      return null;
    }
    if (!this.#arrived() || !this.#linkOk()) return null;
    const rating = this.utilityRating(p);
    if (p.system.kind === 'slow') {
      const target: any = opts.targetUuid ? await fromUuid(opts.targetUuid) : null;
      if (target?.type !== 'ic' || target.system?.derived?.crashed) {
        ui.notifications?.warn?.(tx('SR2E.Notify.Actor.pickAnIcNotDerezzedTo'));
        return null;
      }
      const own = this.#matrixDice();
      return this.#runTest(tx('SR2E.Card.Actor.slowOnTnItsRating', { name: p.name, rating, targetName: target.name, targetRating: target.system.rating, ownSuffix: own.suffix }), own.dice, {
        targetNumber: Number(target.system.rating ?? 4), poolDice: opts.poolDice ?? 0, pool: 'hacking',
        modifiers: [...(opts.modifiers ?? []), ...this.#maneuverMods(target), ...this.matrixTestMods(), ...own.modifiers],
      }, { kind: 'mutility', mutility: { kind: 'slow', programId: p.id, programName: p.name, rating, targetUuid: target.uuid, targetName: target.name } });
    }
    const cfg = RULES.MATRIX_V57.utilities.restore;
    const deck: any = this.activeDeck();
    const before = { crippled: { ...NO_DECK_DAMAGE, ...(this.sys.matrix?.crippled ?? {}) }, deck: { ...NO_DECK_DAMAGE, ...(deck?.system?.damage ?? {}) } };
    return this.#runTest(tx('SR2E.Card.Actor.restoreVs', { name: p.name, rating, cfgTn: cfg.tn }), rating, {
      targetNumber: cfg.tn, poolDice: cfg.pool ? (opts.poolDice ?? 0) : 0, pool: 'hacking', modifiers: [...(opts.modifiers ?? []), ...this.matrixTestMods()],
    }, { kind: 'mutility', mutility: { kind: 'restore', programId: p.id, programName: p.name, rating, before, ...(deck?.id ? { deckId: deck.id as string } : {}) } });
  }

  async #resolveUtility(snap: TestSnapshot): Promise<Resolved> {
    const u = snap.mutility!;
    const s = snap.successes;
    if (u.kind === 'slow') {
      const e = slowEffect(s, u.rating);
      const done = u.applied ?? 0;
      const delta = e.initiative - done;
      // v0.81.0 (D3-2): the target's own combatant (an unlinked token's actor id is its base actor's).
      const tgt: any = fromUuidSync(u.targetUuid ?? '');
      const c: any = tgt?.myCombatant?.() ?? null;
      let note = '';
      let applied = done;
      if (delta && c && c.initiative != null) {
        try {
          if (notWritableNow(c)) throw new Error('not owner');
          await c.update({ initiative: Number(c.initiative) - delta });
          applied = e.initiative;
        } catch { note = ` <em>${tx('SR2E.Card.Actor.gmItsInitiativeByByHand', { part: delta > 0 ? tx('SR2E.Card.Actor.lower') : tx('SR2E.Card.Actor.raise'), delta: Math.abs(delta) })}</em>`; }
      } else if (e.initiative && !c) note = ` <em>${tx('SR2E.Card.Actor.itIsNotInACombat')}</em>`;
      const html = e.initiative ? `<p><strong>${tx('SR2E.Card.Actor.isSlowed', { targetName: escText(u.targetName ?? tx('SR2E.Card.Actor.theIc')) })}</strong> ${tx('SR2E.Card.Actor.initiativeNetAtMostTheSlow', { initiative: e.initiative, net: e.net, rating: u.rating, note })}</p>` : `<p><strong>${tx('SR2E.Card.Actor.isNotSlowed', { targetName: escText(u.targetName ?? tx('SR2E.Card.Actor.theIc')) })}</strong>${done ? ` <em>${tx('SR2E.Card.Actor.theEarlierIsTakenBack', { done })}</em>` : ''}</p>`;
      return { html, flags: {}, snap: { ...snap, mutility: { ...u, applied } } };
    }
    // Restore: from the state before the test, so a re-roll replaces rather than adds.
    const before = u.before ?? { crippled: { ...NO_DECK_DAMAGE }, deck: { ...NO_DECK_DAMAGE } };
    const plan = restorePlan(before.crippled, before.deck, s);
    // v0.81.0 (D3-5): the deck it was rolled on, and only over what is still there from then (or from the last roll).
    const deck: any = u.deckId ? this.items.get(u.deckId) : this.activeDeck();
    const keys = Object.keys(NO_DECK_DAMAGE) as Array<keyof DeckDamage>;
    const same = (a: any, b: any) => keys.every((k) => Number(a?.[k] ?? 0) === Number(b?.[k] ?? 0));
    const expect = u.after ?? before;
    const nowCrippled = { ...NO_DECK_DAMAGE, ...(this.sys.matrix?.crippled ?? {}) };
    const nowDeck = { ...NO_DECK_DAMAGE, ...(deck?.system?.damage ?? {}) };
    const deckToo = Boolean(deck && RULES.MATRIX_V57.utilities.restore.deckDamage);
    if (!same(nowCrippled, expect.crippled) || (deckToo && !same(nowDeck, expect.deck))) {
      return { html: `<p><em>${tx('SR2E.Card.Actor.sPersonaChangedSinceThisWas', { name: escText(this.name) })}</em></p>`, flags: {}, snap };
    }
    await this.update({ 'system.matrix.crippled': { bod: plan.crippled.bod, evasion: plan.crippled.evasion, masking: plan.crippled.masking, sensors: plan.crippled.sensors } });
    if (deckToo) await deck.update({ 'system.damage': plan.deckDamage });
    const after = { crippled: { ...NO_DECK_DAMAGE, ...nowCrippled, bod: plan.crippled.bod, evasion: plan.crippled.evasion, masking: plan.crippled.masking, sensors: plan.crippled.sensors }, deck: deckToo ? { ...NO_DECK_DAMAGE, ...plan.deckDamage } : nowDeck };
    let degraded = Boolean(u.degraded);
    let wear = '';
    if (!degraded && RULES.MATRIX_V57.utilities.restore.degrades) {
      const prog: any = this.items.get(u.programId);
      if (prog) { const to = Math.max(0, Number(prog.system.rating ?? 0) - 1); await prog.update({ 'system.rating': to }); wear = tx('SR2E.Card.Actor.dropsToRating2', { programName: escText(u.programName), to }); }
      degraded = true;
    }
    return { html: `<p>${plan.restored ? `<strong>${tx('SR2E.Card.Actor.restored', { plural: escText(plural(plan.restored, 'point')) })}</strong> ${tx('SR2E.Card.Actor.toSPersona', { name: escText(this.name) })}` : tx('SR2E.Card.Actor.nothingRestored')}${wear}</p>`, flags: {}, snap: { ...snap, mutility: { ...u, degraded, after } } };
  }

  /**
   * v0.57.0: play a BTL or simsense chip (RULES.MATRIX_V57.chips): it needs a chipjack, datajack or
   * simrig; one-use kinds burn out; addictive kinds count as a dose for addiction.
   */
  async playChip(itemId: string): Promise<boolean> {
    const it: any = this.items.get(itemId);
    const c = it?.system?.simchip;
    if (!it || !c?.kind) {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.thatIsNotABtlOr'));
      return false;
    }
    if ((it.system.quantity ?? 0) <= 0) {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.hasNoLeft', { name: escHtml(this.name), name2: escHtml(it.name) }));
      return false;
    }
    const cyber = this.sys.derived?.cyber ?? {};
    const simrig = [...this.items].some((i: any) => i.type === 'gear' && i.system?.simrig && isCarried(i));
    const hw = chipPlayable({ chipjack: Boolean(cyber.chipjack), datajack: Boolean(cyber.datajack), simrig });
    if (!hw.ok) {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.needsAChipjackDatajackOrSimrig', { name: escHtml(this.name), name2: escHtml(it.name) }));
      return false;
    }
    const b = chipBehaviour(c.kind);
    if (b.burnsOut) await it.update({ 'system.quantity': Math.max(0, (it.system.quantity ?? 1) - 1) });
    const minutes = Number(c.minutes ?? 0);
    const what: Record<string, string> = {
      simsense: tx('SR2E.Card.Actor.aFullSensorySimRecording'),
      btl: tx('SR2E.Card.Actor.betterThanLifeTheUserIs'),
      dreamchip: tx('SR2E.Card.Actor.aDreamchipAnEndlessCompellingLoop'),
      moodchip: tx('SR2E.Card.Actor.aMoodchipTheEmotionFloodsIn'),
      personafix: tx('SR2E.Card.Actor.aPersonafixTheUserBelievesThey'),
    };
    await ChatMessage.create({
      speaker: ChatMessage.getSpeaker({ actor: this }),
      content: `<p><strong>${escText(this.name)}</strong> ${tx('SR2E.Card.Actor.plays')} <strong>${escText(it.name)}</strong> ${(minutes ? tCount(minutes, 'SR2E.Card.Actor.throughAWithForMinutes2', { label: escText(b.label), part: c.rating ? ` ${escText(c.rating)}` : '', hwVia: escText(hw.via), what: what[c.kind] ?? tx('SR2E.Card.Actor.theGmPlaysTheEffect'), part3: b.burnsOut ? tx('SR2E.Card.Actor.theChipBurnsOut') : '' }) : tx('SR2E.Card.Actor.throughAPlain', { label: escText(b.label), part: c.rating ? ` ${escText(c.rating)}` : '', hwVia: escText(hw.via), what: what[c.kind] ?? tx('SR2E.Card.Actor.theGmPlaysTheEffect'), part3: b.burnsOut ? tx('SR2E.Card.Actor.theChipBurnsOut') : '' }))}</p>`,
    });
    if (b.addictive && Number(c.rating ?? 0) > 0) await this.#recordDose(it.name, Number(c.rating), 'mental');
    return true;
  }

  /** v0.57.0: count a dose of something addictive (a drug or a BTL), and roll the addiction test when RULES.HEALTH.addiction.auto. */
  async #recordDose(name: string, rating: number, type: string): Promise<void> {
    const now = sysNow();
    const addictions: any[] = [...(this.sys.addictions ?? [])].map((x: any) => ({ ...x }));
    let add: any = addictions.find((x) => x.drug === name);
    if (!add) { add = { drug: name, rating, type, recent: [], lastDose: now, addicted: false, dosesAddicted: 0, withdrawalNoted: false }; addictions.push(add); }
    add.rating = rating;
    add.recent = [...recentDoses(add.recent ?? [], now), now];
    add.lastDose = now;
    add.withdrawalNoted = false;
    if (add.addicted) add.dosesAddicted += 1;
    await this.update({ 'system.addictions': addictions });
    if (RULES.HEALTH.addiction.auto && !add.addicted) await this.drugAddictionTest(name, 'dose');
  }

  /** A trace completes: report the decker's location, or dump them (and burn their deck). */
  async #completeTrace(): Promise<void> {
    const t = this.sys.matrix.trace;
    const host: any = t.hostUuid ? fromUuidSync(t.hostUuid) : null;
    const gms = [...((game as any).users ?? [])].filter((u: any) => u.isGM).map((u: any) => u.id);
    await this.update({ 'system.matrix.trace': { ...t, active: false } });
    let where = '';
    try {
      const token: any = (this as any).getActiveTokens?.()?.[0];
      if (token?.scene?.name ?? token?.document?.parent?.name) where = String(token.scene?.name ?? token.document.parent.name);
    } catch { /* no token */ }
    if (t.mode === 'report') {
      if (host) await SR2Actor.changeHost(host, { minAlert: 'active' }, tx('SR2E.Card.Actor.reports', { icName: t.icName, name: this.name }), this.uuid as string);
      await ChatMessage.create({ speaker: { alias: t.icName }, content: `<p><em>${tx('SR2E.Card.Actor.gmOnly')}</em> · <strong>${tx('SR2E.Card.Actor.traceComplete')}</strong> ${where ? tx('SR2E.Card.Actor.hasLocatedSJackpointAt', { icName: escText(t.icName), name: escText(this.name), sceneName: escText(where) }) : tx('SR2E.Card.Actor.hasLocatedSJackpoint', { icName: escText(t.icName), name: escText(this.name) })}</p>`, whisper: gms });
      return;
    }
    const tn = (host?.system?.securityValue as number | undefined) ?? RULES.MATRIX.dumpShockTn;
    const level = dumpShockLevel(String(host?.system?.securityCode ?? ''));
    await this.update({ 'system.matrix.jackedIn': false, 'system.matrix.hostUuid': '', ...this.#endRunUpdate() });
    const burn = t.mode === 'burn' && RULES.MATRIX.trace.burnMpcp;
    await ChatMessage.create({
      speaker: ChatMessage.getSpeaker({ actor: this }),
      content: `<p><strong>${tx('SR2E.Card.Actor.traceComplete')}</strong> ${(burn ? tx('SR2E.Card.Actor.dumpsFromTheMatrixWithAndBurnsTheDeck', { icName: escText(t.icName), name: escText(this.name) }) : tx('SR2E.Card.Actor.dumpsFromTheMatrixPlain', { icName: escText(t.icName), name: escText(this.name) }))}</p>
        <p>${this.isTortoise() && !RULES.MATRIX.tortoise.dumpShock ? tx('SR2E.Card.Actor.aTortoiseNoDumpShock') : `<button type="button" data-sr2e-action="dumpShock">${tx('SR2E.Card.Actor.resistDumpShockWillpowerVs2', { tn, level })}</button>`}${burn ? ` <button type="button" data-sr2e-action="deckDamage">${tx('SR2E.Card.Actor.deckDamageRatingVsMpcp2', { icName: escText(t.icName), rating: escText(t.rating) })}</button>` : ''}</p>`,
      flags: { [SYSTEM_ID]: { dumpShockFor: this.uuid, dumpShockTn: tn, dumpShockLevel: level, ...(burn ? { deckDamage: { deckerUuid: this.uuid, icName: t.icName, rating: t.rating, reason: tx('SR2E.Card.Actor.traceAndBurn') } } : {}) } },
    });
    await this.#hitcherShock(tn, level);
    await this.#unhitchAll();
  }

  /**
   * An agent searches several hosts by itself (v0.46.0, RULES.MATRIX.agentSearch): it logs on to
   * each in turn (grid path not enforced) and runs the search there; the files it finds are this
   * decker's. Stops at the first find when `stopOnFind`. Returns how many hosts it searched.
   */
  async agentSearch(agentUuid: string, opts: { hostUuids: string[]; operationId?: 'locateFile' | 'locatePaydata'; stopOnFind?: boolean }): Promise<{ searched: number; found: number; hops: number } | null> {
    const agent: any = await fromUuid(agentUuid);
    if (!agent || agent.type !== 'ic' || agent.system?.kind !== 'agent' || agent.system.ownerUuid !== this.uuid || agent.system.derived?.crashed) {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.pickOneOfYourAgentsNot'));
      return null;
    }
    const as = RULES.MATRIX.agentSearch;
    const hosts = [...new Set(opts.hostUuids ?? [])].slice(0, as.maxHosts).map((u) => fromUuidSync(u)).filter((h: any) => h?.type === 'host');
    if (!hosts.length) {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.pickTheHostsForTheAgent'));
      return null;
    }
    const opId = opts.operationId ?? 'locateFile';
    const stop = opts.stopOnFind ?? as.stopOnFind;
    const node = (h: any): GridNode => ({ uuid: h.uuid, gridKind: h.system?.gridKind ?? 'host', parentUuid: h.system?.parentUuid ?? '' });
    const all: GridNode[] = allActors().filter((a: any) => a.type === 'host').map(node);
    const rows: string[] = [];
    let searched = 0, found = 0, hops = 0;
    for (const h of hosts) {
      const here: any = agent.system.hostUuid ? fromUuidSync(agent.system.hostUuid) : null;
      if (agent.system.derived?.crashed) { rows.push(`<li>${tx('SR2E.Card.Actor.hasCrashedTheSearchEnds', { agentName: escText(agent.name) })}</li>`); break; }
      if (here?.uuid !== h.uuid) {
        const leg = gridHops(here ? node(here) : null, node(h), all);
        const on = await this.systemTest('access', { operationId: 'logon', targetUuid: h.uuid, frameUuid: agent.uuid, ignorePath: true });
        if (!on || on.successes <= 0) { rows.push(`<li>${tx('SR2E.Card.Actor.couldNotLogOn', { name: escText(h.name) })}</li>`); continue; }
        hops += leg;
      }
      // What the search can find, counted from the files before it runs (a player's finds may wait on a GM card).
      const filesBefore: DataFile[] = [...(h.system?.files ?? [])].map((f: any) => ({ ...f, foundBy: [...(f.foundBy ?? [])] }));
      const r = await this.systemTest('index', { operationId: opId, frameUuid: agent.uuid });
      searched++;
      const got = r && r.successes > 0 ? locateFiles(filesBefore, this.uuid as string, r.successes, opId === 'locatePaydata').length : 0;
      found += got;
      rows.push(`<li>${escText(h.name)}: ${r && r.successes > 0 ? (got ? `<strong>${tCount(got, 'SR2E.Card.Actor.files2')}</strong> ${tx('SR2E.Card.Actor.found3')}` : tx('SR2E.Card.Actor.nothingNew')) : tx('SR2E.Card.Actor.theSearchFails')}.</li>`);
      if (stop && got > 0) break;
    }
    const turns = travelTurns(hops);
    await ChatMessage.create({
      speaker: ChatMessage.getSpeaker({ actor: this }),
      content: `<div class="sr2e-roll"><h3>${tCount(hosts.length, 'SR2E.Card.Actor.searchesHosts', { agentName: escText(agent.name) })}</h3><ul>${rows.join('')}</ul><p>${tCount(found, 'SR2E.Card.Actor.searchedFilesFound', { searched, part: hops ? tx('SR2E.Card.Actor.acrossTheGridOfTravel', { hops: tCount(hops, 'SR2E.Count.hops'), combatTurns: tCount(turns, 'SR2E.Count.combatTurns') }) : '' })}</p></div>`,
    });
    return { searched, found, hops };
  }

  // ---------------------------------------------------------------- Otaku (v0.49.0)

  /** This otaku's channel rating for a subsystem (0 without a living persona). */
  otakuChannel(sub: string): number {
    if (!this.sys.derived?.matrix?.living) return 0;
    const r = Math.max(0, Math.floor(Number(this.sys.matrix?.channels?.[sub] ?? 0)));
    return RULES.MATRIX.otaku.channels.maxFromMpcp ? Math.min(r, otakuCap(this.sys.derived.matrix.mpcp ?? 0)) : r;
  }

  /** Raise a channel by one for Good Karma (at most MPCP). */
  async raiseChannel(sub: string): Promise<boolean> {
    const m = this.sys.derived?.matrix;
    if (!m?.living) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.hasNoLivingPersonaOtakuHouse', { name: escHtml(this.name) })); return false; }
    if (!(RULES.MATRIX.subsystems as readonly string[]).includes(sub)) return false;
    const from = Math.max(0, Math.floor(Number(this.sys.matrix?.channels?.[sub] ?? 0)));
    const to = from + 1;
    if (RULES.MATRIX.otaku.channels.maxFromMpcp && to > otakuCap(m.mpcp)) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.canTGoAboveMpcp', { sub: escHtml(cap(sub)), mpcp: escHtml(m.mpcp) })); return false; }
    const cost = channelRaiseCost(to);
    const good = Number(this.sys.karma?.good ?? 0);
    if (good < cost) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.hasGoodKarmaCosts', { name: escHtml(this.name), good, sub: escHtml(cap(sub)), to, cost })); return false; }
    if (approvalNeeded(this)) { await fileRequest(this, { kind: 'improve', label: `${cap(sub)} channel ${from} → ${to}`, karma: cost, data: { method: 'raiseChannel', args: [sub] } }); return false; }
    await this.update({ [`system.matrix.channels.${sub}`]: to, 'system.karma.good': good - cost, 'system.ledger': this.#ledgerWith({ kind: 'karma', amount: -cost, reason: tx('SR2E.Text.Actor.channelFromTo', { sub: cap(sub), from, to }) }) });
    await ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor: this }), content: `<p><strong>${escText(this.name)}</strong> ${tx('SR2E.Card.Actor.opensTheChannelToForKarma', { sub: escText(cap(sub)), to, cost })}</p>` });
    return true;
  }

  /** Learn a complex form (an otaku's own program: no memory, never erased) for Good Karma. */
  async learnComplexForm(o: { kind: string; rating: number; damageLevel?: string; name?: string }): Promise<any | null> {
    const m = this.sys.derived?.matrix;
    if (!m?.living) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.hasNoLivingPersonaOtakuHouse', { name: escHtml(this.name) })); return null; }
    if (!(UTILITY_KINDS as readonly string[]).includes(o.kind)) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.unknownProgramKind', { kind: escHtml(o.kind) })); return null; }
    const rating = Math.max(1, Math.floor(o.rating || 1));
    if (RULES.MATRIX.otaku.complexForms.maxFromMpcp && rating > otakuCap(m.mpcp)) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.aComplexFormCanTBe', { mpcp: escHtml(m.mpcp) })); return null; }
    const cost = complexFormCost(rating);
    const good = Number(this.sys.karma?.good ?? 0);
    if (good < cost) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.hasGoodKarmaThatComplexForm', { name: escHtml(this.name), good, cost })); return null; }
    const name = o.name || `${cap(o.kind)} ${rating} (complex form)`;
    if (approvalNeeded(this)) { await fileRequest(this, { kind: 'improve', label: tx('SR2E.Text.Actor.complexForm', { name }), karma: cost, data: { method: 'learnComplexForm', args: [{ ...o }] } }); return null; }
    const [made] = await this.createEmbeddedDocuments('Item', [{ name, type: 'program', system: { kind: o.kind, rating, size: 0, loaded: true, erased: false, damageLevel: o.damageLevel ?? 'M', complexForm: true } }], { sr2eComplexForm: true });
    await this.update({ 'system.karma.good': good - cost, 'system.ledger': this.#ledgerWith({ kind: 'karma', amount: -cost, reason: tx('SR2E.Text.Actor.complexForm', { name }) }) });
    await ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor: this }), content: `<p><strong>${escText(this.name)}</strong> ${tx('SR2E.Card.Actor.learnsTheComplexForm')} <strong>${escText(name)}</strong> ${tx('SR2E.Card.Actor.forKarma', { cost })}</p>` });
    return made ?? null;
  }

  /** v0.49.0: the best programming suite this character has (gear with a suite rating). */
  programmingSuite(): number {
    return [...this.items].filter((i: any) => i.type === 'gear').reduce((n: number, i: any) => Math.max(n, Math.floor(Number(i.system?.suite ?? 0))), 0);
  }

  /**
   * Write a program (v0.46.0, RULES.MATRIX.programming): Computer (Programming) vs the program's
   * rating; on a success the program is added (unloaded), and the card gives the days it took.
   * v0.49.0: program options (size, TN, time) and a programming suite (dice or TN).
   */
  async writeProgram(o: { kind: string; rating: number; damageLevel?: string; name?: string; poolDice?: number; modifiers?: TargetNumberModifier[]; options?: string[]; useSuite?: boolean }): Promise<SuccessTestResult | null> {
    if (!(UTILITY_KINDS as readonly string[]).includes(o.kind)) {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.unknownProgramKind', { kind: escHtml(o.kind) }));
      return null;
    }
    const p = RULES.MATRIX.programming;
    const plan = programPlan(o);
    const rating = Math.max(1, Math.floor(o.rating || 1));
    const skill: any = this.findSkill(p.skill);
    const useConc = Boolean(skill?.system?.concentration && String(skill.system.concentration).toLowerCase() === p.concentration.toLowerCase());
    const sd = this.#skillDice(skill, false, null, 'intelligence', { useConcentration: useConc });
    const suite = o.useSuite === false ? { dice: 0, modifiers: [], note: '' } : suiteBonus(this.programmingSuite(), Number(skill?.system?.rating ?? 0));
    const name = o.name || `${cap(o.kind)} ${rating}${o.kind === 'attack' ? ` (${o.damageLevel ?? 'M'})` : ''}`;
    const options = [...new Set(o.options ?? [])].filter((id) => p.options.some((x) => x.id === id));
    return this.#runTest(tx('SR2E.Card.Actor.writeMpTnRating', { name, planSize: plan.size, part: plan.labels.length ? `; ${plan.labels.join(', ')}` : '', rating, part2: plan.tn !== Math.max(RULES.MIN_TARGET_NUMBER, rating + p.tnMod) ? ` → ${plan.tn}` : '', sdSuffix: sd.suffix, part3: suite.note ? ` [${suite.note}]` : '' }), sd.dice + suite.dice, {
      targetNumber: plan.tn, modifiers: [...(o.modifiers ?? []), ...sd.modifiers, ...suite.modifiers], poolDice: 0,
    }, { kind: 'code', code: { mode: 'program', name, baseDays: plan.baseDays, size: plan.size, system: { kind: o.kind, rating, size: 0, loaded: false, erased: false, damageLevel: o.damageLevel ?? 'M', options } } });
  }

  /**
   * Build or upgrade a deck part (v0.46.0, RULES.MATRIX.deckBuilding): the builder's B/R skill vs
   * the part's rating (+ its TN); on a success the part is set to that rating and the parts are
   * paid for. `deckId` null builds a new deck (its MPCP first).
   */
  async buildDeckPart(o: { deckId?: string | null; part: string; rating: number; name?: string; modifiers?: TargetNumberModifier[]; pay?: boolean }): Promise<SuccessTestResult | null> {
    const deck: any = o.deckId ? this.items.get(o.deckId) : null;
    if (o.deckId && (!deck || deck.type !== 'cyberdeck')) {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.thatDeckIsNotOnThis'));
      return null;
    }
    if (!deck && o.part !== 'mpcp') {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.aNewDeckStartsWithIts'));
      return null;
    }
    const plan = deckPartPlan(o.part, o.rating, deck ? Number(deck.system.mpcp ?? 0) : Math.floor(o.rating || 1));
    if (!plan) {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.unknownDeckPart', { part: escHtml(o.part) }));
      return null;
    }
    for (const w of plan.warnings) ui.notifications?.warn?.(escHtml(w));
    const pay = o.pay ?? true;
    if (pay && plan.cost > Number(this.sys.nuyen ?? 0)) {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.cannotPayForTheParts', { name: escHtml(this.name), planCost: plan.cost }));
      return null;
    }
    const db = RULES.MATRIX.deckBuilding;
    const skill = db.skills.map((n) => this.findSkill(n)).find((x: any) => x && (x.system?.rating ?? 0) > 0);
    const sd = this.#skillDice(skill, false, null, 'intelligence');
    const rating = Math.max(1, Math.floor(o.rating || 1));
    const deckName = deck?.name ?? (o.name || `Home-built deck`);
    // v0.49.0: a programming suite helps design the part's code.
    const suite = RULES.MATRIX.programming.suites.deckBuilding ? suiteBonus(this.programmingSuite(), Number(this.findSkill(RULES.MATRIX.programming.skill)?.system?.rating ?? 0)) : { dice: 0, modifiers: [], note: '' };
    const what = plan.memory ? `${plan.label.replace(/\s*\(.*\)$/, '')} +${rating}` : `${plan.label} ${rating}`;
    return this.#runTest(tx('SR2E.Card.Actor.buildMpDesignMaterials', { deckName, what, planSize: plan.size, planCost: plan.cost.toLocaleString(), part: skill ? ` (${skill.name})` : '', sdSuffix: sd.suffix, part2: suite.note ? ` [${suite.note}]` : '' }), sd.dice + suite.dice, {
      targetNumber: plan.tn, modifiers: [...(o.modifiers ?? []), ...sd.modifiers, ...suite.modifiers], poolDice: 0,
    }, { kind: 'code', code: { mode: 'deck', name: deckName, baseDays: plan.baseDays, part: o.part as DeckPart, rating, cost: pay ? plan.cost : 0, deckId: deck?.id ?? '', size: plan.size, memory: plan.memory } });
  }

  /** A programming or deck-building test's result, applied once (a re-roll only changes the time). */
  async #resolveCode(snap: TestSnapshot): Promise<Resolved> {
    const c = snap.code!;
    const s = snap.successes;
    const days = workDays(c.baseDays, s);
    if (!days && c.projectId) return { html: `<p><strong>${tx('SR2E.Card.Actor.noProgress')}</strong>.${await this.dropProjectOnFailure(c.projectId)}</p>`, flags: {}, snap: { ...snap, code: { ...c, applied: false, projectId: undefined } } };
    if (!days) return { html: `<p><strong>${tx('SR2E.Card.Actor.noProgress')}</strong>: ${c.mode === 'program' ? tx('SR2E.Card.Actor.isNotWritten', { name: escText(c.name) }) : tx('SR2E.Card.Actor.thePartDoesNotWork')}.${c.applied ? ` <em>${tx('SR2E.Card.Actor.itWasAlreadyAppliedUndoIt')}</em>` : ''}</p>`, flags: {}, snap };
    const time = `<strong>${tCount(days, 'SR2E.Card.Actor.days')}</strong> ${tx('SR2E.Card.Actor.ofWork', { baseDays: c.baseDays, s })}`;
    if (c.applied) {
      // v0.65.0: a re-roll of work under way changes how long it takes.
      const p = await this.retimeProject(c.projectId, days * 24);
      return { html: `<p>${p ? tx('SR2E.Card.Actor.underWay', { time }) : `${tx('SR2E.Card.Actor.doneIn2', { time })} <em>${tx('SR2E.Card.Actor.alreadyApplied2')}</em>`}</p>`, flags: {}, snap };
    }
    // v0.65.0: the work takes its days: the program (or the deck part) is ready when they have passed.
    if (this.waitsFor('matrix')) {
      const label = c.mode === 'program' ? '' : RULES.MATRIX.deckBuilding.parts[c.part!]?.label ?? c.part;
      if (c.mode !== 'program' && (c.cost ?? 0) > 0 && !(await this.adjustNuyen(-(c.cost ?? 0), tx('SR2E.Text.Actor.deckMaterials', { label, rating: c.memory ? `+${c.rating}` : c.rating })))) return { html: `<p><em>${tx('SR2E.Card.Actor.notEnoughNuyenForTheMaterials', { cost: c.cost })}</em></p>`, flags: {}, snap };
      const effect: ProjectEffect = c.mode === 'program' ? { creates: [{ name: c.name, type: 'program', system: c.system ?? {} }] } : { call: { method: 'finishDeckPart', args: [c.deckId ?? null, c.name, c.part, c.rating ?? 0, Boolean(c.memory)] } };
      const pr = await this.startProject({ kind: 'code', area: 'matrix', label: c.mode === 'program' ? `Writing ${c.name}` : `${c.name}: ${label} ${c.memory ? `+${c.rating}` : c.rating}`, hours: days * 24, paid: { nuyen: c.mode === 'program' ? 0 : Number(c.cost ?? 0) }, effect });
      return { html: `<p><strong>${escText(c.name)}</strong>${tx('SR2E.Card.Actor.readyWhenItHasPassedUpkeep', { time })}</p>`, flags: {}, snap: { ...snap, code: { ...c, applied: true, projectId: pr.id } } };
    }
    let body = '';
    try {
      if (c.mode === 'program') {
        await this.createEmbeddedDocuments('Item', [{ name: c.name, type: 'program', system: c.system ?? {} }]);
        body = `<strong>${escText(c.name)}</strong> ${tx('SR2E.Card.Actor.isWrittenInItIsOn', { time })}`;
      } else {
        const label = RULES.MATRIX.deckBuilding.parts[c.part!]?.label ?? c.part;
        // v0.81.0 (D3-11): the materials are paid first (as when the work waits); no nuyen, no part.
        if ((c.cost ?? 0) > 0 && !(await this.adjustNuyen(-(c.cost ?? 0), tx('SR2E.Text.Actor.deckMaterials', { label, rating: c.memory ? `+${c.rating}` : c.rating })))) return { html: `<p><em>${tx('SR2E.Card.Actor.notEnoughNuyenForTheMaterials', { cost: c.cost })}</em></p>`, flags: {}, snap };
        const deck: any = c.deckId ? this.items.get(c.deckId) : null;
        // v0.49.0: memory parts add their Mp to what the deck has.
        const value = c.memory ? Number(deck?.system?.[c.part!] ?? 0) + (c.rating ?? 0) : c.rating;
        await this.finishDeckPart(deck ? deck.id : null, c.name, c.part!, c.rating ?? 0, Boolean(c.memory));
        body = `<strong>${escText(c.name)}</strong>${tx('SR2E.Card.Actor.in4', { label: escText(label), part: escText(c.memory ? tx('SR2E.Card.Actor.now5', { rating: c.rating, value }) : c.rating), time, part2: (c.cost ?? 0) > 0 ? tx('SR2E.Card.Actor.materials3', { cost: c.cost }) : '' })}`;
      }
    } catch (err) {
      console.warn('sr2e | code', err);
      body = tx('SR2E.Card.Actor.couldNotApplyThisHereGm2');
    }
    return { html: `<p>${body}</p>`, flags: {}, snap: { ...snap, code: { ...c, applied: true } } };
  }

  /** v0.65.0: a deck repair's time has passed: the repaired points come off (damage taken meanwhile stays). */
  async finishDeckRepair(deckId: string, off: Record<string, number>): Promise<boolean> {
    const deck: any = this.items.get(deckId);
    if (!deck) return false;
    const cur: any = { ...NO_DECK_DAMAGE, ...(deck.system?.damage ?? {}) };
    for (const [k, v] of Object.entries(off ?? {})) cur[k] = Math.max(0, Number(cur[k] ?? 0) - Math.max(0, Number(v) || 0));
    await deck.update({ 'system.damage': cur });
    return true;
  }

  /** v0.65.0: deck work whose time has passed: the part goes in (a new deck when there was none). */
  async finishDeckPart(deckId: string | null, name: string, part: string, rating: number, memory: boolean): Promise<boolean> {
    let deck: any = deckId ? this.items.get(deckId) : null;
    if (deckId && !deck) return false;
    const value = memory ? Number(deck?.system?.[part] ?? 0) + Number(rating) : Number(rating);
    if (!deck) {
      const zero = { mpcp: 0, bod: 0, evasion: 0, masking: 0, sensors: 0, hardening: 0, responseIncrease: 0 };
      await this.createEmbeddedDocuments('Item', [{ name, type: 'cyberdeck', system: { ...zero, active: false, [part]: value } }]);
    } else await deck.update({ [`system.${part}`]: value });
    return true;
  }

  /** GM: launch an IC actor into a host. */
  static async launchIc(host: any, data: { name: string; category: string; icType: string; rating: number; damageLevel: string; damageType: string; behavior?: string; guards?: string; traceMode?: string; attribute?: string; payload?: string; party?: string; construct?: string[] }): Promise<any> {
    const cls: any = (Actor as any).implementation ?? Actor;
    return cls.create({
      name: data.name || `${data.icType || 'IC'} ${data.rating}`,
      type: 'ic',
      prototypeToken: { name: data.name || `${data.icType || 'IC'} ${data.rating}`, actorLink: true },
      system: {
        rating: data.rating, category: data.category, icType: data.icType, damageLevel: data.damageLevel, damageType: data.damageType, hostUuid: host.uuid,
        // Without a behavior, guess it from the IC's name (e.g. "Tar Pit" → tarPit).
        behavior: data.behavior || behaviorFromName(data.icType || data.name) || 'killer', ...(data.guards ? { guards: data.guards } : {}),
        ...(data.traceMode ? { traceMode: data.traceMode } : {}), ...(data.attribute ? { attribute: data.attribute } : {}),
        ...(data.payload ? { payload: data.payload } : {}),
        ...(data.party ? { party: data.party } : {}), ...(data.construct?.length ? { construct: data.construct } : {}),
      },
    });
  }

  // ---------------------------------------------------------------- Vehicles and rigging (v0.24.0)

  /** A vehicle's controller (null on autopilot). */
  controller(): any | null {
    const uuid = this.sys.controllerUuid;
    return uuid ? fromUuidSync(uuid) ?? null : null;
  }

  /** The vehicle this character drives or is jumped into (null if none). */
  riggedVehicle(): any | null {
    const uuid = this.sys.rigging?.vehicleUuid;
    return uuid ? fromUuidSync(uuid) ?? null : null;
  }

  /**
   * v0.81.0 (D3-3, D3-9): why `driver` can't take this vehicle in `mode` now (`block`), and what only warns. Checked
   * before takeControl spends the action, and again by setController. A previous driver or the driver's other vehicle
   * that this client can't write blocks it too (nothing is half-applied).
   */
  #controlProblem(driver: any | null, m: ControlMode): { block: string | null; warn: string[] } {
    const warn: string[] = [];
    const no = (block: string) => ({ block, warn });
    if (driver && this.sys.derived?.destroyed) return no(tx('SR2E.Text.Actor.isDestroyed', { name: this.name }));
    if (driver && m === 'jumped' && RULES.RIGGING.jumpInNeedsVcr && !((driver.system?.derived?.rigging?.vcr ?? 0) > 0)) return no(tx('SR2E.Text.Actor.hasNoControlRigAndCannot', { name: driver.name }));
    if (driver && m === 'jumped') {
      const dj = datajackCheck('rigging', Boolean(driver.system?.derived?.cyber?.datajack));
      if (dj === 'block') return no(tx('SR2E.Text.Actor.hasNoDatajackToJumpIn', { name: driver.name }));
      if (dj === 'warn') warn.push(tx('SR2E.Text.Actor.hasNoDatajackJumpingInAnyway', { name: driver.name }));
    }
    // Jumping in from outside the vehicle needs a remote control deck.
    if (driver && m === 'jumped' && RULES.RIGGING.remote.needsRcd && !this.isAboard(driver) && !((driver.system?.derived?.rigging?.rcd ?? 0) > 0)) return no(tx('SR2E.Text.Actor.isNotAboardAndHasNo', { name: driver.name, vehicleName: this.name }));
    // v0.46.0: rigger adaptation (house rule), a jammed link, and the remote control deck's range.
    if (driver && m === 'jumped' && RULES.RIGGING.needsAdaptation && !this.sys.derived?.adaptation) return no(tx('SR2E.Text.Actor.hasNoRiggerAdaptationInstallThe', { name: this.name }));
    if (driver && m === 'jumped' && !this.isAboard(driver)) {
      // v0.73.0 (O28): jammed, or taken over by a spoofer.
      const blk = droneCommandBlock(this.sys);
      if (blk.blocked) return no(`${this.name}: ${blk.reason}.`);
      const link = driver.remoteLink?.(this);
      if (link?.check?.checked && !link.check.inRange) {
        if (RULES.SIGNAL.outOfRange === 'block') return no(tx('SR2E.Text.Actor.isOutOfSRemoteControl', { name: this.name, driverName: driver.name, note: link.check.note }));
        warn.push(tx('SR2E.Text.Actor.isOutOfRangeJumpingInAnyway', { name: this.name, note: link.check.note }));
      }
    }
    const prev: any = this.controller();
    if (prev && prev.uuid !== driver?.uuid && prev.system?.rigging?.vehicleUuid === this.uuid && notWritableNow(prev)) return no(tx('SR2E.Text.Actor.isAtSControlsTheyLet', { name: prev.name, vehicleName: this.name }));
    const other: any = driver ? driver.riggedVehicle?.() : null;
    if (other && other.uuid !== this.uuid && other.system?.controllerUuid === driver.uuid && notWritableNow(other)) return no(tx('SR2E.Text.Actor.stillControlsLetGoOfIt', { name: driver.name, otherName: other.name }));
    return { block: null, warn };
  }

  /**
   * Vehicle: put a driver at the controls ('manual', or 'jumped' through a control rig), or hand it
   * to the autopilot (driver null). Keeps the driver's `rigging` and the vehicle's controller in step.
   */
  async setController(driver: any | null, mode: ControlMode = 'manual'): Promise<boolean> {
    if (this.type !== 'vehicle') return false;
    const m: ControlMode = driver ? (mode === 'autopilot' ? 'manual' : mode) : 'autopilot';
    const problem = this.#controlProblem(driver, m);
    if (problem.block) { ui.notifications?.warn?.(escHtml(problem.block)); return false; }
    for (const w of problem.warn) ui.notifications?.warn?.(escHtml(w));
    const prev: any = this.controller();
    if (prev && prev.uuid !== driver?.uuid && prev.system?.rigging?.vehicleUuid === this.uuid) {
      await prev.update({ 'system.rigging.vehicleUuid': '', 'system.rigging.jumpedIn': false });
    }
    // One vehicle at a time: let go of any other.
    const other: any = driver ? driver.riggedVehicle?.() : null;
    if (other && other.uuid !== this.uuid && other.system?.controllerUuid === driver.uuid) {
      await other.update({ 'system.controllerUuid': '', 'system.controlMode': 'autopilot' });
    }
    // The vehicle first, then the driver, so the driver's sheet re-renders with the vehicle in place.
    await this.update({ 'system.controllerUuid': driver?.uuid ?? '', 'system.controlMode': m });
    if (driver) await driver.update({ 'system.rigging.vehicleUuid': this.uuid, 'system.rigging.jumpedIn': m === 'jumped' });
    SR2Actor.#rerender(this, driver, prev);
    const text = driver
      ? (m === 'jumped' ? `<strong>${escText(driver.name)}</strong> ${tx('SR2E.Card.Actor.jumpsInto')} <strong>${escText(this.name)}</strong>${this.isAboard(driver) ? '' : tx('SR2E.Card.Actor.byRemoteControlDeck')}.` : `<strong>${escText(driver.name)}</strong> ${tx('SR2E.Card.Actor.takesTheControlsOf')} <strong>${escText(this.name)}</strong>.`)
      : prev ? `<strong>${escText(prev.name)}</strong> ${tx('SR2E.Card.Actor.letsGoOf')} <strong>${escText(this.name)}</strong>; ${this.sys.derived?.autopilotRating > 0 ? tx('SR2E.Card.Actor.itIsOnAutopilot') : tx('SR2E.Card.Actor.nobodyIsDrivingIt')}.` : '';
    if (text) await ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor: this }), content: `<p>${text}</p>` });
    return true;
  }

  /** Character: take the controls of a vehicle (or jump into it). */
  async takeControl(vehicle: any, mode: ControlMode = 'manual'): Promise<boolean> {
    if (!vehicle || vehicle.type !== 'vehicle') return false;
    if (!this.canAct('take the controls')) return false;
    // v0.59.0: taking the controls or jumping in takes an action (RULES.ACTIONS.costs).
    const jump = mode === 'jumped';
    // v0.81.0 (D3-3): a refusal comes before the action is spent.
    const problem = vehicle instanceof SR2Actor ? vehicle.#controlProblem(this, jump ? 'jumped' : mode === 'autopilot' ? 'manual' : mode) : { block: null };
    if (problem.block) { ui.notifications?.warn?.(escHtml(problem.block)); return false; }
    if (!(await this.useAction(jump ? 'jumpIn' : 'takeControls', jump ? tx('SR2E.Card.Actor.jumpingInto', { vehicleName: vehicle.name }) : tx('SR2E.Card.Actor.takingSControls', { vehicleName: vehicle.name })))) return false;
    return vehicle.setController(this, mode);
  }

  /** Character: let go of the vehicle being driven (it goes to autopilot). Jumping out takes an action (v0.59.0) unless `action` is false. */
  async releaseVehicle(opts: { action?: boolean } = {}): Promise<void> {
    const v: any = this.riggedVehicle();
    if (v && opts.action !== false && this.sys.rigging?.jumpedIn && !(await this.useAction('jumpOut', tx('SR2E.Card.Actor.jumpingOutOf', { name: v.name })))) return;
    if (v?.type === 'site' && v.system?.riggerUuid === this.uuid) await v.setRigger(null);
    else if (v && v.system?.controllerUuid === this.uuid) await v.setController(null);
    else await this.update({ 'system.rigging.vehicleUuid': '', 'system.rigging.jumpedIn': false });
  }

  /**
   * v0.92.3 (Rigger 2 pp. 50, 53): this character's skill rating for a vehicle (its category's skill, or the vehicle's own;
   * the higher of the rating and a specialization), the cap on Control Pool dice on its damage resistance. 0 without one.
   */
  vehicleSkillRating(vehicle: any): number {
    const v = vehicle?.system;
    const name = String(v?.derived?.skill ?? vehicleCategory(v?.category).skill ?? '');
    const sk: any = name ? this.findSkill(name) : undefined;
    return Math.max(0, Number(sk?.system?.rating ?? 0) || 0, Number(sk?.system?.specializationRating ?? 0) || 0);
  }

  /** Dice for a vehicle test: the vehicle skill, a related skill (+2) or Reaction (+4). */
  #vehicleSkillDice(skill: any | undefined, skillName: string, useSpecialization?: boolean, relatedSkillId?: string | null, jumped = false) {
    const def = RULES.VEHICLES.defaultAttribute;
    const reaction = jumped ? (this.sys.derived?.rigging?.reaction ?? this.sys.derived?.reaction ?? 0) : (this.sys.derived?.reaction ?? 0);
    const attr = def === 'reaction' ? reaction : ((this.sys.attributes?.[def]?.total as number | undefined) ?? 0);
    const related = relatedSkillId ? this.items.get(relatedSkillId) : null;
    const r = skillTestDice({
      rating: skill?.system.rating ?? 0,
      specializationRating: skill?.system.specializationRating ?? 0,
      useSpecialization: Boolean(useSpecialization),
      attributeRating: attr,
      related: related && related.type === 'skill' ? { name: related.name, rating: related.system.rating } : null,
    });
    const suffix = r.using === 'specialization' ? ` (${skill.system.specialization} ${skill.system.specializationRating})`
      : r.using === 'related' ? tx('SR2E.Text.Actor.defaultingTo', { name: related.name })
      : r.using === 'attribute' ? tx('SR2E.Text.Actor.noVehicleSkill', { skill: skillName || tx('SR2E.Text.Actor.vehicle'), attr: cap(def) }) : '';
    return { dice: r.dice, modifiers: r.modifier ? [r.modifier] : [], suffix };
  }

  /**
   * A driving (vehicle) test. Called on the driver (who must be at the controls) or on the vehicle:
   * a vehicle with a driver hands the test to them, otherwise its autopilot rolls Autonav (drones:
   * Pilot). Skill (+ Control Pool when jumped in) vs Handling + terrain, maneuvers, vehicle damage,
   * the control rig and the driver's own penalties. A failed crash test crashes the vehicle.
   */
  async driveTest(opts: DriveOptions = {}): Promise<SuccessTestResult | null> {
    const setup = this.#driveSetup(opts);
    if (!setup) return null;
    if ('delegate' in setup) return setup.delegate.driveTest({ ...opts, vehicle: setup.vehicle });
    const { vehicle, v, mode, handling, offroad, mods, dice, suffix } = setup;
    const crashTest = Boolean(opts.crashTest);
    const push = opts.push !== undefined && !crashTest ? Math.max(0, Math.round(Number(opts.push))) : undefined;
    // v0.92.3 (RULES.VEHICLES_V923.accel 'book', Rigger 2 p. 45): the Accelerate/Brake Test has no extra TN of its own.
    const pushTn = veh923('accel') === 'book' ? 0 : RULES.VEHICLES_V57.accel.pushTn;
    const pushMods = push !== undefined && pushTn ? [{ id: 'pushingTheVehicle', label: tx('SR2E.Card.Mod.pushingTheVehicle'), value: pushTn }] : [];
    const label = (offroad && (v.handlingOffroad ?? 0) > 0 ? tx('SR2E.Card.Actor.handlingWithOffRoad', { vehicleName: vehicle.name, label: opts.label || (crashTest ? tx('SR2E.Card.Actor.crashTest3') : push !== undefined ? tx('SR2E.Card.Actor.pushToSpeed', { push }) : tx('SR2E.Card.Actor.drivingTest')), setupModeLabel: setup.modeLabel, handling, suffix }) : tx('SR2E.Card.Actor.handlingPlain', { vehicleName: vehicle.name, label: opts.label || (crashTest ? tx('SR2E.Card.Actor.crashTest3') : push !== undefined ? tx('SR2E.Card.Actor.pushToSpeed', { push }) : tx('SR2E.Card.Actor.drivingTest')), setupModeLabel: setup.modeLabel, handling, suffix }));
    return this.#runTest(label, dice, {
      targetNumber: handling, modifiers: [...mods, ...pushMods, ...(opts.modifiers ?? [])], vehicle: true, ...(opts.exclude?.length ? { exclude: opts.exclude } : {}),
      poolDice: mode === 'jumped' ? veh80PoolCap(opts.poolDice ?? 0, setup.poolCap) : 0, pool: 'control',
    }, { kind: 'drive', drive: { vehicleUuid: vehicle.uuid as string, vehicleName: vehicle.name as string, crashTest, speed: Number(v.currentSpeed ?? 0), ...(push !== undefined ? { push } : {}) } });
  }

  /**
   * v0.50.0: the Drive dialog's live preview: Handling and every modifier the test would find by itself
   * (terrain, damage, rig, remote control, weather and visibility, over its Speed, the driver's penalties).
   */
  previewDrive(opts: DriveOptions = {}): { base: number; modifiers: TargetNumberModifier[]; dice: number; label: string } | null {
    const setup = this.#driveSetup({ ...opts, quiet: true });
    if (!setup) return null;
    if ('delegate' in setup) return setup.delegate.previewDrive?.({ ...opts, vehicle: setup.vehicle }) ?? null;
    return { base: setup.handling, modifiers: this.#testModifiers({ modifiers: setup.mods, vehicle: true }), dice: setup.dice, label: `${setup.modeLabel}${setup.suffix}` };
  }

  /**
   * v0.50.0 (on a vehicle): poor visibility from light and smoke at its token, by the driver's eyes (by
   * hand) or its sensors (jumped in, autopilot), and the weather's driving modifier: the worse counts.
   */
  drivingSight(mode: string, driver: any = null, weather = true, manual = false): TargetNumberModifier[] {
    if (this.type !== 'vehicle') return [];
    const vision = vehicleTestVision({ mode, sensors: this.visionNow(), driver: driver && driver !== this ? (driver.sys?.derived?.vision ?? {}) : {} });
    let light: LightLevel | null = null, smoke = false;
    try {
      const t = SR2Actor.tokenFor(this);
      if (t) {
        light = targetLight(t)?.light ?? null;
        smoke = smokeBetweenTokens(t, t, SR2Actor.sceneFires((canvas as any)?.scene)).kind !== 'none';
      }
    } catch { /* no canvas */ }
    const wd = weather ? weatherDriving(this.weatherHere()) : null;
    return drivingVisibility({ light, vision, smoke, weather: wd, manual });
  }

  /** v0.50.0: the scene's terrain for driving (a scene flag the GM sets in the GM panel), or null. */
  static sceneTerrain(at: any = null): string | null {
    const scene = at ?? game.scenes?.viewed ?? game.scenes?.current;
    const t = String(scene?.getFlag?.(SYSTEM_ID, 'terrain') ?? '');
    return RULES.VEHICLES.terrain.some((x) => x.id === t) ? t : null;
  }
  static async setSceneTerrain(id: string): Promise<void> {
    const scene = game.scenes?.viewed ?? game.scenes?.current;
    if (scene) await scene.setFlag(SYSTEM_ID, 'terrain', id || '');
  }

  /** Whether an actor is listed aboard this vehicle. */
  isAboard(actor: any): boolean {
    return Boolean(actor) && (this.sys.occupants ?? []).includes(actor.uuid);
  }

  /** The vehicle this character is riding in (aboard, or driving by hand), or null. */
  vehicleAboard(): any | null {
    if (this.type === 'vehicle') return null;
    const v: any = this.riggedVehicle?.();
    if (v && v.system?.controllerUuid === this.uuid && v.system?.controlMode === 'manual') return v;
    try {
      return allActors().find((a: any) => a.type === 'vehicle' && (a.system?.occupants ?? []).includes(this.uuid)) ?? null;
    } catch { return null; }
  }

  /**
   * Who drives and with what for a vehicle test: the driver at the controls (skill, Control Pool when
   * jumped in, the rig, remote control) or the vehicle's autopilot. A vehicle with a driver hands the
   * test over (`delegate`). Null (with a warning) if nobody can.
   */
  #driveSetup(opts: DriveOptions): { delegate: any; vehicle: any } | {
    vehicle: any; v: any; mode: ControlMode; modeLabel: string; handling: number; offroad: boolean; mods: TargetNumberModifier[]; dice: number; suffix: string;
    /** v0.92.3: the dice the Control Pool cap is measured against (the skill's, without autonav dice). */
    poolCap: number;
  } | null {
    const warn = (m: string) => { if (!opts.quiet) ui.notifications?.warn?.(escHtml(m)); };
    const isVehicle = this.type === 'vehicle';
    const vehicle: any = isVehicle ? this : (opts.vehicle ?? this.riggedVehicle());
    if (!vehicle || vehicle.type !== 'vehicle') {
      warn(tx('SR2E.Card.Actor.isNotDrivingAVehicle', { name: this.name }));
      return null;
    }
    const v = vehicle.system;
    if (v.derived?.destroyed) {
      warn(tx('SR2E.Card.Actor.isDestroyed2', { vehicleName: vehicle.name }));
      return null;
    }
    let mode: ControlMode;
    if (isVehicle) {
      const ctl: any = v.controllerUuid ? vehicle.controller() : null;
      if (ctl) return { delegate: ctl, vehicle };
      mode = 'autopilot';
    } else {
      if (v.controllerUuid !== this.uuid) {
        warn(tx('SR2E.Card.Actor.isNotAtTheControlsOf', { name: this.name, vehicleName: vehicle.name }));
        return null;
      }
      if (!opts.quiet && !this.canAct('drive')) return null;
      mode = v.controlMode === 'jumped' && this.sys.rigging?.jumpedIn ? 'jumped' : 'manual';
    }
    const remote = mode === 'jumped' && !vehicle.isAboard(this);
    const offroad = opts.offroad ?? Boolean(v.offroad);
    // v0.57.0: shot-out tires handle worse; a damaged engine lowers the Speed.
    const wk = v.derived?.working ?? { handling: v.handling, handlingOffroad: v.handlingOffroad, speed: v.speed };
    const handling = handlingFor({ handling: wk.handling, handlingOffroad: wk.handlingOffroad }, offroad);
    // v0.50.0: the vehicle's own visibility (light and smoke at its token, by the driver's eyes or its
    // sensors) and the weather count once between them; over its Speed counts by itself.
    const sight = vehicle.drivingSight(mode, this, opts.weather !== false, (opts.situational ?? []).includes('poorVisibility'));
    const autoIds = new Set<string>();
    if (RULES.TN_AUTO.rigging.overSpeedAuto && Number(v.currentSpeed ?? 0) > Number(wk.speed ?? 0) && Number(wk.speed ?? 0) > 0) autoIds.add('overSpeed');
    // Poor visibility ticked by hand goes into drivingSight (the worse of it and the weather counts).
    const situational = [...new Set([...(opts.situational ?? []).filter((id) => id !== 'poorVisibility'), ...autoIds])];
    // v0.92.3: the kind of test picks its own table rows (terrain, the control rig; Rigger 2 pp. 20, 45–48, 52).
    const kind: DriveKind = opts.kind ?? (opts.crashTest ? 'crash' : opts.push !== undefined ? 'maneuver' : 'driving');
    const mods = drivingModifiers({
      terrain: opts.terrain ?? SR2Actor.sceneTerrain(vehicle.sceneHere()) ?? 'normal', situational, damageBoxes: v.condition ?? 0, mode,
      vcr: (this.sys.derived?.rigging?.vcr as number | undefined) ?? 0, kind,
    });
    // v0.92.3 (RULES.VEHICLES_V923.crashMods 'book', Rigger 2 p. 52): a Crash Test's speed against the driver's Reaction.
    if (kind === 'crash' && veh923('crashMods') === 'book') {
      const reaction = mode === 'autopilot' ? Number(v.derived?.reaction ?? 0) : mode === 'jumped' ? Number(this.sys.derived?.rigging?.reaction ?? this.sys.derived?.reaction ?? 0) : Number(this.sys.derived?.reaction ?? 0);
      const cs = crashSpeedModifier(Number(v.currentSpeed ?? 0), reaction);
      if (cs) mods.push(cs);
    }
    if (remote && RULES.RIGGING.remote.tnMod) mods.push({ id: 'remoteControl', label: tx('SR2E.Card.Mod.remoteControl'), value: RULES.RIGGING.remote.tnMod });
    // v0.48.0: rain, snow, fog and storms make driving harder (v0.50.0: with poor visibility, the worse of the two).
    mods.push(...sight);
    // v0.46.0: an overloaded vehicle handles worse; a remote link near the edge of its range is weak.
    if (v.derived?.cargo?.over && RULES.VEHICLES.cargo.overloadTn) mods.push({ id: 'overloaded', label: tx('SR2E.Card.Mod.overloaded'), value: RULES.VEHICLES.cargo.overloadTn });
    if (remote) {
      const link = this.remoteLink(vehicle);
      if (link?.check?.checked && !link.check.inRange && RULES.SIGNAL.outOfRange === 'block') {
        warn(tx('SR2E.Card.Actor.isOutOfSRemoteControl', { vehicleName: vehicle.name, name: this.name, checkNote: link.check.note }));
        return null;
      }
      mods.push(...(link?.check?.modifiers ?? []));
    }
    let dice: number;
    let suffix: string;
    let poolCap = 0;
    if (mode === 'autopilot') {
      dice = v.derived?.autopilotRating ?? 0;
      const what = v.drone ? 'Pilot' : 'Autonav';
      if (!(dice > 0)) {
        warn(tx('SR2E.Card.Actor.hasNoRatingSomeoneHasTo', { vehicleName: vehicle.name, what }));
        return null;
      }
      // v0.92.3 (RULES.VEHICLES_V923.autonavMin 'book', Rigger 2 p. 122): an autonav of rating 1 can't drive by itself.
      if (!v.drone && dice < 2 && veh923('autonavMin') === 'book') {
        warn(tx('SR2E.Card.Actor.autonavTooLowToDrive', { vehicleName: vehicle.name }));
        return null;
      }
      const maneuver = autosoftDice(v.autosofts?.maneuver ?? 0, dice);
      suffix = ` (${what} ${dice}${maneuver ? ` + maneuver autosoft ${maneuver}` : ''})`;
      dice += maneuver;
    } else {
      const skillName = String(v.derived?.skill ?? vehicleCategory(v.category).skill);
      const sd = this.#vehicleSkillDice(skillName ? this.findSkill(skillName) : undefined, skillName, opts.useSpecialization, opts.relatedSkillId, mode === 'jumped');
      dice = sd.dice;
      poolCap = sd.dice;
      suffix = sd.suffix;
      mods.push(...sd.modifiers);
      // v0.92.3 (RULES.VEHICLES_V923.autonavDice 'book', Rigger 2 pp. 20, 51): the autonav's rating in dice on an
      // ordinary Driving Test and a Crash Test (its collision-avoidance programs), not on the combat maneuvers.
      const nav = Math.max(0, Math.floor(Number(v.autonav ?? 0)));
      if (nav > 0 && (kind === 'driving' || kind === 'crash') && veh923('autonavDice') === 'book') {
        dice += nav;
        suffix += tx('SR2E.Card.Actor.plusAutonavDice', { nav });
      }
    }
    const modeLabel = mode === 'jumped' ? (remote ? tx('SR2E.Card.Actor.jumpedInRemote') : tx('SR2E.Card.Actor.jumpedIn')) : mode;
    return { vehicle, v, mode, modeLabel, handling, offroad, mods, dice, suffix, poolCap: poolCap || dice };
  }

  /**
   * Ram a target with the vehicle: a driving test vs Handling (+ RULES.VEHICLES.ram.tn); on a hit the
   * target defends and resists Power = Body + speed/10 (anti-vehicle, impact armor), and the rammer
   * takes its share. Called on the driver or the vehicle (autopilot).
   */
  async ram(targetUuid: string, opts: DriveOptions = {}): Promise<SuccessTestResult | null> {
    const setup = this.#driveSetup({ ...opts, kind: 'ram' });
    if (!setup) return null;
    if ('delegate' in setup) return setup.delegate.ram(targetUuid, { ...opts, vehicle: setup.vehicle, kind: 'ram' });
    const { vehicle, v, mode, handling, mods, dice, suffix } = setup;
    const target: any = await fromUuid(targetUuid);
    if (!target) {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.pickSomethingToRam'));
      return null;
    }
    // v0.80.0 (URR_V80.vehImpact): in a chase between the two, the ramming speed is the difference of their speeds.
    const inChase = target.type === 'vehicle' && (v.chase?.quarryUuid === target.uuid || target.system?.chase?.quarryUuid === vehicle.uuid);
    // v0.92.3 (RULES.VEHICLES_V923.ram 'book', Rigger 2 pp. 47, 52): against a vehicle always the difference of the speeds;
    // a pedestrian (anything else) takes the rammer's speed.
    const bookRam = veh923('ram') === 'book';
    const r = veh80RamDamage({ body: v.body ?? 0, armor: v.armor ?? 0, currentSpeed: Number(v.currentSpeed ?? 0), speed: Number(v.derived?.working?.speed ?? v.speed ?? 0), otherSpeed: inChase || (bookRam && target.type === 'vehicle') ? Number(target.system?.currentSpeed ?? 0) : null, ...(bookRam && target.type !== 'vehicle' ? { pedestrian: true } : {}) });
    const ramTn = RULES.VEHICLES.ram.tn;
    const attack = {
      attackerUuid: this.uuid as string, targetUuid: target.uuid as string, weaponName: `${vehicle.name} (ram)`, melee: false,
      damageType: 'physical' as DamageType, power: r.power, level: r.level, antiVehicle: true, armorKind: 'impact' as const,
      // v0.92.3: under the book a ram is an impact too (armor doesn't count, its passengers are hit; Rigger 2 p. 50).
      ...(RULES.URR_V80.vehDamage.mode === 'urr' || bookRam ? { vehHit: { impact: true } } : {}),
    };
    return this.#runTest(tx('SR2E.Card.Actor.ramsHandling', { vehicleName: vehicle.name, targetName: target.name, setupModeLabel: setup.modeLabel, handling, power: r.power, level: r.level, suffix }), dice, {
      targetNumber: handling, modifiers: [...mods, ...(ramTn ? [{ id: 'ramming', label: tx('SR2E.Card.Mod.ramming'), value: ramTn }] : []), ...(opts.modifiers ?? [])],
      poolDice: mode === 'jumped' ? veh80PoolCap(opts.poolDice ?? 0, setup.poolCap) : 0, pool: 'control',
    }, { kind: 'attack', attack, ram: { vehicleUuid: vehicle.uuid as string, power: r.selfPower, level: r.selfLevel, ...(r.bodyPerSuccess !== undefined ? { bodyPerSuccess: r.bodyPerSuccess } : {}) } });
  }

  /**
   * Fire a vehicle's mounted weapon. This actor is the driver, a gunner aboard, or the vehicle itself
   * (autopilot); the mount decides who may (RULES.VEHICLES). Rolls through attackWith.
   */
  async fireMounted(vehicle: any, weapon: any, opts: AttackOptions = {}): Promise<SuccessTestResult | null> {
    if (!vehicle || vehicle.type !== 'vehicle') return null;
    if (vehicle.system.derived?.destroyed) {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.isDestroyed2', { vehicleName: escHtml(vehicle.name) }));
      return null;
    }
    const mount = String(weapon?.system?.mount ?? 'none');
    let role: FirerRole | null = null;
    if (this.type === 'vehicle') role = this.uuid === vehicle.uuid ? 'autopilot' : null;
    else if (vehicle.system.controllerUuid === this.uuid) role = 'driver';
    else if (vehicle.isAboard(this)) role = 'gunner';
    else if (SR2Actor.securitySiteFor(vehicle)?.system?.riggerUuid === this.uuid && this.sys.rigging?.jumpedIn) role = 'security';
    if (!role) {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.isNeitherAtTheControlsOf', { name: escHtml(this.name), vehicleName: escHtml(vehicle.name) }));
      return null;
    }
    if (role === 'autopilot' && !((vehicle.system.derived?.autopilotRating ?? 0) > 0)) {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.hasNoRatingToFireOn', { vehicleName: escHtml(vehicle.name), part: vehicle.system.drone ? tx('SR2E.Notify.Actor.pilot') : tx('SR2E.Notify.Actor.autonav') }));
      return null;
    }
    if (!canFireMount(mount, role)) {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.cannotBeFiredBy', { weaponName: escHtml(weapon.name), part: mount === 'none' ? tx('SR2E.Notify.Actor.notMounted') : tx('SR2E.Notify.Actor.mount', { mount: escHtml(mount) }), part2: role === 'gunner' ? tx('SR2E.Notify.Actor.aGunner') : role === 'driver' ? tx('SR2E.Notify.Actor.theDriver') : tx('SR2E.Notify.Actor.theAutopilot') }));
      return null;
    }
    // v0.46.0: a fixed mount fires only into its arc (measured from the vehicle token's facing).
    const arc = SR2Actor.arcCheck(vehicle, weapon, opts.targetUuid ?? null);
    if (arc && !arc.inside && RULES.VEHICLES.arcs.enforce !== 'off' && !opts.ignoreArc) {
      const msg = tx('SR2E.Card.Actor.isOutsideSArc', { part: opts.targetUuid ? (fromUuidSync(opts.targetUuid)?.name ?? tx('SR2E.Card.Actor.theTarget2')) : tx('SR2E.Card.Actor.theTarget2'), arcOffBy: arc.offBy, weaponName: weapon.name, weaponArc: weapon.system.arc });
      if (RULES.VEHICLES.arcs.enforce === 'block') {
        ui.notifications?.warn?.(escHtml(msg));
        return null;
      }
      ui.notifications?.info?.(escHtml(msg));
    }
    // v0.49.0: a turret turns to the target: its limit, and its traverse per shot.
    const tur = SR2Actor.turretAim(vehicle, weapon, opts.targetUuid ?? null);
    let extra: TargetNumberModifier[] = [];
    let turretNote = '';
    if (tur) {
      const c = RULES.VEHICLES.turrets;
      const name = opts.targetUuid ? (fromUuidSync(opts.targetUuid)?.name ?? tx('SR2E.Card.Actor.theTarget2')) : tx('SR2E.Card.Actor.theTarget2');
      if (!tur.inLimit && c.enforceLimit !== 'off' && !opts.ignoreTurret) {
        const msg = tx('SR2E.Card.Actor.isOutsideSTurretLimit', { name, turLimitOffBy: tur.limitOffBy, weaponName: weapon.name });
        if (c.enforceLimit === 'block') { ui.notifications?.warn?.(escHtml(msg)); return null; }
        ui.notifications?.info?.(escHtml(msg));
      }
      if (tur.refused && !opts.ignoreTurret) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.canTTurnThatFarIn', { weaponName: escHtml(weapon.name), turNote: escHtml(tur.note) })); return null; }
      extra = tur.modifiers;
      turretNote = `turret ${tur.turn}°`;
    }
    const result = await this.attackWith(weapon, { ...opts, ...(extra.length ? { modifiers: [...(opts.modifiers ?? []), ...extra] } : {}), ...(turretNote ? { note: opts.note ? `${opts.note}; ${turretNote}` : turretNote } : {}), mounted: { vehicleUuid: vehicle.uuid as string, role } });
    // The turret turns only when the shot is made; the GM's client turns it when the gunner can't.
    if (tur && result) await SR2Actor.setTurretFacing(weapon, tur.newFacing, this);
    return result;
  }

  /** v0.50.0: the Fire dialog's live preview of a mounted weapon (what fireMounted would roll), or null. */
  previewMounted(vehicle: any, weapon: any, opts: AttackOptions = {}): (ReturnType<SR2Actor['previewAttack']> & { auto: string[] }) | null {
    if (!vehicle || vehicle.type !== 'vehicle') return null;
    const role = SR2Actor.mountedRole(this, vehicle);
    if (!role) return null;
    const tur = SR2Actor.turretAim(vehicle, weapon, opts.targetUuid ?? null);
    const extra = tur ? tur.modifiers : [];
    const o: AttackOptions = { ...opts, modifiers: [...(opts.modifiers ?? []), ...extra], mounted: { vehicleUuid: vehicle.uuid as string, role } };
    const pv = this.previewAttack(weapon, o);
    // Only what the scene and the firer bring can be switched off, not the weapon's own rules (recoil, turret, mode).
    const targetDoc: any = opts.targetUuid ? fromUuidSync(opts.targetUuid) : null;
    const auto = [...this.#attackVisibilityMods(weapon, o, { melee: false, situational: [], targetDoc }), ...this.#testModifiers({ vehicle: true })].map((m) => modKey(m));
    return { ...pv, auto };
  }

  /**
   * v0.49.0: turn a turret (its owner, or a whispered card the active GM's client applies).
   * v0.81.0 (R2-SEC 3): the card names the firer (`firerUuid`), so the GM's client can check the card's author owns
   * someone who may fire this vehicle's weapons (SR2Actor.mountedRole), as a gunner of someone else's vehicle does.
   */
  static async setTurretFacing(weapon: any, facing: number, firer: any = null): Promise<void> {
    if (!notWritableNow(weapon)) {
      try { await weapon.update({ 'system.turret.facing': facing }); return; } catch { /* fall through */ }
    }
    const gms = [...((game as any).users ?? [])].filter((u: any) => u.isGM).map((u: any) => u.id);
    await ChatMessage.create({ speaker: { alias: weapon?.parent?.name ?? tx('SR2E.Card.Actor.turret') }, whisper: gms, content: `<p><em>${tx('SR2E.Card.Actor.gmOnly')}</em> ${tx('SR2E.Card.Actor.turnsTo', { weaponName: escText(weapon?.name ?? tx('SR2E.Card.Actor.theTurret')), facing: Math.round(facing) })}</p>`,
      flags: { [SYSTEM_ID]: { turretFacing: { weaponUuid: weapon?.uuid ?? '', facing, ...(firer?.uuid ? { firerUuid: String(firer.uuid) } : {}) } } } });
  }

  /**
   * v0.81.0 (R2-SEC 3): the role `firer` has on `vehicle`'s mounted weapons (as previewMounted works it out): the
   * vehicle itself ('autopilot'), its controller ('driver'), someone aboard ('gunner'), or the site's jumped-in
   * security rigger ('security'); null for anyone else. For the GM's client checking a turret card.
   */
  static mountedRole(firer: any, vehicle: any): FirerRole | null {
    if (!firer || !vehicle || vehicle.type !== 'vehicle') return null;
    if (firer.type === 'vehicle') return firer.uuid === vehicle.uuid ? 'autopilot' : null;
    if (vehicle.system?.controllerUuid === firer.uuid) return 'driver';
    if (vehicle.isAboard?.(firer)) return 'gunner';
    if (SR2Actor.securitySiteFor(vehicle)?.system?.riggerUuid === firer.uuid && firer.system?.rigging?.jumpedIn) return 'security';
    return null;
  }

  /**
   * v0.49.0: bringing a turret to bear on a target, from the vehicle token's rotation and the
   * turret's facing (null when it isn't a turret or the tokens aren't on the scene).
   */
  static turretAim(vehicle: any, weapon: any, targetUuid: string | null): ReturnType<typeof turretCheck> | null {
    if ((weapon?.system?.mount ?? 'none') !== 'turret' || !targetUuid) return null;
    try {
      const from: any = tokenOf(vehicle);
      const target: any = fromUuidSync(targetUuid);
      const to: any = target ? tokenOf(target) : null;
      if (!from || !to) return null;
      const c = (t: any) => t.center ?? { x: (t.document?.x ?? t.x ?? 0) + (t.w ?? 0) / 2, y: (t.document?.y ?? t.y ?? 0) + (t.h ?? 0) / 2 };
      const a = c(from), b = c(to);
      const rotation = Number(from.document?.rotation ?? from.rotation ?? 0) + RULES.VEHICLES.arcs.facingOffset;
      const rel = bearingDeg(b.x - a.x, b.y - a.y) - rotation;
      return turretCheck(weapon.system?.turret ?? {}, rel);
    } catch { return null; }
  }

  /**
   * v0.50.0: what a vehicle's sensor test finds by itself: the jumped-in rigger's own penalties, vehicle
   * damage, a weak remote link, range from the tokens (by the Sensor rating), smoke and weather by its
   * sensors, and the target's concealment (a suit or spell that blinds them: `blind`).
   */
  sensorSituation(target: any): { modifiers: TargetNumberModifier[]; blind: boolean; why: string } {
    const out: TargetNumberModifier[] = [];
    if (this.type !== 'vehicle' || !target) return { modifiers: out, blind: false, why: '' };
    const v = this.sys;
    const r = RULES.TN_AUTO.rigging;
    const ctl: any = v.controlMode === 'jumped' ? this.controller?.() : null;
    const rigger: any = ctl?.system?.rigging?.jumpedIn && ctl.system.rigging.vehicleUuid === this.uuid ? ctl : null;
    if (r.sensorPenalties) {
      const dmg = vehicleDamageModifier(v.condition ?? 0);
      if (dmg) out.push({ id: 'vehicleDamage', label: tx('SR2E.Card.Mod.vehicleDamage'), value: dmg });
      if (rigger?.previewModifiers) out.push(...rigger.previewModifiers({ vehicle: true }));
    }
    if (rigger && !this.isAboard(rigger)) out.push(...(rigger.remoteLink?.(this)?.check?.modifiers ?? []));
    // v0.54.0: the control rig's TN bonus, as on driving tests.
    const vcr = Number(rigger?.system?.derived?.rigging?.vcr ?? 0);
    // v0.92.3 (RULES.VEHICLES_V923.vcrTn 'byTest', Rigger 2 p. 28): the sensor test table has no control-rig row.
    if (vcr > 0 && RULES.RIGGING.vcr.tnPerLevel && vcrTnFactor('sensor')) out.push({ label: tx('SR2E.Card.Mod.controlRig', { vcr }), value: RULES.RIGGING.vcr.tnPerLevel * vcr });
    const vision = this.visionNow();
    try {
      const a = SR2Actor.tokenFor(this), b = SR2Actor.tokenFor(target);
      if (a && b) {
        const rg = sensorRangeModifier(measureTokens(a, b)?.metres ?? null, Number(v.derived?.working?.sensor ?? v.sensor ?? 0));
        if (rg) out.push(rg);
        const sm = smokeBetweenTokens(a, b, SR2Actor.sceneFires((canvas as any)?.scene));
        const sl = smokeLook(sm.kind, vision, sm.source);
        if (sl) out.push(sl);
      }
    } catch { /* no canvas */ }
    // v0.79.0: a vehicle's sensors don't take the Visibility Table's weather rows; with the Rigger 2 sensor table on
    // (RULES.DOCS_V79.vehSensorTable 'rigger2') its own fog / precipitation row (+1) replaces the automatic weather.
    const w = RULES.DOCS_V79.vehSensorTable.mode === 'rigger2' ? null : weatherModifier(this.weatherHere(), vision, { fold: false });
    if (w) out.push(w);
    if (target.type !== 'vehicle' && target.concealmentOf) {
      const senses = ['visual', ...(vision.lowLight ? ['lowLight'] : []), ...(vision.thermographic ? ['thermal'] : [])];
      const list = target.concealmentOf();
      let best: { blind: boolean; modifiers: TargetNumberModifier[]; label: string } | null = null;
      for (const sense of senses) {
        const c = SR2Actor.concealmentAgainst(sense, list);
        const sum = (x: typeof c) => (x.blind ? Infinity : x.modifiers.reduce((n, m) => n + m.value, 0));
        if (!best || sum(c) < sum(best)) best = c;
      }
      if (best?.blind) return { modifiers: out, blind: true, why: best.label };
      if (best) out.push(...best.modifiers);
    }
    return { modifiers: out, blind: false, why: '' };
  }

  /**
   * A vehicle's sensor test on a target: Sensor dice (+ its jumped-in rigger's Control Pool) vs the
   * target's Signature + ECM beyond this vehicle's ECCM. A success gives a sensor lock. A target with
   * ECD may notice the scan.
   */
  async sensorTest(targetUuid: string, opts: { poolDice?: number; modifiers?: TargetNumberModifier[]; exclude?: string[] } = {}): Promise<SuccessTestResult | null> {
    if (this.type !== 'vehicle') return null;
    const v = this.sys;
    if (v.derived?.destroyed) {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.isDestroyed', { name: escHtml(this.name) }));
      return null;
    }
    const target: any = await fromUuid(targetUuid);
    if (!target) return null;
    const isVeh = target.type === 'vehicle';
    const t = sensorTarget({ signature: isVeh ? target.system.signature : RULES.VEHICLES.sensors.personSignature, targetEcm: isVeh ? target.system.ecm : 0, scannerEccm: v.eccm ?? 0 });
    const ctl: any = v.controlMode === 'jumped' ? this.controller() : null;
    const rigger = RULES.VEHICLES.sensors.controlPool && ctl?.system?.rigging?.jumpedIn && ctl.system.rigging.vehicleUuid === this.uuid ? ctl : null;
    // v0.59.0: a sensor test takes the operator's action (the driver's, else the vehicle's own).
    const ctlr: any = v.controllerUuid ? this.controller() : null;
    const operator: any = canWriteNow(ctlr) ? ctlr : this;
    // v0.81.0 (D3-3): sensors that can't pick the target up refuse before the action is spent.
    const sit = this.sensorSituation(target);
    if (sit.blind) {
      await ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor: this }), content: `<p><strong>${tx('SR2E.Card.Actor.sSensorsCanTPickUp', { name: escText(this.name), targetName: escText(target.name) })}</strong> (${escText(sit.why)}).</p>` });
      return null;
    }
    if (operator.useAction && !(await operator.useAction('sensor', tx('SR2E.Text.Actor.sSensorTest', { name: this.name })))) return null;
    const pool = rigger ? Math.max(0, Math.min(opts.poolDice ?? 0, rigger.system.derived?.controlPoolLeft ?? 0)) : 0;
    // v0.46.0: passive sensors are harder to use but can't be noticed; a clearsight autosoft helps a drone on its own.
    const mode = sensorModeEffect(v.sensorMode ?? 'active');
    const clearsight = v.controllerUuid ? 0 : autosoftDice(v.autosofts?.clearsight ?? 0, v.derived?.autopilotRating ?? 0);
    const rolls: any[] = [];
    const off = new Set(opts.exclude ?? []);
    // v0.57.0: shot-out sensors work worse.
    const sensor = Number(v.derived?.working?.sensor ?? v.sensor ?? 0);
    const result = await successTest({ dice: sensor + clearsight, poolDice: pool, targetNumber: t.tn, modifiers: [...t.modifiers, ...mode.modifiers, ...sit.modifiers.filter((m) => !modIn(off, m)), ...(opts.modifiers ?? [])], roll: foundryRoller(rolls) });
    if (pool > 0) await (rigger as SR2Actor).#spendPool('control', pool);
    // v0.57.0: a jumped-in rigger's card (their Karma Pool can re-roll it); the vehicle keeps the lock.
    const poster: SR2Actor = (rigger as SR2Actor | null) ?? this;
    await poster.#post(poster.#snapshot((v.sensorMode === 'passive' ? tx('SR2E.Card.Actor.sensorTestOnSensorSignatureWithPassive', { name: this.name, targetName: target.name, sensor, part2: clearsight ? tx('SR2E.Card.Actor.clearsightAutosoft', { clearsight }) : '', part3: pool ? tx('SR2E.Card.Actor.controlPool2', { pool }) : '', tn: t.tn }) : tx('SR2E.Card.Actor.sensorTestOnSensorSignaturePlain', { name: this.name, targetName: target.name, sensor, part2: clearsight ? tx('SR2E.Card.Actor.clearsightAutosoft', { clearsight }) : '', part3: pool ? tx('SR2E.Card.Actor.controlPool2', { pool }) : '', tn: t.tn })), result, {
      kind: 'sensor', sensor: { targetUuid: target.uuid as string, targetName: target.name as string, vehicleUuid: this.uuid as string },
    }), result, rolls);
    // Electronic counter-detection: the target may notice it is being scanned (not passive sensors).
    if (isVeh && (target.system.ecd ?? 0) > 0 && mode.noticeable) {
      const ecdRolls: any[] = [];
      const ecd = await successTest({ dice: target.system.ecd, targetNumber: RULES.VEHICLES.sensors.ecdTn, roll: foundryRoller(ecdRolls) });
      await ChatMessage.create({
        speaker: ChatMessage.getSpeaker({ actor: target }),
        content: describeResult(tx('SR2E.Card.Actor.ecdCounterDetection', { targetName: target.name, targetEcd: target.system.ecd }), ecd) + `<p>${ecd.successes > 0 ? `<strong>${tx('SR2E.Card.Actor.noticesTheScan', { targetName: escText(target.name) })}</strong>` : tx('SR2E.Card.Actor.theScanGoesUnnoticed')}</p>`,
        rolls: ecdRolls,
      });
    }
    return result;
  }

  /** A sensor test's outcome: a success puts (or refreshes) a sensor lock on the target. */
  async #resolveSensor(snap: TestSnapshot): Promise<Resolved> {
    const sn = snap.sensor!;
    const s = snap.successes;
    const veh: any = sn.vehicleUuid ? (fromUuidSync(sn.vehicleUuid) ?? this) : this;
    // v0.73.0 (O27): a lock remembers when it was made or refreshed (NETRIG_V73.sensorLocks).
    const locks: any[] = [...(veh.system?.locks ?? [])].map((l: any) => ({ targetUuid: l.targetUuid, targetName: l.targetName, successes: l.successes, round: l.round ?? -1, worldTime: l.worldTime ?? -1, combatId: String(l.combatId ?? '') })).filter((l) => l.targetUuid !== sn.targetUuid);
    if (s > 0) locks.push({ targetUuid: sn.targetUuid, targetName: sn.targetName, successes: s, ...sensorLockStamp(SR2Actor.matrixNow()) });
    if (notWritableNow(veh)) {
      // A player's re-roll of a GM vehicle's sensor test: the GM applies the lock.
      const gms = [...((game as any).users ?? [])].filter((u: any) => u.isGM).map((u: any) => u.id);
      await ChatMessage.create({
        speaker: { alias: veh.name }, whisper: gms, blind: true,
        content: `<p><em>${tx('SR2E.Card.Actor.gmOnly')}</em> · <strong>${escText(veh.name)}</strong>${tx('SR2E.Card.Actor.sensorLockOn', { snTargetName: escText(sn.targetName), part: s > 0 ? `(${escText(plural(s, 'success'))})` : tx('SR2E.Card.Actor.lost') })} <button type="button" data-sr2e-action="applyLocks">${tx('SR2E.Card.Actor.applyGm')}</button></p>`,
        flags: { [SYSTEM_ID]: { sensorLocks: { vehicleUuid: veh.uuid, targetUuid: sn.targetUuid, targetName: sn.targetName, successes: s, sourceUuid: this.uuid } } },
      });
    } else {
      try { await veh.update({ 'system.locks': locks }); } catch { /* the vehicle's owner (the GM) can set it */ }
    }
    return {
      html: s > 0 ? `<p><strong>${tx('SR2E.Card.Actor.detected', { snTargetName: escText(sn.targetName) })}</strong> ${tx('SR2E.Card.Actor.sensorLockForGunnery', { plural: escText(plural(s, 'success')) })}</p>` : `<p><strong>${tx('SR2E.Card.Actor.isNotDetected', { snTargetName: escText(sn.targetName) })}</strong></p>`,
      flags: {}, snap,
    };
  }

  /** GM: set (successes > 0) or drop a vehicle's sensor lock on a target, from a player's card. */
  static async applySensorLock(c: { vehicleUuid: string; targetUuid: string; targetName: string; successes: number }): Promise<boolean> {
    const veh: any = await fromUuid(c.vehicleUuid);
    if (!veh) return false;
    const locks: any[] = [...(veh.system?.locks ?? [])].map((l: any) => ({ targetUuid: l.targetUuid, targetName: l.targetName, successes: l.successes, round: l.round ?? -1, worldTime: l.worldTime ?? -1, combatId: String(l.combatId ?? '') })).filter((l) => l.targetUuid !== c.targetUuid);
    if (c.successes > 0) locks.push({ targetUuid: c.targetUuid, targetName: c.targetName, successes: c.successes, ...sensorLockStamp(SR2Actor.matrixNow()) });
    await veh.update({ 'system.locks': locks });
    return true;
  }

  /** v0.73.0 (O27): drop sensor locks that have lapsed (time, range, gone, sensors shot out); the active GM runs it. */
  static async lapseSensorLocks(): Promise<void> {
    if (!RULES.NETRIG_V73.sensorLocks.enabled || !isLeadGm()) return;
    const now = SR2Actor.matrixNow();
    for (const veh of SR2Actor.tickActors().filter((a: any) => a.type === 'vehicle' && (a.system?.locks ?? []).length) as any[]) {
      const vt = SR2Actor.tokenFor(veh);
      const metres: Record<string, number | null> = {};
      if (vt) for (const l of veh.system.locks) {
        const target: any = fromUuidSync(l.targetUuid);
        const tt = target ? SR2Actor.tokenFor(target) : null;
        metres[l.targetUuid] = tt ? (measureTokens(vt, tt)?.metres ?? null) : null;
      }
      const r = sweepSensorLocks([...veh.system.locks], { now, metres, sensorRating: Number(veh.system.derived?.working?.sensor ?? veh.system.sensor ?? 0), sensorsOut: Boolean(veh.system.systems?.sensors) });
      if (!r.dropped.length) continue;
      await veh.update({ 'system.locks': r.keep.map((l: any) => ({ targetUuid: l.targetUuid, targetName: l.targetName, successes: l.successes, round: l.round ?? -1, worldTime: l.worldTime ?? -1, combatId: String(l.combatId ?? '') })) });
      await ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor: veh }), content: `<p><strong>${escText(veh.name)}</strong> ${tCount(r.dropped.length, 'SR2E.Card.Actor.losesItsSensorLocks', { dropped: r.dropped.map((d) => `${escText(d.targetName)} (${escText(d.why)})`).join('; ') })}</p>` });
    }
  }

  /** Drop all sensor locks (or one target's). */
  async clearLocks(targetUuid: string | null = null): Promise<void> {
    const locks = targetUuid ? [...(this.sys.locks ?? [])].filter((l: any) => l.targetUuid !== targetUuid) : [];
    await this.update({ 'system.locks': locks });
  }

  /** Drones subscribed to this rigger's remote control deck. */
  subscribedDrones(): any[] {
    return [...(this.sys.rigging?.subscribed ?? [])].map((u: string) => fromUuidSync(u)).filter((d: any) => d?.type === 'vehicle');
  }

  /** Subscribe a vehicle to this rigger's remote control deck (up to its capacity). */
  async subscribeDrone(drone: any): Promise<boolean> {
    const r = this.sys.derived?.rigging;
    if (!r?.rcd) {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.hasNoRemoteControlDeck', { name: escHtml(this.name) }));
      return false;
    }
    const list: string[] = [...(this.sys.rigging?.subscribed ?? [])];
    if (list.includes(drone.uuid)) return true;
    if (list.length >= rcdCapacity(r.rcd)) {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.sRemoteControlDeckHoldsDrones', { name: escHtml(this.name), rcdCapacity: rcdCapacity(r.rcd) }));
      return false;
    }
    await this.update({ 'system.rigging.subscribed': [...list, drone.uuid] });
    return true;
  }

  async unsubscribeDrone(uuid: string): Promise<void> {
    await this.update({ 'system.rigging.subscribed': [...(this.sys.rigging?.subscribed ?? [])].filter((u: string) => u !== uuid) });
  }

  /** A group command: every subscribed drone makes the same driving test (each on its own autopilot or driver). */
  async groupDrive(opts: DriveOptions = {}): Promise<number> {
    // v0.59.0: a command to the subscribed drones takes the rigger's action (RULES.ACTIONS.costs.droneCommand).
    if (!(await this.useAction('droneCommand', tx('SR2E.Card.Actor.aCommandToTheDrones')))) return 0;
    let n = 0;
    for (const d of this.subscribedDrones()) {
      if (d.system.derived?.destroyed || !this.#canCommand(d)) continue;
      if (await d.driveTest({ ...opts, poolDice: 0 })) n++;
    }
    if (!n) ui.notifications?.warn?.(tx('SR2E.Notify.Actor.hasNoWorkingSubscribedDrones', { name: escHtml(this.name) }));
    return n;
  }

  /** A group command: every subscribed drone fires its first mounted weapon at the target on its own autopilot. */
  async groupAttack(targetUuid: string, opts: AttackOptions = {}): Promise<number> {
    if (!(await this.useAction('droneCommand', tx('SR2E.Card.Actor.aCommandToTheDrones')))) return 0;
    let n = 0;
    for (const d of this.subscribedDrones()) {
      if (d.system.derived?.destroyed || !this.#canCommand(d)) continue;
      const w: any = [...d.items].find((i: any) => i.type === 'weapon' && canFireMount(i.system.mount, 'autopilot'));
      if (!w) continue;
      // v0.50.0: each drone measured from its own token (range band, distance); else the band picked.
      let own: Partial<AttackOptions> = {};
      try {
        const a = SR2Actor.tokenFor(d), b = SR2Actor.tokenFor(fromUuidSync(targetUuid));
        const m = a && b ? measureTokens(a, b) : null;
        if (m) { const band = rangeBandForDistance(m.metres, weaponRange(w.system, 0)); own = { range: band ?? 'extreme', measuredMetres: m.metres, ...(band ? {} : { outOfRange: true }) }; }
      } catch { /* no canvas */ }
      if (await d.fireMounted(d, w, { range: 'short', ...opts, ...own, targetUuid, poolDice: 0 })) n++;
    }
    if (!n) ui.notifications?.warn?.(tx('SR2E.Notify.Actor.noneOfSSubscribedDronesCould', { name: escHtml(this.name) }));
    return n;
  }

  /** Start (or update) a chase: this vehicle pursues the quarry at a gap in metres. */
  async startChase(quarry: any, metres: number): Promise<void> {
    if (this.type !== 'vehicle' || quarry?.type !== 'vehicle') return;
    await this.update({ 'system.chase.quarryUuid': quarry.uuid, 'system.chase.metres': Math.max(0, metres) });
    await ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor: this }), content: `<p><strong>${escText(this.name)}</strong> ${tx('SR2E.Card.Actor.givesChaseTo')} <strong>${escText(quarry.name)}</strong>${tx('SR2E.Card.Actor.mBehind', { metres: Math.round(metres) })}</p>` });
  }

  async endChase(): Promise<void> {
    await this.update({ 'system.chase.quarryUuid': '', 'system.chase.metres': 0 });
  }

  /**
   * One chase turn (GM): the gap drifts by the difference in current speed, then both drivers make a
   * positioning test (the faster one gets a TN bonus); net successes move the gap.
   */
  async chaseTurn(opts: { pursuer?: DriveOptions; quarry?: DriveOptions } = {}): Promise<{ metres: number } | null> {
    const c = this.sys.chase;
    const quarry: any = c?.quarryUuid ? fromUuidSync(c.quarryUuid) : null;
    if (this.type !== 'vehicle' || !quarry) {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.isNotChasingAnyone', { name: escHtml(this.name) }));
      return null;
    }
    const ps = Number(this.sys.currentSpeed ?? 0), qs = Number(quarry.system.currentSpeed ?? 0);
    const pm = chaseSpeedModifier(ps, qs), qm = chaseSpeedModifier(qs, ps);
    const pr = await this.driveTest({ ...(opts.pursuer ?? {}), kind: 'maneuver', label: tx('SR2E.Card.Actor.positioningChase'), modifiers: [...(opts.pursuer?.modifiers ?? []), ...(pm ? [{ id: 'faster', label: tx('SR2E.Card.Mod.faster'), value: pm }] : [])] });
    const qr = await quarry.driveTest({ ...(opts.quarry ?? {}), kind: 'maneuver', label: tx('SR2E.Card.Actor.positioningChase'), modifiers: [...(opts.quarry?.modifiers ?? []), ...(qm ? [{ id: 'faster', label: tx('SR2E.Card.Mod.faster'), value: qm }] : [])] });
    const before = Number(c.metres ?? 0);
    // v0.57.0 (Rigger 2 style): maneuver scores from the positioning successes and speed win a firing position.
    const scored = RULES.VEHICLES_V57.maneuver.mode === 'score';
    const pScore = scored ? maneuverScore({ successes: pr?.successes ?? 0, speed: ps }) : (pr?.successes ?? 0);
    const qScore = scored ? maneuverScore({ successes: qr?.successes ?? 0, speed: qs }) : (qr?.successes ?? 0);
    const r = chaseTurn({ metres: before, pursuerSpeed: ps, quarrySpeed: qs, pursuerSuccesses: pScore, quarrySuccesses: qScore });
    await this.update({ 'system.chase.metres': r.metres });
    let posNote = '';
    if (scored) {
      const pos = maneuverPosition(pScore, qScore);
      const combat: any = (game as any).combat;
      const round = combat?.started ? Number(combat.round ?? 0) : -1;
      const won = pos.winner === 'a' ? this : pos.winner === 'b' ? quarry : null;
      const lost = pos.winner === 'a' ? quarry : pos.winner === 'b' ? this : null;
      // v0.81.1 (RA2-4): stamped with its combat, so another fight's round of the same number doesn't count it.
      const value: VehiclePosition = { winnerUuid: won?.uuid ?? '', loserUuid: lost?.uuid ?? '', tn: won ? pos.tn : 0, round, combatId: combat?.started ? String(combat.id ?? '') : '' };
      for (const v of [this, quarry]) { try { await v.update({ 'system.position': value }); } catch { /* the GM can */ } }
      posNote = won && pos.tn ? `<p>${tx('SR2E.Card.Actor.maneuverScoreVs', { pScore, qScore: escText(qScore) })} <strong>${escText(won.name)}</strong> ${tx('SR2E.Card.Actor.hasThePositionTnFiringAt', { posTn: pos.tn, lostName: escText(lost!.name) })}</p>` : `<p>${tx('SR2E.Card.Actor.maneuverScoreVsNobodyHasThe', { pScore, qScore: escText(qScore) })}</p>`;
    }
    const moved = await SR2Actor.placeChaseTokens(this, quarry, r.metres);
    const fmt = (n: number) => `${n >= 0 ? '+' : ''}${Math.round(n * 10) / 10} m`;
    await ChatMessage.create({
      speaker: ChatMessage.getSpeaker({ actor: this }),
      content: `<div class="sr2e-roll"><h3>${tx('SR2E.Card.Actor.chaseAfter', { name: escText(this.name), quarryName: escText(quarry.name) })}</h3>
        <p>${tx('SR2E.Card.Actor.speedVsVs', { ps, qs, drift: escText(fmt(r.drift)), part: scored ? tx('SR2E.Card.Actor.maneuverScore') : tx('SR2E.Card.Actor.positioning'), pScore, qScore: escText(qScore), shift: escText(fmt(r.shift)), part2: r.winner === 'none' ? '' : tx('SR2E.Card.Actor.gains3', { part: escText(r.winner === 'pursuer' ? this.name : quarry.name) }) })}</p>
        <p>${tx('SR2E.Card.Actor.gap')} <strong>${Math.round(before * 10) / 10} → ${r.metres} m</strong>${r.metres <= 0 ? ` — <strong>${tx('SR2E.Card.Actor.catchesUp', { name: escText(this.name) })}</strong>` : ''}</p>${posNote}${moved}</div>`,
    });
    return { metres: r.metres };
  }

  /** The gap in metres between two vehicles if one is chasing the other (null if not). */
  static chaseGap(a: any, b: any): number | null {
    if (!a || !b) return null;
    if (a.system?.chase?.quarryUuid === b.uuid) return Number(a.system.chase.metres ?? 0);
    if (b.system?.chase?.quarryUuid === a.uuid) return Number(b.system.chase.metres ?? 0);
    return null;
  }

  /**
   * A vehicle dodging: the Control Pool of a rigger jumped into it; v0.57.0: or its manual driver
   * (RULES.VEHICLES_V57.evasion: a driving test with Combat Pool dice, or Combat Pool only).
   */
  async #defendVehicle(attack: AttackState, poolDice: number): Promise<void> {
    // v0.92.3 (RULES.VEHICLES_V923.vehicleDodge 'none', Rigger 2 p. 53): a vehicle makes no dodge test; its rigger's Control
    // Pool goes on the damage resistance instead (RULES.VEHICLES_V923.cpResist).
    if (veh923('vehicleDodge') === 'none') {
      const rolls0: any[] = [];
      const r0 = await successTest({ dice: 0, poolDice: 0, targetNumber: attack.targetNumber, roll: foundryRoller(rolls0) });
      await this.#post(this.#snapshot(tx('SR2E.Card.Actor.vehicleNoDodge', { name: this.name }), r0, { kind: 'defend', defendAgainst: attack }), r0, rolls0);
      return;
    }
    const ctl: any = this.sys.controlMode === 'jumped' ? this.controller() : null;
    const rigger = ctl?.system?.rigging?.jumpedIn && ctl.system.rigging.vehicleUuid === this.uuid ? ctl : null;
    const ev = RULES.VEHICLES_V57.evasion.manual;
    const driver: any = !rigger && this.sys.controlMode === 'manual' && this.sys.controllerUuid ? this.controller() : null;
    if (driver && ev !== 'none' && !this.sys.derived?.destroyed) return (driver as SR2Actor).#manualEvasion(this, attack, poolDice);
    const left = rigger ? ((rigger.system.derived?.controlPoolLeft as number | undefined) ?? 0) : 0;
    const pool = this.sys.derived?.destroyed ? 0 : Math.max(0, Math.min(poolDice, left));
    const rolls: any[] = [];
    // v0.71.0 (R5): a jumped-in rigger evades as a driver does: a driving test (vehicle skill, the control rig's help,
    // against Handling) with the Control Pool, not the pool dice alone.
    if (rigger && RULES.FIXES_V71.riggerDodge === 'skill' && !this.sys.derived?.destroyed) {
      const setup = (rigger as SR2Actor).#driveSetup({ vehicle: this, quiet: true, kind: 'evasion' });
      if (setup && !('delegate' in setup)) {
        const cp = veh80PoolCap(pool, setup.poolCap);
        const r = await successTest({ dice: setup.dice, poolDice: cp, targetNumber: setup.handling, modifiers: (rigger as SR2Actor).#testModifiers({ modifiers: setup.mods, vehicle: true }), roll: foundryRoller(rolls) });
        if (cp > 0) await (rigger as SR2Actor).#spendPool('control', cp);
        await this.#post(this.#snapshot(tx('SR2E.Card.Actor.evasiveDrivingJumpedInHandling', { name: this.name, riggerName: rigger.name, setupHandling: setup.handling, setupSuffix: setup.suffix, part: cp ? tx('SR2E.Card.Actor.controlPool3', { cp }) : '' }), r, { kind: 'defend', defendAgainst: attack }), r, rolls);
        return;
      }
    }
    // v0.73.0 (O26): the rig's TN bonus on the Control-Pool dodge too (the driving-test dodge has it through drivingModifiers).
    const rigMods = controlRigTn({ test: 'evasion', vcr: Number(rigger?.system?.derived?.rigging?.vcr ?? 0), jumpedIn: Boolean(rigger) } as any);
    const result = await successTest({ dice: 0, poolDice: pool, targetNumber: attack.targetNumber, ...(rigMods.length ? { modifiers: rigMods } : {}), roll: foundryRoller(rolls) });
    if (pool > 0 && rigger) await (rigger as SR2Actor).#spendPool('control', pool);
    await this.#post(this.#snapshot(pool > 0 ? tx('SR2E.Card.Actor.evasiveDrivingControlPool', { riggerName: rigger.name }) : tx('SR2E.Card.Actor.defenseNoControlPoolDice'), result, { kind: 'defend', defendAgainst: attack }), result, rolls);
  }

  /** v0.57.0: a manual driver evades with the vehicle: a driving test (+ Combat Pool) or Combat Pool alone; the card is the vehicle's defense. */
  async #manualEvasion(vehicle: any, attack: AttackState, poolDice: number): Promise<void> {
    const ev = RULES.VEHICLES_V57.evasion.manual;
    const pool = Math.max(0, Math.min(poolDice, Number(this.sys.derived?.combatPoolLeft ?? 0)));
    const rolls: any[] = [];
    let result: SuccessTestResult;
    let label: string;
    if (ev === 'driving') {
      const setup = this.#driveSetup({ vehicle, quiet: true, kind: 'evasion' });
      if (!setup || 'delegate' in setup) {
        result = await successTest({ dice: 0, poolDice: pool, targetNumber: attack.targetNumber, roll: foundryRoller(rolls) });
        label = tx('SR2E.Card.Actor.evasiveDrivingNoDrivingTestPossible', { vehicleName: vehicle.name, name: this.name });
      } else {
        result = await successTest({ dice: setup.dice, poolDice: pool, targetNumber: setup.handling, modifiers: this.#testModifiers({ modifiers: setup.mods, vehicle: true }), roll: foundryRoller(rolls) });
        label = tx('SR2E.Card.Actor.evasiveDrivingHandling', { vehicleName: vehicle.name, name: this.name, setupHandling: setup.handling, setupSuffix: setup.suffix, part: pool ? tx('SR2E.Card.Actor.combatPool', { pool }) : '' });
      }
    } else {
      result = await successTest({ dice: 0, poolDice: pool, targetNumber: attack.targetNumber, roll: foundryRoller(rolls) });
      label = tx('SR2E.Card.Actor.evasiveDrivingCombatPool', { vehicleName: vehicle.name, name: this.name, pool });
    }
    if (pool > 0) await this.#spendPool('combat', pool);
    await (vehicle as SR2Actor).#post((vehicle as SR2Actor).#snapshot(label, result, { kind: 'defend', defendAgainst: attack }), result, rolls);
  }

  /**
   * A vehicle resists damage: normal weapons are reduced, armor at or above the Power stops it,
   * otherwise Body vs Power − Armor (no pool); damage goes on the vehicle's condition track.
   */
  async resistVehicleDamage(damage: DamageState, poolDice = 0): Promise<void> {
    if (this.type !== 'vehicle') return;
    const v = this.sys;
    // v0.92.3 (RULES.VEHICLES_V923.ram 'book', Rigger 2 p. 50): a ram is collision damage: no armor, no weapon reduction.
    const bookImpact = Boolean(damage.vehHit?.impact || damage.ramSelf) && veh923('ram') === 'book';
    const armor = damage.ignoreArmor || bookImpact ? 0 : armorAfterAmmo(v.armor ?? 0, damage.armorMultiplier ?? 1) + Math.max(0, damage.extraArmor ?? 0);
    // v0.79.0 (RULES.DOCS_V79.rangedFlechette 'armor', SRII p. 93): no armor, so flechette's extra level.
    if (damage.flechette && !(armor > 0)) damage = { ...damage, level: flechetteSoak({ ballistic: 0, impact: 0, level: damage.level }).level };
    const inc = veh80Incoming({
      power: damage.power, level: damage.level, armor, antiVehicle: Boolean(damage.antiVehicle), crash: Boolean(damage.crash) || bookImpact, damageType: damage.damageType,
      body: Number(v.body ?? 0), rawArmor: Number(v.armor ?? 0), armorMultiplied: (damage.armorMultiplier ?? 1) < 1, ignoreArmor: Boolean(damage.ignoreArmor), hit: damage.vehHit ?? null,
    });
    const what = damage.crash ? tx('SR2E.Card.Actor.crash2', { power: damage.power, level: damage.level }) : `${damage.power}${damage.level}`;
    if (inc.stopped || !inc.level) {
      await ChatMessage.create({
        speaker: ChatMessage.getSpeaker({ actor: this }),
        content: `<div class="sr2e-roll"><h3>${tx('SR2E.Card.Actor.resists2', { name: escText(this.name), what: escText(what) })}</h3></div><p><strong>${tx('SR2E.Card.Actor.noDamage3')}</strong>${inc.notes.length ? ` (${escText(inc.notes.join('; '))})` : ''}.</p>`,
      });
      return;
    }
    const rolls: any[] = [];
    // v0.80.0 (URR_V80.vehCpResist): the jumped-in rigger's Control Pool dice on the vehicle's damage resistance.
    // v0.92.3 (RULES.VEHICLES_V923.cpResist 'driving', Rigger 2 pp. 50, 53): the book's way, at most the rigger's skill.
    const cpCtl: any = veh80ResistPoolOn() && v.controlMode === 'jumped' ? this.controller() : null;
    const cpRigger: any = cpCtl?.system?.rigging?.jumpedIn && cpCtl.system.rigging.vehicleUuid === this.uuid && canWriteNow(cpCtl) ? cpCtl : null;
    const cp = cpRigger ? veh80ResistPool(poolDice, Number(cpRigger.system.derived?.controlPoolLeft ?? 0), (cpRigger as SR2Actor).vehicleSkillRating(this)) : 0;
    // v0.92.3 (RULES.VEHICLES_V923.body0 'destroyed', Rigger 2 p. 53): a Body 0 vehicle is destroyed by any hit that gets through.
    if (!(Number(v.body ?? 0) > 0) && veh923('body0') === 'destroyed' && !damage.crash) {
      const r0 = await successTest({ dice: 0, targetNumber: inc.tn, roll: foundryRoller(rolls) });
      await this.#post(this.#snapshot(tx('SR2E.Card.Actor.bodyZeroDestroyed', { name: this.name, incPower: inc.power, incLevel: inc.level }), r0, {
        kind: 'soak', soak: { mode: 'stage', noun: 'damage', level: 'D', type: 'physical', body: 0, before: { physical: 0, stun: 0 }, track: 'vehicle', vehicleBefore: v.condition ?? 0, power: inc.power },
      }), r0, rolls);
      return;
    }
    const result = await successTest({ dice: v.body ?? 0, ...(cp ? { poolDice: cp } : {}), targetNumber: inc.tn, roll: foundryRoller(rolls) });
    if (cp > 0) await (cpRigger as SR2Actor).#spendPool('control', cp);
    const notes = [tx('SR2E.Card.Actor.body2', { body: v.body }), ...(cp ? [tx('SR2E.Card.Actor.controlPool', { cp })] : []), ...(armor && inc.armor ? [tx('SR2E.Card.Actor.armor2', { armor })] : []), ...inc.notes];
    await this.#post(this.#snapshot((damage.crash ? tx('SR2E.Card.Actor.resists3WithCrash2', { name: this.name, incPower: inc.power, incLevel: inc.level, notes: notes.join(', ') }) : tx('SR2E.Card.Actor.resists3Plain', { name: this.name, incPower: inc.power, incLevel: inc.level, notes: notes.join(', ') })), result, {
      kind: 'soak',
      soak: { mode: 'stage', noun: 'damage', level: inc.level, type: 'physical', body: v.body ?? 0, before: { physical: 0, stun: 0 }, track: 'vehicle', vehicleBefore: v.condition ?? 0, power: inc.power, ...(damage.crash ? { crash: true } : {}), ...(damage.ramSelf ? { ramSelf: true } : {}), ...((damage as any).vehHit?.impact ? { vehImpact: true } : {}),
        ...(cp ? { controlUsed: cp } : {}), ...(damage.attackHits !== undefined ? { attackHits: Math.max(0, Number(damage.attackHits) || 0) } : {}),
        ...(damage.vehiclePart ? { vehiclePart: damage.vehiclePart, ...(damage.vehicleWeaponId ? { vehicleWeaponId: damage.vehicleWeaponId } : {}) } : {}) },
    }), result, rolls);
  }

  /** Apply damage on a vehicle's condition track; feedback or dump shock for a jumped-in rigger. */
  async #resolveVehicleSoak(snap: TestSnapshot, fu: FollowUps): Promise<Resolved> {
    const ctx = snap.soak as SoakContext;
    const level = resolveResistance(ctx.level, snap.successes);
    const before = ctx.vehicleBefore ?? 0;
    const result = applyVehicleDamage(before, level);
    const current = (this.sys.condition as number | undefined) ?? 0;
    const expected = ctx.vehicleAfter ?? before;
    const max = RULES.VEHICLES.conditionBoxes;
    let note = '';
    let stuckRigger = '';
    if (current === expected) {
      await this.update({ 'system.condition': result.after }, { sr2eSoak: true });
      const ctl: any = this.sys.controlMode === 'jumped' ? this.controller() : null;
      const rigger = ctl?.system?.rigging?.jumpedIn && ctl.system.rigging.vehicleUuid === this.uuid ? ctl : null;
      if (result.destroyed && current < max) {
        try { await (this as any).toggleStatusEffect?.('dead', { active: true, overlay: true }); } catch { /* no token */ }
        if (rigger) {
          // v0.92.3 (RULES.VEHICLES_V923.feedback 'book', Rigger 2 p. 49): a rigger jumped in aboard resists 6S Physical when
          // the vehicle is destroyed (the rigger damage), not dump shock; a remote rigger still takes the deck's dump shock.
          const fbD = veh923('feedback') === 'book' && this.isAboard(rigger) ? veh80Feedback({ level: 'D', power: ctx.power ?? 0 }) : null;
          fu.riggerShock = fbD
            ? { riggerUuid: rigger.uuid, riggerName: rigger.name, tn: fbD.tn, level: fbD.level, type: fbD.type, kind: 'feedback', ...(fbD.attribute ? { attribute: fbD.attribute } : {}) }
            : { riggerUuid: rigger.uuid, riggerName: rigger.name, ...dumpShockFor(rigger, !this.isAboard(rigger)), kind: 'dump' };
          // v0.81.1 (D3-12): a rigger this client can't unplug (another player's) is left to the GM, and the card says so.
          if (canWriteNow(rigger)) { try { await rigger.update({ 'system.rigging.vehicleUuid': '', 'system.rigging.jumpedIn': false }); } catch (err) { console.warn('sr2e | rigger dumped', err); stuckRigger = String(rigger.name ?? ''); } }
          else stuckRigger = String(rigger.name ?? '');
          await this.update({ 'system.controllerUuid': '', 'system.controlMode': 'autopilot' });
        }
      } else if (rigger && level && ctx.vehicleAfter === undefined) {
        const fb = veh80Feedback({ level, power: ctx.power ?? 0 });
        if (fb) fu.riggerShock = { riggerUuid: rigger.uuid, riggerName: rigger.name, tn: fb.tn, level: fb.level, type: fb.type, kind: 'feedback', ...(fb.attribute ? { attribute: fb.attribute } : {}) };
      }
      // An attack (not a crash) that damages the vehicle carries through to the people aboard.
      // v0.73.0 (O25): the rammer's own share carries through to its passengers too (NETRIG_V73.ram.passengers).
      // v0.92.3 (RULES.VEHICLES_V923.passengers 'targeted', Rigger 2 p. 50): under the book a crash's damage reaches them
      // after the vehicle's test (at the level it left), as a collision's does.
      const bookCrash = Boolean(ctx.crash) && !ctx.ramSelf && veh923('passengers') === 'targeted';
      if (level && (bookCrash || ramPassengersHurt({ crash: ctx.crash, ramSelf: ctx.ramSelf } as any)) && ctx.vehicleAfter === undefined) {
        const pd = veh80PassengerDamage({ power: ctx.power ?? 0, level, vehicleArmor: this.sys.armor ?? 0, impact: Boolean(ctx.ramSelf || (ctx as any).vehImpact || bookCrash) });
        const aboard = [...(this.sys.occupants ?? [])].filter((u: string) => u && fromUuidSync(u));
        if (this.sys.controllerUuid && this.sys.controlMode === 'manual' && !aboard.includes(this.sys.controllerUuid)) aboard.push(this.sys.controllerUuid);
        if (pd && aboard.length) fu.passengers = aboard.map((u: string) => ({ targetUuid: u, melee: false, damageType: 'physical' as DamageType, power: pd.power, level: pd.level, armorKind: 'impact' as const }));
      }
    } else {
      note = ` <em>${tx('SR2E.Card.Actor.theVehicleSDamageChangedSince', { resultAfter: result.after })}</em>`;
    }
    // v0.92.3 (Rigger 2 p. 53): no damage, and more Control Pool dice used than the attacker's successes: a complete miss.
    const cleanMiss = level === null && Number(ctx.controlUsed ?? 0) > 0 && ctx.attackHits !== undefined && Number(ctx.controlUsed) > Number(ctx.attackHits);
    const body = level === null
      ? outcomeWord('fullyResisted', false) + (cleanMiss ? ` <strong>${tx('SR2E.Card.Actor.vehicleCompleteMiss')}</strong>` : '')
      : takenMark(level, 'vehicle', tx('SR2E.Card.Outcome.takesVehicle', { level: `<strong>${level}</strong>`, plural: escText(plural(result.boxes, 'box')), resultAfter: result.after, max }))
        + (result.destroyed ? ` <strong>${tx('SR2E.Card.Actor.destroyed2')}</strong>` : '') + (stuckRigger ? ` <em>${tx('SR2E.Card.Actor.gmTakeOutOfTheVehicle', { stuckRigger: escText(stuckRigger) })}</em>` : '');
    // v0.57.0: a called shot's effect on the part hit (once), and a crash test after heavy damage.
    let extra = '';
    let flags: Record<string, unknown> = {};
    let partApplied = Boolean(ctx.partApplied);
    const part = ctx.vehiclePart ? vehiclePart(ctx.vehiclePart) : null;
    let tiresHit = false;
    if (part && level && !partApplied && current === expected && !result.destroyed) {
      partApplied = true;
      try {
        if (part.id === 'tires' || part.id === 'sensors' || part.id === 'engine') {
          await this.update({ [`system.systems.${part.id}`]: true });
          tiresHit = part.id === 'tires';
          extra += ` <strong>${escText(part.label)} ${part.id === 'tires' ? tx('SR2E.Card.Actor.shotOut') : tx('SR2E.Card.Actor.damaged')}</strong> ${tx('SR2E.Card.Actor.untilRepaired')}`;
        } else if (part.id === 'mount') {
          const w: any = (ctx.vehicleWeaponId ? this.items.get(ctx.vehicleWeaponId) : null) ?? [...this.items].find((i: any) => i.type === 'weapon' && (i.system?.mount ?? 'none') !== 'none' && !i.system?.jammed);
          if (w) { await w.update({ 'system.jammed': true }); extra += ` <strong>${tx('SR2E.Card.Actor.isKnockedOut', { name: escText(w.name) })}</strong> ${tx('SR2E.Card.Actor.jammedUntilClearedOrRepaired')}`; }
        }
      } catch { extra += ` <em>${tx('SR2E.Card.Actor.gmApplyTheCalledShotBy')}</em>`; }
    }
    const moving = Number(this.sys.currentSpeed ?? 0) > 0;
    // v0.92.3 (RULES.VEHICLES_V923.autoCrash 'book', Rigger 2 p. 53): a moving vehicle whose monitor fills crashes, no test.
    if (level && result.destroyed && current < max && current === expected && moving && !ctx.crash && veh923('autoCrash') === 'book') {
      extra += `</p><p>${tx('SR2E.Card.Actor.destroyedVehicleCrashes', { name: escText(this.name) })} <button type="button" data-sr2e-action="vehicleCrash">${tx('SR2E.Card.Actor.crashDamagePower', { power: veh80CrashDamage(Number(this.sys.currentSpeed ?? 0)).power })}</button>`;
      flags = { crash: { vehicleUuid: this.uuid, speed: Number(this.sys.currentSpeed ?? 0) } };
    }
    // v0.92.3 (RULES.VEHICLES_V923.ram 'book', Rigger 2 p. 47): any damage from a ram (to either vehicle) calls for a Crash Test.
    const ramCrash = Boolean(level) && moving && !result.destroyed && Boolean(ctx.ramSelf || (ctx as any).vehImpact) && veh923('ram') === 'book';
    const crashCall = level && ctx.vehicleAfter === undefined && current === expected && (ramCrash || (!ctx.crash && ((tiresHit && moving) || crashTestAfterDamage(level, moving, result.destroyed))));
    if (crashCall) {
      const tn = tiresHit ? Number(part?.crashTn ?? 0) : 0;
      extra += `</p><p><button type="button" data-sr2e-action="vehicleCrashTest">${tx('SR2E.Card.Actor.crashTest', { name: escText(this.name), part: tn ? tx('SR2E.Card.Actor.forTheTires', { tn }) : '' })}</button>`;
      flags = { crashTest: { vehicleUuid: this.uuid, tn, why: tiresHit ? tx('SR2E.Card.Actor.tiresShotOut') : tx('SR2E.Card.Actor.vehicleDamage') } };
    }
    return { html: `<p>${body}${note}${extra}</p>`, flags, snap: { ...snap, soak: { ...ctx, vehicleAfter: result.after, partApplied } } };
  }

  /** v0.57.0: a crash test called for (heavy damage, tires shot out): the driver, or the autopilot. */
  async crashTestFor(o: { tn?: number; why?: string } = {}): Promise<SuccessTestResult | null> {
    if (this.type !== 'vehicle') return null;
    return this.driveTest({ crashTest: true, label: tx('SR2E.Card.Actor.crashTestWhy', { why: o.why ?? tx('SR2E.Card.Actor.damageWord') }), ...(o.tn ? { modifiers: [{ label: o.why ?? tx('SR2E.Card.Mod.crash'), value: o.tn }] } : {}) });
  }

  /**
   * v0.57.0 (Acceleration): the speed this vehicle may reach this Combat Turn. In a started combat,
   * speed changes by at most its Accel (braking: × the brake multiplier) from where the Combat Turn
   * began, plus anything a push won (RULES.VEHICLES_V57.accel).
   */
  speedWindow(): { limited: boolean; start: number; extra: number; round: number | null; min: number; max: number } {
    const combat: any = (game as any).combat;
    const inCombat = Boolean(combat?.started);
    const round = inCombat ? Number(combat.round ?? 0) : null;
    const st = this.sys.speedTurn ?? { round: -1, start: 0, extra: 0 };
    const cur = Number(this.sys.currentSpeed ?? 0);
    const same = round != null && Number(st.round) === round;
    const start = same ? Number(st.start ?? cur) : cur;
    const extra = same ? Number(st.extra ?? 0) : 0;
    const accel = Number(this.sys.accel ?? 0);
    const up = clampSpeed({ accel, turnStart: start, to: Number.MAX_SAFE_INTEGER, extra }).speed;
    const down = clampSpeed({ accel, turnStart: start, to: 0, extra }).speed;
    return { limited: speedLimited(inCombat), start, extra, round, min: down, max: up };
  }

  /** v0.57.0: push past this Combat Turn's Acceleration: a driving test (each success adds another Accel); then the speed is set. */
  async pushSpeed(to: number, opts: DriveOptions = {}): Promise<SuccessTestResult | null> {
    if (this.type !== 'vehicle') return null;
    return this.driveTest({ ...opts, push: Math.max(0, Math.round(to)) });
  }

  /** v0.57.0: a push test's outcome: the extra change it won this Combat Turn, then the speed it allows. */
  async #resolvePush(snap: TestSnapshot): Promise<Resolved> {
    const d = snap.drive!;
    const veh: any = fromUuidSync(d.vehicleUuid);
    const r = pushResult(snap.successes, snap.botch, Number(veh?.system?.accel ?? 0));
    let html: string;
    let flags: Record<string, unknown> = {};
    if (d.pushApplied) return { html: `<p><em>${tx('SR2E.Card.Actor.thePushWasAlreadyAppliedAdjust')}</em></p>`, flags, snap };
    if (veh && r.extra > 0) {
      const win = veh.speedWindow();
      const round = win.round ?? -1;
      let gm = '';
      try {
        await veh.update({ 'system.speedTurn': { round, start: win.start, extra: win.extra + r.extra } });
        await veh.update({ 'system.currentSpeed': d.push });
      } catch { gm = ` <em>${tx('SR2E.Card.Actor.gmSetSSpeedUpTo', { vehicleName: escText(d.vehicleName), value: escText(win.start + Number(veh.system?.accel ?? 0) + win.extra + r.extra) })}</em>`; }
      const now = Number(veh.system?.currentSpeed ?? 0);
      html = `<p><strong>${tx('SR2E.Card.Actor.isPushed', { vehicleName: escText(d.vehicleName) })}</strong> ${tx('SR2E.Card.Actor.moreChangeThisCombatTurnSpeed', { plural: escText(plural(snap.successes, 'success')), extra: r.extra })} <strong>${now}</strong>${now !== d.push ? tx('SR2E.Card.Actor.ofAsked', { push: d.push }) : ''}.${gm}</p>`;
    } else {
      html = `<p><strong>${tx('SR2E.Card.Actor.thePushFails')}</strong> ${tx('SR2E.Card.Actor.changesSpeedOnlyByItsAcceleration', { vehicleName: escText(d.vehicleName) })}</p>`;
    }
    if (r.crash) {
      html += `<p><strong>${tx('SR2E.Card.Actor.disaster5')}</strong> <button type="button" data-sr2e-action="vehicleCrashTest">${tx('SR2E.Card.Actor.crashTest2', { vehicleName: escText(d.vehicleName) })}</button></p>`;
      flags = { crashTest: { vehicleUuid: d.vehicleUuid, tn: 0, why: tx('SR2E.Card.Actor.aPushGoneWrong') } };
    }
    // Applied once something happened (a re-roll of a plain failure can still push).
    return { html, flags, snap: { ...snap, drive: { ...d, pushApplied: r.extra > 0 || r.crash } } };
  }

  /**
   * v0.57.0 (Rigger 2 style design): build this vehicle from a chassis and powerplant with design
   * points spent on stats (RULES.VEHICLES_V57.design). Writes the stats; returns the price.
   */
  async applyDesign(o: { chassis: string; powerplant: string; spend: Record<string, number> }): Promise<{ cost: number; warnings: string[] } | null> {
    if (this.type !== 'vehicle') return null;
    const d = designVehicle(o);
    if (!d) {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.pickAChassisAndAPowerplant'));
      return null;
    }
    const st = d.stats;
    await this.update({
      'system.body': st.body, 'system.handling': st.handling, 'system.speed': st.speed, 'system.accel': st.accel, 'system.armor': st.armor,
      'system.signature': st.signature, 'system.cargoFactor': st.cf,
    });
    const ch = RULES.VEHICLES_V57.design.chassis.find((c) => c.id === o.chassis);
    const pp = RULES.VEHICLES_V57.design.powerplants.find((c) => c.id === o.powerplant);
    await ChatMessage.create({
      speaker: ChatMessage.getSpeaker({ actor: this }),
      content: `<p><strong>${escText(this.name)}</strong> ${tx('SR2E.Card.Actor.isDesignedBodyHandlingSpeedAccel', { chLabel: escText(ch?.label ?? o.chassis), ppLabel: escText(pp?.label ?? o.powerplant), stBody: st.body, stHandling: st.handling, stSpeed: st.speed, stAccel: st.accel, stArmor: st.armor, stSignature: st.signature, stCf: st.cf, part: st.mounts ? tCount(st.mounts, 'SR2E.Card.Actor.weaponMounts') : '', pointsSpent: d.points.spent, pointsTotal: d.points.total })} <strong>${d.cost.toLocaleString()}¥</strong>.${d.warnings.length ? ` <strong class="sr2e-warn">${d.warnings.map(escText).join('; ')}</strong>` : ''}</p>`,
    });
    return { cost: d.cost, warnings: d.warnings };
  }

  /** A rigger resists feedback or dump shock: Willpower (v0.79.0: Body for a deck's dump shock) vs the TN, staged down by successes. */
  async rollRiggerShock(r: { tn: number; level: DamageLevel; type: DamageType; kind: 'feedback' | 'dump'; attribute?: 'body' | 'willpower' }): Promise<void> {
    await this.#drainTest({
      label: r.kind === 'dump' ? tx('SR2E.Card.Actor.riggerDumpShock') : tx('SR2E.Card.Actor.riggerFeedback'), attribute: r.attribute === 'body' ? 'body' : 'willpower', targetNumber: r.tn,
      level: r.level, type: r.type, poolDice: 0, noun: 'damage', physicalNote: tx('SR2E.Card.Actor.physicalNote'),
    });
    // v0.92.3 (RULES.VEHICLES_V923.dumpDisorient 'book', Rigger 2 p. 64): the book's disorientation too.
    if (r.kind === 'dump' && (RULES.URR_V80.dsDumpDisorient || veh923('dumpDisorient') === 'book')) await this.dsDisorientTest();
  }

  /**
   * v0.80.0 (RULES.URR_V80.dsDumpDisorient, URR): after dump shock, Willpower vs 4: +2 TN on skill tests for
   * 10 Combat Turns ÷ successes (rounded down). The card says so; the GM applies the TN. Returns the turns.
   */
  async dsDisorientTest(): Promise<number> {
    const rolls: any[] = [];
    const r = await successTest({ dice: Number(this.sys.attributes?.willpower?.total ?? 0), targetNumber: dsDisorientation(0).testTn, roll: foundryRoller(rolls) });
    const d = dsDisorientation(r.successes);
    await ChatMessage.create({
      speaker: ChatMessage.getSpeaker({ actor: this }), rolls,
      content: `${describeResult(tx('SR2E.Card.Actor.shakesOffTheDumpWillpower', { name: this.name }), r)}<p>${d.turns > 0 ? `<strong>${tx('SR2E.Card.Actor.disoriented')}</strong>${tCount(d.turns, 'SR2E.Card.Actor.tnOnSkillTestsForCombat', { tn: d.tn })}` : tx('SR2E.Card.Actor.notDisoriented')}</p>`,
    });
    return d.turns;
  }

  /** A vehicle crashes: a card with crash damage for it and for everyone aboard (the manual driver too). */
  async crash(speed?: number): Promise<void> {
    if (this.type !== 'vehicle') return;
    const v = this.sys;
    const sp = Math.max(0, Number(speed ?? v.currentSpeed ?? 0));
    const c0 = veh80CrashDamage(sp);
    const c = { ...c0, passengerLevel: veh80CrashPassengerLevel(c0.passengerLevel, c0.vehicleLevel) };
    // v0.57.0: a crashed vehicle has stopped.
    try { await this.update({ 'system.currentSpeed': 0 }, { sr2eSpeedOk: true }); } catch { /* not the owner */ }
    const aboard: string[] = [...(v.occupants ?? [])];
    if (v.controllerUuid && v.controlMode === 'manual' && !aboard.includes(v.controllerUuid)) aboard.push(v.controllerUuid);
    const damages: DamageState[] = [{
      targetUuid: this.uuid as string, melee: false, damageType: 'physical', power: c.power, level: c.vehicleLevel, crash: true,
      ...(RULES.VEHICLES.crash.vehicleArmor ? {} : { ignoreArmor: true }),
    }];
    // v0.92.3 (RULES.VEHICLES_V923.passengers 'targeted', Rigger 2 p. 50): under the book the people aboard take the crash
    // after the vehicle's own test, at the level it left (#resolveVehicleSoak); the card says so.
    const afterVehicle = veh923('passengers') === 'targeted';
    for (const u of afterVehicle ? [] : aboard) {
      if (u && fromUuidSync(u)) damages.push({ targetUuid: u, melee: false, damageType: 'physical', power: c.power, level: c.passengerLevel, armorKind: 'impact' });
    }
    const rows = damages.map((d, i) => `<li>${escText(fromUuidSync(d.targetUuid)?.name ?? tx('SR2E.Card.Actor.someone'))}: <strong>${d.power}${d.level}</strong>${i === 0 ? '' : tx('SR2E.Card.Actor.impactArmor2')} <button type="button" data-sr2e-action="resist" data-index="${i}">${tx('SR2E.Card.Actor.resist')}</button></li>`).join('');
    await ChatMessage.create({
      speaker: ChatMessage.getSpeaker({ actor: this }),
      content: `<div class="sr2e-roll"><h3>${tx('SR2E.Card.Actor.crashesSpeed', { name: escText(this.name), sp })}</h3><p>${afterVehicle ? tx('SR2E.Card.Actor.powerTheVehicleTakesThenAboard', { power: c.power, vehicleLevel: c.vehicleLevel, part: RULES.VEHICLES.crash.vehicleArmor ? '' : tx('SR2E.Card.Actor.armorDoesNotCount') }) : tx('SR2E.Card.Actor.powerTheVehicleTakesEveryoneAboard', { power: c.power, vehicleLevel: c.vehicleLevel, part: RULES.VEHICLES.crash.vehicleArmor ? '' : tx('SR2E.Card.Actor.armorDoesNotCount'), passengerLevel: c.passengerLevel })}</p></div><ul class="sr2e-blast">${rows}</ul>`,
      flags: { [SYSTEM_ID]: { damages, damage: damages[0] } },
    });
  }

  /**
   * Repair a vehicle (v0.38.0): this character's Build/Repair skill (the first of
   * RULES.SKILLS.vehicleRepair.skills they have; else Intelligence at +4) vs TN; each success repairs boxes.
   */
  async repairVehicleTest(vehicle: any, opts: { modifiers?: TargetNumberModifier[]; tools?: string } = {}): Promise<{ repaired: number } | null> {
    if (vehicle?.type !== 'vehicle') return null;
    const vr = RULES.SKILLS.vehicleRepair;
    const fx = RULES.FIXES_V71.vehicleRepair;
    const before = Number(vehicle.system.condition ?? 0);
    const sys = vehicle.system.systems ?? {};
    const partsOut = fx.enabled && (sys.tires || sys.engine || sys.sensors);
    if (before <= 0 && !partsOut) { ui.notifications?.info?.(tx('SR2E.Notify.Actor.isUndamaged', { vehicleName: escHtml(vehicle.name) })); return { repaired: 0 }; }
    const skill = vr.skills.map((n) => this.findSkill(n)).find((x: any) => x && (x.system?.rating ?? 0) > 0);
    const sd = this.#skillDice(skill, false, null, 'intelligence');
    // v0.71.0 (R18): the B/R tools at hand (a shop by default; less adds to the TN, none may refuse it).
    const toolMods: TargetNumberModifier[] = [];
    let toolNote = '';
    if (fx.enabled) {
      const own = this.toolsFor(String(skill?.name ?? vr.skills[0] ?? ''));
      // v0.71.0 review (F9): tools at hand named in the dialog count when better than the mechanic's own.
      const order = RULES.CHARACTERS_V58.tools.levels.map((l) => l.id);
      const have = opts.tools && order.indexOf(opts.tools) > order.indexOf(own) ? opts.tools : own;
      const t = toolsModifier(String(fx.needs ?? 'shop'), have);
      if (t.blocked) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.canTRepair', { name: escHtml(this.name), vehicleName: escHtml(vehicle.name), tNote: escHtml(t.note) })); return null; }
      if (t.modifier) toolMods.push(t.modifier);
      toolNote = t.note;
    }
    const rolls: any[] = [];
    const r = await successTest({ dice: sd.dice, targetNumber: veh80RepairTn(before, vr.tn), modifiers: this.#testModifiers({ modifiers: [...(opts.modifiers ?? []), ...sd.modifiers, ...toolMods] }), roll: foundryRoller(rolls) });
    const destroyed = Boolean(vehicle.system.derived?.destroyed);
    // v0.79.0 (RULES.DOCS_V79.vehRepair 'rigger2', Rigger 2 p26): any success fixes it all, 16 h per box ÷ successes;
    // 'perSuccess': the old plan (v0.71.0 parts and rebuilds when FIXES_V71.vehicleRepair.enabled).
    const plan = vehicleRepairByMode({ successes: r.successes, condition: before, systems: sys, destroyed, boxesPerSuccess: vr.boxesPerSuccess, hoursPerBox: vr.hoursPerBox, partsFirst: Boolean(fx.partsFirst), rebuild: fx.destroyed === 'rebuild', rebuildFactor: Number(fx.rebuildFactor ?? 2), fixEnabled: Boolean(fx.enabled) });
    const repaired = plan.boxes;
    const any = repaired > 0 || plan.parts.length > 0;
    // v0.65.0: the repair takes its hours: the boxes come off when the work is done.
    const later = any && plan.hours > 0 && this.waitsFor('vehicles');
    if (any && !later) await SR2Actor.#applyVehicleRepair(vehicle, repaired, plan.parts, plan.rebuild);
    const what = tList([repaired ? plural(repaired, 'box') : '', plan.parts.length ? tx('SR2E.Card.Actor.theParts', { parts: plan.parts.join(', ') }) : '']);
    const lead = plan.rebuild ? `<strong>${tx('SR2E.Card.Actor.aFullRebuild')}</strong> ${tx('SR2E.Card.Actor.ofEverything', { vehicleName: escText(vehicle.name), what: escText(what || tx('SR2E.Card.Actor.nothingLeftToFix')) })}`
      : destroyed && fx.enabled && fx.destroyed === 'rebuild' ? tx('SR2E.Card.Actor.noProgressADestroyedVehicleNeeds')
      : any ? `<strong>${later ? tx('SR2E.Card.Actor.whatToRepair', { what: escText(what) }) : tx('SR2E.Card.Actor.whatRepaired', { what: escText(what) })}</strong>${repaired ? ` (${before} → ${before - repaired})` : ''}` : '';
    await ChatMessage.create(withRollMode({
      speaker: ChatMessage.getSpeaker({ actor: this }),
      content: `${describeResult(tx('SR2E.Card.Actor.repairs2', { name: this.name, vehicleName: vehicle.name, skillName: skill?.name ?? tx('SR2E.Card.Actor.noBRSkill'), sdSuffix: sd.suffix }), r)}<p>${any ? tCount(plan.hours, 'SR2E.Card.Actor.hoursOfWork2', { lead, part: later ? tx('SR2E.Card.Actor.upkeepTabUnderWay') : '' }) : lead || tx('SR2E.Card.Actor.noProgress2')}</p>${toolNote && fx.enabled ? `<p class="hint">${tx('SR2E.Card.Actor.tools', { toolNote: escText(toolNote) })}</p>` : ''}`,
      rolls,
    }));
    if (later) await this.startProject({ kind: 'vrepair', area: 'vehicles', label: plan.rebuild ? `Rebuilding ${vehicle.name}` : `Repairing ${vehicle.name} (${what})`, hours: plan.hours, effect: { call: { method: 'finishVehicleRepair', args: [vehicle.uuid, repaired, plan.parts, plan.rebuild] } } });
    return { repaired };
  }

  /** v0.65.0: a vehicle repair's time has passed: its boxes come off (v0.71.0: and its parts are fixed; a rebuild clears all). */
  async finishVehicleRepair(vehicleUuid: string, boxes: number, parts: string[] = [], rebuild = false): Promise<boolean> {
    const v: any = fromUuidSync(vehicleUuid);
    if (!v) return false;
    return SR2Actor.#applyVehicleRepair(v, boxes, parts, rebuild);
  }

  static async #applyVehicleRepair(v: any, boxes: number, parts: string[] = [], rebuild = false): Promise<boolean> {
    const update: Record<string, unknown> = { 'system.condition': rebuild ? 0 : Math.max(0, Number(v.system.condition ?? 0) - Math.max(0, Number(boxes) || 0)) };
    for (const k of (rebuild ? ['tires', 'engine', 'sensors'] : parts ?? [])) if (['tires', 'engine', 'sensors'].includes(k)) update[`system.systems.${k}`] = false;
    await v.update(update);
    // v0.71.0 (R18): no longer destroyed: the dead marker comes off.
    if (!v.system?.derived?.destroyed) { try { await v.toggleStatusEffect?.('dead', { active: false, overlay: true }); } catch { /* no token */ } }
    return true;
  }

  /** v0.65.0: a mod installation's time has passed: it goes in (and the payer pays then). */
  async finishModInstall(vehicleUuid: string, index: number, payerUuid: string | null, modName = '', prepaid = 0, prepaidBy: string | null = null): Promise<boolean> {
    return (await this.#finishModInstall(vehicleUuid, index, payerUuid, modName, prepaid, prepaidBy)) === 'applied';
  }

  /** Round 2 (V-DOC 3): `finishModInstall` saying whether the up-front money went back ('refunded'). */
  async #finishModInstall(vehicleUuid: string, index: number, payerUuid: string | null, modName = '', prepaid = 0, prepaidBy: string | null = null): Promise<'applied' | 'refunded' | 'failed'> {
    const v: any = fromUuidSync(vehicleUuid);
    // v0.73.0 (O43): paid up front and not going in: the payer gets it back.
    const back = async (): Promise<'refunded' | 'failed'> => (prepaid > 0 && (await this.refundModPayer(prepaidBy, prepaid, `Installing ${modName}`)) !== false ? 'refunded' : 'failed');
    if (!v?.installMod) return back();
    // The list may have changed meanwhile: find the mod by its name.
    const mods: any[] = [...(v.system?.mods ?? [])];
    // Review fix: a mod saved without a name is listed under its kind's label: keep it when it is still there and not in.
    const unnamedHere = !String(mods[index]?.name ?? '') && mods[index] && !mods[index].installed;
    if (modName && !unnamedHere && String(mods[index]?.name ?? '') !== modName) {
      const at = mods.findIndex((m: any) => String(m?.name ?? '') === modName && !m?.installed);
      if (at < 0) return back();
      index = at;
    }
    const payer: any = payerUuid ? fromUuidSync(payerUuid) : null;
    const ok = Boolean(await v.installMod(index, { payer }));
    return ok ? 'applied' : back();
  }

  /** v0.73.0 (O43): a mod paid for up front isn't going in: the payer gets it back (a project call). */
  async refundModPayer(payerUuid: string | null, cost: number, label: string): Promise<boolean> {
    const payer: any = payerUuid ? await fromUuid(payerUuid) : null;
    const n = Math.max(0, Math.round(Number(cost) || 0));
    if (!payer || !n) return true;
    // v0.81.0 (SEC1-2): paid straight away only to a payer this actor's players own (a project's flag is theirs to write).
    if (canWriteNow(payer) && this.#projectMayTouch(payer)) await payer.adjustNuyen(n, `Given up (refund): ${label}`);
    // v0.81.1 (D3-6): on the GM's clock a card would be GM-authored (its Apply skips the confirm), so a player's
    // project naming a payer its players don't own (never so in play: the sheet lists only their own) is refused.
    else if (this.#playerOwners().length && isGmNow()) { console.warn(`sr2e | refund to ${payer.name} refused: ${this.name}'s players don't own them`); return false; }
    else await SR2Actor.gmActorCard(payer.uuid, { nuyen: { amount: n, label: `Given up (refund): ${String(label).slice(0, 200)}` }, by: this.uuid as string }, tx('SR2E.Card.Actor.giveBackFromSProjectData', { payerName: escText(payer.name), n: n.toLocaleString(), slice: escText(String(label).slice(0, 200)), name: escText(this.name) }));
    return true;
  }

  /** v0.71.0 (R18): destroyed outside the soak path: mark it, and dump a jumped-in rigger (dump shock card). */
  async #destroyedElsewhere(): Promise<void> {
    try { await (this as any).toggleStatusEffect?.('dead', { active: true, overlay: true }); } catch { /* no token */ }
    const ctl: any = this.sys.controlMode === 'jumped' ? this.controller() : null;
    const rigger = ctl?.system?.rigging?.jumpedIn && ctl.system.rigging.vehicleUuid === this.uuid ? ctl : null;
    if (!rigger) return;
    const r: RiggerShock = { riggerUuid: rigger.uuid, riggerName: rigger.name, ...dumpShockFor(rigger, !this.isAboard(rigger)), kind: 'dump' };
    let stuck = false;
    try { await rigger.update({ 'system.rigging.vehicleUuid': '', 'system.rigging.jumpedIn': false }); } catch (err) { console.warn('sr2e | rigger dumped', err); stuck = true; }
    try { await this.update({ 'system.controllerUuid': '', 'system.controlMode': 'autopilot' }); } catch (err) { console.warn('sr2e | vehicle released', err); stuck = true; }
    await ChatMessage.create({
      speaker: ChatMessage.getSpeaker({ actor: this }),
      content: `<p><strong>${tx('SR2E.Card.Actor.isDestroyed', { name: escText(this.name) })}</strong>${tx('SR2E.Card.Actor.isDumpedOutOfIt2', { riggerName: escText(r.riggerName), part: stuck ? ` <em>${tx('SR2E.Card.Actor.gmTakeThemOutOfThe')}</em>` : '' })}</p><p><button type="button" data-sr2e-action="riggerShock">${tx('SR2E.Card.Actor.resistDumpShockVs', { riggerName: escText(r.riggerName), shockAttr: shockAttr(r), tn: r.tn, level: r.level, type: r.type })}</button></p>`,
      flags: { [SYSTEM_ID]: { riggerShock: r } },
    });
  }

  /** Vehicle: repair all damage. */
  async repairVehicle(): Promise<void> {
    if (this.type !== 'vehicle') return;
    // v0.57.0: shot-out systems are repaired too.
    await this.update({ 'system.condition': 0, 'system.systems': { tires: false, sensors: false, engine: false } });
    try { await (this as any).toggleStatusEffect?.('dead', { active: false, overlay: true }); } catch { /* no token */ }
  }


  // ---------------------------------------------------------------- Rigging leftovers (v0.46.0)

  /** This rigger's remote control deck signal (gear `signal`, else its base flux: v0.79.0 2, RULES.DOCS_V79.signalFlux; old: its RCD rating). */
  rcdSignal(): number {
    const decks = [...this.items].filter((i: any) => i.type === 'gear' && (i.system?.rcdRating ?? 0) > 0 && isCarried(i));
    return decks.reduce((n: number, i: any) => Math.max(n, rcdFlux({ signal: i.system.signal, rcdRating: i.system.rcdRating })), 0);
  }

  /** The remote link from this rigger to a vehicle: its signal, the distance between their tokens (km), and the range check. */
  remoteLink(vehicle: any): { signal: number; km: number; check: SignalCheck } {
    const signal = this.rcdSignal();
    let km = 0;
    try {
      const a = tokenOf(this), b = tokenOf(vehicle);
      const m = a && b ? measureTokens(a, b) : null;
      if (m) km = m.metres / 1000;
    } catch { /* no canvas */ }
    return { signal, km, check: signalCheck(signal, km) };
  }

  /** Whether this rigger can send a drone a group command: not jammed, and in range unless that only warns. */
  #canCommand(drone: any): boolean {
    // v0.73.0 (O28): a link taken over by a spoofer refuses its own rigger's commands too (jamming as before).
    const blk = droneCommandBlock(drone.system);
    if (blk.blocked) {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.ignoresTheCommand', { droneName: escHtml(drone.name), blkReason: escHtml(blk.reason) }));
      return false;
    }
    const link = this.remoteLink(drone);
    if (link.check.checked && !link.check.inRange) {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.isOutOfRange', { droneName: escHtml(drone.name), checkNote: escHtml(link.check.note), part: RULES.SIGNAL.outOfRange === 'block' ? '' : tx('SR2E.Notify.Actor.itActsAnyway') }));
      return RULES.SIGNAL.outOfRange !== 'block';
    }
    return true;
  }

  /** A jammer's rating: a vehicle's ECM, else the best jammer gear. */
  jammerRating(): number {
    if (this.type === 'vehicle') return Math.max(0, Number(this.sys.ecm ?? 0));
    return [...this.items].filter((i: any) => i.type === 'gear' && isCarried(i)).reduce((n: number, i: any) => Math.max(n, Math.floor(i.system?.jammer ?? 0)), 0);
  }

  /**
   * Jam a drone's remote link (RULES.RIGGING.jamming): the jammer's rating vs TN = the link's
   * signal (+ the drone's ECCM). Any success cuts the link: a rigger jumped in from outside is
   * pushed out, and remote control and group commands are refused until it is cleared.
   */
  async jamTest(targetUuid: string, opts: { rating?: number; modifiers?: TargetNumberModifier[] } = {}): Promise<{ jammed: boolean } | null> {
    const drone: any = await fromUuid(targetUuid);
    // v0.49.0: a decker on a wireless connection can be jammed too.
    if (drone && ['character', 'npc'].includes(drone.type)) return this.#jamDecker(drone, opts);
    if (!drone || drone.type !== 'vehicle') {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.pickAVehicleADroneOr'));
      return null;
    }
    const rating = Math.max(0, Math.floor(opts.rating ?? this.jammerRating()));
    if (!(rating > 0)) {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.hasNoJammerAVehicleS', { name: escHtml(this.name) }));
      return null;
    }
    const ctl: any = drone.controller?.() ?? null;
    const remoteRigger = ctl && drone.system.controlMode === 'jumped' && !drone.isAboard(ctl) ? ctl : null;
    const subscriber: any = allActors().find((a: any) => (a.system?.rigging?.subscribed ?? []).includes(drone.uuid)) ?? null;
    const rigger: any = remoteRigger ?? subscriber;
    const signal = rigger?.rcdSignal?.() ?? 0;
    const tn = jamTarget({ signal, eccm: drone.system.eccm ?? 0 });
    const rolls: any[] = [];
    const r = await successTest({ dice: rating, targetNumber: tn, modifiers: opts.modifiers ?? [], roll: foundryRoller(rolls) });
    const jammed = r.successes > 0;
    let body = '';
    let gmFlag: Record<string, unknown> = {};
    const applyHere = canWriteNow(drone) && (!remoteRigger || canWriteNow(remoteRigger));
    if (jammed) {
      if (applyHere) {
        await SR2Actor.applyJam(drone.uuid, this.name as string, rating, { shockCard: false });
        if (remoteRigger) body = tx('SR2E.Card.Actor.isPushedOutOf', { remoteRiggerName: escText(remoteRigger.name), droneName: escText(drone.name) });
      } else {
        body = ` <button type="button" data-sr2e-action="applyJam">${tx('SR2E.Card.Actor.applyGm')}</button>`;
        gmFlag = { jam: { droneUuid: drone.uuid, by: this.name, rating, jammerUuid: this.uuid } };
      }
    }
    // v0.81.0 (D3-7): the dump shock button only once the jam is applied here; else the GM's Apply posts it.
    const dump = jammed && remoteRigger && RULES.RIGGING.jamming.dumpShock && applyHere;
    const ds = dumpShockFor(remoteRigger, true);
    await ChatMessage.create({
      speaker: ChatMessage.getSpeaker({ actor: this }),
      content: `${describeResult(tx('SR2E.Card.Actor.jamsJammerVsSignal', { name: this.name, droneName: drone.name, rating, signal, part: RULES.RIGGING.jamming.eccmAddsTn && drone.system.eccm ? tx('SR2E.Card.Actor.eccm', { droneEccm: drone.system.eccm }) : '' }), r)}<p>${jammed ? `<strong>${tx('SR2E.Card.Actor.sLinkIsJammed', { droneName: escText(drone.name) })}</strong>${tx('SR2E.Card.Actor.noRemoteControlOrGroupCommands', { body })}` : tx('SR2E.Card.Actor.sLinkHolds', { droneName: escText(drone.name) })}</p>${dump ? `<p><button type="button" data-sr2e-action="riggerShock">${tx('SR2E.Card.Actor.resistDumpShockVs2', { remoteRiggerName: escText(remoteRigger.name), shockAttr: shockAttr(ds), dsTn: ds.tn, dsLevel: ds.level, dsType: ds.type })}</button></p>` : ''}`,
      rolls,
      flags: { [SYSTEM_ID]: { ...gmFlag, ...(dump ? { riggerShock: { riggerUuid: remoteRigger.uuid, riggerName: remoteRigger.name, ...ds, kind: 'dump' } } : {}) } },
    });
    return { jammed };
  }

  /** v0.73.0 (O28): the facts a drone-link test needs: the link kind, its rigger and deck, the encryption. */
  #droneLinkFacts(drone: any) {
    const ctl: any = drone.controller?.() ?? null;
    const kind = droneLinkKind({ controlMode: String(drone.system.controlMode ?? 'autopilot'), controllerAboard: Boolean(ctl && drone.isAboard(ctl)), hasController: Boolean(ctl) });
    const subscriber: any = allActors().find((a: any) => (a.system?.rigging?.subscribed ?? []).includes(drone.uuid)) ?? null;
    const rigger: any = (kind.remoteJumped ? ctl : null) ?? subscriber;
    const deck: any = rigger ? [...rigger.items].filter((i: any) => i.type === 'gear' && (i.system?.rcdRating ?? 0) > 0 && !i.system?.damaged && isCarried(i))
      .sort((a: any, b: any) => b.system.rcdRating - a.system.rcdRating)[0] ?? null : null;
    const link = droneLinkOf(drone.system);
    return {
      kind, rigger, link, rcd: Number(deck?.system?.rcdRating ?? 0), signal: rigger?.rcdSignal?.() ?? 0,
      encryption: linkEncryption({ drone: link.encryption, rcd: Number(deck?.system?.radio?.encryption ?? 0) }),
    };
  }

  /** v0.73.0 (O28): this character's link gear: best remote control deck and radio ratings. */
  #linkGear(): { rcd: number; radio: number } {
    const g = [...this.items].filter((i: any) => i.type === 'gear' && !i.system?.damaged && isCarried(i));
    return {
      rcd: g.reduce((n: number, i: any) => Math.max(n, Number(i.system?.rcdRating ?? 0)), 0),
      radio: g.reduce((n: number, i: any) => Math.max(n, Number(i.system?.radio?.rating ?? 0)), 0),
    };
  }

  /**
   * v0.73.0 (O28, 5-A9): intercept a drone's remote link: the link skill vs its encryption
   * (RULES.DRONES_V73.link.intercept). Any success marks it intercepted by this character.
   */
  async interceptDroneLink(targetUuid: string, opts: { modifiers?: TargetNumberModifier[] } = {}): Promise<{ intercepted: boolean } | null> {
    const L = RULES.DRONES_V73.link;
    const drone: any = await fromUuid(targetUuid);
    if (!L.enabled || !drone || drone.type !== 'vehicle') { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.pickADroneOrVehicleTo')); return null; }
    // v0.92.3 (RULES.VEHICLES_V923.interception 'book', Rigger 2 p. 68): the interceptor's own deck rolls the test, so it needs one.
    const bookIntercept = veh923('interception') === 'book';
    const gear = bookIntercept ? 'rcd' : L.intercept.gear;
    if (!linkGearOk(gear, this.#linkGear())) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.needsToInterceptADroneS', { name: escHtml(this.name), linkGearLabel: linkGearLabel(gear) })); return null; }
    const f = this.#droneLinkFacts(drone);
    const skillName = String(L.skill);
    const sd = this.#skillDice(this.findSkill(skillName), false, null, L.attribute as AttributeKey, { skillName });
    const t = droneInterceptTest({ dice: sd.dice, encryption: f.encryption, signal: f.signal, eccm: Number(drone.system.eccm ?? 0), linked: f.kind.linked });
    if (!t.allowed) { ui.notifications?.warn?.(`${escHtml(drone.name)}: ${escHtml(f.kind.note)}.`); return null; }
    if (RULES.URR_V80.dsLinkIntercept === 'rcd' || bookIntercept) return this.#dsInterceptDroneLink(drone, f, opts);
    const rolls: any[] = [];
    const r = await successTest({ dice: t.dice, targetNumber: t.baseTn, modifiers: [...sd.modifiers, ...t.modifiers, ...(opts.modifiers ?? [])], roll: foundryRoller(rolls) });
    const ok = r.successes > 0;
    const c = { droneUuid: drone.uuid, kind: 'intercept' as const, byUuid: this.uuid, by: String(this.name) };
    let body = '';
    let gmFlag: Record<string, unknown> = {};
    if (ok) {
      if (canWriteNow(drone)) await SR2Actor.applyDroneLink(c);
      else { body = ` <button type="button" data-sr2e-action="applyDroneLink">${tx('SR2E.Card.Actor.applyGm')}</button>`; gmFlag = { droneLink: c }; }
    }
    await ChatMessage.create({
      speaker: ChatMessage.getSpeaker({ actor: this }), rolls, flags: { [SYSTEM_ID]: gmFlag },
      content: `${describeResult(tx('SR2E.Card.Actor.interceptsSLink', { name: this.name, droneName: drone.name, skillName, sdSuffix: sd.suffix, part: f.encryption ? tx('SR2E.Card.Actor.encryption2', { encryption: f.encryption }) : tx('SR2E.Card.Actor.unencrypted') }), r)}<p>${ok ? `<strong>${tx('SR2E.Card.Actor.linkIntercepted')}</strong>${tx('SR2E.Card.Actor.hearsItsTrafficAndCanTry', { name: escText(this.name), part: f.rigger ? tx('SR2E.Card.Actor.itsRigger', { riggerName: escText(f.rigger.name) }) : '', body })}` : tx('SR2E.Card.Actor.theLinkStaysClosed')}</p>`,
    });
    return { intercepted: ok };
  }

  /**
   * v0.80.0 (RULES.URR_V80.dsLinkIntercept 'rcd', URR): an encrypted link is decrypted first (Electronic Warfare, or
   * Electronics at +2, vs the encryption + 4; half the target deck's rating in successes), then intercepted: this
   * character's deck rating vs the target deck's rating + 3 (its Pilot with no deck). One success intercepts.
   */
  async #dsInterceptDroneLink(drone: any, f: any, opts: { modifiers?: TargetNumberModifier[] } = {}): Promise<{ intercepted: boolean } | null> {
    const ew: any = this.findSkill(String(RULES.URR_V80.dsDecryptSkill));
    const plan = dsInterceptPlan({ ownRcd: this.#linkGear().rcd, targetRcd: Number(f.rcd ?? 0), pilot: Number(drone.system.derived?.autopilotRating ?? 0), encryption: Number(f.encryption ?? 0), hasEwSkill: Number(ew?.system?.rating ?? 0) > 0 });
    if (!plan) return null;
    const rolls: any[] = [];
    const parts: string[] = [];
    let ok = true;
    if (plan.decrypt) {
      const sk = plan.decrypt.skill;
      const sd = this.#skillDice(sk === 'Electronics' ? this.findSkill('Electronics') : ew, false, null, RULES.DRONES_V73.link.attribute as AttributeKey, { skillName: sk });
      const d = await successTest({ dice: sd.dice, targetNumber: plan.decrypt.baseTn, modifiers: [...sd.modifiers, ...plan.decrypt.modifiers, ...(opts.modifiers ?? [])], roll: foundryRoller(rolls) });
      ok = dsDecryptPassed(d.successes, plan.decrypt.need);
      parts.push(`${describeResult(tx('SR2E.Card.Actor.decryptsSLinkEncryptionNeeds', { name: this.name, droneName: drone.name, sk, sdSuffix: sd.suffix, encryption: Number(f.encryption), decryptNeed: plan.decrypt.need }), d)}<p>${ok ? tx('SR2E.Card.Actor.theEncryptionIsBroken') : tx('SR2E.Card.Actor.theEncryptionHoldsAnotherTryIs', { urrV80DsDecryptRetryTn: Number(RULES.URR_V80.dsDecryptRetryTn) })}</p>`);
    }
    if (ok) {
      const r = await successTest({ dice: plan.intercept.dice, targetNumber: plan.intercept.baseTn, modifiers: [...plan.intercept.modifiers, ...(opts.modifiers ?? [])], roll: foundryRoller(rolls) });
      ok = r.successes > 0;
      parts.push(describeResult(tx('SR2E.Card.Actor.interceptsSLinkDeckVs', { name: this.name, droneName: drone.name, interceptDice: plan.intercept.dice, interceptFrom: plan.intercept.from }), r));
    }
    const c = { droneUuid: drone.uuid, kind: 'intercept' as const, byUuid: this.uuid, by: String(this.name) };
    let body = '';
    let gmFlag: Record<string, unknown> = {};
    if (ok) {
      if (canWriteNow(drone)) await SR2Actor.applyDroneLink(c);
      else { body = ` <button type="button" data-sr2e-action="applyDroneLink">${tx('SR2E.Card.Actor.applyGm')}</button>`; gmFlag = { droneLink: c }; }
    }
    await ChatMessage.create({
      speaker: ChatMessage.getSpeaker({ actor: this }), rolls, flags: { [SYSTEM_ID]: gmFlag },
      content: `${parts.join('')}<p>${ok ? `<strong>${tx('SR2E.Card.Actor.linkIntercepted')}</strong>${tx('SR2E.Card.Actor.hearsItsTrafficAndCanTry', { name: escText(this.name), part: f.rigger ? tx('SR2E.Card.Actor.itsRigger', { riggerName: escText(f.rigger.name) }) : '', body })}` : tx('SR2E.Card.Actor.theLinkStaysClosed')}</p>`,
    });
    return { intercepted: ok };
  }

  /**
   * v0.73.0 (O28, 5-A9): spoof a command to a drone (RULES.DRONES_V73.link.spoof): the link skill vs its
   * rigger's deck (or its Pilot). One false command, or a takeover until the GM clears it.
   */
  async spoofDroneLink(targetUuid: string, opts: { command?: string; modifiers?: TargetNumberModifier[] } = {}): Promise<{ spoofed: boolean } | null> {
    const L = RULES.DRONES_V73.link;
    const drone: any = await fromUuid(targetUuid);
    if (!L.enabled || !drone || drone.type !== 'vehicle') { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.pickADroneOrVehicleTo2')); return null; }
    if (!linkGearOk(L.spoof.gear, this.#linkGear())) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.needsToSpoofADrone', { name: escHtml(this.name), linkGearLabel: linkGearLabel(L.spoof.gear) })); return null; }
    const f = this.#droneLinkFacts(drone);
    const skillName = String(L.skill);
    const sd = this.#skillDice(this.findSkill(skillName), false, null, L.attribute as AttributeKey, { skillName });
    const t = droneSpoofTest({
      dice: sd.dice, rcd: f.rcd, pilot: Number(drone.system.derived?.autopilotRating ?? 0), eccm: Number(drone.system.eccm ?? 0),
      encryption: f.encryption, intercepted: f.link.intercepted.byUuid === this.uuid, linked: f.kind.linked, remoteJumped: f.kind.remoteJumped,
    });
    if (!t.allowed) { ui.notifications?.warn?.(`${escHtml(drone.name)}: ${escHtml(t.reason)}`); return null; }
    const rolls: any[] = [];
    const r = await successTest({ dice: t.dice, targetNumber: t.baseTn, modifiers: [...sd.modifiers, ...t.modifiers, ...(opts.modifiers ?? [])], roll: foundryRoller(rolls) });
    const out = spoofOutcome(r.successes, { remoteJumped: f.kind.remoteJumped });
    const cmd = String(opts.command ?? '').trim();
    let body = '';
    let gmFlag: Record<string, unknown> = {};
    if (out.spoofed && out.effect === 'takeover') {
      const c = { droneUuid: drone.uuid, kind: 'spoof' as const, byUuid: this.uuid, by: String(this.name) };
      const ctl: any = f.kind.remoteJumped ? drone.controller?.() : null;
      if (canWriteNow(drone) && (!ctl || canWriteNow(ctl))) await SR2Actor.applyDroneLink(c);
      else { body = ` <button type="button" data-sr2e-action="applyDroneLink">${tx('SR2E.Card.Actor.applyGm')}</button>`; gmFlag = { droneLink: c }; }
    }
    await ChatMessage.create({
      speaker: ChatMessage.getSpeaker({ actor: this }), rolls, flags: { [SYSTEM_ID]: gmFlag },
      content: `${describeResult(tx('SR2E.Card.Actor.spoofsVs', { name: this.name, droneName: drone.name, skillName, sdSuffix: sd.suffix, reason: t.reason }), r)}${cmd ? `<p>${tx('SR2E.Card.Actor.command')} <em>${escText(cmd)}</em></p>` : ''}<p>${out.spoofed ? `<strong>${escText(out.note)}</strong>${body}` : escText(out.note)}</p>`,
    });
    return { spoofed: out.spoofed };
  }

  /** v0.73.0 (O28): mark a drone's link intercepted or spoofed (owner or GM); a spoof pushes a remote rigger out. */
  static async applyDroneLink(c: { droneUuid: string; kind: 'intercept' | 'spoof'; byUuid: string; by: string }): Promise<boolean> {
    const drone: any = await fromUuid(c.droneUuid);
    if (!drone || drone.type !== 'vehicle') return false;
    await drone.update(droneLinkUpdate(c.kind, { uuid: c.byUuid, name: c.by }));
    if (c.kind === 'spoof') {
      const ctl: any = drone.controller?.() ?? null;
      if (ctl && drone.system.controlMode === 'jumped' && !drone.isAboard(ctl)) await drone.setController(null);
    }
    return true;
  }

  /** v0.73.0 (O28): the rigger has the link back: clear an interception and a spoof (GM). */
  async clearDroneLink(): Promise<void> {
    if (this.type !== 'vehicle') return;
    await this.update(droneLinkUpdate('clear'));
  }

  /**
   * v0.49.0: jam a decker's wireless Matrix link: the jammer's rating vs the deck's signal. Jammed,
   * they are dumped (dump shock) or held (RULES.RIGGING.jamming.onDecker), and can't jack in again
   * until it clears.
   */
  async #jamDecker(decker: any, opts: { rating?: number; modifiers?: TargetNumberModifier[] }): Promise<{ jammed: boolean } | null> {
    const conn = String(decker.system?.matrix?.connection ?? 'jackpoint');
    if (!wirelessConnection(conn)) {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.isOnAConnectionThereIs', { deckerName: escHtml(decker.name), conn: escHtml(conn) }));
      return null;
    }
    const rating = Math.max(0, Math.floor(opts.rating ?? this.jammerRating()));
    if (!(rating > 0)) {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.hasNoJammerAVehicleS', { name: escHtml(this.name) }));
      return null;
    }
    const signal = Number(decker.system?.derived?.matrix?.signal ?? 0);
    const tn = jamTarget({ signal });
    const rolls: any[] = [];
    const r = await successTest({ dice: rating, targetNumber: tn, modifiers: opts.modifiers ?? [], roll: foundryRoller(rolls) });
    const jammed = r.successes > 0;
    const inRun = Boolean(decker.system?.matrix?.jackedIn);
    // The host's Security Value sets the dump shock TN: read it before the jam dumps them.
    const host: any = decker.currentHost?.() ?? null;
    const tnDump = Number(host?.system?.securityValue ?? RULES.MATRIX.dumpShockTn);
    // The dump shock button only once the jam is applied here (else it follows the GM's Apply).
    const dump = jammed && inRun && canWriteNow(decker) && RULES.RIGGING.jamming.onDecker === 'dump' && !(decker.isTortoise?.() && !RULES.MATRIX.tortoise.dumpShock);
    let body = '';
    let gmFlag: Record<string, unknown> = {};
    if (jammed) {
      // This card carries the dump shock button itself; the hitchers' shock and unplugging follow the jam.
      if (canWriteNow(decker)) await SR2Actor.applyDeckerJam(decker.uuid, this.name as string, rating, { shockCard: false });
      else {
        body = ` <button type="button" data-sr2e-action="applyJam">${tx('SR2E.Card.Actor.applyGm')}</button>`;
        gmFlag = { jam: { droneUuid: decker.uuid, by: this.name, rating, jammerUuid: this.uuid } };
      }
    }
    await ChatMessage.create({
      speaker: ChatMessage.getSpeaker({ actor: this }), rolls,
      content: `${describeResult(tx('SR2E.Card.Actor.jamsSLinkJammerVsSignal', { name: this.name, deckerName: decker.name, conn, rating, signal }), r)}<p>${jammed ? `<strong>${tx('SR2E.Card.Actor.sLinkIsJammed2', { deckerName: escText(decker.name) })}</strong>${tx('SR2E.Card.Actor.noJackingInUntilItClears', { part: inRun ? (RULES.RIGGING.jamming.onDecker === 'dump' ? tx('SR2E.Card.Actor.theyAreDumpedFromTheMatrix') : tx('SR2E.Card.Actor.theyCanDoNothingInThe')) : '', body })}` : tx('SR2E.Card.Actor.sLinkHolds2', { deckerName: escText(decker.name) })}</p>${dump ? `<p><button type="button" data-sr2e-action="dumpShock">${tx('SR2E.Card.Actor.resistDumpShockWillpowerVs3', { deckerName: escText(decker.name), tnDump })}</button></p>` : ''}`,
      flags: { [SYSTEM_ID]: { ...gmFlag, ...(dump ? { dumpShockFor: decker.uuid, dumpShockTn: tnDump, dumpShockLevel: dumpShockLevel(String(host?.system?.securityCode ?? '')) } : {}) } },
    });
    return { jammed };
  }

  /**
   * v0.49.0: mark a decker's wireless link jammed (owner or GM); dump them when that is the rule.
   * v0.81.0 (D3-6, SEC1-11): a dump is a dump: the dump shock card (unless `shockCard: false`, when the jammer's own
   * card carries it), the hitchers' shock, and they are unplugged. The rating is bounded.
   */
  static async applyDeckerJam(uuid: string, by: string, rating: number, o: { shockCard?: boolean } = {}): Promise<boolean> {
    const a: any = await fromUuid(uuid);
    if (!a || !(a instanceof SR2Actor) || !['character', 'npc'].includes(a.type)) return false;
    const r = safeInt(rating, 0, 30, 0);
    const up: Record<string, unknown> = { 'system.matrix.jammed': { active: true, by: String(by ?? '').slice(0, 80), rating: r } };
    const dumping = Boolean(a.system?.matrix?.jackedIn) && RULES.RIGGING.jamming.onDecker === 'dump';
    const host: any = dumping ? a.currentHost?.() ?? null : null;
    if (dumping) Object.assign(up, { 'system.matrix.jackedIn': false, 'system.matrix.hostUuid': '', ...a.#endRunUpdate() });
    await a.update(up);
    if (dumping) await a.#dumpFollowUps(host, tx('SR2E.Card.Actor.jammed'), o.shockCard !== false);
    return true;
  }

  /** v0.49.0: clear a jammed wireless Matrix link. */
  async unjamLink(): Promise<void> {
    if (this.type === 'vehicle') return this.unjam();
    await this.update({ 'system.matrix.jammed': { active: false, by: '', rating: 0 } });
  }

  /**
   * Jam a drone's link (owner or GM): mark it jammed and push a remote rigger out.
   * v0.81.0 (SEC1-11): from a card (`o.author` = the card's server-set author), the jam must come from a jammer
   * (`o.jammerUuid`) that author owns and that has a jammer; the rating is bounded. A remote rigger pushed out gets
   * the dump shock card here (D3-7) unless `shockCard: false` (the jammer's card already carries it).
   */
  static async applyJam(droneUuid: string, by: string, rating: number, o: { jammerUuid?: string; author?: any; shockCard?: boolean } = {}): Promise<boolean> {
    const r = safeInt(rating, 0, 30, 0);
    if (o.author !== undefined && !realGm(o.author)) {
      const jammer: any = o.jammerUuid ? await fromUuid(o.jammerUuid) : null;
      if (!jammer || !userOwns(o.author, jammer) || !(Number(jammer.jammerRating?.() ?? 0) > 0)) return false;
    }
    const drone: any = await fromUuid(droneUuid);
    if (drone && ['character', 'npc'].includes(drone.type)) return SR2Actor.applyDeckerJam(droneUuid, by, r, { shockCard: o.shockCard });
    if (!drone || drone.type !== 'vehicle') return false;
    await drone.update({ 'system.jammed': { active: true, by: String(by ?? '').slice(0, 80), rating: r } });
    const ctl: any = drone.controller?.() ?? null;
    if (ctl && drone.system.controlMode === 'jumped' && !drone.isAboard(ctl)) {
      await drone.setController(null);
      if (o.shockCard !== false && RULES.RIGGING.jamming.dumpShock) {
        const ds = dumpShockFor(ctl, true);
        await ChatMessage.create({
          speaker: ChatMessage.getSpeaker({ actor: drone }),
          content: `<p>${tx('SR2E.Card.Actor.isPushedOutOfByThe', { ctlName: escText(ctl.name), droneName: escText(drone.name) })}</p><p><button type="button" data-sr2e-action="riggerShock">${tx('SR2E.Card.Actor.resistDumpShockVs3', { ctlName: escText(ctl.name), shockAttr: shockAttr(ds), dsTn: ds.tn, dsLevel: ds.level, dsType: ds.type })}</button></p>`,
          flags: { [SYSTEM_ID]: { riggerShock: { riggerUuid: ctl.uuid, riggerName: ctl.name, ...ds, kind: 'dump' } } },
        });
      }
    }
    return true;
  }

  /** Vehicle: clear a jammed link. */
  async unjam(): Promise<void> {
    if (this.type !== 'vehicle') return;
    await this.update({ 'system.jammed': { active: false, by: '', rating: 0 } });
  }

  /**
   * Whether a weapon's fixed-mount arc covers a target, from the vehicle token's rotation (null when
   * it has no arc, or the tokens are not on the scene).
   */
  static arcCheck(vehicle: any, weapon: any, targetUuid: string | null): { inside: boolean; offBy: number } | null {
    const arc = String(weapon?.system?.arc ?? '');
    if (!arc || (weapon?.system?.mount ?? 'none') !== 'fixed' || !targetUuid) return null;
    try {
      const from: any = tokenOf(vehicle);
      const target: any = fromUuidSync(targetUuid);
      const to: any = target ? tokenOf(target) : null;
      if (!from || !to) return null;
      const c = (t: any) => t.center ?? { x: (t.document?.x ?? t.x ?? 0) + (t.w ?? 0) / 2, y: (t.document?.y ?? t.y ?? 0) + (t.h ?? 0) / 2 };
      const a = c(from), b = c(to);
      const rotation = Number(from.document?.rotation ?? from.rotation ?? 0);
      return inArc(arc, rotation, bearingDeg(b.x - a.x, b.y - a.y));
    } catch { return null; }
  }

  /**
   * After a chase turn, put the pursuer's token the gap behind the quarry's on the line between
   * them (RULES.VEHICLES.chase.moveTokens). Returns a note for the card.
   */
  static async placeChaseTokens(pursuer: any, quarry: any, metres: number): Promise<string> {
    if (!RULES.VEHICLES.chase.moveTokens) return '';
    try {
      const p: any = tokenOf(pursuer), q: any = tokenOf(quarry);
      if (!p || !q) return '';
      if ((game as any).paused) return `<p class="hint">${tx('SR2E.Card.Actor.theGameIsPausedTheTokens')}</p>`;
      const centre = (t: any) => t.center ?? { x: t.document.x + (t.w ?? 0) / 2, y: t.document.y + (t.h ?? 0) / 2 };
      const to = chasePlacement(centre(q), centre(p), metres, pxPerMetre());
      await p.document.update({ x: Math.round(to.x - (p.w ?? 0) / 2), y: Math.round(to.y - (p.h ?? 0) / 2) });
      return `<p class="hint">${tx('SR2E.Card.Actor.sTokenIsMovedMBehind', { pursuerName: escText(pursuer.name), metres: Math.round(metres), quarryName: escText(quarry.name) })}</p>`;
    } catch (err) {
      console.warn('sr2e | chase token', err);
      return '';
    }
  }

  /**
   * v0.49.0: install a vehicle modification with a test (RULES.VEHICLES.install): this mechanic's
   * vehicle B/R skill vs TN by rating; on success the mod goes in (the payer pays), and the card
   * gives the hours; a disaster damages the vehicle.
   */
  async installModTest(vehicle: any, index: number, opts: { payer?: any | null; modifiers?: TargetNumberModifier[] } = {}): Promise<SuccessTestResult | null> {
    if (vehicle?.type !== 'vehicle') return null;
    const mod = (vehicle.system.mods ?? [])[index];
    if (!mod) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.thatModificationIsGone')); return null; }
    if (mod.installed) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.isAlreadyIn', { modName: escHtml(mod.name || modificationDef(mod.kind)?.label) })); return null; }
    // v0.78.0 (RULES.BOOK_V78.adaptation 'text'): the rigger adaptation goes in on top of the remote adaptation.
    const needs = modPrerequisite(mod.kind, (vehicle.system.mods ?? []).filter((m: any) => m.installed).map((m: any) => String(m.kind)));
    if (needs) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.needsFirst', { vehicleName: escHtml(vehicle.name), needs: escHtml(needs) })); return null; }
    const fx = modificationEffect(mod.kind, mod.rating, Number(vehicle.system.body ?? 0));
    const cost = mod.cost > 0 ? mod.cost : fx.cost;
    if (opts.payer && cost > Number(opts.payer.system?.nuyen ?? 0)) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.canTPayForTheParts', { payerName: escHtml(opts.payer.name), cost: escHtml(cost.toLocaleString()) })); return null; }
    const plan = modInstallPlan(mod.rating);
    const vr = RULES.SKILLS.vehicleRepair;
    const skill = vr.skills.map((n) => this.findSkill(n)).find((x: any) => x && (x.system?.rating ?? 0) > 0);
    const sd = this.#skillDice(skill, false, null, 'intelligence');
    const modName = mod.name || fx.label;
    return this.#runTest(tx('SR2E.Card.Actor.installIn2', { modName, modRating: mod.rating, vehicleName: vehicle.name, skillName: skill?.name ?? tx('SR2E.Card.Actor.noBRSkill'), sdSuffix: sd.suffix }), sd.dice, {
      targetNumber: plan.tn, modifiers: [...(opts.modifiers ?? []), ...sd.modifiers], poolDice: 0,
    }, { kind: 'install', install: { vehicleUuid: vehicle.uuid, vehicleName: vehicle.name, index, modName, rating: mod.rating, baseHours: plan.baseHours, payerUuid: opts.payer?.uuid ?? '' } });
  }

  /** An installation test's result: the mod goes in once; a disaster damages the vehicle once. */
  async #resolveInstall(snap: TestSnapshot): Promise<Resolved> {
    const c = snap.install!;
    const s = snap.successes;
    const vehicle: any = fromUuidSync(c.vehicleUuid);
    const next = { ...c };
    if (snap.botch && !c.botchApplied && vehicle) {
      const boxes = RULES.VEHICLES.install.botchBoxes;
      next.botchApplied = true;
      if (boxes > 0) {
        try { await vehicle.update({ 'system.condition': Number(vehicle.system.condition ?? 0) + boxes }); } catch { /* GM */ }
      }
    }
    const hours = s > 0 ? Math.max(1, Math.ceil(c.baseHours / s)) : null;
    if (!hours && c.projectId) { next.applied = false; const note = await this.dropProjectOnFailure(c.projectId); next.projectId = undefined; return { html: `<p><strong>${tx('SR2E.Card.Actor.doesnTGoIn', { modName: escText(c.modName) })}</strong>${note}</p>`, flags: {}, snap: { ...snap, install: next } }; }
    if (!hours) return { html: `<p><strong>${tx('SR2E.Card.Actor.doesnTGoIn', { modName: escText(c.modName) })}</strong>${snap.botch ? tCount(RULES.VEHICLES.install.botchBoxes, 'SR2E.Card.Actor.aSlipDamagesBoxes', { vehicleName: escText(c.vehicleName) }) : ''}${c.applied ? ` <em>${tx('SR2E.Card.Actor.itWasAlreadyInstalledTakeIt')}</em>` : ''}</p>`, flags: {}, snap: { ...snap, install: next } };
    const time = `<strong>${tCount(hours, 'SR2E.Card.Actor.hours')}</strong> ${tx('SR2E.Card.Actor.ofWork2', { baseHours: c.baseHours, s })}`;
    if (c.applied) {
      const p = await this.retimeProject(c.projectId, hours);
      return { html: `<p>${p ? tx('SR2E.Card.Actor.underWay', { time }) : `${tx('SR2E.Card.Actor.doneIn2', { time })} <em>${tx('SR2E.Card.Actor.alreadyInstalled')}</em>`}</p>`, flags: {}, snap: { ...snap, install: next } };
    }
    // v0.65.0 / v0.73.0 (O43): the mod goes in when the hours of work have passed; paid now (RULES.CROSSCUT_V73.modInstall).
    if (vehicle && this.waitsFor('vehicles')) {
      // Review fix: the list may have changed since the test; find the mod by its name like finishModInstall does.
      const allMods: any[] = vehicle.system?.mods ?? [];
      const mod: any = ((String(allMods[c.index]?.name ?? '') === c.modName || (allMods[c.index] && !String(allMods[c.index]?.name ?? ''))) ? allMods[c.index] : allMods.find((m: any) => String(m?.name ?? '') === c.modName && !m?.installed)) ?? {};
      const fx: any = modificationEffect(mod.kind, mod.rating, Number(vehicle.system?.body ?? 0));
      const pay = modInstallPayment({ modCost: Number(mod.cost ?? 0), tableCost: Number(fx?.cost ?? 0), payerUuid: c.payerUuid || null, installerUuid: String(this.uuid), waits: true });
      const label = tx('SR2E.Text.Actor.installingIn', { modName: c.modName, vehicleName: c.vehicleName });
      if (pay.upFront) {
        const payer: any = fromUuidSync(c.payerUuid!);
        if (!(await payer?.adjustNuyen?.(-pay.cost, tx('SR2E.Text.Actor.ratingForVehicle', { label: fx?.label ?? c.modName, rating: mod.rating ?? '', vehicleName: c.vehicleName })))) {
          return { html: `<p>${tx('SR2E.Card.Actor.theTestSucceededButCanT', { modName: escText(c.modName), time, payerName: escText(payer?.name ?? tx('SR2E.Card.Actor.thePayer')), payCost: pay.cost.toLocaleString() })}</p>`, flags: {}, snap: { ...snap, install: { ...next, applied: false } } };
        }
      }
      const pr = await this.startProject({ kind: 'install', area: 'vehicles', label, hours,
        ...(pay.refund === 'project' ? { paid: { karma: 0, nuyen: pay.cost } } : {}),
        ...(pay.refund === 'payer' ? { onCancel: { call: { method: 'refundModPayer', args: [c.payerUuid, pay.cost, label] } } } : {}),
        effect: { call: { method: 'finishModInstall', args: [c.vehicleUuid, c.index, pay.upFront ? null : (c.payerUuid ?? null), c.modName, pay.upFront ? pay.cost : 0, pay.upFront ? c.payerUuid : null] } } });
      const paidNote = pay.upFront ? tx('SR2E.Card.Actor.paidNowGivenBackIfIt', { payCost: pay.cost.toLocaleString() }) : tx('SR2E.Card.Actor.itIsPaidForThen');
      return { html: `<p><strong>${escText(c.modName)}</strong> ${tx('SR2E.Card.Actor.goesInAfterUpkeepTabUnder', { time, paidNote })}</p>`, flags: {}, snap: { ...snap, install: { ...next, applied: true, projectId: pr.id } } };
    }
    let ok = false;
    try {
      const payer: any = c.payerUuid ? fromUuidSync(c.payerUuid) : null;
      ok = Boolean(vehicle && await vehicle.installMod(c.index, { payer }));
    } catch (err) { console.warn('sr2e | install', err); }
    next.applied = ok;
    return { html: ok ? `<p><strong>${tx('SR2E.Card.Actor.goesIn', { modName: escText(c.modName) })}</strong> ${tx('SR2E.Card.Actor.after3', { time })}</p>` : `<p>${tx('SR2E.Card.Actor.theTestSucceededButItCouldn', { modName: escText(c.modName), time })}</p>`, flags: {}, snap: { ...snap, install: next } };
  }

  /**
   * Vehicle: install a modification from its list (RULES.VEHICLES.modifications): the stat changes
   * and the payer (a character, optional) pays the cost. `remove` takes it out again.
   */
  async installMod(index: number, opts: { payer?: any | null; remove?: boolean } = {}): Promise<boolean> {
    if (this.type !== 'vehicle') return false;
    const list = [...(this.sys.mods ?? [])].map((m: any) => ({ ...m }));
    const mod = list[index];
    if (!mod) return false;
    if (opts.remove) {
      if (!mod.installed) return false;
      // v0.78.0 (RULES.BOOK_V78.adaptation 'text'): the remote adaptation stays while the rigger adaptation is in.
      if (mod.kind === 'remote' && RULES.BOOK_V78.adaptation === 'text' && list.some((m: any) => m.installed && m.kind === 'adaptation')) {
        ui.notifications?.warn?.(tx('SR2E.Notify.Actor.takeTheRiggerAdaptationOutOf', { name: escHtml(this.name) }));
        return false;
      }
      const update: Record<string, unknown> = {};
      if (mod.stat) update[`system.${mod.stat}`] = applyStatDelta(mod.stat, Number(this.sys[mod.stat] ?? 0), -Number(mod.delta ?? 0));
      list[index] = { ...mod, installed: false, stat: '', delta: 0 };
      await this.update({ ...update, 'system.mods': list });
      await ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor: this }), content: `<p>${tx('SR2E.Card.Actor.comesOutOf', { modName: escText(mod.name || modificationDef(mod.kind)?.label) })} <strong>${escText(this.name)}</strong>.</p>` });
      return true;
    }
    if (mod.installed) return false;
    const needs = modPrerequisite(mod.kind, list.filter((m: any) => m.installed).map((m: any) => String(m.kind)));
    if (needs) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.needsFirst2', { name: escHtml(this.name), needs: escHtml(needs) })); return false; }
    const fx = modificationEffect(mod.kind, mod.rating, Number(this.sys.body ?? 0));
    const cost = mod.cost > 0 ? mod.cost : fx.cost;
    if (opts.payer && cost > 0 && !(await opts.payer.adjustNuyen(-cost, tx('SR2E.Text.Actor.ratingForVehicle', { label: fx.label, rating: mod.rating, vehicleName: this.name })))) return false;
    const update: Record<string, unknown> = {};
    let delta = 0;
    if (fx.stat) {
      const before = Number(this.sys[fx.stat] ?? 0);
      const after = applyStatDelta(fx.stat, before, fx.delta);
      delta = after - before;
      update[`system.${fx.stat}`] = after;
    }
    list[index] = { ...mod, installed: true, cost, stat: fx.stat, delta };
    await this.update({ ...update, 'system.mods': list });
    await ChatMessage.create({
      speaker: ChatMessage.getSpeaker({ actor: this }),
      content: `<p><strong>${escText(mod.name || fx.label)}</strong> ${tx('SR2E.Card.Actor.ratingGoesInto', { modRating: escText(mod.rating) })} <strong>${escText(this.name)}</strong>${fx.stat ? `: ${escText(cap(fx.stat))} ${delta >= 0 ? '+' : ''}${delta}` : ''}${opts.payer && cost > 0 ? tx('SR2E.Card.Actor.paidBy', { cost: escText(cost), payerName: escText(opts.payer.name) }) : cost > 0 ? ` (${escText(cost)}¥)` : ''}.</p>`,
    });
    return true;
  }

  // ---------------------------------------------------------------- Magic and critters (v0.39.0)

  /** The total level of active adept powers with this special effect. */
  adeptSpecial(special: AdeptSpecial): number {
    return adeptSpecialLevel([...(this.items ?? [])].filter((i: any) => i.type === 'adeptpower').map((i: any) => i.system ?? {}), special);
  }

  /** Critter weaknesses and special powers (Power items with a Special). */
  critterTraits(): Array<CritterTrait & { id: string; name: string; active: boolean }> {
    return [...(this.items ?? [])].filter((i: any) => i.type === 'power' && i.system?.special).map((i: any) => ({
      id: i.id, name: i.name, special: i.system.special, substance: i.system.substance ?? '', severity: i.system.severity ?? 'mild',
      exposed: Boolean(i.system.exposed), active: i.system.active !== false,
    }));
  }

  /** Whether this actor has an active critter power with this special effect. */
  hasCritterPower(special: string): boolean {
    // A built-in effect works whether or not the power is marked active (that box is for rolled powers).
    return this.critterTraits().some((t) => t.special === special);
  }

  /** Libraries, circles and lodges this magician owns (gear with a site kind). */
  magicSites(): MagicSite[] {
    const own = [...(this.items ?? [])].filter((i: any) => i.type === 'gear' && i.system?.site?.kind)
      .map((i: any) => ({ name: i.name, kind: i.system.site.kind as SiteKind, rating: Number(i.system.site.rating ?? 0), tag: String(i.system.site.tag ?? '') }));
    // v0.45.0: a magical group's sites, for members in good standing.
    return [...own, ...groupSites(SR2Actor.magicGroups(), this.selfUuids())];
  }

  /** Report missing libraries, circles or lodges; false when the house rule blocks the task. */
  #siteProblem(what: string, missing: string[]): boolean {
    const mode = RULES.MAGIC_V39.sites.enforce;
    if (mode === 'off') return true;
    ui.notifications?.warn?.(tx('SR2E.Notify.Actor.needsFor', { name: escHtml(this.name), missing: escHtml(tList(missing)), what: escHtml(what), part: mode === 'block' ? '' : tx('SR2E.Notify.Actor.allowedTheHouseRuleOnlyWarns') }));
    return mode !== 'block';
  }

  /** A spirit template (a spirit actor with no summoner) for a spirit type, by type or name. */
  static spiritTemplateFor(type: string): any | null {
    const want = (type ?? '').trim().toLowerCase();
    if (!want) return null;
    // v0.52.0: spirits from the NPC generator are not templates (they have no powers of their own).
    return allActors().find((a: any) => a.type === 'spirit' && !a.system?.summonerUuid && !a.flags?.sr2e?.generated
      && ((a.system?.spiritType ?? '').trim().toLowerCase() === want || (a.name ?? '').trim().toLowerCase() === want)) ?? null;
  }

  /** A nature spirit outside its domain (its domain is not among the scene's environment tags). */
  outOfDomain(): boolean {
    if (this.type !== 'spirit' || this.sys.spiritKind !== 'nature' || RULES.MAGIC_V39.domains.enforce === 'off') return false;
    return outsideDomain(String(this.sys.domain ?? ''), this.environmentHere());
  }

  /** What this magician lines up with for aspected background count: tradition, totem, element. */
  alignTags(): string[] {
    return [this.sys.tradition, this.sys.totem?.name, this.sys.aspectElement, this.sys.element]
      .map((x: any) => String(x ?? '').trim().toLowerCase()).filter((x) => x && x !== 'none');
  }

  /** Background count sources on the scene being viewed (v0.39.0). */
  static backgroundSources(at: any = null): BackgroundSource[] {
    const scene = at ?? game.scenes?.viewed ?? game.scenes?.current;
    return parseBackgroundSources(String(scene?.getFlag?.(SYSTEM_ID, 'backgroundSources') ?? ''));
  }

  /** GM: set the background count sources of the scene being viewed (one per line). */
  static async setBackgroundSources(text: string): Promise<void> {
    const scene = game.scenes?.viewed ?? game.scenes?.current;
    if (!scene) return;
    await scene.setFlag(SYSTEM_ID, 'backgroundSources', String(text ?? ''));
  }

  /** The background count as it affects this actor: TN penalty, aligned bonus dice, toxic. */
  backgroundInfo(): { penalty: number; bonusDice: number; toxic: boolean; note: string } {
    // v0.50.0: the scene this actor's token is on (RULES.TN_AUTO.magic.tokenScene).
    const at = this.sceneHere();
    // v0.60.0: and the background count of the regions its token stands in.
    return backgroundFor([...SR2Actor.backgroundSources(at), ...regionBackgroundSources(regionsForActor(this))], SR2Actor.backgroundCount(at), this.alignTags());
  }

  /** v0.60.0: the weather where this actor's token stands (a region's, else its scene's). */
  weatherHere(): string {
    return regionWeather(SR2Actor.sceneWeather(this.sceneHere()), regionsForActor(this));
  }

  /** v0.60.0: the environment tags where this actor's token stands (its scene's plus its regions'). */
  environmentHere(): string[] {
    return regionEnvironmentTags(SR2Actor.sceneEnvironment(this.sceneHere()), regionsForActor(this));
  }

  /** An elemental spell's secondary effect on this target: catching fire, shock, corroded armor, knockdown. */
  async applyElementEffect(kind: ElementEffect, force: number): Promise<void> {
    if (kind === 'fire') {
      await this.resistHazard('fire', RULES.COMBAT.flame.catchFire);
      await this.spreadFireFromMe(`${this.name} caught fire`);
      return;
    }
    if (kind === 'knockdown') {
      await this.rollKnockdown(Math.max(2, force));
      return;
    }
    if (kind === 'corrode') {
      const pts = RULES.MAGIC_V39.corrode.points;
      const best = [...this.items].filter((i: any) => i.type === 'armor' && i.system.worn && isCarried(i))
        .sort((a: any, b: any) => ((b.system.ballistic ?? 0) + (b.system.impact ?? 0)) - ((a.system.ballistic ?? 0) + (a.system.impact ?? 0)))[0];
      if (best) await best.update({ 'system.degraded': (best.system.degraded ?? 0) + pts });
      await ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor: this }),
        content: `<p>${best ? `${tx('SR2E.Card.Actor.theAcidEatsInto')} <strong>${escText(best.name)}</strong> ${tx('SR2E.Card.Actor.repairItFromTheSheet', { pts })}` : tx('SR2E.Card.Actor.wearsNoArmorForTheAcid', { name: escText(this.name) })}</p>` });
      return;
    }
    if (kind === 'shock') {
      const sh = RULES.MAGIC_V39.shock;
      const dice = (this.sys.attributes?.[sh.attribute]?.total as number | undefined) ?? 0;
      const r = await this.#runTest(tx('SR2E.Card.Actor.shockVsForce', { shAttribute: cap(sh.attribute), force }), dice, { targetNumber: Math.max(2, force), noPenalties: true });
      const o = shockOutcome(r.successes);
      if (!o.stunned) return;
      const combat: any = (game as any).combat;
      const c = combat?.started ? this.myCombatant() : null;
      if (c && typeof c.initiative === 'number') {
        try { await combat.updateEmbeddedDocuments('Combatant', [{ _id: c.id, initiative: c.initiative - o.initiativeLoss }]); } catch { /* not ours */ }
      } else await this.setTimedStatus('stun', sh.stunTurns * 3);
      await ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor: this }),
        content: `<p><strong>${tx('SR2E.Card.Actor.isStunnedByTheShock', { name: escText(this.name) })}</strong>${c ? tx('SR2E.Card.Actor.initiative2', { initiativeLoss: o.initiativeLoss }) : tCount(sh.stunTurns, 'SR2E.Card.Actor.forTurns')}.</p>` });
    }
  }

  /** A burning target sets its surroundings alight (RULES.FIRE.fromHits, v0.45.0). */
  async spreadFireFromMe(source: string): Promise<void> {
    if (!RULES.FIRE.fromHits) return;
    const t: any = tokenOf(this);
    const c = t?.center ?? (t ? { x: t.x + (t.w ?? 0) / 2, y: t.y + (t.h ?? 0) / 2 } : null);
    if (c) await SR2Actor.startFire({ x: c.x, y: c.y }, { source, sceneId: t.scene?.id ?? t.document?.parent?.id });
  }

  /** The focus addiction test (v0.39.0): rolled when active bonded foci total more than Magic. */
  async focusAddictionTest(): Promise<SuccessTestResult | null> {
    const fa = this.sys.derived?.focusAddiction ?? { total: 0 };
    const magic = Number(this.sys.derived?.magic ?? 0);
    const tn = addictionTn(Number(fa.total ?? 0), magic);
    if (tn === null) {
      ui.notifications?.info?.(tx('SR2E.Notify.Actor.sActiveFociDonTExceed', { name: escHtml(this.name), faTotal: escHtml(fa.total), magic }));
      return null;
    }
    const a = RULES.MAGIC_V39.addiction.attribute;
    const r = await this.#runTest(tx('SR2E.Card.Actor.focusAddictionTestVsFociMagic', { a: cap(a), tn, faTotal: fa.total, magic }), (this.sys.attributes?.[a]?.total as number | undefined) ?? 0,
      { targetNumber: tn, noPenalties: true });
    if (r.successes <= 0) {
      try { await this.setFlag(SYSTEM_ID, 'focusAddict', true); } catch { /* not saved */ }
      await ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor: this }),
        content: `<p><strong>${tx('SR2E.Card.Actor.isAddictedToFoci', { name: escText(this.name) })}</strong> ${tx('SR2E.Card.Actor.withoutAnActiveFocusMagicTakes', { addictionWithdrawalTn: RULES.MAGIC_V39.addiction.withdrawalTn })}</p>` });
    }
    return r;
  }

  /** Clear focus addiction (the GM decides when it is beaten). */
  async clearFocusAddiction(): Promise<void> {
    try { await clearFlag(this, 'focusAddict'); } catch { /* not set */ }
  }

  /** A shapeshifter changes form (a complex action). */
  async shapeshift(): Promise<boolean> {
    const ss = this.sys.shapeshift;
    if (!ss?.enabled) {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.isNotAShapeshifter', { name: escHtml(this.name) }));
      return false;
    }
    if (!this.canAct('shapeshift')) return false;
    if (!(await this.useAction('shapeshift', tx('SR2E.Card.Actor.shapeshifting')))) return false;
    const to = ss.form === 'human' ? 'animal' : 'human';
    await this.update({ 'system.shapeshift.form': to });
    await ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor: this }), content: `<p><strong>${escText(this.name)}</strong> ${tx('SR2E.Card.Actor.shiftsToForm', { to })}</p>` });
    return true;
  }

  /** Mark or clear exposure to an allergen. */
  async setExposed(powerId: string, exposed: boolean): Promise<void> {
    const it: any = this.items.get?.(powerId);
    if (it?.type === 'power') await it.update({ 'system.exposed': exposed });
  }

  /** A touch of an allergen: the severity's contact damage, unresisted. */
  async allergenContact(powerId: string): Promise<boolean> {
    const it: any = this.items.get?.(powerId);
    if (!it || it.system?.special !== 'allergy') return false;
    const level = allergyContact(it.system.severity);
    if (!level) {
      ui.notifications?.info?.(tx('SR2E.Notify.Actor.aAllergyDoesNoDamageOn', { severity: escHtml(it.system.severity) }));
      return false;
    }
    return this.applyUnresisted({ targetUuid: this.uuid as string, melee: false, damageType: 'physical', power: 0, level });
  }

  /**
   * Essence drain: move Essence from this victim to the caster. v0.81.0 (D1-4): `ed.taken`/`ed.gained` are what this
   * card moved before (a re-roll moves only the difference; `net` 0 gives it all back). The victim's side is written
   * here (the resisting client owns it); a side this client can't write is left to the GM with a note.
   * R2-DOC 2: a side left to the GM counts as moved (`gmGain`/`gmTake`), so a later re-roll asks the GM only for the
   * difference (or to take it back), never for the whole amount again; the card says who moves it.
   */
  async #drainEssence(ed: { casterUuid: string; taken?: number; gained?: number; gmGain?: boolean; gmTake?: boolean }, net: number): Promise<{ html: string; taken: number; gained: number; gmGain: boolean; gmTake: boolean }> {
    const prev = { taken: Math.max(0, Number(ed.taken ?? 0) || 0), gained: Math.max(0, Number(ed.gained ?? 0) || 0) };
    let gmGain = Boolean(ed.gmGain);
    let gmTake = Boolean(ed.gmTake);
    const caster: any = await fromUuid(ed.casterUuid);
    if (!caster) return { html: '', taken: prev.taken, gained: prev.gained, gmGain, gmTake };
    // Both sides as they were before this card moved anything.
    const mine = Number(this.sys.derived?.essence ?? 0) + prev.taken;
    const theirs = Number(caster.system?.derived?.essence ?? 0) - prev.gained;
    const d = net > 0 ? essenceDrained(net, mine, theirs) : { taken: 0, gained: 0 };
    const dTaken = Math.round((d.taken - prev.taken) * 100) / 100;
    const dGained = caster.type === 'spirit' ? 0 : Math.round((d.gained - prev.gained) * 100) / 100;
    if (!dTaken && !dGained) return { html: '', taken: prev.taken, gained: prev.gained, gmGain, gmTake };
    const notes: string[] = [];
    if (dTaken) {
      try { await this.update({ 'system.essenceShift': Math.round(((this.sys.essenceShift ?? 0) - dTaken) * 100) / 100 }); }
      catch (err) {
        console.warn('sr2e | essence drain', err);
        gmTake = true;
        notes.push(`<em>${tx('SR2E.Card.Actor.gmEssenceByHand', { part: dTaken > 0 ? tx('SR2E.Card.Actor.take') : tx('SR2E.Card.Actor.giveBack'), dTaken: Math.abs(dTaken), part2: dTaken > 0 ? tx('SR2E.Card.Actor.from3') : tx('SR2E.Card.Actor.to'), name: escText(this.name) })}</em>`);
      }
    }
    if (dGained) {
      let wrote = false;
      if (canWriteNow(caster)) {
        try { await caster.update({ 'system.essenceShift': Math.round(((caster.system.essenceShift ?? 0) + dGained) * 100) / 100 }); wrote = true; }
        catch (err) { console.warn('sr2e | essence drain', err); }
      }
      if (!wrote) {
        gmGain = true;
        notes.push(`<em>${tx('SR2E.Card.Actor.gmByHand', { part: dGained > 0 ? tx('SR2E.Card.Actor.giveEssence', { casterName: escText(caster.name), dGained }) : tx('SR2E.Card.Actor.takeEssenceBackFrom', { value: -dGained, casterName: escText(caster.name) }) })}</em>`);
      }
    }
    // What the card now stands for: a side left to the GM counts as moved (the GM is asked to move it).
    const taken = d.taken;
    const gained = caster.type === 'spirit' ? 0 : d.gained;
    // Draining counts as feeding for a vampire (v0.45.0), on the first drain only.
    let fed = '';
    if (prev.taken <= 0 && d.taken > 0 && RULES.CRITTERS.diet.drainFeeds && caster.hasCritterPower?.('essenceLoss')) {
      try { if (await caster.feed({ quiet: true })) fed = tx('SR2E.Card.Actor.hasFed', { casterName: escText(caster.name) }); } catch { /* not ours */ }
    }
    const vn = escText(this.name);
    const cn = escText(caster.name);
    const lose = gmTake ? tx('SR2E.Card.Actor.theGmTakesEssenceFrom', { taken: d.taken, vn }) : tx('SR2E.Card.Actor.losesEssence', { vn, taken: d.taken });
    const gain = gained > 0 ? (gmGain ? tx('SR2E.Card.Actor.theGmGives', { cn, gained }) : tx('SR2E.Card.Actor.gains2', { cn, gained })) : '';
    const what = d.taken > 0
      ? `${lose}${gain}${prev.taken > 0 ? tx('SR2E.Card.Actor.was2', { prevTaken: prev.taken }) : ''}`
      : tx('SR2E.Card.Actor.backTheEssenceDrained', { part: gmTake ? tx('SR2E.Card.Actor.theGmGives2', { vn }) : tx('SR2E.Card.Actor.gets', { vn }), prevTaken: prev.taken });
    return { html: `<p><strong>${tx('SR2E.Card.Actor.essenceDrain')}</strong> ${notes.length ? `${notes.join(' ')} ` : ''}${what}.${fed}</p>`, taken, gained, gmGain, gmTake };
  }

  /** Regeneration: heal Physical boxes, except damage from a vulnerability. Returns boxes healed. */
  async regenerateTick(): Promise<number> {
    if (!this.hasCritterPower('regeneration') || !this.sys.monitor) return 0;
    const essence = Number(this.sys.derived?.essence ?? 1);
    if (essence <= 0) return 0;
    const r = regenerate(this.sys.monitor, Number(this.getFlag(SYSTEM_ID, 'noRegen') ?? 0) || 0);
    if (r.healed <= 0) return 0;
    await this.update({ 'system.monitor.physical': r.physical });
    await ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor: this }), content: `<p><strong>${tx('SR2E.Card.Actor.regenerates', { name: escText(this.name) })}</strong> ${tx('SR2E.Card.Actor.ofPhysicalDamage', { plural: escText(plural(r.healed, 'box')) })}</p>` });
    return r.healed;
  }

  /**
   * World-time upkeep for magic and critters (active GM): elementals letting sustained spells
   * drop, Essence loss, and regeneration once per hour outside combat.
   */
  static async magicTicks(now: { worldTime?: number; anyGm?: boolean } = {}): Promise<void> {
    if (!(game as any).user?.isGM) return;
    const active = (game as any).users?.activeGM;
    if (!now.anyGm && active && !isLeadGm()) return;
    const time = now.worldTime ?? sysNow();
    for (const a of SR2Actor.tickActors()) {
      // v0.56.0: permanent spells that have been sustained long enough take, and leave the list.
      await SR2Actor.#permanentTicks(a, time);
      // v0.56.0: a nature spirit leaves at sunrise or sunset.
      await SR2Actor.#departureTick(a, time);
      // Elemental sustaining runs out.
      const list: any[] = [...((a as any).system?.sustaining ?? [])];
      const due = list.filter((e) => e.spiritUuid && typeof e.until === 'number' && e.until >= 0 && e.until <= time);
      if (due.length) {
        await a.update({ 'system.sustaining': list.filter((e) => !due.includes(e)) });
        await ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor: a }),
          content: `<p>${tCount(due.length, 'SR2E.Card.Actor.sElementalsStopSustainingTheSpells', { name: escText(a.name), due: escText(due.map((e) => e.spellName).join(', ')) })}</p>` });
      }
      // Essence loss over time.
      if (a.hasCritterPower('essenceLoss')) {
        const since = Number(a.getFlag(SYSTEM_ID, 'essenceLossAt') ?? NaN);
        if (!Number.isFinite(since)) {
          try { await a.setFlag(SYSTEM_ID, 'essenceLossAt', time); } catch { /* not saved */ }
        } else {
          const n = essenceLossPeriods(since, time);
          if (n > 0) {
            const loss = n * RULES.CRITTERS.essenceLoss.points;
            await a.update({ 'system.essenceShift': Math.round((((a as any).system.essenceShift ?? 0) - loss) * 100) / 100 });
            await a.setFlag(SYSTEM_ID, 'essenceLossAt', since + n * RULES.CRITTERS.essenceLoss.days * 86400);
            await ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor: a }), content: `<p><strong>${tx('SR2E.Card.Actor.losesEssence2', { name: escText(a.name), loss })}</strong> ${tx('SR2E.Card.Actor.toTimeEssenceNow', { derivedEssence: escText((a as any).system.derived?.essence) })}</p>` });
          }
        }
      }
      // Regeneration outside combat: once per hour of world time.
      if (a.hasCritterPower('regeneration') && !(game as any).combat?.started) {
        const last = Number(a.getFlag(SYSTEM_ID, 'regenAt') ?? NaN);
        if (!Number.isFinite(last) || time - last >= 3600) {
          try { await a.setFlag(SYSTEM_ID, 'regenAt', time); } catch { /* not saved */ }
          if (Number.isFinite(last)) await a.regenerateTick();
        }
      }
    }
  }

  /** v0.56.0: permanent spells whose time has come: their effects stay for good and they leave the Sustaining list. */
  static async #permanentTicks(a: any, time: number): Promise<void> {
    const list: any[] = [...(a.system?.sustaining ?? [])];
    const due = list.filter((e) => typeof e.permanentAt === 'number' && e.permanentAt >= 0 && e.permanentAt <= time);
    if (!due.length) return;
    for (const e of due) {
      if (!e.effectId) continue;
      for (const u of (e.targetUuids?.length ? e.targetUuids : [a.uuid])) {
        const t: any = fromUuidSync(u);
        const fx = ((t?.getFlag?.(SYSTEM_ID, 'powerEffects') as any[] | undefined) ?? []).find((x: any) => x.id === e.effectId);
        // v0.81.1 (SEC1-8): only this caster's own spell effect (the sustaining list is its players' to write, and
        // this runs with the GM's rights): another caster's curse or an NPC's buff named here stays as it is.
        const mine = new Set<string>([String(a.uuid), ...((a.selfUuids?.() as string[] | undefined) ?? [])]);
        if (fx && fx.kind === 'spell' && mine.has(String(fx.fromUuid ?? ''))) await SR2Actor.setPowerEffect(u, { ...fx, permanent: true });
      }
    }
    await a.update({ 'system.sustaining': list.filter((e) => !due.includes(e)) });
    await ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor: a }), content: `<p>${tCount(due.length, 'SR2E.Card.Actor.areNowPermanentNoLongerSustains', { due: due.map((e) => `<strong>${escText(e.spellName)}</strong>`).join(', '), name: escText(a.name) })}</p>` });
  }

  /** v0.56.0: a nature spirit whose time is up (RULES.MAGIC_V56.natureSpirits) leaves: it owes nothing more. */
  static async #departureTick(a: any, time: number): Promise<void> {
    if (a.type !== 'spirit' || a.system?.spiritKind !== 'nature') return;
    const at = Number(a.system?.departsAt ?? -1);
    if (!(at >= 0) || time < at || RULES.MAGIC_V56.natureSpirits.departs === 'off') return;
    await a.update({ 'system.departsAt': -1, 'system.services': 0 });
    const sunrise = Math.abs(nextDawnOrDusk(at - 1).at - at) < 1 && nextDawnOrDusk(at - 1).which === 'sunrise';
    await ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor: a }), content: `<p><strong>${escText(a.name)}</strong> ${tx('SR2E.Card.Actor.departsAtItsRemainingServicesAre', { part: sunrise ? tx('SR2E.Card.Actor.sunrise') : tx('SR2E.Card.Actor.sunset') })}</p>` });
  }

  /** A signature an object carries (foci and enchanted items). */
  objectSignature(force: number, label: string): Signature & { actorUuid: string; actorName: string; onObject: true } {
    return {
      id: `${Date.now().toString(36)}${Math.random().toString(36).slice(2, 6)}`, sceneId: '', kind: 'object', label, force,
      worldTime: sysNow(), actorUuid: this.uuid as string, actorName: this.name as string, onObject: true,
    };
  }

  /**
   * Clean an astral signature (v0.39.0): the cleaning skill (defaulting to Magic) vs TN = its Force;
   * each success takes hours off what is left. Needs the signature's owner to be editable (GM or owner).
   */
  async cleanSignature(sig: Signature & { actorUuid: string }, opts: { modifiers?: TargetNumberModifier[] } = {}): Promise<SuccessTestResult | null> {
    const c = RULES.MAGIC_V39.cleaning;
    if (RULES.OCCULT.metamagic.cleansing.signaturesNeedTechnique && !this.#knows('cleansing')) return null;
    if (c.needsAstral && !this.isAstral()) {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.mustBePerceivingOrProjectingAstrally3', { name: escHtml(this.name) }));
      return null;
    }
    if (!this.canAct('cleanSignature')) return null;
    const owner: any = await fromUuid(sig.actorUuid);
    if (!owner) return null;
    const skill = this.findSkill(c.skill);
    const dice = (skill?.system?.rating ?? 0) > 0 ? skill.system.rating : Number(this.sys.derived?.magic ?? 0);
    const r = await this.#runTest(tx('SR2E.Card.Actor.cleanAstralSignatureForce', { sigLabel: sig.label, sigForce: sig.force, part: (skill?.system?.rating ?? 0) > 0 ? '' : tx('SR2E.Card.Actor.magic4') }), dice,
      { targetNumber: Math.max(2, sig.force), modifiers: opts.modifiers ?? [], background: true });
    if (r.successes <= 0) return r;
    const now = sysNow();
    const list: any[] = [...((owner.getFlag(SYSTEM_ID, 'signatures') as Signature[] | undefined) ?? [])];
    const i = list.findIndex((x) => x.id === sig.id);
    if (i < 0) return r;
    const moved = { ...list[i], worldTime: list[i].worldTime - cleaningSeconds(r.successes) };
    const gone = signatureHoursLeft(moved, now) <= 0;
    if (gone) list.splice(i, 1); else list[i] = moved;
    try {
      await owner.setFlag(SYSTEM_ID, 'signatures', list);
      await ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor: this }),
        content: `<p>${gone ? `<strong>${tx('SR2E.Card.Actor.theSignatureIsGone')}</strong>` : tx('SR2E.Card.Actor.theSignatureFadesLeft', { hoursLabel: escText(hoursLabel(signatureHoursLeft(moved, now))) })}</p>` });
    } catch {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.onlyTheGmCanChangeThat'));
    }
    return r;
  }

  /** Ritual sorcery, first stage (v0.39.0): pay for materials and start the preparation clock. */
  async #prepareRitual(spell: any, force: number, opts: any, team: any[], spotter: any): Promise<void> {
    const cost = ritualMaterialsCost(force, String(spell?.system?.category ?? ''));
    if (cost > 0) {
      const nuyen = Number(this.sys.nuyen ?? 0);
      if (nuyen < cost) {
        ui.notifications?.warn?.(tx('SR2E.Notify.Actor.ritualMaterialsForForceCostHas', { force, cost, name: escHtml(this.name), nuyen }));
        return;
      }
      // v0.81.0 (D3-15): through adjustNuyen, so it is in the ledger.
      if (!(await this.adjustNuyen(-cost, tx('SR2E.Text.Actor.ritualMaterialsForce', { name: spell?.name ?? tx('SR2E.Text.Actor.spell'), force })))) return;
    }
    const hours = ritualHours(force);
    const startedAt = sysNow();
    const names = [this.name, ...team.map((m) => m.name)];
    await ChatMessage.create({
      speaker: ChatMessage.getSpeaker({ actor: this }),
      content: `<div class="sr2e-roll"><h3>${tx('SR2E.Card.Actor.ritualForce', { spellName: escText(spell.name), force })}</h3>
        <p>${tx('SR2E.Card.Actor.preparationBeginsItTakes', { names: escText(names.join(', ')), part: spotter ? tx('SR2E.Card.Actor.withSpotting', { spotterName: escText(spotter.name) }) : '' })} <strong>${escText(hoursLabel(hours))}</strong>${cost ? tx('SR2E.Card.Actor.materialsCost', { cost }) : ''}.</p>
        <p>${tx('SR2E.Card.Actor.whenThePreparationIsDoneThe')}</p>
        <p><button type="button" data-sr2e-action="sendRitual">${tx('SR2E.Card.Actor.sendTheSpell')}</button></p></div>`,
      flags: { [SYSTEM_ID]: { ritualPrep: {
        casterUuid: this.uuid, spellId: spell.id, force, startedAt, hours,
        opts: { force, targetUuids: opts.targetUuids ?? [], poolDice: opts.poolDice ?? 0, drainPoolDice: opts.drainPoolDice ?? 0,
          ritual: { ...(opts.ritual ?? {}), sending: true } },
      } } },
    });
    // The targets may notice it coming (v0.45.0).
    await SR2Actor.ritualNoticeCards(opts.targetUuids ?? [], { spellName: spell.name, force, casterName: this.name as string });
  }

  /** Ritual sorcery, second stage: send the prepared spell (from the preparation card). */
  static async sendRitual(prep: { casterUuid: string; spellId: string; startedAt: number; hours: number; opts: any }, isGm: boolean): Promise<boolean> {
    const caster: any = await fromUuid(prep.casterUuid);
    const spell: any = caster?.items?.get?.(prep.spellId);
    if (!caster || !spell) {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.theRitualLeaderOrTheSpell'));
      return false;
    }
    // v0.81.1 (SEC1-1): a GM sending a player's ritual (runAsAuthor) waits for the preparation as the player would.
    isGm = Boolean(isGm) && Boolean((game as any).user?.isGM);
    const left = ritualPrepLeft(Number(prep.startedAt) || 0, sysNow(), Number(prep.hours) || 0);
    const wait = RULES.MAGIC_V39.ritualStages.waitForPrep;
    if (left > 0 && wait !== 'off') {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.theRitualNeedsMorePreparation', { hoursLabel: hoursLabel(left), part: wait === 'block' && !isGm ? '' : tx('SR2E.Notify.Actor.sendingAnyway') }));
      if (wait === 'block' && !isGm) return false;
    }
    await caster.castSpell(spell, prep.opts);
    return true;
  }

  // ---------------------------------------------------------------- Magic and critters (v0.45.0)

  /** A short random id. */
  static #newId(): string {
    return (foundry as any).utils?.randomID?.() ?? `${Date.now().toString(36)}${Math.random().toString(36).slice(2, 8)}`;
  }

  /** GMs and this actor's owners (for whispered cards). */
  #ownersAndGms(): string[] {
    return [...((game as any).users ?? [])].filter((u: any) => u.isGM || (this as any).testUserPermission?.(u, 'OWNER')).map((u: any) => u.id);
  }

  /** The UUIDs this actor goes by: its own, and its base actor's when it is a token's actor. */
  selfUuids(): string[] {
    const out = [this.uuid as string];
    const base: any = (this as any).isToken ? (game as any).actors?.get?.((this as any).id) : null;
    if (base?.uuid && !out.includes(base.uuid)) out.push(base.uuid);
    return out;
  }

  /** "+2 Strength, −1 Quickness" for a set of attribute changes. */
  static describeChanges(attributes: Record<string, number>): string {
    const parts = Object.entries(attributes ?? {}).filter(([, v]) => v).map(([k, v]) => `${v > 0 ? '+' : '−'}${Math.abs(v)} ${cap(k)}`);
    return parts.length ? parts.join(', ') : 'no change';
  }

  /** A failed (or failing) knowledge of a technique: warns and returns false. */
  #knows(technique: string): boolean {
    if (this.initiate.techniques.includes(technique)) return true;
    ui.notifications?.warn?.(tx('SR2E.Notify.Actor.doesNotKnowTheMetamagic', { name: escHtml(this.name), technique }));
    return false;
  }

  /** Dice for an initiate's skill-based technique: the skill, else Magic. */
  #techniqueDice(skillName: string): { dice: number; note: string } {
    const skill = this.findSkill(skillName);
    return (skill?.system?.rating ?? 0) > 0 ? { dice: skill.system.rating, note: `${skill.name} ${skill.system.rating}` } : { dice: Number(this.sys.derived?.magic ?? 0), note: tx('SR2E.Card.Actor.magic', { derivedMagic: Number(this.sys.derived?.magic ?? 0) }) };
  }

  /** Cleansing: lower the background count where this initiate is (RULES.OCCULT.metamagic.cleansing). */
  async cleanse(opts: { modifiers?: TargetNumberModifier[] } = {}): Promise<SuccessTestResult | null> {
    if (!this.#knows('cleansing')) return null;
    const c = RULES.OCCULT.metamagic.cleansing;
    if (c.needsAstral && !this.isAstral()) {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.mustBePerceivingOrProjectingAstrally4', { name: escHtml(this.name) }));
      return null;
    }
    if (!this.canAct('cleanse')) return null;
    const scene: any = game.scenes?.viewed ?? game.scenes?.current;
    if (!scene) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.openASceneFirstBackgroundCount2')); return null; }
    const info = this.backgroundInfo();
    if (info.penalty <= 0) { ui.notifications?.info?.(tx('SR2E.Notify.Actor.thereIsNoBackgroundCountHere')); return null; }
    const d = this.#techniqueDice(c.skill);
    return this.#runTest(tx('SR2E.Card.Actor.cleansingBackgroundCount', { infoPenalty: info.penalty, part: info.toxic ? tx('SR2E.Card.Actor.toxic') : '', note: d.note }), d.dice,
      // The count is already the TN; it doesn't also add its own penalty (live run, v0.45.0).
      { targetNumber: cleansingTn(info.penalty, info.toxic), modifiers: opts.modifiers ?? [], astralAct: true },
      { kind: 'cleanse', cleanse: { sceneId: scene.id, count: info.penalty, applied: 0, align: this.alignTags() } });
  }

  async #resolveCleanse(snap: TestSnapshot): Promise<Resolved> {
    const c = snap.cleanse!;
    const pts = Math.min(cleansingPoints(snap.successes), Math.max(0, c.count));
    if (pts <= 0 && c.projectId) return { html: `<p><strong>${tx('SR2E.Card.Actor.theBackgroundCountHolds')}</strong>${await this.dropProjectOnFailure(c.projectId)}</p>`, flags: {}, snap: { ...snap, cleanse: { ...c, applied: 0, projectId: undefined } } };
    if (pts <= 0) return { html: `<p><strong>${tx('SR2E.Card.Actor.theBackgroundCountHolds')}</strong> ${tx('SR2E.Card.Actor.successesTakeOff1Point', { cleansingSuccessesPerPoint: RULES.OCCULT.metamagic.cleansing.successesPerPoint })}</p>`, flags: {}, snap };
    const hours = pts * RULES.OCCULT.metamagic.cleansing.hoursPerPoint;
    let html = `<p><strong>${tCount(pts, 'SR2E.Card.Actor.cleansedPoints')}</strong> ${tx('SR2E.Card.Actor.ofBackgroundCountOfWork', { hoursLabel: escText(hoursLabel(hours)) })}</p>`;
    // v0.65.0: the background count drops when the work's hours have passed (a re-roll changes the points and hours).
    if (c.projectId || (this.waitsFor('magic') && pts > c.applied && c.applied === 0)) {
      const p = this.projects().find((x) => x.id === c.projectId);
      const effect: ProjectEffect = { call: { method: 'finishCleanse', args: [c.sceneId, pts, c.align] } };
      let id = p?.id;
      if (p) await this.update({ [`flags.${SYSTEM_ID}.projects.${p.id}`]: { ...retimed(p, hours), effect } });
      else if (!c.projectId) id = (await this.startProject({ kind: 'cleanse', area: 'magic', label: tCount(pts, 'SR2E.Text.Actor.cleansingPointsOfBackgroundCount'), hours, effect })).id;
      else return { html: `${html}<p><em>${tx('SR2E.Card.Actor.theCleansingIsOverOrWas')}</em></p>`, flags: {}, snap };
      return { html: `${html}<p>${tx('SR2E.Card.Actor.theCountDropsWhenTheTime')}</p>`, flags: {}, snap: { ...snap, cleanse: { ...c, applied: pts, projectId: id } } };
    }
    const delta = pts - c.applied;
    let flags: Record<string, unknown> = {};
    if (delta > 0) {
      if (isGmNow()) await SR2Actor.applyCleansing(c.sceneId, delta, c.align);
      else {
        html += `<p><button type="button" data-sr2e-action="applyCleanse">${tx('SR2E.Card.Actor.applyToTheSceneGm')}</button></p>`;
        flags = { cleanse: { sceneId: c.sceneId, points: delta, align: c.align } };
      }
    }
    return { html, flags, snap: { ...snap, cleanse: { ...c, applied: Math.max(c.applied, pts) } } };
  }

  /** v0.65.0: a cleansing's time has passed (on the GM's client): the scene's background count drops. */
  async finishCleanse(sceneId: string, points: number, align: string[] = []): Promise<boolean> {
    // v0.81.1 (D3-3): a player's cleansing (their project data) waits for the GM's Apply, as one done at once does;
    // only a project no player owns lowers the count by itself.
    if (this.#playerOwners().length) {
      const scene: any = (game as any).scenes?.get?.(sceneId);
      if (!scene) return false;
      const pts = safeInt(points, 0, MAX_BACKGROUND_COUNT, 0);
      const gms = [...((game as any).users ?? [])].filter((u: any) => u.isGM).map((u: any) => u.id);
      await ChatMessage.create({
        speaker: ChatMessage.getSpeaker({ actor: this }), whisper: gms,
        content: `<p><em>${tx('SR2E.Card.Actor.gmOnly')}</em> ${tx('SR2E.Card.Actor.sCleansingIsDoneSBackground', { name: escText(this.name), sceneName: escText(scene.name), pts })}</p><p><button type="button" data-sr2e-action="applyCleanse">${tx('SR2E.Card.Actor.applyToTheSceneGm')}</button></p>`,
        flags: { [SYSTEM_ID]: { cleanse: { sceneId: String(sceneId), points: pts, align: (align ?? []).map((x) => String(x)).slice(0, 20), sourceUuid: this.uuid } } },
      });
      return true;
    }
    return SR2Actor.applyCleansing(sceneId, safeInt(points, 0, MAX_BACKGROUND_COUNT, 0), align ?? []);
  }

  /** GM: take points off a scene's background count (plain count first, then unaligned sources). */
  static async applyCleansing(sceneId: string, points: number, align: string[] = []): Promise<boolean> {
    if (!isGmNow()) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.onlyTheGmChangesAScene')); return false; }
    const scene: any = game.scenes?.get?.(sceneId);
    if (!scene) return false;
    const plain = Number(scene.getFlag(SYSTEM_ID, 'backgroundCount') ?? 0) || 0;
    const sources = parseBackgroundSources(String(scene.getFlag(SYSTEM_ID, 'backgroundSources') ?? ''));
    const r = applyCleansing(plain, sources, points, align);
    await scene.setFlag(SYSTEM_ID, 'backgroundCount', r.plain);
    await scene.setFlag(SYSTEM_ID, 'backgroundSources', formatBackgroundSources(r.sources));
    await ChatMessage.create({ speaker: { alias: tx('SR2E.Card.Actor.backgroundCount') }, content: `<p>${tx('SR2E.Card.Actor.theBackgroundCountDropsByNow', { sceneName: escText(scene.name), removed: r.removed, plain: Math.max(r.plain, ...r.sources.map((s) => s.rating), 0) })}</p>` });
    return true;
  }

  /** Divining: ask a question of the future; whispered to the GMs and this actor's owners. */
  async divine(o: { question?: string; weeksAhead?: number; text?: string; modifiers?: TargetNumberModifier[] } = {}): Promise<SuccessTestResult | null> {
    if (!this.#knows('divining')) return null;
    if (!this.canAct('divine')) return null;
    const t = diviningTn(o.question ?? 'general', o.weeksAhead ?? 0);
    const d = this.#techniqueDice(RULES.OCCULT.metamagic.divining.skill);
    return this.#runTest(tx('SR2E.Card.Actor.divining', { text: o.text?.trim() || t.label, part: o.weeksAhead ? tCount(o.weeksAhead, 'SR2E.Card.Actor.weeksAhead') : '', note: d.note }), d.dice,
      { targetNumber: t.tn, modifiers: o.modifiers ?? [], magical: true },
      { kind: 'divine', divine: { question: o.text?.trim() || t.label }, privateTo: this.#ownersAndGms() });
  }

  /** Invoking: make one of this initiate's spirits a great form spirit. */
  async invoke(spiritUuid: string, opts: { poolDice?: number; drainPoolDice?: number } = {}): Promise<SuccessTestResult | null> {
    if (!this.#knows('invoking')) return null;
    if (!this.canAct('invoke')) return null;
    const spirit: any = await fromUuid(spiritUuid);
    if (!spirit || spirit.type !== 'spirit') return null;
    const mine = this.selfUuids();
    const summoner = String(spirit.system.summonerUuid ?? '');
    const problem = invokeProblem({ kind: spirit.system.spiritKind, summonerUuid: mine.includes(summoner) ? (this.uuid as string) : summoner, services: spirit.system.services ?? 0, greatForm: Boolean(spirit.system.greatForm) }, this.uuid as string);
    if (problem) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.canTInvoke', { spiritName: escHtml(spirit.name), problem })); return null; }
    const skill = this.#conjuringSkill();
    if (!skill) return null;
    const iv = RULES.OCCULT.metamagic.invoking;
    const force = Number(spirit.system.force ?? 1);
    if (iv.servicesCost > 0) await spirit.update({ 'system.services': Math.max(0, (spirit.system.services ?? 0) - iv.servicesCost) });
    const extra = bonusNote(conjuringFocusDice(this.foci(), { kind: spirit.system.spiritKind, type: spirit.system.spiritType ?? '' }), totemConjuringDice(this.tradition, this.sys.totem, { kind: spirit.system.spiritKind, type: spirit.system.spiritType ?? '', domain: spirit.system.domain ?? '' }));
    const result = await this.#runTest(tx('SR2E.Card.Actor.invokeIntoAGreatFormForce', { spiritName: spirit.name, force, invokingTn: invokingTn(force), extraNote: extra.note }), Math.max(0, skill.system.rating + extra.dice),
      { targetNumber: invokingTn(force), poolDice: RULES.CONJURING.spellPoolAllowed ? opts.poolDice ?? 0 : 0, pool: 'spell', magical: true },
      { kind: 'invoke', invoke: { spiritUuid: spirit.uuid as string, spiritName: spirit.name as string } });
    await this.leaveSignature('summoning', tx('SR2E.Text.Actor.invoking', { name: spirit.name }), force);
    await this.#conjuringDrain(force + iv.drainForceBonus, opts.drainPoolDice ?? 0);
    return result;
  }

  async #resolveInvoke(snap: TestSnapshot): Promise<Resolved> {
    const v = snap.invoke!;
    const iv = RULES.OCCULT.metamagic.invoking;
    if (snap.successes <= 0) return { html: `<p><strong>${tx('SR2E.Card.Actor.theInvocationFails')}</strong> ${tx('SR2E.Card.Actor.keepsItsUsualForm', { spiritName: escText(v.spiritName) })}</p>`, flags: {}, snap };
    if (!v.applied) {
      const spirit: any = await fromUuid(v.spiritUuid);
      try { await spirit?.update({ 'system.greatForm': true }); } catch { /* not ours */ }
    }
    return { html: `<p><strong>${tx('SR2E.Card.Actor.takesAGreatForm', { spiritName: escText(v.spiritName) })}</strong>${tx('SR2E.Card.Actor.toEveryAttributeToItsPowers', { ivAttributeBonus: iv.attributeBonus, ivPowerBonus: iv.powerBonus })}</p>`, flags: {}, snap: { ...snap, invoke: { ...v, applied: true } } };
  }

  /** Possessing: a projecting initiate takes over a body (opposed Willpower tests). */
  async possess(targetUuid: string, opts: { modifiers?: TargetNumberModifier[] } = {}): Promise<boolean> {
    if (!this.#knows('possessing')) return false;
    if (this.sys.derived?.astralMode !== 'projecting') { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.mustBeProjectingToPossessA', { name: escHtml(this.name) })); return false; }
    if (this.getFlag(SYSTEM_ID, 'possessing')) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.isAlreadyPossessingSomeone', { name: escHtml(this.name) })); return false; }
    if (!this.canAct('possess')) return false;
    const target: any = await fromUuid(targetUuid);
    if (!target?.system?.attributes || target.uuid === this.uuid || target.type === 'vehicle') return false;
    if (target.getFlag?.(SYSTEM_ID, 'possessedBy')) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.isAlreadyPossessed', { targetName: escHtml(target.name) })); return false; }
    const p = RULES.OCCULT.metamagic.possessing;
    const myWil = Number(this.sys.attributes.willpower.total ?? 0);
    const theirWil = Number(target.system.attributes.willpower?.total ?? 0);
    const grade = p.diceFromGrade ? this.initiate.grade : 0;
    const rolls: any[] = [];
    const mine = await successTest({ dice: myWil + grade, targetNumber: Math.max(2, theirWil), modifiers: this.#testModifiers({ modifiers: opts.modifiers ?? [], magical: true }), roll: foundryRoller(rolls) });
    const theirs = await successTest({ dice: theirWil, targetNumber: Math.max(2, myWil), modifiers: [], roll: foundryRoller(rolls) });
    const o = possessionOutcome(mine.successes, theirs.successes);
    await ChatMessage.create({
      speaker: ChatMessage.getSpeaker({ actor: this }), rolls,
      content: `${describeResult(tx('SR2E.Card.Actor.triesToPossessWillpowerVs', { name: this.name, targetName: target.name, myWil, part: grade ? tx('SR2E.Card.Actor.grade', { grade }) : '', theirWil }), mine)}${describeResult(tx('SR2E.Card.Actor.resistsWillpowerVs', { targetName: target.name, theirWil, myWil }), theirs)}
        <p>${o.possessed ? `<strong>${tx('SR2E.Card.Actor.possesses', { name: escText(this.name), targetName: escText(target.name) })}</strong> ${tx('SR2E.Card.Actor.netTheBodyThinksWithS', { net: o.net, name: escText(this.name) })}` : `<strong>${tx('SR2E.Card.Actor.keepsOut', { targetName: escText(target.name), name: escText(this.name) })}</strong>`}</p>`,
    });
    if (!o.possessed) return false;
    await this.setFlag(SYSTEM_ID, 'possessing', { uuid: target.uuid, name: target.name });
    await SR2Actor.setPossession(target.uuid as string, this.#possessionBy());
    await this.leaveSignature('power', tx('SR2E.Text.Actor.possessing', { name: target.name }), Math.max(1, Number(this.sys.derived?.magic ?? 1)));
    return true;
  }

  /** GM or the body's owner: set (or clear, with null) who possesses a body; others post a card for the GM. */
  /** What a possessed body takes from this possessor: its mental attributes and (v0.48.0) its skills. */
  #possessionBy(): { uuid: string; name: string; attributes: Record<string, number>; skills: SkillCopy[] } {
    const p = RULES.OCCULT.metamagic.possessing;
    const attributes = Object.fromEntries(p.mental.map((k) => [k, Number(this.sys.attributes?.[k]?.total ?? 0)]));
    // v0.48.0: the possessor's skills come along (which ones count: RULES.OCCULT.metamagic.possessing.skills).
    const skills = [...this.items].filter((i: any) => i.type === 'skill').map((i: any) => skillCopy(i));
    return { uuid: this.uuid as string, name: this.name as string, attributes, skills };
  }

  static async setPossession(targetUuid: string, byIn: { uuid: string; name: string; attributes: Record<string, number>; skills?: SkillCopy[] } | null): Promise<boolean> {
    const t: any = await fromUuid(targetUuid);
    if (!t) return false;
    // v0.81.1 (D3-5, SEC1-7): only who possesses comes from the caller (a card): the name, attributes and skills the
    // body takes are the possessor's own, read here; and the possessor must be possessing this very body.
    let by: { uuid: string; name: string; attributes: Record<string, number>; skills?: SkillCopy[] } | null = null;
    if (byIn) {
      const who: any = await fromUuid(String(byIn.uuid ?? ''));
      const mine = who?.getFlag?.(SYSTEM_ID, 'possessing') as { uuid?: string } | undefined;
      if (!(who instanceof SR2Actor) || mine?.uuid !== t.uuid) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.thatPossessorIsnTPossessingThem', { tName: escText(t.name) })); return false; }
      by = who.#possessionBy();
    }
    if (!canWriteNow(t)) {
      await ChatMessage.create({
        speaker: { alias: tx('SR2E.Card.Actor.possession') },
        content: `<p><em>${tx('SR2E.Card.Actor.gmOnly')}</em> · ${by ? tx('SR2E.Card.Actor.possesses2', { byName: escText(by.name), name: escText(t.name) }) : tx('SR2E.Card.Actor.isFree2', { name: escText(t.name) })}.</p><p><button type="button" data-sr2e-action="applyPossession">${tx('SR2E.Card.Actor.applyGm')}</button></p>`,
        whisper: [...((game as any).users ?? [])].filter((u: any) => u.isGM).map((u: any) => u.id),
        flags: { [SYSTEM_ID]: { possession: { targetUuid, by } } },
      });
      return false;
    }
    if (by) await t.setFlag(SYSTEM_ID, 'possessedBy', by);
    else await clearFlag(t, 'possessedBy');
    return true;
  }

  /** End a possession, from either side. */
  async endPossession(): Promise<void> {
    const mine = this.getFlag(SYSTEM_ID, 'possessing') as { uuid: string; name: string } | undefined;
    if (mine) {
      await clearFlag(this, 'possessing');
      await SR2Actor.setPossession(mine.uuid, null);
      await ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor: this }), content: `<p><strong>${escText(this.name)}</strong> ${tx('SR2E.Card.Actor.leavesSBody', { mineName: escText(mine.name) })}</p>` });
    }
    const by = this.getFlag(SYSTEM_ID, 'possessedBy') as { uuid: string; name: string } | undefined;
    if (by) {
      await clearFlag(this, 'possessedBy');
      const p: any = await fromUuid(by.uuid);
      try { if (p?.getFlag?.(SYSTEM_ID, 'possessing')) await clearFlag(p, 'possessing'); } catch { /* not ours */ }
      await ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor: this }), content: `<p><strong>${escText(this.name)}</strong> ${tx('SR2E.Card.Actor.isFreeOf', { byName: escText(by.name) })}</p>` });
    }
  }

  /** Reflecting: the button that bounces a resisted spell back at its caster, if any successes are left over. */
  #reflection(ctx: SoakContext, successes: number): { html: string; flags: Record<string, unknown> } {
    const r = ctx.reflect;
    if (!r) return { html: '', flags: {} };
    const n = reflectedSuccesses(ctx.casterSuccesses ?? 0, successes, r.defense);
    if (n <= 0) return { html: '', flags: {} };
    const caster: any = fromUuidSync(r.casterUuid);
    const spell: SpellState = {
      casterUuid: this.uuid as string, targetUuid: r.casterUuid, spellName: `${r.spellName} (reflected)`, force: r.force,
      resistAttribute: r.resistAttribute, level: r.level, damageType: r.damageType, casterSuccesses: n,
      noun: r.noun === 'power' ? 'power' : 'spell', resistPool: (r.noun === 'power' ? (r.resistPool ?? 'none') : 'spell') as any, reflected: true,
      ...(r.effectOnly ? { effectOnly: true } : {}),
    };
    return {
      html: `<p><strong>${tx('SR2E.Card.Actor.reflected')}</strong> ${tx('SR2E.Card.Actor.turnsBackWith', { name: escText(this.name), spellName: escText(r.spellName), plural: escText(plural(n, 'success')) })} <button type="button" data-sr2e-action="resistSpell" data-index="0">${tx('SR2E.Card.Actor.resist9', { part: r.noun === 'power' ? tx('SR2E.Card.Actor.power4') : tx('SR2E.Card.Actor.spell'), casterName: escText(caster?.name ?? tx('SR2E.Card.Actor.theCaster')) })}</button></p>`,
      flags: { spell, spells: [spell] },
    };
  }

  /** Magical groups (world setting sr2e.magicGroups). */
  static magicGroups(): MagicGroup[] {
    try { return [...(((game as any).settings?.get?.(SYSTEM_ID, 'magicGroups') as any[] | undefined) ?? [])].map(normalizeGroup); } catch { return []; }
  }

  /** GM: save the magical groups. */
  static async saveMagicGroups(list: MagicGroup[]): Promise<boolean> {
    if (!isGmNow()) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.onlyTheGmChangesMagicalGroups')); return false; }
    await (game as any).settings.set(SYSTEM_ID, 'magicGroups', list.map(normalizeGroup));
    for (const a of allActors()) { try { if (a.sheet?.rendered) a.sheet.render(); } catch { /* no sheet */ } }
    return true;
  }

  /** GM: change one group (by id) with a function, then save. */
  static async updateMagicGroup(id: string, fn: (g: MagicGroup) => MagicGroup | null): Promise<boolean> {
    const list = SR2Actor.magicGroups();
    const i = list.findIndex((g) => g.id === id);
    if (i < 0) return false;
    const next = fn(list[i]!);
    if (next) list[i] = next; else list.splice(i, 1);
    return SR2Actor.saveMagicGroups(list);
  }

  /** The magical groups this actor belongs to. */
  myGroups(): MagicGroup[] {
    return groupsOf(SR2Actor.magicGroups(), this.selfUuids());
  }

  /** Add a spell to a group's grimoire: the GM directly; members post a card for the GM. */
  async addToGrimoire(groupId: string, spell: any): Promise<boolean> {
    const g = this.myGroups().find((x) => x.id === groupId);
    if (!g) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.isNotInThatGroup', { name: escHtml(this.name) })); return false; }
    const entry = { name: String(spell.name), system: { ...(spell.system?.toObject?.() ?? spell.system ?? {}) } };
    delete (entry.system as any).description;
    if (!isGmNow()) {
      await ChatMessage.create({
        speaker: ChatMessage.getSpeaker({ actor: this }),
        content: `<p>${tx('SR2E.Card.Actor.offers', { name: escText(this.name) })} <strong>${escText(entry.name)}</strong> ${tx('SR2E.Card.Actor.toSGrimoire', { name: escText(g.name) })}</p><p><button type="button" data-sr2e-action="grimoireAdd">${tx('SR2E.Card.Actor.addItGm')}</button></p>`,
        flags: { [SYSTEM_ID]: { grimoire: { groupId, entry } } },
      });
      return false;
    }
    return SR2Actor.addGrimoireEntry(groupId, entry);
  }

  /** GM: put a spell formula in a group's grimoire. */
  static async addGrimoireEntry(groupId: string, entry: { name: string; system: Record<string, unknown> }): Promise<boolean> {
    let name = '';
    const ok = await SR2Actor.updateMagicGroup(groupId, (g) => {
      name = g.name;
      return { ...g, grimoire: [...g.grimoire.filter((s) => s.name !== entry.name), entry] };
    });
    if (ok) await ChatMessage.create({ speaker: { alias: name || tx('SR2E.Card.Actor.grimoire') }, content: `<p><strong>${escText(entry.name)}</strong> ${tx('SR2E.Card.Actor.isNowInSGrimoire', { name: escText(name) })}</p>` });
    return ok;
  }

  /**
   * v0.91.8 (RULES.FORMULA_V918.required): where a character out of creation learns `name` at `force` from: the best
   * spell formula they hold (their own tradition first), as `{ from: its name, foreign }`. Not required (off, an NPC, in
   * creation): `{ from: '', foreign: false }`. Required and none held: a notice, and null.
   */
  #formulaSource(name: string, force: number, required: boolean): { from: string; foreign: boolean } | null {
    const learner = learnerTradition(this.sys.tradition);
    const held = bestFormula([...this.items].filter((i: any) => i.type === 'gear'), String(name ?? ''), force, learner) as any;
    if (held) return { from: String(held.name), foreign: isForeign(held.system.formula.tradition, learner) };
    if (!required || this.type !== 'character' || inCreation(this)) return { from: '', foreign: false };
    ui.notifications?.warn?.(tx('SR2E.Notify.Formula.needsOne', { name: escHtml(this.name), spell: escHtml(name), force }));
    return null;
  }

  /**
   * v0.91.8: can a study of `spell` at `force` go ahead (the Good Karma; with learning tests, the skill and a site the
   * house rule demands)? A notice when not. Checked before a teacher's card is used and before their fee is paid.
   */
  #canStudy(spell: string, force: number): boolean {
    const cost = spellKarmaCost(force);
    const good = Number(this.sys.karma?.good ?? 0);
    if (good < cost) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.learningAtForceCostsGoodKarma', { name: escHtml(spell), force, cost, name2: escHtml(this.name), good })); return false; }
    const L = RULES.MAGIC_V56.learning;
    if (!L.enabled) return true;
    if (!(Number(this.findSkill(L.skill)?.system?.rating ?? 0) > 0)) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.needsToLearnSpells', { name: escHtml(this.name), lSkill: L.skill })); return false; }
    const problem = L.site === 'block' ? this.#learnSiteProblem(force) : '';
    if (problem) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.needsToLearnAtForce', { name: escHtml(this.name), problem: escHtml(problem), name2: escHtml(spell), force, part: '' })); return false; }
    return true;
  }

  /** v0.91.8: one of this character's formula items as a source for `spell` at `force` (null with a notice when it isn't). */
  #formulaItemSource(id: string, spell: string, force: number): { from: string; foreign: boolean } | null {
    const it: any = this.items.get?.(String(id ?? ''));
    if (!it || it.type !== 'gear' || !isFormula(it.system) || it.system.formula.spell !== spell || formulaForce(it.system.formula.force) < force) { ui.notifications?.warn?.(tx('SR2E.Notify.Formula.notThatFormula', { name: escHtml(this.name), spell: escHtml(spell), force })); return null; }
    return { from: String(it.name), foreign: isForeign(it.system.formula.tradition, learnerTradition(this.sys.tradition)) };
  }

  /**
   * v0.91.8: a teacher's help, read again from their card (never from a request): the card must be a teacher's test for
   * this character and `spell` at `force` or more, posted by the user learning (the filer of an approved request) or a
   * GM; the teacher must still know the spell. Their Sorcery, the fee and the tradition are worked out again here; the
   * dice are the card's own successes, up to the Sorcery. Null (with a notice) when not.
   */
  async #teachHelp(messageId: string, spell: string, force: number): Promise<{ dice: number; from: string; foreign: boolean; fee: number } | null> {
    const refuse = () => { ui.notifications?.warn?.(tx('SR2E.Notify.Formula.notThatTeaching')); return null; };
    const m: any = (game as any).messages?.get?.(String(messageId ?? ''));
    const snap: any = m?.getFlag?.(SYSTEM_ID, 'test') ?? m?.flags?.[SYSTEM_ID]?.test;
    const t = snap?.teach;
    if (!t || t.studentUuid !== this.uuid || t.spell !== spell || formulaForce(t.force) < force) return refuse();
    const ctx = approvalContext(String(this.uuid ?? ''));
    const who = ctx?.requesterId ?? game.user?.id;
    const by = m?.author?.id ?? m?.author ?? m?.user?.id ?? m?.user;
    if (!by || (by !== who && !(game as any).users?.get?.(by)?.isGM)) return refuse();
    const inst: any = await fromUuid(String(t.teacherUuid ?? ''));
    if (!(inst instanceof SR2Actor) || inst.uuid === this.uuid) return refuse();
    const theirs = [...inst.items].filter((i: any) => i.type === 'spell').map((i: any) => ({ name: String(i.name), system: i.system }));
    if (!canTeach(theirs, spell, force)) return refuse();
    const sorcery = Number(inst.findSkill(RULES.MAGIC_V56.learning.skill)?.system?.rating ?? 0);
    return {
      dice: teacherDice(snap.successes, sorcery), from: String(inst.name),
      foreign: isForeign(learnerTradition(inst.sys.tradition), learnerTradition(this.sys.tradition)),
      fee: teacherFee(formulaForce(t.force), Boolean(inst.hasPlayerOwner)),
    };
  }

  /** v0.91.8: pay a teacher's fee once the study can go ahead (#canStudy); false when it can't or the money isn't there. */
  async #payTeacher(fee: number, spell: string, force: number): Promise<boolean> {
    if (!this.#canStudy(spell, force)) return false;
    const f = Math.max(0, Math.round(Number(fee) || 0));
    if (!f) return true;
    return Boolean(await this.adjustNuyen(-f, tx('SR2E.Text.Formula.teacherFee', { spell })));
  }

  /**
   * Learn a spell from a spell formula (a design or a grimoire) for Good Karma = Force. v0.91.8: `o.origin` 'shop' (the
   * shop's Learn) needs a formula the character holds (RULES.FORMULA_V918.required); 'formula' is one of their formula
   * items (`o.formulaId`); `o.teach` is a teacher's help (their dice, name, tradition and fee, from their card).
   */
  async learnFormula(name: string, system: Record<string, unknown>, from = 'a formula', o: { origin?: 'shop' | 'formula' | 'design' | 'grimoire'; formulaId?: string; teachMessage?: string } = {}): Promise<boolean> {
    if ([...this.items].some((i: any) => i.type === 'spell' && i.name === name)) {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.alreadyKnows2', { name: escHtml(this.name), name2: escHtml(name) }));
      return false;
    }
    if (this.projects().some((p) => p.kind === 'learn' && (p.subject === name || (p.subject === undefined && p.label.startsWith(`Learning ${name} at`))))) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.isAlreadyStudying2', { name: escHtml(this.name), name2: escHtml(name) })); return false; }
    const force = Math.max(1, Number((system as any).learnedForce ?? 1));
    // v0.91.8: where it is learned from (a held formula, one formula item, a teacher), and the other tradition's penalty.
    // A design or the group's grimoire needs no formula; anything else (the shop, a request, a call without an origin) does.
    let foreign = false;
    const help = o.teachMessage ? await this.#teachHelp(o.teachMessage, name, force) : null;
    if (o.teachMessage && !help) return false;
    if (help) { from = help.from; foreign = help.foreign; }
    else if (o.origin === 'formula') {
      const src = this.#formulaItemSource(String(o.formulaId ?? ''), name, force);
      if (!src) return false;
      from = src.from; foreign = src.foreign;
    } else if (o.origin !== 'design' && o.origin !== 'grimoire') {
      const src = this.#formulaSource(name, force, formulasRequired());
      if (!src) return false;
      if (src.from) from = src.from;
      foreign = src.foreign;
    }
    // v0.64.0: with the approval queue on, a player's new spell waits for the GM.
    if (approvalNeeded(this)) { await fileRequest(this, { kind: 'spellForce', label: RULES.MAGIC_V56.learning.enabled ? tx('SR2E.Text.Actor.learnForceLearningTest', { name, force }) : tx('SR2E.Text.Actor.learnForce', { name, force }), karma: spellKarmaCost(force), data: { method: 'learnFormula', args: [name, { ...system }, from, o] } }); return false; }
    // v0.91.8: the teacher's fee only once the study can go ahead (a refused study pays no one).
    if (help && !(await this.#payTeacher(help.fee, name, force))) return false;
    // v0.56.0: a learning test (RULES.MAGIC_V56.learning); the spell is written and Karma paid on success.
    if (RULES.MAGIC_V56.learning.enabled) {
      const r = await this.learnSpellTest({ name, force, system, from, foreign, extraDice: help?.dice ?? 0 });
      return Boolean(r && r.successes > 0);
    }
    const cost = spellKarmaCost(force);
    const good = Number(this.sys.karma?.good ?? 0);
    if (good < cost) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.learningAtForceCostsGoodKarma', { name: escHtml(name), force, cost, name2: escHtml(this.name), good })); return false; }
    // v0.65.0: the study takes Force × days per Force: the spell is known when it has passed.
    if (this.waitsFor('magic')) {
      await this.update({ 'system.karma.good': good - cost, 'system.ledger': this.#ledgerWith({ kind: 'karma', amount: -cost, reason: tx('SR2E.Text.Actor.studying', { name }) }) });
      await this.startProject({ kind: 'learn', area: 'magic', subject: name, label: tx('SR2E.Card.Actor.learningAtForce', { name, force }), hours: Number(foreignAdjust(learningPlan(force, 1), foreign).days ?? force) * 24, paid: { karma: cost }, effect: { creates: [{ name, type: 'spell', system: { ...system } }] } });
      return true;
    }
    await this.createEmbeddedDocuments('Item', [{ name, type: 'spell', system: { ...system } }]);
    await this.update({ 'system.karma.good': good - cost, 'system.ledger': this.#ledgerWith({ kind: 'karma', amount: -cost, reason: tx('SR2E.Text.Actor.learned', { name }) }) });
    await ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor: this }), content: `<p><strong>${escText(this.name)}</strong> ${tx('SR2E.Card.Actor.learnsForceFromForGoodKarma', { name: escText(name), force, from: escText(from), cost })}</p>` });
    return true;
  }

  /** Learn a spell from a group's grimoire (no design test). */
  async learnFromGrimoire(groupId: string, name: string): Promise<boolean> {
    if (!RULES.OCCULT.groups.grimoire) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.groupGrimoiresAreSwitchedOffHouse')); return false; }
    const g = this.myGroups().find((x) => x.id === groupId);
    if (!g) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.isNotInThatGroup', { name: escHtml(this.name) })); return false; }
    if (inBreach(g, this.selfUuids())) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.hasBrokenSStricturesAndCan', { name: escHtml(this.name), name2: escHtml(g.name) })); return false; }
    const entry = g.grimoire.find((s) => s.name === name);
    if (!entry) return false;
    return this.learnFormula(entry.name, entry.system, `${g.name}'s grimoire`, { origin: 'grimoire' });
  }

  /**
   * v0.91.8: learn the spell of one of this character's spell formulas (a gear item) at `force` (up to the formula's).
   * A spell already known at a lower Force is raised; one not known yet is learned (the learning test, Good Karma).
   */
  async learnFromFormula(itemId: string, force?: number): Promise<boolean> {
    const it: any = this.items.get?.(String(itemId ?? ''));
    if (!it || it.type !== 'gear' || !isFormula(it.system)) return false;
    const f = it.system.formula;
    const top = formulaForce(f.force);
    const want = Math.min(top, formulaForce(force ?? top));
    const known: any = [...this.items].find((i: any) => i.type === 'spell' && i.name === f.spell);
    if (known) {
      if (Number(known.system?.learnedForce ?? 0) >= want) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.isAlreadyForce', { spellName: escHtml(known.name), spellLearnedForce: escHtml(known.system.learnedForce) })); return false; }
      return this.raiseSpellForce(known, want, { formulaId: it.id });
    }
    return this.learnFormula(String(f.spell), { ...(f.data ?? {}), learnedForce: want }, String(it.name), { origin: 'formula', formulaId: it.id });
  }

  /**
   * v0.91.8 (RULES.FORMULA_V918.teacher): a teacher who knows `spell` at `force` or more makes their Instruction test
   * (RULES.CHARACTERS_V58.training's skill and TN, rolled with their dice); its card offers this character the learning
   * test with the successes, up to the teacher's Sorcery, as extra dice. A teacher no player owns charges a fee.
   */
  async learnFromTeacher(teacherUuid: string, spell: string, force: number, o: { modifiers?: TargetNumberModifier[] } = {}): Promise<SuccessTestResult | null> {
    if (!teachersOn()) { ui.notifications?.warn?.(tx('SR2E.Notify.Formula.teachersOff')); return null; }
    if (!this.isOwner) { ui.notifications?.warn?.(tx('SR2E.Notify.Shop.onlyTheOwner', { name: escHtml(this.name) })); return null; }
    const inst: any = await fromUuid(String(teacherUuid ?? ''));
    if (!(inst instanceof SR2Actor) || inst.uuid === this.uuid) return null;
    const f = formulaForce(force);
    const theirs = [...inst.items].filter((i: any) => i.type === 'spell').map((i: any) => ({ name: String(i.name), system: i.system }));
    if (!canTeach(theirs, String(spell ?? ''), f)) { ui.notifications?.warn?.(tx('SR2E.Notify.Formula.teacherDoesNotKnow', { teacher: escHtml(inst.name), spell: escHtml(spell), force: f })); return null; }
    const known: any = [...this.items].find((i: any) => i.type === 'spell' && i.name === spell);
    if (known && Number(known.system?.learnedForce ?? 0) >= f) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.isAlreadyForce', { spellName: escHtml(spell), spellLearnedForce: escHtml(known.system.learnedForce) })); return null; }
    const c = RULES.CHARACTERS_V58.training;
    const isd = inst.#skillDice(inst.findSkill(c.instructionSkill), false, null, 'charisma', { skillName: c.instructionSkill });
    const sorcery = Number(inst.findSkill(RULES.MAGIC_V56.learning.skill)?.system?.rating ?? 0);
    const foreign = isForeign(learnerTradition(inst.sys.tradition), learnerTradition(this.sys.tradition));
    const fee = teacherFee(f, Boolean(inst.hasPlayerOwner));
    const taught: any = [...inst.items].find((i: any) => i.type === 'spell' && i.name === spell);
    // Review (B3): the teacher's own choices (exclusive, fetish, sustaining) aren't taught.
    const system = { ...formulaSpellData(taught?.system?.toObject?.() ?? taught?.system ?? {}), learnedForce: f };
    return inst.#runTest(tx('SR2E.Card.Formula.teaches', { teacher: inst.name, name: this.name, spell, force: f, skill: c.instructionSkill, suffix: isd.suffix }), isd.dice, {
      targetNumber: c.instructionTn, modifiers: [...(o.modifiers ?? []), ...isd.modifiers],
    }, { kind: 'plain', teach: { studentUuid: String(this.uuid), teacherUuid: String(inst.uuid), spell: String(spell), force: f, ...(known ? { spellId: known.id } : {}), system, teacherName: String(inst.name), sorcery, foreign, fee } });
  }

  /**
   * v0.91.8: the learning test with a teacher's help, from their card (`messageId`). The help is read again from the card
   * (#teachHelp). Returns 'refused' when nothing was started (the card stays usable), 'used' once the learning test was
   * rolled or the request filed (the card is then spent, whatever the result).
   */
  async learnTaught(messageId: string): Promise<'used' | 'refused'> {
    const m: any = (game as any).messages?.get?.(String(messageId ?? ''));
    const t: any = (m?.getFlag?.(SYSTEM_ID, 'test') ?? m?.flags?.[SYSTEM_ID]?.test)?.teach;
    if (!t) return 'refused';
    const force = formulaForce(t.force);
    const known: any = [...this.items].find((i: any) => i.type === 'spell' && i.name === t.spell);
    if (known && Number(known.system?.learnedForce ?? 0) >= force) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.isAlreadyForce', { spellName: escHtml(known.name), spellLearnedForce: escHtml(known.system.learnedForce) })); return 'refused'; }
    if (!(await this.#teachHelp(messageId, String(t.spell), force))) return 'refused';
    if (!approvalNeeded(this) && !this.#canStudy(String(t.spell), force)) return 'refused';
    if (known) await this.raiseSpellForce(known, force, { teachMessage: String(messageId) });
    else await this.learnFormula(String(t.spell), { ...(t.system ?? {}), learnedForce: force }, String(t.teacherName ?? ''), { teachMessage: String(messageId) });
    return 'used';
  }

  /** Spell design: the design test; a success gives a formula card to learn it from. */
  async designSpell(d: SpellDesign & { name: string; force: number; element?: string; targetNumber?: number; resist?: string; heals?: boolean; modifiers?: TargetNumberModifier[] }): Promise<SuccessTestResult | null> {
    const sorcery = this.findSkill(RULES.OCCULT.design.skill);
    if (!sorcery || !((sorcery.system?.rating ?? 0) > 0)) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.needsToDesignSpells', { name: escHtml(this.name), designSkill: RULES.OCCULT.design.skill })); return null; }
    const force = Math.max(1, Math.floor(d.force || 1));
    const drain = designDrain({ ...d, resisted: Boolean(d.resist && d.resist !== 'none') });
    const kind = isShamanic(this.tradition) ? 'lodge' : 'library';
    const site = bestSite(this.magicSites(), kind as SiteKind, kind === 'library' ? 'sorcery' : String(this.sys.totem?.name ?? ''));
    const t = designTest(force, site?.rating ?? 0);
    const system = {
      category: d.category, spellType: d.spellType, learnedForce: force, damageLevel: d.damageLevel ?? 'M', damageType: d.damageType ?? 'physical',
      targetNumber: Math.max(2, Math.floor(d.targetNumber ?? 4)), duration: d.duration ?? 'instant', area: Boolean(d.area),
      resist: d.category === 'combat' ? 'none' : (d.resist || 'none'), heals: Boolean(d.heals), elemental: Boolean(d.elemental), element: d.element ?? '',
      drainModifier: drain.drainModifier, drainLevel: drain.drainLevel,
      // v0.48.0: exclusive and fetish spells carry their flags (their drain changes apply when cast).
      exclusive: Boolean(d.exclusive), fetish: Boolean(d.fetish),
    };
    const code = `(F/2)${drain.drainModifier ? `${drain.drainModifier > 0 ? '+' : ''}${drain.drainModifier}` : ''} ${drain.drainLevel}`;
    return this.#runTest(tx('SR2E.Card.Actor.designForceDrain', { name: d.name, force, code, part: site ? ` [${site.name} +${t.siteDice}]` : '' }), sorcery.system.rating + t.siteDice,
      { targetNumber: t.tn, modifiers: d.modifiers ?? [], magical: true },
      { kind: 'design', design: { name: d.name, system, notes: drain.notes } });
  }

  async #resolveDesign(snap: TestSnapshot): Promise<Resolved> {
    const d = snap.design!;
    const force = Number(d.system['learnedForce'] ?? 1);
    const days = designDays(force, snap.successes);
    if (days === null && d.projectId) return { html: `<p><strong>${tx('SR2E.Card.Actor.theDesignFails')}</strong> ${tx('SR2E.Card.Actor.theFormulaDoesnTHoldTogether', { value: await this.dropProjectOnFailure(d.projectId) })}</p>`, flags: {}, snap: { ...snap, design: { ...d, projectId: undefined } } };
    if (days === null) return { html: `<p><strong>${tx('SR2E.Card.Actor.theDesignFails')}</strong> ${tx('SR2E.Card.Actor.theFormulaDoesnTHoldTogether2')}</p>`, flags: {}, snap };
    // v0.65.0: the design takes its days; the formula (and its Learn button) comes when they have passed.
    if (this.waitsFor('magic')) {
      if (d.projectId) {
        const old = await this.retimeProject(d.projectId, days * 24);
        return { html: old ? `<p><strong>${tx('SR2E.Card.Actor.designs', { name: escText(this.name), name2: escText(d.name) })}</strong>${tx('SR2E.Card.Actor.ofWorkUpkeepTabUnderWay', { plural: escText(plural(days, 'day')) })}</p>` : `<p><em>${tx('SR2E.Card.Actor.theDesignIsFinishedOrWas')}</em></p>`, flags: {}, snap };
      }
      const pr = await this.startProject({ kind: 'design', area: 'magic', label: tx('SR2E.Text.Actor.designing', { name: d.name }), hours: days * 24, effect: { call: { method: 'finishDesign', args: [d.name, d.system, d.notes] } } });
      return { html: `<p><strong>${tx('SR2E.Card.Actor.designs', { name: escText(this.name), name2: escText(d.name) })}</strong>${tx('SR2E.Card.Actor.ofWorkTheFormulaIsReady', { plural: escText(plural(days, 'day')) })}</p>`, flags: {}, snap: { ...snap, design: { ...d, projectId: pr.id } } };
    }
    return this.#designCard(d, days, snap);
  }

  /** v0.65.0: a design's time has passed: the formula's card, with Learn it and the grimoire buttons. */
  async finishDesign(name: string, system: Record<string, unknown>, notes: string[] = []): Promise<boolean> {
    const r = this.#designCard({ name, system, notes } as any, 0, null);
    await ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor: this }), content: r.html, flags: { [SYSTEM_ID]: r.flags } });
    return true;
  }

  #designCard(d: { name: string; system: Record<string, unknown>; notes: string[] }, days: number, snap: TestSnapshot | null): Resolved {
    const force = Number(d.system['learnedForce'] ?? 1);
    const groups = this.myGroups().filter((g) => !inBreach(g, this.selfUuids()));
    const grim = RULES.OCCULT.groups.grimoire ? groups.map((g) => `<button type="button" data-sr2e-action="formulaGrimoire" data-group="${escText(g.id)}">${tx('SR2E.Card.Actor.addToSGrimoire', { name: escText(g.name) })}</button>`).join(' ') : '';
    const dm = Number(d.system['drainModifier']) || 0;
    return {
      html: `<p><strong>${tx('SR2E.Card.Actor.isDesigned', { name: escText(d.name) })}</strong>${(days ? tCount(days, 'SR2E.Card.Actor.drainF2WithInDays', { part2: dm ? `${dm > 0 ? '+' : ''}${dm}` : '', system: escText(d.system['drainLevel']), part3: d.notes.length ? ` (${escText(d.notes.join(', '))})` : '' }) : tx('SR2E.Card.Actor.drainF2Plain', { part2: dm ? `${dm > 0 ? '+' : ''}${dm}` : '', system: escText(d.system['drainLevel']), part3: d.notes.length ? ` (${escText(d.notes.join(', '))})` : '' }))}</p>
        <p><button type="button" data-sr2e-action="learnFormula">${tx('SR2E.Card.Actor.learnItGoodKarma', { spellKarmaCost: spellKarmaCost(force) })}</button> ${grim}</p>`,
      flags: { formula: { actorUuid: this.uuid, name: d.name, system: d.system } }, snap: snap as any,
    };
  }

  /** Noticing a ritual being prepared against this actor. */
  async noticeRitual(tn: number, n: { spellName: string; force: number; casterName: string }): Promise<SuccessTestResult | null> {
    const g = RULES.OCCULT.ritualNotice.gradeDice ? this.initiate.grade : 0;
    const int = Number(this.sys.attributes?.intelligence?.total ?? 0);
    return this.#runTest(tx('SR2E.Card.Actor.noticeARitualIntelligenceVs', { int, part: g ? tx('SR2E.Card.Actor.grade2', { g }) : '', tn }), int + g, { targetNumber: tn, background: true },
      { kind: 'notice', notice: n, privateTo: this.#ownersAndGms() });
  }

  /** Cards offering each target of a ritual a chance to notice it. */
  static async ritualNoticeCards(targetUuids: string[], n: { spellName: string; force: number; casterName: string }): Promise<void> {
    for (const u of targetUuids) {
      const t: any = await fromUuid(u);
      if (!t?.system?.attributes) continue;
      const awakened = t.type === 'spirit' || Number(t.system.derived?.magic ?? 0) > 0;
      const tn = ritualNoticeTn({ awakened, astral: Boolean(t.isAstral?.()) });
      if (tn === null) continue;
      await ChatMessage.create({
        speaker: { alias: tx('SR2E.Card.Actor.ritual') },
        content: `<p>${tx('SR2E.Card.Actor.maySenseSomethingReachingForThem', { name: escText(t.name) })}</p><p><button type="button" data-sr2e-action="noticeRitual">${tx('SR2E.Card.Actor.noticeItIntelligenceVs', { tn })}</button></p>`,
        whisper: t.#ownersAndGms(),
        flags: { [SYSTEM_ID]: { ritualNotice: { targetUuid: t.uuid, tn, ...n } } },
      });
    }
  }

  /** Build or raise a library, circle or lodge (a gear item with a site) for nuyen. */
  async raiseSite(itemId: string, newRating: number): Promise<boolean> {
    const it: any = [...this.items].find((i: any) => i.id === itemId);
    const kind = String(it?.system?.site?.kind ?? '');
    if (!it || !kind) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.thatIsNotALibraryCircle')); return false; }
    const from = Number(it.system.site.rating ?? 0);
    const to = Math.max(0, Math.floor(newRating));
    if (to <= from) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.isAlreadyRating', { name: escHtml(it.name), from })); return false; }
    const c = siteRaiseCost(kind, from, to);
    // v0.65.0: one raise at a time per site.
    if (this.projects().some((p) => p.kind === 'site' && p.effect.updates?.some((u) => u.itemId === itemId))) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.isAlreadyBeingWorkedOnUpkeep', { name: escHtml(it.name) })); return false; }
    if (c.nuyen > 0 && !(await this.adjustNuyen(-c.nuyen, tx('SR2E.Text.Actor.ratingFromTo', { name: it.name, from, to })))) return false;
    // v0.65.0: the work takes its days; the rating rises when they have passed.
    if (this.waitsFor('magic') && c.days > 0) {
      await this.startProject({ kind: 'site', area: 'magic', label: tx('SR2E.Text.Actor.ratingFromTo', { name: it.name, from, to }), hours: c.days * 24, paid: { nuyen: c.nuyen }, effect: { updates: [{ itemId, changes: [['system.site.rating', to]] }] } });
      return true;
    }
    await it.update({ 'system.site.rating': to });
    await ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor: this }), content: `<p><strong>${escText(this.name)}</strong> ${tx('SR2E.Card.Actor.raisesFromTo', { name: escText(it.name), kind: escText(kind), from })} <strong>${to}</strong> ${tCount(c.days, 'SR2E.Card.Actor.forTheWorkTakesDays', { nuyen: c.nuyen.toLocaleString() })}</p>` });
    return true;
  }

  /** Ghouls and vampires: days since the last meal and hunger, or null for anyone else. */
  hungerInfo(): { days: number; hungry: boolean; tn: number } | null {
    if (!this.hasCritterPower('essenceLoss')) return null;
    const last = Number(this.getFlag?.(SYSTEM_ID, 'lastFed') ?? NaN);
    return hunger(last, sysNow());
  }

  /** A ghoul or vampire feeds: the Essence loss clock starts again and hunger ends. */
  async feed(opts: { quiet?: boolean } = {}): Promise<boolean> {
    if (!this.hasCritterPower('essenceLoss')) { if (!opts.quiet) ui.notifications?.warn?.(tx('SR2E.Notify.Actor.hasNoEssenceLossToFeed', { name: escHtml(this.name) })); return false; }
    const now = sysNow();
    await this.setFlag(SYSTEM_ID, 'lastFed', now);
    if (RULES.CRITTERS.diet.feedingResets) await this.setFlag(SYSTEM_ID, 'essenceLossAt', now);
    if (!opts.quiet) await ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor: this }), content: `<p><strong>${tx('SR2E.Card.Actor.feeds', { name: escText(this.name) })}</strong> ${tx('SR2E.Card.Actor.theEssenceLossClockStartsAgain')}</p>` });
    return true;
  }

  /** Put (or replace) a sustained power's effect on a target, or take it off (null); non-owners post a GM card. */
  static async setPowerEffect(targetUuid: string, effect: FxEntry | null, removeId = ''): Promise<boolean> {
    // v0.56.0: one change at a time per target (each reads and writes the whole list).
    const prev = SR2Actor.#fxQueue.get(targetUuid) ?? Promise.resolve(true);
    const next = prev.catch(() => true).then(() => SR2Actor.#setPowerEffectNow(targetUuid, effect, removeId));
    SR2Actor.#fxQueue.set(targetUuid, next);
    try { return await next; } finally { if (SR2Actor.#fxQueue.get(targetUuid) === next) SR2Actor.#fxQueue.delete(targetUuid); }
  }

  static #fxQueue = new Map<string, Promise<boolean>>();

  /**
   * v0.56.0: a change to an actor this user can't make (a patient's boxes, a spirit changing hands):
   * a whispered GM card with an Apply button (chat action applyActorUpdate, once).
   */
  static async gmActorCard(uuid: string, change: Omit<ActorChange, 'uuid'>, text: string): Promise<void> {
    await ChatMessage.create({
      speaker: { alias: tx('SR2E.Card.Actor.sr2e') },
      content: `<p><em>${tx('SR2E.Card.Actor.gmOnly')}</em> · ${text}.</p><p><button type="button" data-sr2e-action="applyActorUpdate">${tx('SR2E.Card.Actor.applyGm')}</button></p>`,
      whisper: [...((game as any).users ?? [])].filter((u: any) => u.isGM).map((u: any) => u.id),
      flags: { [SYSTEM_ID]: { actorUpdate: { uuid, ...change } } },
    });
  }

  /**
   * v0.56.0: the GM applies a gmActorCard change.
   * v0.81.0 (SEC1-1, SEC2-8, D3-1): the card's flags are untrusted. There is no free-form `update` any more: only the
   * typed kinds of `ActorChange`, each bounded and re-derived here, and only on an Actor. An `update` key is refused.
   */
  static async applyActorUpdate(c: ActorChange & { update?: unknown }, o: { author?: any } = {}): Promise<boolean> {
    if (!c || typeof c !== 'object' || c.update !== undefined) return false;
    const a: any = await fromUuid(String(c.uuid ?? ''));
    // An Actor only (never a User, Macro, Scene or Setting a uuid can also name).
    if (!isActorDoc(a)) return false;
    // From a card: its (server-set) author must be a GM or own the actor the change comes from.
    if (o.author !== undefined && !realGm(o.author)) {
      const by: any = c.by ? await fromUuid(String(c.by)) : null;
      if (!by || !userOwns(o.author, by)) return false;
    }
    // v0.81.0 (D2-3): lowering a spirit's Force or a barrier's rating: only down, only when it still has the rolled value.
    // R2-DOC 6: from a player's card, only what one of that player's banishing or breaching test cards works out.
    if (c.lower) {
      const key = c.lower.key === 'rating' ? 'rating' : 'force';
      if ((key === 'force' && a.type !== 'spirit') || (key === 'rating' && a.type !== 'barrier')) return false;
      const from = safeInt(c.lower.from, 0, 1000, -1);
      const to = safeInt(c.lower.to, 0, 1000, -1);
      if (from < 0 || to < 0 || to >= from || Number(a.system?.[key]) !== from) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.hasChangedSinceThisWasRolled', { name: escHtml(a.name) })); return false; }
      if (o.author !== undefined && !realGm(o.author) && !SR2Actor.#testBacks(o.author, a.uuid, { lower: { key, from, to } })) {
        ui.notifications?.warn?.(tx('SR2E.Notify.Actor.noTestCardOfSWorks', { authorName: escHtml(o.author?.name ?? tx('SR2E.Notify.Actor.thatPlayer')), name: escHtml(a.name), key, from, to }));
        return false;
      }
      await a.update({ [`system.${key}`]: to });
      return true;
    }
    // v0.81.0 (D2-3): a dispel on a spell this actor sustains: only fewer successes, only when it still has the rolled ones.
    if (c.dispel) {
      const list: any[] = [...(a.sustained?.() ?? [])];
      const from = safeInt(c.dispel.from, 0, 1000, -1);
      const to = safeInt(c.dispel.to, 0, 1000, -1);
      const i = list.findIndex((e: any) => e.spellName === c.dispel!.spellName && e.force === c.dispel!.force && (e.successes ?? 1) === from);
      if (i < 0 || to < 0 || to >= from) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.onHasChangedSinceThisWas', { dispelSpellName: escHtml(c.dispel.spellName), name: escHtml(a.name) })); return false; }
      if (o.author !== undefined && !realGm(o.author) && !SR2Actor.#testBacks(o.author, a.uuid, { dispel: { spellName: String(c.dispel.spellName), force: Number(c.dispel.force), from, to } })) {
        ui.notifications?.warn?.(tx('SR2E.Notify.Actor.noDispellingTestCardOfS', { authorName: escHtml(o.author?.name ?? tx('SR2E.Notify.Actor.thatPlayer')), dispelSpellName: escHtml(c.dispel.spellName), name: escHtml(a.name), from, to }));
        return false;
      }
      const entry = list[i];
      if (to <= 0) list.splice(i, 1); else list[i] = { ...entry, successes: to };
      await a.update({ 'system.sustaining': list });
      if (to > 0 && RULES.FIXES_V71.dispelShrinks && entry?.effectId) await SR2Actor.#shrinkSpellEffect(entry, from - to, a);
      return true;
    }
    // v0.72.0 (O17): a dropped barrier spell's barrier (only barriers raised by a spell).
    if (c.remove) {
      const bs = a.type === 'barrier' ? a.getFlag?.(SYSTEM_ID, 'barrierSpell') : null;
      if (!bs) return true;
      // Review fix: a re-roll may have brought the spell back since this card was posted: then the barrier stays.
      const caster: any = bs.casterUuid ? fromUuidSync(bs.casterUuid) : null;
      if ((caster?.system?.sustaining ?? []).some((e: any) => e.effectId === bs.effectId)) { ui.notifications?.info?.(tx('SR2E.Notify.Actor.theSpellIsSustainedAgainThe', { name: escHtml(a.name) })); return true; }
      await SR2Actor.removeBarrier(a);
      return true;
    }
    // v0.81.0: a bound spirit whose master died: worked out here from the spirit's kind, and only if the master is dead.
    if (c.masterDied) {
      if (a.type !== 'spirit') return false;
      const master: any = a.system?.summonerUuid ? await fromUuid(String(a.system.summonerUuid)) : null;
      if (master?.system?.derived?.status !== 'dead' || (c.by && c.by !== master.uuid)) return false;
      const r = boundSpiritOnMasterDeath(String(a.system?.spiritKind ?? ''), RULES.MAGIC_V61.masterDies);
      if (r.action !== 'none') await a.update(r.update);
      return true;
    }
    // v0.81.0: a spirit changing hands: the summoner and services, with the owners worked out here (handSpirit).
    if (c.handSpirit) {
      if (a.type !== 'spirit') return false;
      const to: any = c.handSpirit.toUuid ? await fromUuid(String(c.handSpirit.toUuid)) : null;
      const old = String(c.handSpirit.oldSummonerUuid ?? '');
      if (c.handSpirit.toUuid && !(to instanceof SR2Actor)) return false;
      // Only between the spirit's summoner now and the one named: never a third party's spirit to a stranger.
      const now = String(a.system?.summonerUuid ?? '');
      if (now && now !== old && now !== String(to?.uuid ?? '')) return false;
      if (c.by && c.by !== old && c.by !== String(to?.uuid ?? '')) return false;
      await a.update(SR2Actor.#handSpiritUpdate(a, to, safeInt(c.handSpirit.services, 0, 99, 0), old));
      return true;
    }
    // v0.73.0 review fix: a nuyen change is relative (read when the GM applies it) and goes in the ledger.
    const amount = c.nuyen ? safeInt(c.nuyen.amount, -1_000_000, 1_000_000, 0) : 0;
    if (amount) await a.adjustNuyen(amount, String(c.nuyen?.label ?? '').slice(0, 200));
    if (c.monitor && a.system?.monitor) {
      const t = c.monitor.track === 'stun' ? 'stun' : 'physical';
      // R2-SEC 9: no card of the system's heals through here (healing has its own stored-test path, applyHeal), so a
      // player's card may only put boxes on (a dropped spell's healing coming back), never take them off.
      const boxes = safeInt(c.monitor.boxes, o.author !== undefined && !realGm(o.author) ? 0 : -RULES.MONITOR_BOXES, RULES.MONITOR_BOXES, 0);
      if (boxes) await a.update({ [`system.monitor.${t}`]: Math.max(0, Math.min(RULES.MONITOR_BOXES, Number(a.system.monitor[t] ?? 0) + boxes)) });
    }
    return true;
  }

  /**
   * v0.81.0 (R2-DOC 6): whether a test card the same user posted (a banishing, a breach or a dispelling, from its
   * stored snapshot) works out this lowering or dispel: the same target, the value it had then and the value the
   * test leaves.
   * v0.81.1 (D2-6, D3-10, SEC1-16): a consistency check against stale or mistyped cards, not a security check: the
   * same user writes that test card's flags too, so a forger can post both. The GM's confirm is the gate. A test card
   * pruned from the chat log fails it (the GM then applies by hand).
   */
  static #testBacks(author: any, targetUuid: string, ch: { lower?: { key: 'force' | 'rating'; from: number; to: number }; dispel?: { spellName: string; force: number; from: number; to: number } }): boolean {
    const all: any = (game as any).messages;
    const list: any[] = Array.isArray(all?.contents) ? all.contents : all && typeof all[Symbol.iterator] === 'function' ? [...all] : [];
    return list.some((m: any) => {
      const by = m?.author?.id ?? m?.author ?? m?.user?.id ?? m?.user;
      if (!author?.id || by !== author.id) return false;
      const snap: any = m.getFlag?.(SYSTEM_ID, 'test') ?? m.flags?.[SYSTEM_ID]?.test;
      if (!snap || typeof snap !== 'object') return false;
      const successes = Number(snap.successes ?? 0);
      if (ch.lower?.key === 'force' && snap.kind === 'banish' && snap.banish && !snap.banish.control && snap.banish.spiritUuid === targetUuid) {
        const b = snap.banish;
        return (b.forceAfter ?? b.forceBefore) === ch.lower.from && resolveBanishing({ banisherSuccesses: successes, spiritSuccesses: b.spiritSuccesses, force: b.forceBefore }).force === ch.lower.to;
      }
      if (ch.lower?.key === 'rating' && snap.kind === 'barrier' && snap.barrier?.barrierUuid === targetUuid) {
        const b = snap.barrier;
        return (b.ratingAfter ?? b.ratingBefore) === ch.lower.from && resolveBarrier({ attackerSuccesses: successes, barrierSuccesses: b.barrierSuccesses, rating: b.ratingBefore }).rating === ch.lower.to;
      }
      if (ch.dispel && snap.kind === 'dispel' && snap.dispel?.targetUuid === targetUuid) {
        const d = snap.dispel;
        return d.spellName === ch.dispel.spellName && d.force === ch.dispel.force && (d.successesAfter ?? d.successesBefore) === ch.dispel.from
          && resolveDispel(d.successesBefore, successes).remaining === ch.dispel.to;
      }
      return false;
    });
  }

  /**
   * v0.56.0: a spirit's new master: summoner, services, and its owners (the new master's owners in, the
   * old master's out; the default level kept). A non-GM sends it to the GM.
   */
  static async handSpirit(spirit: any, to: any | null, services: number, oldSummonerUuid: string, text: string): Promise<boolean> {
    // The card comes from the client making the change: the new master's, or (handing back) the old one's.
    if (!isGmNow()) { await SR2Actor.gmActorCard(spirit.uuid, { handSpirit: { toUuid: String(to?.uuid ?? ''), services, oldSummonerUuid }, by: String([to, fromUuidSync(oldSummonerUuid)].find((x: any) => canWriteNow(x))?.uuid ?? to?.uuid ?? oldSummonerUuid) }, text); return false; }
    await spirit.update(SR2Actor.#handSpiritUpdate(spirit, to, services, oldSummonerUuid));
    return true;
  }

  /** The update for handSpirit, worked out from the documents (v0.81.0: the GM's Apply re-derives it, never a card's). */
  static #handSpiritUpdate(spirit: any, to: any | null, services: number, oldSummonerUuid: string): Record<string, unknown> {
    const users: any[] = [...((game as any).users ?? [])];
    const old: any = oldSummonerUuid ? fromUuidSync(oldSummonerUuid) : null;
    const ownership: Record<string, number> = {};
    for (const u of users) {
      if (u.isGM) continue;
      const newLevel = to?.testUserPermission?.(u, 'OWNER') ? 3 : null;
      const oldLevel = old?.testUserPermission?.(u, 'OWNER') ? 3 : null;
      if (newLevel) ownership[u.id] = 3;
      else if (oldLevel && Number(spirit.ownership?.[u.id] ?? 0) >= 3) ownership[u.id] = 0;
    }
    // v0.81.1 (D3-4): handed to nobody (a binding undone: "free again") leaves it with no summoner, not the old one.
    return { 'system.summonerUuid': to ? String(to.uuid) : '', 'system.services': services, ...Object.fromEntries(Object.entries(ownership).map(([k, v]) => [`ownership.${k}`, v])) };
  }

  static async #setPowerEffectNow(targetUuid: string, effect: FxEntry | null, removeId = ''): Promise<boolean> {
    const t: any = await fromUuid(targetUuid);
    if (!t) return false;
    const id = effect?.id ?? removeId;
    const had = [...((t.getFlag?.(SYSTEM_ID, 'powerEffects') as any[] | undefined) ?? [])];
    // v0.56.0: nothing to take off (a failed cast, an effect already gone): no card, no change.
    if (!effect && !had.some((e: any) => e.id === id)) return true;
    const list = had.filter((e: any) => e.id !== id);
    if (effect) list.push(effect);
    if (!canWriteNow(t)) {
      await ChatMessage.create({
        speaker: { alias: effect?.fromName ?? tx('SR2E.Card.Actor.power3') },
        content: `<p><em>${tx('SR2E.Card.Actor.gmOnly')}</em> · ${effect ? tx('SR2E.Card.Actor.on10', { effectName: escText(effect.name), name: escText(t.name), bundle: escText(describeBundle(effect)) }) : tx('SR2E.Card.Actor.anEffectOnEnds', { name: escText(t.name) })}.</p><p><button type="button" data-sr2e-action="applyPowerEffect">${tx('SR2E.Card.Actor.applyGm')}</button></p>`,
        whisper: [...((game as any).users ?? [])].filter((u: any) => u.isGM).map((u: any) => u.id),
        flags: { [SYSTEM_ID]: { powerEffect: { targetUuid, effect, removeId } } },
      });
      return false;
    }
    await t.setFlag(SYSTEM_ID, 'powerEffects', list);
    // v0.78.0 (RULES.BOOK_V78.paralysis 'drain'): Quickness drained to 0 paralyses; it lifts when the drain does.
    if (had.some((e: any) => e.special === 'paralysis' && e.until) || list.some((e: any) => e.special === 'paralysis' && e.until)) {
      const draining = list.some((e: any) => e.special === 'paralysis' && e.until);
      const q = Number(t.system?.attributes?.quickness?.total ?? 1);
      const st = String(RULES.MAGIC_V61.holdPowers.paralysis.status ?? 'paralysis');
      try { await t.toggleStatusEffect?.(st, { active: draining && q <= 0 }); } catch { /* no status */ }
    }
    // v0.61.0: holding powers switch their token status on while any effect needs it, off when none does.
    const wanted = new Set(list.map((e: any) => String(e.status ?? '')).filter(Boolean));
    for (const st of new Set(had.map((e: any) => String(e.status ?? '')).filter(Boolean))) {
      if (!wanted.has(st)) { try { await t.toggleStatusEffect?.(st, { active: false }); } catch { /* no status */ } }
    }
    if (effect?.status) {
      if (Number(effect.holdTurns ?? 0) > 0 && typeof t.setTimedStatus === 'function') await t.setTimedStatus(effect.status, Number(effect.holdTurns) * RULES.TOXINS.secondsPerTurn);
      else { try { await t.toggleStatusEffect?.(effect.status, { active: true }); } catch { /* no status */ } }
      // A new binding: the held one gets a Break free button (resisted or not).
      if (effect.special === 'binding' && !had.some((e: any) => e.id === effect.id)) {
        await ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor: t }),
          content: `<p><strong>${tx('SR2E.Card.Actor.isBound2', { name: escText(t.name) })}</strong> ${tx('SR2E.Card.Actor.by3', { effectName: escText(effect.name) })} <button type="button" data-sr2e-action="breakBinding">${tx('SR2E.Card.Actor.breakFreeVs', { bindingBreakAttribute: escText(cap(String(RULES.MAGIC_V61.holdPowers.binding.breakAttribute))), effectBreakTn: effect.breakTn ?? '?' })}</button></p>`,
          flags: { [SYSTEM_ID]: { breakBinding: { targetUuid: t.uuid, effectId: effect.id } } } });
      }
    }
    return true;
  }

  /** v0.61.0: break free of a binding power: the held one's attribute (Strength) vs its Force. */
  async breakBinding(effectId: string): Promise<boolean> {
    const fx = ((this.getFlag?.(SYSTEM_ID, 'powerEffects') as any[] | undefined) ?? []).find((e: any) => e.id === effectId);
    if (!fx) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.isnTHeldByThatAny', { name: escHtml(this.name) })); return false; }
    // Breaking free takes an action (RULES.ACTIONS.costs.breakFree).
    if (!(await this.useAction('breakFree', tx('SR2E.Card.Actor.breakingFreeOf', { fxName: fx.name })))) return false;
    const h = RULES.MAGIC_V61.holdPowers.binding;
    const attr = String(h.breakAttribute ?? 'strength');
    const t = breakFreeTest({ attribute: Number(this.sys.attributes?.[attr]?.total ?? 0), force: Number(fx.breakTn ?? 4) });
    const rolls: any[] = [];
    const r = await successTest({ dice: t.dice, targetNumber: t.tn, modifiers: this.#testModifiers({ modifiers: [] }), roll: foundryRoller(rolls) });
    const free = r.successes > 0;
    if (free) await SR2Actor.setPowerEffect(this.uuid as string, null, effectId);
    await ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor: this }), rolls,
      content: `<p><strong>${escText(this.name)}</strong> ${tCount(r.successes, 'SR2E.Card.Actor.strainsAgainstVsTnSuccesses', { fxName: escText(fx.name), attr: escText(cap(attr)), dice: t.dice, tn: t.tn, part: free ? `<strong>${tx('SR2E.Card.Actor.breaksFree2')}</strong>` : tx('SR2E.Card.Actor.stillHeld') })}</p>` });
    return free;
  }

  /** Every sustained power effect this actor keeps up, on anyone in the world or on the canvas. */
  static powerEffectsFrom(uuids: string[]): Array<{ targetUuid: string; targetName: string; id: string; name: string; attributes: Record<string, number>; summary: string }> {
    const seen = new Set<string>();
    const actors: any[] = allActors();
    const out: Array<{ targetUuid: string; targetName: string; id: string; name: string; attributes: Record<string, number>; summary: string }> = [];
    for (const a of actors) {
      for (const e of ((a.getFlag?.(SYSTEM_ID, 'powerEffects') as any[] | undefined) ?? [])) {
        // v0.56.0: a spell that has become permanent isn't sustained any more; spells are listed under Sustaining.
        // v0.78.0 review fix: a timed effect (Paralyzing Touch's drain) runs its time, it isn't sustained.
        if (e.permanent || e.until || e.kind === 'spell' || !uuids.includes(e.fromUuid) || seen.has(`${a.uuid}|${e.id}`)) continue;
        seen.add(`${a.uuid}|${e.id}`);
        out.push({ targetUuid: a.uuid, targetName: a.name, id: e.id, name: e.name, attributes: e.attributes ?? {}, summary: describeBundle(e) });
      }
    }
    return out;
  }

  /** Drop every power this actor sustains (it was knocked out, or the player chose to). */
  async dropAllPowerEffects(): Promise<number> {
    const list = SR2Actor.powerEffectsFrom(this.selfUuids());
    for (const e of list) await SR2Actor.setPowerEffect(e.targetUuid, null, e.id);
    return list.length;
  }

  /** The Body Index rejection test (RULES.BIOWARE.rejection); null when within the limit. */
  async rejectionTest(): Promise<SuccessTestResult | null> {
    const bi = this.sys.derived?.bodyIndex ?? { used: 0, max: 0 };
    // v0.72.0 (O11): Sensitive System calls for rejection tests even within the Body Index.
    const tn = sensitiveRejectionTn(rejectionTn(Number(bi.used ?? 0), Number(bi.max ?? 0)), Number(bi.used ?? 0), this.sys.derived?.vitals ?? { sensitive: false });
    if (tn === null) { ui.notifications?.info?.(tx('SR2E.Notify.Actor.sBodyIndexOfIsWithin', { name: escHtml(this.name), biUsed: escHtml(bi.used), biMax: escHtml(bi.max) })); return null; }
    try { await this.setFlag(SYSTEM_ID, 'rejectionAt', nextRejectionAt(sysNow())); } catch { /* not saved */ }
    return this.#runTest(tx('SR2E.Card.Actor.biowareRejectionBodyVsBodyIndex', { tn, biUsed: bi.used, biMax: bi.max }), Number(this.sys.attributes?.body?.total ?? 0),
      { targetNumber: tn, noPenalties: true }, { kind: 'rejection', rejection: {} });
  }

  async #resolveRejection(snap: TestSnapshot): Promise<Resolved> {
    const r = RULES.BIOWARE.rejection;
    if (snap.successes > 0) return { html: `<p><strong>${tx('SR2E.Card.Actor.theBodyHolds')}</strong> ${tx('SR2E.Card.Actor.theBiowareStaysIn', { plural: escText(plural(snap.successes, 'success')) })}</p>`, flags: {}, snap };
    if (snap.rejection?.applied) return { html: `<p><strong>${tx('SR2E.Card.Actor.rejection')}</strong> <em>${tx('SR2E.Card.Actor.alreadyApplied2')}</em></p>`, flags: {}, snap };
    const ware = [...this.items].filter((i: any) => i.type === 'cyberware' && i.system.bioware)
      .map((i: any) => ({ id: i.id, name: i.name, installed: Boolean(i.system.installed), damaged: Boolean(i.system.damaged), cultured: Boolean(i.system.cultured), sort: Number(i.sort ?? 0) }));
    // The implant most recently put in (still healing in) goes first (live run, v0.45.0).
    const latest = [...(this.sys.recovering ?? [])].sort((a: any, b: any) => b.until - a.until).map((r: any) => r.itemId);
    const fresh = ware.filter((w) => latest.includes(w.id)).sort((a, b) => latest.indexOf(a.id) - latest.indexOf(b.id));
    const cand = rejectionCandidate(fresh.filter((w) => rejectionCandidate([w])).slice(0, 1)) ?? rejectionCandidate(ware);
    if (cand && r.rejectItem) { const it: any = this.items.get?.(cand.id); if (it) await it.update({ 'system.damaged': true }); }
    const res = applyDamageToMonitor({ physical: this.sys.monitor.physical, stun: this.sys.monitor.stun }, 'physical', r.level, Number(this.sys.derived?.vitals?.overflowBody ?? this.sys.attributes.body.total));
    await this.update({ 'system.monitor.physical': res.monitor.physical, 'system.monitor.stun': res.monitor.stun });
    return {
      html: `<p><strong>${tx('SR2E.Card.Actor.rejection2')}</strong> ${tx('SR2E.Card.Actor.takesPhysicalUnresisted', { part: cand ? tx('SR2E.Card.Actor.sBodyTurnsOn', { name: escText(this.name), candName: escText(cand.name), part: r.rejectItem ? tx('SR2E.Card.Actor.itStopsWorkingUntilRepaired') : '' }) : tx('SR2E.Card.Actor.sBodyFightsTheImplants', { name: escText(this.name) }), name: escText(this.name), level: r.level, plural: escText(plural(res.boxes, 'box')) })}</p>`,
      flags: {}, snap: { ...snap, rejection: { applied: true } },
    };
  }

  /** Fires burning on a scene (scene flag fires). */
  static sceneFires(scene?: any): SceneFire[] {
    const s = scene ?? game.scenes?.viewed ?? game.scenes?.current;
    return [...(((s?.getFlag?.(SYSTEM_ID, 'fires') as SceneFire[] | undefined)) ?? [])];
  }

  /** Draw (or redraw) a fire's circle on its scene; returns the drawing id. A burnt-out fire shows its smoke (v0.48.0). */
  static async #drawFire(scene: any, fire: SceneFire): Promise<string | undefined> {
    if (!RULES.FIRE.draw) return fire.drawingId;
    const ppm = (canvas as any)?.scene?.id === scene.id ? pxPerMetre() : Number(scene.grid?.size ?? 100) / Math.max(0.01, Number(scene.grid?.distance ?? 1));
    const smoke = Boolean(fire.burntOut);
    const r = Math.max(10, (smoke ? smokeRadius(fire) : fire.radius) * ppm);
    const fk = fuelKind(fire.fuel);
    const data = smoke
      ? { x: fire.x - r, y: fire.y - r, shape: { type: 'e', width: 2 * r, height: 2 * r }, fillType: 1, fillColor: '#777777', fillAlpha: 0.25, strokeColor: '#555555', strokeWidth: 2, strokeAlpha: 0.6, text: tx('SR2E.Text.Actor.smoke', { left: fire.smokeLeft ?? 0 }), fontSize: 24 }
      : { x: fire.x - r, y: fire.y - r, shape: { type: 'e', width: 2 * r, height: 2 * r }, fillType: 1, fillColor: '#ff5a1f', fillAlpha: 0.25, strokeColor: '#ff3300', strokeWidth: 4, strokeAlpha: 0.8, text: fk ? tx('SR2E.Text.Actor.fireFuel', { intensity: fire.intensity, fuel: fire.fuel }) : tx('SR2E.Text.Actor.fire', { intensity: fire.intensity }), fontSize: 24 };
    try {
      const existing = fire.drawingId ? scene.drawings?.get?.(fire.drawingId) : null;
      if (existing) { await existing.update(data); return existing.id; }
      const [d] = await scene.createEmbeddedDocuments('Drawing', [data]);
      return d?.id;
    } catch (err) {
      console.warn('sr2e | Could not draw the fire', err);
      return fire.drawingId;
    }
  }

  /** Drawings marked as fuel on a scene (v0.48.0): kind, rectangle (pixels), and whether it is burning or burnt. */
  static fuelAreas(scene?: any): Array<{ id: string; doc: any; kind: string; label: string; rect: { x: number; y: number; width: number; height: number }; burning: string; burnt: boolean }> {
    const s = scene ?? game.scenes?.viewed ?? game.scenes?.current;
    const out: Array<{ id: string; doc: any; kind: string; label: string; rect: { x: number; y: number; width: number; height: number }; burning: string; burnt: boolean }> = [];
    const coll: any = s?.drawings;
    const drawings: any[] = coll?.contents ?? (coll && typeof coll[Symbol.iterator] === 'function' ? [...coll] : []);
    for (const d of drawings) {
      const kind = String(d.getFlag?.(SYSTEM_ID, 'fuel') ?? d.flags?.sr2e?.fuel ?? '');
      const fk = fuelKind(kind);
      if (!fk) continue;
      const w = Number(d.shape?.width ?? 0), h = Number(d.shape?.height ?? 0);
      out.push({ id: d.id, doc: d, kind, label: fk.label, rect: { x: Number(d.x ?? 0), y: Number(d.y ?? 0), width: w, height: h },
        burning: String(d.getFlag?.(SYSTEM_ID, 'fuelFire') ?? ''), burnt: Boolean(d.getFlag?.(SYSTEM_ID, 'fuelBurnt')) });
    }
    return out;
  }

  /** GM: mark drawings as fuel of a kind ('' clears it, and resets a burnt one). */
  static async markFuel(drawings: any[], kind: string): Promise<number> {
    if (!isGmNow()) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.onlyTheGmMarksFuel')); return 0; }
    let n = 0;
    for (const d of drawings) {
      if (!d?.update) continue;
      if (kind && fuelKind(kind)) await d.update({ [`flags.${SYSTEM_ID}.fuel`]: kind, [`flags.${SYSTEM_ID}.fuelBurnt`]: false, [`flags.${SYSTEM_ID}.fuelFire`]: '' });
      else await d.update({ [`flags.${SYSTEM_ID}.-=fuel`]: null, [`flags.${SYSTEM_ID}.-=fuelBurnt`]: null, [`flags.${SYSTEM_ID}.-=fuelFire`]: null });
      n++;
    }
    return n;
  }

  /** Start a fire at a point (GM; anyone else posts a card asking the GM). Inside fuel it takes the fuel's kind (v0.48.0). */
  static async startFire(point: { x: number; y: number }, o: { source: string; sceneId?: string; radius?: number }): Promise<SceneFire | null> {
    const scene: any = o.sceneId ? game.scenes?.get?.(o.sceneId) : (game.scenes?.viewed ?? game.scenes?.current);
    if (!scene) return null;
    if (!isGmNow()) {
      await ChatMessage.create({
        speaker: { alias: tx('SR2E.Card.Actor.fire') },
        content: `<p><em>${tx('SR2E.Card.Actor.gmOnly')}</em> ${tx('SR2E.Card.Actor.aFireMayStart', { source: escText(o.source) })}</p><p><button type="button" data-sr2e-action="startFire">${tx('SR2E.Card.Actor.startTheFireGm')}</button></p>`,
        whisper: [...((game as any).users ?? [])].filter((u: any) => u.isGM).map((u: any) => u.id),
        flags: { [SYSTEM_ID]: { startFire: { x: point.x, y: point.y, source: o.source, sceneId: scene.id } } },
      });
      return null;
    }
    const fires = SR2Actor.sceneFires(scene);
    // v0.81.0 (D3-12): a scene nobody is viewing: its own grid (pixels per grid unit / metres per unit), not 100 px/m.
    const ppm = (canvas as any)?.scene?.id === scene.id ? pxPerMetre() : Number(scene.grid?.size ?? 100) / Math.max(0.01, Number(scene.grid?.distance ?? 1));
    const near = fires.find((f) => !f.burntOut && Math.hypot(f.x - point.x, f.y - point.y) / ppm <= f.radius);
    if (near) return near;
    const now = sysNow();
    const area = SR2Actor.fuelAreas(scene).find((a) => !a.burnt && !a.burning && circleTouchesRect(point, 0, a.rect));
    const fire: SceneFire = { ...newFire({ id: SR2Actor.#newId(), x: point.x, y: point.y, source: o.source, now, ...(o.radius ? { radius: o.radius } : {}),
      ...(area ? { fuel: area.kind, maxRadius: fuelSpan(area.rect, ppm), fuelId: area.id } : {}) }), lastRound: (game as any).combat?.started ? Number((game as any).combat.round ?? 0) : -1 } as any;
    fire.drawingId = await SR2Actor.#drawFire(scene, fire);
    await scene.setFlag(SYSTEM_ID, 'fires', [...fires, fire]);
    if (area) await area.doc.update({ [`flags.${SYSTEM_ID}.fuelFire`]: fire.id });
    await ChatMessage.create({ speaker: { alias: tx('SR2E.Card.Actor.fire') }, content: `<p><strong>${tx('SR2E.Card.Actor.aFireStarts')}</strong>: ${escText(o.source)} (${fire.radius} m, ${escText(fire.intensity)}${area ? tx('SR2E.Card.Actor.on11', { areaLabel: escText(area.label.toLowerCase()) }) : ''}).</p>` });
    return fire;
  }

  /** GM: put a fire out (its smoke goes too). */
  static async putOutFire(sceneId: string, id: string): Promise<boolean> {
    if (!isGmNow()) return false;
    const scene: any = game.scenes?.get?.(sceneId);
    if (!scene) return false;
    const fires = SR2Actor.sceneFires(scene);
    const f = fires.find((x) => x.id === id);
    if (!f) return false;
    try { if (f.drawingId && scene.drawings?.get?.(f.drawingId)) await scene.deleteEmbeddedDocuments('Drawing', [f.drawingId]); } catch { /* gone */ }
    if (f.fuelId && !f.burntOut) { try { await scene.drawings?.get?.(f.fuelId)?.update?.({ [`flags.${SYSTEM_ID}.fuelFire`]: '' }); } catch { /* gone */ } }
    await scene.setFlag(SYSTEM_ID, 'fires', fires.filter((x) => x.id !== id));
    return true;
  }

  /** A burnable wall inside a fire loses barrier rating; burnt through, it no longer blocks (v0.48.0). Returns a note. */
  static async #burnWallDoc(doc: any, intensity: string): Promise<string> {
    const burns = Boolean(doc?.getFlag?.(SYSTEM_ID, 'burns') ?? doc?.flags?.sr2e?.burns);
    if (!burns || doc.move === 0) return '';
    const set = doc.getFlag?.(SYSTEM_ID, 'barrierRating') ?? doc.flags?.sr2e?.barrierRating;
    // A rating of 0 (the wall config's blank) counts as unset for burning.
    const rating = Number(set) > 0 ? Number(set) : RULES.FIRE.walls.defaultRating;
    const r = burnWall(rating, intensity);
    if (!r.loss) return '';
    const update: Record<string, unknown> = { [`flags.${SYSTEM_ID}.barrierRating`]: r.left };
    if (doc.getFlag?.(SYSTEM_ID, 'barrierFull') == null) update[`flags.${SYSTEM_ID}.barrierFull`] = rating;
    if (r.burntThrough) {
      update[`flags.${SYSTEM_ID}.breached`] = { move: doc.move, sight: doc.sight, light: doc.light, sound: doc.sound, rating };
      Object.assign(update, { move: 0, sight: 0, light: 0, sound: 0 });
    }
    await doc.update(update);
    return r.burntThrough ? tx('SR2E.Card.Actor.aWallBurnsThrough', { rating }) : tx('SR2E.Card.Actor.aWallBurns', { rating, left: r.left });
  }

  /**
   * Fires spread (GM): one step per new Combat Turn in combat, or per RULES.FIRE.secondsPerTurn of
   * world time outside it. Everyone caught (on the viewed scene, not behind a wall) gets a Resist
   * button; v0.48.0: burnable walls burn, fuel catches, and everyone in the smoke gets a Smoke button.
   */
  static async fireTicks(at: { round: number | null; worldTime: number }, force = 0): Promise<void> {
    if (!game.user?.isGM) return;
    const inCombat = Boolean((game as any).combat?.started);
    const all: any = (game as any).scenes;
    const scenes: any[] = all?.contents ?? (all && typeof all[Symbol.iterator] === 'function' ? [...all] : []);
    for (const scene of scenes) {
      const fires = SR2Actor.sceneFires(scene);
      if (!fires.length) continue;
      const keep: SceneFire[] = [];
      const lit: SceneFire[] = [];
      let changed = false;
      const viewed = (canvas as any)?.scene?.id === scene.id;
      for (const f0 of fires) {
        let f: any = { ...f0 };
        let steps = force;
        if (!force) {
          if (at.round !== null && at.round !== undefined) { if (f.lastRound !== at.round) { steps = 1; f.lastRound = at.round; } }
          else if (!inCombat) { steps = fireTurnsElapsed(f.lastTick, at.worldTime); if (steps) f.lastTick += steps * RULES.FIRE.secondsPerTurn; }
        }
        if (!steps) { keep.push(f); continue; }
        changed = true;
        // Lingering smoke after the fire is out (v0.48.0).
        if (f.burntOut) {
          f.smokeLeft = Number(f.smokeLeft ?? 0) - steps;
          if (f.smokeLeft <= 0) {
            try { if (f.drawingId && scene.drawings?.get?.(f.drawingId)) await scene.deleteEmbeddedDocuments('Drawing', [f.drawingId]); } catch { /* gone */ }
            continue;
          }
          f.drawingId = await SR2Actor.#drawFire(scene, f);
          keep.push(f);
          if (viewed) await SR2Actor.#fireCard(f, [], []);
          continue;
        }
        let out = false;
        for (let i = 0; i < Math.min(steps, 50) && !out; i++) { const r = fireTurn(f); f = { ...f, ...r.fire }; out = r.out; }
        if (out) {
          if (f.fuelId) { try { await scene.drawings?.get?.(f.fuelId)?.update?.({ [`flags.${SYSTEM_ID}.fuelBurnt`]: true, [`flags.${SYSTEM_ID}.fuelFire`]: '' }); } catch { /* gone */ } }
          const linger = RULES.FIRE.smoke.enabled ? Math.max(0, Math.floor(RULES.FIRE.smoke.lingerTurns)) : 0;
          if (linger > 0) {
            f = { ...f, burntOut: true, smokeLeft: linger };
            f.drawingId = await SR2Actor.#drawFire(scene, f);
            keep.push(f);
            await ChatMessage.create({ speaker: { alias: tx('SR2E.Card.Actor.fire') }, content: `<p>${tx('SR2E.Card.Actor.theFireBurnsOutItsSmoke', { source: escText(f.source), plural: escText(plural(linger, 'combat turn')) })}</p>` });
            continue;
          }
          try { if (f.drawingId && scene.drawings?.get?.(f.drawingId)) await scene.deleteEmbeddedDocuments('Drawing', [f.drawingId]); } catch { /* gone */ }
          await ChatMessage.create({ speaker: { alias: tx('SR2E.Card.Actor.fire') }, content: `<p>${tx('SR2E.Card.Actor.theFireBurnsOut', { source: escText(f.source) })}</p>` });
          continue;
        }
        f.drawingId = await SR2Actor.#drawFire(scene, f);
        keep.push(f);
        if (!viewed) continue;
        const notes: string[] = [];
        // Burnable walls inside the fire (v0.48.0).
        for (const w of wallsNear({ x: f.x, y: f.y }, f.radius)) {
          const n = await SR2Actor.#burnWallDoc(w.doc, f.intensity);
          if (n) notes.push(n);
        }
        // Fuel the fire reaches catches (not through a wall) (v0.48.0).
        if (RULES.FIRE.fuel.spreads) {
          const ppm = pxPerMetre();
          for (const a of SR2Actor.fuelAreas(scene)) {
            if (a.burnt || a.burning || a.id === f.fuelId) continue;
            if (!circleTouchesRect(f, f.radius * ppm, a.rect)) continue;
            const inside = circleTouchesRect(f, 0, a.rect);
            if (!inside && pointsBlocked(f, nearestRectPoint(f, a.rect))) continue;
            const c = { x: a.rect.x + a.rect.width / 2, y: a.rect.y + a.rect.height / 2 };
            const nf: any = { ...newFire({ id: SR2Actor.#newId(), x: c.x, y: c.y, source: `${a.label.replace(/ \(.*\)$/, '').toLowerCase()} caught from ${f.source}`, now: at.worldTime, fuel: a.kind, maxRadius: fuelSpan(a.rect, ppm), fuelId: a.id }), lastRound: f.lastRound ?? -1 };
            nf.drawingId = await SR2Actor.#drawFire(scene, nf);
            lit.push(nf);
            await a.doc.update({ [`flags.${SYSTEM_ID}.fuelFire`]: nf.id });
            notes.push(tx('SR2E.Card.Actor.catchesFire2', { name: a.label.replace(/ \(.*\)$/, '').toLowerCase() }));
          }
        }
        const shielded = (t: any) => RULES.FIRE.walls.block && blastBlocked({ x: f.x, y: f.y }, t);
        const caught = tokensNear({ x: f.x, y: f.y }, f.radius).filter((e) => !shielded(e.token)).map((e) => e.token.actor).filter((a: any) => a);
        await SR2Actor.#fireCard(f, caught, notes);
      }
      if (changed || lit.length) await scene.setFlag(SYSTEM_ID, 'fires', [...keep, ...lit]);
    }
  }

  /** The card a fire posts as it spreads: who burns, who breathes its smoke, walls and fuel (v0.48.0). */
  static async #fireCard(f: SceneFire, caught: any[], notes: string[]): Promise<void> {
    const shielded = (t: any) => RULES.FIRE.walls.block && blastBlocked({ x: f.x, y: f.y }, t);
    const inh = smokeInhalation(f.intensity);
    const smoky = inh ? tokensNear({ x: f.x, y: f.y }, smokeRadius(f)).filter((e) => !shielded(e.token)).map((e) => e.token.actor).filter((a: any) => a) : [];
    if (f.burntOut && !smoky.length) return;
    const rows = caught.map((a: any, i: number) => `<li>${escText(a.name)} <button type="button" data-sr2e-action="fireBurn" data-index="${i}">${tx('SR2E.Card.Actor.resist10', { intensity: escText(f.intensity) })}</button></li>`).join('');
    const smokeRows = inh ? smoky.map((a: any, i: number) => `<li>${escText(a.name)} <button type="button" data-sr2e-action="smokeInhale" data-index="${i}">${tx('SR2E.Card.Actor.smoke', { inhPower: inh.power, inhLevel: inh.level })}</button></li>`).join('') : '';
    const head = f.burntOut
      ? `<p><strong>${tx('SR2E.Card.Actor.smoke2')}</strong> ${tx('SR2E.Card.Actor.lingersWhereTheFireWasM', { source: escText(f.source), value: Math.round(smokeRadius(f) * 10) / 10 })}</p>`
      : `<p><strong>${tx('SR2E.Card.Actor.theFireSpreads')}</strong> (${escText(f.source)}): ${Math.round(f.radius * 10) / 10} m, ${escText(f.intensity)}${f.fuel ? tx('SR2E.Card.Actor.onFuel', { fuel: escText(f.fuel) }) : ''}.${notes.length ? ` ${escText(cap(notes.join('; ')))}.` : ''}</p>${rows ? `<ul class="sr2e-blast">${rows}</ul>` : `<p><em>${tx('SR2E.Card.Actor.nobodyIsInIt')}</em></p>`}`;
    await ChatMessage.create({
      speaker: { alias: tx('SR2E.Card.Actor.fire') },
      content: `${head}${smokeRows ? `<p>${tx('SR2E.Card.Actor.inTheSmoke')}</p><ul class="sr2e-blast">${smokeRows}</ul>` : ''}`,
      flags: { [SYSTEM_ID]: {
        fireBurn: { intensity: f.intensity, uuids: caught.map((a: any) => a.uuid) },
        ...(inh && smoky.length ? { smokeInhale: { ...inh, intensity: f.intensity, source: f.source, uuids: smoky.map((a: any) => a.uuid) } } : {}),
      } },
    });
  }

  /** Smoke inhalation (v0.48.0): Body (+ inhalant dice, + a respirator) vs Power, staged down; a gas mask stops it. */
  async resistSmoke(o: { power: number; level: DamageLevel; type: DamageType; source?: string }): Promise<void> {
    const prot = protectionFor(this.protectiveGear(), 'inhalation');
    if (prot.immune) {
      await ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor: this }), content: `<p><strong>${escText(this.name)}</strong> ${tx('SR2E.Card.Actor.breathesThroughTheSmokeDoesNothing', { protLabel: escText(prot.label) })}</p>` });
      return;
    }
    const inhalant = Number(this.sys.derived?.bio?.inhalantDice ?? 0) + Number(this.sys.derived?.toxinDice ?? 0);
    // v0.58.0: an air filtration system helps against smoke too.
    const filt = this.filtrationFor('inhalation');
    const extra = prot.dice + inhalant + filt.dice;
    // v0.78.0 (RULES.BOOK_V78.toxinBioware 'power'): a tracheal filter lowers the smoke's Power instead.
    const power = toxinPower(o.power, this.sys.derived?.bio?.toxinPowerOff, 'inhalation');
    return this.#drainTest({
      label: tx('SR2E.Card.Actor.smokeInhalation', { part: o.source ? ` (${o.source})` : '', power, part2: power < o.power ? tx('SR2E.Card.Actor.trachealFilter2', { value: o.power - power }) : '' }), attribute: 'body', targetNumber: Math.max(RULES.MIN_TARGET_NUMBER, power), level: o.level, type: o.type, poolDice: 0, noun: 'damage',
      physicalNote: tx('SR2E.Card.Actor.physicalNote'), noBackground: true, ...(extra ? { extraDice: extra, extraNote: [prot.dice ? `${prot.label} +${prot.dice}` : '', inhalant ? tx('SR2E.Card.Actor.toxinDicePlus', { inhalant }) : '', filt.dice ? `${filt.label} +${filt.dice}` : ''].filter(Boolean).join(', ') } : {}),
    });
  }

  // ---------------------------------------------------------------- Building security (v0.26.0)

  /** Re-render open sheets of actors linked to each other (each sheet reads the other's data). */
  static #rerender(...actors: any[]): void {
    for (const a of actors) {
      try { if (a?.sheet?.rendered) a.sheet.render(); } catch { /* no sheet */ }
    }
  }

  /** A site's device by id, or null. */
  device(id: string): any | null {
    return [...(this.sys.devices ?? [])].find((d: any) => d.id === id) ?? null;
  }

  /** The site whose network slaves this vehicle (a turret or security drone), or null. */
  static securitySiteFor(vehicle: any): any | null {
    try {
      return allActors().find((a: any) => a.type === 'site' && (a.system.slaved ?? []).includes(vehicle?.uuid)) ?? null;
    } catch { return null; }
  }

  /** The security rigger jumped into this site, or null. */
  securityRigger(): any | null {
    const r: any = this.sys.riggerUuid ? fromUuidSync(this.sys.riggerUuid) : null;
    return r?.system?.rigging?.jumpedIn && r.system.rigging.vehicleUuid === this.uuid ? r : null;
  }

  /** Lock or unlock a device's door wall on its scene (GM). */
  static async #setDoor(d: any, state: 'locked' | 'unlocked'): Promise<boolean> {
    try {
      const scene: any = (game as any).scenes?.get?.(d.sceneId);
      const wall: any = scene?.walls?.get?.(d.wallId);
      if (!wall) return false;
      const ds = (globalThis as any).CONST?.WALL_DOOR_STATES ?? { CLOSED: 0, OPEN: 1, LOCKED: 2 };
      if (state === 'locked' && wall.ds !== ds.LOCKED) await wall.update({ ds: ds.LOCKED });
      if (state === 'unlocked' && wall.ds === ds.LOCKED) await wall.update({ ds: ds.CLOSED });
      return true;
    } catch { return false; }
  }

  /**
   * Apply a change to a site (owner/GM): tally points and steps, the alert (only rises), a device
   * bypassed, the response called at active, doors locked at lockdown, the linked host's alert.
   * Returns an HTML note.
   */
  static async applySiteChange(siteUuid: string, c: SiteChange): Promise<string | null> {
    const site: any = await fromUuid(siteUuid);
    if (!site || site.type !== 'site') return null;
    const sys = site.system;
    const before = { tally: Number(sys.tally ?? 0), alert: String(sys.alert ?? 'none'), round: Number(sys.response?.round ?? -1), time: Number(sys.response?.worldTime ?? -1) };
    const devices = [...(sys.devices ?? [])].map((d: any) => ({ ...d }));
    const notes: string[] = [];
    if (c.deviceId && c.casingOpen !== undefined) {
      const d = devices.find((x) => x.id === c.deviceId);
      if (d) { d.casingOpen = c.casingOpen; notes.push(`${d.name}'s casing ${c.casingOpen ? 'open' : 'closed'}`); }
    }
    if (c.deviceId && c.bypassed !== undefined) {
      const d = devices.find((x) => x.id === c.deviceId);
      if (d) {
        d.bypassed = c.bypassed;
        notes.push(`${d.name} ${c.bypassed ? 'bypassed' : 'restored'}`);
        if (c.bypassed && RULES.SECURITY.bypass.unlocksDoor && d.wallId && (await SR2Actor.#setDoor(d, 'unlocked'))) notes.push(tx('SR2E.Card.Actor.itsDoorIsUnlocked'));
        // Re-armed (v0.40.0): a door the bypass unlocked locks again.
        if (!c.bypassed && RULES.SECURITY.bypass.unlocksDoor && d.wallId && (await SR2Actor.#setDoor(d, 'locked'))) notes.push(tx('SR2E.Card.Actor.itsDoorLocksAgain'));
      }
    }
    const t = siteTally({ tally: before.tally, add: c.add ?? 0, alert: before.alert, steps: sys.steps ?? [], minAlert: c.minAlert || 'none' });
    const update: Record<string, unknown> = { 'system.devices': devices, 'system.tally': t.tally, 'system.alert': t.alert };
    if (alertAtLeast(t.alert, 'active') && before.round < 0 && before.time < 0) {
      const combat: any = (game as any).combat;
      const r = responseDue({ round: combat?.started ? Number(combat.round ?? 0) : null, worldTime: sysNow(), own: sys.response ?? {} });
      update['system.response.round'] = r.round ?? -1;
      // v0.70.0: a world-time deadline too (3 s per Combat Turn in a fight), and the Combat Turn counts only in
      // the combat it was set in, so the response isn't lost when the fight ends or due in the next one.
      update['system.response.worldTime'] = r.round != null
        ? sysNow() + r.turns * RULES.COMBAT_TURN_SECONDS : r.worldTime;
      update[`flags.${SYSTEM_ID}.responseCombat`] = r.round != null ? String(combat?.id ?? '') : '';
      update['system.response.arrived'] = false;
      notes.push(r.round != null ? tx('SR2E.Card.Actor.theResponseArrivesInCombatTurn', { round: r.round }) : tx('SR2E.Card.Actor.theResponseArrivesInMinutes', { minutes: r.minutes }));
    }
    await site.update(update);
    if (t.alert === 'lockdown' && before.alert !== 'lockdown' && RULES.SECURITY.lockdownLocksDoors) {
      let n = 0;
      for (const d of devices) if (!d.bypassed && d.wallId && (await SR2Actor.#setDoor(d, 'locked'))) n++;
      notes.push(tCount(n, 'SR2E.Card.Actor.lockdownDoorsLocked'));
    }
    // v0.61.0: gas devices fill their rooms on lockdown (SECURITY_V61.gas).
    if (t.alert === 'lockdown' && before.alert !== 'lockdown') {
      for (const id of gasDevicesToRelease(devices)) {
        const d = devices.find((x: any) => x.id === id);
        if (d) notes.push(await SR2Actor.#releaseGas(site, d));
      }
    }
    if (sys.hostUuid && t.alert !== before.alert) {
      const host: any = await fromUuid(sys.hostUuid);
      const want = hostAlertFor(t.alert);
      const order = RULES.MATRIX.alerts as readonly string[];
      if (host?.type === 'host' && order.indexOf(want) > order.indexOf(host.system.alert)) {
        await host.update({ 'system.alert': want });
        notes.push(tx('SR2E.Card.Actor.sAlertRisesTo', { name: host.name, want }));
        if (want === 'shutdown') await SR2Actor.startShutdown(host);
      }
    }
    const events = t.triggered.map((s) => `<li>${tx('SR2E.Card.Actor.stepN', { step: s.step })} <strong>${s.event ? escText(s.event) : tx('SR2E.Card.Actor.noEvent')}</strong>${s.alert ? ` (${s.alert})` : ''}</li>`).join('');
    return `<p>${tx('SR2E.Card.Actor.securityTallyArrow', { before: before.tally })} <strong>${t.tally}</strong> ${tx('SR2E.Card.Actor.alertLabel')} <strong>${t.alert}</strong>${notes.length ? ` · ${escText(notes.join('; '))}` : ''}.</p>${events ? `<ul>${events}</ul>` : ''}`;
  }

  /** Apply a site change (or, for a player who does not own the site, post it for the GM), whispered to the GMs. */
  static async changeSite(site: any, c: SiteChange, label: string, sourceUuid = ''): Promise<void> {
    const gms = [...((game as any).users ?? [])].filter((u: any) => u.isGM).map((u: any) => u.id);
    let body: string;
    let flags: Record<string, unknown> = {};
    if (canWriteNow(site)) body = (await SR2Actor.applySiteChange(site.uuid, c)) ?? '';
    else {
      const parts = [c.deviceId && c.bypassed !== undefined ? `${escText(site.device?.(c.deviceId)?.name ?? tx('SR2E.Card.Actor.device'))} ${c.bypassed ? tx('SR2E.Card.Actor.bypassed2') : tx('SR2E.Card.Actor.restored2')}` : '', c.deviceId && c.casingOpen !== undefined ? tx('SR2E.Card.Actor.sCasing', { name: escText(site.device?.(c.deviceId)?.name ?? tx('SR2E.Card.Actor.device')), part: c.casingOpen ? tx('SR2E.Card.Actor.opened') : tx('SR2E.Card.Actor.closed') }) : '', c.add ? tx('SR2E.Card.Actor.toTheTally', { add: c.add }) : '', c.minAlert ? tx('SR2E.Card.Actor.alertAtLeast', { minAlert: c.minAlert }) : ''].filter(Boolean);
      body = `<p>${parts.join(', ')}. <button type="button" data-sr2e-action="applySite">${tx('SR2E.Card.Actor.applyGm')}</button></p>`;
      flags = { [SYSTEM_ID]: { siteChange: { siteUuid: site.uuid, ...c, ...(sourceUuid ? { sourceUuid } : {}) } } };
    }
    await ChatMessage.create({ speaker: { alias: site.name }, content: `<p><em>${tx('SR2E.Card.Actor.gmOnly')}</em> · <strong>${escText(label)}</strong></p>${body}`, whisper: gms, flags, ...(isGmNow() ? {} : { blind: true }) });
  }

  /** v0.46.0: what hides this actor from sensors: worn stealth suits and their own sustained invisibility spells. */
  concealmentOf(): Array<{ kind: string; rating: number; source: string; key?: string; force?: number }> {
    const out: Array<{ kind: string; rating: number; source: string; key?: string; force?: number }> = [];
    for (const i of [...(this.items ?? [])] as any[]) {
      const st = i.type === 'gear' && isCarried(i) ? i.system?.stealth : null;
      if (st?.kind && st.worn && st.rating > 0) out.push({ kind: st.kind, rating: st.rating, source: i.name });
    }
    // v0.49.0: masking spells too (silence, masks), and spells someone else sustains on this actor.
    const masking = ['invisibility', 'improvedInvisibility', 'silence', 'mask', 'physicalMask'];
    const me = new Set<string>(this.selfUuids?.() ?? [this.uuid as string]);
    const onMe = (e: any, caster: any) => {
      const t: string[] = [...(e.targetUuids ?? [])];
      return t.length ? t.some((u) => me.has(u)) : caster === this;
    };
    const seen = new Set<string>([this.uuid as string]);
    const casters: any[] = [this, ...SR2Actor.tickActors().filter((a: any) => {
      if (a === this || seen.has(a.uuid) || !(a.system?.sustaining ?? []).length) return false;
      seen.add(a.uuid);
      return true;
    })];
    for (const caster of casters) {
      for (const e of (caster.system?.sustaining ?? []) as any[]) {
        const kind = concealmentFromName(e.spellName);
        if (!masking.includes(kind) || !onMe(e, caster)) continue;
        out.push({ kind, rating: Math.max(1, e.successes ?? 1), source: caster === this ? e.spellName : `${e.spellName} (${caster.name})`,
          // v0.61.0: which casting it is (an observer who saw through it remembers that), and its Force.
          // No dots in it: it is a flag key (Foundry would split it into nested objects).
          key: `${caster.uuid}|${e.effectId || e.spellName}|${e.force ?? 1}|${e.successes ?? 1}`.replace(/\./g, '~'), force: Math.max(1, Number(e.force ?? 1)) });
      }
    }
    return out;
  }

  /**
   * v0.61.0: this actor's concealment as one observer sees it (MAGIC_V61.invisibility): an invisibility spell the
   * observer has seen through, or that their astral sight sees past, doesn't hide them.
   */
  concealmentFor(observer: any): Array<{ kind: string; rating: number; source: string; key?: string; force?: number }> {
    const list = this.concealmentOf();
    if (!observer || observer === this) return list;
    const astral = typeof observer.isAstral === 'function' ? Boolean(observer.isAstral()) : false;
    // v0.71.0 review (F2): what this client rolled for an observer it doesn't own counts too (kept in memory).
    const seen = { ...((observer.getFlag?.(SYSTEM_ID, 'seenThrough') as Record<string, boolean> | undefined) ?? {}), ...(observer.seenLocal ?? {}) };
    let thermo = false;
    try { thermo = typeof observer.visionNow === 'function' ? Boolean(observer.visionNow()?.thermographic) : false; } catch { thermo = false; }
    return list.map((c) => ({ ...c, rating: effectiveConcealment({ kind: c.kind, rating: c.rating, observerAstral: astral, seenThrough: Boolean(c.key && seen[c.key]), observerThermographic: thermo }) })).filter((c) => c.rating > 0);
  }

  /**
   * v0.61.0: meeting an invisible target, this observer resists each invisibility spell on it once: Intelligence
   * vs its Force; more successes than the caster's see through it (remembered on the observer's flag seenThrough).
   */
  async seeThroughInvisibility(target: any): Promise<void> {
    if (!target?.concealmentOf || !RULES.MAGIC_V61.invisibility.resist || target === this) return;
    const kinds = ['invisibility', 'improvedInvisibility'];
    const seen = { ...((this.getFlag?.(SYSTEM_ID, 'seenThrough') as Record<string, boolean> | undefined) ?? {}), ...this.seenLocal };
    const todo = target.concealmentOf().filter((c: any) => kinds.includes(c.kind) && c.key && !(c.key in seen));
    if (!todo.length || (typeof this.isAstral === 'function' && this.isAstral())) return;
    const gms = [...((game as any).users ?? [])].filter((u: any) => u.isGM).map((u: any) => u.id);
    const attr = String(RULES.MAGIC_V61.invisibility.attribute ?? 'intelligence');
    // v0.78.0 (RULES.BOOK_V78.invisibility 'perception', Core Rules): a Perception Test vs 2 × the caster's successes.
    const book = RULES.BOOK_V78.invisibility.mode === 'perception';
    let thermo = false;
    try { thermo = Boolean(this.visionNow()?.thermographic); } catch { thermo = false; }
    for (const c of todo) {
      // Thermographic sight sees through (mana) Invisibility anyway: nothing to roll.
      if (c.kind === 'invisibility' && thermo && RULES.BOOK_V78.invisibility.thermographicSeesMana) continue;
      const pd = book ? this.perceptionDice() : null;
      const t = pd ? invisibilityPerceptionTest({ dice: pd.dice, casterSuccesses: Number(c.rating ?? 0) }) : invisibilityResistTest({ intelligence: Number(this.sys.attributes?.[attr]?.total ?? 0), force: Number(c.force ?? 1) });
      const rolls: any[] = [];
      const r = await successTest({ dice: t.dice, targetNumber: t.tn, ...(pd?.modifiers?.length ? { modifiers: pd.modifiers } : {}), roll: foundryRoller(rolls) });
      const sees = seesThrough(r.successes, c.rating);
      seen[c.key] = sees;
      await ChatMessage.create({
        speaker: ChatMessage.getSpeaker({ actor: this }), rolls, whisper: [...new Set([...gms, game.user?.id].filter(Boolean))],
        content: pd
          ? `<p><strong>${escText(this.name)}</strong> ${tCount(r.successes, 'SR2E.Card.Actor.looksForThroughPerceptionVsTn', { targetName: escText(target.name), source: escText(c.source), dice: t.dice, targetNumber: r.targetNumber, rating: escText(c.rating), part: sees ? `<strong>${tx('SR2E.Card.Actor.seesThroughIt')}</strong>` : tx('SR2E.Card.Actor.staysUnseen', { targetName: escText(target.name) }) })}</p>`
          : `<p><strong>${escText(this.name)}</strong> ${tCount(r.successes, 'SR2E.Card.Actor.resistsVsTnSuccessesAgainst', { source: escText(c.source), attr: escText(cap(attr)), dice: t.dice, tn: t.tn, rating: escText(c.rating), part: sees ? `<strong>${tx('SR2E.Card.Actor.seesThroughIt')}</strong>` : tx('SR2E.Card.Actor.staysUnseen', { targetName: escText(target.name) }) })}</p>`,
      });
    }
    // v0.71.0 review (F2): an observer this client doesn't own (a guard a player sneaks past) keeps the result in memory here.
    Object.assign(this.seenLocal, seen);
    if (canWriteNow(this)) await this.setFlag(SYSTEM_ID, 'seenThrough', seen);
  }

  /** v0.71.0 review (F2): invisibility resisted on this client for an actor it can't write to. */
  seenLocal: Record<string, boolean> = {};

  /** The strongest concealment against a sense: blind, or the biggest TN modifier. */
  static concealmentAgainst(sense: string, list: ReadonlyArray<{ kind: string; rating: number; source?: string }>, identifies = false): { blind: boolean; modifiers: TargetNumberModifier[]; label: string } {
    let best: { blind: boolean; modifiers: TargetNumberModifier[]; label: string } = { blind: false, modifiers: [], label: '' };
    for (const c of list) {
      // v0.49.0: a physical mask fools a device that identifies people.
      const mask = maskEffect(c.kind, c.rating, identifies);
      const e = mask.length ? { blind: false, modifiers: mask } : concealmentEffect(sense, c.kind, c.rating);
      const label = `${c.source ?? c.kind} ${c.rating}`;
      if (e.blind) return { blind: true, modifiers: [], label };
      const v = e.modifiers.reduce((n, m) => n + m.value, 0);
      if (v > best.modifiers.reduce((n, m) => n + m.value, 0)) best = { blind: false, modifiers: e.modifiers, label };
    }
    return best;
  }

  /**
   * A device tries to spot an intruder: opposed — the device's rating (+ the security rigger's Control
   * Pool) vs the intruder's Stealth, the intruder's Stealth vs the device's rating. Detection raises the
   * tally and the alert. `sight: false` (measured on the canvas) means it cannot see them unless `force`.
   * Whispered to the GM.
   */
  async detect(deviceId: string, intruderUuid: string, opts: {
    poolDice?: number; modifiers?: TargetNumberModifier[]; sight?: boolean | null; force?: boolean; exclude?: string[];
    /** v0.46.0: the intruder's concealment (null/undefined = from their worn suits and sustained spells). */
    concealment?: { kind: string; rating: number } | null;
  } = {}): Promise<{ detected: boolean } | null> {
    if (this.type !== 'site') return null;
    const d = this.device(deviceId);
    if (!d) return null;
    if (!d.active || d.bypassed) {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.is', { name: escHtml(d.name), part: d.bypassed ? tx('SR2E.Notify.Actor.bypassed') : tx('SR2E.Notify.Actor.switchedOff') }));
      return null;
    }
    const intruder: any = await fromUuid(intruderUuid);
    if (!intruder) return null;
    const gms = [...((game as any).users ?? [])].filter((u: any) => u.isGM).map((u: any) => u.id);
    if (opts.sight === false && !opts.force && RULES.SECURITY.detection.needsSight.includes(d.kind)) {
      await ChatMessage.create({ speaker: { alias: this.name }, content: `<p><em>${tx('SR2E.Card.Actor.gmOnly')}</em> ${tx('SR2E.Card.Actor.hasNoLineOfSightTo', { name: escText(d.name), intruderName: escText(intruder.name) })}</p>`, whisper: gms });
      return { detected: false };
    }
    // v0.46.0: concealment against what the device senses with.
    const hidden = SR2Actor.concealmentAgainst(d.sense ?? '', opts.concealment ? [opts.concealment] : (intruder.concealmentOf?.() ?? []), Boolean(d.identifies));
    if (hidden.blind && !opts.force) {
      await ChatMessage.create({ speaker: { alias: this.name }, content: `<p><em>${tx('SR2E.Card.Actor.gmOnly')}</em> ${tx('SR2E.Card.Actor.cannotPickUpNotDetected', { name: escText(d.name), sense: escText(d.sense), intruderName: escText(intruder.name), hiddenLabel: escText(hidden.label) })}</p>`, whisper: gms });
      return { detected: false };
    }
    const det = RULES.SECURITY.detection;
    const skill: any = intruder.findSkill?.(det.skill);
    const stealth = (skill?.system?.rating as number | undefined) ?? 0;
    const tns = detectionTargets({ deviceRating: d.rating, stealthRating: stealth });
    const rigger = this.securityRigger();
    const pool = rigger ? Math.max(0, Math.min(opts.poolDice ?? 0, rigger.system.derived?.controlPoolLeft ?? 0)) : 0;
    const rolls: any[] = [];
    const dev = await successTest({ dice: d.rating, poolDice: pool, targetNumber: tns.deviceTn, modifiers: [...hidden.modifiers, ...this.deviceSight(d, intruder).filter((m) => !modIn(opts.exclude ?? [], m)), ...(opts.modifiers ?? [])], roll: foundryRoller(rolls) });
    if (pool > 0) await (rigger as SR2Actor).#spendPool('control', pool);
    const attr = (intruder.system?.attributes?.[det.attribute]?.total as number | undefined) ?? 0;
    const intr = await successTest({
      dice: stealth > 0 ? stealth : attr, targetNumber: tns.intruderTn,
      // v0.50.0: the intruder's full own penalties, edges and flaws and movement (as when sneaking past people).
      modifiers: det.skill === RULES.PERCEPTION.stealthSkill && intruder.stealthSide ? intruder.stealthSide().modifiers
        : [...(stealth > 0 ? [] : [{ id: 'defaultingToAttribute', label: tx('SR2E.Card.Mod.defaultingToAttribute'), value: RULES.ATTRIBUTE_DEFAULT_TN_MOD }]), ...(intruder.previewModifiers?.() ?? intruder.woundModifiers?.() ?? [])],
      roll: foundryRoller(rolls),
    });
    const out = detectionOutcome(dev.successes, intr.successes);
    await ChatMessage.create({
      speaker: { alias: this.name },
      content: `<p><em>${tx('SR2E.Card.Actor.gmOnly')}</em></p>${describeResult(tx('SR2E.Card.Actor.watchesFor', { name: d.name, kind: d.kind, rating: d.rating, part: pool ? tx('SR2E.Card.Actor.controlPool2', { pool }) : '', intruderName: intruder.name }), dev)}${describeResult(`${intruder.name}: ${stealth > 0 ? `${det.skill} ${stealth}` : tx('SR2E.Card.Actor.no', { detSkill: det.skill, detAttribute: cap(det.attribute) })}`, intr)}
        <p>${out.detected ? `<strong>${tx('SR2E.Card.Actor.isDetected', { intruderName: escText(intruder.name) })}</strong> ${tx('SR2E.Card.Actor.net3', { outNet: out.net })}` : `<strong>${tx('SR2E.Card.Actor.slipsByUnseen', { intruderName: escText(intruder.name) })}</strong>`}</p>`,
      rolls, whisper: gms, blind: true,
    });
    if (out.detected) await SR2Actor.changeSite(this, { add: out.tally, minAlert: out.minAlert }, tx('SR2E.Card.Actor.detects', { name: d.name, intruderName: intruder.name }), this.uuid as string);
    return { detected: out.detected };
  }

  /**
   * v0.50.0: what a camera-like device (visual, low-light, thermal, ultrasound) meets looking at an
   * intruder: light at them, smoke between, the weather, by the device's sense. Other senses: nothing.
   */
  deviceSight(d: any, intruder: any): TargetNumberModifier[] {
    const eyes: Record<string, Vision> = { visual: {}, lowLight: { lowLight: true }, thermal: { thermographic: true }, ultrasound: { ultrasound: true } };
    const vision = eyes[String(d?.sense ?? '')];
    if (!vision) return [];
    try {
      const devTok: any = d.tokenUuid ? (fromUuidSync(d.tokenUuid) as any)?.object ?? null : null;
      const intrTok = SR2Actor.tokenFor(intruder);
      if (!intrTok) return [];
      const out: TargetNumberModifier[] = [];
      const l = lightModifier(targetLight(intrTok)?.light ?? null, vision);
      if (l) out.push(l);
      if (devTok) {
        const sm = smokeBetweenTokens(devTok, intrTok, SR2Actor.sceneFires((canvas as any)?.scene));
        const s = smokeLook(sm.kind, vision, sm.source);
        if (s) out.push(s);
      }
      const w = weatherModifier(regionWeather(SR2Actor.sceneWeather(devTok?.document?.parent ?? null), devTok ? regionsAtToken(devTok) : []), vision);
      if (w) out.push(w);
      return out;
    } catch { return []; }
  }

  /** Bypass a maglock (or other locked device) of a site: Electronics vs its rating. */
  async bypassLock(site: any, deviceId: string, opts: { poolDice?: number; modifiers?: TargetNumberModifier[]; useSpecialization?: boolean; relatedSkillId?: string | null; exclude?: string[] } = {}): Promise<SuccessTestResult | null> {
    if (!this.canAct('bypass a lock')) return null;
    const d = site?.device?.(deviceId);
    if (!d) {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.thatLockNoLongerExists'));
      return null;
    }
    if (d.bypassed) {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.isAlreadyBypassed', { name: escHtml(d.name) }));
      return null;
    }
    // v0.57.0: the lock's kind, its casing first, the bypasser's tools, and the light at the lock.
    const p = this.bypassPreview(site, deviceId, opts);
    if (!p) return null;
    const exclude = new Set(opts.exclude ?? []);
    // v0.78.0 (RULES.BOOK_V78.voiceLocks 'deception'): a voice lock needs a voice-deception device; its rating is the dice.
    if (p.step === 'voice') {
      if (!p.tool) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.onlyOpensToAnApprovedVoice', { name: escHtml(d.name), name2: escHtml(this.name) })); return null; }
      // v0.80.0 (RULES.URR_V80.dsSequencer 'opposed'): a sequencer against a keypad runs the same opposed step.
      const w = dsDeviceStepWords(String(d.lockType ?? ''));
      return this.#runTest(`${w.verb} ${d.name} (${site.name}, ${w.what} ${d.rating}) [${p.tool}]`, p.dice, {
        targetNumber: p.tn, modifiers: [...(opts.modifiers ?? [])], poolDice: 0,
      }, { kind: 'bypass', bypass: { siteUuid: site.uuid as string, deviceId, deviceName: d.name as string, kind: d.kind as string, tamper: Number(d.tamper ?? 0), skillRating: p.skillRating, step: 'voice' as const, deception: p.dice, lockRating: Number(d.rating ?? 0), ...(RULES.URR_V80.dsSequencer === 'opposed' || veh923('sequencer') === 'book' ? { lockType80: String(d.lockType ?? '') } : {}) } });
    }
    // v0.78.0 (RULES.BOOK_V78.tamper 'tn'): the step that carries the anti-tamper alarm says so.
    const tamperNote = d.tamper && (RULES.BOOK_V78.tamper.mode === 'tn' ? p.tamperOnStep : p.step !== 'casing') ? tx('SR2E.Card.Actor.tamperAlarm', { tamper: d.tamper }) : '';
    return this.#runTest(`${p.step === 'casing' ? tx('SR2E.Card.Actor.openTheCasingOf') : tx('SR2E.Card.Actor.bypass')} ${d.name} (${site.name}, ${p.step === 'casing' ? tx('SR2E.Card.Actor.casing', { casing: d.casing }) : tx('SR2E.Card.Actor.rating9', { rating: d.rating })}${d.lockType ? `, ${lockTypeOf(d.lockType).label}` : ''}${tamperNote})${p.suffix}${p.tool ? ` [${p.tool}]` : ''}`, p.dice, {
      targetNumber: p.tn, modifiers: [...(opts.modifiers ?? []), ...p.modifiers.filter((m) => !modIn(exclude, m))], poolDice: opts.poolDice ?? 0,
    }, { kind: 'bypass', bypass: { siteUuid: site.uuid as string, deviceId, deviceName: d.name as string, kind: d.kind as string, tamper: Number(d.tamper ?? 0), skillRating: p.skillRating, ...(p.step === 'casing' ? { step: 'casing' as const } : {}), ...(p.tamperOnStep ? { tamperOnStep: true } : {}) } });
  }

  /**
   * v0.57.0: what a bypass would roll (also the dialog's preview): the casing first when it has one,
   * then the circuit; the lock type's TN, the best of the bypasser's tools, no tools, light at the lock.
   */
  bypassPreview(site: any, deviceId: string, opts: { useSpecialization?: boolean; relatedSkillId?: string | null } = {}): { step: 'casing' | 'circuit' | 'voice'; tn: number; dice: number; modifiers: TargetNumberModifier[]; suffix: string; tool: string; skillRating: number; tamperOnStep: boolean } | null {
    const d = site?.device?.(deviceId);
    if (!d) return null;
    const b = RULES.SECURITY.bypass;
    const casing = Number(d.casing ?? 0) > 0 && !d.casingOpen;
    const skill: any = this.findSkill(casing ? RULES.SECURITY_V57.casingSkill : b.skill) ?? (casing ? this.findSkill(b.skill) : undefined);
    const sd = this.#skillDice(skill, opts.useSpecialization, opts.relatedSkillId, b.attribute as AttributeKey);
    const tools = [...this.items].filter((i: any) => i.type === 'gear' && i.system?.bypassTool?.kind && Number(i.system.bypassTool.rating ?? 0) > 0 && Number(i.system.quantity ?? 1) > 0 && isCarried(i))
      .map((i: any) => ({ kind: String(i.system.bypassTool.kind), rating: Number(i.system.bypassTool.rating), name: String(i.name) }));
    // v0.78.0: an installed voice modulator or synthesizer (cyberware with a rating) fools voice locks too.
    for (const i of [...this.items].filter((x: any) => x.type === 'cyberware' && x.system?.installed && !x.system?.damaged && /voice\s*(?:modulat|synth)/i.test(String(x.name ?? '')) && Number(x.system?.rating ?? 0) > 0)) {
      tools.push({ kind: 'voiceDeception', rating: Number((i as any).system.rating), name: String((i as any).name) });
    }
    let light: LightLevel | null = null;
    try { const t = SR2Actor.tokenFor(this); if (t) light = targetLight(t)?.light ?? null; } catch { /* no canvas */ }
    const plan = bypassPlan({ rating: Number(d.rating ?? 0), lockType: String(d.lockType ?? ''), casing: Number(d.casing ?? 0), casingOpen: Boolean(d.casingOpen), skillDice: sd.dice, tools, light, vision: this.visionNow(), tamper: Number(d.tamper ?? 0) });
    return { step: plan.step, tn: plan.tn, dice: plan.dice, modifiers: plan.step === 'voice' ? [] : [...plan.modifiers, ...sd.modifiers], suffix: plan.step === 'voice' ? '' : sd.suffix, tool: plan.tool ? `${plan.tool.name} ${plan.tool.rating}` : '', skillRating: Number(skill?.system?.rating ?? 0), tamperOnStep: plan.tamperOnStep };
  }

  /** A bypass test's outcome; the site change follows the card (also after a Karma re-roll, once each way). */
  async #resolveBypass(snap: TestSnapshot, fu: FollowUps): Promise<Resolved> {
    const bp = snap.bypass!;
    const o = bypassOutcome(snap.successes, snap.botch, bp.step === 'casing' ? 'casing' : bp.step === 'voice' ? 'voice' : 'circuit');
    const site: any = fromUuidSync(bp.siteUuid);
    const next = { ...bp };
    // v0.78.0 (RULES.BOOK_V78.voiceLocks 'deception'): the lock rolls its rating vs the device's (once; a re-roll keeps it).
    if (bp.step === 'voice') {
      let lockS = bp.lockSuccesses;
      const ww = dsDeviceStepWords(String(bp.lockType80 ?? site?.device?.(bp.deviceId)?.lockType ?? 'voice'));
      if (lockS === undefined) {
        const rolls: any[] = [];
        const r = await successTest({ dice: Math.max(0, Number(bp.lockRating ?? 0)), targetNumber: Math.max(RULES.MIN_TARGET_NUMBER, Number(bp.deception ?? 0)), roll: foundryRoller(rolls) });
        lockS = r.successes;
        next.lockSuccesses = lockS;
        const gms = [...((game as any).users ?? [])].filter((u: any) => u.isGM).map((u: any) => u.id);
        await ChatMessage.create({ speaker: { alias: site?.name ?? tx('SR2E.Card.Actor.security') }, whisper: gms, blind: true, rolls,
          content: `<p><em>${tx('SR2E.Card.Actor.gmOnly')}</em></p>${describeResult(tx('SR2E.Card.Actor.ratingVsTheDeviceS', { bpDeviceName: bp.deviceName, wwAnswers: ww.answers, bpLockRating: bp.lockRating, bpDeception: bp.deception }), r)}` });
      }
      const v = voiceOutcome(snap.successes, lockS);
      if (site && v === 'open' && !bp.opened) {
        fu.siteChange = { site, change: { deviceId: bp.deviceId, bypassed: true }, label: `${this.name} fools ${bp.deviceName}` };
        next.opened = true;
      } else if (site && v === 'hold' && !bp.failApplied && !bp.opened) {
        // Review fix: a rejected voice counts as a failed bypass whatever the device rolled (a disaster still alerts).
        // v0.92.3 (RULES.VEHICLES_V923.sequencer 'book', CSH p. 100): a keypad that beats the sequencer trips a passive alert.
        const seqAlert = ww.noun === 'code' && veh923('sequencer') === 'book' && !o.minAlert ? 'passive' : o.minAlert;
        fu.siteChange = { site, change: { add: Math.max(Number(o.tally ?? 0), Number(RULES.SECURITY.bypass.failTally ?? 0)), ...(seqAlert ? { minAlert: seqAlert } : {}) }, label: `${bp.deviceName} doesn't accept ${this.name}'s ${ww.noun}` };
        next.failApplied = true;
      }
      const secs = ww.noun === 'code' ? dsSequencerSeconds(snap.successes - lockS) : 0;
      const html = v === 'open' ? `<p><strong>${escText(bp.deviceName)} ${escText(ww.accepts)}</strong> ${(secs ? tx('SR2E.Card.Actor.vsTheLockSWithAfterS', { successes: snap.successes, lockS, secs }) : tx('SR2E.Card.Actor.vsTheLockSPlain', { successes: snap.successes, lockS }))}</p>`
        : v === 'tie' ? `<p><strong>${tx('SR2E.Card.Actor.aTie')}</strong> ${tx('SR2E.Card.Actor.eachTheLockAsksAgainTry', { successes: snap.successes })}</p>`
        : `<p><strong>${escText(bp.deviceName)} ${escText(ww.rejects)}</strong> ${tx('SR2E.Card.Actor.vsTheLockS2', { successes: snap.successes, lockS, part: o.minAlert ? ` <strong>${tx('SR2E.Card.Actor.theAlarmGoesOff')}</strong>` : '' })}</p>`;
      return { html, flags: {}, snap: { ...snap, bypass: next } };
    }
    // v0.78.0 (RULES.BOOK_V78.tamper 'tn', Corporate Security Handbook): the step that carries the anti-tamper alarm
    // trips it on 0 successes (once; a successful re-roll still opens the lock, but the alarm has gone off).
    let tamperTrip = '';
    if (bp.tamperOnStep && snap.successes <= 0 && !bp.tampered && site) {
      const t = RULES.SECURITY.tamper;
      next.tampered = true;
      const prior = (fu.siteChange ?? null);
      fu.siteChange = { site, change: { ...(prior?.change ?? {}), add: (prior?.change?.add ?? 0) + t.tally, ...(t.alert ? { minAlert: t.alert } : {}) }, label: tx('SR2E.Card.Actor.sAntiTamperAlarmTripsAs', { deviceName: bp.deviceName, name: this.name }) };
    }
    if (bp.tamperOnStep && (next.tampered || bp.tampered)) tamperTrip = ` <strong>${tx('SR2E.Card.Actor.theAntiTamperAlarmTrips')}</strong>`;
    // v0.57.0: the casing step: open it (no alarm on a plain failure; a disaster still alerts).
    if (bp.step === 'casing') {
      if (site && snap.successes > 0 && !bp.opened) {
        fu.siteChange = { site, change: { deviceId: bp.deviceId, casingOpen: true }, label: `${this.name} opens ${bp.deviceName}'s casing` };
        next.opened = true;
      } else if (site && snap.successes <= 0 && snap.botch && !bp.failApplied && !bp.opened) {
        const prior = (fu.siteChange ?? null);
        fu.siteChange = { site, change: { ...(prior?.change ?? {}), add: (prior?.change?.add ?? 0) + o.tally, ...(o.minAlert ? { minAlert: o.minAlert } : {}) }, label: `${this.name} botches ${bp.deviceName}'s casing` };
        next.failApplied = true;
      }
      // v0.77.0 review fix: the casing step has its own time (SECURITY.bypassTime.baseTurns.casing ÷ successes).
      const ct = snap.successes > 0 ? bypassTime('casing', snap.successes) : null;
      const html = snap.successes > 0 ? `<p><strong>${(ct ? tCount(ct.turns, 'SR2E.Card.Actor.sCasingIsOpenWithAfterCombatTurnsS', { bpDeviceName: escText(bp.deviceName), ctSeconds: ct.seconds }) : tx('SR2E.Card.Actor.sCasingIsOpenPlain', { bpDeviceName: escText(bp.deviceName) }))}</strong> ${tx('SR2E.Card.Actor.nowBypassTheCircuit', { tamperTrip })}</p>` : `<p><strong>${tx('SR2E.Card.Actor.theCasingHolds')}</strong>${snap.botch ? ` <strong>${tx('SR2E.Card.Actor.theAlarmGoesOff')}</strong>` : ''}${tamperTrip}</p>`;
      return { html, flags: {}, snap: { ...snap, bypass: next } };
    }
    const priorTamper = (fu.siteChange ?? null);
    if (site && o.opened && !bp.opened) {
      fu.siteChange = { site, change: { deviceId: bp.deviceId, bypassed: true }, label: tx('SR2E.Card.Actor.bypasses', { name: this.name, deviceName: bp.deviceName }) };
      next.opened = true;
    } else if (site && !o.opened && !bp.failApplied && !bp.opened) {
      fu.siteChange = { site, change: { ...(priorTamper?.change ?? {}), add: (priorTamper?.change?.add ?? 0) + o.tally, ...(o.minAlert || priorTamper?.change?.minAlert ? { minAlert: !priorTamper?.change?.minAlert || (o.minAlert && alertAtLeast(String(o.minAlert), String(priorTamper.change.minAlert))) ? String(o.minAlert ?? '') : String(priorTamper.change.minAlert) } : {}) }, label: tamperTrip ? tx('SR2E.Card.Actor.failsToBypassAndTrips', { name: this.name, deviceName: bp.deviceName }) : tx('SR2E.Card.Actor.failsToBypass', { name: this.name, deviceName: bp.deviceName }) };
      next.failApplied = true;
    }
    // v0.46.0: how long it takes, and a tamper alarm checking the work (rolled once; the old way, BOOK_V78.tamper 'opposed').
    const time = o.opened ? bypassTime(bp.kind ?? 'other', snap.successes) : null;
    let tamper = tamperTrip;
    if (o.opened && (bp.tamper ?? 0) > 0 && RULES.BOOK_V78.tamper.mode === 'opposed') {
      if (!bp.tamperRolled) {
        const t = RULES.SECURITY.tamper;
        const tn = tamperTn(bp.skillRating ?? 0);
        const rolls: any[] = [];
        const r = await successTest({ dice: bp.tamper!, targetNumber: tn, roll: foundryRoller(rolls) });
        next.tamperRolled = true;
        next.tampered = tamperTrips(r.successes, snap.successes);
        const gms = [...((game as any).users ?? [])].filter((u: any) => u.isGM).map((u: any) => u.id);
        await ChatMessage.create({ speaker: { alias: site?.name ?? tx('SR2E.Card.Actor.security') }, whisper: gms, blind: true, rolls,
          content: `<p><em>${tx('SR2E.Card.Actor.gmOnly')}</em></p>${describeResult(tx('SR2E.Card.Actor.sTamperAlarmVs', { bpDeviceName: bp.deviceName, bpTamper: bp.tamper, tn }), r)}<p>${next.tampered ? `<strong>${tx('SR2E.Card.Actor.theTamperAlarmTrips2')}</strong> ${tx('SR2E.Card.Actor.vsTheBypassS', { successes: r.successes, successes2: snap.successes })}` : tx('SR2E.Card.Actor.theTamperAlarmStaysQuiet')}</p>` });
        if (next.tampered && site) {
          const prior = (fu.siteChange ?? null);
          fu.siteChange = { site, change: { ...(prior?.change ?? {}), add: (prior?.change?.add ?? 0) + t.tally, ...(t.alert ? { minAlert: t.alert } : {}) }, label: tx('SR2E.Card.Actor.sTamperAlarmTripsAs', { deviceName: bp.deviceName, name: this.name }) };
        }
      }
      tamper = next.tampered ? ` <strong>${tx('SR2E.Card.Actor.theTamperAlarmTrips')}</strong>` : '';
    }
    const html = o.opened
      ? `<p><strong>${tx('SR2E.Card.Actor.isOpen', { bpDeviceName: escText(bp.deviceName) })}</strong>${time ? tCount(time.turns, 'SR2E.Card.Actor.afterCombatTurnsSOfWork', { timeSeconds: time.seconds }) : ''}.${tamper}</p>`
      : `<p><strong>${tx('SR2E.Card.Actor.theLockHolds')}</strong>${o.minAlert ? ` <strong>${tx('SR2E.Card.Actor.theAlarmGoesOff')}</strong>` : ''}</p>`;
    return { html, flags: {}, snap: { ...snap, bypass: next } };
  }

  // ---------------------------------------------------------------- Security leftovers (v0.49.0)

  /** Site: add guards (actor UUIDs) or take one off. */
  async setGuards(add: string[] = [], remove: string[] = []): Promise<string[]> {
    if (this.type !== 'site') return [];
    const list = [...new Set([...(this.sys.guards ?? []), ...add])].filter((u) => !remove.includes(u));
    await this.update({ 'system.guards': list });
    return list;
  }

  /**
   * Site: the guards look for intruders. Each intruder sneaks past all the standing guards at once
   * (Stealth vs their Perception, whispered); every guard who notices someone raises the tally and the alert.
   */
  async guardsWatch(intruderUuids: string[], opts: { modifiers?: TargetNumberModifier[]; observerModifiers?: TargetNumberModifier[] } = {}): Promise<{ noticed: number } | null> {
    if (this.type !== 'site') return null;
    const guards: any[] = [];
    for (const u of this.sys.guards ?? []) {
      const g: any = await fromUuid(u);
      if (g && !['unconscious', 'dying', 'dead'].includes(g.system?.derived?.status ?? 'ok')) guards.push(g);
    }
    if (!guards.length) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.hasNoGuardsStanding', { name: escHtml(this.name) })); return null; }
    // Each guard who notices anyone counts once (RULES.SECURITY.guards.tallyPerGuard).
    const spotters = new Set<string>();
    const who: string[] = [];
    for (const u of intruderUuids) {
      const intruder: any = await fromUuid(u);
      if (!intruder?.sneakPast || guards.some((gd) => gd.uuid === intruder.uuid)) continue;
      const res: Array<{ name: string; noticed: boolean }> = await intruder.sneakPast(guards.map((g) => g.uuid), { modifiers: opts.modifiers ?? [], observerModifiers: opts.observerModifiers ?? [], whisper: true, watched: true });
      res.forEach((x, i) => { if (x.noticed) spotters.add(guards[i]?.uuid ?? x.name); });
      if (res.some((x) => x.noticed)) who.push(intruder.name);
    }
    const noticed = spotters.size;
    const change = guardsNotice(noticed);
    if (change) await SR2Actor.changeSite(this, { add: change.add, ...(change.minAlert ? { minAlert: change.minAlert as any } : {}) }, tx('SR2E.Card.Actor.sGuardsSpot', { name: this.name, who: who.join(', ') }), this.uuid as string);
    return { noticed };
  }

  /**
   * Site: a device is forced: its door broken ('breach') or the device smashed or cut out ('force').
   * Its tamper alarm trips with no roll; a smashed device without one still goes dead on the board.
   */
  async forceDevice(deviceId: string, how: 'breach' | 'force', by = ''): Promise<boolean> {
    if (this.type !== 'site') return false;
    const d = this.device(deviceId);
    if (!d) return false;
    // Once only: a smashed device is off, a forced door is broken open (bypassed).
    if ((how === 'force' && !d.active) || (how === 'breach' && d.bypassed)) return false;
    const r = forcedDevice(Number(d.tamper ?? 0), how);
    const devices = [...(this.sys.devices ?? [])].map((x: any) => (x.id === deviceId ? (how === 'force' ? { ...x, active: false } : { ...x, bypassed: true }) : x));
    await this.update({ 'system.devices': devices });
    const what = how === 'breach' ? tx('SR2E.Card.Actor.sDoorIsForced', { name: d.name }) : tx('SR2E.Card.Actor.is3', { name: d.name, part: by ? tx('SR2E.Card.Actor.smashedBy', { by }) : tx('SR2E.Card.Actor.smashed') });
    if (r.add || r.minAlert) await SR2Actor.changeSite(this, { add: r.add, ...(r.minAlert ? { minAlert: r.minAlert as any } : {}) }, `${what}: ${r.note}`, this.uuid as string);
    else if (how === 'force') {
      const gms = [...((game as any).users ?? [])].filter((u: any) => u.isGM).map((u: any) => u.id);
      await ChatMessage.create({ speaker: { alias: this.name }, whisper: gms, content: `<p><em>${tx('SR2E.Card.Actor.gmOnly')}</em> · ${escText(what)}.</p>` });
    }
    return r.trips;
  }

  /** v0.49.0: a damaged wall that is a site device's door forces that device. */
  static async #wallForced(doc: any): Promise<void> {
    const sceneId = doc?.parent?.id;
    if (!sceneId || !RULES.SECURITY.tamper.onBreach) return;
    for (const site of allActors().filter((a: any) => a.type === 'site')) {
      for (const d of (site.system.devices ?? []) as any[]) {
        if (d.sceneId === sceneId && d.wallId === doc.id && d.active && !d.bypassed) await site.forceDevice(d.id, 'breach');
      }
    }
  }

  /** Site: put a security rigger in the network (control rig needed), or take them out (null). */
  async setRigger(rigger: any | null): Promise<boolean> {
    if (this.type !== 'site') return false;
    if (rigger && RULES.SECURITY.riggerNeedsVcr && !((rigger.system?.derived?.rigging?.vcr ?? 0) > 0)) {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.hasNoControlRig', { riggerName: escHtml(rigger.name) }));
      return false;
    }
    const prev: any = this.sys.riggerUuid ? fromUuidSync(this.sys.riggerUuid) : null;
    // v0.81.0 (D3-9): someone this client can't write is in the way: refuse before writing anything.
    const prevHere = prev && prev.uuid !== rigger?.uuid && prev.system?.rigging?.vehicleUuid === this.uuid;
    if (prevHere && notWritableNow(prev)) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.isInSSecuritySystemThey', { prevName: escHtml(prev.name), name: escHtml(this.name) })); return false; }
    const otherOf: any = rigger ? rigger.riggedVehicle?.() : null;
    if (otherOf && otherOf.uuid !== this.uuid && notWritableNow(otherOf) && ((otherOf.type === 'vehicle' && otherOf.system?.controllerUuid === rigger.uuid) || otherOf.type === 'site')) {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.stillControlsLetGoOfIt', { riggerName: escHtml(rigger.name), otherOfName: escHtml(otherOf.name) }));
      return false;
    }
    if (prevHere) {
      await prev.update({ 'system.rigging.vehicleUuid': '', 'system.rigging.jumpedIn': false });
    }
    if (rigger) {
      const other: any = otherOf;
      if (other?.type === 'vehicle' && other.system?.controllerUuid === rigger.uuid) await other.update({ 'system.controllerUuid': '', 'system.controlMode': 'autopilot' });
      if (other?.type === 'site' && other.uuid !== this.uuid) await other.update({ 'system.riggerUuid': '' });
    }
    await this.update({ 'system.riggerUuid': rigger?.uuid ?? '' });
    if (rigger) await rigger.update({ 'system.rigging.vehicleUuid': this.uuid, 'system.rigging.jumpedIn': true });
    SR2Actor.#rerender(this, rigger, prev);
    const text = rigger ? `<strong>${escText(rigger.name)}</strong> ${tx('SR2E.Card.Actor.jumpsInto')} <strong>${escText(this.name)}</strong>${tx('SR2E.Card.Actor.sSecuritySystem')}` : prev ? `<strong>${escText(prev.name)}</strong> ${tx('SR2E.Card.Actor.jumpsOutOf')} <strong>${escText(this.name)}</strong>${tx('SR2E.Card.Actor.sSecuritySystem')}` : '';
    if (text) await ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor: this }), content: `<p>${text}</p>`, whisper: [...((game as any).users ?? [])].filter((u: any) => u.isGM || rigger?.testUserPermission?.(u, 'OWNER')).map((u: any) => u.id) });
    return true;
  }

  /** GM: announce responses that are due (a Combat Turn reached, or the world time passed). */
  static async securityResponses(now: { round?: number | null; worldTime?: number; anyGm?: boolean; combatId?: string } = {}): Promise<void> {
    if (!(game as any).user?.isGM) return;
    // Hooks fire on every client: only the active GM answers them (the combat path passes anyGm).
    const active = (game as any).users?.activeGM;
    if (!now.anyGm && active && !isLeadGm()) return;
    const time = now.worldTime ?? sysNow();
    for (const site of allActors().filter((a: any) => a.type === 'site')) {
      const r = site.system.response;
      if (!r || r.arrived) continue;
      // v0.70.0: a Combat Turn deadline counts only in the combat that set it (old sites without the flag: any).
      const setIn = String(site.getFlag?.(SYSTEM_ID, 'responseCombat') ?? '');
      const byRound = r.round >= 0 && now.round != null && now.round >= r.round && (!setIn || !now.combatId || setIn === now.combatId);
      const byTime = r.worldTime >= 0 && time >= r.worldTime;
      if (!byRound && !byTime) continue;
      await site.update({ 'system.response.arrived': true });
      await ChatMessage.create({ speaker: { alias: site.name }, content: `<p><strong>${tx('SR2E.Card.Actor.theSecurityResponseArrivesAt', { siteName: escText(site.name) })}</strong>${r.force ? `: ${escText(r.force)}` : ''}.</p>`, whisper: [...((game as any).users ?? [])].filter((u: any) => u.isGM).map((u: any) => u.id) });
    }
  }

  /** Site: reset the tally, alert and response (and restore bypassed devices if asked). */
  async resetSite(restoreDevices = false): Promise<void> {
    const was: any[] = [...(this.sys.devices ?? [])];
    const devices = was.map((d: any) => ({ ...d, ...(restoreDevices ? { bypassed: false } : {}) }));
    // v0.81.0 (D3-10): the response's combat marker goes too.
    await this.update({ 'system.tally': 0, 'system.alert': 'none', 'system.response.round': -1, 'system.response.worldTime': -1, 'system.response.arrived': false, 'system.devices': devices, [`flags.${SYSTEM_ID}.responseCombat`]: '' });
    // v0.81.0 (D3-10): a restored device locks its door again, as applySiteChange does.
    if (restoreDevices && RULES.SECURITY.bypass.unlocksDoor) for (const d of was) if (d.bypassed && d.wallId) await SR2Actor.#setDoor(d, 'locked');
  }

  /** Refresh pools at the start of a Combat Turn. */
  async refreshPools(): Promise<void> {
    if (!this.sys.poolSpent) return;
    await this.update({ 'system.poolSpent.combat': 0, 'system.poolSpent.spell': 0, 'system.poolSpent.spellConc': 0, 'system.poolSpent.spellSpec': 0, 'system.poolSpent.hacking': 0, 'system.poolSpent.control': 0, 'system.poolSpent.task': 0, 'system.spellDefense': 0 });
  }
}

export class SR2Item extends Item {
  /** v0.49.0: setting an item's Heat stamps when it was set, so it cools from then (RULES.STREET.heat). */
  async _preUpdate(changed: any, options: any, user: any): Promise<boolean | void> {
    // Heat and complex forms are the GM's (and learnComplexForm's) to set, not a player's sheet edit.
    const u: any = typeof user === 'string' ? (game as any).users?.get?.(user) : user;
    if (u && !u.isGM && changed?.system) {
      for (const k of ['heat', 'heatAt', 'complexForm']) delete changed.system[k];
    }
    const heat = changed?.system?.heat;
    if (heat !== undefined && Number(heat) !== Number((this as any).system?.heat ?? 0) && changed.system.heatAt === undefined) {
      changed.system.heatAt = Number(heat) > 0 ? sysNow() : -1;
    }
    // v0.92.1 (RULES.SHEET_V921.carried): left behind, it can't be worn, drawn or switched on; putting it on brings it along.
    if (changed?.system) SR2Item.carriedRules((this as any).type, (this as any).system ?? {}, changed.system);
    // v0.92.1 (RULES.SHEET_V921.accessories): a weapon's new description is read for accessories.
    if ((this as any).type === 'weapon' && changed?.system?.description !== undefined && String(changed.system.description ?? '') !== String((this as any).system?.description ?? '')) {
      SR2Item.readDescriptionInto(changed, (this as any).system ?? {}, (this as any).flags?.sr2e?.fromDescription, { oldDescription: String((this as any).system?.description ?? '') });
    }
    // v0.73.0 (O28): a weapon on a vehicle must fit its firmpoints and hardpoints.
    const ms = changed?.system ?? {};
    if ((this as any).type === 'weapon' && (ms.mount !== undefined || ms.mountPoint !== undefined || ms.antiVehicle !== undefined || ms.guidance !== undefined || changed?.name !== undefined)) {
      const sys = { ...(this as any).system, ...ms };
      if (!this.#mountFits({ name: String(changed?.name ?? (this as any).name), system: sys })) return false;
    }
    return super._preUpdate?.(changed, options, user);
  }

  async _preCreate(data: any, options: any, user: any): Promise<boolean | void> {
    // v0.81.0 (D3-20): a complex form (no memory, never erased) is learnComplexForm's to make, not a player's drop or copy.
    // R2-DOC 5: a copy or move of a complex form the same user already owns keeps it (SR2Item.complexFormSourceOk).
    // (Heat stays: stripping it from a player's copy would launder hot goods.)
    const u: any = typeof user === 'string' ? (game as any).users?.get?.(user) : user;
    if (u && !u.isGM && data?.system?.complexForm && !options?.sr2eComplexForm && !SR2Item.complexFormSourceOk(data, options, u)) {
      (this as any).updateSource({ 'system.complexForm': false });
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.comesInAsAnOrdinaryProgram', { name: escHtml(String(data?.name ?? tx('SR2E.Notify.Actor.thatProgram'))) }));
    }
    const heat = Number(data?.system?.heat ?? 0);
    if (heat > 0 && !(Number(data?.system?.heatAt ?? -1) >= 0)) (this as any).updateSource({ 'system.heatAt': sysNow() });
    // v0.92.1: an item arriving left behind isn't worn or drawn; a weapon arriving is read for accessories (only defaults filled).
    if (data?.system && data.system.carried === false) {
      const sys: any = { ...((this as any).system?.toObject?.() ?? (this as any).system ?? {}) };
      const patch: any = {};
      SR2Item.carriedRules(String(data.type ?? ''), sys, Object.assign(patch, { carried: false }));
      const flat: Record<string, unknown> = {};
      for (const [k, v] of Object.entries(patch)) if (k !== 'carried') flat[`system.${k}`] = v;
      if (Object.keys(flat).length) (this as any).updateSource(foundry.utils.expandObject(flat));
    }
    // A copy of a weapon already read keeps its values (a field someone cleared by hand isn't filled again).
    if (data?.type === 'weapon' && String(data?.system?.description ?? '').trim() && !data?.flags?.sr2e?.fromDescription) {
      const ch: any = { system: { description: data.system.description } };
      const cur: any = (this as any).system?.toObject?.() ?? { ...(this as any).system };
      SR2Item.readDescriptionInto(ch, cur, data?.flags?.sr2e?.fromDescription, { creating: true });
      const flat: Record<string, unknown> = {};
      for (const [k, v] of Object.entries(ch.system ?? {})) if (k !== 'description') flat[`system.${k}`] = v;
      if (ch.flags?.sr2e?.fromDescription) flat['flags.sr2e.fromDescription'] = ch.flags.sr2e.fromDescription;
      if (Object.keys(flat).length) (this as any).updateSource(flat);
    }
    // v0.73.0 (O28): a weapon on a vehicle must fit its firmpoints and hardpoints.
    if (data?.type === 'weapon' && !this.#mountFits({ name: String(data.name ?? ''), system: { ...(this as any).system, ...(data.system ?? {}) } })) return false;
    return super._preCreate?.(data, options, user);
  }

  /**
   * v0.92.1 (RULES.SHEET_V921.carried): keeps an edit (`next`, the `system` part, changed in place) in line with Carried.
   * Untick Carried: armor comes off, a weapon is holstered, gear's worn and slotted parts switch off. Wear, draw or switch
   * on something left behind: it is carried again (the owner's rule: it can't be used until it is). Returns how many fields it changed.
   */
  static carriedRules(type: string, current: any, next: any): number {
    if (RULES.SHEET_V921.carried !== 'on' || !['weapon', 'armor', 'gear'].includes(type) || !next || typeof next !== 'object') return 0;
    let done = 0;
    const wasCarried = current?.carried !== false;
    const willCarry = next.carried === undefined ? wasCarried : next.carried !== false;
    const turnsOn = (k: 'worn' | 'ready'): boolean => next[k] === true && current?.[k] !== true;
    const partOn = (part: string, k: string): boolean => next[part]?.[k] === true && current?.[part]?.[k] !== true;
    if (!willCarry) {
      // Something put on or drawn in the same edit that leaves it behind: it comes along after all.
      const wants = (type === 'armor' && turnsOn('worn')) || (type === 'weapon' && turnsOn('ready'))
        || (type === 'gear' && (partOn('stealth', 'worn') || partOn('protection', 'worn') || partOn('optics', 'worn') || partOn('chip', 'slotted')));
      if (wants && next.carried === undefined) { next.carried = true; done++; return done; }
      if (type === 'armor' && (current?.worn || next.worn)) { next.worn = false; done++; }
      if (type === 'weapon' && (current?.ready !== false || next.ready)) { next.ready = false; done++; }
      if (type === 'weapon' && (current?.supportSetUp || next.supportSetUp)) { next.supportSetUp = false; done++; }
      if (type === 'gear') {
        for (const [part, k] of [['stealth', 'worn'], ['protection', 'worn'], ['optics', 'worn'], ['chip', 'slotted']] as const) {
          if (current?.[part]?.[k] || next[part]?.[k]) { next[part] = { ...(next[part] ?? {}), [k]: false }; done++; }
        }
      }
    }
    return done;
  }

  /**
   * v0.92.1 (RULES.SHEET_V921.accessories): reads a weapon's new description (`changed.system.description`) for accessories
   * (rules/accessories.ts) and adds to `changed`: the fields still at their default (never one this edit sets itself), note
   * tweaks for accessories without a field, and the record the sheet's "From the description" line and Undo use.
   */
  static readDescriptionInto(changed: any, current: any, record: any, o: { creating?: boolean; oldDescription?: string } = {}): void {
    if (RULES.SHEET_V921.accessories !== 'auto' || !changed?.system) return;
    const rec = record && typeof record === 'object' ? record : {};
    const dismissed: string[] = Array.isArray(rec.dismissed) ? rec.dismissed.map(String) : [];
    const noted: string[] = Array.isArray(rec.noted) ? rec.noted.map(String) : [];
    const merged = { ...(current ?? {}), ...(changed.system ?? {}) };
    // Review (B6): an edit reads only accessories it newly mentions, so a value cleared by hand stays cleared.
    const already = o.oldDescription ? readAccessories(o.oldDescription).map((h) => h.id) : [];
    const plan = accessoryPlan(changed.system.description, merged, { dismissed: [...dismissed, ...already], noted });
    if (!plan.filled.length && !plan.notes.length) return;
    const fields: Record<string, unknown> = { ...(rec.fields && typeof rec.fields === 'object' ? rec.fields : {}) };
    for (const h of plan.filled) {
      const key = String(h.field);
      // A value this same edit sets by hand wins.
      if (Object.prototype.hasOwnProperty.call(changed.system, key)) continue;
      changed.system[key] = h.value;
      fields[key] = { id: h.id, value: h.value, before: plan.before[`system.${key}`], text: h.text };
    }
    const newNotes = plan.notes.map((h) => ({ id: `acc${h.id}`, label: tx('SR2E.Text.Accessories.fromDescription', { name: tKey(ACCESSORY_NAME_KEYS[h.id] ?? '') }), target: 'note', key: '', value: 0, on: true }));
    if (newNotes.length) {
      const base = Array.isArray(changed.system.tweaks) ? changed.system.tweaks : normalizeTweaks(current?.tweaks ?? []);
      const have = new Set(base.map((t: any) => String(t?.id ?? '')));
      changed.system.tweaks = [...base, ...newNotes.filter((t) => !have.has(t.id))].slice(0, TWEAK_MAX);
    }
    const next = { fields, dismissed, noted: [...noted, ...plan.notes.map((h) => h.id)] };
    changed.flags = foundry.utils.mergeObject(changed.flags ?? {}, { sr2e: { fromDescription: next } }, { inplace: false });
  }

  /**
   * v0.81.0 (R2-DOC 5): whether a new item's complex form comes from one this user already owns: the source named by
   * the drop (option `sr2eComplexFormFrom`, applications/drops.ts) or by Foundry's duplicate/source bookkeeping must be
   * an existing complex form the user owns. A compendium, the sidebar or someone else's form is not such a source.
   * The uuid itself can be anything: only a real, owned complex form at it passes.
   */
  static complexFormSourceOk(data: any, options: any, user: any): boolean {
    const ids = [options?.sr2eComplexFormFrom, data?._stats?.duplicateSource, data?.flags?.core?.sourceId].filter((x) => typeof x === 'string' && x && !x.startsWith('Compendium.'));
    return ids.some((id: string) => {
      const src: any = (globalThis as any).fromUuidSync?.(id) ?? null;
      if (!src || src.documentName !== 'Item' || !src.system?.complexForm || src.pack) return false;
      return Boolean(src.testUserPermission ? src.testUserPermission(user, 'OWNER') : src.isOwner);
    });
  }

  /** v0.73.0 (O28): a weapon on a vehicle must fit its firmpoints and hardpoints (RULES.DRONES_V73.mounts). False = refuse. */
  #mountFits(next: { name: string; system: any }): boolean {
    const v: any = (this as any).parent;
    if (!v || v.type !== 'vehicle' || (this as any).type !== 'weapon') return true;
    const asMount = (n: string, s: any): MountWeapon => ({ name: n, mount: String(s?.mount ?? 'none'), mountPoint: String(s?.mountPoint ?? ''), antiVehicle: Boolean(s?.antiVehicle), guidance: Number(s?.guidance ?? 0) } as any);
    const others = [...v.items].filter((i: any) => i.type === 'weapon' && i.id !== (this as any).id).map((i: any) => asMount(String(i.name), i.system));
    const c = mountCheck({ body: Number(v.system.body ?? 0), firmpoints: Number(v.system.firmpoints ?? 0), hardpoints: Number(v.system.hardpoints ?? 0), weapons: others, adding: asMount(next.name, next.system) } as any);
    if (c.ok) return true;
    ui.notifications?.warn?.(`${escHtml(v.name)}: ${escHtml(c.note)}${c.refuse ? '' : tx('SR2E.Notify.Actor.mountedAnyway')}`);
    return !c.refuse;
  }
}

/** Initiative is Reaction + Nd6, rolled through the engine so bonus dice are honored. */
export class SR2Combatant extends Combatant {
  getInitiativeRoll(): any {
    const f = initiativeFormula(this.actor);
    return new Roll(`${f.dice}d6 + ${f.base}${f.minus ? ` - ${f.minus}` : ''}`);
  }
}

/**
 * Initiative passes: after everyone has acted, subtract 10 from every score; anyone still
 * above 0 acts again in a new pass. When nobody is left, a new Combat Turn begins and
 * initiative is re-rolled. (Run live since v0.59.0.)
 */
export class SR2Combat extends Combat {
  setupTurns(): any[] {
    const turns = super.setupTurns();
    const surprisedIds = this.surprisedNow();
    const active = turns.filter((c: any) => (c.initiative === null || c.initiative > 0)
      && SR2Combat.canTakeTurns(c, turns)
      && !surprisedIds.includes(c.id));
    this.turns = active;
    return active;
  }

  /** v0.59.0: whether a combatant takes turns at all (score aside): the same test for the turn list and for "anyone left this pass". */
  static canTakeTurns(c: any, all: any[]): boolean {
    return !(RULES.CONDITIONS.skipInCombat && incapacitated(c.actor?.system?.derived?.status))
      && !c.actor?.system?.derived?.destroyed
      && !SR2Combat.matrixIdle(c.actor)
      && !SR2Combat.drivenByCombatant(c, all);
  }

  /**
   * v0.46.0: IC, frames and agents that can't act this turn: derezzed, or a frame whose owner is
   * not jacked in (an agent works on its own).
   */
  static matrixIdle(actor: any): boolean {
    if (actor?.type !== 'ic') return false;
    if (actor.system?.derived?.crashed) return true;
    if (actor.system?.kind !== 'frame') return false;
    const owner: any = actor.system.ownerUuid ? fromUuidSync(actor.system.ownerUuid) : null;
    return !owner?.isJackedIn?.();
  }

  /**
   * v0.59.0: a vehicle driven by hand or by a jumped-in rigger who is in this combat acts on the driver's
   * turns (the driver's actions drive and fire it), so it takes no turns of its own.
   */
  static drivenByCombatant(c: any, all: any[]): boolean {
    const a: any = c?.actor;
    if (a?.type !== 'vehicle' || !['manual', 'jumped'].includes(String(a.system?.controlMode ?? ''))) return false;
    const ctl = String(a.system?.controllerUuid ?? '');
    if (!ctl) return false;
    return all.some((o: any) => o !== c && o.actor && (o.actor.uuid === ctl || (!o.actor.isToken && `Actor.${o.actor.id}` === ctl)));
  }

  /** v0.46.0: party IC share their best member's initiative (RULES.MATRIX.party). */
  async alignParties(): Promise<number> {
    if ((game as any).user && !(game as any).user.isGM) return 0;
    const entries = [...(this.combatants as any)].filter((c: any) => c.actor?.type === 'ic' && String(c.actor.system?.party ?? '').trim())
      .map((c: any) => ({ id: c.id as string, party: `${c.actor.system.hostUuid ?? ''}|${String(c.actor.system.party).trim()}`, initiative: c.initiative ?? null }));
    const ups = partyInitiativeUpdates(entries);
    if (!ups.length) return 0;
    // Keep the acting combatant acting after the order changes.
    const current: string | null = (this as any).started ? ((this as any).combatant?.id ?? null) : null;
    await this.updateEmbeddedDocuments('Combatant', ups);
    if (current) {
      const i = (this.turns ?? []).findIndex((t: any) => t.id === current);
      if (i >= 0 && i !== (this as any).turn) await this.update({ turn: i });
    }
    return ups.length;
  }

  async rollInitiative(ids: any, options: any = {}): Promise<any> {
    const r = await (super.rollInitiative as any)(ids, options);
    try { await this.alignParties(); } catch (err) { console.warn('sr2e | party initiative', err); }
    return r;
  }

  /** Initiative order with SR2 tie-breaks (RULES.INITIATIVE_TIES): Reaction, then Quickness. */
  _sortCombatants(a: any, b: any): number {
    // v0.80.0 (URR_V80.cbtTies, URR): Reaction, then natural Reaction under the Revamp.
    const ties = (c: any) => U80C.cbtTieKeys().map((k) => U80C.cbtTieValue(k, c.actor?.system));
    const r = compareInitiative({ initiative: a.initiative, ties: ties(a) }, { initiative: b.initiative, ties: ties(b) });
    return r || String(a.name ?? '').localeCompare(String(b.name ?? '')) || String(a.id).localeCompare(String(b.id));
  }

  /** v0.79.0 (RULES.DOCS_V79.rangedSurprise 'order', SRII p. 86): the target actors this attacker may not act against in the surprise turn. */
  surpriseBlocked(attacker: any, targets: any[]): any[] {
    const s = this.getFlag(SYSTEM_ID, 'surprise') as { round: number; successes?: Record<string, number>; order?: boolean } | undefined;
    if (!s?.order || !s.successes) return [];
    const cid = (a: any): string | null => ([...(this.combatants as any)].find((c: any) => c.actor?.uuid === a?.uuid)?.id as string | undefined) ?? null;
    const ids = surpriseBlockedTargets({
      active: s.round === Number((this as any).round ?? 0) && this.pass === 0, successes: s.successes, attackerId: cid(attacker),
      targetIds: targets.map(cid).filter((x): x is string => Boolean(x)),
    });
    // (Token dispositions are too unreliable to tell sides apart (a world's default may be hostile for everyone), so
    // any target with more successes is blocked, allies included; attacking an ally in the surprise turn is rare.)
    return targets.filter((t) => ids.includes(cid(t) ?? ''));
  }

  /** Combatants surprised in the current pass (they lose the first RULES.SURPRISE.losesPasses passes). */
  surprisedNow(): string[] {
    const s = this.getFlag(SYSTEM_ID, 'surprise') as { round: number; ids: string[] } | undefined;
    if (!s || s.round !== (this as any).round || this.pass >= RULES.SURPRISE.losesPasses) return [];
    return s.ids;
  }

  /**
   * Surprise test (GM): every combatant rolls RULES.SURPRISE.attribute vs its TN; anyone with fewer
   * successes than the best on the other side (token disposition) is surprised this Combat Turn.
   */
  async rollSurprise(): Promise<string[]> {
    const sp = RULES.SURPRISE;
    const entries: Array<{ id: string; side: string; successes: number; name: string }> = [];
    const rows: string[] = [];
    for (const c of this.combatants as any) {
      const sys = c.actor?.system;
      // v0.78.0 (RULES.BOOK_V78.combatSense 'pool', Core Rules): Combat Sense lets the Combat Pool help on the surprise test.
      const senseLevel = Number(c.actor?.adeptSpecial?.('combatSense') ?? 0);
      const sense = RULES.BOOK_V78.combatSense === 'pool' ? (senseLevel > 0 ? Math.max(0, Number(sys?.derived?.combatPoolLeft ?? 0)) : 0) : senseLevel * RULES.ADEPT.combatSense.dicePerLevel;
      const dice = (sp.attribute === 'reaction' ? (sys?.derived?.reaction ?? 0) : (sys?.attributes?.[sp.attribute]?.total ?? 0)) + sense;
      const rolls: any[] = [];
      const r = await successTest({ dice, targetNumber: sp.tn, roll: foundryRoller(rolls) });
      const side = String(c.token?.disposition ?? c.actor?.prototypeToken?.disposition ?? 0);
      entries.push({ id: c.id, side, successes: r.successes, name: c.name });
      rows.push(`<li>${tCount(r.successes, 'SR2E.Card.Actor.successesDice', { name: escText(c.name), dice: escText(dice) })}</li>`);
    }
    // v0.79.0 (RULES.DOCS_V79.rangedSurprise 'order', SRII p. 86): the surprise turn: everyone acts once, most successes first,
    // and nobody may act against an opponent who rolled more successes; nobody loses a pass. Initiative is rolled as normal next turn.
    if (surpriseByOrder()) {
      const successes = Object.fromEntries(entries.map((e) => [e.id, e.successes]));
      await this.setFlag(SYSTEM_ID, 'surprise', { round: (this as any).round ?? 0, ids: [], successes, order: true });
      await this.updateEmbeddedDocuments('Combatant', entries.map((e) => ({ _id: e.id, initiative: surpriseInitiative(e.successes) })));
      await ChatMessage.create({
        speaker: { alias: tx('SR2E.Card.Actor.surprise') },
        content: `<div class="sr2e-roll"><h3>${tx('SR2E.Card.Actor.surpriseTestVs', { spAttribute: sp.attribute, spTn: sp.tn })}</h3><ul>${rows.join('')}</ul></div><p><strong>${tx('SR2E.Card.Actor.surpriseTurn')}</strong> ${tx('SR2E.Card.Actor.everyoneActsOnceMostSuccessesFirst')}</p>`,
      });
      this.setupTurns();
      return [];
    }
    const ids = surprised(entries);
    await this.setFlag(SYSTEM_ID, 'surprise', { round: (this as any).round ?? 0, ids });
    const names = entries.filter((e) => ids.includes(e.id)).map((e) => e.name);
    await ChatMessage.create({
      speaker: { alias: tx('SR2E.Card.Actor.surprise') },
      content: `<div class="sr2e-roll"><h3>${tx('SR2E.Card.Actor.surpriseTestVs', { spAttribute: sp.attribute, spTn: sp.tn })}</h3><ul>${rows.join('')}</ul></div><p>${names.length ? `<strong>${tx('SR2E.Card.Actor.surprised')}</strong> ${tCount(sp.losesPasses, 'SR2E.Card.Actor.loseTheFirst', { names: escText(names.join(', ')), part: sp.losesPasses === 1 ? tx('SR2E.Card.Actor.initiativePass') : tx('SR2E.Card.Actor.passes', { spLosesPasses: sp.losesPasses }) })}` : tx('SR2E.Card.Actor.nobodyIsSurprised')}</p>`,
    });
    this.setupTurns();
    return ids;
  }

  /** Dying characters not yet stabilised take another Physical box every Body Combat Turns. */
  async #dyingTicks(): Promise<void> {
    // v0.70.0: dying runs on world time instead (SR2Actor.#dyingWorldTick from timedEffects), in and out of combat.
    if (RULES.FIXES_V70.dyingOutOfCombat) return;
    const round = Number((this as any).round ?? 0);
    for (const c of this.combatants as any) {
      const a: any = c.actor;
      const sys = a?.system;
      if (sys?.derived?.status !== 'dying' || sys.care?.stabilised || !canWriteNow(a)) continue;
      const since = Number(sys.care?.dyingSince ?? -1);
      if (since < 0) continue;
      if (dyingTick(round - since, sys.attributes?.body?.total ?? 1)) {
        await a.update({ 'system.monitor.physical': sys.monitor.physical + 1 });
        await ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor: a }), content: `<p>${tx('SR2E.Card.Actor.isDyingAndTakesAnotherPhysical', { name: escText(a.name), monitorPhysical: escText(sys.monitor.physical) })}</p>` });
      }
    }
  }

  get pass(): number {
    return (this.getFlag(SYSTEM_ID, 'pass') as number | undefined) ?? 0;
  }

  /** v0.59.0: the initiative of the pass about to end, kept for Previous Round (set by nextTurn, read by nextRound). */
  #endingPass: { round: number; pass: number; init: Record<string, number | null> } | null = null;

  /** v0.59.0: a player's client can't end a pass (other combatants' initiative, the pass flag): the GM's client does. */
  async #relayEnd(): Promise<this> {
    const r = await requestGm('nextTurn', { combatId: this.id, state: combatState(this) }, 30000);
    if (!r.ok) ui.notifications?.warn?.(escHtml(r.note ?? tx('SR2E.Notify.Actor.theGmCouldNotEndThe')));
    return this;
  }

  /** v0.59.0: the next turn in this pass (skipping the defeated when Foundry's setting says so), or null at the pass's end. */
  nextTurnIndex(): number | null {
    const turn = this.turn ?? -1;
    const skip = Boolean((this as any).settings?.skipDefeated);
    for (let i = turn + 1; i < this.turns.length; i++) if (!skip || !(this.turns[i] as any)?.isDefeated) return i;
    return null;
  }

  async nextTurn(): Promise<any> {
    if (Number((this as any).round ?? 0) === 0) return super.nextTurn();
    // Mid-pass: Foundry's own (it finds the same next turn); at the pass's end, SR2's.
    if (this.turn !== null && this.nextTurnIndex() !== null) return super.nextTurn();
    // The last turn of a pass: every score drops by 10 (a player's client asks the GM to).
    if (!(game as any).user?.isGM) return this.#relayEnd();

    const before: Record<string, number | null> = {};
    for (const c of this.combatants as any) before[c.id] = c.initiative ?? null;
    const updates = this.combatants.map((c: any) => ({
      _id: c.id,
      // v0.81.0 (D3-21): not rolled yet stays not rolled (the GM can still roll it this Combat Turn), as the undo does.
      initiative: c.initiative === null || c.initiative === undefined ? null : c.initiative - RULES.INITIATIVE_PASS_DECREMENT,
    }));
    await this.updateEmbeddedDocuments('Combatant', updates);
    const everyone = [...(this.combatants as any)];
    const anyLeft = everyone.some((c: any) => !c.isDefeated && (c.initiative ?? 0) > 0 && SR2Combat.canTakeTurns(c, everyone));

    if (anyLeft) {
      await this.update({ turn: 0, [`flags.${SYSTEM_ID}.pass`]: this.pass + 1, [`flags.${SYSTEM_ID}.passBefore`]: { round: Number((this as any).round ?? 0), pass: this.pass, init: before } }, { direction: 1 } as any);
      return this;
    }
    this.#endingPass = { round: Number((this as any).round ?? 0), pass: this.pass, init: before };
    return this.nextRound();
  }

  /**
   * v0.59.0: a new Combat Turn, from the end of the last pass or the tracker's Next Round button alike:
   * the clock moves one Combat Turn, initiative is re-rolled, pools refresh, the pass starts at 0 and the
   * Combat Turn timers (dying, security, traces, timed effects, regeneration) run once on the active GM.
   */
  async nextRound(): Promise<any> {
    if (!(game as any).user?.isGM) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.onlyTheGmCanStartA')); return this; }
    const started = Number((this as any).round ?? 0) > 0;
    const hist = this.#endingPass ?? { round: Number((this as any).round ?? 0), pass: this.pass, init: Object.fromEntries([...(this.combatants as any)].map((c: any) => [c.id, c.initiative ?? null])) };
    this.#endingPass = null;
    await super.nextRound();
    if (!started) return this;
    await this.setFlag(SYSTEM_ID, 'lastPass', hist);
    // Foundry's rollAll() only rolls combatants whose initiative is null, so clear the
    // spent (<= 0) scores first or nobody would be re-rolled and the turn order stays empty.
    await this.updateEmbeddedDocuments(
      'Combatant',
      this.combatants.map((c: any) => ({ _id: c.id, initiative: null })),
    );
    await this.rollAll();
    await this.alignParties();
    for (const c of this.combatants) await (c.actor as any)?.refreshPools?.();
    await this.update({ turn: 0, [`flags.${SYSTEM_ID}.pass`]: 0 });
    const round = Number((this as any).round ?? 0);
    if (isRelayGm() || !activeGm()) await SR2Combat.#awaitTicks(this.runRoundTicks(round));
    else {
      const r = await requestGm('roundTicks', { combatId: this.id, round });
      // v0.81.1 round 3 (FIX3-BRIEF 5): a request that timed out may still be running on the active GM: never run it here too.
      if (!r.ok && !r.timedOut) await this.runRoundTicks(round);
    }
    return this;
  }

  /**
   * v0.59.0: the Combat Turn timers, once per Combat Turn (a flag remembers the last one) and queued
   * behind any world-time timers running on this client, so the two paths never interleave.
   */
  /**
   * v0.81.1 round 2: wait for queued timers, unless a locked task is running on this client (a relay handler that
   * turned the round): the timers queue behind it then, as awaiting them inside it would deadlock.
   */
  static async #awaitTicks(p: Promise<void>): Promise<void> {
    if (gmLockHeld()) { void p; return; }
    await p;
  }

  async runRoundTicks(round: number): Promise<void> {
    await serialTicks(async () => {
      if (Number(this.getFlag(SYSTEM_ID, 'tickedRound') ?? -1) >= round) return;
      await this.setFlag(SYSTEM_ID, 'tickedRound', round);
      await this.#dyingTicks();
      await SR2Actor.securityResponses({ round, anyGm: true, combatId: String(this.id ?? '') });
      await SR2Actor.matrixTraces({ round, anyGm: true, combatId: String(this.id ?? '') });
      await SR2Actor.timedEffects({ round, anyGm: true, combatId: String(this.id ?? '') });
      // Regenerating critters heal at the end of each Combat Turn (v0.39.0).
      for (const c of this.combatants) await (c.actor as any)?.regenerateTick?.();
    });
  }

  /**
   * v0.59.0: back one turn. At the first turn of a later pass this goes back to the last turn of the
   * pass before (every score +10); at the first turn of pass 0, to the last pass of the Combat Turn
   * before. Nothing the timers did is undone (use the GM panel's undo for that).
   */
  async previousTurn(): Promise<any> {
    if (!(game as any).user?.isGM) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.onlyTheGmCanGoBack')); return this; }
    if (Number((this as any).round ?? 0) === 0) return this;
    if ((this.turn ?? 0) > 0 && this.turns.length) return super.previousTurn();
    if (this.pass > 0) {
      // The scores as they were in the pass before (kept when it ended), else everyone's +10.
      const kept = this.getFlag(SYSTEM_ID, 'passBefore') as { round: number; pass: number; init: Record<string, number | null> } | undefined;
      const exact = kept && kept.round === Number((this as any).round ?? 0) && kept.pass === this.pass - 1 ? kept.init : null;
      await this.updateEmbeddedDocuments('Combatant', this.combatants.map((c: any) => ({ _id: c.id, initiative: exact && c.id in exact ? exact[c.id] : c.initiative === null || c.initiative === undefined ? null : c.initiative + RULES.INITIATIVE_PASS_DECREMENT })));
      await this.update({ [`flags.${SYSTEM_ID}.pass`]: this.pass - 1 });
      this.setupTurns();
      await this.update({ turn: Math.max(0, this.turns.length - 1) }, { direction: -1 } as any);
      return this;
    }
    return this.previousRound();
  }

  /**
   * v0.59.0: back to the last pass of the Combat Turn before, with its initiative as it was (kept when
   * that Combat Turn ended). Only one Combat Turn back: older initiative was re-rolled and is gone.
   */
  async previousRound(): Promise<any> {
    if (!(game as any).user?.isGM) { ui.notifications?.warn?.(tx('SR2E.Notify.Actor.onlyTheGmCanGoBack2')); return this; }
    const round = Number((this as any).round ?? 0);
    if (round <= 1) return super.previousRound();
    const h = this.getFlag(SYSTEM_ID, 'lastPass') as { round: number; pass: number; init: Record<string, number | null> } | undefined;
    if (!h || h.round !== round - 1) {
      ui.notifications?.warn?.(tx('SR2E.Notify.Actor.previousRoundGoesBackOnlyOne'));
      return this;
    }
    const ups = Object.entries(h.init).filter(([id]) => [...(this.combatants as any)].some((c: any) => c.id === id)).map(([id, v]) => ({ _id: id, initiative: v }));
    if (ups.length) await this.updateEmbeddedDocuments('Combatant', ups);
    const back = -(Number((globalThis as any).CONFIG?.time?.roundTime ?? 0) || 0);
    await this.update({ round: h.round, [`flags.${SYSTEM_ID}.pass`]: h.pass }, { direction: -1, ...(back ? { worldTime: { delta: back } } : {}) } as any);
    this.setupTurns();
    await this.update({ turn: Math.max(0, this.turns.length - 1) }, { direction: -1 } as any);
    return this;
  }
}

/**
 * v0.59.0: timers run one after another on this client: the world-time hook and a new Combat Turn can
 * both start them, and two runs interleaving could both see a response "not arrived yet" and post twice.
 */
let tickChain: Promise<void> = Promise.resolve();
export function serialTicks(fn: () => Promise<void>): Promise<void> {
  // v0.81.1 round 2 (FIX2-BRIEF A2): the timers act with the GM's rights, so they run under the GM lock (never inside
  // a player's re-run). Don't await this from inside a locked task (a relay handler): see `#awaitTicks`.
  const run = tickChain.then(() => withGmLock(fn)).catch((err) => { console.warn('sr2e | timers', err); });
  tickChain = run;
  return run;
}

/** v0.81.1 round 2 (A7): the spell-defense spend running per protector on this (the GM's) client. */
const spellDefenseSpends = new Map<string, Promise<void>>();

/** v0.59.0: what the active GM's client does for players and other GMs (applications/socket.ts). */
export function registerCombatRelay(): void {
  // One end-of-pass at a time per combat (a double-clicked End Turn must not end it twice).
  const ending = new Set<string>();
  // v0.91.4: a player's vehicle purchase or gift (vehicleShopAsGm checks the user, key, price and money again).
  onRelay('vehicleShop', async (d, user) => {
    const actor: any = typeof d['actorUuid'] === 'string' ? fromUuidSync(d['actorUuid']) : null;
    if (!(actor instanceof SR2Actor) || (actor as any).inCompendium) return { ok: false, note: tx('SR2E.Notify.VehicleShop.noActor') };
    const action = d['action'] === 'free' ? 'free' : d['action'] === 'buy' ? 'buy' : '';
    if (!action) return { ok: false };
    return actor.vehicleShopAsGm(action, d['key'], d['price'], d['hours'], user);
  });
  onRelay('nextTurn', async (d, user) => {
    const c: any = (game as any).combats?.get?.(String(d.combatId ?? ''));
    if (!c?.started) return { ok: false, note: tx('SR2E.Text.Actor.thatCombatIsNotRunning') };
    // GMs end turns themselves; a request claiming to be from one is not believed.
    if (user?.isGM) return { ok: false, note: tx('SR2E.Text.Actor.refused') };
    if (ending.has(c.id)) return { ok: false, note: tx('SR2E.Text.Actor.theTurnIsAlreadyBeingEnded') };
    if (!d.state || !sameCombatState(d.state, combatState(c))) return { ok: false, note: tx('SR2E.Text.Actor.theTurnHasAlreadyMovedOn') };
    if (!mayEndTurn(user, c.combatant)) return { ok: false, note: tx('SR2E.Text.Actor.onlyTheActingCharacterSOwner') };
    ending.add(c.id);
    try { await c.nextTurn(); } finally { ending.delete(c.id); }
    return { ok: true };
  });
  // v0.79.0: spend a protector's spell defense after a player's resist test (the player may not own the protector).
  onRelay('spendSpellDefense', async (d, user) => {
    const protector: any = await fromUuid(String(d.protectorUuid ?? ''));
    const target: any = await fromUuid(String(d.targetUuid ?? ''));
    if (!protector || !target) return { ok: false, note: tx('SR2E.Text.Actor.thatCharacterIsGone') };
    // v0.81.0 (SEC1-7): `user` is the socket's real sender (applications/socket.ts); no GM bypass.
    if (!target.testUserPermission?.(user, 'OWNER')) return { ok: false, note: tx('SR2E.Text.Actor.onlyTheProtectedCharacterSOwner') };
    // v0.81.1 (D2-1, D3-2, SEC1-12): someone else's protector covers only a character it is covering: named by its
    // holder (spellDefenseCovers), or on the same side on the same scene (in a fight or not). An enemy never does.
    const why = SR2Actor.spellDefenseCoverProblem(protector, target, user);
    if (why) return { ok: false, note: why };
    // v0.81.1 round 2 (V-DOC 14, FIX2-BRIEF A7): one spend at a time per protector on the GM's client, the value read
    // again after the one before: the second of two quick spends sees what is left (0). And a write that didn't land
    // (a cancelled update) is a refusal, so the resister never counts dice that weren't taken.
    const key = String(protector.uuid ?? '');
    const prev = spellDefenseSpends.get(key) ?? Promise.resolve();
    const run = prev.then(async () => {
      const held = Number(protector.system?.spellDefense ?? 0);
      const amount = Math.min(held, Math.max(0, Math.floor(Number(d.amount) || 0)));
      // v0.81.1: nothing spent is a refusal (the resister counts only dice actually spent).
      if (amount <= 0) return { ok: false, note: tx('SR2E.Text.Actor.nothingLeftToSpend') };
      // Inside a re-run (requestGm ran this inline, judged as the player above), the spend itself is the relay's, made
      // with the GM's rights, as for a request from the player's own client: the dice really leave the protector.
      // Round 3 (V2 #14): the write itself is marked (`sr2eRelay`), which the acting-author guard lets through, instead
      // of clearing the acting author for everything that runs meanwhile.
      await protector.update({ 'system.spellDefense': held - amount, 'system.poolSpent.spell': Number(protector.system.poolSpent?.spell ?? 0) + amount }, { sr2eRelay: true });
      if (Number(protector.system?.spellDefense ?? 0) !== held - amount) return { ok: false, note: tx('SR2E.Text.Actor.sSpellDefenseCouldnTBe', { name: protector.name }) };
      return { ok: true };
    });
    const settled = run.catch(() => undefined).then(() => undefined);
    spellDefenseSpends.set(key, settled);
    void settled.then(() => { if (spellDefenseSpends.get(key) === settled) spellDefenseSpends.delete(key); });
    return run;
  });
  onRelay('roundTicks', async (d, user) => {
    if (!user?.isGM) return { ok: false, note: tx('SR2E.Text.Actor.onlyAGmCanAskForThat') };
    const c: any = (game as any).combats?.get?.(String(d.combatId ?? ''));
    if (!c?.started) return { ok: false, note: tx('SR2E.Text.Actor.thatCombatIsOver') };
    // The combat's own round, never the request's (a forged round could run every timer at once).
    if (Number(d.round) !== Number(c.round ?? 0)) return { ok: false, note: tx('SR2E.Text.Actor.thatCombatTurnHasPassed') };
    // v0.81.1 round 2: queued, not awaited (this handler runs under the GM lock; the timers take it after).
    void c.runRoundTicks(Number(c.round ?? 0));
    return { ok: true };
  });
}

/**
 * v0.58.0: Essence holes (RULES.GEAR_V58.essenceHoles): cyberware leaving the body (deleted, or switched
 * off) leaves its Essence as a hole; ware going in fills it first. Runs on the client that made the change;
 * an undo's own changes are left alone (the undo log puts the hole back itself).
 */
export function registerEssenceHoleHooks(): void {
  // v0.81.1: the acting-author guard rides on this register too (sr2e-system.ts calls it once, at init).
  registerActingAuthorHooks();
  const eligible = (item: any) => item?.type === 'cyberware' && item.parent && ['character', 'npc'].includes(item.parent.type) && !item.parent.pack && !item.pack;
  const skip = (o: any, userId: string) => !madeHere(o, userId) || Boolean(o?.sr2eUndoing || o?.isUndo || o?.sr2eNoHole) || !RULES.GEAR_V58.essenceHoles.enabled;
  const r2 = (n: number) => Math.round(n * 100) / 100;
  // A new vehicle skill (Car, Bike, aircraft…) links to Reaction unless an attribute was given. (Not an Essence hook:
  // it rides here because this is the item-hook register sr2e-system.ts calls.)
  Hooks.on('preCreateItem', (item: any, data: any) => {
    if (item?.type !== 'skill' || data?.system?.attribute !== undefined) return;
    if (vehicleSkillAttribute(String(data?.name ?? item.name ?? ''))) item.updateSource({ 'system.attribute': 'reaction' });
  });
  // Only ware going in or coming out counts (the Installed box, creating, deleting): editing its Essence cost,
  // grade or housing is a correction, not surgery.
  Hooks.on('preUpdateItem', (item: any, change: any, options: any) => {
    if (!eligible(item) || change?.system?.installed === undefined) return;
    options.sr2eEss = { ...(options.sr2eEss ?? {}), [item.id]: { ess: SR2Actor.essenceOf(item), housed: SR2Actor.housedEssence(item) } };
  });
  Hooks.on('updateItem', (item: any, _c: any, options: any, userId: string) => {
    if (!eligible(item) || skip(options, userId) || options?.sr2eEss?.[item.id] === undefined) return;
    const b = options.sr2eEss[item.id];
    const after = SR2Actor.essenceOf(item);
    const actor = item.parent;
    // A cyberlimb going back in: the ware housed in it stops costing Essence first (its hole), then the limb fills it.
    const housedNow = item.system?.kind === 'cyberlimb' ? SR2Actor.housedEssence(item) : 0;
    if (item.system?.kind === 'cyberlimb' && item.system.installed && housedNow > 0) void actor.openEssenceHole(housedNow, tx('SR2E.Card.Actor.theWareHousedIn', { name: item.name }));
    if (after < b.ess) void actor.openEssenceHole(r2(b.ess - after), item.name);
    else if (after > b.ess) void actor.fillEssenceHole(r2(after - b.ess));
    // A cyberlimb coming out: the ware housed in it now costs Essence (filling the limb's hole).
    if (item.system?.kind === 'cyberlimb' && !item.system.installed && b.housed > 0) void actor.fillEssenceHole(b.housed);
  });
  Hooks.on('createItem', (item: any, options: any, userId: string) => {
    if (!eligible(item) || skip(options, userId)) return;
    const e = SR2Actor.essenceOf(item);
    if (e > 0) void item.parent.fillEssenceHole(e);
  });
  Hooks.on('preDeleteItem', (item: any, options: any) => {
    if (eligible(item) && item.system?.kind === 'cyberlimb' && item.system?.installed) options.sr2eHoused = { ...(options.sr2eHoused ?? {}), [item.id]: SR2Actor.housedEssence(item) };
  });
  Hooks.on('deleteItem', (item: any, options: any, userId: string) => {
    if (!eligible(item) || skip(options, userId)) return;
    const e = SR2Actor.essenceOf(item, item.parent);
    if (e > 0) void item.parent.openEssenceHole(e, item.name);
    const housed = Number(options?.sr2eHoused?.[item.id] ?? 0);
    if (housed > 0) void item.parent.fillEssenceHole(housed);
  });
}
